function Get-AdfaForestSummary {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([hashtable]$AdParams = @{})
    $f = Get-ADForest @AdParams
    [pscustomobject]@{
        ForestName         = $f.Name
        RootDomain         = $f.RootDomain
        ForestMode         = [string]$f.ForestMode
        Domains            = ($f.Domains -join '; ')
        Sites              = ($f.Sites -join '; ')
        GlobalCatalogs     = (@($f.GlobalCatalogs).Count)
        SchemaMaster       = $f.SchemaMaster
        DomainNamingMaster = $f.DomainNamingMaster
        UPNSuffixes        = ($f.UPNSuffixes -join '; ')
    }
}

function Get-AdfaDomainSummary {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$DomainName, [hashtable]$AdParams = @{})
    $p = @{} + $AdParams; $p.Identity = $DomainName
    $d = Get-ADDomain @p
    [pscustomobject]@{
        Scope                = $DomainName
        DomainName           = $d.DNSRoot
        NetBIOSName          = $d.NetBIOSName
        DomainMode           = [string]$d.DomainMode
        PDCEmulator          = $d.PDCEmulator
        RIDMaster            = $d.RIDMaster
        InfrastructureMaster = $d.InfrastructureMaster
        DomainSID            = [string]$d.DomainSID
    }
}

function Get-AdfaFsmoRole {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([hashtable]$AdParams = @{}, [Parameter(Mandatory)][string]$DomainName)
    $f = Get-ADForest @AdParams
    $dp = @{} + $AdParams; $dp.Identity = $DomainName
    $d = Get-ADDomain @dp
    [pscustomobject]@{
        Scope                = $DomainName
        SchemaMaster         = $f.SchemaMaster
        DomainNamingMaster   = $f.DomainNamingMaster
        PDCEmulator          = $d.PDCEmulator
        RIDMaster            = $d.RIDMaster
        InfrastructureMaster = $d.InfrastructureMaster
    }
}

function Get-AdfaDomainControllerInventory {
    <#
    .SYNOPSIS
        DC inventory. Get-ADDomainController has no -Properties, so enrich via Get-ADComputer.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName, [hashtable]$AdParams = @{})
    $p = @{} + $AdParams; $p.Server = $DomainName
    $dcs = Get-ADDomainController -Filter * @p
    $inv = foreach ($dc in $dcs) {
        $comp = $null
        $enrichError = ''
        try {
            $id = if ($dc.ComputerObjectDN) { $dc.ComputerObjectDN } else { $dc.HostName }
            # $p, NOT $AdParams: $p already carries -Server for THIS domain. Before v1.15.0 this
            # copied $AdParams instead, so Get-ADComputer had no -Server and asked whatever DC
            # the tool was running against - while $id is a DN in the domain being enumerated.
            # On a multi-domain forest that is a cross-naming-context lookup, the root DC answers
            # with an LDAP referral rather than the object, Get-ADComputer does not chase
            # referrals, and EVERY child-domain DC lost its OperatingSystem. The Exchange SE
            # verdict then called those DCs "unverified, not compatible" - so a forest-wide
            # readiness answer was wrong for every domain but the one the tool happened to run
            # in. Found on a live four-domain forest, 2026-09-26; single-domain runs never showed
            # it, because there the default server and the target domain are the same.
            $cp = @{} + $p
            $cp.Identity = $id
            $cp.Properties = @('OperatingSystem', 'OperatingSystemVersion', 'Enabled', 'whenCreated')
            $comp = Get-ADComputer @cp
        }
        catch {
            $enrichError = [string]$_.Exception.Message
            Write-Warning ("DC enrichment failed for {0}: {1}" -f $dc.HostName, $enrichError)
        }

        [pscustomobject]@{
            Scope                  = $DomainName
            HostName               = $dc.HostName
            Name                   = $dc.Name
            Site                   = $dc.Site
            IPv4Address            = $dc.IPv4Address
            IsGlobalCatalog        = $dc.IsGlobalCatalog
            IsReadOnly             = $dc.IsReadOnly
            OperatingSystem        = $(if ($comp) { $comp.OperatingSystem } else { $script:Status.NotAssessed })
            OperatingSystemVersion = $(if ($comp) { $comp.OperatingSystemVersion } else { $script:Status.NotAssessed })
            Enabled                = $(if ($comp) { $comp.Enabled } else { $script:Status.NotAssessed })
            # Why the three fields above are unreadable, carried into the row rather than left in
            # the warning stream. A reader of Assessment.html previously saw 'Not Assessed' with
            # no cause anywhere in the report - the same defect H10 fixed for dcdiag, missed here.
            EnrichmentError        = $enrichError
        }
    }
    return @($inv)
}

# ===========================================================================
# region Replication
# ===========================================================================

function Get-AdfaReplicationHealth {
    <#
    .SYNOPSIS
        Per-DC replication health with reachability gating. Get-ADReplication* take no -Server.
    .DESCRIPTION
        Takes the DCs of every scoped domain (PORT-PLAN C2e): rows (HostName, Scope) so each row
        carries its domain, or plain host names. A scoped domain with no DC row gets its own
        "Replication health (population): <domain>" Not Assessed row. A DC is probed through the
        shared gate (Get-AdfaDcProbeGate, PORT-PLAN C1b): one classified Unreachable is Not
        Assessed with that class and is not probed again.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # AllowEmptyCollection: when DC enumeration fails the caller passes an empty list. DC rows
        # (HostName, Scope) or plain host names (PORT-PLAN C2e).
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [hashtable]$RepParams = @{},
        [int]$RpcPortTimeoutMs = 1200,
        [int]$StaleMinutes = 180,
        # Domains whose DC enumeration threw (Domain, Error), and the domains of the run.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    $population = @(Get-AdfaDcPopulationRow -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Area 'Replication' `
            -Label 'Replication health' -NothingRead 'No replication partner of it was read.' -Shape 'DomainController')
    if ($targets.Count -eq 0) {
        return @(@($population) + @(New-Finding -Area 'Replication' -Item 'Replication health' -Status $script:Status.NotAssessed `
                    -Detail 'No domain controllers were enumerated, so replication health could not be assessed. This is not a clean result.'))
    }
    $rows = foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        $gate = $null
        $skip = ''
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $dc = '(unnamed)'
            $skip = 'The inventory holds a domain controller with no host name, so there was nothing to connect to and no replication partner was read.'
        }
        else {
            $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135, 9389) -TimeoutMs $RpcPortTimeoutMs
            if ($gate.Cause) { $skip = Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'no replication partner was read' }
            elseif (-not ($gate.Open[135] -and $gate.Open[9389])) { $skip = ("SKIPPED: RPC135={0} ADWS9389={1}" -f $gate.Open[135], $gate.Open[9389]) }
        }
        if ($skip) {
            # Same shape as the full row below - a section whose rows disagree breaks CSV
            # columns and, under StrictMode, the HTML renderer.
            [pscustomobject]@{
                DomainController = $dc; PartnerCount = $null; PartnerErrors = $null
                LastSuccessMinutesAgo = $null; FailureCount = $null; OldestFailureTime = $null
                ReplicationQueue = $null; Status = $script:Status.NotAssessed
                FailureDetail = ''
                Detail = $skip; Scope = $scope
            }
            continue
        }

        $meta = $null; $fail = $null; $qCount = $null; $notes = @()
        $metaOk = $false; $failOk = $false; $queueOk = $false
        try { $meta = Get-ADReplicationPartnerMetadata -Target $dc -Partition * @RepParams -ErrorAction Stop; $metaOk = $true }
        catch { $notes += ("PartnerMetadata: {0}" -f $_.Exception.Message) }
        try { $fail = Get-ADReplicationFailure -Target $dc -Scope Server @RepParams -ErrorAction Stop; $failOk = $true }
        catch { $notes += ("ReplicationFailure: {0}" -f $_.Exception.Message) }
        try { $q = Get-ADReplicationQueueOperation -Server $dc @RepParams -ErrorAction Stop; $queueOk = $true; $qCount = @($q).Count }
        catch { $notes += ("QueueOperation: {0}" -f $_.Exception.Message) }

        $partnerErrors = 0; $partnerCount = $null; $lastMin = $null
        $failingList = New-Object System.Collections.Generic.List[string]
        if ($meta) {
            $badPartners = @($meta | Where-Object { $_.ConsecutiveReplicationFailures -gt 0 })
            $partnerErrors = $badPartners.Count
            $partners = @($meta | Select-Object -ExpandProperty Partner -ErrorAction SilentlyContinue | Sort-Object -Unique)
            $partnerCount = $partners.Count
            $succ = @($meta | Where-Object { $_.LastReplicationSuccess } | ForEach-Object { $_.LastReplicationSuccess })
            if ($succ.Count -gt 0) {
                $latest = ($succ | Sort-Object -Descending | Select-Object -First 1)
                $lastMin = [math]::Round(((Get-Date) - $latest).TotalMinutes, 0)
            }
            foreach ($bp in $badPartners) {
                $failingList.Add(("partner={0} partition={1} lastResult={2} consecutiveFailures={3}" -f `
                    $bp.Partner, $bp.Partition, $bp.LastReplicationResult, $bp.ConsecutiveReplicationFailures))
            }
        }
        $failureCount = @($fail).Count
        $oldest = $null
        if ($fail -and @($fail).Count -gt 0) {
            $oldest = ($fail | Sort-Object FirstFailureTime | Select-Object -First 1).FirstFailureTime
            foreach ($fr in @($fail)) {
                $failingList.Add(("partner={0} failureType={1} count={2} since={3} lastError={4}" -f `
                    $fr.Partner, $fr.FailureType, $fr.FailureCount, $fr.FirstFailureTime, $fr.LastError))
            }
        }

        $anyQueried = ($metaOk -or $failOk -or $queueOk)
        $status = $script:Status.NotAssessed
        if ($anyQueried) {
            if ($partnerErrors -eq 0 -and $failureCount -eq 0 -and ($null -eq $lastMin -or $lastMin -le $StaleMinutes)) {
                $status = $script:Status.Pass
            }
            elseif ($partnerErrors -gt 0 -or $failureCount -gt 0) { $status = $script:Status.Fail }
            else { $status = $script:Status.Warning }
        }

        [pscustomobject]@{
            DomainController = $dc; PartnerCount = $partnerCount; PartnerErrors = $partnerErrors
            LastSuccessMinutesAgo = $lastMin; FailureCount = $failureCount; OldestFailureTime = $oldest
            ReplicationQueue = $qCount; Status = $status
            FailureDetail = ($failingList -join ' | ')
            Detail = $(if ($notes.Count -gt 0) { $notes -join ' | ' } else { '' })
            Scope = $scope
        }
    }
    return @(@($population) + @($rows))
}

function Get-AdfaTopologyObjectRaw {
    <#
    .SYNOPSIS
        The read seam of the site links and the connection objects (PORT-PLAN C4b): one
        Get-ADReplicationSiteLink or Get-ADReplicationConnection call with the declared property
        list, capped. Never throws.
    .DESCRIPTION
        The list is checked before anything is sent: a wildcard, a blank, an empty list or a secret
        attribute name refuses the read (Refused). Neither cmdlet's Filter parameter set shows
        -ResultSetSize on Learn, so the cap stops the pipeline after MaxObjects + 1 objects; a read
        that returned more than MaxObjects is Capped, never a short list read as complete.
    .OUTPUTS
        [pscustomobject] Ok, Error, ErrorType, NotFound, Refused, Records, Count, Capped, Kind.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][ValidateSet('SiteLink', 'Connection')][string]$Kind,
        [AllowNull()][AllowEmptyCollection()][string[]]$PropertyNames = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$SecretNames = @(),
        [ValidateRange(1, 1000000)][int]$MaxObjects = 100000,
        [hashtable]$AdParams = @{}
    )
    $out = [pscustomobject]@{ Ok = $false; Error = ''; ErrorType = ''; NotFound = $false; Refused = $false; Records = @(); Count = 0; Capped = $false; Kind = $Kind }
    $refused = @(Get-AdfaRefusedPropertyName -PropertyNames $PropertyNames -SecretNames $SecretNames)
    if ($refused.Count -gt 0) {
        $out.Refused = $true
        $out.Error = ("the property list was refused before anything was sent, because it names {0}; this is a defect in the tool's DirectoryRead table, not in the directory" -f ($refused -join ', '))
        return $out
    }
    try {
        $records = @()
        if ($Kind -eq 'SiteLink') {
            $records = @(Get-ADReplicationSiteLink -Filter * -Properties @($PropertyNames) @AdParams -ErrorAction Stop | Select-Object -First ($MaxObjects + 1))
        }
        else {
            $records = @(Get-ADReplicationConnection -Filter * -Properties @($PropertyNames) @AdParams -ErrorAction Stop | Select-Object -First ($MaxObjects + 1))
        }
        $out.Records = @($records | Where-Object { $null -ne $_ })
        $out.Count = @($out.Records).Count
        $out.Capped = ($out.Count -gt $MaxObjects)
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function ConvertTo-AdfaTopologyListRow {
    <#
    .SYNOPSIS
        Pure: the rows of 'Site Links' or 'Replication Connections' from one topology read
        (PORT-PLAN C4b). Inventory rows, not graded.
    .DESCRIPTION
        A read that was refused, failed (unreachable, access denied, timed out told apart) or reached
        its cap gives ONE row, Status Not Assessed with the cause - never an empty list, which would
        read as "no site link". A complete read gives one row per object, with the columns the
        sections have always had for site links, and for connections the raw LDAP values: FromServer
        (fromServer, the source's NTDS Settings DN), DistinguishedName (its parent is the NTDS Settings
        object of the DC that holds it), Enabled (enabledConnection) and Options (options, raw; its bits
        are not decoded, PORT-PLAN C4b3).
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][ValidateSet('SiteLink', 'Connection')][string]$Kind,
        [AllowNull()]$Raw,
        [ValidateRange(1, 1000000)][int]$MaxObjects = 100000,
        # Where MaxObjects came from, in the row's words (Get-AdfaCapSource).
        [string]$CapSource = 'Inventory.MaxObjects, a tool default'
    )
    $what = 'the site links'
    $item = 'Site links'
    if ($Kind -eq 'Connection') { $what = 'the replication connection objects'; $item = 'Replication connections' }
    $cause = ''
    if ($null -ne $Raw -and [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Refused')) {
        $cause = ("Reading {0} was refused: {1}." -f $what, ([string](Get-AdfaConfigValue -Entry $Raw -Name 'Error')).Trim().TrimEnd('.'))
    }
    else {
        $cause = Get-AdfaInventoryReadCause -Raw $Raw -What $what -MaxObjects $MaxObjects -CapSource $CapSource
    }
    if (-not [string]::IsNullOrWhiteSpace($cause)) {
        return @([pscustomobject]@{ Item = $item; Status = $script:Status.NotAssessed; Detail = ("{0} The list is not shown, and it is not an empty list." -f $cause) })
    }
    $rows = @()
    foreach ($r in @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Records') | Where-Object { $null -ne $_ })) {
        if ($Kind -eq 'SiteLink') {
            $sites = @(@(Get-AdfaConfigValue -Entry $r -Name 'SitesIncluded') | Where-Object { $null -ne $_ } | ForEach-Object { $_.ToString() })
            $rows += [pscustomobject]@{
                Name                          = [string](Get-AdfaConfigValue -Entry $r -Name 'Name')
                Cost                          = (Get-AdfaConfigValue -Entry $r -Name 'Cost')
                ReplicationFrequencyInMinutes = (Get-AdfaConfigValue -Entry $r -Name 'ReplicationFrequencyInMinutes')
                InterSiteTransportProtocol    = [string](Get-AdfaConfigValue -Entry $r -Name 'InterSiteTransportProtocol')
                SitesIncluded                 = ($sites -join '; ')
            }
        }
        else {
            $rows += [pscustomobject]@{
                Name              = [string](Get-AdfaConfigValue -Entry $r -Name 'name')
                FromServer        = [string](Get-AdfaConfigValue -Entry $r -Name 'fromServer')
                DistinguishedName = [string](Get-AdfaConfigValue -Entry $r -Name 'distinguishedName')
                Enabled           = (Get-AdfaConfigValue -Entry $r -Name 'enabledConnection')
                Options           = (Get-AdfaConfigValue -Entry $r -Name 'options')
            }
        }
    }
    return @($rows)
}

function Get-AdfaReplicationTopology {
    <#
    .SYNOPSIS
        Sites, subnets, site links and connection objects of the forest.
    .DESCRIPTION
        Since v1.33.0 (PORT-PLAN C4b) the site links and the connection objects are read with the
        declared lists of the DirectoryRead table, each through its own never-throwing seam, so a
        failed site link or connection read is a Not Assessed row of its own and no longer takes the
        sites and subnets down with it. The site and subnet reads are unchanged.
    .OUTPUTS
        [pscustomobject] Sites, Subnets, SiteLinks, Connections.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [hashtable]$AdParams = @{},
        [hashtable]$Config = $script:Config.DirectoryRead,
        [AllowNull()][AllowEmptyCollection()][string[]]$SecretNames = @(Get-AdfaSecretAttributeName),
        [ValidateRange(1, 1000000)][int]$MaxObjects = [int]$script:Config.Inventory['MaxObjects'],
        # Where MaxObjects came from, in the row's words (Get-AdfaCapSource).
        [string]$CapSource = 'Inventory.MaxObjects, a tool default'
    )
    $out = [ordered]@{}
    $out.Sites = @(Get-ADReplicationSite -Filter * @AdParams |
        Select-Object Name, Description, WhenCreated, WhenChanged)
    $out.Subnets = @(Get-ADReplicationSubnet -Filter * @AdParams |
        Select-Object Name, Site, Location, Description)
    $linkRaw = Get-AdfaTopologyObjectRaw -Kind SiteLink -PropertyNames @($Config['SiteLinkProperties']) -SecretNames $SecretNames -MaxObjects $MaxObjects -AdParams $AdParams
    $out.SiteLinks = @(ConvertTo-AdfaTopologyListRow -Kind SiteLink -Raw $linkRaw -MaxObjects $MaxObjects -CapSource $CapSource)
    $connRaw = Get-AdfaTopologyObjectRaw -Kind Connection -PropertyNames @($Config['ConnectionProperties']) -SecretNames $SecretNames -MaxObjects $MaxObjects -AdParams $AdParams
    $out.Connections = @(ConvertTo-AdfaTopologyListRow -Kind Connection -Raw $connRaw -MaxObjects $MaxObjects -CapSource $CapSource)
    return [pscustomobject]$out
}

function Get-AdfaSiteHealthFinding {
    <#
    .SYNOPSIS
        Derives findings from topology (sites without subnets, subnets without sites, empty sites).
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][pscustomobject]$Topology,
        # See the note on Get-AdfaReplicationHealth: an empty inventory must degrade, not abort.
        [Parameter(Mandatory)][AllowEmptyCollection()][pscustomobject[]]$DomainControllers)
    $findings = @()
    $dcSites = @($DomainControllers | ForEach-Object { $_.Site } | Sort-Object -Unique)

    foreach ($s in @($Topology.Sites)) {
        $hasSubnet = @($Topology.Subnets | Where-Object { $_.Site -match [regex]::Escape($s.Name) }).Count -gt 0
        if (-not $hasSubnet) {
            $findings += New-Finding -Area 'Sites' -Item ("Site '{0}' has no subnets" -f $s.Name) -Status $script:Status.Warning -Detail 'Clients may not map to this site.'
        }
        if ($dcSites -notcontains $s.Name) {
            $findings += New-Finding -Area 'Sites' -Item ("Site '{0}' has no domain controllers" -f $s.Name) -Status $script:Status.Info -Detail 'Empty site.'
        }
    }
    if (@($findings).Count -eq 0) {
        $findings += New-Finding -Area 'Sites' -Item 'Site/subnet topology' -Status $script:Status.Pass -Detail 'All sites have subnets and DCs.'
    }
    return @($findings)
}

# ===========================================================================
# region DC diagnostics (parsed)
# ===========================================================================

function Get-AdfaDcdiagArgument {
    <#
    .SYNOPSIS
        Pure: builds the dcdiag argument string for one test against one DC.
    .DESCRIPTION
        Exists because two tests in the grid need more than '/test:<name> /s:<dc>', and getting
        that wrong is silent rather than loud.

        Intersite. The vendor is explicit: "The /a or /e parameter must be used as not providing
        a site would allow the test to run but SKIPS ACTUAL TESTING." Every run of this tool
        before v1.13.0 invoked it without either, so the Intersite column reported Pass while
        dcdiag had tested nothing - a false Pass, which is the one outcome this tool is built to
        make impossible. /a (this AD site) is used rather than /e (whole enterprise), because
        Learn warns that run times with /e are significant and that offline DCs make them worse,
        and this grid already iterates every DC.

        DNS. Not run by default and must be requested explicitly; '/test:DNS' alone defaults to
        /DnsAll, but the default is spelled out here so a change to it cannot silently narrow
        what this tool checks. /DnsAll runs basic, forwarders, delegation, dynamic update and
        record registration - everything except the external-name resolution test, which needs
        internet egress and is not a directory-health question. Learn: /DnsAll "Performs all tests,
        except for the /DnsResolveExtName test". The summary table of this run is graded per test
        group (PORT-PLAN C12) without adding any switch: no /v, no /e, and never /x, whose XML
        Microsoft documents only as "Redirects all output to xmllog.xml", with no schema.

        https://learn.microsoft.com/windows-server/administration/windows-commands/dcdiag
        Read: 2026-11-16.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$TestName,
        [Parameter(Mandatory)][string]$DomainController
    )
    if ($TestName -eq 'Intersite') { return ("/test:Intersite /s:{0} /a" -f $DomainController) }
    if ($TestName -eq 'DNS') { return ("/test:DNS /DnsAll /s:{0}" -f $DomainController) }
    return ("/test:{0} /s:{1}" -f $TestName, $DomainController)
}

function Get-AdfaDcdiagTestOutcome {
    <#
    .SYNOPSIS
        Pure classification of one 'dcdiag /test:<name>' invocation.
    .DESCRIPTION
        Separates the three things a run can mean, which the caller previously collapsed into
        two. 'dcdiag ran and said passed/failed' is a measurement. 'dcdiag ran and its output
        contained neither verdict' and 'dcdiag did not run' are BOTH unassessed - but for
        different reasons, and only one of them is about the directory.

        The verdict strings are dcdiag's own, matched case-insensitively and with the test name
        escaped, so a name containing regex metacharacters cannot silently widen the match.
    .OUTPUTS
        [string] Pass | Fail | Unparsed | ToolFailed
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$TestName,
        [bool]$Success = $true,
        [AllowNull()][string]$StdOut = ''
    )
    $escaped = [regex]::Escape($TestName)
    $text = "$StdOut"
    # The verdict is read before Success is consulted on purpose: dcdiag returns a non-zero exit
    # code for a FAILED test, and treating that as "the tool did not run" would discard a real
    # measurement. Only output with no verdict at all falls through to the Success check.
    # 'failed' is read BEFORE 'passed' (PORT-PLAN C11, the reference's R2 false pass): output that
    # holds both - one partition passed, another failed - is a Fail, never a Pass. The collector
    # itself grades through ConvertFrom-AdfaDcdiagOutput and Resolve-AdfaDcdiagVerdict, which
    # also attribute each verdict to its DC, partition or enterprise block.
    if ($text -match ("(?i)failed test\s+{0}\b" -f $escaped)) { return 'Fail' }
    if ($text -match ("(?i)passed test\s+{0}\b" -f $escaped)) { return 'Pass' }
    if (-not $Success) { return 'ToolFailed' }
    return 'Unparsed'
}

function Get-AdfaDcdiagUnassessedCause {
    <#
    .SYNOPSIS
        Pure: builds the human-readable cause for a dcdiag cell that could not be assessed.
    .DESCRIPTION
        This exists because the collector used to write 'Not Assessed' into the grid and keep
        NOTHING about why - no exit code, no output, no error. On a live forest that made
        several cells unassessed on every DC with no way to tell whether dcdiag had failed to
        run, run and said something unrecognised, or been localised into a language the verdict
        match does not know. CLAUDE.md requires a value that was not measured to be reported
        with a NAMED CAUSE; an empty 'Not Assessed' is not that.

        The stdout excerpt is deliberately short and stripped of blank lines: enough to identify
        a localised verdict line or an access error, not enough to bloat a CSV cell. It is NOT
        the first lines of output - those are dcdiag's banner ("Directory Server Diagnosis",
        "Performing initial setup") and say nothing. Lines naming the test, or carrying a
        verdict or error word, are preferred; failing that the LAST lines are taken, because
        that is where dcdiag prints its summary and therefore where a localised verdict sits.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$TestName,
        [Parameter(Mandatory)][ValidateSet('Unparsed', 'ToolFailed')][string]$Outcome,
        [AllowNull()][string]$StdOut = '',
        [AllowNull()][string]$ErrorText = '',
        [AllowNull()]$ExitCode = $null,
        [int]$ExcerptChars = 200
    )
    $excerpt = Get-AdfaDcdiagOutputExcerpt -TestName $TestName -StdOut $StdOut -ExcerptChars $ExcerptChars
    $codeText = '(none)'
    if ($null -ne $ExitCode) { $codeText = [string]$ExitCode }

    if ($Outcome -eq 'ToolFailed') {
        $why = "dcdiag did not complete (exit code {0})" -f $codeText
        if (-not [string]::IsNullOrWhiteSpace($ErrorText)) { $why = "{0}: {1}" -f $why, ("$ErrorText").Trim() }
        if ($excerpt) { $why = "{0}. Output: {1}" -f $why, $excerpt }
        return ("{0}: NOT ASSESSED - {1}. The test did not run, so nothing is known about it on this DC." -f $TestName, $why)
    }
    if ([string]::IsNullOrWhiteSpace($excerpt)) {
        return ("{0}: NOT ASSESSED - dcdiag exited {1} and produced NO output, so the test reported no verdict. Run 'dcdiag /test:{0} /s:<dc>' by hand on this DC to see what it says." -f $TestName, $codeText)
    }
    return ("{0}: NOT ASSESSED - dcdiag ran (exit code {1}) but its output contained neither 'passed test {0}' nor 'failed test {0}', so no verdict could be read. This is usually a test that did not execute on this DC, or a non-English Windows whose verdict line this build does not match. Output: {2}" -f $TestName, $codeText, $excerpt)
}

function Get-AdfaDcdiagOutputExcerpt {
    <#
    .SYNOPSIS
        Pure: a short excerpt of dcdiag output, for the cause of a cell that could not be assessed.
    .DESCRIPTION
        The lines that name the test or carry a verdict or error word, the last four of them;
        failing that the last four lines, because dcdiag prints its banner at the top and its
        summary at the bottom. Bounded to -ExcerptChars, with "..." when cut.
    .OUTPUTS
        [string] '' when there is no output.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$TestName,
        [AllowNull()][string]$StdOut = '',
        [int]$ExcerptChars = 200
    )
    $lines = @(("$StdOut") -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    if ($lines.Count -eq 0) { return '' }
    $escapedName = [regex]::Escape($TestName)
    $interesting = @($lines | Where-Object {
            $_ -match $escapedName -or $_ -match '(?i)\btest\b|error|warning|fail|cannot|could not|denied|unable'
        } | Select-Object -Last 4)
    # No line looked diagnostic, so take the END of the output rather than the start: the
    # beginning is dcdiag's banner, the summary is at the bottom.
    if (@($interesting).Count -eq 0) { $interesting = @($lines | Select-Object -Last 4) }
    $joined = @($interesting) -join ' / '
    if ($joined.Length -gt $ExcerptChars) { $joined = $joined.Substring(0, $ExcerptChars) + '...' }
    return $joined
}

function Test-AdfaDcdiagSubject {
    <#
    .SYNOPSIS
        Pure: whether the subject of a dcdiag verdict line ("<subject> passed test X") names this
        domain controller.
    .DESCRIPTION
        dcdiag names a DC by its short name in a verdict line. In the dcdiag reference's sample the
        home server is "MapleWaffle-WS22" and its verdicts are written for "MAPLEWAFFLE-WS2": the
        NetBIOS name, which is at most 15 characters ("Maximum name length: 15 characters", Naming
        conventions in Active Directory, KB 909264). So a subject matches the full host name, its
        first label, or - only when that label is longer than 15 characters and the subject is
        exactly 15 - the label's first 15 characters. Compared without regard to case. An empty
        subject matches nothing; the caller decides what a bare verdict line means.
          https://learn.microsoft.com/windows-server/administration/windows-commands/dcdiag
          https://learn.microsoft.com/troubleshoot/windows-server/active-directory/naming-conventions-for-computer-domain-site-ou
          Read: 2026-11-16 (both).
    .OUTPUTS
        [bool]
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Subject = '',
        [AllowNull()][AllowEmptyString()][string]$HostName = ''
    )
    $s = ("$Subject").Trim().TrimStart('.').ToLowerInvariant()
    $h = ("$HostName").Trim().ToLowerInvariant()
    if ($s -eq '' -or $h -eq '') { return $false }
    if ($s -eq $h) { return $true }
    $short = $h.Split('.')[0]
    if ($s -eq $short) { return $true }
    if ($s.Length -eq 15 -and $short.Length -gt 15 -and $short.StartsWith($s, [System.StringComparison]::Ordinal)) { return $true }
    return $false
}

function ConvertFrom-AdfaDcdiagOutput {
    <#
    .SYNOPSIS
        Pure parser for the output of one dcdiag invocation: every verdict line, attributed to the
        block it is printed in, and the lines that say why a verdict may be missing.
    .DESCRIPTION
        The block headers and the verdict line are the en-US text of the dcdiag reference's sample
        output (OutputMarkers in the DcDiag config table): "Testing server: <site>\<DC>" opens a
        Server block, "Running partition tests on : <NC>" a Partition block and "Running enterprise
        tests on : <name>" an Enterprise block. A verdict is "<subject> passed|failed test <Test>";
        the match spans the line break Learn's own sample shows between "passed test" and the test
        name. A verdict before any header is in block None.

        Every verdict found is returned, for every test, so the caller can tell "this DC's
        verdict", "another DC's verdict", "a partition's verdict" and "no verdict" apart. Nothing
        here grades anything.

        Recognised is true when the output holds any line this build reads: a block header, a
        verdict, or one of dcdiag's banner lines. Output that is not empty and holds none of them
        is the shape a localised (non-English) dcdiag would produce.

        Evidence: the lines matching the UnreachablePatterns (provisional), AccessDeniedPatterns and
        EventLogUnreadablePatterns of the config table, at most three of each.
    .OUTPUTS
        [pscustomobject] Empty, Recognised, Parts (Test, Verdict Pass|Fail, Subject, ScopeKind
        Server|Partition|Enterprise|None, ScopeName, Line), UnreachableEvidence,
        AccessDeniedEvidence, EventLogUnreadableEvidence.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$StdOut = '',
        [Parameter(Mandatory)][hashtable]$Config
    )
    $text = "$StdOut"
    $markers = Get-AdfaConfigValue -Entry $Config -Name 'OutputMarkers'
    $blocks = New-Object System.Collections.ArrayList
    foreach ($kind in @('Server', 'Partition', 'Enterprise')) {
        $pattern = [string](Get-AdfaConfigValue -Entry $markers -Name ("{0}Block" -f $kind))
        if ($pattern -eq '') { continue }
        foreach ($m in [regex]::Matches($text, $pattern)) {
            [void]$blocks.Add([pscustomobject]@{ Index = [int]$m.Index; Kind = $kind; Name = [string]$m.Groups['name'].Value })
        }
    }
    $ordered = @($blocks | Sort-Object -Property Index)
    $parts = New-Object System.Collections.ArrayList
    $verdictPattern = [string](Get-AdfaConfigValue -Entry $markers -Name 'Verdict')
    if ($verdictPattern -ne '') {
        foreach ($m in [regex]::Matches($text, $verdictPattern)) {
            $kind = 'None'
            $name = ''
            foreach ($b in $ordered) {
                if ($b.Index -lt $m.Index) { $kind = $b.Kind; $name = $b.Name }
                else { break }
            }
            $verdict = 'Pass'
            if ([string]$m.Groups['verdict'].Value -match '(?i)^failed$') { $verdict = 'Fail' }
            [void]$parts.Add([pscustomobject]@{
                    Test      = [string]$m.Groups['test'].Value
                    Verdict   = $verdict
                    Subject   = ([string]$m.Groups['subject'].Value).Trim().TrimStart('.')
                    ScopeKind = $kind
                    ScopeName = $name
                    Line      = (([string]$m.Value) -replace '\s+', ' ').Trim()
                })
        }
    }
    $recognised = ($blocks.Count -gt 0 -or $parts.Count -gt 0)
    if (-not $recognised) {
        foreach ($p in @(Get-AdfaConfigValue -Entry $markers -Name 'Recognised')) {
            if (-not [string]::IsNullOrEmpty([string]$p) -and $text -match [string]$p) { $recognised = $true; break }
        }
    }
    $lines = @($text -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    $evidence = @{}
    foreach ($key in @('UnreachablePatterns', 'AccessDeniedPatterns', 'EventLogUnreadablePatterns')) {
        $found = New-Object System.Collections.ArrayList
        foreach ($entry in @(Get-AdfaConfigValue -Entry $Config -Name $key)) {
            $pattern = [string](Get-AdfaConfigValue -Entry $entry -Name 'Pattern')
            if ($pattern -eq '') { continue }
            foreach ($line in $lines) {
                if ($line -match $pattern -and -not $found.Contains($line)) { [void]$found.Add($line) }
            }
        }
        $evidence[$key] = @($found | Select-Object -First 3)
    }
    return [pscustomobject]@{
        Empty                      = [string]::IsNullOrWhiteSpace($text)
        Recognised                 = [bool]$recognised
        Parts                      = $parts.ToArray()
        UnreachableEvidence        = @($evidence['UnreachablePatterns'])
        AccessDeniedEvidence       = @($evidence['AccessDeniedPatterns'])
        EventLogUnreadableEvidence = @($evidence['EventLogUnreadablePatterns'])
    }
}

function Resolve-AdfaDcdiagVerdict {
    <#
    .SYNOPSIS
        Pure verdict for one dcdiag test from its parsed output: Pass, Fail or Not Assessed, and
        the text that says why.
    .DESCRIPTION
        Which verdicts count. Mode Dc (a per-DC grid cell): the DC's own verdicts - a Server or
        None block whose subject names -HostName (Test-AdfaDcdiagSubject), or a bare verdict with
        no subject, which in a "/s:<this DC>" invocation can only be about this DC - and, for a
        test with -PartitionParts, the verdicts in partition blocks, which are about the replicas
        of the server that was asked; for a test with -EnterpriseParts (one of dcdiag's enterprise
        tests, such as DNS and FsmoCheck), the verdicts in the enterprise block, which in a
        "/s:<this DC>" invocation without /e is the enterprise test run from this DC. Other
        enterprise verdicts, other DCs' verdicts and other tests' partition verdicts never count
        for a DC: they are listed as "not counted". Mode Scope (a
        once-per-domain, -forest or -site test): every verdict for the test counts, wherever it is
        printed.

        The roll-up: any counted part failed -> Fail; otherwise any passed -> Pass; otherwise Not
        Assessed. "failed" always wins, whatever order the lines are in. A missing verdict is never
        a Pass.

        Two documented exceptions. An event-log test (-EventLog) that failed while its output says
        the log "could not be queried" is Not Assessed: Microsoft calls that an expected error of
        the DC's firewall rules (KB 2512643), and the log was not read. A failed verdict whose
        output also says "Access is denied" stays a Fail, with a note: Microsoft documents
        error 5 "Access is denied" between DCs, with causes on the DCs themselves (KB 3073945,
        https://learn.microsoft.com/troubleshoot/windows-server/active-directory/replication-error-5,
        read 2026-11-16), so the words
        alone do not show that the runner lacked rights. The note is worded without the words
        the unscoped recommendation entries match on (no "replication", "not a pass", ...), so it
        cannot choose the advice for the grid row: the recommendation map matches on the whole
        finding text, first match wins, and a grid row has no section-scoped entry.

        With no counted verdict, the cause is chosen in this order: access denied; the server could
        not be reached (provisional patterns); the invocation's own Connectivity test failed; a
        verdict was printed only for something other than this DC; dcdiag did not complete; no
        output; output not recognised (possibly localised); otherwise no verdict line.
    .OUTPUTS
        [pscustomobject] Status, Detail ('' for a plain Pass), Parts (counted), Ignored.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Parsed,
        [Parameter(Mandatory)][string]$TestName,
        [ValidateSet('Dc', 'Scope')][string]$Mode = 'Dc',
        [AllowNull()][AllowEmptyString()][string]$HostName = '',
        [bool]$PartitionParts = $false,
        [bool]$EnterpriseParts = $false,
        [bool]$EventLog = $false,
        [bool]$Success = $true,
        [AllowNull()]$ExitCode = $null,
        [AllowNull()][AllowEmptyString()][string]$ErrorText = '',
        [AllowNull()][AllowEmptyString()][string]$StdOut = ''
    )
    $relevant = New-Object System.Collections.ArrayList
    $ignored = New-Object System.Collections.ArrayList
    $connectivityFailed = $false
    foreach ($part in @($Parsed.Parts)) {
        if ($null -eq $part) { continue }
        $counts = $false
        if ($Mode -eq 'Scope') { $counts = $true }
        elseif ([string]$part.ScopeKind -eq 'Partition') { $counts = $PartitionParts }
        elseif ([string]$part.ScopeKind -eq 'Enterprise') { $counts = $EnterpriseParts }
        else {
            $subject = [string]$part.Subject
            if ($subject -eq '' -and [string]$part.ScopeKind -eq 'Server') { $subject = [string]$part.ScopeName }
            if ($subject -eq '') { $counts = $true }
            else { $counts = Test-AdfaDcdiagSubject -Subject $subject -HostName $HostName }
        }
        if ([string]$part.Test -ne $TestName) {
            if ($counts -and [string]$part.Test -eq 'Connectivity' -and [string]$part.Verdict -eq 'Fail') { $connectivityFailed = $true }
            continue
        }
        if ($counts) { [void]$relevant.Add($part) } else { [void]$ignored.Add($part) }
    }
    $failed = @($relevant | Where-Object { [string]$_.Verdict -eq 'Fail' })
    $passed = @($relevant | Where-Object { [string]$_.Verdict -eq 'Pass' })
    $out = [pscustomobject]@{ Status = $script:Status.NotAssessed; Detail = ''; Parts = $relevant.ToArray(); Ignored = $ignored.ToArray() }
    $quote = {
        param([string]$Line)
        $q = $Line.Trim()
        if ($q.Length -gt 200) { $q = $q.Substring(0, 200) + '...' }
        $q
    }

    if ($failed.Count -gt 0) {
        $eventLines = @($Parsed.EventLogUnreadableEvidence)
        if ($EventLog -and $eventLines.Count -gt 0) {
            $out.Detail = ("{0}: NOT ASSESSED - dcdiag reported the test failed, but the event log it reads could not be queried ('{1}'). Microsoft documents this as an expected error when the domain controller's firewall does not allow remote event log access, and names the inbound rules Remote Event Log Management (NP-In), (RPC) and (RPC-EPMAP) (KB 2512643). The log itself was not read, so nothing is known about its entries." -f $TestName, (& $quote $eventLines[0]))
            return $out
        }
        $out.Status = $script:Status.Fail
        $errLines = @(("$StdOut") -split "`r?`n" |
            Where-Object { $_ -match 'error|warning|failed|could not|cannot|unable' -and $_ -notmatch 'passed test' } |
            ForEach-Object { $_.Trim() } | Where-Object { $_ } | Select-Object -First 3)
        $what = 'no diagnostic lines captured'
        if ($errLines.Count -gt 0) { $what = $errLines -join ' / ' }
        $where = @($failed | Where-Object { [string]$_.ScopeKind -eq 'Partition' } | ForEach-Object { [string]$_.ScopeName })
        if ($Mode -eq 'Dc' -and $where.Count -gt 0) { $what = ("failed for partition(s) {0}: {1}" -f ($where -join ', '), $what) }
        $enterprise = @($failed | Where-Object { [string]$_.ScopeKind -eq 'Enterprise' } | ForEach-Object { [string]$_.ScopeName } | Select-Object -Unique)
        if ($Mode -eq 'Dc' -and $enterprise.Count -gt 0) {
            $what = ("failed in the enterprise tests on {0}, which dcdiag ran from this domain controller (a fault of the forest shows on every domain controller asked): {1}" -f ($enterprise -join ', '), $what)
        }
        $out.Detail = ("{0}: {1}" -f $TestName, $what)
        if (@($Parsed.AccessDeniedEvidence).Count -gt 0) {
            # Worded so that no unscoped recommendation entry matches it (see .DESCRIPTION).
            $out.Detail = ("{0}. The output also says 'Access is denied' (error 5): Microsoft documents that error between domain controllers with causes on the domain controllers themselves, such as an invalid secure channel (KB 3073945), and it can also be the rights of the account running dcdiag; the failure is reported as dcdiag printed it." -f $out.Detail.TrimEnd('.'))
        }
        return $out
    }
    if ($passed.Count -gt 0) {
        $out.Status = $script:Status.Pass
        return $out
    }

    $denied = @($Parsed.AccessDeniedEvidence)
    $unreachable = @($Parsed.UnreachableEvidence)
    if ($denied.Count -gt 0) {
        $out.Detail = ("{0}: NOT ASSESSED - access denied: dcdiag printed no verdict for this test, and its output says '{1}'. Microsoft documents that dcdiag must be run with administrative rights from an elevated prompt; the account running this tool may not hold them on this server. Nothing is known about this test here." -f $TestName, (& $quote $denied[0]))
    }
    elseif ($unreachable.Count -gt 0) {
        $out.Detail = ("{0}: NOT ASSESSED - dcdiag printed no verdict for this test, and its output says it could not reach the server: '{1}'. That line is matched by a provisional pattern, not a string Microsoft publishes. Nothing is known about this test here." -f $TestName, (& $quote $unreachable[0]))
    }
    elseif ($connectivityFailed -and $TestName -ne 'Connectivity') {
        $out.Detail = ("{0}: NOT ASSESSED - dcdiag's initial Connectivity test failed in this invocation and no verdict for {0} was printed. dcdiag runs Connectivity first in every invocation (Microsoft: it can't be skipped)." -f $TestName)
    }
    elseif ($ignored.Count -gt 0) {
        $named = @($ignored | ForEach-Object {
                $label = [string]$_.Subject
                if ([string]$_.ScopeKind -eq 'Partition' -or [string]$_.ScopeKind -eq 'Enterprise') { $label = ("{0} {1}" -f ([string]$_.ScopeKind).ToLowerInvariant(), [string]$_.ScopeName) }
                elseif ($label -eq '') { $label = [string]$_.ScopeName }
                $label
            } | Select-Object -Unique)
        $out.Detail = ("{0}: NOT ASSESSED - dcdiag printed a verdict for {0} only for {1}, which is not this domain controller, so it is not counted here." -f $TestName, ($named -join ', '))
    }
    elseif (-not $Success) {
        $out.Detail = Get-AdfaDcdiagUnassessedCause -TestName $TestName -Outcome 'ToolFailed' -StdOut $StdOut -ErrorText $ErrorText -ExitCode $ExitCode
    }
    elseif ([bool]$Parsed.Empty) {
        $out.Detail = Get-AdfaDcdiagUnassessedCause -TestName $TestName -Outcome 'Unparsed' -StdOut $StdOut -ErrorText $ErrorText -ExitCode $ExitCode
    }
    elseif (-not [bool]$Parsed.Recognised) {
        $out.Detail = ("{0}: NOT ASSESSED - the dcdiag output was not recognised (possibly a localised, non-English Windows): it holds no line in a form this build reads ('Testing server:', 'Starting test:', 'passed test', 'failed test'), so no verdict was read and the cell is not graded. Output: {1}" -f $TestName, (Get-AdfaDcdiagOutputExcerpt -TestName $TestName -StdOut $StdOut))
    }
    else {
        $out.Detail = Get-AdfaDcdiagUnassessedCause -TestName $TestName -Outcome 'Unparsed' -StdOut $StdOut -ErrorText $ErrorText -ExitCode $ExitCode
    }
    return $out
}

function Invoke-AdfaDcdiagTest {
    <#
    .SYNOPSIS
        The one place that runs dcdiag for the parsed section: one test against one server, with
        the argument from Get-AdfaDcdiagArgument. Never throws.
    .OUTPUTS
        [pscustomobject] StdOut, Success, ExitCode, Error.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$TestName,
        [Parameter(Mandatory)][string]$DomainController,
        [int]$TimeoutSeconds = 90,
        [int]$Retries = 2,
        [int]$RetryDelaySeconds = 2
    )
    $out = [pscustomobject]@{ StdOut = ''; Success = $true; ExitCode = $null; Error = '' }
    try {
        $r = Invoke-ExternalCommand -FilePath 'dcdiag.exe' -Arguments (Get-AdfaDcdiagArgument -TestName $TestName -DomainController $DomainController) `
            -TimeoutSeconds $TimeoutSeconds -Retries $Retries -RetryDelaySeconds $RetryDelaySeconds
        # StrictMode-safe reads: Invoke-ExternalCommand's contract is fixed, but a stub or a future
        # change must not be able to abort the run on a missing property.
        if ($null -ne $r) {
            $sp = $r.PSObject.Properties['StdOut']
            if ($null -ne $sp -and $null -ne $sp.Value) { $out.StdOut = [string]$sp.Value }
            $okp = $r.PSObject.Properties['Success']
            if ($null -ne $okp -and $null -ne $okp.Value) { $out.Success = [bool]$okp.Value }
            $ep = $r.PSObject.Properties['ExitCode']
            if ($null -ne $ep -and $null -ne $ep.Value) { $out.ExitCode = $ep.Value }
            $erp = $r.PSObject.Properties['Error']
            if ($null -ne $erp -and $null -ne $erp.Value) { $out.Error = [string]$erp.Value }
        }
        else {
            $out.Success = $false
            $out.Error = 'the command returned nothing'
        }
    }
    catch {
        $out.Success = $false
        $out.Error = [string]$_.Exception.Message
    }
    return $out
}

function New-AdfaDcDiagRow {
    <#
    .SYNOPSIS
        Pure: one row of a dcdiag test that runs once per domain, forest or site, or a population
        row of the section. Every such row has the same columns. (The per-DC grid rows keep their
        own shape: DomainController, Scope, Status, Ping, one DCDIAG_<test> column per test,
        Failures, NotRun.)
    .OUTPUTS
        [pscustomobject] Scope, Area, Item, Status, Detail, Evidence, Target, NotRun.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][ValidateSet('Pass', 'Warning', 'Fail', 'Not Assessed', 'Info')][string]$Status,
        [AllowNull()][AllowEmptyString()][string]$Detail = '',
        [AllowNull()][AllowEmptyString()][string]$Evidence = '',
        [AllowNull()][AllowEmptyString()][string]$Target = '',
        [AllowNull()][AllowEmptyString()][string]$NotRun = ''
    )
    return [pscustomobject]@{
        Scope    = [string]$Scope
        Area     = 'DcDiagnostics'
        Item     = $Item
        Status   = $Status
        Detail   = [string]$Detail
        Evidence = [string]$Evidence
        Target   = [string]$Target
        NotRun   = [string]$NotRun
    }
}

function ConvertFrom-AdfaDcdiagDnsSummary {
    <#
    .SYNOPSIS
        Pure parser for the summary table of dcdiag's DNS test: the header, and one row per DC with
        its "Domain:" line and its cells.
    .DESCRIPTION
        The table is in the output of the DNS test C11 already runs; nothing is invoked here. Its
        only published form is one sample on Learn (KB 2102154, read 2026-11-16, DnsSummary in the
        DcDiag config table): a header "Auth Basc Forw Del  Dyn  RReg Ext" with uneven spacing,
        "Domain: <fqdn>" lines, rows "<DC> PASS PASS FAIL PASS PASS PASS n/a", then "Enterprise DNS
        infrastructure test results:".

        The header is the LAST line (Learn: the summary table is at the end of the report) whose
        whitespace-separated tokens are all column tokens of the config table, compared without
        regard to case, none twice, and at least HeaderMinTokens of them (a tool default). It is
        never found by column position. Rows run from the header to the first end marker, verdict
        line or block header; blank lines and separator lines are skipped, a "Domain:" line sets the
        domain of the rows under it. Each row is split on runs of whitespace: the first token is the
        DC's name, the rest are its cells, mapped to the header's columns by order by the caller. A
        row whose cell count is not the header's column count is kept with Recognised = $false, so
        it can never be graded. CRLF and LF are both read.

        Nothing is graded here.
    .OUTPUTS
        [pscustomobject] HeaderFound, HeaderLine, HeaderCount (header lines seen), Columns (tokens in
        header order, spelled as in the config table), Rows (Name, Domain, Cells, CellCount,
        Recognised, Line).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$StdOut = '',
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{ HeaderFound = $false; HeaderLine = ''; HeaderCount = 0; Columns = @(); Rows = @() }
    $ds = Get-AdfaConfigValue -Entry $Config -Name 'DnsSummary'
    if ($null -eq $ds) { return $out }
    $known = @(@(Get-AdfaConfigValue -Entry $ds -Name 'Categories') | Where-Object { $null -ne $_ } | ForEach-Object { [string](Get-AdfaConfigValue -Entry $_ -Name 'Token') } | Where-Object { $_ -ne '' })
    if ($known.Count -eq 0) { return $out }
    # Fail closed: with no threshold configured, every column must be in the header.
    $min = $known.Count
    $configuredMin = Get-AdfaConfigValue -Entry $ds -Name 'HeaderMinTokens'
    if ($null -ne $configuredMin) { $min = [int]$configuredMin }
    if ($min -lt 1) { $min = 1 }
    $lines = @(("$StdOut") -split "`r?`n" | ForEach-Object { $_.Trim() })

    $headerAt = -1
    $columns = @()
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $tokens = @($lines[$i] -split '\s+' | Where-Object { $_ -ne '' })
        if ($tokens.Count -eq 0 -or $tokens.Count -lt $min) { continue }
        $canon = @()
        $isHeader = $true
        foreach ($tk in $tokens) {
            $hit = @($known | Where-Object { $_ -eq $tk })
            if ($hit.Count -ne 1 -or $canon -contains $hit[0]) { $isHeader = $false; break }
            $canon += [string]$hit[0]
        }
        if (-not $isHeader) { continue }
        $headerAt = $i
        $columns = $canon
        $out.HeaderCount = $out.HeaderCount + 1
    }
    if ($headerAt -lt 0) { return $out }

    $stops = New-Object System.Collections.Generic.List[string]
    foreach ($p in @(Get-AdfaConfigValue -Entry $ds -Name 'EndMarkers')) { if (-not [string]::IsNullOrEmpty([string]$p)) { $stops.Add([string]$p) } }
    $markers = Get-AdfaConfigValue -Entry $Config -Name 'OutputMarkers'
    foreach ($k in @('ServerBlock', 'PartitionBlock', 'EnterpriseBlock')) {
        $p = [string](Get-AdfaConfigValue -Entry $markers -Name $k)
        if ($p -ne '') { $stops.Add($p) }
    }
    $domainPattern = [string](Get-AdfaConfigValue -Entry $ds -Name 'DomainLine')
    $separator = [string](Get-AdfaConfigValue -Entry $ds -Name 'SeparatorLine')
    $rows = New-Object System.Collections.ArrayList
    $domain = ''
    for ($j = $headerAt + 1; $j -lt $lines.Count; $j++) {
        $line = $lines[$j]
        if ($line -eq '') { continue }
        $stop = $false
        foreach ($p in $stops) { if ($line -match $p) { $stop = $true; break } }
        if ($stop) { break }
        if ($separator -ne '' -and $line -match $separator) { continue }
        if ($domainPattern -ne '') {
            $dm = [regex]::Match($line, $domainPattern)
            if ($dm.Success) { $domain = [string]$dm.Groups['name'].Value; continue }
        }
        $tokens = @($line -split '\s+' | Where-Object { $_ -ne '' })
        $cells = @()
        if ($tokens.Count -gt 1) { $cells = @($tokens[1..($tokens.Count - 1)]) }
        [void]$rows.Add([pscustomobject]@{
                Name       = [string]$tokens[0]
                Domain     = $domain
                Cells      = $cells
                CellCount  = $cells.Count
                Recognised = ($cells.Count -eq $columns.Count)
                Line       = ($tokens -join ' ')
            })
    }
    $out.HeaderFound = $true
    $out.HeaderLine = (@($lines[$headerAt] -split '\s+' | Where-Object { $_ -ne '' }) -join ' ')
    $out.Columns = $columns
    $out.Rows = $rows.ToArray()
    return $out
}

function Resolve-AdfaDcdiagDnsCategory {
    <#
    .SYNOPSIS
        Pure verdict for one test group (Auth, Basc, Forw, Del, Dyn, RReg or Ext) of dcdiag's DNS
        summary table, for one DC: Status, Detail, the cell and the evidence lines.
    .DESCRIPTION
        In this order, the first that applies:
          -NotRunCause (the DC was unreachable on RPC/135, dcdiag.exe is absent, the test was not
            started after Connectivity failed, the DC has no host name) -> Not Assessed with it.
          No table in the output -> Not Assessed: with -RunCause (C11's cause for a test that
            printed no verdict: access denied, unreachable, did not complete or timed out, no
            output, not recognised) when there is one, otherwise saying that the overall verdict
            (-OverallStatus, -OverallEvidence) grades no test group.
          No row for this DC (Test-AdfaDcdiagSubject: host name, first label, 15-character NetBIOS
            form), or more than one -> Not Assessed.
          No column for the group in the header -> Not Assessed.
          The DC's row has a cell count other than the header's -> Not Assessed ("row not
            recognised").
          A cell value outside the config table's Cells -> Not Assessed ("cell value not
            recognised").
          Otherwise the Cells map: PASS Pass, FAIL Fail, WARN Warning (provisional: Learn shows
          "Warn" only in prose), n/a Not Assessed - except in a column with its own NaStatus (Ext:
          Info, "not requested by /DnsAll"). Microsoft does not publish what n/a means, so the
          Detail says no more than that.
        A missing value is never a Pass.
    .OUTPUTS
        [pscustomobject] Status, Detail, Cell, Evidence.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$Summary,
        [AllowNull()][AllowEmptyString()][string]$HostName = '',
        [Parameter(Mandatory)][string]$Token,
        [Parameter(Mandatory)][hashtable]$Config,
        [AllowNull()][AllowEmptyString()][string]$NotRunCause = '',
        [AllowNull()][AllowEmptyString()][string]$RunCause = '',
        [AllowNull()][AllowEmptyString()][string]$OverallStatus = '',
        [AllowNull()][AllowEmptyString()][string]$OverallEvidence = ''
    )
    $na = $script:Status.NotAssessed
    $out = [pscustomobject]@{ Status = $na; Detail = ''; Cell = ''; Evidence = '' }
    $ds = Get-AdfaConfigValue -Entry $Config -Name 'DnsSummary'
    $cat = @(@(Get-AdfaConfigValue -Entry $ds -Name 'Categories') | Where-Object { $null -ne $_ -and [string](Get-AdfaConfigValue -Entry $_ -Name 'Token') -eq $Token })
    if ($cat.Count -ne 1) {
        $out.Detail = ("{0}: NOT ASSESSED - the DNS summary table of this build has no test group {0}." -f $Token)
        return $out
    }
    $entry = $cat[0]
    $tok = [string](Get-AdfaConfigValue -Entry $entry -Name 'Token')
    $label = ("{0} ({1})" -f $tok, [string](Get-AdfaConfigValue -Entry $entry -Name 'Name'))
    $learn = ([string](Get-AdfaConfigValue -Entry $entry -Name 'Learn')).TrimEnd('.')
    if (-not [string]::IsNullOrWhiteSpace($NotRunCause)) {
        $out.Detail = ("{0}: NOT ASSESSED - {1}" -f $label, $NotRunCause.Trim())
        return $out
    }
    $found = $false
    if ($null -ne $Summary) {
        $hp = $Summary.PSObject.Properties['HeaderFound']
        if ($null -ne $hp -and [bool]$hp.Value) { $found = $true }
    }
    if (-not $found) {
        if (-not [string]::IsNullOrWhiteSpace($RunCause)) {
            $out.Detail = ("{0}: NOT ASSESSED - no DNS summary table was found in dcdiag's output, so this test group was not graded. {1}" -f $label, $RunCause.Trim())
        }
        elseif ($OverallStatus -eq $script:Status.Pass -or $OverallStatus -eq $script:Status.Fail) {
            $out.Detail = ("{0}: NOT ASSESSED - dcdiag's overall verdict for its DNS test on this domain controller was {1} ('{2}'), but no DNS summary table (a header made of the column tokens Auth Basc Forw Del Dyn RReg Ext) was found in the output, so this test group was not graded. The overall verdict is the grid's DCDIAG_DNS cell." -f $label, $OverallStatus, $OverallEvidence.Trim())
        }
        else {
            $out.Detail = ("{0}: NOT ASSESSED - no DNS summary table was read for this domain controller, and no cause was recorded, so this test group was not graded." -f $label)
        }
        return $out
    }
    $headerLine = [string]$Summary.HeaderLine
    $out.Evidence = $headerLine
    $tail = ''
    if (-not [string]::IsNullOrWhiteSpace($RunCause)) { $tail = (" {0}" -f $RunCause.Trim()) }
    $allRows = @(@($Summary.Rows) | Where-Object { $null -ne $_ })
    $mine = @($allRows | Where-Object { Test-AdfaDcdiagSubject -Subject ([string]$_.Name) -HostName $HostName })
    if ($mine.Count -eq 0) {
        $names = @($allRows | ForEach-Object { [string]$_.Name } | Select-Object -Unique)
        $list = '(none)'
        if ($names.Count -gt 0) { $list = $names -join ', ' }
        $out.Detail = ("{0}: NOT ASSESSED - the DNS summary table dcdiag printed has no row for this domain controller (looked for its host name, its first label and its 15-character NetBIOS form). Rows found: {1}.{2}" -f $label, $list, $tail)
        return $out
    }
    if ($mine.Count -gt 1) {
        $out.Evidence = ("{0} / {1}" -f $headerLine, (@($mine | ForEach-Object { [string]$_.Line }) -join ' / '))
        $out.Detail = ("{0}: NOT ASSESSED - the DNS summary table has {1} rows naming this domain controller, so which one is its own is not known." -f $label, $mine.Count)
        return $out
    }
    $row = $mine[0]
    $out.Evidence = ("{0} / {1}" -f $headerLine, [string]$row.Line)
    $columns = @($Summary.Columns)
    $col = -1
    for ($c = 0; $c -lt $columns.Count; $c++) { if ([string]$columns[$c] -eq $tok) { $col = $c; break } }
    if ($col -lt 0) {
        $out.Detail = ("{0}: NOT ASSESSED - the summary table's header ('{1}') has no {2} column, so this test group was not reported." -f $label, $headerLine, $tok)
        return $out
    }
    if (-not [bool]$row.Recognised) {
        $out.Detail = ("{0}: NOT ASSESSED - row not recognised: the row for this domain controller has {1} cell(s) and the header {2} column(s), so its cells cannot be matched to the columns." -f $label, [int]$row.CellCount, $columns.Count)
        return $out
    }
    $cell = [string]@($row.Cells)[$col]
    $out.Cell = $cell
    $map = @(@(Get-AdfaConfigValue -Entry $ds -Name 'Cells') | Where-Object { $null -ne $_ -and [string](Get-AdfaConfigValue -Entry $_ -Name 'Token') -eq $cell })
    $read = @(@(Get-AdfaConfigValue -Entry $ds -Name 'Cells') | Where-Object { $null -ne $_ } | ForEach-Object { [string](Get-AdfaConfigValue -Entry $_ -Name 'Token') })
    if ($map.Count -ne 1) {
        $out.Detail = ("{0}: NOT ASSESSED - cell value '{1}' under {2} is not one this build reads ({3}), so this test group was not graded. A localised dcdiag would print other values." -f $label, $cell, $tok, ($read -join ', '))
        return $out
    }
    $status = [string](Get-AdfaConfigValue -Entry $map[0] -Name 'Status')
    $isNa = ([string](Get-AdfaConfigValue -Entry $map[0] -Name 'Token') -eq 'n/a')
    $naStatus = [string](Get-AdfaConfigValue -Entry $entry -Name 'NaStatus')
    if ($isNa -and $naStatus -ne '') { $status = $naStatus }
    $allowed = @($script:Status.Pass, $script:Status.Warning, $script:Status.Fail, $na, $script:Status.Info)
    if ($allowed -notcontains $status) {
        $out.Detail = ("{0}: NOT ASSESSED - the config table maps '{1}' to '{2}', which is not a status this tool reports." -f $label, $cell, $status)
        return $out
    }
    $resultNote = [string](Get-AdfaConfigValue -Entry $entry -Name 'ResultNote')
    $who = $HostName
    if ([string]::IsNullOrWhiteSpace($who)) { $who = 'this domain controller' }
    if ($isNa) {
        if ($status -eq $na) {
            $out.Detail = ("{0}: NOT ASSESSED - dcdiag printed n/a, and Microsoft does not publish what n/a means in this table, so nothing is known about this test group on this domain controller." -f $label)
        }
        else {
            $out.Detail = ("{0}: dcdiag printed n/a - {1}." -f $label, ([string](Get-AdfaConfigValue -Entry $entry -Name 'NaMeaning')).TrimEnd('.'))
        }
        $out.Status = $status
        return $out
    }
    $out.Status = $status
    $out.Detail = ("{0}: dcdiag's DNS test against {1} printed {2} for this test group. Microsoft: {3}." -f $label, $who, $cell, $learn)
    if ($status -eq $script:Status.Warning) {
        $out.Detail = ("{0} Microsoft notes that the summary and detailed sections of dcdiag may report warnings for DNS configurations that are currently functional (archived Windows Server 2003 SP1 dcdiag page). The WARN value is read from Learn's prose; no published sample shows it." -f $out.Detail)
    }
    if (($status -eq $script:Status.Fail -or $status -eq $script:Status.Warning) -and $resultNote -ne '') {
        $out.Detail = ("{0} {1}" -f $out.Detail, $resultNote)
    }
    return $out
}

function Resolve-AdfaDcdiagDnsRollup {
    <#
    .SYNOPSIS
        Pure roll-up of one test group of dcdiag's DNS summary over the DCs of one domain.
    .DESCRIPTION
        The declared population is every DC of the domain in the section's list: each one is passed
        in, with the status its own row got (Resolve-AdfaDcdiagDnsCategory), and counted. Fail if any
        DC failed; otherwise Warning if any warned; otherwise Not Assessed if any DC was not assessed
        or carries a status this roll-up does not read (empty, null or anything outside Pass,
        Warning, Fail, Not Assessed and Info: counted and named, never dropped, because one unread
        DC means the domain is not known to be clean); otherwise Pass if any passed; otherwise Info
        (every cell was Info). No DC at all is Not Assessed.
    .OUTPUTS
        [pscustomobject] Status, Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        # One object per DC of the domain: HostName, Status.
        [AllowNull()][AllowEmptyCollection()]$Cells = @(),
        [Parameter(Mandatory)][string]$Token
    )
    $na = $script:Status.NotAssessed
    $all = @(@($Cells) | Where-Object { $null -ne $_ })
    if ($all.Count -eq 0) {
        return [pscustomobject]@{ Status = $na
            Detail = ("No domain controller of this domain is in this section's list, so no {0} result of dcdiag's DNS summary was read for it. This is not a clean result." -f $Token) }
    }
    $pick = { param([string]$S) @($all | Where-Object { [string]$_.Status -eq $S }) }
    $p = @(& $pick $script:Status.Pass)
    $w = @(& $pick $script:Status.Warning)
    $f = @(& $pick $script:Status.Fail)
    $n = @(& $pick $na)
    $i = @(& $pick $script:Status.Info)
    # Fail closed: a cell whose status is none of the five above is counted here, never dropped.
    $known = @($script:Status.Pass, $script:Status.Warning, $script:Status.Fail, $na, $script:Status.Info)
    $u = @($all | Where-Object { $known -notcontains [string]$_.Status })
    $status = $script:Status.Info
    if ($f.Count -gt 0) { $status = $script:Status.Fail }
    elseif ($w.Count -gt 0) { $status = $script:Status.Warning }
    elseif ($n.Count -gt 0 -or $u.Count -gt 0) { $status = $na }
    elseif ($p.Count -gt 0) { $status = $script:Status.Pass }
    $detail = ("{0} domain controller(s) of this domain (every one in this section's list), {1} column: {2} Pass, {3} Warning, {4} Fail, {5} Not Assessed, {6} Info." -f $all.Count, $Token, $p.Count, $w.Count, $f.Count, $n.Count, $i.Count)
    $names = { param($Set) (@($Set | ForEach-Object { [string]$_.HostName }) -join ', ') }
    if ($u.Count -gt 0) { $detail = ("{0} {1} with a status this roll-up does not read, so not assessed: {2}." -f $detail, $u.Count, (& $names $u)) }
    if ($f.Count -gt 0) { $detail = ("{0} Failed on: {1}." -f $detail, (& $names $f)) }
    if ($w.Count -gt 0) { $detail = ("{0} Warned on: {1}." -f $detail, (& $names $w)) }
    if ($n.Count -gt 0) { $detail = ("{0} Not assessed on: {1}; see each one's row for why." -f $detail, (& $names $n)) }
    return [pscustomobject]@{ Status = $status; Detail = $detail }
}

function Select-AdfaDcdiagTarget {
    <#
    .SYNOPSIS
        Pure: the domain controller a once-per-domain, -forest or -site dcdiag test is run against.
    .DESCRIPTION
        Only a DC that is usable - reachable on RPC/135, dcdiag present, and its own Connectivity
        test not failed - and not known to be read-only. In order: Connectivity passed and known
        writable; Connectivity passed and writability unknown (no DC inventory in this run); then
        the same two with Connectivity not assessed. Read-only DCs are never chosen: the reference
        runs these tests against a writable DC, and Learn does not say what they report on a
        read-only one. $null when none qualifies.
    .OUTPUTS
        [pscustomobject] the chosen state, or $null.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][AllowEmptyCollection()]$States = @())
    $usable = @(@($States) | Where-Object { $null -ne $_ -and [bool]$_.Usable })
    $pass = $script:Status.Pass
    $ranked = @(
        @($usable | Where-Object { [string]$_.Connectivity -eq $pass -and $_.IsReadOnly -is [bool] -and -not $_.IsReadOnly })
        @($usable | Where-Object { [string]$_.Connectivity -eq $pass -and $null -eq $_.IsReadOnly })
        @($usable | Where-Object { [string]$_.Connectivity -ne $pass -and $_.IsReadOnly -is [bool] -and -not $_.IsReadOnly })
        @($usable | Where-Object { [string]$_.Connectivity -ne $pass -and $null -eq $_.IsReadOnly })
    )
    if ($ranked.Count -eq 0) { return $null }
    return $ranked[0]
}

function Invoke-AdfaDcdiagScopedTest {
    <#
    .SYNOPSIS
        Runs one once-per-domain, -forest or -site dcdiag test against the chosen DC and grades it
        in Scope mode. Never throws.
    .OUTPUTS
        [pscustomobject] Run (Invoke-AdfaDcdiagTest), Verdict (Resolve-AdfaDcdiagVerdict).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$TestName,
        [Parameter(Mandatory)][string]$DomainController,
        [Parameter(Mandatory)][hashtable]$Config,
        [int]$TimeoutSeconds = 90,
        [int]$Retries = 2,
        [int]$RetryDelaySeconds = 2
    )
    $run = Invoke-AdfaDcdiagTest -TestName $TestName -DomainController $DomainController -TimeoutSeconds $TimeoutSeconds -Retries $Retries -RetryDelaySeconds $RetryDelaySeconds
    $parsed = ConvertFrom-AdfaDcdiagOutput -StdOut $run.StdOut -Config $Config
    $verdict = Resolve-AdfaDcdiagVerdict -Parsed $parsed -TestName $TestName -Mode 'Scope' -HostName $DomainController -Success ([bool]$run.Success) `
        -ExitCode $run.ExitCode -ErrorText ([string]$run.Error) -StdOut ([string]$run.StdOut)
    return [pscustomobject]@{ Run = $run; Verdict = $verdict }
}

function Get-AdfaDcdiagScopedDetail {
    <#
    .SYNOPSIS
        Pure: the Detail of a once-per-domain, -forest or -site dcdiag row, from its verdict.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$TestName,
        [Parameter(Mandatory)][string]$DomainController,
        [Parameter(Mandatory)]$Verdict,
        [AllowNull()]$IsReadOnly = $null
    )
    $parts = @($Verdict.Parts)
    $names = @($parts | ForEach-Object {
            $label = [string]$_.ScopeName
            if ([string]$_.ScopeKind -notmatch '^(Partition|Enterprise)$' -or $label -eq '') { $label = [string]$_.Subject }
            if ($label -eq '') { $label = '(no subject)' }
            $label
        })
    $failedNames = @($parts | Where-Object { [string]$_.Verdict -eq 'Fail' } | ForEach-Object {
            $label = [string]$_.ScopeName
            if ([string]$_.ScopeKind -notmatch '^(Partition|Enterprise)$' -or $label -eq '') { $label = [string]$_.Subject }
            if ($label -eq '') { $label = '(no subject)' }
            $label
        })
    $writable = ''
    if ($null -eq $IsReadOnly) { $writable = (" Whether {0} is writable is not known: the DC inventory was not collected in this run." -f $DomainController) }
    if ([string]$Verdict.Status -eq $script:Status.Pass) {
        return ("dcdiag /test:{0} /s:{1} reported passed for {2} part(s): {3}.{4}" -f $TestName, $DomainController, $parts.Count, ($names -join ', '), $writable)
    }
    if ([string]$Verdict.Status -eq $script:Status.Fail) {
        return ("dcdiag /test:{0} /s:{1} reported failed for {2} of {3} part(s): {4}. {5}{6}" -f $TestName, $DomainController, $failedNames.Count, $parts.Count, ($failedNames -join ', '), [string]$Verdict.Detail, $writable)
    }
    return ("Run against {0}. {1}{2}" -f $DomainController, [string]$Verdict.Detail, $writable)
}

function Get-AdfaDcDiagnostic {
    <#
    .SYNOPSIS
        dcdiag, parsed: a grid of per-DC tests, Topology once per scoped domain, CheckSDRefDom and
        CrossRefValidation once per forest with one row per partition, Intersite once per site
        (opt-in), and a coverage row per scoped domain.
    .DESCRIPTION
        Runs "dcdiag /test:<name> /s:<server>" through Invoke-AdfaDcdiagTest, one test per
        invocation, and grades each from its output (ConvertFrom-AdfaDcdiagOutput,
        Resolve-AdfaDcdiagVerdict). The tests, their scope and the parser's anchors are the DcDiag
        config table; the tests Microsoft documents as changing state ($script:Config.
        DcdiagActiveTests: DNS, Intersite, SystemLog) run only with -IncludeActiveTests.

        Per DC (one grid row each, carrying its domain as Scope): probed on RPC/135 through the
        per-run cache (Test-AdfaDcPort); closed -> every cell Not Assessed and nothing run; dcdiag
        absent -> every cell Not Assessed. Connectivity runs first; when it fails, no further
        test is started on that DC and every remaining cell is Not Assessed; the row's NotRun
        column names them and Connectivity (not Failures, which the recommendation is chosen from).
        A cell is Pass, Fail or Not Assessed with its cause in Failures. The row is Fail when a
        cell failed, Not Assessed when no attempted cell could be read, Warning when some could
        not, Pass otherwise; a held-back cell is explained in NotRun and does not lower the row.

        Per scoped domain: Topology against a usable writable DC of the domain
        (Select-AdfaDcdiagTarget). Per forest: CheckSDRefDom and CrossRefValidation once each,
        against a DC of the forest root domain if one is usable, else any; one row per part dcdiag
        printed (a partition) and a roll-up row. Per site that holds a DC, with
        -IncludeActiveTests: Intersite /a; a DC whose site is not known gets a "site unknown" row.
        LocatorCheck is never run (not in Learn's known-tests table) and has a row saying so.

        DNS summary (PORT-PLAN C12), with -IncludeActiveTests: the summary table of each DC's DNS
        run is parsed from the same output (ConvertFrom-AdfaDcdiagDnsSummary) and graded per test
        group (Resolve-AdfaDcdiagDnsCategory), and each domain is rolled up per group
        (Resolve-AdfaDcdiagDnsRollup). A DC that was unreachable, had no dcdiag, failed
        Connectivity or has no host name gets that cause in every group; a run that printed no
        table gets C11's cause (access denied, did not complete or timed out, not recognised, ...).

        DECLARED POPULATIONS. DCs: every target gets exactly one grid row and, with the opt-in, one
        "dcdiag DNS <group>: <host>" row per DNS test group (seven). Domains: every name in
        -ScopedDomains gets one "dcdiag Topology: <domain>" row and one "dcdiag coverage: <domain>"
        row - Info with the counts of its DCs' grid rows, or Not Assessed when no DC row accounts
        for the domain (Get-AdfaDcPopulationGap) - and, with the opt-in, one "dcdiag DNS <group>:
        domain <domain>" row per group over every DC of the domain, or one "dcdiag DNS not run:
        <domain>" row without it. Forest: one roll-up row per forest test. Sites: one row per site
        holding a DC, with the opt-in; one "not run" row without it.
    .OUTPUTS
        [pscustomobject[]] Grid rows and scoped rows (New-AdfaDcDiagRow).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # Inventory rows (HostName, Scope, Site, IsReadOnly), (Scope, HostName) rows from
        # Get-AdfaDcTargetsByDomain, or plain host names, which carry no domain or site.
        # AllowEmptyCollection: when DC enumeration fails the caller passes an empty list, and the
        # section reports itself unassessed rather than failing to bind.
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$DomainControllers,
        # Also run the tests listed in $script:Config.DcdiagActiveTests, which Microsoft documents
        # as changing state on the DC or in DNS. Off unless asked for.
        [switch]$IncludeActiveTests,
        [int]$TimeoutSeconds = 90,
        [int]$Retries = 2,
        [int]$RetryDelaySeconds = 2,
        [int]$RpcPortTimeoutMs = 1200,
        # The DcDiag table: the built-in one, or the one -ConfigOverridePath supplied.
        [AllowNull()][hashtable]$Config = $null,
        # Domains whose DC enumeration threw: objects with Domain and Error.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        # Why no DC could be enumerated at all, where the caller knows.
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        # The domains this run was scoped to: the declared population of the domain rows.
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @(),
        # The forest root domain's DNS name: whose DCs the forest tests are asked first.
        [AllowNull()][AllowEmptyString()][string]$ForestRoot = ''
    )
    if ($null -eq $Config) { $Config = $script:Config.DcDiag }
    $na = $script:Status.NotAssessed
    $timeout = $TimeoutSeconds
    $configuredTimeout = Get-AdfaConfigValue -Entry $Config -Name 'TestTimeoutSeconds'
    if ($null -ne $configuredTimeout) { $timeout = [int]$configuredTimeout }
    $tries = $Retries
    $configuredRetries = Get-AdfaConfigValue -Entry $Config -Name 'Retries'
    if ($null -ne $configuredRetries) { $tries = [int]$configuredRetries }
    $timeoutSource = [string](Get-AdfaConfigValue -Entry $Config -Name 'TimeoutSource')
    if ($timeoutSource -eq '') { $timeoutSource = 'tool default, not a Microsoft value' }
    $perDc = @(@(Get-AdfaConfigValue -Entry $Config -Name 'PerDcTests') | Where-Object { $null -ne $_ })
    $testNames = @($perDc | ForEach-Object { [string](Get-AdfaConfigValue -Entry $_ -Name 'Test') })

    # Tests held back unless asked for, and the sentence that explains each held-back cell.
    $active = @($script:Config.DcdiagActiveTests)
    $heldBack = @()
    $heldBackWhy = @()
    if (-not $IncludeActiveTests) {
        foreach ($entry in $active) {
            if ($testNames -contains [string]$entry.Test) {
                $heldBack += [string]$entry.Test
                $heldBackWhy += ("{0} ({1})" -f [string]$entry.Test, [string]$entry.Effect)
            }
        }
    }
    $heldBackNote = ''
    if ($heldBack.Count -gt 0) {
        $heldBackNote = ("Not run by default, so not assessed: {0}. Microsoft documents these dcdiag tests as changing state. -IncludeDcdiagActiveTests runs them." -f ($heldBackWhy -join '; '))
    }
    $haveDcdiag = Test-CommandAvailable -Name 'dcdiag.exe'
    $rows = New-Object System.Collections.ArrayList
    $states = New-Object System.Collections.ArrayList
    $targets = @(@($DomainControllers) | Where-Object { $null -ne $_ })
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        [void]$rows.Add((New-AdfaDcDiagRow -Item 'dcdiag grid' -Status $na `
                    -Detail ("No domain controllers were enumerated, so no dcdiag test could be run.{0} This is not a clean result." -f $why)))
    }

    # ---- Per DC: the grid ----
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        $site = ''
        $readOnly = $null
        if ($target -isnot [string]) {
            $siteProp = $target.PSObject.Properties['Site']
            if ($null -ne $siteProp -and $null -ne $siteProp.Value) { $site = ([string]$siteProp.Value).Trim() }
            $readOnlyProp = $target.PSObject.Properties['IsReadOnly']
            if ($null -ne $readOnlyProp -and $readOnlyProp.Value -is [bool]) { $readOnly = [bool]$readOnlyProp.Value }
        }
        # Dns*: what the DNS summary rows of this DC are graded from (PORT-PLAN C12): a cause that
        # stopped the test, or the run's own cause, overall verdict and parsed summary table.
        $state = [pscustomobject]@{ HostName = $dc; Scope = $scope; Site = $site; IsReadOnly = $readOnly; Usable = $false; Connectivity = $na; Status = $na
            DnsCause = ''; DnsRunCause = ''; DnsOverall = ''; DnsOverallLine = ''; DnsSummary = $null }
        [void]$states.Add($state)
        $row = [ordered]@{ DomainController = $dc; Scope = $scope; Status = $null; Ping = $null }
        foreach ($t in $testNames) { $row["DCDIAG_$t"] = $na }
        $row.Failures = ''
        # Why the held-back cells of THIS row read Not Assessed. Its own column, not Failures:
        # nothing failed, and Failures is the text the recommendation is chosen from. Filled in
        # only for a DC that dcdiag was actually run against; an unreachable DC has its own cause.
        $row.NotRun = ''

        if ([string]::IsNullOrWhiteSpace($dc)) {
            $row.DomainController = '(unnamed)'
            $row.Ping = $na
            $row.Status = $na
            $row.Failures = 'The inventory holds a domain controller with no host name, so dcdiag could not be run against it.'
            $state.DnsCause = 'the inventory holds this domain controller with no host name, so dcdiag could not be run against it.'
            [void]$rows.Add([pscustomobject]$row)
            continue
        }
        # PORT-PLAN C14c: a DC classified Unreachable is not probed again; its row and its DNS
        # rows carry that class. The grid row stays Fail, as for a DC silent on RPC (C11g(1)).
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135) -TimeoutMs $RpcPortTimeoutMs
        $reachable = [bool]$gate.Open[135]
        $row.Ping = $(if ($reachable) { $script:Status.Pass } else { $script:Status.Fail })
        if (-not $reachable) {
            $row.Status = $script:Status.Fail
            $row.Failures = 'DC not reachable (RPC/135) - no dcdiag tests run.'
            $state.DnsCause = 'unreachable: the domain controller did not answer on RPC/135, so dcdiag was not run against it.'
            if ($gate.Cause) {
                $row.Failures = ("DC not reachable - no dcdiag tests run. {0}" -f (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'it was not probed again'))
                $state.DnsCause = (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'dcdiag was not run against it')
            }
            $state.Status = $row.Status
            [void]$rows.Add([pscustomobject]$row)
            continue
        }
        if (-not $haveDcdiag) {
            $row.Status = $na
            $row.Failures = 'dcdiag.exe not available on this host.'
            $state.DnsCause = 'dcdiag.exe is not available on this host, so the DNS test was not run.'
            [void]$rows.Add([pscustomobject]$row)
            continue
        }

        $failDetails = New-Object System.Collections.Generic.List[string]
        $skipped = New-Object System.Collections.Generic.List[string]
        $gated = $false
        foreach ($entry in $perDc) {
            $t = [string](Get-AdfaConfigValue -Entry $entry -Name 'Test')
            # Decided, not attempted: dcdiag is not invoked for a held-back test at all.
            if ($heldBack -contains $t) { continue }
            if ($gated) { $skipped.Add($t); continue }
            $run = Invoke-AdfaDcdiagTest -TestName $t -DomainController $dc -TimeoutSeconds $timeout -Retries $tries -RetryDelaySeconds $RetryDelaySeconds
            $parsed = ConvertFrom-AdfaDcdiagOutput -StdOut $run.StdOut -Config $Config
            $verdict = Resolve-AdfaDcdiagVerdict -Parsed $parsed -TestName $t -Mode 'Dc' -HostName $dc `
                -PartitionParts ([bool](Get-AdfaConfigValue -Entry $entry -Name 'PartitionParts')) -EnterpriseParts ([bool](Get-AdfaConfigValue -Entry $entry -Name 'EnterpriseParts')) -EventLog ([bool](Get-AdfaConfigValue -Entry $entry -Name 'EventLog')) `
                -Success ([bool]$run.Success) -ExitCode $run.ExitCode -ErrorText ([string]$run.Error) -StdOut ([string]$run.StdOut)
            $row["DCDIAG_$t"] = [string]$verdict.Status
            $detail = [string]$verdict.Detail
            if ([string]$verdict.Status -eq $na -and -not [bool]$run.Success -and [string]$run.Error -match '(?i)time.?out') {
                $detail = ("{0} The time-out for one dcdiag invocation was {1} s ({2})." -f $detail, $timeout, $timeoutSource)
            }
            if ($t -eq 'DNS') {
                # PORT-PLAN C12: the summary table is read from this same output; no new invocation.
                $state.DnsSummary = ConvertFrom-AdfaDcdiagDnsSummary -StdOut ([string]$run.StdOut) -Config $Config
                $state.DnsOverall = [string]$verdict.Status
                $state.DnsOverallLine = (@($verdict.Parts | ForEach-Object { [string]$_.Line }) -join ' / ')
                if ([string]$verdict.Status -eq $na) { $state.DnsRunCause = $detail }
            }
            if ($t -eq 'Connectivity') {
                $state.Connectivity = [string]$verdict.Status
                if ([string]$verdict.Status -eq $script:Status.Fail) {
                    $gated = $true
                    $detail = ("{0} (dcdiag's connectivity checks include an ICMP ping, and Microsoft documents that blocking ICMP prevents DCDiag from functioning as intended, so a DC that drops ping can fail this test.)" -f $detail)
                }
            }
            if (-not [string]::IsNullOrWhiteSpace($detail)) { $failDetails.Add($detail) }
        }
        # The tests not started after a failed Connectivity go in NotRun, not Failures: they did not
        # fail, and their names ("Replications", "SysVolCheck", ...) would otherwise choose the
        # replication or SYSVOL advice for a DC whose fault is Connectivity (independent review).
        $notRunNotes = New-Object System.Collections.Generic.List[string]
        if ($skipped.Count -gt 0) {
            $notRunNotes.Add(("Not run after Connectivity failed: {0}. dcdiag runs its Connectivity test first in every invocation and Microsoft documents that it can't be skipped, so no further dcdiag test was started on this DC; nothing is known about these tests here." -f ($skipped -join ', ')))
        }
        if ($skipped -contains 'DNS') {
            $state.DnsCause = "not run after dcdiag's Connectivity test failed on this domain controller: no further dcdiag test was started on it."
        }
        if ($heldBackNote -ne '') { $notRunNotes.Add($heldBackNote) }

        # The row's status is taken from the tests that were ATTEMPTED. A held-back test is a
        # decision, not a failed measurement: counting it would make every DC a Warning in every
        # default run and bury the DCs with a test that really could not be read. Its cell still
        # reads Not Assessed, and the row's NotRun column carries the reason.
        $cells = @(foreach ($t in $testNames) { if ($heldBack -notcontains $t) { $row["DCDIAG_$t"] } })
        if ($cells -contains $script:Status.Fail) { $row.Status = $script:Status.Fail }
        elseif (@($cells | Where-Object { $_ -ne $na }).Count -eq 0) { $row.Status = $na }
        elseif ($cells -contains $na) { $row.Status = $script:Status.Warning }
        else { $row.Status = $script:Status.Pass }
        $row.NotRun = $notRunNotes -join ' | '
        $row.Failures = $failDetails -join ' | '
        $state.Status = $row.Status
        $state.Usable = ($state.Connectivity -ne $script:Status.Fail)
        [void]$rows.Add([pscustomobject]$row)
    }
    $allStates = @($states.ToArray())

    # ---- Per scoped domain: Topology ----
    $domains = New-Object System.Collections.ArrayList
    foreach ($name in @(@($ScopedDomains) + @($allStates | ForEach-Object { [string]$_.Scope }))) {
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        if (@($domains | Where-Object { $_ -eq $name.Trim() }).Count -eq 0) { [void]$domains.Add($name.Trim()) }
    }
    $noDcdiag = 'dcdiag.exe is not available on this host, so this test was not run. This is not a clean result.'
    foreach ($test in @(@(Get-AdfaConfigValue -Entry $Config -Name 'DomainTests') | Where-Object { $null -ne $_ })) {
        $t = [string](Get-AdfaConfigValue -Entry $test -Name 'Test')
        if ($domains.Count -eq 0) {
            [void]$rows.Add((New-AdfaDcDiagRow -Item ("dcdiag {0}: (no domain known)" -f $t) -Status $na `
                        -Detail ("No scoped domain was given to this section and no domain controller carries its domain, so dcdiag /test:{0}, which runs once per domain, was not run. This is not a clean result." -f $t)))
            continue
        }
        foreach ($domain in $domains) {
            $item = ("dcdiag {0}: {1}" -f $t, $domain)
            if (-not $haveDcdiag) { [void]$rows.Add((New-AdfaDcDiagRow -Scope $domain -Item $item -Status $na -Detail $noDcdiag)); continue }
            $inDomain = @($allStates | Where-Object { [string]$_.Scope -eq $domain })
            $pick = Select-AdfaDcdiagTarget -States $inDomain
            if ($null -eq $pick) {
                $cause = ("No domain controller of this domain is in this section's list, so dcdiag /test:{0}, which runs once per domain, was not run. This is not a clean result." -f $t)
                if ($inDomain.Count -gt 0) {
                    $cause = ("None of the {0} domain controller(s) of this domain in this section could run it: each was unreachable on RPC/135, failed dcdiag's Connectivity test, or is read-only. dcdiag /test:{1} was not run, which is not a clean result." -f $inDomain.Count, $t)
                }
                [void]$rows.Add((New-AdfaDcDiagRow -Scope $domain -Item $item -Status $na -Detail $cause))
                continue
            }
            $res = Invoke-AdfaDcdiagScopedTest -TestName $t -DomainController ([string]$pick.HostName) -Config $Config -TimeoutSeconds $timeout -Retries $tries -RetryDelaySeconds $RetryDelaySeconds
            [void]$rows.Add((New-AdfaDcDiagRow -Scope $domain -Item $item -Status ([string]$res.Verdict.Status) -Target ([string]$pick.HostName) `
                        -Detail (Get-AdfaDcdiagScopedDetail -TestName $t -DomainController ([string]$pick.HostName) -Verdict $res.Verdict -IsReadOnly $pick.IsReadOnly) `
                        -Evidence (@($res.Verdict.Parts | ForEach-Object { [string]$_.Line }) -join ' / ')))
        }
    }

    # ---- Per forest: CheckSDRefDom, CrossRefValidation, one row per part and a roll-up ----
    $forestScope = ([string]$ForestRoot).Trim()
    $forestLabel = $forestScope
    if ($forestLabel -eq '') { $forestLabel = '(root not read)' }
    $forestPick = Select-AdfaDcdiagTarget -States @($allStates | Where-Object { $forestLabel -ne '(root not read)' -and [string]$_.Scope -eq $forestLabel })
    if ($null -eq $forestPick) { $forestPick = Select-AdfaDcdiagTarget -States $allStates }
    foreach ($test in @(@(Get-AdfaConfigValue -Entry $Config -Name 'ForestTests') | Where-Object { $null -ne $_ })) {
        $t = [string](Get-AdfaConfigValue -Entry $test -Name 'Test')
        $rollItem = ("dcdiag {0}: forest {1}" -f $t, $forestLabel)
        if (-not $haveDcdiag) { [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item $rollItem -Status $na -Detail $noDcdiag)); continue }
        if ($null -eq $forestPick) {
            [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item $rollItem -Status $na `
                        -Detail ("No domain controller in this section could run it: each was unreachable on RPC/135, failed dcdiag's Connectivity test, or is read-only, or none was enumerated. dcdiag /test:{0}, which runs once per forest, was not run. This is not a clean result." -f $t)))
            continue
        }
        $host1 = [string]$forestPick.HostName
        $res = Invoke-AdfaDcdiagScopedTest -TestName $t -DomainController $host1 -Config $Config -TimeoutSeconds $timeout -Retries $tries -RetryDelaySeconds $RetryDelaySeconds
        foreach ($part in @($res.Verdict.Parts)) {
            $kind = [string]$part.ScopeKind
            $label = [string]$part.ScopeName
            if ($kind -notmatch '^(Partition|Enterprise)$' -or $label -eq '') { $label = [string]$part.Subject }
            if ($label -eq '') { $label = '(no subject)' }
            $kindWord = 'output'
            if ($kind -eq 'Partition') { $kindWord = 'partition' }
            elseif ($kind -eq 'Enterprise') { $kindWord = 'enterprise' }
            elseif ($kind -eq 'Server') { $kindWord = 'server' }
            $word = 'passed'
            if ([string]$part.Verdict -eq 'Fail') { $word = 'failed' }
            $partStatus = $script:Status.Pass
            if ([string]$part.Verdict -eq 'Fail') { $partStatus = $script:Status.Fail }
            [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item ("dcdiag {0}: {1}" -f $t, $label) -Status $partStatus -Target $host1 -Evidence ([string]$part.Line) `
                        -Detail ("dcdiag /test:{0} /s:{1} reported {2} for the {3} {4}." -f $t, $host1, $word, $kindWord, $label)))
        }
        [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item $rollItem -Status ([string]$res.Verdict.Status) -Target $host1 `
                    -Detail (Get-AdfaDcdiagScopedDetail -TestName $t -DomainController $host1 -Verdict $res.Verdict -IsReadOnly $forestPick.IsReadOnly) `
                    -Evidence (@($res.Verdict.Parts | ForEach-Object { [string]$_.Line }) -join ' / ')))
    }

    # ---- Per site: Intersite, opt-in ----
    foreach ($test in @(@(Get-AdfaConfigValue -Entry $Config -Name 'SiteTests') | Where-Object { $null -ne $_ })) {
        $t = [string](Get-AdfaConfigValue -Entry $test -Name 'Test')
        $activeEntry = @($active | Where-Object { [string]$_.Test -eq $t })
        if (-not $IncludeActiveTests -and $activeEntry.Count -gt 0) {
            [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item ("dcdiag {0}: not run" -f $t) -Status $na `
                        -NotRun ("Not run by default, so not assessed: {0} ({1}). Microsoft documents this dcdiag test as changing state. -IncludeDcdiagActiveTests runs it, once per site that holds a domain controller, with /a." -f $t, [string]$activeEntry[0].Effect)))
            continue
        }
        if (-not $haveDcdiag) { [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item ("dcdiag {0}: not run" -f $t) -Status $na -Detail $noDcdiag)); continue }
        $named = @($allStates | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.HostName) })
        $unknown = @($named | Where-Object { [string]$_.Site -eq '' })
        if ($unknown.Count -gt 0) {
            [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item ("dcdiag {0}: site unknown" -f $t) -Status $na `
                        -Detail ("The site of {0} domain controller(s) is not known ({1}): the DC inventory was not collected in this run, or gave no site. {2} runs once per site, so their sites were not tested unless another domain controller of the same site was. Name DomainControllers with DcDiagnostics." -f $unknown.Count, (@($unknown | ForEach-Object { [string]$_.HostName }) -join ', '), $t)))
        }
        $sites = @($named | Where-Object { [string]$_.Site -ne '' } | ForEach-Object { [string]$_.Site } | Sort-Object -Unique)
        if ($sites.Count -eq 0 -and $unknown.Count -eq 0) {
            [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item ("dcdiag {0}: no site" -f $t) -Status $na `
                        -Detail ("No domain controller was enumerated, so no site was tested with dcdiag /test:{0}. This is not a clean result." -f $t)))
        }
        foreach ($siteName in $sites) {
            $item = ("dcdiag {0}: {1}" -f $t, $siteName)
            $inSite = @($named | Where-Object { [string]$_.Site -eq $siteName })
            $pick = Select-AdfaDcdiagTarget -States $inSite
            if ($null -eq $pick) {
                [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item $item -Status $na `
                            -Detail ("This site holds {0} domain controller(s) in this section, and none could run dcdiag: each was unreachable on RPC/135, failed dcdiag's Connectivity test, or is read-only. dcdiag /test:{1} was not run for this site, which is not a clean result." -f $inSite.Count, $t)))
                continue
            }
            $res = Invoke-AdfaDcdiagScopedTest -TestName $t -DomainController ([string]$pick.HostName) -Config $Config -TimeoutSeconds $timeout -Retries $tries -RetryDelaySeconds $RetryDelaySeconds
            [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item $item -Status ([string]$res.Verdict.Status) -Target ([string]$pick.HostName) `
                        -Detail (Get-AdfaDcdiagScopedDetail -TestName $t -DomainController ([string]$pick.HostName) -Verdict $res.Verdict -IsReadOnly $pick.IsReadOnly) `
                        -Evidence (@($res.Verdict.Parts | ForEach-Object { [string]$_.Line }) -join ' / ')))
        }
    }

    # ---- Tests that are never run, for which the catalogue has a row ----
    foreach ($entry in @(@(Get-AdfaConfigValue -Entry $Config -Name 'NotAdded') | Where-Object { $null -ne $_ -and [bool](Get-AdfaConfigValue -Entry $_ -Name 'Report') })) {
        $t = [string](Get-AdfaConfigValue -Entry $entry -Name 'Test')
        [void]$rows.Add((New-AdfaDcDiagRow -Scope $forestScope -Item ("dcdiag {0}: not run" -f $t) -Status $na `
                    -NotRun ("Not run: {0} is {1}. This tool runs only dcdiag tests Microsoft documents. Not run is not a clean result." -f $t, [string](Get-AdfaConfigValue -Entry $entry -Name 'Why'))))
    }

    # ---- The DNS test's summary table: per DC and per domain, one row per test group (C12) ----
    # Read from the output of the DNS test the grid already ran; nothing more is invoked. Without the
    # opt-in, one "not run" row per domain says why (the C11 Intersite wording, in NotRun).
    if ($testNames -contains 'DNS') {
        $dnsSummaryConfig = Get-AdfaConfigValue -Entry $Config -Name 'DnsSummary'
        $dnsTokens = @(@(Get-AdfaConfigValue -Entry $dnsSummaryConfig -Name 'Categories') | Where-Object { $null -ne $_ } | ForEach-Object { [string](Get-AdfaConfigValue -Entry $_ -Name 'Token') })
        if ($heldBack -contains 'DNS') {
            $dnsActive = @($active | Where-Object { [string]$_.Test -eq 'DNS' })
            $dnsEffect = ''
            if ($dnsActive.Count -gt 0) { $dnsEffect = (" ({0})" -f [string]$dnsActive[0].Effect) }
            $dnsNotRun = ("Not run by default, so not assessed: DNS{0}. Microsoft documents this dcdiag test as changing state. -IncludeDcdiagActiveTests runs it on every domain controller, and its summary table is then graded per test group ({1}) for each domain controller and each domain." -f $dnsEffect, ($dnsTokens -join ', '))
            $dnsLabels = @($domains)
            if ($dnsLabels.Count -eq 0) { $dnsLabels = @('(no domain known)') }
            foreach ($d in $dnsLabels) {
                $dScope = $d
                if ($d -eq '(no domain known)') { $dScope = '' }
                [void]$rows.Add((New-AdfaDcDiagRow -Scope $dScope -Item ("dcdiag DNS not run: {0}" -f $d) -Status $na -NotRun $dnsNotRun))
            }
        }
        else {
            $dnsCells = New-Object System.Collections.ArrayList
            foreach ($st in $allStates) {
                $dnsHost = [string]$st.HostName
                if ([string]::IsNullOrWhiteSpace($dnsHost)) { $dnsHost = '(unnamed)' }
                foreach ($tok in $dnsTokens) {
                    $res = Resolve-AdfaDcdiagDnsCategory -Summary $st.DnsSummary -HostName ([string]$st.HostName) -Token $tok -Config $Config -NotRunCause ([string]$st.DnsCause) `
                        -RunCause ([string]$st.DnsRunCause) -OverallStatus ([string]$st.DnsOverall) -OverallEvidence ([string]$st.DnsOverallLine)
                    [void]$rows.Add((New-AdfaDcDiagRow -Scope ([string]$st.Scope) -Item ("dcdiag DNS {0}: {1}" -f $tok, $dnsHost) -Status ([string]$res.Status) `
                                -Detail ([string]$res.Detail) -Evidence ([string]$res.Evidence) -Target ([string]$st.HostName)))
                    [void]$dnsCells.Add([pscustomobject]@{ HostName = $dnsHost; Scope = ([string]$st.Scope).Trim(); Token = $tok; Status = [string]$res.Status })
                }
            }
            # Declared population of each roll-up: every DC of the domain in this section's list. A DC
            # whose domain is not known is rolled up under "(domain not known)", never dropped.
            $dnsGroups = @($domains)
            if (@($allStates | Where-Object { [string]::IsNullOrWhiteSpace([string]$_.Scope) }).Count -gt 0) { $dnsGroups += '(domain not known)' }
            if ($dnsGroups.Count -eq 0) {
                [void]$rows.Add((New-AdfaDcDiagRow -Item 'dcdiag DNS: (no domain known)' -Status $na `
                            -Detail 'No scoped domain was given to this section and no domain controller was enumerated, so no DNS summary table was read. This is not a clean result.'))
            }
            foreach ($d in $dnsGroups) {
                $dScope = $d
                if ($d -eq '(domain not known)') { $dScope = '' }
                foreach ($tok in $dnsTokens) {
                    $inGroup = @($dnsCells | Where-Object { $_.Scope -eq $dScope -and $_.Token -eq $tok })
                    $roll = Resolve-AdfaDcdiagDnsRollup -Cells $inGroup -Token $tok
                    [void]$rows.Add((New-AdfaDcDiagRow -Scope $dScope -Item ("dcdiag DNS {0}: domain {1}" -f $tok, $d) -Status ([string]$roll.Status) -Detail ([string]$roll.Detail)))
                }
            }
        }
    }

    # ---- Per scoped domain: coverage ----
    $population = New-Object System.Collections.ArrayList
    foreach ($name in @($ScopedDomains)) {
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        if (@($population | Where-Object { $_ -eq $name.Trim() }).Count -eq 0) { [void]$population.Add($name.Trim()) }
    }
    $gaps = @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains @($population))
    foreach ($gap in $gaps) {
        [void]$rows.Add((New-AdfaDcDiagRow -Scope ([string]$gap.Domain) -Item ("dcdiag coverage: {0}" -f [string]$gap.Domain) -Status $na `
                    -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No dcdiag test was run against its domain controllers.')))
    }
    foreach ($domain in $population) {
        if (@($gaps | Where-Object { [string]$_.Domain -eq $domain }).Count -gt 0) { continue }
        $inDomain = @($allStates | Where-Object { [string]$_.Scope -eq $domain })
        $count = { param([string]$Status) @($inDomain | Where-Object { [string]$_.Status -eq $Status }).Count }
        [void]$rows.Add((New-AdfaDcDiagRow -Scope $domain -Item ("dcdiag coverage: {0}" -f $domain) -Status $script:Status.Info `
                    -Detail ("{0} domain controller(s) of this domain have a grid row: {1} Pass, {2} Warning, {3} Fail, {4} Not Assessed." -f $inDomain.Count, (& $count $script:Status.Pass), (& $count $script:Status.Warning), (& $count $script:Status.Fail), (& $count $na))))
    }
    return @($rows.ToArray())
}

# ===========================================================================
# region DNS
# ===========================================================================

function Get-AdfaForwarderAddress {
    <#
    .SYNOPSIS
        Pure: extracts the forwarder IP list from a Get-DnsServerForwarder result, tolerating
        a DNS server that has none configured.
    .DESCRIPTION
        Fixes a defect found on the first live run (v1.11.0), where a DC with NO forwarders was
        reported as 'Not Assessed - You cannot call a method on a null-valued expression'. The
        previous code was:

            ($fwd.IPAddress | ForEach-Object { $_.ToString() }) -join ', '

        With no forwarders configured, IPAddress is $null. Piping $null into ForEach-Object
        still runs the block once with $_ = $null, and $null.ToString() throws under
        Set-StrictMode -Version Latest. The exception was caught upstream and turned into
        'Not Assessed', so a MEASURED ABSENCE was reported as a FAILED MEASUREMENT - the exact
        conflation this tool exists to prevent, running backwards.

        Returns an empty array for "none configured", so the caller can say so plainly. Every
        read is property-existence-checked, and null elements inside the collection are dropped
        rather than stringified into empty entries.
    .OUTPUTS
        [string[]] Zero or more forwarder addresses.
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param([AllowNull()]$Forwarder)
    $ips = @()
    foreach ($f in @($Forwarder | Where-Object { $null -ne $_ })) {
        # Load-bearing: when the property is absent this lookup returns $null, and reading
        # .Value off $null throws "The property 'Value' cannot be found on this object" under
        # Set-StrictMode -Version Latest. Measured, not assumed.
        $p = $f.PSObject.Properties['IPAddress']
        if ($null -eq $p) { continue }
        # @($null) is a one-element array holding $null, and [string]$null is '', so the
        # emptiness test below covers both "IPAddress is null" and "the collection holds a
        # null". Separate null checks here would be unreachable - and an unreachable guard
        # implies a coverage this function does not have.
        foreach ($ip in @($p.Value)) {
            $text = ([string]$ip).Trim()
            if ($text) { $ips += $text }
        }
    }
    return @($ips | Select-Object -Unique)
}

# ---------------------------------------------------------------------------
# DNS (PORT-PLAN C13): zone dynamic update and aging/scavenging per zone (DNS-001, DNS-002), zone
# inventory (INV-013), DC locator SRV records, DC A records and records that name no DC per DC
# (DNS-003..005, rows of DNS vs AD Consistency), each DC's DNS client settings (INV-016, rows of the
# DomainControllers section) and the opt-in record export (INV-014). Sources, read dates and the
# tool defaults are beside $script:Config.Dns. Every read here is a Get- cmdlet, Resolve-DnsName or
# a CIM instance query; nothing is written and no method is invoked.
# ---------------------------------------------------------------------------

function New-AdfaDnsRow {
    <#
    .SYNOPSIS
        Pure: one row of the DNS sections. Every row has the same columns, so a consumer never has
        to test whether a column exists.
    .DESCRIPTION
        Names, addresses and record data go in their own columns, never in Detail: the consolidated
        findings choose a recommendation from Detail, and none of these columns is read there. A
        value that was not measured is an empty string.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [string]$Area = 'DNS',
        [AllowEmptyString()][string]$NotRun = '',
        [AllowEmptyString()][string]$Evidence = '',
        [AllowEmptyString()][string]$Server = '',
        [AllowEmptyString()][string]$Zone = '',
        [AllowEmptyString()][string]$HostName = '',
        [AllowEmptyString()][string]$RecordName = '',
        [AllowEmptyString()][string]$RecordType = '',
        [AllowEmptyString()][string]$RecordData = '',
        [AllowEmptyString()][string]$ZoneType = '',
        [AllowEmptyString()][string]$ReplicationScope = '',
        [AllowEmptyString()][string]$DsIntegrated = '',
        [AllowEmptyString()][string]$DynamicUpdate = '',
        [AllowEmptyString()][string]$Aging = '',
        [AllowEmptyString()][string]$ConfiguredIPv4 = '',
        [AllowEmptyString()][string]$DnsServers = ''
    )
    $row = New-Finding -Scope $Scope -Area $Area -Item $Item -Status $Status -Detail $Detail
    $columns = [ordered]@{
        NotRun = $NotRun; Evidence = $Evidence; Server = $Server; Zone = $Zone; HostName = $HostName; RecordName = $RecordName
        RecordType = $RecordType; RecordData = $RecordData; ZoneType = $ZoneType; ReplicationScope = $ReplicationScope
        DsIntegrated = $DsIntegrated; DynamicUpdate = $DynamicUpdate; Aging = $Aging; ConfiguredIPv4 = $ConfiguredIPv4; DnsServers = $DnsServers
    }
    foreach ($k in @($columns.Keys)) { $row | Add-Member -NotePropertyName $k -NotePropertyValue ([string]$columns[$k]) }
    return $row
}

function ConvertTo-AdfaDnsBool {
    <#
    .SYNOPSIS
        Pure: $true or $false from a boolean or its text, $null for anything else - an absent or
        unreadable value is never read as $false.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [bool]) { return [bool]$Value }
    $text = ([string]$Value).Trim()
    if ($text -match '^(?i)true$') { return $true }
    if ($text -match '^(?i)false$') { return $false }
    return $null
}

function Test-AdfaDnsServerScavenges {
    <#
    .SYNOPSIS
        Pure: whether a DNS server's scavenging interval enables scavenging. $true above zero,
        $false at zero, $null when the value is not a time span this tool can read.
    .DESCRIPTION
        "ScavengingInterval determines whether the scavenging feature for the DNS server is enabled
        ... The default setting is 0, which disables scavenging" (Set-DnsServerScavenging, read
        2026-11-17). The parameter is a TimeSpan; text is read as a TimeSpan in the invariant
        culture. A bare number is NOT read: its unit is not published for the cmdlet's output (the
        WMI class counts hours), so guessing one could turn "off" into "on".
    #>
    [CmdletBinding()]
    param([AllowNull()]$Interval)
    if ($null -eq $Interval) { return $null }
    $span = $null
    if ($Interval -is [timespan]) { $span = [timespan]$Interval }
    elseif ($Interval -is [string]) {
        $parsed = [timespan]::Zero
        if ([timespan]::TryParse($Interval.Trim(), [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsed)) { $span = $parsed }
    }
    if ($null -eq $span) { return $null }
    return ($span -gt [timespan]::Zero)
}

function Get-AdfaDnsReadErrorClass {
    <#
    .SYNOPSIS
        Pure: the class of a DNS read failure - AccessDenied, NoProvider, Timeout, NotFound or Error.
    .DESCRIPTION
        Refusal first, by the CIM error code and then the text (Get-AdfaRemoteReadErrorClass). Then
        the DNS CIM provider missing (InvalidNamespace, InvalidClass - reference decision 60), a
        time-out (text only: NativeErrorCode has no time-out value, read 2026-11-17), and "no such
        record" (the config's NoRecordPattern: Win32 9701 or 9714, by number or exact text, provisional).
        Anything else is Error and is quoted, never interpreted - in particular it is never an
        absence: a CIM NotFound code does not say WHAT was not found, and a bare "was not found" is
        also how a transport failure reads ("The network path was not found.").
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Message,
        [AllowNull()][AllowEmptyString()][string]$ErrorCode,
        [Parameter(Mandatory)][hashtable]$Config
    )
    if ((Get-AdfaRemoteReadErrorClass -Message $Message -ErrorCode $ErrorCode) -eq 'AccessDenied') { return 'AccessDenied' }
    $code = ([string]$ErrorCode).Trim()
    if ($code -ne '' -and @($Config['NoProviderErrorCodes']) -contains $code) { return 'NoProvider' }
    $text = [string]$Message
    if ($text -match [string]$Config['TimeoutPattern']) { return 'Timeout' }
    if ($text -match [string]$Config['NoRecordPattern']) { return 'NotFound' }
    return 'Error'
}

function Get-AdfaDnsReadCause {
    <#
    .SYNOPSIS
        Pure: the fixed lead of a Not Assessed cause for one failed DNS read, then what was reported.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][string]$Class, [AllowNull()][AllowEmptyString()][string]$Message)
    $lead = switch ($Class) {
        'AccessDenied' { 'Access denied: the account running the assessment was refused by the DNS server.'; break }
        'NoProvider' { 'DNS provider did not answer: the DNS server management provider is not there (the DNS Server role may not be installed on this DC).'; break }
        'Timeout' { 'Timed out: the DNS server did not answer in time.'; break }
        'NotFound' { 'Not found: the DNS server reports no such object.'; break }
        default { 'Read failed: the DNS server answered with an error this tool does not interpret.' }
    }
    $said = ([string]$Message).Trim()
    if ($said -eq '') { return $lead }
    return ("{0} Reported: {1}" -f $lead, $said)
}

function Get-AdfaDnsServerRaw {
    <#
    .SYNOPSIS
        The one place DNS Health touches a DNS server: Get-DnsServerZone, Get-DnsServerScavenging,
        Get-DnsServerZoneAging per primary zone and Get-DnsServerForwarder, all with -ComputerName.
    .DESCRIPTION
        Read-only: Learn documents no side effect for any Get-DnsServer* cmdlet (absence of a
        statement, not a guarantee). The output property names are not published (config table),
        so every one is read by name and a property not returned is $null, never $false.

        Never throws. Ok is $false only when the zone list could not be read; a failed scavenging,
        aging or forwarder read is kept beside the zones so one half is not thrown away. Zone aging
        is read only for primary zones that were not auto-created (Learn: aging "is relevant only
        for DNS primary zones").
    .OUTPUTS
        [pscustomobject] Ok, Error, ErrorCode, Zones (ZoneName, ZoneType, IsAutoCreated,
        IsDsIntegrated, IsReverseLookupZone, DynamicUpdate, ReplicationScope, SecureSecondaries),
        ScavengingOk, ScavengingInterval, ScavengingState, ScavengingError, Aging (lower-case zone
        name -> Ok, AgingEnabled, NoRefreshInterval, RefreshInterval, ScavengeServers, Error),
        ForwardersOk, Forwarders, ForwarderError.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$ComputerName)
    $out = [pscustomobject]@{
        Ok = $false; Error = ''; ErrorCode = ''; Zones = @(); ScavengingOk = $false; ScavengingInterval = $null; ScavengingState = $null
        ScavengingError = ''; Aging = @{}; ForwardersOk = $false; Forwarders = @(); ForwarderError = ''
    }
    try {
        $list = New-Object System.Collections.ArrayList
        foreach ($z in @(Get-DnsServerZone -ComputerName $ComputerName -ErrorAction Stop)) {
            if ($null -eq $z) { continue }
            $text = { param($Name) $v = Get-AdfaCimRawValue -Instance $z -Name $Name; if ($null -eq $v) { return '' } return ([string]$v).Trim() }
            [void]$list.Add([pscustomobject]@{
                    ZoneName            = (& $text 'ZoneName')
                    ZoneType            = (& $text 'ZoneType')
                    IsAutoCreated       = (ConvertTo-AdfaDnsBool -Value (Get-AdfaCimRawValue -Instance $z -Name 'IsAutoCreated'))
                    IsDsIntegrated      = (ConvertTo-AdfaDnsBool -Value (Get-AdfaCimRawValue -Instance $z -Name 'IsDsIntegrated'))
                    IsReverseLookupZone = (ConvertTo-AdfaDnsBool -Value (Get-AdfaCimRawValue -Instance $z -Name 'IsReverseLookupZone'))
                    DynamicUpdate       = (& $text 'DynamicUpdate')
                    ReplicationScope    = (& $text 'ReplicationScope')
                    SecureSecondaries   = (& $text 'SecureSecondaries')
                })
        }
        $out.Zones = $list.ToArray()
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $codeProp = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $out.ErrorCode = [string]$codeProp.Value }
        return $out
    }
    try {
        $s = Get-DnsServerScavenging -ComputerName $ComputerName -ErrorAction Stop
        $out.ScavengingInterval = Get-AdfaCimRawValue -Instance $s -Name 'ScavengingInterval'
        $out.ScavengingState = ConvertTo-AdfaDnsBool -Value (Get-AdfaCimRawValue -Instance $s -Name 'ScavengingState')
        $out.ScavengingOk = $true
    }
    catch {
        $out.ScavengingError = [string]$_.Exception.Message
        if ($out.ScavengingError -eq '') { $out.ScavengingError = 'The scavenging read failed without an error message.' }
    }
    $aging = @{}
    foreach ($z in @($out.Zones)) {
        if ([string]$z.ZoneName -eq '' -or [string]$z.ZoneType -ne 'Primary' -or $z.IsAutoCreated -eq $true) { continue }
        $entry = [pscustomobject]@{ Ok = $false; AgingEnabled = $null; NoRefreshInterval = $null; RefreshInterval = $null; ScavengeServers = @(); Error = '' }
        try {
            $a = Get-DnsServerZoneAging -Name ([string]$z.ZoneName) -ComputerName $ComputerName -ErrorAction Stop
            $entry.AgingEnabled = ConvertTo-AdfaDnsBool -Value (Get-AdfaCimRawValue -Instance $a -Name 'AgingEnabled')
            $entry.NoRefreshInterval = Get-AdfaCimRawValue -Instance $a -Name 'NoRefreshInterval'
            $entry.RefreshInterval = Get-AdfaCimRawValue -Instance $a -Name 'RefreshInterval'
            $entry.ScavengeServers = @(@(Get-AdfaCimRawValue -Instance $a -Name 'ScavengeServers') | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ })
            $entry.Ok = $true
        }
        catch { $entry.Error = [string]$_.Exception.Message }
        $aging[([string]$z.ZoneName).ToLowerInvariant()] = $entry
    }
    $out.Aging = $aging
    try {
        $out.Forwarders = @(Get-AdfaForwarderAddress -Forwarder (Get-DnsServerForwarder -ComputerName $ComputerName -ErrorAction Stop))
        $out.ForwardersOk = $true
    }
    catch { $out.ForwarderError = [string]$_.Exception.Message }
    return $out
}

function ConvertTo-AdfaDnsRecordDataText {
    <#
    .SYNOPSIS
        Pure: the RecordData of one resource record as "Name=Value; ..." text, for display and the
        export. The property names inside RecordData are not published; every one present is shown.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Data)
    if ($null -eq $Data) { return '' }
    if ($Data -is [string]) { return $Data }
    $pairs = @()
    $store = $Data.PSObject.Properties['CimInstanceProperties']
    $props = @()
    if ($null -ne $store -and $null -ne $store.Value) { $props = @($store.Value | ForEach-Object { [pscustomobject]@{ Name = [string]$_.Name; Value = $_.Value } }) }
    else { $props = @($Data.PSObject.Properties | Where-Object { $_.MemberType -match 'Property' } | ForEach-Object { [pscustomobject]@{ Name = [string]$_.Name; Value = $_.Value } }) }
    foreach ($p in $props) {
        if ($null -eq $p.Value -or $p.Name -match '^(PSComputerName|CimClass|CimInstanceProperties|CimSystemProperties)$') { continue }
        $v = (@($p.Value) | ForEach-Object { ([string]$_).TrimEnd('.') }) -join ','
        $pairs += ("{0}={1}" -f $p.Name, $v)
    }
    return ($pairs -join '; ')
}

function Get-AdfaDnsRecordTarget {
    <#
    .SYNOPSIS
        Pure: what one record points at - the SRV target host (DomainName), the A address
        (IPv4Address) or the CNAME alias (HostNameAlias); '' for any other type. Names are
        provisional: they are the parameter names of Add-DnsServerResourceRecord.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Data, [AllowNull()][AllowEmptyString()][string]$RecordType)
    if ($null -eq $Data) { return '' }
    $name = switch -Regex ([string]$RecordType) {
        '^(?i)srv$' { 'DomainName'; break }
        '^(?i)a$' { 'IPv4Address'; break }
        '^(?i)cname$' { 'HostNameAlias'; break }
        default { '' }
    }
    if ($name -eq '') { return '' }
    $v = Get-AdfaCimRawValue -Instance $Data -Name $name
    if ($null -eq $v) { return '' }
    return ([string]$v).Trim().TrimEnd('.')
}

function Get-AdfaDnsRecordSetRaw {
    <#
    .SYNOPSIS
        Reads resource records from one zone of one DNS server with Get-DnsServerResourceRecord, up
        to a cap, keeping the real count.
    .DESCRIPTION
        With no -Name every record of the zone is read (Learn, Example 1). A cap of 0 keeps every
        record. Never throws. A failure the config reads as "no such record" (Win32 9701 or 9714, in
        the message or the error id) is Outcome NoRecord with Ok $true - a measured absence; any other
        failure is Outcome Error with Ok $false, never an absence.
    .OUTPUTS
        [pscustomobject] Ok, Outcome (Resolved|NoRecord|Error), Records (HostName, RecordType,
        TimeToLive, Timestamp, RecordData, Target), RealCount, Truncated, Error, ErrorCode, ErrorId.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][string]$ZoneName,
        [AllowEmptyString()][string]$Name = '',
        [AllowEmptyString()][string]$RRType = '',
        [ValidateRange(0, 1000000)][int]$Cap = 0,
        [hashtable]$Config = $script:Config.Dns
    )
    $out = [pscustomobject]@{ Ok = $false; Outcome = 'Error'; Records = @(); RealCount = 0; Truncated = $false; Error = ''; ErrorCode = ''; ErrorId = '' }
    try {
        $rrArgs = @{ ComputerName = $ComputerName; ZoneName = $ZoneName; ErrorAction = 'Stop' }
        if ($Name -ne '') { $rrArgs.Name = $Name }
        if ($RRType -ne '') { $rrArgs.RRType = $RRType }
        $list = New-Object System.Collections.ArrayList
        $count = 0
        foreach ($r in @(Get-DnsServerResourceRecord @rrArgs)) {
            if ($null -eq $r) { continue }
            $count++
            if ($Cap -gt 0 -and $list.Count -ge $Cap) { continue }
            $type = [string](Get-AdfaCimRawValue -Instance $r -Name 'RecordType')
            $data = Get-AdfaCimRawValue -Instance $r -Name 'RecordData'
            $ttl = Get-AdfaCimRawValue -Instance $r -Name 'TimeToLive'
            $stamp = Get-AdfaCimRawValue -Instance $r -Name 'Timestamp'
            $stampText = ''
            if ($stamp -is [datetime]) { $stampText = ([datetime]$stamp).ToString('yyyy-MM-dd HH:mm', [System.Globalization.CultureInfo]::InvariantCulture) }
            elseif ($null -ne $stamp) { $stampText = [string]$stamp }
            [void]$list.Add([pscustomobject]@{
                    HostName = [string](Get-AdfaCimRawValue -Instance $r -Name 'HostName'); RecordType = $type
                    TimeToLive = $(if ($null -eq $ttl) { '' } else { [string]$ttl }); Timestamp = $stampText
                    RecordData = (ConvertTo-AdfaDnsRecordDataText -Data $data); Target = (Get-AdfaDnsRecordTarget -Data $data -RecordType $type)
                })
        }
        $out.Records = $list.ToArray()
        $out.RealCount = $count
        $out.Truncated = ($Cap -gt 0 -and $count -gt $Cap)
        $out.Ok = $true
        if ($count -gt 0) { $out.Outcome = 'Resolved' } else { $out.Outcome = 'NoRecord' }
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $codeProp = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $out.ErrorCode = [string]$codeProp.Value }
        # The error id is read with the message: a CIM cmdlet's error id can carry the Win32 code
        # ("WIN32 9714,...") when the message does not (provisional, PORT-PLAN C13a).
        $idProp = $_.PSObject.Properties['FullyQualifiedErrorId']
        if ($null -ne $idProp -and $null -ne $idProp.Value) { $out.ErrorId = [string]$idProp.Value }
        $classText = ("{0} {1}" -f $out.Error, $out.ErrorId).Trim()
        if ((Get-AdfaDnsReadErrorClass -Message $classText -ErrorCode $out.ErrorCode -Config $Config) -eq 'NotFound') {
            $out.Ok = $true
            $out.Outcome = 'NoRecord'
        }
    }
    return $out
}

function Get-AdfaDnsServerZoneNames {
    <#
    .SYNOPSIS
        The zone names one DNS server holds, read once per run (Get-DnsServerZone) and shared by the
        DNS vs AD and record export sections, with each zone's type (ZoneType, '' when not returned).
        Never throws.
    .OUTPUTS
        [pscustomobject] Ok, Names, Types (lower-case zone name -> ZoneType), Error, ErrorCode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$ComputerName)
    $key = $ComputerName.ToLowerInvariant()
    if ($script:DnsZoneListCache.ContainsKey($key)) { return $script:DnsZoneListCache[$key] }
    $out = [pscustomobject]@{ Ok = $false; Names = @(); Types = @{}; Error = ''; ErrorCode = '' }
    try {
        $names = @(); $types = @{}
        foreach ($z in @(@(Get-DnsServerZone -ComputerName $ComputerName -ErrorAction Stop) | Where-Object { $null -ne $_ })) {
            $n = [string](Get-AdfaCimRawValue -Instance $z -Name 'ZoneName')
            if ($n -eq '') { continue }
            $t = Get-AdfaCimRawValue -Instance $z -Name 'ZoneType'
            $names += $n
            $types[$n.Trim().TrimEnd('.').ToLowerInvariant()] = $(if ($null -eq $t) { '' } else { ([string]$t).Trim() })
        }
        $out.Names = @($names)
        $out.Types = $types
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $codeProp = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $out.ErrorCode = [string]$codeProp.Value }
    }
    $script:DnsZoneListCache[$key] = $out
    return $out
}

function Resolve-AdfaDnsZoneForName {
    <#
    .SYNOPSIS
        Pure: the zone, of the ones a server holds, that holds a name - the longest zone name the
        name ends with on a label boundary - and the name relative to it ('@' for the apex).
        $null when no zone holds it.
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Name, [AllowEmptyCollection()][string[]]$ZoneNames = @())
    $n = $Name.Trim().TrimEnd('.').ToLowerInvariant()
    $best = ''
    foreach ($z in @($ZoneNames | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        $zl = $z.Trim().TrimEnd('.').ToLowerInvariant()
        if (($n -eq $zl -or $n.EndsWith('.' + $zl)) -and $zl.Length -gt $best.Length) { $best = $zl }
    }
    if ($best -eq '') { return $null }
    $relative = '@'
    if ($n -ne $best) { $relative = $n.Substring(0, $n.Length - $best.Length - 1) }
    return [pscustomobject]@{ Zone = $best; Relative = $relative }
}

function Get-AdfaDnsDelegationPoint {
    <#
    .SYNOPSIS
        Pure: the delegation, of a zone's delegation points (owner names of NS records below its
        apex, relative to the zone), at or above a relative name - '' when the name is not below
        any. Such a name is held by the delegated zone, not by the zone that was read.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][string]$Relative, [AllowNull()][AllowEmptyCollection()][string[]]$Delegations = @())
    $r = $Relative.Trim().TrimEnd('.').ToLowerInvariant()
    if ($r -eq '@' -or $r -eq '') { return '' }
    foreach ($d in @($Delegations | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        $dl = $d.Trim().TrimEnd('.').ToLowerInvariant()
        if ($dl -eq '@') { continue }
        if ($r -eq $dl -or $r.EndsWith('.' + $dl)) { return $dl }
    }
    return ''
}

function Get-AdfaDnsZoneDelegation {
    <#
    .SYNOPSIS
        The delegation points of one zone on one DNS server: the owner names of its NS records below
        the apex (Get-DnsServerResourceRecord -ZoneName <zone> -RRType Ns), read once per run. Never
        throws.
    .DESCRIPTION
        A zone always carries NS records at its apex, so a read that returns none, or fails, leaves
        the delegations unknown (Ok $false), never "none". The owner name of a record is its HostName,
        relative to the zone, '@' for the apex (Learn, Get-DnsServerResourceRecord: HostName; Example 6
        reads the apex NS records with -Node).
    .OUTPUTS
        [pscustomobject] Ok, Names (relative, lower-case), Cause.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$ComputerName, [Parameter(Mandatory)][string]$ZoneName, [Parameter(Mandatory)][hashtable]$Config)
    $key = ("{0}|{1}" -f $ComputerName, $ZoneName).ToLowerInvariant()
    if ($script:DnsDelegationCache.ContainsKey($key)) { return $script:DnsDelegationCache[$key] }
    $out = [pscustomobject]@{ Ok = $false; Names = @(); Cause = '' }
    $read = Get-AdfaDnsRecordSetRaw -ComputerName $ComputerName -ZoneName $ZoneName -RRType 'Ns' -Config $Config
    if ($read.Outcome -eq 'Resolved') {
        $out.Names = @(@($read.Records) | ForEach-Object { ([string]$_.HostName).Trim().TrimEnd('.').ToLowerInvariant() } | Where-Object { $_ -ne '' -and $_ -ne '@' } | Sort-Object -Unique)
        $out.Ok = $true
    }
    elseif ($read.Outcome -eq 'NoRecord') {
        $out.Cause = 'the NS records of the zone it holds came back empty, so whether the name sits below a delegation is not known'
    }
    else {
        $class = Get-AdfaDnsReadErrorClass -Message $read.Error -ErrorCode $read.ErrorCode -Config $Config
        $out.Cause = ("the NS records of the zone it holds, which show its delegations, could not be read ({0})" -f (Get-AdfaDnsReadCause -Class $class -Message $read.Error).TrimEnd('.'))
    }
    $script:DnsDelegationCache[$key] = $out
    return $out
}

function Resolve-AdfaDnsServerZone {
    <#
    .SYNOPSIS
        The zone of one DNS server whose own records can say whether a name exists there: the
        longest zone the server holds that ends with the name, of a type that holds records, with the
        name not below a delegation in it. Otherwise the cause, and the server read is not made.
    .DESCRIPTION
        A server that holds only a parent zone (contoso.com, with child.contoso.com delegated), a stub
        zone, or a conditional forwarder zone answers "no such name" for a name it does not hold - a
        read of that zone is not a measurement of the record, so it must never be graded as an
        absence. Learn: "A stub zone only contains information about the authoritative name servers
        for the zone" (zone-types, read 2026-11-17).
    .OUTPUTS
        [pscustomobject] Ok, Zone, Relative, Cause.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$ComputerName, [Parameter(Mandatory)][string]$Name, [Parameter(Mandatory)][hashtable]$Config)
    $fail = { param([string]$Cause) [pscustomobject]@{ Ok = $false; Zone = ''; Relative = ''; Cause = $Cause } }
    $zones = Get-AdfaDnsServerZoneNames -ComputerName $ComputerName
    if (-not $zones.Ok) {
        $class = Get-AdfaDnsReadErrorClass -Message $zones.Error -ErrorCode $zones.ErrorCode -Config $Config
        return (& $fail (Get-AdfaDnsReadCause -Class $class -Message $zones.Error))
    }
    $where = Resolve-AdfaDnsZoneForName -Name $Name -ZoneNames @($zones.Names)
    if ($null -eq $where) { return (& $fail 'this DNS server holds no zone for the name, so its zone was not read.') }
    $typeText = ''
    $typesProp = $zones.PSObject.Properties['Types']
    if ($null -ne $typesProp -and $typesProp.Value -is [hashtable] -and $typesProp.Value.ContainsKey([string]$where.Zone)) { $typeText = [string]$typesProp.Value[[string]$where.Zone] }
    $holds = @(@($Config['RecordZoneTypes']) | Where-Object { [string]$_ -eq $typeText })
    if ($holds.Count -eq 0) {
        $shown = $typeText
        if ($shown -eq '') { $shown = 'not returned' }
        return (& $fail ("the zone this DNS server holds for the name is of type '{0}', which does not hold its records, so its zone was not read." -f $shown))
    }
    if ([string]$where.Relative -ne '@') {
        $del = Get-AdfaDnsZoneDelegation -ComputerName $ComputerName -ZoneName ([string]$where.Zone) -Config $Config
        if (-not $del.Ok) { return (& $fail ("{0}, so its zone was not read for the name." -f [string]$del.Cause)) }
        $point = Get-AdfaDnsDelegationPoint -Relative ([string]$where.Relative) -Delegations @($del.Names)
        if ($point -ne '') { return (& $fail 'the name sits below a delegation in the zone this DNS server holds, so that zone does not hold the record and was not read for it.') }
    }
    return [pscustomobject]@{ Ok = $true; Zone = [string]$where.Zone; Relative = [string]$where.Relative; Cause = '' }
}

function Get-AdfaDnsServerRecord {
    <#
    .SYNOPSIS
        Instrument one: the record as the DNS server's own zone holds it (Get-DnsServerResourceRecord
        on the zone that holds the name).
    .DESCRIPTION
        Present (with its targets), Absent (the zone that holds the name was read and holds no such
        record), or Unread with the cause: the DnsServer module is missing, the server did not answer
        on RPC, its zone list could not be read, it holds no zone for the name, the zone it holds is
        a stub or forwarder zone, the name sits below a delegation in that zone (or its delegations
        could not be read), or the record read failed (Resolve-AdfaDnsServerZone). What this
        instrument cannot see: a record a client would get from another server or a delegation - so
        a name it does not hold is never Absent here.
    .OUTPUTS
        [pscustomobject] Outcome (Present|Absent|Unread), Targets, Cause.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][ValidateSet('SRV', 'A', 'CNAME')][string]$Type,
        [Parameter(Mandatory)][hashtable]$Config,
        [bool]$ModuleAvailable = $true,
        [int]$PortTimeoutMs = 1200
    )
    $unread = { param([string]$Cause) [pscustomobject]@{ Outcome = 'Unread'; Targets = @(); Cause = $Cause } }
    if (-not $ModuleAvailable) { return (& $unread 'Server read: the DnsServer PowerShell module is not installed on the host running the assessment.') }
    $rpcPort = [int]$Config['RpcPort']
    $gate = Get-AdfaDcProbeGate -ComputerName $ComputerName -Ports @($rpcPort) -TimeoutMs $PortTimeoutMs
    if ($gate.Cause) { return (& $unread ("Server read: {0}" -f (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'the server was not read'))) }
    if (-not $gate.Open[$rpcPort]) {
        return (& $unread ("Server read: Unreachable: RPC ({0}) did not answer within {1} ms." -f $rpcPort, $PortTimeoutMs))
    }
    $where = Resolve-AdfaDnsServerZone -ComputerName $ComputerName -Name $Name -Config $Config
    if (-not $where.Ok) { return (& $unread ("Server read: {0}" -f [string]$where.Cause)) }
    $rr = switch ($Type) { 'SRV' { 'Srv' } 'A' { 'A' } default { 'CName' } }
    $read = Get-AdfaDnsRecordSetRaw -ComputerName $ComputerName -ZoneName ([string]$where.Zone) -Name ([string]$where.Relative) -RRType $rr -Config $Config
    if ($read.Outcome -eq 'Resolved') {
        $targets = @(@($read.Records) | ForEach-Object { ([string]$_.Target).Trim().TrimEnd('.') } | Where-Object { $_ -ne '' } | Sort-Object -Unique)
        return [pscustomobject]@{ Outcome = 'Present'; Targets = $targets; Cause = '' }
    }
    if ($read.Outcome -eq 'NoRecord') { return [pscustomobject]@{ Outcome = 'Absent'; Targets = @(); Cause = '' } }
    $class = Get-AdfaDnsReadErrorClass -Message $read.Error -ErrorCode $read.ErrorCode -Config $Config
    return (& $unread ("Server read: {0}" -f (Get-AdfaDnsReadCause -Class $class -Message $read.Error)))
}

function Get-AdfaDnsResolverRecord {
    <#
    .SYNOPSIS
        Instrument two: the record as the DNS server answers a query for it (Resolve-AdfaDnsRecord,
        Resolve-DnsName -DnsOnly -Server, nslookup where the DnsClient module is absent).
    .DESCRIPTION
        Present, Absent (an authoritative "no such record") or Unread (no query tool on this host, or
        the server did not answer). What it cannot see: whether the answer came from the zone or
        from the server's cache or a forwarder; Learn does not say whether the query fills the local
        client cache.
    .OUTPUTS
        [pscustomobject] Outcome (Present|Absent|Unread), Targets, Cause.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$Name, [Parameter(Mandatory)][ValidateSet('SRV', 'A', 'CNAME')][string]$Type, [Parameter(Mandatory)][string]$Server)
    $r = Resolve-AdfaDnsRecord -Name $Name -Type $Type -Server $Server
    switch ([string]$r.Outcome) {
        'Resolved' { return [pscustomobject]@{ Outcome = 'Present'; Targets = @(@($r.Targets) | ForEach-Object { ([string]$_).Trim().TrimEnd('.') }); Cause = '' } }
        'NoRecord' { return [pscustomobject]@{ Outcome = 'Absent'; Targets = @(); Cause = '' } }
        'NoTool' { return [pscustomobject]@{ Outcome = 'Unread'; Targets = @(); Cause = ("Resolver query: no query tool on this host ({0})." -f ([string]$r.Error).Trim().TrimEnd('.')) } }
        default { return [pscustomobject]@{ Outcome = 'Unread'; Targets = @(); Cause = 'Resolver query: the DNS server did not answer.' } }
    }
}

function Get-AdfaDnsEvidenceState {
    <#
    .SYNOPSIS
        Pure: one record on one DNS server, from the two instruments. Present when either sees it,
        AbsentBoth when both say it is absent, AbsentOne when one says absent and the other could not
        be read, Unread when neither could.
    .DESCRIPTION
        A negative conclusion needs two instruments: only AbsentBoth may be graded as a measured
        absence. A server read and a query that disagree (one present, one absent) are Present: a
        record seen by either exists somewhere the DC locator can reach.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][ValidateSet('Present', 'Absent', 'Unread')][string]$ServerOutcome, [Parameter(Mandatory)][ValidateSet('Present', 'Absent', 'Unread')][string]$ResolverOutcome)
    if ($ServerOutcome -eq 'Present' -or $ResolverOutcome -eq 'Present') { return 'Present' }
    if ($ServerOutcome -eq 'Absent' -and $ResolverOutcome -eq 'Absent') { return 'AbsentBoth' }
    if ($ServerOutcome -eq 'Absent' -or $ResolverOutcome -eq 'Absent') { return 'AbsentOne' }
    return 'Unread'
}

function Get-AdfaDnsGradeText {
    <#
    .SYNOPSIS
        Pure: where a DNS grade came from - "Graded <status>: <ThresholdSource>." The built-in source
        says tool defaults, not Microsoft values; after -ConfigOverridePath it names the file for the
        keys the file supplied (Merge-AdfaDnsConfig), so a grade set by a file is never called a tool
        default. Every row that carries this text is matched by a section-scoped recommendation entry
        anchored on its Item, so a file path here cannot choose advice.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][string]$Status, [Parameter(Mandatory)][hashtable]$Config)
    $source = ([string]$Config['ThresholdSource']).Trim().TrimEnd('.')
    if ($source -eq '') { $source = 'source not recorded' }
    return ("Graded {0}: {1}." -f $Status, $source)
}

function Get-AdfaDnsDynamicUpdateVerdict {
    <#
    .SYNOPSIS
        Pure verdict for ADA-DNS-001: one zone's dynamic update setting over the DNS servers that
        host it.
    .DESCRIPTION
        Observations: one per hosting server - Server, Read, Cause, IsDsIntegrated ($true, $false or
        $null), DynamicUpdate (text). NonsecureStatus (Fail by default) when a server that was read
        reports the config's NonsecureDynamicUpdate on an AD-integrated zone: "Secure only is
        recommended for AD-integrated zones" (Learn). That measured finding stands even when another
        server was not read. Otherwise Not Assessed when any hosting server was not read, did not
        return the property, or returned a value outside DynamicUpdateValues; Info when the zone is
        not AD-integrated ("The last option is available only for AD-integrated DNS zones"); Pass
        only when every hosting server was read.
    .OUTPUTS
        [pscustomobject] Status, Detail, Evidence.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][AllowEmptyCollection()]$Observations = @(), [Parameter(Mandatory)][hashtable]$Config)
    $obs = @($Observations | Where-Object { $null -ne $_ })
    $known = @($Config['DynamicUpdateValues'] | ForEach-Object { [string]$_ })
    $nonsecure = [string]$Config['NonsecureDynamicUpdate']
    $failing = @(); $unmeasured = @(); $notDs = @(); $values = @()
    foreach ($o in $obs) {
        if (-not [bool]$o.Read) { $unmeasured += ("{0}: {1}" -f [string]$o.Server, [string]$o.Cause); continue }
        $value = ([string]$o.DynamicUpdate).Trim()
        $match = @($known | Where-Object { $_ -eq $value })
        if ($null -eq $o.IsDsIntegrated -or $o.IsDsIntegrated -isnot [bool] -or $match.Count -eq 0) {
            $unmeasured += ("{0}: value not recognised or not returned (DynamicUpdate '{1}', IsDsIntegrated '{2}')" -f [string]$o.Server, $value, [string]$o.IsDsIntegrated)
            continue
        }
        $values += ("{0}: {1}" -f [string]$o.Server, [string]$match[0])
        if (-not [bool]$o.IsDsIntegrated) { $notDs += [string]$o.Server; continue }
        if ([string]$match[0] -eq $nonsecure) { $failing += [string]$o.Server }
    }
    $evidence = (@($values) + @($unmeasured)) -join '; '
    $n = $obs.Count
    if ($failing.Count -gt 0) {
        return [pscustomobject]@{ Status = [string]$Config['NonsecureStatus']; Evidence = $evidence
            Detail = ("Dynamic update is Nonsecure and secure on this AD-integrated zone on {0} of {1} hosting DNS server(s): any computer on the network can then modify an existing record. Microsoft recommends Secure only for AD-integrated zones. {2}" -f $failing.Count, $n, (Get-AdfaDnsGradeText -Status ([string]$Config['NonsecureStatus']) -Config $Config)) }
    }
    if ($n -eq 0) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = ''; Detail = 'No DNS server reported this zone, so its dynamic update setting was not read.' } }
    if ($unmeasured.Count -gt 0) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = $evidence
            Detail = ("The dynamic update setting was not measured on {0} of {1} hosting DNS server(s) (not read, or a value not recognised); the servers that were read do not allow nonsecure updates. This is not a clean result." -f $unmeasured.Count, $n) }
    }
    if ($notDs.Count -gt 0) {
        return [pscustomobject]@{ Status = $script:Status.Info; Evidence = $evidence
            Detail = ("This zone is not AD-integrated on {0} of {1} hosting DNS server(s). Microsoft documents secure dynamic update as available only for AD-integrated zones, so it is not graded here." -f $notDs.Count, $n) }
    }
    return [pscustomobject]@{ Status = $script:Status.Pass; Evidence = $evidence
        Detail = ("Every one of the {0} hosting DNS server(s) was read, and none allows nonsecure dynamic updates on this AD-integrated zone." -f $n) }
}

function Get-AdfaDnsScavengingVerdict {
    <#
    .SYNOPSIS
        Pure verdict for ADA-DNS-002: whether stale records of one zone can be cleaned up - zone aging
        on, and at least one hosting server scavenging.
    .DESCRIPTION
        Observations: Server, Read, Cause, ServerScavenging ($true/$false/$null, from
        Test-AdfaDnsServerScavenges), AgingEnabled ($true/$false/$null). Learn: "You must enable both"
        and scavenging "skips any zone that has aging disabled".
          - AgingOffStatus (Warning) when a server that was read reports aging off - a measured fact
            that stands even if another server was not read.
          - ScavengingOffStatus (Warning) only when EVERY hosting server was read and none scavenges
            (catalogue: "Warning only when every hosting server was read"), and only when the
            observations are the zone's whole hosting set (-HostSetComplete): a zone replicated
            beyond the servers this run read (Forest or Custom scope in a run that did not cover the
            forest, or a scope this tool cannot map to servers) may be scavenged by a server it did
            not read - Microsoft recommends exactly one scavenging server per zone - so that is Not
            Assessed with -HostSetCause, never a Warning.
          - Not Assessed when any hosting server was not read, or a value was not returned; Pass
            only when every value was read, aging is on and at least one server scavenges.
        Both grades are tool defaults: Microsoft publishes no requirement to enable either.
    .OUTPUTS
        [pscustomobject] Status, Detail, Evidence.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()]$Observations = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [bool]$HostSetComplete = $true,
        [AllowNull()][AllowEmptyString()][string]$HostSetCause = ''
    )
    $obs = @($Observations | Where-Object { $null -ne $_ })
    $n = $obs.Count
    if ($n -eq 0) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = ''; Detail = 'No DNS server reported this zone, so its aging and scavenging were not read.' } }
    $unmeasured = @(); $scavenging = @(); $notScavenging = @(); $agingOff = @(); $parts = @()
    foreach ($o in $obs) {
        if (-not [bool]$o.Read) { $unmeasured += ("{0}: {1}" -f [string]$o.Server, [string]$o.Cause); continue }
        $s = $o.ServerScavenging
        $a = $o.AgingEnabled
        if ($a -is [bool] -and -not $a) { $agingOff += [string]$o.Server }
        if ($null -eq $s -or $s -isnot [bool] -or $null -eq $a -or $a -isnot [bool]) {
            $unmeasured += ("{0}: server scavenging '{1}', zone aging '{2}' (not returned or not read)" -f [string]$o.Server, [string]$s, [string]$a)
            continue
        }
        if ($s) { $scavenging += [string]$o.Server } else { $notScavenging += [string]$o.Server }
        $parts += ("{0}: server scavenging {1}, zone aging {2}" -f [string]$o.Server, $(if ($s) { 'on' } else { 'off' }), $(if ($a) { 'on' } else { 'off' }))
    }
    $evidence = (@($parts) + @($unmeasured)) -join '; '
    $rank = @{ 'Fail' = 0; 'Warning' = 1; 'Info' = 2 }
    $issues = @()
    if ($agingOff.Count -gt 0) {
        $issues += [pscustomobject]@{ Status = [string]$Config['AgingOffStatus']
            Text = ("Zone aging is not enabled for this zone on {0} of {1} hosting DNS server(s); Microsoft documents that scavenging skips a zone with aging disabled, so its stale records are never removed." -f $agingOff.Count, $n) }
    }
    if ($HostSetComplete -and $unmeasured.Count -eq 0 -and $scavenging.Count -eq 0) {
        $issues += [pscustomobject]@{ Status = [string]$Config['ScavengingOffStatus']
            Text = ("Every one of the {0} hosting DNS server(s) was read and no hosting DNS server has scavenging enabled, so stale records in this zone are never removed (Microsoft: aging and scavenging must both be enabled)." -f $n) }
    }
    if ($issues.Count -gt 0) {
        $worst = @($issues | Sort-Object { $r = $rank[[string]$_.Status]; if ($null -eq $r) { 9 } else { $r } })[0]
        return [pscustomobject]@{ Status = [string]$worst.Status; Evidence = $evidence
            Detail = ("{0} {1}" -f ((@($issues | ForEach-Object { $_.Text })) -join ' '), (Get-AdfaDnsGradeText -Status ([string]$worst.Status) -Config $Config)) }
    }
    if ($unmeasured.Count -gt 0) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = $evidence
            Detail = ("Aging or scavenging was not measured on {0} of {1} hosting DNS server(s), so whether stale records of this zone are cleaned up is not known. This is not a clean result." -f $unmeasured.Count, $n) }
    }
    if (-not $HostSetComplete -and $scavenging.Count -eq 0) {
        $why = ([string]$HostSetCause).Trim().TrimEnd('.')
        if ($why -eq '') { $why = 'this zone is replicated to DNS servers this run did not read' }
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = $evidence
            Detail = ("None of the {0} DNS server(s) of this run that host this zone has scavenging enabled, but {1}, so whether any hosting server scavenges it is not known. This is not a clean result." -f $n, $why) }
    }
    return [pscustomobject]@{ Status = $script:Status.Pass; Evidence = $evidence
        Detail = ("Zone aging is on, and {0} of {1} hosting DNS server(s) scavenge (Microsoft recommends one scavenging server per zone)." -f $scavenging.Count, $n) }
}

function Get-AdfaDcLocatorVerdict {
    <#
    .SYNOPSIS
        Pure verdict for ADA-DNS-003: whether one writable DC is a target of each graded DC locator
        SRV record on every DNS server asked.
    .DESCRIPTION
        Checks: one per graded record per DNS server - Record, Server, State (from
        Get-AdfaDnsEvidenceState), Cause. Fail only when both instruments agree a record does not
        name the DC (AbsentBoth); OneInstrumentStatus (Warning by default) when only one instrument
        could say so; Not Assessed when a server could not be read by either instrument, or there is
        nothing to check; Pass only when every check is Present. A read-only DC is Info: Microsoft
        documents that RODCs register site-specific records by default (reference SPEC: excluded).
    .OUTPUTS
        [pscustomobject] Status, Detail, Evidence.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$IsReadOnly, [AllowNull()][AllowEmptyCollection()]$Checks = @(), [Parameter(Mandatory)][hashtable]$Config)
    if ($IsReadOnly -eq $true) {
        return [pscustomobject]@{ Status = $script:Status.Info; Evidence = ''
            Detail = 'Excluded: a read-only domain controller. Microsoft documents that read-only DCs register site-specific records by default, so the generic records are not expected of it.' }
    }
    $c = @($Checks | Where-Object { $null -ne $_ })
    if ($c.Count -eq 0) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = ''; Detail = 'No DNS server was asked, so the DC locator records of this DC were not checked. This is not a clean result.' } }
    $both = @($c | Where-Object { $_.State -eq 'AbsentBoth' })
    $one = @($c | Where-Object { $_.State -eq 'AbsentOne' })
    $unread = @($c | Where-Object { $_.State -ne 'Present' -and $_.State -ne 'AbsentBoth' -and $_.State -ne 'AbsentOne' })
    $evidence = (@($c | ForEach-Object { $t = ("{0} on {1}: {2}" -f [string]$_.Record, [string]$_.Server, [string]$_.State); if ([string]$_.Cause -ne '') { $t = ("{0} ({1})" -f $t, [string]$_.Cause) }; $t })) -join '; '
    if ($both.Count -gt 0) {
        return [pscustomobject]@{ Status = $script:Status.Fail; Evidence = $evidence
            Detail = ("This DC is not named by a graded DC locator record in {0} of {1} check(s), and both instruments (the server's own zone and a query to that server) agree. Clients and other DCs cannot find it through that record." -f $both.Count, $c.Count) }
    }
    if ($one.Count -gt 0) {
        return [pscustomobject]@{ Status = [string]$Config['OneInstrumentStatus']; Evidence = $evidence
            Detail = ("This DC is not named by a graded DC locator record in {0} of {1} check(s), seen by one instrument only - the other could not be read - so the absence is not confirmed. {2}" -f $one.Count, $c.Count, (Get-AdfaDnsGradeText -Status ([string]$Config['OneInstrumentStatus']) -Config $Config)) }
    }
    if ($unread.Count -gt 0) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = $evidence
            Detail = ("{0} of {1} check(s) could not be read by either instrument. This is not a clean result." -f $unread.Count, $c.Count) }
    }
    return [pscustomobject]@{ Status = $script:Status.Pass; Evidence = $evidence
        Detail = ("This DC is named by every graded DC locator record on every DNS server asked ({0} check(s))." -f $c.Count) }
}

function Get-AdfaDcARecordVerdict {
    <#
    .SYNOPSIS
        Pure verdict for ADA-DNS-004: whether every A record for a DC's host name is one of the IPv4
        addresses its adapters hold, and at least one exists.
    .DESCRIPTION
        Answers: one per DNS server - Server, State (Get-AdfaDnsEvidenceState), Addresses. ARecordStatus
        (Warning by default) for an A record whose address is not configured on the DC, or no A
        record on both instruments; the absence on one instrument only is OneInstrumentStatus when
        that is Not Assessed, otherwise ARecordStatus. Not Assessed when the adapters were not read
        ($null), hold no IPv4 address, a server could not be read, or a server returned a record
        from which no address could be read (nothing was compared). IPv4 only: Learn does not
        publish how IPv6 is handled for this purpose.
    .OUTPUTS
        [pscustomobject] Status, Detail, Evidence.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$ConfiguredIPv4,
        [AllowNull()][AllowEmptyString()][string]$ConfiguredCause = '',
        [AllowNull()][AllowEmptyCollection()]$Answers = @(),
        [Parameter(Mandatory)][hashtable]$Config
    )
    $a = @($Answers | Where-Object { $null -ne $_ })
    $evidence = (@($a | ForEach-Object { ("{0}: {1} {2}" -f [string]$_.Server, [string]$_.State, ((@($_.Addresses) | ForEach-Object { [string]$_ }) -join ',')).Trim() })) -join '; '
    if ($null -eq $ConfiguredIPv4) {
        $why = ([string]$ConfiguredCause).Trim()
        if ($why -eq '') { $why = 'The adapters of this DC were not read.' }
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = $evidence; Detail = ("The DC's configured addresses are not known, so its A records were not compared. {0}" -f $why) }
    }
    $configured = @($ConfiguredIPv4 | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
    if ($configured.Count -eq 0) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = $evidence; Detail = 'The adapters of this DC hold no IPv4 address, so its A records were not compared.' } }
    if ($a.Count -eq 0) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = ''; Detail = 'No DNS server was asked, so the A records of this DC were not checked. This is not a clean result.' } }
    $extra = @(); $both = 0; $one = 0; $unread = 0; $noAddress = 0
    foreach ($ans in $a) {
        switch ([string]$ans.State) {
            'Present' {
                $seen = @(@($ans.Addresses) | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ -ne '' })
                # A record was returned but no address could be read from it (the RecordData property
                # names are provisional): nothing was compared, so it is not a match.
                if ($seen.Count -eq 0) { $noAddress++; break }
                foreach ($t in $seen) { if ($configured -notcontains $t -and $extra -notcontains $t) { $extra += $t } }
            }
            'AbsentBoth' { $both++ }
            'AbsentOne' { $one++ }
            default { $unread++ }
        }
    }
    $status = [string]$Config['ARecordStatus']
    if ($extra.Count -gt 0 -or $both -gt 0) {
        $bits = @()
        if ($extra.Count -gt 0) { $bits += ("{0} address(es) in A records for this DC are not configured on its adapters" -f $extra.Count) }
        if ($both -gt 0) { $bits += ("{0} DNS server(s) hold no A record for it, by both instruments" -f $both) }
        return [pscustomobject]@{ Status = $status; Evidence = $evidence; Detail = ("{0}. {1}" -f ($bits -join '; '), (Get-AdfaDnsGradeText -Status $status -Config $Config)) }
    }
    if ($one -gt 0) {
        $oneStatus = [string]$Config['OneInstrumentStatus']
        if ($oneStatus -ne $script:Status.NotAssessed) { $oneStatus = $status }
        return [pscustomobject]@{ Status = $oneStatus; Evidence = $evidence
            Detail = ("{0} DNS server(s) hold no A record for this DC by one instrument only; the other could not be read, so the absence is not confirmed. {1}" -f $one, (Get-AdfaDnsGradeText -Status $oneStatus -Config $Config)) }
    }
    if ($unread -gt 0 -or $noAddress -gt 0) {
        $bits = @()
        if ($unread -gt 0) { $bits += ("{0} of {1} DNS server(s) could not be read by either instrument" -f $unread, $a.Count) }
        if ($noAddress -gt 0) { $bits += ("{0} of {1} DNS server(s) returned an A record whose address this tool could not read, so it was not compared" -f $noAddress, $a.Count) }
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Evidence = $evidence; Detail = ("{0}. This is not a clean result." -f ($bits -join '; ')) }
    }
    return [pscustomobject]@{ Status = $script:Status.Pass; Evidence = $evidence; Detail = ("Every A record for this DC on the {0} DNS server(s) asked is an address configured on its adapters." -f $a.Count) }
}

function Get-AdfaStaleDnsRecordVerdict {
    <#
    .SYNOPSIS
        Pure verdict for ADA-DNS-005: the DC locator SRV targets and <guid>._msdcs CNAMEs that match
        no domain controller the directory holds.
    .DESCRIPTION
        Candidates: Name, Type (SRV or CNAME), Target, Server. An SRV target is stale when its host
        is in no -KnownDcHosts entry (read-only DCs are known, so their records are never stale). A
        CNAME is stale when its GUID label is in no -KnownDsaGuids entry; with -DsaError set the DSA
        GUIDs were not read and no CNAME is judged, and an empty -KnownDsaGuids is read the same way
        when there is a CNAME to judge. Not Assessed, with nothing listed, when no DC is known (checked
        first: every SRV target would otherwise be listed as stale). StaleRecordStatus (Warning by
        default) when any is stale; Not Assessed when nothing is stale but a server or the DSA list
        was not read; Pass otherwise. Microsoft publishes no grade, only "Remove references to stale
        domain controllers".
    .OUTPUTS
        [pscustomobject] Stale (Name, Type, Target, Servers), Status, Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()]$Candidates = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$KnownDcHosts = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$KnownDsaGuids = @(),
        [AllowNull()][AllowEmptyString()][string]$DsaError = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$Unread = @(),
        [Parameter(Mandatory)][hashtable]$Config
    )
    $hosts = @{}
    foreach ($h in @($KnownDcHosts | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) { $hosts[$h.Trim().TrimEnd('.').ToLowerInvariant()] = $true }
    # No DC known: every SRV target would look stale, so nothing is judged. This guard comes before
    # any record is listed, so an empty DC list can never turn live DCs' records into findings.
    if ($hosts.Count -eq 0) { return [pscustomobject]@{ Stale = @(); Status = $script:Status.NotAssessed; Detail = 'No domain controller is known to this run, so no record could be judged. This is not a clean result.' } }
    $guids = @{}
    foreach ($g in @($KnownDsaGuids | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) { $guids[$g.Trim().Trim('{', '}').ToLowerInvariant()] = $true }
    $dsaMissing = -not [string]::IsNullOrWhiteSpace($DsaError)
    # No DSA GUID known and no error given: a forest always has an NTDS Settings object, so an empty
    # list is a read that saw nothing, and every <guid>._msdcs CNAME would look stale.
    if (-not $dsaMissing -and $guids.Count -eq 0 -and @(@($Candidates | Where-Object { $null -ne $_ -and ([string]$_.Type).ToUpperInvariant() -eq 'CNAME' })).Count -gt 0) {
        $dsaMissing = $true
        $DsaError = 'no DSA GUID is known to this run'
    }
    $stale = [ordered]@{}
    foreach ($c in @($Candidates | Where-Object { $null -ne $_ })) {
        $type = ([string]$c.Type).ToUpperInvariant()
        $key = ''
        if ($type -eq 'SRV') {
            $t = ([string]$c.Target).Trim().TrimEnd('.').ToLowerInvariant()
            if ($t -eq '' -or $hosts.ContainsKey($t)) { continue }
            $key = ("SRV|{0}|{1}" -f ([string]$c.Name).ToLowerInvariant(), $t)
        }
        elseif ($type -eq 'CNAME') {
            if ($dsaMissing) { continue }
            $label = (([string]$c.Name).Trim().TrimEnd('.').Split('.'))[0].ToLowerInvariant()
            if ($label -notmatch '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' -or $guids.ContainsKey($label)) { continue }
            $key = ("CNAME|{0}" -f ([string]$c.Name).Trim().TrimEnd('.').ToLowerInvariant())
        }
        else { continue }
        if (-not $stale.Contains($key)) {
            $stale[$key] = [pscustomobject]@{ Name = ([string]$c.Name).Trim().TrimEnd('.'); Type = $type; Target = ([string]$c.Target).Trim().TrimEnd('.'); Servers = @() }
        }
        $srv = [string]$c.Server
        if ($srv -ne '' -and @($stale[$key].Servers) -notcontains $srv) { $stale[$key].Servers = @(@($stale[$key].Servers) + $srv) }
    }
    $list = @($stale.Values)
    $gaps = @($Unread | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($list.Count -gt 0) {
        return [pscustomobject]@{ Stale = $list; Status = [string]$Config['StaleRecordStatus']
            Detail = ("{0} DC locator record(s) name a host or a DSA GUID that matches no domain controller in the directory. Microsoft: remove references to stale domain controllers. {1}" -f $list.Count, (Get-AdfaDnsGradeText -Status ([string]$Config['StaleRecordStatus']) -Config $Config)) }
    }
    if ($dsaMissing -or $gaps.Count -gt 0) {
        $bits = @()
        if ($dsaMissing) { $bits += ("the DSA GUIDs could not be read, so no <guid>._msdcs CNAME was judged ({0})" -f $DsaError.Trim().TrimEnd('.')) }
        if ($gaps.Count -gt 0) { $bits += ("{0} read(s) did not answer" -f $gaps.Count) }
        return [pscustomobject]@{ Stale = @(); Status = $script:Status.NotAssessed; Detail = ("No record that names no DC was found, but {0}. This is not a clean result." -f ($bits -join '; ')) }
    }
    return [pscustomobject]@{ Stale = @(); Status = $script:Status.Pass; Detail = 'Every DC locator record read names a domain controller in the directory.' }
}

function Get-AdfaDcDnsClientVerdict {
    <#
    .SYNOPSIS
        Pure verdict for one DC's DNS client settings (ADA-INV-016, inventory, with one graded flag).
    .DESCRIPTION
        -DnsServers: the DC's DNS server list in order across its enabled adapters, or $null when the
        list was not measured - the adapters not read, or no adapter returned DNSServerSearchOrder
        (then Not Assessed with -Cause). SingleServerStatus (Warning by default) for a list that was
        returned empty, or a single DNS server while more than one DC is known to this run:
        Microsoft calls a single server, loopback included, "a single point of failure ... tolerable
        in a forest with only one domain controller" (KB 4013 article). A single server with one DC
        known is Info only when -DcCountIsForest says the count covers every DC of the forest;
        otherwise the premise is not measured and the row is Not Assessed. Everything else is Info:
        itself or loopback first (Learn allows a DC to use itself as preferred once replication is
        verified; its hub-and-branch guidance lists itself last), no other known DC in the list, and
        addresses that are no DC known to this run (Learn: do not point DCs at ISP DNS servers; an
        address alone cannot tell an ISP resolver from an internal one). Addresses stay in the
        DnsServers column, never in Detail.
    .OUTPUTS
        [pscustomobject] Status, Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$DnsServers,
        [AllowNull()][AllowEmptyString()][string]$Cause = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$SelfAddresses = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$KnownDcAddresses = @(),
        [int]$DcCount = 0,
        [bool]$DcCountIsForest = $false,
        [Parameter(Mandatory)][hashtable]$Config
    )
    if ($null -eq $DnsServers) {
        $why = ([string]$Cause).Trim()
        if ($why -eq '') { $why = 'The adapters of this DC were not read.' }
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Detail = $why }
    }
    $list = New-Object System.Collections.ArrayList
    foreach ($s in @($DnsServers)) { $t = ([string]$s).Trim(); if ($t -ne '' -and -not $list.Contains($t)) { [void]$list.Add($t) } }
    $loop = @($Config['LoopbackAddresses'] | ForEach-Object { [string]$_ })
    $self = @(@($SelfAddresses) + $loop | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
    $dcs = @($KnownDcAddresses | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
    $single = [string]$Config['SingleServerStatus']
    if ($list.Count -eq 0) {
        return [pscustomobject]@{ Status = $single; Detail = ("The DNS server list returned for the enabled adapters of this DC is empty, so it cannot resolve the locator records it depends on. {0}" -f (Get-AdfaDnsGradeText -Status $single -Config $Config)) }
    }
    $notes = @()
    if ($self -contains [string]$list[0]) { $notes += 'It lists itself or loopback first (Microsoft allows this once replication is verified; its hub-and-branch guidance lists the DC itself last).' }
    $others = @($list | Where-Object { $self -notcontains $_ -and $dcs -contains $_ })
    if ($others.Count -eq 0 -and $DcCount -gt 1) { $notes += 'It lists no other domain controller known to this run.' }
    $unknown = @($list | Where-Object { $self -notcontains $_ -and $dcs -notcontains $_ })
    if ($unknown.Count -gt 0) { $notes += ("{0} address(es) are not an address of any domain controller known to this run; Microsoft says not to point DCs at ISP DNS servers, and an address alone cannot show whether one is." -f $unknown.Count) }
    $noteText = ''
    if ($notes.Count -gt 0) { $noteText = (' ' + ($notes -join ' ')) }
    if ($list.Count -eq 1) {
        if ($DcCount -gt 1) {
            return [pscustomobject]@{ Status = $single
                Detail = ("This DC points to a single DNS server while {0} domain controllers are known to this run. Microsoft: a single DNS server, loopback included, is a single point of failure, tolerable only in a forest with one domain controller. {2}{1}" -f $DcCount, $noteText, (Get-AdfaDnsGradeText -Status $single -Config $Config)) }
        }
        if ($DcCountIsForest -and $DcCount -eq 1) {
            return [pscustomobject]@{ Status = $script:Status.Info
                Detail = ("This DC points to a single DNS server, and it is the only domain controller of the forest (every domain of the forest was read); Microsoft calls that tolerable in a forest with one domain controller.{0}" -f $noteText) }
        }
        return [pscustomobject]@{ Status = $script:Status.NotAssessed
            Detail = ("This DC points to a single DNS server. Microsoft calls that a single point of failure, tolerable only in a forest with one domain controller, and this run did not count the domain controllers of the whole forest (it did not cover every domain, or a domain's DC list could not be read), so whether that holds here is not known. This is not a clean result.{0}" -f $noteText) }
    }
    return [pscustomobject]@{ Status = $script:Status.Info; Detail = ("This DC lists {0} DNS servers (inventory).{1}" -f $list.Count, $noteText) }
}

function Get-AdfaDcNetworkRaw {
    <#
    .SYNOPSIS
        The one place C13 reads a DC's adapters: Win32_NetworkAdapterConfiguration where IPEnabled,
        five properties, in one bounded CIM session.
    .DESCRIPTION
        IPEnabled, IPAddress, DNSServerSearchOrder, Description and InterfaceIndex, read raw
        (Get-AdfaCimRawValue). The class has methods that change an adapter (SetDNSServerSearchOrder,
        EnableStatic, ...); none is called - instances are enumerated, properties read. Never throws;
        the session is always closed with -WhatIf and -Confirm forced off (see Get-AdfaDcDiskRaw).
          https://learn.microsoft.com/windows/win32/cimwin32prov/win32-networkadapterconfiguration
          Read: 2026-11-17.
    .OUTPUTS
        [pscustomobject] Ok, Protocol, Error, ErrorCode, Adapters (IPEnabled, IPAddress,
        DNSServerSearchOrder - $null when absent, Description, InterfaceIndex).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [ValidateSet('Wsman', 'Dcom')][string]$Protocol = 'Wsman',
        [pscredential]$Credential,
        [int]$OperationTimeoutSec = 90
    )
    $out = [pscustomobject]@{ Ok = $false; Protocol = $Protocol; Error = ''; ErrorCode = ''; Adapters = @() }
    $session = $null
    try {
        $sessionArgs = @{ ComputerName = $ComputerName; OperationTimeoutSec = [uint32]$OperationTimeoutSec; ErrorAction = 'Stop' }
        if ($Protocol -eq 'Dcom') { $sessionArgs.SessionOption = New-CimSessionOption -Protocol Dcom }
        if ($Credential) { $sessionArgs.Credential = $Credential }
        $session = New-CimSession @sessionArgs
        $instances = @(Get-CimInstance -CimSession $session -Namespace 'root/cimv2' -ClassName 'Win32_NetworkAdapterConfiguration' -Filter 'IPEnabled = TRUE' `
                -Property 'IPEnabled', 'IPAddress', 'DNSServerSearchOrder', 'Description', 'InterfaceIndex' -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -ErrorAction Stop)
        $list = New-Object System.Collections.ArrayList
        foreach ($i in $instances) {
            if ($null -eq $i) { continue }
            $dns = Get-AdfaCimRawValue -Instance $i -Name 'DNSServerSearchOrder'
            $dnsList = $null
            if ($null -ne $dns) { $dnsList = @(@($dns) | Where-Object { $null -ne $_ } | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ -ne '' }) }
            [void]$list.Add([pscustomobject]@{
                    IPEnabled = ConvertTo-AdfaDnsBool -Value (Get-AdfaCimRawValue -Instance $i -Name 'IPEnabled')
                    IPAddress = @(@(Get-AdfaCimRawValue -Instance $i -Name 'IPAddress') | Where-Object { $null -ne $_ } | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ -ne '' })
                    DNSServerSearchOrder = $dnsList
                    Description = [string](Get-AdfaCimRawValue -Instance $i -Name 'Description')
                    InterfaceIndex = Get-AdfaCimRawValue -Instance $i -Name 'InterfaceIndex'
                })
        }
        $out.Adapters = $list.ToArray()
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $codeProp = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $out.ErrorCode = [string]$codeProp.Value }
    }
    finally {
        if ($null -ne $session) {
            try { Remove-CimSession -CimSession $session -WhatIf:$false -Confirm:$false -ErrorAction SilentlyContinue } catch { }
        }
    }
    return $out
}

function Get-AdfaDcNetworkState {
    <#
    .SYNOPSIS
        One DC's adapters, read once per run and shared by the DC DNS Client rows and the DC A
        record check: its configured IPv4 addresses and its DNS server list.
    .DESCRIPTION
        Probes WinRM and RPC through the shared cache (Test-AdfaDcPort), reads over the first
        transport that answers (Invoke-AdfaDcRemoteRead), and keeps unreachable, access denied and
        any other failure apart. A query that answered with no IP-enabled adapter is Error ("Read
        returned no adapter"), not a DC with no address and no DNS server. Never throws.
    .OUTPUTS
        [pscustomobject] Status (Read|Unreachable|AccessDenied|Error), Cause, IPv4 (string[]),
        DnsServers (string[] in adapter order, $null when no adapter returned the property),
        DnsCause (why DnsServers is $null after a read), Adapters.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][hashtable]$Config,
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [int]$OperationTimeoutSec = 90
    )
    $key = $ComputerName.ToLowerInvariant()
    if ($script:DcNetworkCache.ContainsKey($key)) { return $script:DcNetworkCache[$key] }
    $state = [pscustomobject]@{ Status = 'Error'; Cause = ''; IPv4 = @(); DnsServers = $null; DnsCause = ''; Adapters = @() }
    $wsmanPort = [int]$Config['WsmanPort']
    $rpcPort = [int]$Config['RpcPort']
    $protocols = @()
    $gate = Get-AdfaDcProbeGate -ComputerName $ComputerName -Ports @($wsmanPort, $rpcPort) -TimeoutMs $PortTimeoutMs
    if ($gate.Open[$wsmanPort]) { $protocols += 'Wsman' }
    if ($gate.Open[$rpcPort]) { $protocols += 'Dcom' }
    if ($gate.Cause) {
        $state.Status = 'Unreachable'
        $state.Cause = Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'the adapters were not read'
    }
    elseif ($protocols.Count -eq 0) {
        $state.Status = 'Unreachable'
        $state.Cause = ("Unreachable: neither WinRM ({0}) nor RPC ({1}) answered within {2} ms, so the adapters were not read." -f $wsmanPort, $rpcPort, $PortTimeoutMs)
    }
    else {
        $readArguments = @{ OperationTimeoutSec = $OperationTimeoutSec }
        if ($Credential) { $readArguments.Credential = $Credential }
        $read = Invoke-AdfaDcRemoteRead -ComputerName $ComputerName -Protocols $protocols -ReadCommand 'Get-AdfaDcNetworkRaw' -ReadArguments $readArguments
        if ($null -eq $read.Raw -or -not $read.Raw.Ok) {
            if ($read.Denied) {
                $state.Status = 'AccessDenied'
                $state.Cause = ("Access denied: the account running the assessment could not read the adapters of this DC (local Administrators rights are needed for remote WMI). Reported by the DC - {0}" -f (@($read.Attempts) -join ' | '))
            }
            else {
                $state.Status = 'Error'
                $state.Cause = ("Read failed: a port answered, but the adapters could not be read. Reported by the DC - {0}" -f (@($read.Attempts) -join ' | '))
            }
        }
        elseif (@(@($read.Raw.Adapters) | Where-Object { $null -ne $_ }).Count -eq 0) {
            # The query answered but listed no IP-enabled adapter. A DC that answers over the network
            # has one, so this is a read that saw nothing (a damaged WMI repository, a filter the
            # provider did not honour), not a measured configuration: neither the addresses nor the
            # DNS servers are known.
            $state.Status = 'Error'
            $state.Cause = 'Read returned no adapter: the adapter query answered but listed no IP-enabled adapter, so the addresses and the DNS server list of this DC are not known.'
        }
        else {
            $state.Status = 'Read'
            $state.Adapters = @($read.Raw.Adapters)
            $ipv4 = @(); $dns = $null
            foreach ($ad in @($read.Raw.Adapters)) {
                foreach ($ip in @($ad.IPAddress)) {
                    $parsed = $null
                    if ([System.Net.IPAddress]::TryParse([string]$ip, [ref]$parsed) -and $parsed.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetwork -and $ipv4 -notcontains [string]$ip) { $ipv4 += [string]$ip }
                }
                if ($null -ne $ad.DNSServerSearchOrder) {
                    if ($null -eq $dns) { $dns = @() }
                    foreach ($s in @($ad.DNSServerSearchOrder)) { if ($dns -notcontains [string]$s) { $dns += [string]$s } }
                }
            }
            $state.IPv4 = @($ipv4)
            # $null stays $null: no adapter returned DNSServerSearchOrder, so the list is not
            # measured (Win32_NetworkAdapterConfiguration gives no other way to tell "no DNS server
            # configured" from "property not returned"); the DNS client row is then Not Assessed.
            if ($null -ne $dns) { $state.DnsServers = @($dns) }
            else {
                $state.DnsServers = $null
                $state.DnsCause = 'Not returned: the adapters of this DC were read, but none returned a DNS server list (DNSServerSearchOrder), so whether a DNS server is configured is not known.'
            }
        }
    }
    $script:DcNetworkCache[$key] = $state
    return $state
}

function Get-AdfaDnsHealth {
    <#
    .SYNOPSIS
        DNS Health: per DNS server read, per zone dynamic update (DNS-001) and aging/scavenging
        (DNS-002) over the DNS servers of each domain, and the zone inventory (INV-013).
    .DESCRIPTION
        Every DC of every scoped domain is asked as a DNS server, through the DnsServer module of
        the host running the assessment (Get-DnsServerZone, Get-DnsServerScavenging,
        Get-DnsServerZoneAging, Get-DnsServerForwarder with -ComputerName; Get-AdfaDnsServerRaw).
        RPC is probed once per DC (Test-AdfaDcPort). Unreachable, access denied, DNS provider
        missing, timed out, any other failure and the DnsServer module missing are separate Not
        Assessed causes, never Pass.

        DECLARED POPULATION: the domains named in -ScopedDomains (each one either has DC rows or
        its own "DNS server - <domain>" Not Assessed row), every DC of each (one "DNS server: <dc>"
        row), and every primary zone a read DC of the domain reports (one "Zone dynamic update" and
        one "Zone scavenging" row per zone and domain - per zone for a forest-wide zone, see below -
        a "Zone configuration" row per zone and server,
        and a "DNS zones (population)" row per domain). A DC that was not read counts as a hosting
        server of every zone of its domain, so no zone of that domain can Pass.

        Hosting set by replication scope (ReplicationScope, read on every server that reports the
        zone): a Domain zone is graded per domain over that domain's DNS servers. A Forest or Custom
        zone is graded once, under the first domain that holds it, over every DNS server of the run
        (a DC of any domain that was not read counts as a host); "no hosting server scavenges" is
        asserted for it only with -ForestComplete (every domain of the forest scoped, Invoke-Main)
        and no inventory failure. Any other scope - Legacy, none, not returned, or servers that
        disagree - never gets that Warning, because the servers that host it are not known.

        The forwarder and zone transfer rows of earlier versions are kept as they were; the
        "<dc>: zones" and "<dc>: scavenging" rows are replaced by the zone rows (the old scavenging
        row passed a zone whose aging property was not returned).
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [hashtable]$Config = $script:Config.Dns,
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @(),
        [bool]$ForestComplete = $false
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaDnsRow -Scope ([string]$gap.Domain) -Item ("DNS server - {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No DNS server of it was read.')
    }
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        $rows += New-AdfaDnsRow -Item 'DNS health' -Status $script:Status.NotAssessed -Detail ("No domain controllers were enumerated, so no DNS server could be queried.{0} This is not a clean result." -f $why)
        return @($rows)
    }
    $module = [bool](Test-ModuleAvailable -Name 'DnsServer')
    if ($module) { Import-Module DnsServer -ErrorAction SilentlyContinue -Verbose:$false }
    $rpcPort = [int]$Config['RpcPort']
    $graded = @($Config['GradedZoneTypes'] | ForEach-Object { [string]$_ })
    # Per domain, in the order the DCs came: each DC with its read, or the cause it was not read.
    $byDomain = [ordered]@{}
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        $domainKey = $scope.ToLowerInvariant()
        if (-not $byDomain.Contains($domainKey)) { $byDomain[$domainKey] = [pscustomobject]@{ Scope = $scope; Servers = (New-Object System.Collections.ArrayList) } }
        $label = $dc
        if ([string]::IsNullOrWhiteSpace($dc)) { $label = '(unnamed)' }
        $entry = [pscustomobject]@{ Server = $label; Read = $false; Cause = ''; Raw = $null }
        $item = ("DNS server: {0}" -f $label)
        $dnsReach = ''
        if (-not [string]::IsNullOrWhiteSpace($dc)) { $dnsReach = Get-AdfaDcReachCause -HostName $dc }
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $entry.Cause = 'The inventory holds a domain controller with no host name, so there was nothing to connect to.'
        }
        elseif ($dnsReach) {
            # PORT-PLAN C14c: classified Unreachable for this run; not probed again.
            $entry.Cause = Get-AdfaDcGateText -Cause $dnsReach -NotRead 'no DNS server read was attempted'
        }
        elseif (-not $module) {
            $entry.Cause = 'The DnsServer PowerShell module is not installed on the host running the assessment (it comes with the DNS Server role or RSAT), so no DNS server was read.'
        }
        elseif (-not (Get-AdfaDcProbeGate -ComputerName $dc -Ports @($rpcPort) -TimeoutMs $PortTimeoutMs).Open[$rpcPort]) {
            $entry.Cause = ("Unreachable: RPC ({0}) did not answer within {1} ms, so no DNS server read was attempted." -f $rpcPort, $PortTimeoutMs)
        }
        else {
            $raw = Get-AdfaDnsServerRaw -ComputerName $dc
            if ($null -eq $raw -or -not $raw.Ok) {
                $message = ''; $code = ''
                if ($null -ne $raw) { $message = [string]$raw.Error; $code = [string]$raw.ErrorCode }
                $entry.Cause = Get-AdfaDnsReadCause -Class (Get-AdfaDnsReadErrorClass -Message $message -ErrorCode $code -Config $Config) -Message $message
            }
            else { $entry.Read = $true; $entry.Raw = $raw }
        }
        [void]$byDomain[$domainKey].Servers.Add($entry)
        if (-not $entry.Read) {
            $rows += New-AdfaDnsRow -Scope $scope -Item $item -Status $script:Status.NotAssessed -Detail $entry.Cause -Server $label
            continue
        }
        $raw = $entry.Raw
        $zones = @($raw.Zones | Where-Object { $_.IsAutoCreated -ne $true -and [string]$_.ZoneName -ne '' })
        $scavText = 'not read'
        if ($raw.ScavengingOk) {
            $on = Test-AdfaDnsServerScavenges -Interval $raw.ScavengingInterval
            if ($null -eq $on) { $scavText = 'not recognised' } elseif ($on) { $scavText = 'enabled' } else { $scavText = 'disabled' }
        }
        $rows += New-AdfaDnsRow -Scope $scope -Item $item -Status $script:Status.Info -Server $label -Evidence ([string]$raw.ScavengingError) `
            -Detail ("Read: {0} zone(s) not auto-created, {1} AD-integrated; server scavenging {2}." -f $zones.Count, @($zones | Where-Object { $_.IsDsIntegrated -eq $true }).Count, $scavText)
        foreach ($z in $zones) {
            $agingText = ''
            $agingEntry = $raw.Aging[([string]$z.ZoneName).ToLowerInvariant()]
            if ($null -ne $agingEntry) {
                if ($agingEntry.Ok) { $agingText = ("AgingEnabled={0}; NoRefresh={1}; Refresh={2}; ScavengeServers={3}" -f [string]$agingEntry.AgingEnabled, [string]$agingEntry.NoRefreshInterval, [string]$agingEntry.RefreshInterval, (@($agingEntry.ScavengeServers) -join ',')) }
                else { $agingText = ("not read: {0}" -f [string]$agingEntry.Error) }
            }
            $rows += New-AdfaDnsRow -Scope $scope -Item ("Zone configuration: {0} on {1}" -f [string]$z.ZoneName, $label) -Status $script:Status.Info `
                -Detail 'Zone configuration as this DNS server reports it (inventory, not graded).' -Server $label -Zone ([string]$z.ZoneName) `
                -ZoneType ([string]$z.ZoneType) -ReplicationScope ([string]$z.ReplicationScope) -DsIntegrated ([string]$z.IsDsIntegrated) `
                -DynamicUpdate ([string]$z.DynamicUpdate) -Aging $agingText
        }
        # Kept from earlier versions, unchanged.
        if ($raw.ForwardersOk) {
            $fwdIps = @($raw.Forwarders)
            if ($fwdIps.Count -eq 0) {
                $rows += New-AdfaDnsRow -Scope $scope -Item ("{0}: forwarders" -f $label) -Status $script:Status.Info -Server $label `
                    -Detail 'No conditional or global forwarders are configured on this DNS server. It resolves names outside its own zones through root hints, or not at all. That is a valid design - confirm it is the intended one, because a DC that cannot resolve external names is a common post-recovery state.'
            }
            else {
                $rows += New-AdfaDnsRow -Scope $scope -Item ("{0}: forwarders" -f $label) -Status $script:Status.Info -Server $label -Detail ("{0} forwarder(s): {1}" -f $fwdIps.Count, ($fwdIps -join ', '))
            }
        }
        else {
            $rows += New-AdfaDnsRow -Scope $scope -Item ("{0}: forwarders" -f $label) -Status $script:Status.NotAssessed -Server $label -Detail ("Forwarder list could not be read: {0}" -f [string]$raw.ForwarderError)
        }
        $insecureXfer = @($zones | Where-Object { [string]$_.SecureSecondaries -eq 'TransferAnyServer' })
        if ($insecureXfer.Count -gt 0) {
            $rows += New-AdfaDnsRow -Scope $scope -Item ("{0}: zone transfer" -f $label) -Status $script:Status.Warning -Server $label `
                -Detail ("Zones allowing transfer to ANY server: {0}" -f ((@($insecureXfer | ForEach-Object { [string]$_.ZoneName }) | Select-Object -First 8) -join ', '))
        }
    }
    # Each graded zone's replication scope, over every server of the run that reported it. Domain:
    # hosted by the DNS servers of one domain. Forest (or Custom): hosted beyond one domain, graded
    # once over every server of the run. Anything else (Legacy, none, not returned, or servers that
    # disagree): the hosting set is not known, so "no hosting server scavenges" is not asserted.
    $domainScopes = @($Config['DomainScopes'] | ForEach-Object { [string]$_ })
    $forestScopes = @($Config['ForestScopes'] | ForEach-Object { [string]$_ })
    $scopeSeen = @{}
    foreach ($domainKey in @($byDomain.Keys)) {
        foreach ($s in @($byDomain[$domainKey].Servers | Where-Object { $_.Read })) {
            foreach ($z in @($s.Raw.Zones)) {
                if ($z.IsAutoCreated -eq $true -or [string]$z.ZoneName -eq '' -or $graded -notcontains [string]$z.ZoneType) { continue }
                $k = ([string]$z.ZoneName).ToLowerInvariant()
                if (-not $scopeSeen.ContainsKey($k)) { $scopeSeen[$k] = @() }
                $v = ([string]$z.ReplicationScope).Trim()
                if (@($scopeSeen[$k]) -notcontains $v) { $scopeSeen[$k] = @(@($scopeSeen[$k]) + $v) }
            }
        }
    }
    $scopeClass = @{}
    foreach ($k in @($scopeSeen.Keys)) {
        $values = @($scopeSeen[$k])
        $class = 'Unknown'
        if ($values.Count -gt 0 -and @($values | Where-Object { $domainScopes -notcontains $_ }).Count -eq 0) { $class = 'Domain' }
        elseif ($values.Count -gt 0 -and @($values | Where-Object { $forestScopes -notcontains $_ }).Count -eq 0) { $class = 'Forest' }
        $scopeClass[$k] = [pscustomobject]@{ Class = $class; Values = (@($values | ForEach-Object { if ($_ -eq '') { '(not returned)' } else { $_ } }) -join ', ') }
    }
    # The run read every DNS server a forest-wide zone can have only when every domain of the forest
    # was in scope and every domain's DC list was read.
    $forestHostSet = ($ForestComplete -and @($InventoryFailures | Where-Object { $null -ne $_ }).Count -eq 0 -and [string]::IsNullOrWhiteSpace($EnumerationError))
    $allServers = @(foreach ($domainKey in @($byDomain.Keys)) { @($byDomain[$domainKey].Servers) })
    $observe = {
        param($ServerList, [string]$ZoneKey)
        $out = @()
        foreach ($s in @($ServerList)) {
            if (-not $s.Read) { $out += [pscustomobject]@{ Server = $s.Server; Read = $false; Cause = $s.Cause; IsDsIntegrated = $null; DynamicUpdate = ''; ServerScavenging = $null; AgingEnabled = $null }; continue }
            $z = @($s.Raw.Zones | Where-Object { ([string]$_.ZoneName).ToLowerInvariant() -eq $ZoneKey })
            if ($z.Count -eq 0) { continue }
            $scav = $null
            if ($s.Raw.ScavengingOk) { $scav = Test-AdfaDnsServerScavenges -Interval $s.Raw.ScavengingInterval }
            $agingEntry = $s.Raw.Aging[$ZoneKey]
            $aging = $null
            if ($null -ne $agingEntry -and $agingEntry.Ok) { $aging = $agingEntry.AgingEnabled }
            $out += [pscustomobject]@{ Server = $s.Server; Read = $true; Cause = ''; IsDsIntegrated = $z[0].IsDsIntegrated; DynamicUpdate = [string]$z[0].DynamicUpdate; ServerScavenging = $scav; AgingEnabled = $aging }
        }
        return $out
    }
    $forestGraded = @{}
    # Per domain and zone: every hosting server of the domain, read or not (of the run, for a
    # forest-wide zone).
    foreach ($domainKey in @($byDomain.Keys)) {
        $group = $byDomain[$domainKey]
        $scope = [string]$group.Scope
        $domainLabel = $scope
        if ($domainLabel -eq '') { $domainLabel = '(domain not known)' }
        $servers = @($group.Servers)
        $readServers = @($servers | Where-Object { $_.Read })
        $zoneNames = [ordered]@{}
        foreach ($s in $readServers) {
            foreach ($z in @($s.Raw.Zones)) {
                if ($z.IsAutoCreated -eq $true -or [string]$z.ZoneName -eq '' -or $graded -notcontains [string]$z.ZoneType) { continue }
                $k = ([string]$z.ZoneName).ToLowerInvariant()
                if (-not $zoneNames.Contains($k)) { $zoneNames[$k] = [string]$z.ZoneName }
            }
        }
        foreach ($k in @($zoneNames.Keys)) {
            $zoneName = [string]$zoneNames[$k]
            $class = $scopeClass[$k]
            $hostList = $servers
            $complete = $true
            $hostCause = ''
            if ($class.Class -eq 'Forest') {
                # Graded once, under the first domain that holds it, over every server of the run.
                if ($forestGraded.ContainsKey($k)) { continue }
                $forestGraded[$k] = $true
                $hostList = $allServers
                $complete = $forestHostSet
                $hostCause = ("its replication scope ({0}) reaches DNS servers in every domain of the forest, and this run did not read every domain's DNS servers" -f $class.Values)
            }
            elseif ($class.Class -ne 'Domain') {
                $complete = $false
                $hostCause = ("its replication scope ({0}) does not tell this tool which DNS servers host it, so a server this run did not read may host and scavenge it" -f $class.Values)
            }
            $obs = @(& $observe $hostList $k)
            $dyn = Get-AdfaDnsDynamicUpdateVerdict -Observations $obs -Config $Config
            $rows += New-AdfaDnsRow -Scope $scope -Item ("Zone dynamic update: {0}" -f $zoneName) -Status ([string]$dyn.Status) -Detail ([string]$dyn.Detail) -Evidence ([string]$dyn.Evidence) -Zone $zoneName -ReplicationScope ([string]$class.Values)
            $scavVerdict = Get-AdfaDnsScavengingVerdict -Observations $obs -Config $Config -HostSetComplete $complete -HostSetCause $hostCause
            $rows += New-AdfaDnsRow -Scope $scope -Item ("Zone scavenging: {0}" -f $zoneName) -Status ([string]$scavVerdict.Status) -Detail ([string]$scavVerdict.Detail) -Evidence ([string]$scavVerdict.Evidence) -Zone $zoneName -ReplicationScope ([string]$class.Values)
        }
        $popStatus = $script:Status.Info
        if ($readServers.Count -eq 0) { $popStatus = $script:Status.NotAssessed }
        $rows += New-AdfaDnsRow -Scope $scope -Item ("DNS zones (population): {0}" -f $domainLabel) -Status $popStatus `
            -Detail ("{0} primary zone(s) found; {1} of {2} DNS server(s) of this domain read. A zone replicated forest-wide is graded once, under the first domain that holds it, over every DNS server of the run." -f $zoneNames.Count, $readServers.Count, $servers.Count)
    }
    return @($rows)
}

function Get-AdfaDnsLocatorFinding {
    <#
    .SYNOPSIS
        The per-DC rows of DNS vs AD Consistency for one domain: DC locator records (DNS-003), DC A
        records (DNS-004) and the records that name no DC (DNS-005).
    .DESCRIPTION
        Two instruments per record and DNS server: the server's own zone (Get-AdfaDnsServerRecord)
        and a query to that server (Get-AdfaDnsResolverRecord). The configured IPv4 addresses come
        from each DC's adapters (Get-AdfaDcNetworkState, shared with the DC DNS Client rows). In the
        forest root domain the <guid>._msdcs CNAMEs of every DNS server's zone are read too, so a
        CNAME left by a removed DC is found.

        DECLARED POPULATION: every DC -Dcs names (one "DC locator records" and one "DC A record" row
        each), one "Stale DC record" row per record that names no DC, and one "Stale DC records
        (population)" row for the domain.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowNull()][AllowEmptyCollection()]$Dcs = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$DnsServers = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [AllowNull()][AllowEmptyCollection()]$DsaInventory = @(),
        [AllowNull()][AllowEmptyString()][string]$DsaError = '',
        [AllowNull()][AllowEmptyString()][string]$ForestRoot = '',
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [int]$OperationTimeoutSec = 90
    )
    $rows = @()
    $area = 'DnsAdConsistency'
    $servers = @($DnsServers | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Sort-Object -Unique)
    $module = [bool](Test-ModuleAvailable -Name 'DnsServer')
    if ($module) { Import-Module DnsServer -ErrorAction SilentlyContinue -Verbose:$false }
    $dcList = @($Dcs | Where-Object { $null -ne $_ })
    $dcHosts = @($dcList | ForEach-Object { $p = $_.PSObject.Properties['HostName']; if ($null -ne $p -and $null -ne $p.Value) { ([string]$p.Value).Trim() } } | Where-Object { $_ -ne '' })
    $unread = @()
    $candidates = @()
    # The graded SRV records, once per server and instrument.
    $srvEvidence = @{}
    foreach ($definition in @($Config['LocatorRecords'])) {
        $recordName = ([string](Get-AdfaConfigValue -Entry $definition -Name 'Name')) -f $DomainName
        $mnemonic = [string](Get-AdfaConfigValue -Entry $definition -Name 'Mnemonic')
        foreach ($srv in $servers) {
            $a = Get-AdfaDnsServerRecord -ComputerName $srv -Name $recordName -Type 'SRV' -Config $Config -ModuleAvailable $module -PortTimeoutMs $PortTimeoutMs
            $b = Get-AdfaDnsResolverRecord -Name $recordName -Type 'SRV' -Server $srv
            $srvEvidence[("{0}|{1}" -f $mnemonic, $srv)] = [pscustomobject]@{ Mnemonic = $mnemonic; Record = $recordName; Server = $srv; A = $a; B = $b }
            foreach ($t in @(@($a.Targets) + @($b.Targets))) { $candidates += [pscustomobject]@{ Name = $recordName; Type = 'SRV'; Target = [string]$t; Server = $srv } }
            if ($a.Outcome -eq 'Unread' -and $b.Outcome -eq 'Unread') { $unread += ("{0} on {1}" -f $mnemonic, $srv) }
        }
    }
    foreach ($dc in $dcList) {
        $hostProp = $dc.PSObject.Properties['HostName']
        $dcHost = ''
        if ($null -ne $hostProp -and $null -ne $hostProp.Value) { $dcHost = ([string]$hostProp.Value).Trim() }
        if ($dcHost -eq '') { continue }
        $roProp = $dc.PSObject.Properties['IsReadOnly']
        $readOnly = $null
        if ($null -ne $roProp) { $readOnly = ConvertTo-AdfaDnsBool -Value $roProp.Value }
        $hostKey = $dcHost.TrimEnd('.').ToLowerInvariant()
        # DNS-003: is this DC a target of each graded record, per server and instrument.
        $checks = @()
        foreach ($k in @($srvEvidence.Keys | Sort-Object)) {
            $e = $srvEvidence[$k]
            $forDc = { param($Answer)
                if ($Answer.Outcome -eq 'Unread') { return 'Unread' }
                if ($Answer.Outcome -eq 'Present' -and @(@($Answer.Targets) | ForEach-Object { ([string]$_).TrimEnd('.').ToLowerInvariant() }) -contains $hostKey) { return 'Present' }
                return 'Absent' }
            $state = Get-AdfaDnsEvidenceState -ServerOutcome (& $forDc $e.A) -ResolverOutcome (& $forDc $e.B)
            $cause = (@(@($e.A.Cause, $e.B.Cause) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) -join ' '
            $checks += [pscustomobject]@{ Record = $e.Mnemonic; Server = $e.Server; State = $state; Cause = $cause }
        }
        $loc = Get-AdfaDcLocatorVerdict -IsReadOnly $readOnly -Checks $checks -Config $Config
        $rows += New-AdfaDnsRow -Area $area -Scope $DomainName -Item ("DC locator records: {0}" -f $dcHost) -Status ([string]$loc.Status) -Detail ([string]$loc.Detail) `
            -Evidence ([string]$loc.Evidence) -HostName $dcHost -RecordType 'SRV' -RecordName ((@($Config['LocatorRecords'] | ForEach-Object { ([string](Get-AdfaConfigValue -Entry $_ -Name 'Name')) -f $DomainName })) -join ', ')
        # DNS-004: the A records for the DC's host name against its adapters.
        $net = Get-AdfaDcNetworkState -ComputerName $dcHost -Config $Config -Credential $Credential -PortTimeoutMs $PortTimeoutMs -OperationTimeoutSec $OperationTimeoutSec
        $configured = $null
        $configuredCause = ''
        if ($net.Status -eq 'Read') { $configured = @($net.IPv4) } else { $configuredCause = [string]$net.Cause }
        $answers = @()
        foreach ($srv in $servers) {
            $a = Get-AdfaDnsServerRecord -ComputerName $srv -Name $dcHost -Type 'A' -Config $Config -ModuleAvailable $module -PortTimeoutMs $PortTimeoutMs
            $b = Get-AdfaDnsResolverRecord -Name $dcHost -Type 'A' -Server $srv
            $addresses = @(@(@($a.Targets) + @($b.Targets)) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Sort-Object -Unique)
            $answers += [pscustomobject]@{ Server = $srv; State = (Get-AdfaDnsEvidenceState -ServerOutcome ([string]$a.Outcome) -ResolverOutcome ([string]$b.Outcome)); Addresses = $addresses }
        }
        $aVerdict = Get-AdfaDcARecordVerdict -ConfiguredIPv4 $configured -ConfiguredCause $configuredCause -Answers $answers -Config $Config
        $rows += New-AdfaDnsRow -Area $area -Scope $DomainName -Item ("DC A record: {0}" -f $dcHost) -Status ([string]$aVerdict.Status) -Detail ([string]$aVerdict.Detail) `
            -Evidence ([string]$aVerdict.Evidence) -HostName $dcHost -RecordType 'A' -RecordName $dcHost -ConfiguredIPv4 ((@($configured) | Where-Object { $null -ne $_ }) -join ', ')
    }
    # DNS-005: SRV targets that name no DC, and, in the forest root, <guid>._msdcs CNAMEs of no DSA.
    $known = @(@($dcHosts) + @(@($DsaInventory | Where-Object { $null -ne $_ }) | ForEach-Object { $p = $_.PSObject.Properties['DnsHostName']; if ($null -ne $p -and $null -ne $p.Value) { [string]$p.Value } }) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $guids = @(@($DsaInventory | Where-Object { $null -ne $_ }) | ForEach-Object { $p = $_.PSObject.Properties['DsaGuid']; if ($null -ne $p -and $null -ne $p.Value) { [string]$p.Value } } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $isRoot = (-not [string]::IsNullOrWhiteSpace($ForestRoot) -and $ForestRoot.Trim().TrimEnd('.').ToLowerInvariant() -eq $DomainName.Trim().TrimEnd('.').ToLowerInvariant())
    # A forest has at least one NTDS Settings object; an empty answer is a read that saw nothing, and
    # judging CNAMEs against it would call every DSA CNAME stale.
    $dsaProblem = [string]$DsaError
    if ($isRoot -and [string]::IsNullOrWhiteSpace($dsaProblem) -and $guids.Count -eq 0) { $dsaProblem = 'no NTDS Settings object was returned, so no DSA GUID is known' }
    if ($isRoot -and [string]::IsNullOrWhiteSpace($dsaProblem)) {
        $msdcs = ("{0}.{1}" -f [string]$script:Config.MsdcsZoneLabel, $ForestRoot.Trim().TrimEnd('.')).ToLowerInvariant()
        foreach ($srv in $servers) {
            if (-not $module) { $unread += ("CNAME on {0}: the DnsServer module is not installed" -f $srv); continue }
            $srvGate = Get-AdfaDcProbeGate -ComputerName $srv -Ports @([int]$Config['RpcPort']) -TimeoutMs $PortTimeoutMs
            if ($srvGate.Cause) { $unread += ("CNAME on {0}: {1}" -f $srv, $srvGate.Cause.Trim().TrimEnd('.')); continue }
            if (-not $srvGate.Open[[int]$Config['RpcPort']]) { $unread += ("CNAME on {0}: unreachable" -f $srv); continue }
            # The zone that holds <guid>._msdcs.<forest> on this server, or why none can be read: no
            # zone, a stub or forwarder zone, or a delegation of _msdcs out of the zone it holds.
            $where = Resolve-AdfaDnsServerZone -ComputerName $srv -Name ("00000000-0000-0000-0000-000000000000.{0}" -f $msdcs) -Config $Config
            if (-not $where.Ok) { $unread += ("CNAME on {0}: {1}" -f $srv, ([string]$where.Cause).TrimEnd('.')); continue }
            $read = Get-AdfaDnsRecordSetRaw -ComputerName $srv -ZoneName ([string]$where.Zone) -RRType 'CName' -Config $Config
            if ($read.Outcome -eq 'Error') { $unread += ("CNAME on {0}: {1}" -f $srv, (Get-AdfaDnsReadErrorClass -Message $read.Error -ErrorCode $read.ErrorCode -Config $Config)); continue }
            foreach ($r in @($read.Records)) {
                $fqdn = [string]$where.Zone
                if ([string]$r.HostName -ne '@' -and [string]$r.HostName -ne '') { $fqdn = ("{0}.{1}" -f [string]$r.HostName, [string]$where.Zone) }
                if ($fqdn.ToLowerInvariant().EndsWith('.' + $msdcs)) { $candidates += [pscustomobject]@{ Name = $fqdn; Type = 'CNAME'; Target = [string]$r.Target; Server = $srv } }
            }
        }
    }
    $staleDsaError = ''
    if ($isRoot) { $staleDsaError = $dsaProblem }
    $stale = Get-AdfaStaleDnsRecordVerdict -Candidates $candidates -KnownDcHosts $known -KnownDsaGuids $guids -DsaError $staleDsaError -Unread $unread -Config $Config
    foreach ($s in @($stale.Stale)) {
        $label = [string]$s.Target
        if ([string]$s.Type -eq 'CNAME') { $label = [string]$s.Name }
        $rows += New-AdfaDnsRow -Area $area -Scope $DomainName -Item ("Stale DC record: {0}" -f $label) -Status ([string]$Config['StaleRecordStatus']) `
            -Detail ("This {0} record names a host or DSA GUID that matches no domain controller in the directory (read-only DCs included). Microsoft: remove references to stale domain controllers. {1}" -f [string]$s.Type, (Get-AdfaDnsGradeText -Status ([string]$Config['StaleRecordStatus']) -Config $Config)) `
            -RecordName ([string]$s.Name) -RecordType ([string]$s.Type) -RecordData ([string]$s.Target) -Server ((@($s.Servers)) -join ', ')
    }
    $rows += New-AdfaDnsRow -Area $area -Scope $DomainName -Item ("Stale DC records (population): {0}" -f $DomainName) -Status ([string]$stale.Status) -Detail ([string]$stale.Detail) `
        -Evidence ((@($unread)) -join '; ')
    return @($rows)
}

function Get-AdfaDcDnsClient {
    <#
    .SYNOPSIS
        DC DNS Client (rows of the DomainControllers section, ADA-INV-016): each DC's DNS server list
        from its enabled adapters, with the single-server flag Microsoft documents.
    .DESCRIPTION
        One read per DC (Get-AdfaDcNetworkState, shared with the DC A record check). Unreachable,
        access denied and any other failure are separate Not Assessed causes. -ForestComplete: every
        domain of the forest is in -ScopedDomains (Invoke-Main); only then, with no inventory failure,
        is the run's DC count the forest's, which the single-server grade needs. DECLARED POPULATION:
        the domains named in -ScopedDomains (DC rows, or a "DNS client - <domain>" Not Assessed row)
        and every DC (one "DNS client: <dc>" row), plus a "DNS client (population)" row per domain.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [hashtable]$Config = $script:Config.Dns,
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [int]$OperationTimeoutSec = 90,
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @(),
        [bool]$ForestComplete = $false
    )
    $rows = @()
    $area = 'DnsClient'
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaDnsRow -Area $area -Scope ([string]$gap.Domain) -Item ("DNS client - {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No adapter of its DCs was read.')
    }
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        $rows += New-AdfaDnsRow -Area $area -Item 'DNS client' -Status $script:Status.NotAssessed -Detail ("No domain controllers were enumerated, so no adapter was read.{0} This is not a clean result." -f $why)
        return @($rows)
    }
    # First every read, so each DC is judged against every DC address known to the run.
    $reads = @()
    $knownDc = @()
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dirIp = ''
        if ($target -isnot [string]) { $ipProp = $target.PSObject.Properties['IPv4Address']; if ($null -ne $ipProp -and $null -ne $ipProp.Value) { $dirIp = ([string]$ipProp.Value).Trim() } }
        $state = $null
        if (-not [string]::IsNullOrWhiteSpace([string]$named.HostName)) {
            $state = Get-AdfaDcNetworkState -ComputerName ([string]$named.HostName) -Config $Config -Credential $Credential -PortTimeoutMs $PortTimeoutMs -OperationTimeoutSec $OperationTimeoutSec
        }
        if ($dirIp -ne '' -and $knownDc -notcontains $dirIp) { $knownDc += $dirIp }
        if ($null -ne $state -and $state.Status -eq 'Read') { foreach ($ip in @($state.IPv4)) { if ($knownDc -notcontains [string]$ip) { $knownDc += [string]$ip } } }
        $reads += [pscustomobject]@{ HostName = [string]$named.HostName; Scope = [string]$named.Scope; DirIp = $dirIp; State = $state }
    }
    $dcCount = $reads.Count
    # The run's DC count is the forest's only when every domain of the forest was in scope and every
    # scoped domain's DC list was read; otherwise "the only DC" is not measured (KB 4013's
    # "tolerable in a forest with only one domain controller" is about the forest).
    $dcCountIsForest = ($ForestComplete -and @($InventoryFailures | Where-Object { $null -ne $_ }).Count -eq 0 -and [string]::IsNullOrWhiteSpace($EnumerationError))
    $byDomain = [ordered]@{}
    foreach ($r in $reads) {
        $label = $r.HostName
        if ([string]::IsNullOrWhiteSpace($label)) { $label = '(unnamed)' }
        $key = $r.Scope.ToLowerInvariant()
        if (-not $byDomain.Contains($key)) { $byDomain[$key] = [pscustomobject]@{ Scope = $r.Scope; Total = 0; Read = 0 } }
        $byDomain[$key].Total++
        if ($null -eq $r.State) {
            $rows += New-AdfaDnsRow -Area $area -Scope $r.Scope -Item ("DNS client: {0}" -f $label) -Status $script:Status.NotAssessed -HostName $label `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and no adapter was read.'
            continue
        }
        if ($r.State.Status -ne 'Read') {
            $rows += New-AdfaDnsRow -Area $area -Scope $r.Scope -Item ("DNS client: {0}" -f $label) -Status $script:Status.NotAssessed -HostName $label -Detail ([string]$r.State.Cause)
            continue
        }
        $byDomain[$key].Read++
        $self = @(@($r.State.IPv4) + @($r.DirIp) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        # Not wrapped in @(): a list that was not returned stays $null, so the verdict reports it
        # Not Assessed instead of grading an empty list it never saw.
        $v = Get-AdfaDcDnsClientVerdict -DnsServers $r.State.DnsServers -Cause ([string]$r.State.DnsCause) -SelfAddresses $self -KnownDcAddresses $knownDc `
            -DcCount $dcCount -DcCountIsForest $dcCountIsForest -Config $Config
        $rows += New-AdfaDnsRow -Area $area -Scope $r.Scope -Item ("DNS client: {0}" -f $label) -Status ([string]$v.Status) -Detail ([string]$v.Detail) -HostName $label `
            -ConfiguredIPv4 ((@($r.State.IPv4)) -join ', ') -DnsServers ((@($r.State.DnsServers)) -join ', ')
    }
    foreach ($key in @($byDomain.Keys)) {
        $g = $byDomain[$key]
        $domainLabel = [string]$g.Scope
        if ($domainLabel -eq '') { $domainLabel = '(domain not known)' }
        $status = $script:Status.Info
        if ($g.Read -lt $g.Total) { $status = $script:Status.NotAssessed }
        $rows += New-AdfaDnsRow -Area $area -Scope ([string]$g.Scope) -Item ("DNS client (population): {0}" -f $domainLabel) -Status $status `
            -Detail ("{0} of {1} domain controller(s) of this domain had their adapters read." -f $g.Read, $g.Total)
    }
    return @($rows)
}

function Export-AdfaDnsRecord {
    <#
    .SYNOPSIS
        DNS Record Export (opt-in, ADA-INV-014): every zone of every DC's DNS server to one CSV per
        zone and server under the run's csv folder, capped per zone, with a row saying how many
        records were exported and whether the cap was hit.
    .DESCRIPTION
        Get-DnsServerResourceRecord -ZoneName per zone (Learn: "gets all DNS server resource records
        in a zone"). The cap is RecordExportCap (50000 per zone, a tool default; Microsoft publishes
        none). Files: csv\DnsRecords_<server>_<zone>.csv. Opt-in because a zone can hold many records.
    .OUTPUTS
        [pscustomobject[]] summary rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [hashtable]$Config = $script:Config.Dns,
        [Parameter(Mandatory)][string]$CsvPath,
        [int]$PortTimeoutMs = 1200,
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $rows = @()
    $area = 'DnsRecordExport'
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaDnsRow -Area $area -Scope ([string]$gap.Domain) -Item ("Record export - {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No zone of it was exported.')
    }
    if ($targets.Count -eq 0) {
        $rows += New-AdfaDnsRow -Area $area -Item 'Record export' -Status $script:Status.NotAssessed -Detail 'No domain controllers were enumerated, so no DNS server was exported. This is not a clean result.'
        return @($rows)
    }
    $cap = [int]$Config['RecordExportCap']
    $module = [bool](Test-ModuleAvailable -Name 'DnsServer')
    if ($module) { Import-Module DnsServer -ErrorAction SilentlyContinue -Verbose:$false }
    $rpcPort = [int]$Config['RpcPort']
    $total = 0; $zonesDone = 0; $capped = 0; $serversDone = 0
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        $label = $dc
        if ([string]::IsNullOrWhiteSpace($dc)) { $label = '(unnamed)' }
        $item = ("Record export (population): {0}" -f $label)
        $cause = ''
        if ([string]::IsNullOrWhiteSpace($dc)) { $cause = 'The inventory holds a domain controller with no host name, so nothing was exported.' }
        elseif (-not $module) { $cause = 'The DnsServer PowerShell module is not installed on the host running the assessment, so nothing was exported.' }
        else {
            $exportGate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @($rpcPort) -TimeoutMs $PortTimeoutMs
            if ($exportGate.Cause) { $cause = Get-AdfaDcGateText -Cause $exportGate.Cause -NotRead 'nothing was exported' }
            elseif (-not $exportGate.Open[$rpcPort]) { $cause = ("Unreachable: RPC ({0}) did not answer within {1} ms, so nothing was exported." -f $rpcPort, $PortTimeoutMs) }
        }
        $zones = $null
        if ($cause -eq '') {
            $zones = Get-AdfaDnsServerZoneNames -ComputerName $dc
            if (-not $zones.Ok) { $cause = Get-AdfaDnsReadCause -Class (Get-AdfaDnsReadErrorClass -Message $zones.Error -ErrorCode $zones.ErrorCode -Config $Config) -Message $zones.Error }
        }
        if ($cause -ne '') {
            $rows += New-AdfaDnsRow -Area $area -Scope $scope -Item $item -Status $script:Status.NotAssessed -Detail $cause -Server $label
            continue
        }
        $serversDone++
        $ok = 0; $failed = 0
        foreach ($zoneName in @($zones.Names)) {
            $read = Get-AdfaDnsRecordSetRaw -ComputerName $dc -ZoneName ([string]$zoneName) -Cap $cap -Config $Config
            $zoneItem = ("Record export: {0} on {1}" -f [string]$zoneName, $label)
            if ($read.Outcome -eq 'Error') {
                $failed++
                $rows += New-AdfaDnsRow -Area $area -Scope $scope -Item $zoneItem -Status $script:Status.NotAssessed -Server $label -Zone ([string]$zoneName) `
                    -Detail (Get-AdfaDnsReadCause -Class (Get-AdfaDnsReadErrorClass -Message $read.Error -ErrorCode $read.ErrorCode -Config $Config) -Message $read.Error)
                continue
            }
            $records = @($read.Records)
            if ($records.Count -gt 0) {
                $file = Join-Path $CsvPath ("DnsRecords_{0}_{1}.csv" -f (New-SafeFileName $label), (New-SafeFileName ([string]$zoneName)))
                Save-Csv -InputObject @($records | ForEach-Object { [pscustomobject]@{ Server = $label; Zone = [string]$zoneName; HostName = $_.HostName; RecordType = $_.RecordType; TimeToLive = $_.TimeToLive; Timestamp = $_.Timestamp; RecordData = $_.RecordData } }) -Path $file
            }
            $ok++
            $zonesDone++
            $total += $records.Count
            if ($read.Truncated) { $capped++ }
            $hit = 'no'
            if ($read.Truncated) { $hit = 'yes' }
            $rows += New-AdfaDnsRow -Area $area -Scope $scope -Item $zoneItem -Status $script:Status.Info -Server $label -Zone ([string]$zoneName) `
                -Detail ("Exported {0} of {1} record(s); cap {2} per zone (a tool default, not a Microsoft value); cap reached: {3}." -f $records.Count, [int]$read.RealCount, $cap, $hit)
        }
        $popStatus = $script:Status.Info
        if ($failed -gt 0) { $popStatus = $script:Status.NotAssessed }
        $rows += New-AdfaDnsRow -Area $area -Scope $scope -Item $item -Status $popStatus -Server $label `
            -Detail ("{0} zone(s) listed; {1} exported, {2} not read." -f @($zones.Names).Count, $ok, $failed)
    }
    # Nothing exported from any server is not a clean total.
    $totalStatus = $script:Status.Info
    if ($serversDone -eq 0) { $totalStatus = $script:Status.NotAssessed }
    $rows += New-AdfaDnsRow -Area $area -Item 'Record export: total' -Status $totalStatus `
        -Detail ("{0} record(s) exported from {1} zone(s) on {2} DNS server(s); cap reached in {3} zone(s)." -f $total, $zonesDone, $serversDone, $capped)
    return @($rows)
}

function Merge-AdfaDnsConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in DNS table, with validation. The Dns validator for
        -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: the seven statuses, each within its own set, and RecordExportCap:

            { "Dns": { "NonsecureStatus": "Warning", "RecordExportCap": 10000 } }

          NonsecureStatus      Fail | Warning
          ScavengingOffStatus, AgingOffStatus, ARecordStatus, StaleRecordStatus, SingleServerStatus
                               Warning | Info
          OneInstrumentStatus  Warning | Not Assessed
          RecordExportCap      a whole number from 1 to 1000000

        What it cannot: the record names, the zone types, the patterns, the error codes, the ports and
        the sources. Every such key is refused as unknown, so a file can never make a status Pass,
        read another record or turn a failed read into an absence.

        Refused with the reason: an override that is not one object, an empty object, an unknown key,
        a key named twice, a null, a status that is not a string or not in its set, a cap that is not
        a JSON number or not a whole number in range. Provenance follows the keys.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }
    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("DNS config override must be a single object with named keys (for example {{ ""NonsecureStatus"": ""Warning"" }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) { throw 'DNS config override is an empty object. It names no key, so it would change nothing while appearing to be in force.' }
    $statusSets = [ordered]@{
        NonsecureStatus     = @('Fail', 'Warning')
        ScavengingOffStatus = @('Warning', 'Info')
        AgingOffStatus      = @('Warning', 'Info')
        ARecordStatus       = @('Warning', 'Info')
        StaleRecordStatus   = @('Warning', 'Info')
        OneInstrumentStatus = @('Warning', 'Not Assessed')
        SingleServerStatus  = @('Warning', 'Info')
    }
    $known = @(@($statusSets.Keys) + 'RecordExportCap')
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("DNS config override names an unknown key '{0}'. Known keys: {1}. The record names, the zone types, the patterns, the error codes, the ports and the sources cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        if ($supplied -contains $name) { throw ("DNS config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) { throw ("DNS config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name) }
        if ($name -eq 'RecordExportCap') {
            if ($value -is [array] -or $numericTypes -notcontains $value.GetType()) {
                throw ("DNS config override sets '{0}' to a {1}. It must be a JSON number, written without quotes." -f $name, $value.GetType().Name)
            }
            $number = [double]$value
            if ([double]::IsNaN($number) -or [double]::IsInfinity($number) -or $number -ne [math]::Floor($number) -or $number -lt 1 -or $number -gt 1000000) {
                throw ("DNS config override sets '{0}' to {1}. It must be a whole number from 1 to 1000000 (records per zone)." -f $name, $number.ToString('0.####', $inv))
            }
            $merged[$name] = [int]$number
        }
        else {
            if ($value -isnot [string]) { throw ("DNS config override sets '{0}' to a {1}. It must be a string: one of {2}." -f $name, $value.GetType().Name, (@($statusSets[$name]) -join ', ')) }
            $allowed = @($statusSets[$name] | Where-Object { $_ -eq $value.Trim() })
            if ($allowed.Count -eq 0) { throw ("DNS config override sets '{0}' to '{1}'. It must be one of {2}." -f $name, $value, (@($statusSets[$name]) -join ', ')) }
            $merged[$name] = [string]$allowed[0]
        }
        $supplied += $name
    }
    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
    $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
    if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
    $merged['ThresholdSource'] = $text
    return $merged
}

# ===========================================================================
# region SYSVOL / DFSR
# ===========================================================================

function Get-AdfaSysvolHealth {
    <#
    .SYNOPSIS
        SYSVOL replication migration state (dfsrmig) and per-DC SysVolCheck.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([int]$TimeoutSeconds = 90, [int]$Retries = 2, [int]$RetryDelaySeconds = 2)
    $rows = @()
    if (Test-CommandAvailable -Name 'dfsrmig.exe') {
        $r = Invoke-ExternalCommand -FilePath 'dfsrmig.exe' -Arguments '/getglobalstate' -TimeoutSeconds $TimeoutSeconds -Retries $Retries -RetryDelaySeconds $RetryDelaySeconds
        $state = $script:Status.NotAssessed; $detail = ($r.StdOut -split "`n" | Where-Object { $_.Trim() } | Select-Object -First 2) -join ' '
        if ($r.StdOut -match "'Eliminated'") { $state = $script:Status.Pass; $detail = 'SYSVOL migrated to DFSR (Eliminated state).' }
        elseif ($r.StdOut -match "'Prepared'|'Redirected'|'Start'") { $state = $script:Status.Warning; $detail = 'SYSVOL DFSR migration not fully complete (still FRS-capable).' }
        $rows += New-Finding -Area 'SYSVOL' -Item 'DFSR migration global state' -Status $state -Detail $detail
    }
    else {
        $rows += New-Finding -Area 'SYSVOL' -Item 'DFSR migration global state' -Status $script:Status.NotAssessed -Detail 'dfsrmig.exe not available on this host.'
    }
    return @($rows)
}

# ===========================================================================
# region GPO
# ===========================================================================

function Get-AdfaGpoInventory {
    <#
    .SYNOPSIS
        GPO inventory: links and unlinked GPOs (GroupPolicy module; degrades if absent). WMI
        filters are not read. The version check of the same section is Get-AdfaGpoVersion.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName)
    if (-not (Test-ModuleAvailable -Name 'GroupPolicy')) {
        return @(New-Finding -Area 'GPO' -Item 'GroupPolicy module' -Status $script:Status.NotAssessed -Detail 'RSAT GroupPolicy module not installed on this host.' -Scope $DomainName)
    }
    Import-Module GroupPolicy -ErrorAction SilentlyContinue -Verbose:$false
    $rows = @()
    try {
        $gpos = @(Get-GPO -All -Domain $DomainName -ErrorAction Stop)
        $rows += [pscustomobject]@{ Scope = $DomainName; GPOName = '(total)'; Status = $script:Status.Info; Detail = ("{0} GPOs" -f $gpos.Count) }
        foreach ($g in $gpos) {
            [xml]$rep = $g.GenerateReport('Xml')
            # An unlinked GPO's report has no LinksTo element; under StrictMode reading
            # $rep.GPO.LinksTo directly throws, which sent every domain with one unlinked GPO to the
            # catch-all. Read through PSObject.Properties: absent is $null.
            $linksNode = $null
            $linksProp = $rep.GPO.PSObject.Properties['LinksTo']
            if ($null -ne $linksProp) { $linksNode = $linksProp.Value }
            $linked = $null -ne $linksNode
            $rows += [pscustomobject]@{
                Scope   = $DomainName
                GPOName = $g.DisplayName
                Status  = $(if ($linked) { $script:Status.Info } else { $script:Status.Warning })
                Detail  = $(if ($linked) { ("Linked: {0}" -f (@($linksNode.SOMPath) -join ', ')) } else { 'Unlinked GPO (candidate for cleanup).' })
            }
        }
    }
    catch {
        # Fail closed, in the four columns this row always had (Scope, GPOName, Status, Detail). The
        # class leads the Detail, as in the C4-C8 rows: unreachable, access denied and timed out are
        # different results. Rows written before the failure are kept and counted.
        $message = [string]$_.Exception.Message
        $type = [string]$_.Exception.GetType().FullName
        $lead = Get-AdfaGpoFailureLead -Class (Get-AdfaDirectoryReadErrorClass -Message $message -TypeName $type)
        $detail = ("{0}: the GPO inventory of {1} could not be completed ({2} row(s) were written before the failure), so it is not a clean result. Reported by Get-GPO or the GPO report: {3} (exception type: {4})" -f $lead, $DomainName, @($rows).Count, $message.Trim(), $type)
        $rows += [pscustomobject]@{ Scope = $DomainName; GPOName = '(enumeration failed)'; Status = $script:Status.NotAssessed; Detail = $detail }
    }
    return @($rows)
}

# ---------------------------------------------------------------------------
# GPO version consistency (PORT-PLAN C8): the version of each GPO in the directory against the
# version in its GPT.INI in SYSVOL, both read from the domain's PDC emulator. Rows of the Gpo
# section (report section "GPO Inventory"). Sources and tool defaults: $script:Config.Gpo.
# ---------------------------------------------------------------------------

function New-AdfaGpoVersionRow {
    <#
    .SYNOPSIS
        Pure: one GPO version row. Every row has the same columns, so a consumer never has to test
        whether a column exists.
    .DESCRIPTION
        The GPO's display name is free text that anyone allowed to edit the GPO can set, and the
        gPCFileSysPath value is a path the directory holds: both go in their own columns (GPOName,
        FileSysPath), never in Item or Detail, because the consolidated findings choose a
        recommendation from Item and Detail. Item carries only text this tool writes and the GPO's
        GUID. A number that was not measured is an empty string, never 0.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = '',
        [AllowEmptyString()][string]$Evidence = '',
        [AllowEmptyString()][string]$GPOName = '',
        [AllowEmptyString()][string]$GpoGuid = '',
        [AllowEmptyString()][string]$ReadFrom = '',
        [AllowNull()]$DsVersion = $null,
        [AllowNull()]$SysvolVersion = $null,
        [AllowNull()]$Flags = $null,
        [AllowEmptyString()][string]$FlagsLabel = '',
        [AllowEmptyString()][string]$GptIniPath = '',
        [AllowEmptyString()][string]$FileSysPath = '',
        [AllowEmptyString()][string]$Encoding = '',
        [AllowNull()]$Population = $null,
        [AllowNull()]$Compared = $null,
        [AllowNull()]$Mismatched = $null,
        [AllowNull()]$NotAssessedCount = $null,
        [AllowNull()]$FoldersWithoutContainer = $null
    )
    $row = New-Finding -Scope $Scope -Area 'GPO' -Item $Item -Status $Status -Detail $Detail
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $asText = { param($Number) if ($null -eq $Number) { return '' } return ([int64]$Number).ToString($inv) }
    $dsUser = ''; $dsComputer = ''; $svUser = ''; $svComputer = ''
    if ($null -ne $DsVersion) { $split = Split-AdfaGpoVersion -Version ([int64]$DsVersion); $dsUser = & $asText $split.User; $dsComputer = & $asText $split.Computer }
    if ($null -ne $SysvolVersion) { $split = Split-AdfaGpoVersion -Version ([int64]$SysvolVersion); $svUser = & $asText $split.User; $svComputer = & $asText $split.Computer }
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    $row | Add-Member -NotePropertyName 'Evidence' -NotePropertyValue $Evidence
    $row | Add-Member -NotePropertyName 'GPOName' -NotePropertyValue $GPOName
    $row | Add-Member -NotePropertyName 'GpoGuid' -NotePropertyValue $GpoGuid
    $row | Add-Member -NotePropertyName 'ReadFrom' -NotePropertyValue $ReadFrom
    $row | Add-Member -NotePropertyName 'DsVersion' -NotePropertyValue (& $asText $DsVersion)
    $row | Add-Member -NotePropertyName 'DsUser' -NotePropertyValue $dsUser
    $row | Add-Member -NotePropertyName 'DsComputer' -NotePropertyValue $dsComputer
    $row | Add-Member -NotePropertyName 'SysvolVersion' -NotePropertyValue (& $asText $SysvolVersion)
    $row | Add-Member -NotePropertyName 'SysvolUser' -NotePropertyValue $svUser
    $row | Add-Member -NotePropertyName 'SysvolComputer' -NotePropertyValue $svComputer
    $row | Add-Member -NotePropertyName 'Flags' -NotePropertyValue (& $asText $Flags)
    $row | Add-Member -NotePropertyName 'FlagsLabel' -NotePropertyValue $FlagsLabel
    $row | Add-Member -NotePropertyName 'GptIniPath' -NotePropertyValue $GptIniPath
    $row | Add-Member -NotePropertyName 'FileSysPath' -NotePropertyValue $FileSysPath
    $row | Add-Member -NotePropertyName 'Encoding' -NotePropertyValue $Encoding
    $row | Add-Member -NotePropertyName 'Population' -NotePropertyValue (& $asText $Population)
    $row | Add-Member -NotePropertyName 'Compared' -NotePropertyValue (& $asText $Compared)
    $row | Add-Member -NotePropertyName 'Mismatched' -NotePropertyValue (& $asText $Mismatched)
    $row | Add-Member -NotePropertyName 'NotAssessedCount' -NotePropertyValue (& $asText $NotAssessedCount)
    $row | Add-Member -NotePropertyName 'FoldersWithoutContainer' -NotePropertyValue (& $asText $FoldersWithoutContainer)
    return $row
}

function ConvertTo-AdfaGpoVersionNumber {
    <#
    .SYNOPSIS
        Pure: a GPO version (versionNumber, or the Version value of GPT.INI) as a whole number from 0
        to 4294967295, or the reason it is not one.
    .DESCRIPTION
        MS-GPOL defines both as a 32-bit integer of a 16-bit user half and a 16-bit computer half.
        versionNumber has the Enumeration syntax, a signed Int32, so a user half of 0x8000 or more
        reads as a negative number: a value from -2147483648 to -1 is taken as its 32-bit pattern
        (Masked = $true). That is an inference from the type, not a Learn statement. A value outside
        -2147483648..4294967295 does not fit in 32 bits and is refused (OutOfRange).

        Causes: NotReturned (null, or an empty collection), MultiValued (more than one value),
        NotANumber (not a whole number), OutOfRange.
    .OUTPUTS
        [pscustomobject] Ok, Version ([int64] or $null), Cause, Masked.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Value)
    $out = [pscustomobject]@{ Ok = $false; Version = $null; Cause = ''; Masked = $false }
    if ($null -eq $Value) { $out.Cause = 'NotReturned'; return $out }
    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        $items = @($Value)
        if ($items.Count -eq 0) { $out.Cause = 'NotReturned'; return $out }
        if ($items.Count -gt 1) { $out.Cause = 'MultiValued'; return $out }
        $Value = $items[0]
        if ($null -eq $Value) { $out.Cause = 'NotReturned'; return $out }
    }
    $number = [int64]0
    $integerTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64])
    if ($integerTypes -contains $Value.GetType()) { $number = [int64]$Value }
    elseif ($Value -is [uint64]) {
        if ([uint64]$Value -gt [uint64]4294967295) { $out.Cause = 'OutOfRange'; return $out }
        $number = [int64]$Value
    }
    elseif ($Value -is [string]) {
        $text = $Value.Trim()
        if ($text -notmatch '^-?[0-9]+$') { $out.Cause = 'NotANumber'; return $out }
        if (-not [int64]::TryParse($text, [System.Globalization.NumberStyles]::AllowLeadingSign, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$number)) {
            $out.Cause = 'OutOfRange'; return $out
        }
    }
    else { $out.Cause = 'NotANumber'; return $out }
    if ($number -lt [int64]-2147483648 -or $number -gt [int64]4294967295) { $out.Cause = 'OutOfRange'; return $out }
    if ($number -lt 0) { $number = $number + [int64]4294967296; $out.Masked = $true }
    $out.Version = [int64]$number
    $out.Ok = $true
    return $out
}

function Split-AdfaGpoVersion {
    <#
    .SYNOPSIS
        Pure: the user half (upper 16 bits) and the computer half (lower 16 bits) of a GPO version,
        as MS-GPOL publishes them.
    .OUTPUTS
        [pscustomobject] User, Computer.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][int64]$Version)
    $v = $Version -band [int64]4294967295
    return [pscustomobject]@{ User = [int64](($v -shr 16) -band 65535); Computer = [int64]($v -band 65535) }
}

function ConvertFrom-AdfaGptIniVersion {
    <#
    .SYNOPSIS
        Pure: the GPO file system version from the bytes of a GPT.INI - the Version key of its
        [General] section - or the reason there is none.
    .DESCRIPTION
        MS-GPOL requires the file in ANSI, with a [General] section ("If this section is not present,
        the file is considered corrupt") holding a Version key that is a 32-bit integer. Section and
        key names are compared without regard to case, and spaces around '=' are allowed. A
        comment line (';Version=5') is never taken as the key: its key would be ';Version', so no
        separate comment rule is needed. A UTF-16 or UTF-8 file is tolerated and says so in Encoding:
        a byte-order mark decides; with none, a zero second byte is read as UTF-16LE (inferred);
        otherwise the bytes are ANSI, read byte for byte (ISO-8859-1), which keeps every ASCII
        character - the only ones a version is written in - exact on any host code page.

        Causes: Empty, NoGeneralSection, NoVersionKey, DuplicateVersionKey, NotANumber, OutOfRange.
        The value itself is not quoted in CauseText: the file's content is not for the report text.
    .OUTPUTS
        [pscustomobject] Ok, Version ([int64] or $null), Cause, CauseText, Encoding.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()][byte[]]$Bytes,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{ Ok = $false; Version = $null; Cause = ''; CauseText = ''; Encoding = '' }
    $texts = @{
        Empty               = 'GPT.INI is empty'
        NoGeneralSection    = 'GPT.INI has no [General] section (MS-GPOL: the file is then considered corrupt)'
        NoVersionKey        = 'the [General] section of GPT.INI has no Version key'
        DuplicateVersionKey = 'the [General] section of GPT.INI has more than one Version key'
        NotANumber          = 'the Version value of GPT.INI is not a whole number'
        OutOfRange          = 'the Version value of GPT.INI does not fit in 32 bits'
    }
    if ($null -eq $Bytes -or $Bytes.Length -eq 0) { $out.Cause = 'Empty'; $out.CauseText = $texts['Empty']; return $out }
    $offset = 0
    $encoding = [System.Text.Encoding]::GetEncoding(28591)
    $out.Encoding = 'ANSI (no BOM)'
    if ($Bytes.Length -ge 2 -and $Bytes[0] -eq 0xFF -and $Bytes[1] -eq 0xFE) { $encoding = [System.Text.Encoding]::Unicode; $offset = 2; $out.Encoding = 'UTF-16LE (BOM)' }
    elseif ($Bytes.Length -ge 2 -and $Bytes[0] -eq 0xFE -and $Bytes[1] -eq 0xFF) { $encoding = [System.Text.Encoding]::BigEndianUnicode; $offset = 2; $out.Encoding = 'UTF-16BE (BOM)' }
    elseif ($Bytes.Length -ge 3 -and $Bytes[0] -eq 0xEF -and $Bytes[1] -eq 0xBB -and $Bytes[2] -eq 0xBF) { $encoding = [System.Text.Encoding]::UTF8; $offset = 3; $out.Encoding = 'UTF-8 (BOM)' }
    elseif ($Bytes.Length -ge 2 -and $Bytes[0] -ne 0 -and $Bytes[1] -eq 0) { $encoding = [System.Text.Encoding]::Unicode; $out.Encoding = 'UTF-16LE (no BOM, inferred)' }
    $text = $encoding.GetString($Bytes, $offset, $Bytes.Length - $offset)
    $section = [string]$Config['GptIniSection']
    $key = [string]$Config['GptIniKey']
    $inGeneral = $false
    $sawGeneral = $false
    $values = @()
    foreach ($line in @($text -split "`r`n|`n|`r")) {
        $trimmed = $line.Trim()
        if ($trimmed -eq '') { continue }
        if ($trimmed -match '^\[\s*([^\]]*?)\s*\]$') {
            $inGeneral = ([string]$Matches[1] -eq $section)
            if ($inGeneral) { $sawGeneral = $true }
            continue
        }
        if ($inGeneral -and $trimmed -match '^([^=]+?)\s*=\s*(.*)$' -and [string]$Matches[1] -eq $key) { $values += [string]$Matches[2] }
    }
    $cause = ''
    if (-not $sawGeneral) { $cause = 'NoGeneralSection' }
    elseif ($values.Count -eq 0) { $cause = 'NoVersionKey' }
    elseif ($values.Count -gt 1) { $cause = 'DuplicateVersionKey' }
    if ($cause -ne '') { $out.Cause = $cause; $out.CauseText = $texts[$cause]; return $out }
    $number = ConvertTo-AdfaGpoVersionNumber -Value ([string]$values[0])
    if (-not $number.Ok) { $out.Cause = [string]$number.Cause; $out.CauseText = $texts[[string]$number.Cause]; return $out }
    $out.Version = [int64]$number.Version
    $out.Ok = $true
    return $out
}

function Get-AdfaGpoFailureLead {
    <#
    .SYNOPSIS
        Pure: the words a Not Assessed row of this section starts with, for a read failure class.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowEmptyString()][string]$Class)
    switch ($Class) {
        'Unreachable' { return 'Unreachable' }
        'AccessDenied' { return 'Access denied' }
        'TimedOut' { return 'Timed out' }
        'NotFound' { return 'Not found' }
        'TooLarge' { return 'Not read' }
    }
    return 'Read failed'
}

function Get-AdfaGpoFileReadErrorClass {
    <#
    .SYNOPSIS
        Pure: NotFound, AccessDenied, Unreachable, TimedOut or Error, for a file or folder read over
        SMB that threw.
    .DESCRIPTION
        From the exception type first, then from the Win32 code an IOException carries in the low
        16 bits of its HResult (Learn: "strip out the upper 16 bits"), then from its text. Types:
        FileNotFound, DirectoryNotFound and DriveNotFound (COR_E_DIRECTORYNOTFOUND, Learn) not
        found; UnauthorizedAccess access denied; Timeout timed out. SecurityException is NOT read
        as access denied: Learn says .NET Framework throws it only in limited trust, not for a
        refused file, so it is Error. Codes read on Learn 2026-11-16: 2 and 3 not found; 5 access
        denied and 65 network access denied; 51 and 53 network path not found, 64 network name no
        longer available, 1231 and 1232 network location cannot be reached. Anything else is
        Error, quoted and not interpreted. Which exception a real SYSVOL read throws for each case
        is not published (PORT-PLAN C8a).
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyString()][string]$TypeName,
        [int]$HResult = 0,
        [AllowNull()][AllowEmptyString()][string]$Message
    )
    if (-not [string]::IsNullOrWhiteSpace($TypeName)) {
        if ($TypeName -match '(?i)(FileNotFound|DirectoryNotFound|ItemNotFound|DriveNotFound)Exception$') { return 'NotFound' }
        if ($TypeName -match '(?i)UnauthorizedAccessException$') { return 'AccessDenied' }
        if ($TypeName -match '(?i)TimeoutException$') { return 'TimedOut' }
    }
    if (($HResult -band 0xFFFF0000) -eq 0x80070000) {
        $code = $HResult -band 0xFFFF
        if (@(2, 3) -contains $code) { return 'NotFound' }
        if (@(5, 65) -contains $code) { return 'AccessDenied' }
        if (@(51, 53, 64, 1231, 1232) -contains $code) { return 'Unreachable' }
    }
    if ((Get-AdfaRemoteReadErrorClass -Message $Message -ErrorCode '') -eq 'AccessDenied') { return 'AccessDenied' }
    return 'Error'
}

function Get-AdfaGpoFileFailure {
    <#
    .SYNOPSIS
        Pure: what a file or folder read that threw is reported as - the innermost exception that
        PowerShell did not add, its type, HResult and class.
    .DESCRIPTION
        A .NET method called from PowerShell throws a MethodInvocationException around the real
        exception; that wrapper says nothing about the cause and is unwrapped first.
    .OUTPUTS
        [pscustomobject] Class, Error, ErrorType, HResult.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][System.Exception]$Exception)
    $ex = $Exception
    while ($ex -is [System.Management.Automation.MethodException] -and $null -ne $ex.InnerException) { $ex = $ex.InnerException }
    $type = [string]$ex.GetType().FullName
    $message = [string]$ex.Message
    $hresult = [int]$ex.HResult
    return [pscustomobject]@{ Class = (Get-AdfaGpoFileReadErrorClass -TypeName $type -HResult $hresult -Message $message); Error = $message.Trim(); ErrorType = $type; HResult = $hresult }
}

function Get-AdfaGpoSysvolPath {
    <#
    .SYNOPSIS
        Pure: where this tool reads a GPO's GPT.INI - always the PDC's own SYSVOL share - and whether
        the directory's gPCFileSysPath agrees that this is the GPO's folder.
    .DESCRIPTION
        The path read is built from the PDC's name, the domain and the container's GUID name:
        \\<PDC>\SYSVOL\<domain>\Policies\<GUID>\GPT.INI. The host in gPCFileSysPath is never
        contacted: the value is a directory string, and reading a path it names would send this
        account's credentials to whatever host an administrator of the GPO wrote there.

        gPCFileSysPath must have the form MS-GPOL defines, \\<domain>\sysvol\<domain>\policies\<GUID>
        (case-insensitive, an optional trailing backslash), with this domain and this GPO's GUID.
        Otherwise the GPT.INI that clients read is not the one this tool would read, and the GPO is
        not compared (Ok = $false, IniPath empty). A PDC or domain name that is not a plain DNS name
        is refused rather than put in a path.
    .OUTPUTS
        [pscustomobject] Ok, PoliciesPath, FolderPath, IniPath, Cause.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Pdc = '',
        [AllowEmptyString()][string]$Domain = '',
        [AllowEmptyString()][string]$Guid = '',
        [AllowNull()][AllowEmptyString()][string]$FileSysPath = '',
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{ Ok = $false; PoliciesPath = ''; FolderPath = ''; IniPath = ''; Cause = '' }
    $dns = '^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)*$'
    if ($Pdc -notmatch $dns -or $Domain -notmatch $dns) {
        $out.Cause = 'the PDC emulator or the domain name is not a plain DNS name, so no SYSVOL path was built from it'
        return $out
    }
    $out.PoliciesPath = ("\\{0}\{1}\{2}\{3}" -f $Pdc, [string]$Config['SysvolShare'], $Domain, [string]$Config['PoliciesFolder'])
    if ($Guid -notmatch [string]$Config['GuidPattern']) {
        $out.Cause = 'the container''s name is not a GUID in braces, which MS-GPOL requires of every GPO, so there is no SYSVOL folder to match it to'
        return $out
    }
    if ([string]::IsNullOrWhiteSpace($FileSysPath)) {
        $out.Cause = 'gPCFileSysPath was not returned (not set, or not readable by this account), so the folder clients read for this GPO is not known'
        return $out
    }
    $expected = ("\\{0}\sysvol\{0}\policies\{1}" -f $Domain, $Guid)
    $given = $FileSysPath.Trim().TrimEnd('\')
    if (-not [string]::Equals($given, $expected, [System.StringComparison]::OrdinalIgnoreCase)) {
        $out.Cause = 'gPCFileSysPath is not the path MS-GPOL defines for this GPO (\\<domain>\sysvol\<domain>\policies\<GUID>, with this domain and this GPO''s GUID), so the GPT.INI clients read is not the one this tool would read; the value is in the FileSysPath column'
        return $out
    }
    $out.FolderPath = ("{0}\{1}" -f $out.PoliciesPath, $Guid)
    $out.IniPath = ("{0}\{1}" -f $out.FolderPath, [string]$Config['GptIniFileName'])
    $out.Ok = $true
    return $out
}

function ConvertTo-AdfaGpoContainerRecord {
    <#
    .SYNOPSIS
        Pure: one groupPolicyContainer object as the small record the verdicts read.
    .DESCRIPTION
        Every value is read through PSObject.Properties, so an attribute the object does not carry is
        $null and never an error under StrictMode. The GUID is the object's name (cn), which MS-GPOL
        defines as "a curly braced GUID string"; it is upper-cased so that folder names compare
        without regard to case.
    .OUTPUTS
        [pscustomobject] Guid, DisplayName, Version (as returned), FileSysPath, Flags (as returned), Dn.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)]$Object)
    $values = @{}
    foreach ($attribute in @('Name', 'cn', 'displayName', 'versionNumber', 'gPCFileSysPath', 'flags', 'DistinguishedName')) {
        $values[$attribute] = $null
        $p = $Object.PSObject.Properties[$attribute]
        if ($null -ne $p) { $values[$attribute] = $p.Value }
    }
    $guid = [string]$values['Name']
    if ([string]::IsNullOrWhiteSpace($guid)) { $guid = [string]$values['cn'] }
    $fileSysPath = $null
    if ($null -ne $values['gPCFileSysPath']) { $fileSysPath = [string]$values['gPCFileSysPath'] }
    return [pscustomobject]@{
        Guid = $guid.Trim().ToUpperInvariant(); DisplayName = [string]$values['displayName']; Version = $values['versionNumber']
        FileSysPath = $fileSysPath; Flags = $values['flags']; Dn = [string]$values['DistinguishedName']
    }
}

function Get-AdfaGpoContainerRaw {
    <#
    .SYNOPSIS
        The directory seam of C8: the domain's PDC emulator, and its groupPolicyContainer objects,
        read from that PDC. Read-only. Never throws.
    .DESCRIPTION
        Two reads:
          Get-ADDomain -Identity <domain>   with the caller's AD parameters unchanged, for the
                                            domain's DN and PDCEmulator
          Get-ADObject -Server <PDC> -SearchBase CN=Policies,CN=System,<domain DN> -SearchScope
                                            OneLevel -LDAPFilter (objectClass=groupPolicyContainer),
                                            asking for Config.ContainerProperties only
        Both reads of this check - the directory here and SYSVOL in Get-AdfaGpoSysvolRaw - go to the
        same DC, the PDC emulator, which Group Policy editing targets by default; so a difference is
        a difference on that one DC, not between two DCs. A property list that is empty or holds a
        blank or a wildcard is refused before any call. Nothing here writes.
    .OUTPUTS
        [pscustomobject] Ok, Refused, Error, ErrorType, Pdc, PdcError, PdcErrorType, DomainDn,
        Containers (records of ConvertTo-AdfaGpoContainerRecord).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{ Ok = $false; Refused = $false; Error = ''; ErrorType = ''; Pdc = ''; PdcError = ''; PdcErrorType = ''; DomainDn = ''; Containers = @() }
    $properties = @(@($Config['ContainerProperties']) | ForEach-Object { [string]$_ })
    $bad = @($properties | Where-Object { [string]::IsNullOrWhiteSpace($_) -or $_ -match '[*?]' })
    if ($properties.Count -eq 0 -or $bad.Count -gt 0) {
        $out.Refused = $true
        $out.Error = 'the property list is empty or holds a blank or a wildcard, so nothing was asked of the directory'
        return $out
    }
    try {
        $domainArgs = @{} + $AdParams
        $domainArgs.Identity = $DomainName
        $domainArgs.ErrorAction = 'Stop'
        $domain = Get-ADDomain @domainArgs
        if ($null -ne $domain) {
            $dnProp = $domain.PSObject.Properties['DistinguishedName']
            if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $out.DomainDn = ([string]$dnProp.Value).Trim() }
            $pdcProp = $domain.PSObject.Properties['PDCEmulator']
            if ($null -ne $pdcProp -and -not [string]::IsNullOrWhiteSpace([string]$pdcProp.Value)) { $out.Pdc = ([string]$pdcProp.Value).Trim() }
        }
        if ($out.Pdc -eq '') { $out.PdcError = ("Get-ADDomain returned no PDCEmulator for {0}" -f $DomainName) }
        elseif ($out.DomainDn -eq '') { $out.PdcError = ("Get-ADDomain returned no DistinguishedName for {0}" -f $DomainName); $out.Pdc = '' }
    }
    catch {
        $out.PdcError = [string]$_.Exception.Message
        $out.PdcErrorType = [string]$_.Exception.GetType().FullName
    }
    if ($out.Pdc -eq '') { return $out }
    try {
        $objectArgs = @{} + $AdParams
        $objectArgs.Server = $out.Pdc
        $objectArgs.LDAPFilter = [string]$Config['ContainerFilter']
        $objectArgs.SearchBase = ("{0},{1}" -f [string]$Config['PoliciesContainerRdn'], $out.DomainDn)
        $objectArgs.SearchScope = 'OneLevel'
        $objectArgs.Properties = @($properties)
        $objectArgs.ErrorAction = 'Stop'
        $records = New-Object System.Collections.ArrayList
        Get-ADObject @objectArgs | ForEach-Object {
            if ($null -ne $_) { [void]$records.Add((ConvertTo-AdfaGpoContainerRecord -Object $_)) }
        }
        $out.Containers = $records.ToArray()
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Get-AdfaSysvolPolicyFolderRaw {
    <#
    .SYNOPSIS
        File seam of C8: the names of the folders under a SYSVOL Policies folder. Read-only. Never
        throws.
    .DESCRIPTION
        One directory listing ([System.IO.Directory]::GetDirectories); nothing is opened, created,
        changed or deleted. Runs as the account running the script: -Credential is not passed to
        file reads.
    .OUTPUTS
        [pscustomobject] Ok, Class (Read or a class of Get-AdfaGpoFileReadErrorClass), Names, Error,
        ErrorType, HResult, Path.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$Path)
    $out = [pscustomobject]@{ Ok = $false; Class = ''; Names = @(); Error = ''; ErrorType = ''; HResult = 0; Path = $Path }
    try {
        $out.Names = @([System.IO.Directory]::GetDirectories($Path) | ForEach-Object { [System.IO.Path]::GetFileName([string]$_) })
        $out.Class = 'Read'
        $out.Ok = $true
    }
    catch {
        $f = Get-AdfaGpoFileFailure -Exception $_.Exception
        $out.Class = $f.Class; $out.Error = $f.Error; $out.ErrorType = $f.ErrorType; $out.HResult = $f.HResult
    }
    return $out
}

function Get-AdfaGptIniRaw {
    <#
    .SYNOPSIS
        File seam of C8: the bytes of one GPT.INI, opened for reading only. Never throws.
    .DESCRIPTION
        new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete)
        (Learn): read access only, and no other open of the file - for reading, writing or delete -
        is refused while this handle is held, so a GPMC save or a DFSR install of the same GPT.INI
        on the PDC is never made to fail by this read (File.OpenRead's FileShare.Read would refuse
        them). At most MaxBytes + 1 bytes are read: a larger file is not taken (TooLarge), so a file
        in SYSVOL cannot make the tool read without bound. The MS-GPOL update sequence opens GPT.INI
        for read/write; this never does. Runs as the account running the script: -Credential is not
        passed to file reads.
    .OUTPUTS
        [pscustomobject] Ok, Class (Read, TooLarge or a class of Get-AdfaGpoFileReadErrorClass),
        Bytes, Error, ErrorType, HResult, Path.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Path,
        [ValidateRange(1, 16777216)][int]$MaxBytes = 65536
    )
    $out = [pscustomobject]@{ Ok = $false; Class = ''; Bytes = $null; Error = ''; ErrorType = ''; HResult = 0; Path = $Path }
    $stream = $null
    try {
        $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
        $stream = [System.IO.FileStream]::new($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
        $buffer = New-Object byte[] ($MaxBytes + 1)
        $total = 0
        while ($total -lt $buffer.Length) {
            $n = $stream.Read($buffer, $total, $buffer.Length - $total)
            if ($n -le 0) { break }
            $total += $n
        }
        if ($total -gt $MaxBytes) {
            $out.Class = 'TooLarge'
            $out.Error = ("the file is larger than {0} bytes" -f $MaxBytes)
        }
        else {
            $bytes = New-Object byte[] $total
            for ($i = 0; $i -lt $total; $i++) { $bytes[$i] = $buffer[$i] }
            $out.Bytes = $bytes
            $out.Class = 'Read'
            $out.Ok = $true
        }
    }
    catch {
        $f = Get-AdfaGpoFileFailure -Exception $_.Exception
        $out.Class = $f.Class; $out.Error = $f.Error; $out.ErrorType = $f.ErrorType; $out.HResult = $f.HResult
    }
    finally {
        if ($null -ne $stream) { $stream.Dispose() }
    }
    return $out
}

function Get-AdfaGpoSysvolRaw {
    <#
    .SYNOPSIS
        The SYSVOL seam of C8: on the PDC, a probe of SMB, a listing of the Policies folder, and a
        read of each GPT.INI. Read-only. Never throws.
    .DESCRIPTION
        1. Get-AdfaDcProbeGate <PDC> 445 (the reachability class, then the per-run probe cache). A
           PDC classified Unreachable in this run is not probed: ReachCause holds its class. With
           no answer nothing else is tried: a UNC "not found" cannot be told from a host that did
           not answer, so no file is reported absent unless this DC answered.
        2. The folder names under \\<PDC>\SYSVOL\<domain>\Policies (Get-AdfaSysvolPolicyFolderRaw).
        3. GPT.INI of each target whose folder the listing holds (Get-AdfaGptIniRaw). A target whose
           folder is not listed is not read: its folder is absent, which the verdict reports. When
           the listing failed, every target is read only if the listing's class is in
           Config.ReadFilesAfterListingClass (access denied: a folder can refuse a listing and still
           let its files be read); after any other class - unreachable, timed out, not found, an
           error not interpreted - nothing is read, because each read would go to the path that
           just failed and has no timeout of its own, and the verdict reports every GPO with the
           listing's class.
    .OUTPUTS
        [pscustomobject] PortOk, Port, Pdc, PoliciesPath, Listing (or $null when SMB did not answer),
        Reads (hashtable: GUID -> read), ReachCause ('' unless the PDC was classified Unreachable in
        this run, PORT-PLAN C14c: then port 445 was not probed and this is the class).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Pdc,
        [Parameter(Mandatory)][string]$Domain,
        [AllowNull()][AllowEmptyCollection()]$Targets = @(),
        [Parameter(Mandatory)][hashtable]$Config
    )
    $port = [int]$Config['SmbPort']
    $policies = ("\\{0}\{1}\{2}\{3}" -f $Pdc, [string]$Config['SysvolShare'], $Domain, [string]$Config['PoliciesFolder'])
    $out = [pscustomobject]@{ PortOk = $false; Port = $port; Pdc = $Pdc; PoliciesPath = $policies; Listing = $null; Reads = @{}; ReachCause = '' }
    # PORT-PLAN C1b: through the shared gate, so a PDC classified Unreachable is not probed again. Its
    # class is kept (ReachCause), so the verdict names it instead of a probe of 445 that was never made.
    $smbGate = Get-AdfaDcProbeGate -ComputerName $Pdc -Ports @($port) -TimeoutMs ([int]$Config['SmbProbeTimeoutMs'])
    $out.ReachCause = [string]$smbGate.Cause
    $out.PortOk = [bool]$smbGate.Open[$port]
    if (-not $out.PortOk) { return $out }
    $out.Listing = Get-AdfaSysvolPolicyFolderRaw -Path $policies
    $listed = @{}
    if ($out.Listing.Ok) { foreach ($name in @($out.Listing.Names)) { $listed[([string]$name).ToUpperInvariant()] = $true } }
    elseif (@($Config['ReadFilesAfterListingClass']) -notcontains [string]$out.Listing.Class) { return $out }
    foreach ($target in @($Targets | Where-Object { $null -ne $_ })) {
        $guid = ([string]$target.Guid).ToUpperInvariant()
        if ($out.Listing.Ok -and -not $listed.ContainsKey($guid)) { continue }
        $out.Reads[$guid] = Get-AdfaGptIniRaw -Path ([string]$target.IniPath) -MaxBytes ([int]$Config['GptIniMaxBytes'])
    }
    return $out
}

function Get-AdfaGpoVersionVerdict {
    <#
    .SYNOPSIS
        Pure: the verdict on one GPO whose two versions were read - equal (Pass, and no row is
        written for it) or not (Config.MismatchStatus), naming the half that differs.
    .DESCRIPTION
        The whole 32-bit numbers decide; the halves (MS-GPOL: user upper 16 bits, computer lower 16
        bits) only explain. Learn publishes no grade for a difference and no time after which one
        stops being transient, so the status is the config's, labelled with its source.
    .OUTPUTS
        [pscustomobject] Status, Half (None, User, Computer, Both), Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][int64]$DsVersion,
        [Parameter(Mandatory)][int64]$SysvolVersion,
        [AllowEmptyString()][string]$ReadFrom = '',
        [Parameter(Mandatory)][hashtable]$Config
    )
    if ($DsVersion -eq $SysvolVersion) { return [pscustomobject]@{ Status = $script:Status.Pass; Half = 'None'; Detail = '' } }
    $ds = Split-AdfaGpoVersion -Version $DsVersion
    $sv = Split-AdfaGpoVersion -Version $SysvolVersion
    $user = ($ds.User -ne $sv.User)
    $computer = ($ds.Computer -ne $sv.Computer)
    $half = 'Both'
    $halfText = 'the user and computer halves differ'
    if ($user -and -not $computer) { $half = 'User'; $halfText = 'the user half differs' }
    elseif ($computer -and -not $user) { $half = 'Computer'; $halfText = 'the computer half differs' }
    $status = [string]$Config['MismatchStatus']
    $detail = ("Version mismatch on {0}: the directory (versionNumber) holds {1} (user {2}, computer {3}) and GPT.INI in SYSVOL holds {4} (user {5}, computer {6}); {7}. The directory and SYSVOL replicate independently (Microsoft: DFSR replicates SYSVOL within a site every 15 minutes), so this can be replication still in flight: run the assessment again once replication has converged. A mismatch that remains means this domain controller's directory copy and SYSVOL copy of the GPO disagree. Graded {8}: {9}." -f `
            $ReadFrom, $DsVersion, $ds.User, $ds.Computer, $SysvolVersion, $sv.User, $sv.Computer, $halfText, $status, [string]$Config['ThresholdSource'])
    return [pscustomobject]@{ Status = $status; Half = $half; Detail = $detail }
}

function Get-AdfaGpoDomainVerdict {
    <#
    .SYNOPSIS
        Pure: the summary verdict for one domain from its counts.
    .DESCRIPTION
        Pass only when the population was read, holds at least one GPO, every GPO in it was compared
        and none differs. Any difference is Config.MismatchStatus. Otherwise any GPO not compared
        makes the domain Not Assessed. An empty population is Not Assessed: a domain holds at least
        the Default Domain Policy, so no container visible to this account is not a clean result.
        Counts that do not add up (compared + not compared against the population, more mismatched
        than compared) are a defect in the tool and are said to be.
    .OUTPUTS
        [pscustomobject] Status, Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [AllowEmptyString()][string]$ReadFrom = '',
        [AllowNull()]$Population,
        [int]$Compared = 0,
        [int]$Mismatched = 0,
        [int]$NotAssessed = 0,
        [Parameter(Mandatory)][hashtable]$Config
    )
    if ($null -eq $Population -or ($Compared + $NotAssessed) -ne [int]$Population -or $Mismatched -gt $Compared -or $Compared -lt 0 -or $NotAssessed -lt 0) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed
            Detail = ("Not assessed: the counts for {0} do not add up ({1} compared and {2} not compared against a population of {3}, {4} mismatched); this is a defect in the tool, not a result." -f $Domain, $Compared, $NotAssessed, [string]$Population, $Mismatched) }
    }
    $n = [int]$Population
    if ($n -le 0) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed
            Detail = ("Not assessed: no groupPolicyContainer object under CN=Policies,CN=System of {0} is visible to this account on {1}. A domain holds at least the Default Domain Policy, so an empty answer is not a clean result." -f $Domain, $ReadFrom) }
    }
    if ($Mismatched -gt 0) {
        $status = [string]$Config['MismatchStatus']
        return [pscustomobject]@{ Status = $status
            Detail = ("{0} of {1} GPO(s) of {2} have a directory version that differs from GPT.INI in SYSVOL on {3} (see their 'GPO version' rows); {4} compared, {5} not compared. This can be replication still in flight: run the assessment again once replication has converged. Graded {6}: {7}." -f $Mismatched, $n, $Domain, $ReadFrom, $Compared, $NotAssessed, $status, [string]$Config['ThresholdSource']) }
    }
    if ($NotAssessed -gt 0) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed
            Detail = ("Not assessed: {0} of {1} GPO(s) of {2} could not be compared on {3} (see their 'GPO version' rows); {4} compared, none mismatched. This is not a clean result." -f $NotAssessed, $n, $Domain, $ReadFrom, $Compared) }
    }
    return [pscustomobject]@{ Status = $script:Status.Pass
        Detail = ("All {0} GPO(s) of {1} visible to this account were compared on {2}: for each, the directory version (versionNumber) equals the GPT.INI version in SYSVOL, both halves. A GPO this account cannot read is not counted." -f $n, $Domain, $ReadFrom) }
}

function Get-AdfaGpoDomainFinding {
    <#
    .SYNOPSIS
        Pure: one domain's reads (directory and SYSVOL) to its rows.
    .DESCRIPTION
        Rows, in this order, written only where there is something to say:
          "GPO version: {GUID}"               one per GPO whose versions differ, or that could not be
                                              compared (Not Assessed, each cause in its own words)
          "GPO folder without container: {GUID}"  one per GUID-named folder under Policies with no
                                              container visible to this account (OrphanFolderStatus)
          "GPO folder listing: <domain>"      Not Assessed, when the Policies folder was not listed
          "GPO version summary: <domain>"     always: the declared population (containers read),
                                              compared, mismatched and not compared
        A failed directory read gives the summary row only. Every row's Evidence says what was
        measured: 'none', 'directory', 'SYSVOL' or 'directory and SYSVOL'; the summary says SYSVOL
        only when the Policies folder was listed or a GPT.INI version was read.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [Parameter(Mandatory)]$Raw,
        [AllowNull()]$Sysvol,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    $summaryItem = ("GPO version summary: {0}" -f $Domain)
    $pdc = [string]$Raw.Pdc
    if ($Raw.Refused) {
        return @(New-AdfaGpoVersionRow -Scope $Domain -Item $summaryItem -Status $script:Status.NotAssessed -Evidence 'none' `
                -Detail ("Not assessed: {0}; this is a defect in the tool, not a result." -f [string]$Raw.Error))
    }
    if ([string]::IsNullOrWhiteSpace($pdc)) {
        $lead = Get-AdfaGpoFailureLead -Class (Get-AdfaDirectoryReadErrorClass -Message ([string]$Raw.PdcError) -TypeName ([string]$Raw.PdcErrorType))
        $type = ''
        if (-not [string]::IsNullOrWhiteSpace([string]$Raw.PdcErrorType)) { $type = (" (exception type: {0})" -f [string]$Raw.PdcErrorType) }
        return @(New-AdfaGpoVersionRow -Scope $Domain -Item $summaryItem -Status $script:Status.NotAssessed -Evidence 'none' `
                -Detail ("{0}: the PDC emulator of {1} could not be identified, so there was no domain controller to read the GPOs and their GPT.INI from. This is not a clean result. Reported: {2}{3}" -f $lead, $Domain, ([string]$Raw.PdcError).Trim(), $type))
    }
    if (-not $Raw.Ok) {
        $lead = Get-AdfaGpoFailureLead -Class (Get-AdfaDirectoryReadErrorClass -Message ([string]$Raw.Error) -TypeName ([string]$Raw.ErrorType))
        return @(New-AdfaGpoVersionRow -Scope $Domain -Item $summaryItem -Status $script:Status.NotAssessed -Evidence 'none' -ReadFrom $pdc `
                -Detail ("{0}: the groupPolicyContainer objects of {1} could not be read from {2}, so no GPO was compared and no SYSVOL folder was looked at. This is not a clean result. Reported: {3} (exception type: {4})" -f $lead, $Domain, $pdc, ([string]$Raw.Error).Trim(), [string]$Raw.ErrorType))
    }

    $guidPattern = [string]$Config['GuidPattern']
    $portOk = ($null -ne $Sysvol -and [bool]$Sysvol.PortOk)
    # PORT-PLAN C14c: a PDC classified Unreachable was not probed on 445; its rows name the class,
    # never a probe result that was not measured. Read without assuming the property (an older shape).
    $reachCause = ''
    if ($null -ne $Sysvol) {
        $reachProp = $Sysvol.PSObject.Properties['ReachCause']
        if ($null -ne $reachProp -and $null -ne $reachProp.Value) { $reachCause = [string]$reachProp.Value }
    }
    $listing = $null
    if ($portOk) { $listing = $Sysvol.Listing }
    $listingOk = ($null -ne $listing -and [bool]$listing.Ok)
    $listingClass = ''
    if ($null -ne $listing) { $listingClass = [string]$listing.Class }
    # After a failed listing, files were read only for these classes (Get-AdfaGpoSysvolRaw).
    $listingSkippedReads = ($portOk -and -not $listingOk -and @($Config['ReadFilesAfterListingClass']) -notcontains $listingClass)
    $policies = ''
    if ($null -ne $Sysvol) { $policies = [string]$Sysvol.PoliciesPath }
    $smbPort = [int]$Config['SmbPort']
    $listed = @{}
    $nonGuidFolders = 0
    if ($listingOk) {
        foreach ($name in @($listing.Names)) {
            $upper = ([string]$name).ToUpperInvariant()
            if ($upper -match $guidPattern) { $listed[$upper] = $true } else { $nonGuidFolders++ }
        }
    }
    $reads = @{}
    if ($null -ne $Sysvol -and $null -ne $Sysvol.Reads) { $reads = $Sysvol.Reads }

    $containers = @($Raw.Containers | Where-Object { $null -ne $_ })
    $population = $containers.Count
    $compared = 0
    $mismatched = 0
    $notAssessed = 0
    $sysvolVersionsRead = 0
    $containerGuids = @{}
    foreach ($c in $containers) {
        $guid = ([string]$c.Guid).ToUpperInvariant()
        $validGuid = ($guid -match $guidPattern)
        if ($validGuid) { $containerGuids[$guid] = $true }
        $item = ("GPO version: {0}" -f $guid)
        if (-not $validGuid) { $item = 'GPO version: (container with no GUID name)' }
        $flagsLabel = ''
        $flagsNumber = $null
        $flagsRead = ConvertTo-AdfaGpoVersionNumber -Value $c.Flags
        if ($flagsRead.Ok) {
            $flagsNumber = $flagsRead.Version
            $flagsLabel = 'other bits set (not interpreted)'
            foreach ($entry in @($Config['FlagLabels'])) { if ([int64]$entry['Value'] -eq $flagsNumber) { $flagsLabel = [string]$entry['Label'] } }
        }
        $path = Get-AdfaGpoSysvolPath -Pdc $pdc -Domain $Domain -Guid $guid -FileSysPath ([string]$c.FileSysPath) -Config $Config
        $ds = ConvertTo-AdfaGpoVersionNumber -Value $c.Version
        $causes = @()
        $sysvolVersion = $null
        $encoding = ''
        if (-not $path.Ok) { $causes += ("Not assessed: {0}. GPT.INI was not read." -f $path.Cause) }
        if (-not $ds.Ok) {
            if ($ds.Cause -eq 'NotReturned') { $causes += "Not returned: versionNumber of this GPO's container was not returned (not set, or not readable by this account), so the directory version is not known." }
            else { $causes += ("Not parsed: versionNumber of this GPO's container could not be read as a 32-bit version ({0})." -f [string]$ds.Cause) }
        }
        if ($path.Ok) {
            if (-not $portOk -and -not [string]::IsNullOrWhiteSpace($reachCause)) {
                $causes += ("{0} This is not a clean result." -f (Get-AdfaDcGateText -Cause $reachCause -NotRead ('port {0} (SMB) of {1} was not probed, GPT.INI of this GPO was not read and its versions were not compared' -f $smbPort, $pdc)))
            }
            elseif (-not $portOk) {
                $causes += ("Unreachable: port {0} (SMB) of {1} did not answer, so GPT.INI of this GPO was not read and its versions were not compared. This is not a clean result." -f $smbPort, $pdc)
            }
            elseif ($listingOk -and -not $listed.ContainsKey($guid)) {
                $causes += ("Not found: the GPO's folder is not in {0} on {1}, although that folder was listed: a container with no SYSVOL folder on this domain controller - an orphaned container, or a folder not yet replicated here. Microsoft calls a container orphaned only when no domain controller of the domain holds its folder, and only this one was read." -f $policies, $pdc)
            }
            elseif (-not $reads.ContainsKey($guid) -and $listingSkippedReads) {
                $causes += ("{0}: {1} could not be listed on {2}, so GPT.INI of this GPO was not read and its versions were not compared (after a listing failure of this kind no file is read: each read would go to the path that just failed). This is not a clean result." -f (Get-AdfaGpoFailureLead -Class $listingClass), $policies, $pdc)
            }
            elseif (-not $reads.ContainsKey($guid)) {
                $causes += 'Not assessed: GPT.INI of this GPO was not read although its path was known; this is a defect in the tool, not a result.'
            }
            else {
                $read = $reads[$guid]
                if ($read.Ok) {
                    $parsed = ConvertFrom-AdfaGptIniVersion -Bytes $read.Bytes -Config $Config
                    $encoding = [string]$parsed.Encoding
                    if ($parsed.Ok) { $sysvolVersion = [int64]$parsed.Version; $sysvolVersionsRead++ }
                    else { $causes += ("Not parsed: GPT.INI on {0} was read but its version could not be taken from it: {1}." -f $pdc, [string]$parsed.CauseText) }
                }
                else {
                    $class = [string]$read.Class
                    $reported = ''
                    if (-not [string]::IsNullOrWhiteSpace([string]$read.Error)) { $reported = (" Reported: {0}" -f ([string]$read.Error).Trim()) }
                    if (-not [string]::IsNullOrWhiteSpace([string]$read.ErrorType)) { $reported = ("{0} (exception type: {1})" -f $reported, [string]$read.ErrorType) }
                    switch ($class) {
                        'NotFound' {
                            if ($listingOk) { $causes += ("Not found: the GPO's folder is on {0} but holds no GPT.INI, so the SYSVOL version is not known. This is not a clean result.{1}" -f $pdc, $reported) }
                            else { $causes += ("Not found: GPT.INI was not found at the path read on {0}; the Policies folder could not be listed, so whether the GPO's folder exists is not known.{1}" -f $pdc, $reported) }
                        }
                        'AccessDenied' { $causes += ("Access denied: GPT.INI of this GPO on {0} could not be read by the account running this script (file reads run as that account; -Credential is not passed to them). This is not a clean result.{1}" -f $pdc, $reported) }
                        'TooLarge' { $causes += ("Not read: GPT.INI on {0} is larger than {1} bytes (GptIniMaxBytes, a tool default, not a Microsoft value), so it was not read." -f $pdc, [int]$Config['GptIniMaxBytes']) }
                        default { $causes += ("{0}: GPT.INI of this GPO on {1} could not be read. This is not a clean result.{2}" -f (Get-AdfaGpoFailureLead -Class $class), $pdc, $reported) }
                    }
                }
            }
        }
        $dsVersion = $null
        if ($ds.Ok) { $dsVersion = [int64]$ds.Version }
        $rowArgs = @{
            Scope = $Domain; Item = $item; GPOName = [string]$c.DisplayName; GpoGuid = $guid; ReadFrom = $pdc; DsVersion = $dsVersion; SysvolVersion = $sysvolVersion
            Flags = $flagsNumber; FlagsLabel = $flagsLabel; GptIniPath = [string]$path.IniPath; FileSysPath = [string]$c.FileSysPath; Encoding = $encoding
        }
        if ($causes.Count -gt 0) {
            $notAssessed++
            $evidence = 'none'
            if ($null -ne $dsVersion -and $null -ne $sysvolVersion) { $evidence = 'directory and SYSVOL' }
            elseif ($null -ne $dsVersion) { $evidence = 'directory' }
            elseif ($null -ne $sysvolVersion) { $evidence = 'SYSVOL' }
            $rows += New-AdfaGpoVersionRow @rowArgs -Status $script:Status.NotAssessed -Evidence $evidence -Detail ($causes -join ' Also: ')
            continue
        }
        $compared++
        $verdict = Get-AdfaGpoVersionVerdict -DsVersion $dsVersion -SysvolVersion $sysvolVersion -ReadFrom $pdc -Config $Config
        if ($verdict.Status -ne $script:Status.Pass) {
            $mismatched++
            $rows += New-AdfaGpoVersionRow @rowArgs -Status $verdict.Status -Evidence 'directory and SYSVOL' -Detail $verdict.Detail
        }
    }

    # SYSVOL folders named by a GPO GUID with no container visible to this account.
    $orphans = $null
    if ($listingOk) {
        $orphans = 0
        foreach ($name in @($listing.Names)) {
            $upper = ([string]$name).ToUpperInvariant()
            if ($upper -notmatch $guidPattern -or $containerGuids.ContainsKey($upper)) { continue }
            $orphans++
            $orphanStatus = [string]$Config['OrphanFolderStatus']
            $rows += New-AdfaGpoVersionRow -Scope $Domain -Item ("GPO folder without container: {0}" -f $upper) -Status $orphanStatus -Evidence 'SYSVOL' -GpoGuid $upper -ReadFrom $pdc `
                -Detail ("SYSVOL folder with no container visible to this account: {0}\{1} on {2} is named by a GPO GUID, and no groupPolicyContainer with that GUID was returned under CN=Policies,CN=System. Microsoft calls such a folder an orphaned GPO in the file system. A container this account cannot read looks the same as a missing one. Graded {3}: {4}." -f $policies, $upper, $pdc, $orphanStatus, [string]$Config['ThresholdSource'])
        }
    }
    elseif (-not $portOk -and -not [string]::IsNullOrWhiteSpace($reachCause)) {
        $rows += New-AdfaGpoVersionRow -Scope $Domain -Item ("GPO folder listing: {0}" -f $Domain) -Status $script:Status.NotAssessed -Evidence 'none' -ReadFrom $pdc `
            -Detail ("{0} This is not a clean result." -f (Get-AdfaDcGateText -Cause $reachCause -NotRead ('port {0} (SMB) of {1} was not probed, {2} was not listed and SYSVOL folders with no container were not looked for' -f $smbPort, $pdc, $policies)))
    }
    elseif (-not $portOk) {
        $rows += New-AdfaGpoVersionRow -Scope $Domain -Item ("GPO folder listing: {0}" -f $Domain) -Status $script:Status.NotAssessed -Evidence 'none' -ReadFrom $pdc `
            -Detail ("Unreachable: port {0} (SMB) of {1} did not answer, so {2} was not listed and SYSVOL folders with no container were not looked for. This is not a clean result." -f $smbPort, $pdc, $policies)
    }
    else {
        $lead = Get-AdfaGpoFailureLead -Class $listingClass
        $listingError = ''
        $listingType = ''
        if ($null -ne $listing) { $listingError = ([string]$listing.Error).Trim(); $listingType = [string]$listing.ErrorType }
        $rows += New-AdfaGpoVersionRow -Scope $Domain -Item ("GPO folder listing: {0}" -f $Domain) -Status $script:Status.NotAssessed -Evidence 'none' -ReadFrom $pdc `
            -Detail ("{0}: {1} could not be listed on {2}, so SYSVOL folders with no container were not looked for. This is not a clean result. Reported: {3} (exception type: {4})" -f $lead, $policies, $pdc, $listingError, $listingType)
    }

    $summary = Get-AdfaGpoDomainVerdict -Domain $Domain -ReadFrom $pdc -Population $population -Compared $compared -Mismatched $mismatched -NotAssessed $notAssessed -Config $Config
    $summaryDetail = [string]$summary.Detail
    if ($listingOk) {
        $summaryDetail = ("{0} SYSVOL folder(s) with no container visible to this account: {1}. {2} folder(s) of the Policies folder whose name is not a GPO GUID (such as PolicyDefinitions, the central store) were not considered." -f $summaryDetail, $orphans, $nonGuidFolders)
    }
    # Evidence says what was measured for this domain, as on the GPO rows: the containers were read
    # (the directory), and SYSVOL only when the Policies folder was listed or at least one GPT.INI
    # version was taken from a file.
    $summaryEvidence = 'directory'
    if ($listingOk -or $sysvolVersionsRead -gt 0) { $summaryEvidence = 'directory and SYSVOL' }
    $rows += New-AdfaGpoVersionRow -Scope $Domain -Item $summaryItem -Status $summary.Status -Evidence $summaryEvidence -ReadFrom $pdc -Detail $summaryDetail `
        -Population $population -Compared $compared -Mismatched $mismatched -NotAssessedCount $notAssessed -FoldersWithoutContainer $orphans
    return @($rows)
}

function Get-AdfaGpoVersion {
    <#
    .SYNOPSIS
        GPO version consistency, per scoped domain: each GPO's version in the directory against the
        version in its GPT.INI in SYSVOL, both read from the domain's PDC emulator, and SYSVOL GPO
        folders with no container. Read-only.
    .DESCRIPTION
        Two seams, each read-only and neither of which throws: Get-AdfaGpoContainerRaw (Get-ADDomain
        and Get-ADObject) and Get-AdfaGpoSysvolRaw (a port probe, a folder listing and GPT.INI reads).
        No GroupPolicy cmdlet is used: Learn does not document the Gpo object's version properties.
        Nothing is written: no Set-GP*, no Backup-GPO, no gpupdate, and GPT.INI is opened for reading
        only.

        DECLARED POPULATION: the domains named in -Domains. Each gets exactly one "GPO version
        summary: <domain>" row, whatever happened to its reads; with none scoped there is one "GPO
        version (no domain scoped)" row. Per domain, the population is the number of
        groupPolicyContainer objects returned, stated in the summary's Population column. An
        exception while one domain is handled makes its summary Not Assessed and never ends the
        section.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$Domains = @(),
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    $scoped = New-Object System.Collections.ArrayList
    foreach ($name in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        if (@($scoped | Where-Object { $_ -eq $name.Trim() }).Count -eq 0) { [void]$scoped.Add($name.Trim()) }
    }
    if ($scoped.Count -eq 0) {
        $rows += New-AdfaGpoVersionRow -Item 'GPO version (no domain scoped)' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail 'No domain was scoped for this run, so no GPO version was read. This is not a clean result.'
        return @($rows)
    }
    foreach ($domain in $scoped) {
        try {
            $raw = Get-AdfaGpoContainerRaw -DomainName $domain -AdParams $AdParams -Config $Config
            $sysvol = $null
            if ($raw.Ok -and -not [string]::IsNullOrWhiteSpace([string]$raw.Pdc)) {
                $targets = @()
                foreach ($c in @($raw.Containers | Where-Object { $null -ne $_ })) {
                    $path = Get-AdfaGpoSysvolPath -Pdc ([string]$raw.Pdc) -Domain $domain -Guid ([string]$c.Guid) -FileSysPath ([string]$c.FileSysPath) -Config $Config
                    if ($path.Ok) { $targets += [pscustomobject]@{ Guid = ([string]$c.Guid).ToUpperInvariant(); IniPath = [string]$path.IniPath } }
                }
                $sysvol = Get-AdfaGpoSysvolRaw -Pdc ([string]$raw.Pdc) -Domain $domain -Targets $targets -Config $Config
            }
            $rows += @(Get-AdfaGpoDomainFinding -Domain $domain -Raw $raw -Sysvol $sysvol -Config $Config)
        }
        catch {
            # A defect in this tool, not in the directory. Fail closed for this domain only.
            $rows += New-AdfaGpoVersionRow -Scope $domain -Item ("GPO version summary: {0}" -f $domain) -Status $script:Status.NotAssessed -Evidence 'none' `
                -Detail ("Not assessed: handling the GPO versions of {0} failed inside this tool, so nothing about this domain is graded; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$_.Exception.Message)
        }
    }
    return @($rows)
}

function Merge-AdfaGpoConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in GPO version table, with validation. The Gpo
        validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: MismatchStatus (Warning or Fail, the grade of a GPO whose directory
        and GPT.INI versions differ) and OrphanFolderStatus (Warning or Info, the grade of a SYSVOL
        GPO folder with no container):

            { "Gpo": { "MismatchStatus": "Fail", "OrphanFolderStatus": "Info" } }

        What it cannot: the filter, the property list, the share, the folder and file names, the
        port, the size bound and the sources. Every such key is refused as unknown, so a file cannot
        make the tool read another path or ask for every attribute.

        Refused with the reason: an override that is not one object, an empty object, an unknown
        key, a null, a value that is not a single text value (named by its type), and a status that
        is not one of the two the key allows (a mismatch or an orphan folder is never reported as a
        pass).

        Provenance follows the keys: ThresholdSource is rewritten to name the override's source for
        exactly the keys it supplied.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("GPO config override must be a single object with named keys (for example {{ ""MismatchStatus"": ""Fail"" }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) {
        throw 'GPO config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $known = @('MismatchStatus', 'OrphanFolderStatus')
    $allowed = @{ MismatchStatus = @('Warning', 'Fail'); OrphanFolderStatus = @('Warning', 'Info') }
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("GPO config override names an unknown key '{0}'. Known keys: {1}. The filter, the property list, the share, the folder and file names, the port, the size bound and the sources cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        if ($supplied -contains $name) { throw ("GPO config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) {
            throw ("GPO config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name)
        }
        if ($value -isnot [string]) {
            # Named by its type, never by [string]$value: a list holding 'Fail' would print as 'Fail'
            # and read as if that allowed value had been refused.
            throw ("GPO config override sets '{0}' to a value of type {1}, not a single text value. It must be the text {2}: a finding of this kind is never reported as a pass." -f $name, $value.GetType().Name, ($allowed[$name] -join ' or '))
        }
        $statusMatch = @($allowed[$name] | Where-Object { $_ -eq $value.Trim() })
        if ($statusMatch.Count -eq 0) {
            throw ("GPO config override sets '{0}' to '{1}'. It must be {2}: a finding of this kind is never reported as a pass." -f $name, $value, ($allowed[$name] -join ' or '))
        }
        $merged[$name] = [string]$statusMatch[0]
        $supplied += $name
    }
    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
    $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
    if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
    $merged['ThresholdSource'] = $text
    return $merged
}

# ===========================================================================
# region Password policy
# ===========================================================================

function Get-AdfaPasswordPolicy {
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName, [hashtable]$AdParams = @{})
    $rows = @()
    try {
        $p = @{} + $AdParams; $p.Identity = $DomainName
        $dp = Get-ADDefaultDomainPasswordPolicy @p
        $rows += [pscustomobject]@{
            Scope = $DomainName; PolicyName = 'Default Domain Policy'
            MinPasswordLength = $dp.MinPasswordLength
            PasswordHistoryCount = $dp.PasswordHistoryCount
            MaxPasswordAgeDays = $dp.MaxPasswordAge.Days
            MinPasswordAgeDays = $dp.MinPasswordAge.Days
            ComplexityEnabled = $dp.ComplexityEnabled
            LockoutThreshold = $dp.LockoutThreshold
            ReversibleEncryptionEnabled = $dp.ReversibleEncryptionEnabled
            Status = $(if ($dp.MinPasswordLength -ge 14 -and $dp.ComplexityEnabled -and $dp.LockoutThreshold -gt 0) { $script:Status.Pass } else { $script:Status.Warning })
        }
    }
    catch {
        $rows += [pscustomobject]@{ Scope = $DomainName; PolicyName = 'Default Domain Policy'; Status = $script:Status.NotAssessed; Detail = $_.Exception.Message }
    }
    try {
        $fp = @{} + $AdParams; $fp.Filter = '*'; $fp.Server = $DomainName
        $fgpp = @(Get-ADFineGrainedPasswordPolicy @fp)
        foreach ($g in $fgpp) {
            $rows += [pscustomobject]@{
                Scope = $DomainName; PolicyName = ("FGPP: {0}" -f $g.Name)
                MinPasswordLength = $g.MinPasswordLength; PasswordHistoryCount = $g.PasswordHistoryCount
                MaxPasswordAgeDays = $g.MaxPasswordAge.Days; MinPasswordAgeDays = $g.MinPasswordAge.Days
                ComplexityEnabled = $g.ComplexityEnabled; LockoutThreshold = $g.LockoutThreshold
                ReversibleEncryptionEnabled = $g.ReversibleEncryptionEnabled
                Status = $script:Status.Info
            }
        }
    }
    catch {
        # Previously silent. With no row at all, a report showing only the default policy could
        # not be distinguished from one where the FGPP query failed - and an absent key and a
        # measured absence are different claims.
        $rows += New-Finding -Scope $DomainName -Area 'PasswordPolicy' -Item 'Fine-grained password policies' `
            -Status $script:Status.NotAssessed `
            -Detail ("Could not be enumerated: {0}. This is NOT the same as 'no fine-grained policies exist'." -f $_.Exception.Message)
    }
    return @($rows)
}

# ===========================================================================
# region Privileged accounts & security posture
# ===========================================================================

function Get-AdfaSecurityPosture {
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName, [bool]$IsRootDomain, [hashtable]$AdParams = @{}, [int]$KrbtgtMaxAgeDays = 180)
    $rows = @()
    $srv = @{} + $AdParams; $srv.Server = $DomainName

    # krbtgt password age
    try {
        $k = Get-ADUser -Identity 'krbtgt' -Properties PasswordLastSet @srv
        $age = $null
        if ($k.PasswordLastSet) { $age = [int]((Get-Date) - $k.PasswordLastSet).TotalDays }
        $st = $script:Status.NotAssessed
        if ($null -ne $age) { $st = $(if ($age -le $KrbtgtMaxAgeDays) { $script:Status.Pass } else { $script:Status.Warning }) }
        $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'krbtgt password age' -Status $st -Detail ("{0} days (threshold {1})" -f $age, $KrbtgtMaxAgeDays)
    }
    catch { $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'krbtgt password age' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }

    # AD Recycle Bin (forest scoped, but report per root domain)
    if ($IsRootDomain) {
        try {
            $rb = Get-ADOptionalFeature -Filter "Name -eq 'Recycle Bin Feature'" @AdParams
            $enabled = ($rb -and @($rb.EnabledScopes).Count -gt 0)
            $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'AD Recycle Bin' -Status $(if ($enabled) { $script:Status.Pass } else { $script:Status.Warning }) -Detail $(if ($enabled) { 'Enabled.' } else { 'Not enabled - object recovery limited.' })
        }
        catch { $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'AD Recycle Bin' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }
    }

    # Tombstone lifetime
    try {
        $cnc = (Get-ADRootDSE @srv).configurationNamingContext
        $dsDn = "CN=Directory Service,CN=Windows NT,CN=Services,$cnc"
        $ds = Get-ADObject -Identity $dsDn -Properties tombstoneLifetime @srv
        $tsl = $ds.tombstoneLifetime
        $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'Tombstone lifetime' -Status $(if ($null -ne $tsl -and $tsl -ge 180) { $script:Status.Pass } else { $script:Status.Warning }) -Detail ("{0} days" -f $tsl)
    }
    catch { $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'Tombstone lifetime' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }

    # Machine account quota
    try {
        $dp = @{} + $AdParams; $dp.Identity = $DomainName
        $dn = (Get-ADDomain @dp).DistinguishedName
        $mq = Get-ADObject -Identity $dn -Properties 'ms-DS-MachineAccountQuota' @srv
        $q = $mq.'ms-DS-MachineAccountQuota'
        $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'Machine account quota' -Status $(if ($q -eq 0) { $script:Status.Pass } else { $script:Status.Warning }) -Detail ("ms-DS-MachineAccountQuota = {0} (0 recommended)" -f $q)
    }
    catch { $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'Machine account quota' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }

    # Privileged accounts with reversible/DES/RC4 or password-not-required
    try {
        $weak = @(Get-ADUser -Filter { (UserAccountControl -band 0x80) -or (UserAccountControl -band 0x200000) } -Properties UserAccountControl @srv)
        $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'DES/reversible-encryption accounts' -Status $(if ($weak.Count -eq 0) { $script:Status.Pass } else { $script:Status.Warning }) -Detail ("{0} accounts flagged" -f $weak.Count)
    }
    catch { $rows += New-Finding -Scope $DomainName -Area 'Security' -Item 'DES/reversible-encryption accounts' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }

    return @($rows)
}

function Get-AdfaStaleObject {
    <#
    .SYNOPSIS
        StaleObjects, per domain: inactive enabled users and computers (STALE-001/002, PORT-PLAN C14),
        enabled users with an old password, and PasswordNeverExpires users.
    .DESCRIPTION
        Directory reads only, each sent to the domain: the domain head's msDS-LogonTimeSyncInterval,
        the enabled user and computer populations (Get-AdfaStalePopulationRaw, a capped count), then
        three listed-property, capped searches through Get-AdfaStaleRaw (never every property),
        each graded by its pure verdict. Before C14 the inactive rows used a -Filter that dropped every
        account that never logged on, stated no logon-sync caveat and had no cap. The
        PasswordNeverExpires row is unchanged.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [int]$StaleDays = 90,
        [hashtable]$Config = $script:Config.Stale,
        [AllowNull()]$Now = $null
    )
    $rows = @()
    $srv = @{} + $AdParams; $srv.Server = $DomainName
    $when = Get-Date
    if ($Now -is [datetime]) { $when = $Now }
    $nowUtc = $when
    if ($nowUtc.Kind -ne [System.DateTimeKind]::Utc) { $nowUtc = $nowUtc.ToUniversalTime() }
    $interval = Get-AdfaLogonSyncIntervalRaw -DomainName $DomainName -AdParams $AdParams
    $cutoff = $nowUtc.AddDays(-1 * $StaleDays)
    $maxObjects = [int]$Config['MaxObjects']
    # The declared populations: the enabled users and computers this account can see, counted once
    # each, so that a read that returned nothing is never taken for "none stale" when it saw nothing.
    $userPopulation = Get-AdfaStalePopulationRaw -DomainName $DomainName -Kind 'User' -MaxObjects $maxObjects -AdParams $AdParams
    $computerPopulation = Get-AdfaStalePopulationRaw -DomainName $DomainName -Kind 'Computer' -MaxObjects $maxObjects -AdParams $AdParams
    $users = Get-AdfaStaleRaw -DomainName $DomainName -Kind 'User' -CutoffUtc $cutoff -MaxObjects $maxObjects -AdParams $AdParams
    $rows += Get-AdfaStaleCountVerdict -DomainName $DomainName -Kind 'User' -Raw $users -Interval $interval -StaleDays $StaleDays -Now $nowUtc -Population $userPopulation -Config $Config
    $computers = Get-AdfaStaleRaw -DomainName $DomainName -Kind 'Computer' -CutoffUtc $cutoff -MaxObjects $maxObjects -AdParams $AdParams
    $rows += Get-AdfaStaleCountVerdict -DomainName $DomainName -Kind 'Computer' -Raw $computers -Interval $interval -StaleDays $StaleDays -Now $nowUtc -Population $computerPopulation -Config $Config
    $passwords = Get-AdfaStaleRaw -DomainName $DomainName -Kind 'Password' -CutoffUtc ($nowUtc.AddDays(-1 * [int]$Config['PasswordAgeDays'])) -MaxObjects $maxObjects -AdParams $AdParams
    $rows += Get-AdfaPasswordAgeVerdict -DomainName $DomainName -Raw $passwords -Now $nowUtc -Population $userPopulation -Config $Config
    # PORT-PLAN C15 (INV-009): stale DISABLED users and computers, inventory only - the same listed,
    # capped read with ACCOUNTDISABLE set, against the disabled accounts as the declared population.
    $disabledUserPopulation = Get-AdfaStalePopulationRaw -DomainName $DomainName -Kind 'DisabledUser' -MaxObjects $maxObjects -AdParams $AdParams
    $disabledUsers = Get-AdfaStaleRaw -DomainName $DomainName -Kind 'DisabledUser' -CutoffUtc $cutoff -MaxObjects $maxObjects -AdParams $AdParams
    $rows += Get-AdfaStaleDisabledVerdict -DomainName $DomainName -Kind 'User' -Raw $disabledUsers -Interval $interval -StaleDays $StaleDays -Now $nowUtc -Population $disabledUserPopulation -Config $Config
    $disabledComputerPopulation = Get-AdfaStalePopulationRaw -DomainName $DomainName -Kind 'DisabledComputer' -MaxObjects $maxObjects -AdParams $AdParams
    $disabledComputers = Get-AdfaStaleRaw -DomainName $DomainName -Kind 'DisabledComputer' -CutoffUtc $cutoff -MaxObjects $maxObjects -AdParams $AdParams
    $rows += Get-AdfaStaleDisabledVerdict -DomainName $DomainName -Kind 'Computer' -Raw $disabledComputers -Interval $interval -StaleDays $StaleDays -Now $nowUtc -Population $disabledComputerPopulation -Config $Config
    try {
        $neverExpire = @(Get-ADUser -Filter { Enabled -eq $true -and PasswordNeverExpires -eq $true } @srv)
        $rows += New-Finding -Scope $DomainName -Area 'Stale' -Item 'PasswordNeverExpires users' -Status $(if ($neverExpire.Count -eq 0) { $script:Status.Pass } else { $script:Status.Warning }) -Detail ("{0} enabled users" -f $neverExpire.Count)
    }
    catch { $rows += New-Finding -Scope $DomainName -Area 'Stale' -Item 'PasswordNeverExpires users' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }
    return @($rows)
}

# ===========================================================================
# region Identity inventory (full user / computer export)
# ===========================================================================

function ConvertTo-AdfaFlatObject {
    <#
    .SYNOPSIS
        Flattens an AD object's requested properties into a CSV-safe [pscustomobject].
        Multi-valued attributes are joined with ';'. Only properties actually present are read.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$InputObject,
        [Parameter(Mandatory)][string[]]$Property
    )
    $o = [ordered]@{}
    foreach ($p in $Property) {
        $v = $null
        if ($InputObject.PSObject.Properties.Name -contains $p) { $v = $InputObject.$p }
        if ($null -eq $v) { $o[$p] = '' }
        elseif ($v -is [string]) { $o[$p] = $v }
        elseif ($v -is [bool] -or $v -is [datetime] -or $v.GetType().IsPrimitive) { $o[$p] = $v }
        elseif ($v -is [System.Collections.IEnumerable]) { $o[$p] = ((@($v) | ForEach-Object { "$_" }) -join ';') }
        else { $o[$p] = "$v" }
    }
    return [pscustomobject]$o
}

function Get-AdfaObjectPropertyUnion {
    # Union of populated property names across a set (AD returns only set properties per object).
    [CmdletBinding()]
    [OutputType([string[]])]
    param([Parameter(Mandatory)][AllowEmptyCollection()]$Objects)
    $set = New-Object System.Collections.Generic.HashSet[string]
    foreach ($obj in @($Objects)) {
        foreach ($name in $obj.PSObject.Properties.Name) { [void]$set.Add($name) }
    }
    return (@($set) | Sort-Object)
}

function Get-AdfaSecretAttributeName {
    <#
    .SYNOPSIS
        Pure: every attribute name this tool never puts in a property list (PORT-PLAN C4b) - the seven
        LAPS names of Laps.NeverRead and DirectoryRead.SecretNames, each once.
    .OUTPUTS
        [string[]]
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [hashtable]$LapsConfig = $script:Config.Laps,
        [hashtable]$Config = $script:Config.DirectoryRead
    )
    $names = @(@($LapsConfig['NeverRead']) + @($Config['SecretNames']) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim() })
    return @($names | Sort-Object -Unique)
}

function Get-AdfaRefusedPropertyName {
    <#
    .SYNOPSIS
        Pure: the names in a property list that must never be sent (PORT-PLAN C4b) - empty when the
        list may be sent.
    .DESCRIPTION
        Refused: a list with no name at all, a blank name, any name holding a wildcard character
        (* or ?; "-Properties *" asks for every attribute set on the object, and Learn documents no
        partial wildcard), any name that is not a plain name - a letter, then only letters, digits
        and hyphens - and any name equal, without regard to case, to a name of the secret list.
        The plain-name rule is this tool's, not a Microsoft value: a name with an attribute option
        or a range (";binary", ";range=0-1"), an OID, or a space could carry a secret attribute past
        a by-name comparison ("ms-Mcs-AdmPwd;binary" is not equal to "ms-Mcs-AdmPwd"), so it is
        refused rather than parsed. Whether the ActiveDirectory module would accept such a name in
        -Properties was not measured. With no secret list to check against, every name is refused:
        a guard that cannot check does not let a list through. Unlike Get-AdfaLapsRefusedProperty
        there is no rule on the beginning of a name, so pwdLastSet and the LAPS expiry attributes
        are allowed.
    .OUTPUTS
        [string[]]
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$PropertyNames = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$SecretNames = @()
    )
    $secret = @(@($SecretNames) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { ([string]$_).Trim() })
    $names = @(@($PropertyNames) | Where-Object { $null -ne $_ })
    $refused = New-Object System.Collections.Generic.List[string]
    if ($names.Count -eq 0) { $refused.Add('(an empty list)') }
    foreach ($n in $names) {
        $s = [string]$n
        if ([string]::IsNullOrWhiteSpace($s)) { $refused.Add('(a blank name)'); continue }
        if ($s -match '[*?]') { $refused.Add($s); continue }
        # A plain name only (tool rule): no option, range, OID or space can slip past the compare below.
        if ($s -cnotmatch '^[A-Za-z][A-Za-z0-9-]*$') { $refused.Add($s); continue }
        if ($secret.Count -eq 0) { $refused.Add($s); continue }
        foreach ($x in $secret) {
            if ([string]::Equals($s.Trim(), $x, [System.StringComparison]::OrdinalIgnoreCase)) { $refused.Add($s); break }
        }
    }
    return $refused.ToArray()
}

function Get-AdfaCapSource {
    <#
    .SYNOPSIS
        Pure: where a cap came from, in the words a row uses (PORT-PLAN C4b) - "<Label>.<Key>, a
        tool default" or "<Label>.<Key>, set in the -ConfigOverridePath file".
    .DESCRIPTION
        Read from the provenance Merge-AdfaSpecConfig records: a table no file supplied keeps the
        built-in ThresholdSource; a merged one names the file, then " for " and the keys the file
        supplied, then "; ", the built-in source, ", for " and the other keys. The file's path is
        not repeated in the phrase (it stays in the merged ThresholdSource): a row's text is what
        the recommendation map matches. A provenance this function cannot read is said to be so,
        never called a default.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][hashtable]$Config,
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)][string]$Label
    )
    $name = ("{0}.{1}" -f $Label, $Key)
    $base = [string]$BaseConfig['ThresholdSource']
    $source = [string]$Config['ThresholdSource']
    if ([string]::Equals($source, $base, [System.StringComparison]::Ordinal)) { return ("{0}, a tool default" -f $name) }
    $head = $source
    $builtIn = @()
    $tail = ("; {0}, for " -f $base)
    $at = $source.LastIndexOf($tail, [System.StringComparison]::Ordinal)
    if ($at -ge 0) {
        $head = $source.Substring(0, $at)
        $builtIn = @($source.Substring($at + $tail.Length).Split(',') | ForEach-Object { $_.Trim() })
    }
    $for = $head.LastIndexOf(' for ', [System.StringComparison]::Ordinal)
    if ($for -ge 0) {
        $supplied = @($head.Substring($for + 5).Split(',') | ForEach-Object { $_.Trim() })
        if (@($supplied | Where-Object { [string]::Equals($_, $Key, [System.StringComparison]::Ordinal) }).Count -gt 0) { return ("{0}, set in the -ConfigOverridePath file" -f $name) }
        if (@($builtIn | Where-Object { [string]::Equals($_, $Key, [System.StringComparison]::Ordinal) }).Count -gt 0) { return ("{0}, a tool default" -f $name) }
    }
    return ("{0}, whose source was not recorded (see the {1} ThresholdSource)" -f $name, $Label)
}

function Get-AdfaIdentityExportRaw {
    <#
    .SYNOPSIS
        The read of one domain's user or computer export (PORT-PLAN C4b): the C15 directory seam,
        with the declared filter and property list of the DirectoryRead table. Never throws.
    .DESCRIPTION
        Replaces "Get-ADUser -Filter * -Properties *" and "Get-ADComputer -Filter * -Properties *".
        The list is checked here before anything is sent (a wildcard, a blank, an empty list or a
        secret attribute refuses the read, Refused), and again by Get-AdfaInventoryDirectoryRaw,
        which refuses a wildcard. -Server is the domain, -ResultSetSize MaxObjects + 1, so a domain
        with more objects than the cap is Capped, never read as complete.
    .OUTPUTS
        [pscustomobject] the seam's result (Ok, Error, ErrorType, NotFound, Records, Count, Capped,
        Filter, Identity) plus Refused, Kind and Properties.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [Parameter(Mandatory)][ValidateSet('User', 'Computer')][string]$Kind,
        [hashtable]$Config = $script:Config.DirectoryRead,
        [AllowNull()][AllowEmptyCollection()][string[]]$SecretNames = @(Get-AdfaSecretAttributeName),
        [ValidateRange(1, 1000000)][int]$MaxObjects = [int]$script:Config.Inventory['MaxObjects'],
        [hashtable]$AdParams = @{}
    )
    $filter = [string]$Config['UserExportFilter']
    $props = @($Config['UserExportProperties'])
    if ($Kind -eq 'Computer') {
        $filter = [string]$Config['ComputerExportFilter']
        $props = @($Config['ComputerExportProperties'])
    }
    $refused = @(Get-AdfaRefusedPropertyName -PropertyNames $props -SecretNames $SecretNames)
    if ([string]::IsNullOrWhiteSpace($filter)) { $refused += '(no LDAP filter)' }
    if ($refused.Count -gt 0) {
        return [pscustomobject]@{ Ok = $false; Error = ("the property list was refused before anything was sent, because it names {0}; this is a defect in the tool's DirectoryRead table, not in the directory" -f ($refused -join ', '))
            ErrorType = ''; NotFound = $false; Records = @(); Count = 0; Capped = $false; Filter = $filter; Identity = ''; Refused = $true; Kind = $Kind; Properties = @($props)
        }
    }
    $raw = Get-AdfaInventoryDirectoryRaw -Server $DomainName -LDAPFilter $filter -Properties $props -MaxObjects $MaxObjects -AdParams $AdParams
    $raw | Add-Member -NotePropertyName 'Refused' -NotePropertyValue $false -Force
    $raw | Add-Member -NotePropertyName 'Kind' -NotePropertyValue $Kind -Force
    $raw | Add-Member -NotePropertyName 'Properties' -NotePropertyValue @($props) -Force
    return $raw
}

function ConvertTo-AdfaIdentityExport {
    <#
    .SYNOPSIS
        Pure: the AllUsers_ / AllComputers_ CSV rows of one domain, and why they cannot be counted
        when they cannot (PORT-PLAN C4b).
    .DESCRIPTION
        One row per object: the declared columns in the order of the list (multi-valued joined with
        ';'), then Enabled - True or False from the ACCOUNTDISABLE bit of userAccountControl, empty
        when userAccountControl was not returned or is not a number - and ListComplete. Cause is ''
        for a complete read, and otherwise names why the objects are not counted: refused (nothing
        was sent), unreachable, access denied, timed out, read failed, a cap reached (the rows are
        kept, at most MaxObjects, each marked ListComplete "No: ...", so the CSV never reads as the
        domain's whole list) or a read that returned nothing (which cannot be told from a read that
        saw nothing). The summary row is Not Assessed whenever Cause is set, never 0.
    .OUTPUTS
        [pscustomobject] Rows, Cause.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][ValidateSet('User', 'Computer')][string]$Kind,
        [AllowNull()]$Raw,
        # The declared list (DirectoryRead.UserExportProperties or ComputerExportProperties): the CSV columns.
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Columns,
        [ValidateRange(1, 1000000)][int]$MaxObjects = 100000,
        [int]$AccountDisableBit = 2,
        # Where MaxObjects came from, in the row's words (Get-AdfaCapSource).
        [string]$CapSource = 'Inventory.MaxObjects, a tool default'
    )
    $noun = 'users'
    if ($Kind -eq 'Computer') { $noun = 'computers' }
    $what = ("the {0} of this domain" -f $noun)
    $out = [pscustomobject]@{ Rows = @(); Cause = '' }
    if ($null -ne $Raw -and [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Refused')) {
        $out.Cause = ("Reading {0} was refused: {1}." -f $what, ([string](Get-AdfaConfigValue -Entry $Raw -Name 'Error')).Trim().TrimEnd('.'))
        return $out
    }
    if ($null -eq $Raw -or -not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) {
        $out.Cause = Get-AdfaInventoryReadCause -Raw $Raw -What $what -MaxObjects $MaxObjects -CapSource $CapSource
        return $out
    }
    $records = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Records') | Where-Object { $null -ne $_ })
    $complete = 'Yes'
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'Capped')) {
        $out.Cause = Get-AdfaInventoryReadCause -Raw $Raw -What $what -MaxObjects $MaxObjects -CapSource $CapSource
        $complete = ("No: the read reached its cap of {0} objects ({1}), so objects after it are not listed" -f $MaxObjects, $CapSource)
        $records = @($records | Select-Object -First $MaxObjects)
    }
    elseif ($records.Count -eq 0) {
        $out.Cause = ("Reading {0} returned no object. A read that returned nothing cannot be told from a read that saw nothing, so they were not counted." -f $what)
        return $out
    }
    $rows = @()
    foreach ($r in $records) {
        $row = ConvertTo-AdfaFlatObject -InputObject $r -Property $Columns
        $enabled = ''
        $uac = Get-AdfaConfigValue -Entry $r -Name 'userAccountControl'
        $uacNumber = [int64]0
        if ($null -ne $uac -and [int64]::TryParse(([string]$uac), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$uacNumber)) {
            $enabled = (($uacNumber -band [int64]$AccountDisableBit) -eq 0)
        }
        $row | Add-Member -NotePropertyName 'Enabled' -NotePropertyValue $enabled -Force
        $row | Add-Member -NotePropertyName 'ListComplete' -NotePropertyValue $complete -Force
        $rows += $row
    }
    $out.Rows = @($rows)
    return $out
}

function Get-AdfaIdentitySummary {
    <#
    .SYNOPSIS
        Compact summary of a full user/computer export for the HTML report.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowEmptyCollection()]$Users,
        [AllowEmptyCollection()]$Computers,
        [int]$StaleDays = 90,
        # PORT-PLAN C15: why an export failed. Before v1.32.0 a failed export was summarised as 0
        # objects with status Info; it is now Not Assessed with its cause, never 0.
        [AllowNull()][AllowEmptyString()][string]$UsersError = '',
        [AllowNull()][AllowEmptyString()][string]$ComputersError = ''
    )
    $rows = @()
    # PORT-PLAN C4b: Enabled and Disabled are each counted from a value that was read. An object whose
    # Enabled is neither True nor False (userAccountControl not returned) is counted in neither, and
    # the row says how many - before v1.33.0 it was counted as disabled.
    $enabledOf = {
        param($o)
        if ($null -eq $o -or $null -eq $o.PSObject.Properties['Enabled']) { return '' }
        return [string]$o.Enabled
    }
    $kinds = @(
        @{ Object = 'Users'; Noun = 'user'; Items = @($Users); Error = $UsersError; Csv = 'AllUsers'; List = 'UserExportProperties' }
        @{ Object = 'Computers'; Noun = 'computer'; Items = @($Computers); Error = $ComputersError; Csv = 'AllComputers'; List = 'ComputerExportProperties' }
    )
    foreach ($k in $kinds) {
        if (-not [string]::IsNullOrWhiteSpace([string]$k.Error)) {
            $rows += [pscustomobject]@{ Scope = $DomainName; Object = $k.Object; Total = ''; Enabled = ''; Disabled = ''; Status = $script:Status.NotAssessed; Detail = ("The {0} export could not be used, so the {0}s of this domain were not counted - not zero: {1}" -f $k.Noun, ([string]$k.Error).Trim()) }
            continue
        }
        $items = @($k.Items | Where-Object { $null -ne $_ })
        $on = @($items | Where-Object { (& $enabledOf $_) -eq 'True' }).Count
        $off = @($items | Where-Object { (& $enabledOf $_) -eq 'False' }).Count
        $unread = $items.Count - $on - $off
        $detail = ("Declared attribute list (DirectoryRead.{0}), not every attribute, in csv\{1}_<domain>.csv." -f $k.List, $k.Csv)
        if ($unread -gt 0) { $detail = ("{0} {1} object(s) returned no readable userAccountControl and are counted neither enabled nor disabled." -f $detail, $unread) }
        $rows += [pscustomobject]@{ Scope = $DomainName; Object = $k.Object; Total = $items.Count; Enabled = $on; Disabled = $off; Status = $script:Status.Info; Detail = $detail }
    }
    return @($rows)
}

# ===========================================================================
# region Deep security & reliability (pure helpers)
# ===========================================================================

function Test-AdfaEsc1Template {
    <#
    .SYNOPSIS
        ESC1 heuristic for a certificate template: enrollee-supplies-subject + auth EKU +
        no manager approval + no enrollment-agent signatures. Pure function.
    .OUTPUTS
        [pscustomobject] Vulnerable (bool), Reason
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][pscustomobject]$Template)

    $names = $Template.PSObject.Properties.Name
    $nameFlag = if ($names -contains 'msPKI-Certificate-Name-Flag') { [int64]$Template.'msPKI-Certificate-Name-Flag' } else { 0 }
    $enrollFlag = if ($names -contains 'msPKI-Enrollment-Flag') { [int64]$Template.'msPKI-Enrollment-Flag' } else { 0 }
    $raSig = if ($names -contains 'msPKI-RA-Signature') { [int]$Template.'msPKI-RA-Signature' } else { 0 }
    $ekus = @()
    if ($names -contains 'pKIExtendedKeyUsage' -and $Template.'pKIExtendedKeyUsage') { $ekus = @($Template.'pKIExtendedKeyUsage') }

    $suppliesSubject = ($nameFlag -band $script:Config.EnrolleeSuppliesSubject) -ne 0
    $approvalRequired = ($enrollFlag -band $script:Config.PendAllRequests) -ne 0
    $authEku = ($ekus.Count -eq 0) -or (@($ekus | Where-Object { $script:Config.AuthEkuOids -contains $_ }).Count -gt 0)

    $vulnerable = $suppliesSubject -and $authEku -and (-not $approvalRequired) -and ($raSig -le 0)
    $reason = if ($vulnerable) {
        'ENROLLEE_SUPPLIES_SUBJECT + client-auth EKU + no manager approval + no enrollment-agent signature (ESC1-susceptible; verify enrollment rights).'
    }
    else { 'Not ESC1-susceptible by configuration.' }
    return [pscustomobject]@{ Vulnerable = $vulnerable; Reason = $reason }
}

function Find-AdfaDuplicateSpn {
    <#
    .SYNOPSIS
        Finds servicePrincipalName values registered on more than one object. Pure function.
    .OUTPUTS
        [pscustomobject[]] Spn, Holders
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][AllowEmptyCollection()]$Objects)
    $map = @{}
    foreach ($o in @($Objects)) {
        if ($o.PSObject.Properties.Name -notcontains 'ServicePrincipalName') { continue }
        $id = if ($o.PSObject.Properties.Name -contains 'SamAccountName') { $o.SamAccountName } else { "$($o.DistinguishedName)" }
        foreach ($spn in @($o.ServicePrincipalName)) {
            if (-not $spn) { continue }
            $key = "$spn".ToLower()
            if (-not $map.ContainsKey($key)) { $map[$key] = New-Object System.Collections.Generic.List[string] }
            if (-not $map[$key].Contains($id)) { $map[$key].Add($id) }
        }
    }
    $dupes = foreach ($k in $map.Keys) {
        if ($map[$k].Count -gt 1) { [pscustomobject]@{ Spn = $k; Holders = ($map[$k] -join '; ') } }
    }
    return @($dupes | Where-Object { $null -ne $_ })
}

# ===========================================================================
# region Deep security & reliability (collectors)
# ===========================================================================

function Get-AdfaPkiHealth {
    <#
    .SYNOPSIS
        Enterprise PKI (AD CS): enrolment CAs and ESC1-susceptible certificate templates.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([hashtable]$AdParams = @{})
    $rows = @()
    try {
        $cfg = (Get-ADRootDSE @AdParams).configurationNamingContext
        $pkiBase = "CN=Public Key Services,CN=Services,$cfg"
        $cas = @(Get-ADObject -SearchBase "CN=Enrollment Services,$pkiBase" -LDAPFilter '(objectClass=pKIEnrollmentService)' -Properties dNSHostName, cn @AdParams -ErrorAction Stop)
        if ($cas.Count -eq 0) {
            $rows += New-Finding -Area 'PKI' -Item 'Certificate Authorities' -Status $script:Status.Info -Detail 'No enterprise CA found in the forest.'
            return @($rows)
        }
        $rows += New-Finding -Area 'PKI' -Item 'Certificate Authorities' -Status $script:Status.Info -Detail (("{0} CA(s): {1}" -f $cas.Count, (($cas | ForEach-Object { $_.dNSHostName }) -join ', ')))

        $templates = @(Get-ADObject -SearchBase "CN=Certificate Templates,$pkiBase" -LDAPFilter '(objectClass=pKICertificateTemplate)' -Properties 'msPKI-Certificate-Name-Flag', 'msPKI-Enrollment-Flag', 'msPKI-RA-Signature', 'pKIExtendedKeyUsage', 'cn' @AdParams -ErrorAction Stop)
        $vuln = @()
        foreach ($t in $templates) {
            $r = Test-AdfaEsc1Template -Template $t
            if ($r.Vulnerable) { $vuln += $t.cn }
        }
        if ($vuln.Count -gt 0) {
            $rows += New-Finding -Area 'PKI' -Item 'ESC1-susceptible templates' -Status $script:Status.Fail -Detail ("{0}: {1}" -f $vuln.Count, ($vuln -join ', '))
        }
        else {
            $rows += New-Finding -Area 'PKI' -Item 'ESC1-susceptible templates' -Status $script:Status.Pass -Detail ("0 of {0} templates flagged by the ESC1 heuristic." -f $templates.Count)
        }
    }
    catch {
        $rows += New-Finding -Area 'PKI' -Item 'AD CS assessment' -Status $script:Status.NotAssessed -Detail $_.Exception.Message
    }
    return @($rows)
}

# ---------------------------------------------------------------------------
# Dangerous rights in the directory (PORT-PLAN C9): replication and control rights on the domain
# head, write and control rights on AdminSDHolder and on every groupPolicyContainer, judged against
# an allowlist matched by SID only. Section Acl, report section "Dangerous ACLs (DCSync)".
# ---------------------------------------------------------------------------

function New-AdfaAclRow {
    <#
    .SYNOPSIS
        Pure: one Dangerous ACLs row. Every row has the same columns, so a consumer never has to test
        whether a column exists.
    .DESCRIPTION
        Detail names SIDs, never a display name. Names are in Principals, a column no verdict reads and
        the consolidated findings never choose a recommendation from. A count that was not measured is
        an empty string, never 0.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = '',
        [AllowEmptyString()][string]$Evidence = '',
        [AllowEmptyString()][string]$CatalogueId = '',
        [AllowEmptyString()][string]$Severity = '',
        [AllowEmptyString()][string]$ObjectKind = '',
        [AllowEmptyString()][string]$ObjectDn = '',
        [AllowEmptyString()][string]$ReadFrom = '',
        [AllowEmptyString()][string]$OwnerSid = '',
        [AllowNull()]$AceCount = $null,
        [AllowEmptyString()][string]$FlaggedSids = '',
        [AllowEmptyString()][string]$RightsHeld = '',
        [AllowEmptyString()][string]$Principals = '',
        [AllowEmptyString()][string]$Undecided = '',
        [AllowEmptyString()][string]$AllowlistNote = '',
        [AllowNull()]$Population = $null,
        [AllowNull()]$ReadCount = $null,
        [AllowNull()]$FlaggedCount = $null,
        [AllowNull()]$NotAssessedCount = $null
    )
    $row = New-Finding -Scope $Scope -Area 'ACL' -Item $Item -Status $Status -Detail $Detail
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $asText = { param($Number) if ($null -eq $Number) { return '' } return ([int64]$Number).ToString($inv) }
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    $row | Add-Member -NotePropertyName 'Evidence' -NotePropertyValue $Evidence
    $row | Add-Member -NotePropertyName 'CatalogueId' -NotePropertyValue $CatalogueId
    $row | Add-Member -NotePropertyName 'Severity' -NotePropertyValue $Severity
    $row | Add-Member -NotePropertyName 'ObjectKind' -NotePropertyValue $ObjectKind
    $row | Add-Member -NotePropertyName 'ObjectDn' -NotePropertyValue $ObjectDn
    $row | Add-Member -NotePropertyName 'ReadFrom' -NotePropertyValue $ReadFrom
    $row | Add-Member -NotePropertyName 'OwnerSid' -NotePropertyValue $OwnerSid
    $row | Add-Member -NotePropertyName 'AceCount' -NotePropertyValue (& $asText $AceCount)
    $row | Add-Member -NotePropertyName 'FlaggedSids' -NotePropertyValue $FlaggedSids
    $row | Add-Member -NotePropertyName 'RightsHeld' -NotePropertyValue $RightsHeld
    $row | Add-Member -NotePropertyName 'Principals' -NotePropertyValue $Principals
    $row | Add-Member -NotePropertyName 'Undecided' -NotePropertyValue $Undecided
    $row | Add-Member -NotePropertyName 'AllowlistNote' -NotePropertyValue $AllowlistNote
    $row | Add-Member -NotePropertyName 'Population' -NotePropertyValue (& $asText $Population)
    $row | Add-Member -NotePropertyName 'ReadCount' -NotePropertyValue (& $asText $ReadCount)
    $row | Add-Member -NotePropertyName 'FlaggedCount' -NotePropertyValue (& $asText $FlaggedCount)
    $row | Add-Member -NotePropertyName 'NotAssessedCount' -NotePropertyValue (& $asText $NotAssessedCount)
    return $row
}

function ConvertTo-AdfaAclDescriptor {
    <#
    .SYNOPSIS
        The Windows seam of C9: a security descriptor as the directory read handed it over, read in
        memory into its owner SID, whether a DACL is present, and every ACE of the DACL in its order.
        Never throws. Writes nothing.
    .DESCRIPTION
        Which .NET type Get-ADObject returns for nTSecurityDescriptor is not published on Learn, so two
        are read: System.DirectoryServices.ActiveDirectorySecurity (its GetSecurityDescriptorBinaryForm)
        and a byte array. Anything else is Unparseable, with its type named.

        The binary form is read with System.Security.AccessControl.RawSecurityDescriptor. NOT with
        GetAccessRules: measured in this session (2026-11-16, Windows PowerShell 5.1 and PowerShell 7),
        GetAccessRules returns one synthetic "Everyone, full control" rule for a descriptor that has no
        DACL, which would turn "no DACL was returned" into a finding about Everyone. Here a descriptor
        whose ControlFlags lack DiscretionaryAclPresent (4) is DaclAbsent; one whose flag is set but
        whose DiscretionaryAcl is null is NullDacl - a NULL DACL, which Learn documents as granting full
        access to any user, measured 2026-11-16 to come from SDDL "D:NO_ACCESS_CONTROL" with the flag
        set; and an EMPTY DACL is a DACL that was read and holds no ACE.

        Each ACE becomes a record whose principal is its SID text. An ACE that is not a plain or an
        object allow or deny ACE, or that carries callback data, is Kind Other: the verdict does not
        guess what it grants and fails closed. The access mask is read as an unsigned 32-bit number, so
        GENERIC_READ (0x80000000) is not a negative number.

        Order: from a byte array it is the DACL's own. An ActiveDirectorySecurity holding a canonical
        DACL hands it back regrouped - measured 2026-11-16 on 5.1 and 7, the explicit allow ACEs came
        back reordered among themselves, explicit denies still first and inherited ACEs last - and one
        holding a non-canonical DACL hands it back as it is. Neither changes which deny comes before
        which allow, the one order Test-AdfaAclDenyCover relies on.
    .OUTPUTS
        [pscustomobject] Ok, Class (Read | NotReturned | DaclAbsent | NullDacl | Unparseable), Error, OwnerSid,
        Aces (Index, Sid, Allow, Deny, Kind Common|Object|Other, Mask, InheritOnly, Inherited,
        ObjectType, InheritedObjectType), AceCount.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Value)
    $out = [pscustomobject]@{ Ok = $false; Class = 'Unparseable'; Error = ''; OwnerSid = ''; Aces = @(); AceCount = 0 }
    if ($null -eq $Value) { $out.Class = 'NotReturned'; $out.Error = 'no value was given'; return $out }
    try {
        $bytes = $null
        if ($Value -is [byte[]]) { $bytes = [byte[]]$Value }
        elseif ([string]$Value.GetType().FullName -eq 'System.DirectoryServices.ActiveDirectorySecurity') { $bytes = [byte[]]$Value.GetSecurityDescriptorBinaryForm() }
        if ($null -eq $bytes) {
            $out.Error = ("a value of type {0} is not a security descriptor this tool reads" -f $Value.GetType().FullName)
            return $out
        }
        $raw = [System.Security.AccessControl.RawSecurityDescriptor]::new($bytes, 0)
        if ($null -ne $raw.Owner) { $out.OwnerSid = [string]$raw.Owner.Value }
        if ((([int]$raw.ControlFlags) -band 4) -eq 0) {
            $out.Class = 'DaclAbsent'
            $out.Error = 'the descriptor carries no DACL (the DACL-present flag is clear)'
            return $out
        }
        if ($null -eq $raw.DiscretionaryAcl) {
            # The DACL-present flag is set and no ACL came with it: a NULL DACL (measured 2026-11-16 with
            # SDDL "D:NO_ACCESS_CONTROL"), which Learn documents as granting full access to any user.
            $out.Class = 'NullDacl'
            $out.Error = 'the descriptor carries a NULL DACL (the DACL-present flag is set and no ACL is attached)'
            return $out
        }
        $records = New-Object System.Collections.ArrayList
        $index = 0
        foreach ($ace in $raw.DiscretionaryAcl) {
            $kind = 'Other'; $allow = $false; $deny = $false; $sid = ''; $mask = [int64]0; $objectType = ''; $inheritedType = ''
            $flags = [int]$ace.AceFlags
            if ($ace -is [System.Security.AccessControl.QualifiedAce] -and -not [bool]$ace.IsCallback) {
                if ($ace -is [System.Security.AccessControl.ObjectAce]) {
                    $kind = 'Object'
                    $objectFlags = [int]$ace.ObjectAceFlags
                    if (($objectFlags -band 1) -ne 0) { $objectType = $ace.ObjectAceType.ToString().ToLowerInvariant() }
                    if (($objectFlags -band 2) -ne 0) { $inheritedType = $ace.InheritedObjectAceType.ToString().ToLowerInvariant() }
                }
                elseif ($ace -is [System.Security.AccessControl.CommonAce]) { $kind = 'Common' }
                if ($kind -ne 'Other') {
                    $qualifier = [string]$ace.AceQualifier
                    if ($qualifier -eq 'AccessAllowed') { $allow = $true }
                    elseif ($qualifier -eq 'AccessDenied') { $deny = $true }
                    else { $kind = 'Other' }
                    $sid = [string]$ace.SecurityIdentifier.Value
                    $mask = [int64]$ace.AccessMask
                    if ($mask -lt 0) { $mask = $mask + [int64]4294967296 }
                }
            }
            [void]$records.Add([pscustomobject]@{
                    Index = $index; Sid = $sid; Allow = $allow; Deny = $deny; Kind = $kind; Mask = $mask
                    InheritOnly = (($flags -band 8) -ne 0); Inherited = (($flags -band 16) -ne 0)
                    ObjectType = $objectType; InheritedObjectType = $inheritedType
                })
            $index++
        }
        $out.Aces = $records.ToArray()
        $out.AceCount = $records.Count
        $out.Class = 'Read'
        $out.Ok = $true
    }
    catch {
        $out.Class = 'Unparseable'
        $out.Error = [string]$_.Exception.Message
    }
    return $out
}

function Get-AdfaAclNormalMask {
    <#
    .SYNOPSIS
        Pure: an access mask with its two generic bits replaced by what they stand for on a directory
        object - GENERIC_ALL (0x10000000) by GenericAll 983551, GENERIC_WRITE (0x40000000) by
        GenericWrite 131112 (Learn: ads_rights_enum, ActiveDirectoryRights).
    .OUTPUTS
        [int64]
    #>
    [CmdletBinding()]
    [OutputType([int64])]
    param([int64]$Mask, [Parameter(Mandatory)][hashtable]$Config)
    $m = $Config['Masks']
    $value = $Mask
    if (($value -band [int64]$m['GenericAllBit']) -ne 0) { $value = $value -bor [int64]$m['GenericAll'] }
    if (($value -band [int64]$m['GenericWriteBit']) -ne 0) { $value = $value -bor [int64]$m['GenericWrite'] }
    return $value
}

function Get-AdfaAclAceRight {
    <#
    .SYNOPSIS
        Pure: the rights this section grades that one ACE grants, decided by its access mask bits and
        object type - never by a rights name, whose text for a combined mask is not stable.
    .DESCRIPTION
        First the object type. An object type that is the GUID of the object's own class, or of a class
        above it (Config.ClassGuids for -ObjectKind), is the node of the object itself, which grants on
        every node below it (OBJECT_TYPE_LIST level zero, MS-DTYP 2.5.3.2), so the ACE is graded as if it
        had no object type (tool rule for the classes above the structural one: may over-report, never
        under-reports). An object type that is any other GUID scopes the ACE to that one node: only
        the replication right whose GUID it is can be granted (by ExtendedRight, which GenericAll also
        carries), and WriteDacl, WriteOwner, write of all properties and full control are never
        granted on the object by it.

        With no object type: GenericAll: every bit of 983551 (0xF01FF), or the GENERIC_ALL bit; it
        grants every right below. WriteDacl 0x40000. WriteOwner 0x80000. WriteAllProperties:
        WriteProperty 0x20, or GENERIC_WRITE - a write scoped to one property or property set is not
        graded. AllExtendedRights: ExtendedRight 0x100, which Learn documents as every extended right,
        so it also grants the three replication rights. Any other extended right (Apply-Group-Policy on
        a GPO, for instance) is not graded. ReadControl, which GenericWrite also carries, is not a right
        this section grades, so a plain read ACE grants nothing here.
    .OUTPUTS
        [pscustomobject] GenericAll, Atoms (in the order of Config.RightNames), Scope (None | Class | Node).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)]$Ace, [Parameter(Mandatory)][string]$ObjectKind, [Parameter(Mandatory)][hashtable]$Config)
    $m = $Config['Masks']
    $mask = Get-AdfaAclNormalMask -Mask ([int64]$Ace.Mask) -Config $Config
    $objectType = ([string]$Ace.ObjectType).Trim().ToLowerInvariant()
    $scope = 'None'
    if ($objectType -ne '') {
        $classes = @()
        $classTable = $Config['ClassGuids']
        if ($null -ne $classTable -and $classTable.Contains($ObjectKind)) { $classes = @(@($classTable[$ObjectKind]) | ForEach-Object { ([string]$_).ToLowerInvariant() }) }
        if ($classes -contains $objectType) { $scope = 'Class'; $objectType = '' }
        else { $scope = 'Node' }
    }
    $atoms = New-Object System.Collections.Generic.List[string]
    if ($scope -eq 'Node') {
        # Scoped to one node that is not the object itself: only a replication right's own GUID counts.
        if (($mask -band [int64]$m['ExtendedRight']) -ne 0) {
            foreach ($rep in @($Config['ReplicationRights'])) {
                if (([string]$rep['Guid']).ToLowerInvariant() -eq $objectType) { $atoms.Add([string]$rep['Name']) }
            }
        }
        return [pscustomobject]@{ GenericAll = $false; Atoms = $atoms.ToArray(); Scope = $scope }
    }
    $genericAll = (($mask -band [int64]$m['GenericAll']) -eq [int64]$m['GenericAll'])
    if ($genericAll) {
        foreach ($name in @($Config['RightNames'])) { $atoms.Add([string]$name) }
    }
    else {
        if (($mask -band [int64]$m['WriteDacl']) -ne 0) { $atoms.Add('WriteDacl') }
        if (($mask -band [int64]$m['WriteOwner']) -ne 0) { $atoms.Add('WriteOwner') }
        if (($mask -band [int64]$m['WriteProperty']) -ne 0) { $atoms.Add('WriteAllProperties') }
        if (($mask -band [int64]$m['ExtendedRight']) -ne 0) {
            $atoms.Add('AllExtendedRights')
            foreach ($rep in @($Config['ReplicationRights'])) { $atoms.Add([string]$rep['Name']) }
        }
    }
    return [pscustomobject]@{ GenericAll = $genericAll; Atoms = $atoms.ToArray(); Scope = $scope }
}

function Test-AdfaAclDenyCover {
    <#
    .SYNOPSIS
        Pure: whether an allow ACE is cancelled by a deny ACE that comes before it in the DACL.
    .DESCRIPTION
        The real access check depends on the reader's token, which this tool cannot see, so a deny is
        honoured only when it is beyond doubt: it names the same SID, comes earlier in the DACL, is not
        inherit-only, applies to every object type (none) or to the allow's own object type, and covers
        every graded bit of the allow (WriteDacl, WriteOwner, WriteProperty, ExtendedRight, after the
        generic bits are mapped). Anything less leaves the grant flagged. Tool rule (Learn's MS-DTYP
        access check evaluates ACEs in order; group membership is not expanded here).
    .OUTPUTS
        [bool]
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param([AllowEmptyCollection()]$Aces = @(), [int]$Index, [Parameter(Mandatory)][hashtable]$Config)
    $list = @($Aces)
    if ($Index -lt 0 -or $Index -ge $list.Count) { return $false }
    $m = $Config['Masks']
    $graded = [int64]$m['WriteDacl'] -bor [int64]$m['WriteOwner'] -bor [int64]$m['WriteProperty'] -bor [int64]$m['ExtendedRight']
    $allow = $list[$Index]
    $relevant = (Get-AdfaAclNormalMask -Mask ([int64]$allow.Mask) -Config $Config) -band $graded
    if ($relevant -eq 0) { return $false }
    $allowType = ([string]$allow.ObjectType).Trim().ToLowerInvariant()
    for ($j = 0; $j -lt $Index; $j++) {
        $d = $list[$j]
        if ([string]$d.Kind -eq 'Other' -or [bool]$d.Allow -or -not [bool]$d.Deny -or [bool]$d.InheritOnly) { continue }
        if ([string]$d.Sid -ne [string]$allow.Sid) { continue }
        $denyType = ([string]$d.ObjectType).Trim().ToLowerInvariant()
        if ($denyType -ne '' -and $denyType -ne $allowType) { continue }
        $denyMask = Get-AdfaAclNormalMask -Mask ([int64]$d.Mask) -Config $Config
        if (($denyMask -band $relevant) -eq $relevant) { return $true }
    }
    return $false
}

function Get-AdfaAclAllowedSet {
    <#
    .SYNOPSIS
        Pure: the allowlist for one kind of object, as SID text -> the rights it may hold there.
    .DESCRIPTION
        Built from Config.Allowlist and Config.AdditionalAllowed (what an override file adds). A row
        with Sid is that SID; a row with Rid and Scope Domain is <scoped domain SID>-RID, and with Scope
        ForestRoot <forest root domain SID>-RID. A row whose domain SID was not read is left out - the
        verdict then fails closed on any SID it can no longer decide. Rights '*' is every right in
        Config.RightNames. Nothing here reads a name.
    .OUTPUTS
        [hashtable] SID -> @{ Rights = string[]; Reasons = string[] (override reasons) }
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][string]$ObjectKind,
        [AllowEmptyString()][string]$DomainSid = '',
        [AllowEmptyString()][string]$RootDomainSid = '',
        [Parameter(Mandatory)][hashtable]$Config
    )
    $set = @{}
    $all = @($Config['RightNames'])
    foreach ($r in @(@($Config['Allowlist']) + @($Config['AdditionalAllowed']))) {
        if ($null -eq $r -or $r -isnot [System.Collections.IDictionary]) { continue }
        if (@($r['Objects']) -notcontains $ObjectKind) { continue }
        $sid = ''
        if ($r.Contains('Sid') -and -not [string]::IsNullOrWhiteSpace([string]$r['Sid'])) { $sid = [string]$r['Sid'] }
        elseif ([string]$r['Scope'] -eq 'Domain') { if ($DomainSid -ne '') { $sid = ("{0}-{1}" -f $DomainSid, [string]$r['Rid']) } }
        elseif ([string]$r['Scope'] -eq 'ForestRoot') { if ($RootDomainSid -ne '') { $sid = ("{0}-{1}" -f $RootDomainSid, [string]$r['Rid']) } }
        if ($sid -eq '') { continue }
        $sid = $sid.Trim().ToUpperInvariant()
        $rights = @($r['Rights'])
        if ($rights -contains '*') { $rights = $all }
        if (-not $set.ContainsKey($sid)) { $set[$sid] = @{ Rights = @(); Reasons = @() } }
        $set[$sid]['Rights'] = @(@($set[$sid]['Rights']) + @($rights | ForEach-Object { [string]$_ }) | Select-Object -Unique)
        if ($r.Contains('Reason')) { $set[$sid]['Reasons'] = @(@($set[$sid]['Reasons']) + @([string]$r['Reason'])) }
    }
    return $set
}

function Get-AdfaAclAnalysis {
    <#
    .SYNOPSIS
        Pure: one object's descriptor against the allowlist, for the rights one row grades.
    .DESCRIPTION
        Every ACE in DACL order. Skipped: a deny ACE (it grants nothing), an inherit-only ACE (Learn: it
        "does not control access to the object to which it is attached") and an ACE that grants none of
        the row's rights. NOT skipped: an ACE scoped to a child class through InheritedObjectType that is
        not inherit-only, which Learn documents as effective on the container too; and an object ACE
        whose object type is the object's own class or a class above it, which Get-AdfaAclAceRight
        grades as unscoped. An ACE of a type the
        tool does not interpret is counted in Unrecognised. An allow ACE whose SID may hold every right
        it grants passes; one cancelled by an earlier deny (Test-AdfaAclDenyCover) is recorded and
        passes; otherwise its SID is flagged with the rights it may not hold - unless the SID is an
        account-domain SID that cannot be decided because the domain SID it would be judged against was
        not read (with the forest root's SID unread, that includes the scoped domain's own RIDs that the
        allowlist judges against the root, -519 and -498), when it is Undecided. With Owner set for the
        row, the owner is graded as holding
        WriteDacl, which Learn says an owner holds implicitly.

        The principal is compared by SID text only. No name is read here.
    .OUTPUTS
        [pscustomobject] Flagged (Sid, Rights, GenericAll), Undecided (SID text), Unrecognised,
        Considered, Cancelled, DenyNotes, OverrideUsed, AceCount.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Descriptor,
        [Parameter(Mandatory)][string]$ObjectKind,
        [Parameter(Mandatory)][string]$RowKey,
        [AllowEmptyString()][string]$DomainSid = '',
        [AllowEmptyString()][string]$RootDomainSid = '',
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rowConfig = $Config['Rows'][$RowKey]
    $rowRights = @($rowConfig['Rights'])
    $allowed = Get-AdfaAclAllowedSet -ObjectKind $ObjectKind -DomainSid $DomainSid -RootDomainSid $RootDomainSid -Config $Config
    $aces = @(@($Descriptor.Aces) | Where-Object { $null -ne $_ })
    $flaggedOrder = New-Object System.Collections.Generic.List[string]
    $flaggedRights = @{}
    $flaggedGeneric = @{}
    $undecided = New-Object System.Collections.Generic.List[string]
    $cancelled = New-Object System.Collections.Generic.List[string]
    $denyNotes = New-Object System.Collections.Generic.List[string]
    $overrideUsed = New-Object System.Collections.Generic.List[string]
    $unrecognised = 0
    $considered = 0
    $denySids = @($aces | Where-Object { [string]$_.Kind -ne 'Other' -and [bool]$_.Deny } | ForEach-Object { ([string]$_.Sid).ToUpperInvariant() })
    # Whether a SID that is not allowed can be decided at all: an account-domain SID is undecidable when
    # the scoped domain's SID was not read, or when the forest root's was not read and the SID is either
    # not of the scoped domain or carries a RID the allowlist judges against the forest root (Enterprise
    # Admins, ERODC) - with the root's SID unread, the scoped domain may itself be the root, so its own
    # -519 or -498 may be a default holder.
    $rootRids = @(@(@($Config['Allowlist']) + @($Config['AdditionalAllowed'])) | Where-Object { $null -ne $_ -and $_ -is [System.Collections.IDictionary] -and [string]$_['Scope'] -eq 'ForestRoot' } | ForEach-Object { [string]$_['Rid'] })
    $isUndecidable = {
        param([string]$Sid)
        $parsed = ConvertFrom-AdfaSidValue -Value $Sid
        if (-not $parsed.Ok -or -not $parsed.IsAccountDomain) { return $false }
        if ($DomainSid -eq '') { return $true }
        if ($RootDomainSid -eq '') {
            if ($parsed.DomainPart -ne $DomainSid.ToUpperInvariant()) { return $true }
            if ($rootRids -contains [string]$parsed.Rid) { return $true }
        }
        return $false
    }
    $addFlag = {
        param([string]$Sid, [string[]]$Rights, [bool]$Generic)
        if (-not $flaggedRights.ContainsKey($Sid)) { $flaggedOrder.Add($Sid); $flaggedRights[$Sid] = @(); $flaggedGeneric[$Sid] = $false }
        $flaggedRights[$Sid] = @(@($flaggedRights[$Sid]) + @($Rights) | Select-Object -Unique)
        if ($Generic) { $flaggedGeneric[$Sid] = $true }
    }
    for ($i = 0; $i -lt $aces.Count; $i++) {
        $ace = $aces[$i]
        if ([string]$ace.Kind -eq 'Other') { $unrecognised++; continue }
        if ([bool]$ace.InheritOnly -or -not [bool]$ace.Allow) { continue }
        $right = Get-AdfaAclAceRight -Ace $ace -ObjectKind $ObjectKind -Config $Config
        $atoms = @(@($right.Atoms) | Where-Object { $rowRights -contains $_ })
        if ($atoms.Count -eq 0) { continue }
        $considered++
        $sid = ([string]$ace.Sid).Trim().ToUpperInvariant()
        $mayHold = @()
        if ($allowed.ContainsKey($sid)) { $mayHold = @($allowed[$sid]['Rights']) }
        $notAllowed = @($atoms | Where-Object { $mayHold -notcontains $_ })
        if ($notAllowed.Count -eq 0) {
            foreach ($reason in @($allowed[$sid]['Reasons'])) { $note = ("{0} ({1})" -f $sid, $reason); if (-not $overrideUsed.Contains($note)) { $overrideUsed.Add($note) } }
            continue
        }
        if (Test-AdfaAclDenyCover -Aces $aces -Index $i -Config $Config) { $cancelled.Add(("{0} (ACE {1})" -f $sid, $i)); continue }
        if ($denySids -contains $sid) { $denyNotes.Add(("{0} (ACE {1})" -f $sid, $i)) }
        if (& $isUndecidable $sid) { if (-not $undecided.Contains($sid)) { $undecided.Add($sid) }; continue }
        & $addFlag $sid $notAllowed ([bool]$right.GenericAll)
    }
    $owner = ([string]$Descriptor.OwnerSid).Trim().ToUpperInvariant()
    if ([bool]$rowConfig['Owner'] -and $owner -ne '') {
        $mayHold = @()
        if ($allowed.ContainsKey($owner)) { $mayHold = @($allowed[$owner]['Rights']) }
        if ($mayHold -notcontains 'WriteDacl') {
            if (& $isUndecidable $owner) { if (-not $undecided.Contains($owner)) { $undecided.Add($owner) } }
            else { & $addFlag $owner @('owner (implicit WriteDacl)') $false }
        }
    }
    $flagged = @(foreach ($s in $flaggedOrder) {
            $ordered = @(@($Config['RightNames']) + @('owner (implicit WriteDacl)') | Where-Object { @($flaggedRights[$s]) -contains $_ })
            [pscustomobject]@{ Sid = $s; Rights = $ordered; GenericAll = [bool]$flaggedGeneric[$s] }
        })
    return [pscustomobject]@{
        Flagged = $flagged; Undecided = $undecided.ToArray(); Unrecognised = $unrecognised; Considered = $considered
        Cancelled = $cancelled.ToArray(); DenyNotes = $denyNotes.ToArray(); OverrideUsed = $overrideUsed.ToArray(); AceCount = $aces.Count
    }
}

function Get-AdfaAclReadLead {
    <#
    .SYNOPSIS
        Pure: the opening of a Not Assessed row for a descriptor that was not read, by class.
    .DESCRIPTION
        Unreachable, access denied and timed out are worded from the exception (type first, then text)
        by Get-AdfaLapsReadFailureLead. A successful answer without nTSecurityDescriptor is "Not
        returned": Learn documents that a search can succeed without the properties the caller cannot
        read, so it is not measured, never "no ACE". A descriptor without a DACL is "No DACL returned":
        this read cannot tell a DACL that was not handed over from an object that has none.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Read, [Parameter(Mandatory)][string]$What)
    if ($null -eq $Read) { return 'Not assessed: the read returned nothing. This is a defect in the tool, not a result.' }
    $class = [string]$Read.Class
    $err = ([string]$Read.Error).Trim()
    if ($class -eq 'Refused') { return ("Not assessed: {0} - nothing was asked of the directory. This is a defect in the tool, not a result." -f $err) }
    if ($class -eq 'NotReturned') {
        return ("Not returned: the directory answered for {0} but returned no nTSecurityDescriptor, so no ACE was read. A read can succeed without the attributes the account may not see; reading the owner and the DACL needs READ_CONTROL on the object. This is not a clean result." -f $What)
    }
    if ($class -eq 'DaclAbsent') {
        return ("No DACL returned: the security descriptor of {0} came back without a DACL, so no ACE was read. Either the DACL was not handed to this account or the object has none - and no DACL at all lets anyone do anything - and this read cannot tell the two apart. This is not a clean result." -f $What)
    }
    if ($class -eq 'Unparseable') { return ("Not read: the security descriptor of {0} could not be read: {1}. This is not a clean result." -f $What, $err) }
    return ("{0} This is not a clean result." -f (Get-AdfaLapsReadFailureLead -Message ([string]$Read.Error) -TypeName ([string]$Read.ErrorType) -What ("the security descriptor of {0}" -f $What)))
}

function Get-AdfaAclObjectVerdict {
    <#
    .SYNOPSIS
        Pure: one object read to one row - the domain head's DCSync row or its control row, the
        AdminSDHolder row, or one GPO's row.
    .DESCRIPTION
        Not Assessed, with the cause, when the descriptor was not read (Get-AdfaAclReadLead). A NULL
        DACL (the present flag set, no ACL) is the row's grade with Everyone (S-1-1-0) flagged for every
        right the row grades: Learn documents that a null DACL grants full access to any user.
        Otherwise the row's grade (Config.FlaggedStatus, a tool default) when at least one SID outside
        the allowlist holds a graded right, naming every such SID and its rights in Detail - also when
        another ACE is of a type the tool does not interpret or another SID could not be decided, which
        the Detail then names; Not Assessed when none is flagged but an ACE was not interpreted or a SID
        could not be decided; Pass otherwise. Every graded row says the allowlist is provisional and
        that matching is by SID only.

        -NameResolver turns a SID into a display name for the Principals column only. It is called for
        the flagged and undecided SIDs, after the verdict, and a SID it cannot name stays a SID marked
        "unresolved". No decision reads a name.
    .OUTPUTS
        [pscustomobject] one row (New-AdfaAclRow).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$ObjectKind,
        [Parameter(Mandatory)][string]$RowKey,
        [Parameter(Mandatory)][string]$What,
        [AllowNull()]$Read,
        [AllowEmptyString()][string]$DomainSid = '',
        [AllowEmptyString()][string]$DomainSidError = '',
        [AllowEmptyString()][string]$RootDomainSid = '',
        [AllowEmptyString()][string]$RootDomainSidError = '',
        [Parameter(Mandatory)][hashtable]$Config,
        [AllowNull()][scriptblock]$NameResolver = $null
    )
    $rowConfig = $Config['Rows'][$RowKey]
    $notRun = 'Not read by this check: the SACL; the members of a group that holds a right (a group is graded as its own SID); and any deny ACE that names a group rather than the SID itself.'
    if ($ObjectKind -eq 'Gpo') { $notRun = ("{0} The permissions of the GPO's folder in SYSVOL were not read either." -f $notRun) }
    $common = @{
        Scope = $Domain; Item = $Item; NotRun = $notRun; CatalogueId = [string]$rowConfig['CatalogueId']; Severity = [string]$rowConfig['Severity']
        ObjectKind = $ObjectKind; AllowlistNote = [string]$Config['AllowlistNote']
    }
    $dn = ''; $server = ''
    if ($null -ne $Read) { $dn = [string]$Read.Dn; $server = [string]$Read.Server }
    $evidence = 'none'
    if ($dn -ne '') { $evidence = ("nTSecurityDescriptor of '{0}', read from {1}" -f $dn, $server) }
    $rightsText = 'a write or control right (WriteDacl, WriteOwner, write of all properties, all extended rights, a replication right or full control) or ownership'
    if ($RowKey -eq 'DCSync') { $rightsText = 'a replication right (DS-Replication-Get-Changes, DS-Replication-Get-Changes-All or DS-Replication-Get-Changes-In-Filtered-Set, held alone or through all extended rights or full control)' }
    elseif ($RowKey -eq 'DomainRootControl') { $rightsText = 'WriteDacl, WriteOwner, write of all properties or full control, or ownership' }
    $nameOf = {
        param([string]$Sid)
        $name = ''
        if ($null -ne $NameResolver) { try { $name = [string](& $NameResolver $Sid) } catch { $name = '' } }
        if ([string]::IsNullOrWhiteSpace($name)) { return ("{0} = unresolved" -f $Sid) }
        return ("{0} = {1}" -f $Sid, $name.Trim())
    }
    if ($null -ne $Read -and [string]$Read.Class -eq 'NullDacl' -and $null -ne $Read.Descriptor) {
        # A NULL DACL was returned: measured, and Microsoft documents it as granting full access to any
        # user, so Everyone holds every right the row grades.
        $status = [string]$Config['FlaggedStatus']
        $everyone = 'S-1-1-0'
        $rowRights = @(@($Config['RightNames']) | Where-Object { @($rowConfig['Rights']) -contains $_ })
        $detail = ("NULL DACL: the security descriptor of {0} came back with the DACL-present flag set and no ACL attached - a NULL DACL, which Microsoft documents as granting full access to any user that requests it - so everyone ({1}) holds {2}. Graded {3}: {4}; {5}." -f `
                $What, $everyone, $rightsText, $status, [string]$Config['ThresholdSource'], [string]$Config['AllowlistNote'])
        return (New-AdfaAclRow @common -Status $status -Detail $detail -Evidence $evidence -ObjectDn $dn -ReadFrom $server -OwnerSid ([string]$Read.Descriptor.OwnerSid) `
                -FlaggedSids $everyone -RightsHeld ("{0}: {1}" -f $everyone, ($rowRights -join ', ')) -Principals (& $nameOf $everyone))
    }
    if ($null -eq $Read -or -not [bool]$Read.Ok -or $null -eq $Read.Descriptor) {
        $owner = ''
        if ($null -ne $Read -and $null -ne $Read.Descriptor) { $owner = [string]$Read.Descriptor.OwnerSid }
        return (New-AdfaAclRow @common -Status $script:Status.NotAssessed -Detail (Get-AdfaAclReadLead -Read $Read -What $What) -Evidence $evidence -ObjectDn $dn -ReadFrom $server -OwnerSid $owner)
    }
    $descriptor = $Read.Descriptor
    $an = Get-AdfaAclAnalysis -Descriptor $descriptor -ObjectKind $ObjectKind -RowKey $RowKey -DomainSid $DomainSid -RootDomainSid $RootDomainSid -Config $Config
    $owner = [string]$descriptor.OwnerSid
    $notes = @()
    if (@($an.Cancelled).Count -gt 0) { $notes += ("{0} grant(s) cancelled by an earlier deny ACE naming the same SID and covering every graded bit: {1}" -f @($an.Cancelled).Count, (@($an.Cancelled) -join ', ')) }
    if (@($an.DenyNotes).Count -gt 0) { $notes += ("{0} flagged grant(s) beside a deny ACE naming the same SID that was not judged to cancel them (a deny counts only when it comes first, applies to the object and covers every graded bit): {1}" -f @($an.DenyNotes).Count, (@($an.DenyNotes) -join ', ')) }
    if (@($an.OverrideUsed).Count -gt 0) { $notes += ("allowed by the config override: {0}" -f (@($an.OverrideUsed) -join '; ')) }
    if ($notes.Count -gt 0) { $evidence = ("{0}; {1}" -f $evidence, ($notes -join '; ')) }
    $unrecognisedText = ''
    if ([int]$an.Unrecognised -gt 0) {
        $unrecognisedText = ("{0} ACE(s) of {1} are of a type this tool does not interpret (not a plain or object allow or deny ACE, or a callback ACE), so what they grant was not interpreted" -f [int]$an.Unrecognised, $What)
    }
    $flagged = @($an.Flagged)
    $undecided = @($an.Undecided)
    $principals = (@(@($flagged | ForEach-Object { [string]$_.Sid }) + @($undecided) | ForEach-Object { & $nameOf $_ }) -join '; ')
    $undecidedText = ''
    if ($undecided.Count -gt 0) {
        $why = @()
        if ($DomainSid -eq '') { $why += ("the SID of {0} was not read ({1})" -f $Domain, $DomainSidError) }
        if ($RootDomainSid -eq '') { $why += ("the SID of the forest root domain was not read ({0})" -f $RootDomainSidError) }
        $undecidedText = (" {0} SID(s) holding one of these rights could not be decided against the allowlist, because {1}; they are listed in the Undecided column." -f $undecided.Count, ($why -join ' and '))
    }
    # A measured grant outside the allowlist takes the grade before anything the tool could not judge -
    # an ACE it does not interpret, or a SID it cannot decide - so neither hides it; both are named.
    if ($flagged.Count -gt 0) {
        $status = [string]$Config['FlaggedStatus']
        $list = @($flagged | ForEach-Object { "{0} ({1})" -f $_.Sid, (@($_.Rights) -join ', ') })
        $unrecognisedNote = ''
        if ($unrecognisedText -ne '') { $unrecognisedNote = (" Besides, {0}." -f $unrecognisedText) }
        $detail = ("{0} principal(s) outside the allowlist hold {1} on {2}: {3}. Principals were matched by SID only, never by name; a group is graded as its own SID and its members were not expanded.{4}{5} Graded {6}: {7}; {8}." -f `
                $flagged.Count, $rightsText, $What, ($list -join '; '), $undecidedText, $unrecognisedNote, $status, [string]$Config['ThresholdSource'], [string]$Config['AllowlistNote'])
        return (New-AdfaAclRow @common -Status $status -Detail $detail -Evidence $evidence -ObjectDn $dn -ReadFrom $server -OwnerSid $owner -AceCount ([int]$an.AceCount) `
                -FlaggedSids (@($flagged | ForEach-Object { [string]$_.Sid }) -join '; ') -RightsHeld (@($flagged | ForEach-Object { "{0}: {1}" -f $_.Sid, (@($_.Rights) -join ', ') }) -join '; ') `
                -Principals $principals -Undecided ($undecided -join '; '))
    }
    if ($unrecognisedText -ne '') {
        return (New-AdfaAclRow @common -Status $script:Status.NotAssessed -Evidence $evidence -ObjectDn $dn -ReadFrom $server -OwnerSid $owner -AceCount ([int]$an.AceCount) -Principals $principals -Undecided ($undecided -join '; ') `
                -Detail ("Not assessed: no principal outside the allowlist was found holding {0} on {1}, but {2}, and no grade is given.{3} This is not a clean result." -f $rightsText, $What, $unrecognisedText, $undecidedText))
    }
    if ($undecided.Count -gt 0) {
        return (New-AdfaAclRow @common -Status $script:Status.NotAssessed -Evidence $evidence -ObjectDn $dn -ReadFrom $server -OwnerSid $owner -AceCount ([int]$an.AceCount) -Principals $principals -Undecided ($undecided -join '; ') `
                -Detail ("Not assessed: no principal outside the allowlist was found holding {0} on {1}, but{2} This is not a clean result." -f $rightsText, $What, $undecidedText))
    }
    $detail = ("No principal outside the allowlist holds {0} on {1}: {2} ACE(s) read, {3} of them granting one of these rights, each to a SID the allowlist allows it. Principals were matched by SID only, never by name; {4}." -f `
            $rightsText, $What, [int]$an.AceCount, [int]$an.Considered, [string]$Config['AllowlistNote'])
    return (New-AdfaAclRow @common -Status $script:Status.Pass -Detail $detail -Evidence $evidence -ObjectDn $dn -ReadFrom $server -OwnerSid $owner -AceCount ([int]$an.AceCount))
}

function Get-AdfaAclDomainRaw {
    <#
    .SYNOPSIS
        Directory seam of C9: a domain's distinguished name and SID. Read-only. Never throws.
    .DESCRIPTION
        Get-ADDomain -Identity <domain> -Server <domain>, with the caller's other AD parameters
        (-Credential): the read goes to the domain it is about, as the descriptor reads do, never to the
        run's -Server (Learn: -Server takes a fully qualified domain name). Ok is true when the
        distinguished name was read; the SID is parsed with ConvertFrom-AdfaSidValue and is '' with
        DomainSidError when it was not. DomainMode (C10: whether the Protected Users delegation restriction
        is in force) is the text of the DomainMode property, '' when the answer did not carry it.
    .OUTPUTS
        [pscustomobject] Ok, Error, ErrorType, DomainDn, DomainSid, DomainSidError, DomainMode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$DomainName, [hashtable]$AdParams = @{})
    $out = [pscustomobject]@{ Ok = $false; Error = ''; ErrorType = ''; DomainDn = ''; DomainSid = ''; DomainSidError = ''; DomainMode = '' }
    try {
        $domainArgs = @{} + $AdParams
        $domainArgs.Identity = $DomainName
        $domainArgs.Server = $DomainName
        $domainArgs.ErrorAction = 'Stop'
        $domain = Get-ADDomain @domainArgs
        if ($null -ne $domain) {
            $dnProp = $domain.PSObject.Properties['DistinguishedName']
            if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $out.DomainDn = ([string]$dnProp.Value).Trim() }
            $sidProp = $domain.PSObject.Properties['DomainSID']
            if ($null -ne $sidProp -and $null -ne $sidProp.Value) {
                $parsed = ConvertFrom-AdfaSidValue -Value $sidProp.Value
                if ($parsed.Ok) { $out.DomainSid = $parsed.Text }
                else { $out.DomainSidError = ("the DomainSID Get-ADDomain returned for {0} could not be read as a SID: {1}" -f $DomainName, $parsed.Error) }
            }
            else { $out.DomainSidError = ("Get-ADDomain returned no DomainSID for {0}" -f $DomainName) }
            $modeProp = $domain.PSObject.Properties['DomainMode']
            if ($null -ne $modeProp -and $null -ne $modeProp.Value) { $out.DomainMode = ([string]$modeProp.Value).Trim() }
        }
        if ($out.DomainDn -eq '') { $out.Error = ("Get-ADDomain returned no DistinguishedName for {0}" -f $DomainName) }
        else { $out.Ok = $true }
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        $out.DomainSidError = $out.Error
    }
    return $out
}

function Get-AdfaAclObjectRaw {
    <#
    .SYNOPSIS
        Directory seam of C9: one object's security descriptor. Read-only. Never throws.
    .DESCRIPTION
        Get-ADObject -Identity <DN> -Server <domain> -Properties nTSecurityDescriptor, with the caller's
        other AD parameters (-Credential) and the domain as -Server - so the read goes to the domain it is
        about, and neither the AD: drive nor Get-Acl is used. A property list that is not
        nTSecurityDescriptor alone is refused before any call. The value is read by
        ConvertTo-AdfaAclDescriptor, in memory; nothing is written and Persist is never called.

        Classes: Read; NotReturned (the answer held no nTSecurityDescriptor); DaclAbsent; Unparseable;
        Refused; and, for a read that threw, Unreachable, AccessDenied, TimedOut or Error
        (Get-AdfaDirectoryReadErrorClass, from the exception type first).
    .OUTPUTS
        [pscustomobject] Ok, Class, Error, ErrorType, Dn, Server, Descriptor.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Dn,
        [Parameter(Mandatory)][string]$Server,
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{ Ok = $false; Class = ''; Error = ''; ErrorType = ''; Dn = $Dn; Server = $Server; Descriptor = $null }
    $properties = @(@($Config['Properties']) | ForEach-Object { [string]$_ })
    if ($properties.Count -ne 1 -or $properties[0] -ne 'nTSecurityDescriptor') {
        $out.Class = 'Refused'
        $out.Error = ("the property list is '{0}', not nTSecurityDescriptor alone" -f ($properties -join ','))
        return $out
    }
    try {
        $objectArgs = @{} + $AdParams
        $objectArgs.Identity = $Dn
        $objectArgs.Server = $Server
        $objectArgs.Properties = @($properties)
        $objectArgs.ErrorAction = 'Stop'
        $object = Get-ADObject @objectArgs
        $sdProp = $null
        if ($null -ne $object) { $sdProp = $object.PSObject.Properties['nTSecurityDescriptor'] }
        if ($null -eq $sdProp -or $null -eq $sdProp.Value) {
            $out.Class = 'NotReturned'
            $out.Error = 'the answer held no nTSecurityDescriptor'
            return $out
        }
        $descriptor = ConvertTo-AdfaAclDescriptor -Value $sdProp.Value
        $out.Descriptor = $descriptor
        $out.Class = [string]$descriptor.Class
        $out.Error = [string]$descriptor.Error
        $out.Ok = [bool]$descriptor.Ok
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        $out.Class = Get-AdfaDirectoryReadErrorClass -Message $out.Error -TypeName $out.ErrorType
    }
    return $out
}

function Get-AdfaAclGpoRaw {
    <#
    .SYNOPSIS
        Directory seam of C9: every groupPolicyContainer of a domain, each with its security
        descriptor. Read-only. Never throws.
    .DESCRIPTION
        One search: Get-ADObject -Server <domain> -SearchBase CN=Policies,CN=System,<domain DN>
        -SearchScope OneLevel -LDAPFilter (objectClass=groupPolicyContainer), asking for
        nTSecurityDescriptor only. Every GPO the search returns is one item, in the shape
        Get-AdfaAclObjectRaw returns, so a GPO whose answer held no descriptor is NotReturned and is
        never dropped. A GPO this account may not see at all is not returned by the search (Learn), and
        cannot be counted. A property list that is not nTSecurityDescriptor alone is refused before any
        call.
    .OUTPUTS
        [pscustomobject] Ok, Class, Error, ErrorType, SearchBase, Items (Guid, Dn, Read).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [Parameter(Mandatory)][string]$DomainDn,
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{ Ok = $false; Class = ''; Error = ''; ErrorType = ''; SearchBase = ("{0},{1}" -f [string]$Config['PoliciesContainerRdn'], $DomainDn); Items = @() }
    $properties = @(@($Config['Properties']) | ForEach-Object { [string]$_ })
    if ($properties.Count -ne 1 -or $properties[0] -ne 'nTSecurityDescriptor') {
        $out.Class = 'Refused'
        $out.Error = ("the property list is '{0}', not nTSecurityDescriptor alone" -f ($properties -join ','))
        return $out
    }
    try {
        $objectArgs = @{} + $AdParams
        $objectArgs.Server = $DomainName
        $objectArgs.LDAPFilter = [string]$Config['GpoFilter']
        $objectArgs.SearchBase = $out.SearchBase
        $objectArgs.SearchScope = 'OneLevel'
        $objectArgs.Properties = @($properties)
        $objectArgs.ErrorAction = 'Stop'
        $items = New-Object System.Collections.ArrayList
        Get-ADObject @objectArgs | ForEach-Object {
            if ($null -ne $_) {
                $dnProp = $_.PSObject.Properties['DistinguishedName']
                $nameProp = $_.PSObject.Properties['Name']
                $sdProp = $_.PSObject.Properties['nTSecurityDescriptor']
                $itemDn = ''
                if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $itemDn = ([string]$dnProp.Value).Trim() }
                $guid = ''
                if ($null -ne $nameProp -and $null -ne $nameProp.Value) { $guid = ([string]$nameProp.Value).Trim().ToUpperInvariant() }
                if ($guid -eq '') { $guid = $itemDn }
                $read = [pscustomobject]@{ Ok = $false; Class = 'NotReturned'; Error = 'the answer held no nTSecurityDescriptor'; ErrorType = ''; Dn = $itemDn; Server = $DomainName; Descriptor = $null }
                if ($null -ne $sdProp -and $null -ne $sdProp.Value) {
                    $descriptor = ConvertTo-AdfaAclDescriptor -Value $sdProp.Value
                    $read.Descriptor = $descriptor
                    $read.Class = [string]$descriptor.Class
                    $read.Error = [string]$descriptor.Error
                    $read.Ok = [bool]$descriptor.Ok
                }
                [void]$items.Add([pscustomobject]@{ Guid = $guid; Dn = $itemDn; Read = $read })
            }
        }
        $out.Items = $items.ToArray()
        $out.Class = 'Read'
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        $out.Class = Get-AdfaDirectoryReadErrorClass -Message $out.Error -TypeName $out.ErrorType
    }
    return $out
}

function Get-AdfaAclDomainFinding {
    <#
    .SYNOPSIS
        Pure: one domain's reads to its rows - "DCSync rights", "Domain root control rights" and
        "AdminSDHolder rights" (each ": <domain>"), one "GPO rights: {GUID}" per groupPolicyContainer
        returned, and "GPO rights summary: <domain>", in that order.
    .DESCRIPTION
        A domain whose distinguished name was not read gets the three object rows and the summary, Not
        Assessed with the cause. The summary's population is the number of containers the search
        returned; it is Not Assessed when the search failed or returned none (a domain normally holds
        at least its two default GPOs, so none visible is not "no GPO"), the grade when any GPO is
        flagged, Not Assessed when any GPO could not be graded, and Pass only when every GPO was read
        and none is flagged. The summary is Not Assessed, as a defect in the tool, unless there is exactly
        one GPO row per container returned.
    .OUTPUTS
        [pscustomobject[]] rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [AllowNull()]$DomainRaw,
        [AllowNull()]$RootRaw,
        [AllowNull()]$HeadRead,
        [AllowNull()]$AdminRead,
        [AllowNull()]$GpoRaw,
        [Parameter(Mandatory)][hashtable]$Config,
        [AllowNull()][scriptblock]$NameResolver = $null
    )
    $rows = @()
    $headWhat = ("the domain head of {0}" -f $Domain)
    $adminWhat = ("CN=AdminSDHolder of {0}" -f $Domain)
    $gpoRow = $Config['Rows']['Gpo']
    $summaryItem = ("GPO rights summary: {0}" -f $Domain)
    $summaryCommon = @{ Scope = $Domain; Item = $summaryItem; CatalogueId = [string]$gpoRow['CatalogueId']; Severity = [string]$gpoRow['Severity']; ObjectKind = 'Gpo'; AllowlistNote = [string]$Config['AllowlistNote'] }
    if ($null -eq $DomainRaw -or -not [bool]$DomainRaw.Ok) {
        $why = 'Not assessed: the domain was not read. This is a defect in the tool, not a result.'
        if ($null -ne $DomainRaw) {
            $why = ("{0} No security descriptor of this domain was read. This is not a clean result." -f (Get-AdfaLapsReadFailureLead -Message ([string]$DomainRaw.Error) -TypeName ([string]$DomainRaw.ErrorType) -What ("the domain {0} (its distinguished name and SID)" -f $Domain)))
        }
        foreach ($spec in @(@('DCSync', 'DCSync rights'), @('DomainRootControl', 'Domain root control rights'), @('AdminSDHolder', 'AdminSDHolder rights'))) {
            $rc = $Config['Rows'][$spec[0]]
            $rows += New-AdfaAclRow -Scope $Domain -Item ("{0}: {1}" -f $spec[1], $Domain) -Status $script:Status.NotAssessed -Detail $why -Evidence 'none' -CatalogueId ([string]$rc['CatalogueId']) -Severity ([string]$rc['Severity']) -AllowlistNote ([string]$Config['AllowlistNote'])
        }
        $rows += New-AdfaAclRow @summaryCommon -Status $script:Status.NotAssessed -Detail $why -Evidence 'none'
        return @($rows)
    }
    $sids = @{
        DomainSid = [string]$DomainRaw.DomainSid; DomainSidError = [string]$DomainRaw.DomainSidError
        RootDomainSid = ''; RootDomainSidError = 'the forest root domain was not read'
    }
    if ($null -ne $RootRaw) { $sids.RootDomainSid = [string]$RootRaw.Sid; $sids.RootDomainSidError = [string]$RootRaw.Error }
    $rows += Get-AdfaAclObjectVerdict -Domain $Domain -Item ("DCSync rights: {0}" -f $Domain) -ObjectKind 'DomainRoot' -RowKey 'DCSync' -What $headWhat -Read $HeadRead @sids -Config $Config -NameResolver $NameResolver
    $rows += Get-AdfaAclObjectVerdict -Domain $Domain -Item ("Domain root control rights: {0}" -f $Domain) -ObjectKind 'DomainRoot' -RowKey 'DomainRootControl' -What $headWhat -Read $HeadRead @sids -Config $Config -NameResolver $NameResolver
    $rows += Get-AdfaAclObjectVerdict -Domain $Domain -Item ("AdminSDHolder rights: {0}" -f $Domain) -ObjectKind 'AdminSDHolder' -RowKey 'AdminSDHolder' -What $adminWhat -Read $AdminRead @sids -Config $Config -NameResolver $NameResolver
    if ($null -eq $GpoRaw -or -not [bool]$GpoRaw.Ok) {
        $searchBase = ''
        if ($null -ne $GpoRaw) { $searchBase = [string]$GpoRaw.SearchBase }
        $rows += New-AdfaAclRow @summaryCommon -Status $script:Status.NotAssessed -ObjectDn $searchBase -Evidence 'none' `
            -Detail (Get-AdfaAclReadLead -Read $GpoRaw -What ("the groupPolicyContainer objects of {0}" -f $Domain))
        return @($rows)
    }
    $gpoRows = @()
    foreach ($item in @($GpoRaw.Items | Where-Object { $null -ne $_ })) {
        $gpoRows += @(Get-AdfaAclObjectVerdict -Domain $Domain -Item ("GPO rights: {0}" -f [string]$item.Guid) -ObjectKind 'Gpo' -RowKey 'Gpo' -What ("the GPO {0} of {1}" -f [string]$item.Guid, $Domain) -Read $item.Read @sids -Config $Config -NameResolver $NameResolver)
    }
    $rows += $gpoRows
    $population = @($GpoRaw.Items | Where-Object { $null -ne $_ }).Count
    $flaggedStatus = [string]$Config['FlaggedStatus']
    $flagged = @($gpoRows | Where-Object { $_.Status -eq $flaggedStatus }).Count
    $notAssessed = @($gpoRows | Where-Object { $_.Status -eq $script:Status.NotAssessed }).Count
    $read = @($gpoRows | Where-Object { $_.Status -ne $script:Status.NotAssessed }).Count
    $counts = @{ Population = $population; ReadCount = $read; FlaggedCount = $flagged; NotAssessedCount = $notAssessed }
    $evidence = ("Get-ADObject -SearchBase '{0}' -SearchScope OneLevel -LDAPFilter '{1}' -Server {2} -Properties nTSecurityDescriptor" -f [string]$GpoRaw.SearchBase, [string]$Config['GpoFilter'], $Domain)
    if ($population -eq 0) {
        $rows += New-AdfaAclRow @summaryCommon @counts -Status $script:Status.NotAssessed -ObjectDn ([string]$GpoRaw.SearchBase) -Evidence $evidence `
            -Detail ("Not assessed: No groupPolicyContainer is visible to this account under {0}. A domain normally holds at least the Default Domain Policy and the Default Domain Controllers Policy, so this is not read as 'no GPO': a GPO whose permissions deny this account read access is not returned at all. This is not a clean result." -f [string]$GpoRaw.SearchBase)
        return @($rows)
    }
    # Exactly one graded row per container returned: a verdict that gave none, or more than one, would
    # make every count below wrong. ReadCount + NotAssessedCount is the number of rows by construction,
    # so the row count itself is what is checked.
    if (@($gpoRows).Count -ne $population) {
        $rows += New-AdfaAclRow @summaryCommon @counts -Status $script:Status.NotAssessed -ObjectDn ([string]$GpoRaw.SearchBase) -Evidence $evidence `
            -Detail ("Not assessed: the {0} GPO row(s) of {1} are not one per container for the {2} container(s) returned. This is a defect in the tool, not a result." -f @($gpoRows).Count, $Domain, $population)
        return @($rows)
    }
    if ($flagged -gt 0) {
        $rows += New-AdfaAclRow @summaryCommon @counts -Status $flaggedStatus -ObjectDn ([string]$GpoRaw.SearchBase) -Evidence $evidence `
            -Detail ("{0} of {1} GPO(s) of {2} visible to this account have a principal outside the allowlist holding a write or control right or ownership; {3} could not be assessed. Each is in its own row. Graded {4}: {5}; {6}." -f $flagged, $population, $Domain, $notAssessed, $flaggedStatus, [string]$Config['ThresholdSource'], [string]$Config['AllowlistNote'])
        return @($rows)
    }
    if ($notAssessed -gt 0) {
        $rows += New-AdfaAclRow @summaryCommon @counts -Status $script:Status.NotAssessed -ObjectDn ([string]$GpoRaw.SearchBase) -Evidence $evidence `
            -Detail ("Not assessed: {0} of {1} GPO(s) of {2} visible to this account were read and none is flagged, but {3} could not be assessed; each is in its own row. This is not a clean result." -f $read, $population, $Domain, $notAssessed)
        return @($rows)
    }
    $rows += New-AdfaAclRow @summaryCommon @counts -Status $script:Status.Pass -ObjectDn ([string]$GpoRaw.SearchBase) -Evidence $evidence `
        -Detail ("All {0} GPO(s) of {1} visible to this account were read, and no principal outside the allowlist holds a write or control right or ownership on any of them. Principals were matched by SID only, never by name; {2}." -f $population, $Domain, [string]$Config['AllowlistNote'])
    return @($rows)
}

function Resolve-AdfaAclSidName {
    <#
    .SYNOPSIS
        A SID's account name, for display only, or '' when it cannot be translated. Never throws.
    .DESCRIPTION
        SecurityIdentifier.Translate([NTAccount]), a lookup through the local security authority of the
        host running the assessment (a read). Learn documents IdentityNotMappedException for a SID that
        cannot be translated; any failure gives ''. The result is shown in the Principals column only:
        no verdict reads it.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowEmptyString()][string]$Sid = '')
    if ([string]::IsNullOrWhiteSpace($Sid)) { return '' }
    try {
        $identity = New-Object System.Security.Principal.SecurityIdentifier -ArgumentList $Sid
        return [string]$identity.Translate([System.Security.Principal.NTAccount]).Value
    }
    catch { return '' }
}

function Get-AdfaDangerousAcl {
    <#
    .SYNOPSIS
        Dangerous rights in the directory, per scoped domain: replication rights and control rights on
        the domain head, write and control rights on AdminSDHolder and on every GPO, judged against an
        allowlist matched by SID only. Directory reads only.
    .DESCRIPTION
        Three seams, each read-only and none of which throws: Get-AdfaAclDomainRaw (Get-ADDomain, for the
        forest root once and for every scoped domain), Get-AdfaAclObjectRaw (Get-ADObject for the domain
        head and for CN=AdminSDHolder,CN=System) and Get-AdfaAclGpoRaw (one Get-ADObject search). Every
        read goes to the domain it is about (-Server <domain>). Nothing is written: no Set-Acl, no
        Set-ADObject, and an ActiveDirectorySecurity is never persisted. The name-matching check this
        replaces (Get-Acl on the AD: drive, principals matched by name) is gone.

        DECLARED POPULATION: the domains named in -Domains. Each gets at least the three object rows and
        the GPO summary, whatever happened to its reads; with none scoped there is one "Dangerous ACLs
        (no domain scoped)" row. An exception while one domain is handled makes its four rows Not
        Assessed and never ends the section.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$Domains = @(),
        [AllowEmptyString()][string]$RootDomain = '',
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config,
        [AllowNull()][scriptblock]$NameResolver = $null
    )
    $rows = @()
    if ($null -eq $NameResolver) { $NameResolver = { param($Sid) Resolve-AdfaAclSidName -Sid $Sid } }
    $scoped = New-Object System.Collections.ArrayList
    foreach ($name in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        if (@($scoped | Where-Object { $_ -eq $name.Trim() }).Count -eq 0) { [void]$scoped.Add($name.Trim()) }
    }
    if ($scoped.Count -eq 0) {
        $rows += New-AdfaAclRow -Item 'Dangerous ACLs (no domain scoped)' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail 'No domain was scoped for this run, so no security descriptor was read. This is not a clean result.'
        return @($rows)
    }
    $domainReads = @{}
    $root = [pscustomobject]@{ Sid = ''; Error = 'the forest reported no root domain' }
    if (-not [string]::IsNullOrWhiteSpace($RootDomain)) {
        $rootRead = Get-AdfaAclDomainRaw -DomainName $RootDomain.Trim() -AdParams $AdParams
        $domainReads[$RootDomain.Trim().ToLowerInvariant()] = $rootRead
        $rootError = [string]$rootRead.DomainSidError
        if ($rootError -eq '') { $rootError = [string]$rootRead.Error }
        $root = [pscustomobject]@{ Sid = [string]$rootRead.DomainSid; Error = $rootError }
    }
    foreach ($domain in $scoped) {
        try {
            $key = ([string]$domain).ToLowerInvariant()
            if ($domainReads.ContainsKey($key)) { $domainRead = $domainReads[$key] }
            else { $domainRead = Get-AdfaAclDomainRaw -DomainName $domain -AdParams $AdParams; $domainReads[$key] = $domainRead }
            $head = $null; $admin = $null; $gpo = $null
            if ([bool]$domainRead.Ok) {
                $head = Get-AdfaAclObjectRaw -Dn ([string]$domainRead.DomainDn) -Server $domain -AdParams $AdParams -Config $Config
                $admin = Get-AdfaAclObjectRaw -Dn ("{0},{1}" -f [string]$Config['AdminSdHolderRdn'], [string]$domainRead.DomainDn) -Server $domain -AdParams $AdParams -Config $Config
                $gpo = Get-AdfaAclGpoRaw -DomainName $domain -DomainDn ([string]$domainRead.DomainDn) -AdParams $AdParams -Config $Config
            }
            $rows += @(Get-AdfaAclDomainFinding -Domain $domain -DomainRaw $domainRead -RootRaw $root -HeadRead $head -AdminRead $admin -GpoRaw $gpo -Config $Config -NameResolver $NameResolver)
        }
        catch {
            # A defect in this tool, not in the directory. Fail closed for this domain only.
            $why = ("Not assessed: handling the security descriptors of {0} failed inside this tool, so nothing about this domain is graded; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$_.Exception.Message)
            foreach ($prefix in @('DCSync rights', 'Domain root control rights', 'AdminSDHolder rights', 'GPO rights summary')) {
                $rows += New-AdfaAclRow -Scope $domain -Item ("{0}: {1}" -f $prefix, $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why -AllowlistNote ([string]$Config['AllowlistNote'])
            }
        }
    }
    return @($rows)
}

function Merge-AdfaAclConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in Dangerous ACLs table, with validation. The Acl
        validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: FlaggedStatus (Warning or Fail, the grade of a row with a principal
        outside the allowlist) and AdditionalAllowed, a list of SIDs to add to the allowlist, each for
        named objects and named rights, with the reason:

            { "Acl": { "FlaggedStatus": "Fail",
                       "AdditionalAllowed": [ { "Sid": "S-1-5-21-...-1105", "Objects": [ "DomainRoot" ],
                                                "Rights": [ "DS-Replication-Get-Changes", "DS-Replication-Get-Changes-All" ],
                                                "Reason": "Entra Connect AD DS connector account" } ] } }

        What it cannot: the built-in allowlist, the masks, the GUIDs, the rows, the filter and the
        property list. Every such key is refused as unknown.

        Refused with the reason: an override that is not one object, an empty object, an unknown key, a
        null, a FlaggedStatus that is not the text Warning or Fail; an AdditionalAllowed that is not a
        non-empty list of objects; an entry with a key other than Sid, Objects, Rights and Reason or
        without one of them; a Sid that is not a SID in its text form (a name is refused - the allowlist
        is matched by SID only); a SID that may never be allowlisted (Everyone, Anonymous Logon,
        Authenticated Users, Users, Guests, or RID 513, 514 or 515 of any domain); an Objects or Rights
        list that is empty or names something unknown ("*" included); a Reason that is blank.

        Provenance follows the keys: ThresholdSource is rewritten to name the override's source for
        exactly the keys it supplied.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }
    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("Acl config override must be a single object with named keys (for example {{ ""FlaggedStatus"": ""Fail"" }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) {
        throw 'Acl config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $known = @('FlaggedStatus', 'AdditionalAllowed')
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("Acl config override names an unknown key '{0}'. Known keys: {1}. The built-in allowlist, the masks, the GUIDs, the rows, the filter and the property list cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        if ($supplied -contains $name) { throw ("Acl config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) { throw ("Acl config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name) }
        if ($name -eq 'FlaggedStatus') {
            if ($value -isnot [string]) {
                throw ("Acl config override sets 'FlaggedStatus' to a value of type {0}, not a single text value. It must be the text Warning or Fail: a principal outside the allowlist is never reported as a pass." -f $value.GetType().Name)
            }
            $statusMatch = @(@('Warning', 'Fail') | Where-Object { $_ -eq $value.Trim() })
            if ($statusMatch.Count -eq 0) {
                throw ("Acl config override sets 'FlaggedStatus' to '{0}'. It must be Warning or Fail: a principal outside the allowlist is never reported as a pass." -f $value)
            }
            $merged['FlaggedStatus'] = [string]$statusMatch[0]
        }
        else {
            if ($value -is [string] -or $value -is [System.Collections.IDictionary] -or $value -isnot [System.Collections.IList]) {
                throw ("Acl config override sets 'AdditionalAllowed' to a value of type {0}. It must be a list (a JSON array) of objects, each with Sid, Objects, Rights and Reason." -f $value.GetType().Name)
            }
            $entries = @($value)
            if ($entries.Count -eq 0) { throw "Acl config override sets 'AdditionalAllowed' to an empty list. Remove the key to keep the built-in allowlist." }
            $added = @()
            $entryKeys = @('Sid', 'Objects', 'Rights', 'Reason')
            for ($n = 0; $n -lt $entries.Count; $n++) {
                $label = ("Acl config override: entry {0} of AdditionalAllowed" -f ($n + 1))
                $entry = ConvertTo-AdfaOverrideTable -Value $entries[$n]
                if ($null -eq $entry) { throw ("{0} is not an object; each entry must be an object with Sid, Objects, Rights and Reason." -f $label) }
                foreach ($ek in @($entry.Keys)) {
                    if (@($entryKeys | Where-Object { $_ -eq [string]$ek }).Count -eq 0) { throw ("{0} names an unknown key '{1}'. Known keys: {2}." -f $label, [string]$ek, ($entryKeys -join ', ')) }
                }
                $values = @{}
                foreach ($ek in $entryKeys) {
                    $found = @(@($entry.Keys) | Where-Object { [string]$_ -eq $ek })
                    if ($found.Count -eq 0 -or $null -eq $entry[$found[0]]) { throw ("{0} has no '{1}'. Each entry needs Sid, Objects, Rights and Reason." -f $label, $ek) }
                    $values[$ek] = $entry[$found[0]]
                }
                if ($values['Sid'] -isnot [string]) { throw ("{0}: 'Sid' must be a SID in its text form, not a value of type {1}." -f $label, $values['Sid'].GetType().Name) }
                $parsed = ConvertFrom-AdfaSidValue -Value ([string]$values['Sid'])
                if (-not $parsed.Ok) { throw ("{0}: '{1}' is not a SID in its text form; names are refused, because the allowlist is matched by SID only." -f $label, [string]$values['Sid']) }
                $refusedRid = ($parsed.IsAccountDomain -and @(@($BaseConfig['RefusedOverrideRids']) | Where-Object { [uint32]$_ -eq $parsed.Rid }).Count -gt 0)
                if (@($BaseConfig['RefusedOverrideSids']) -contains $parsed.Text -or $refusedRid) {
                    throw ("{0}: {1} can never be allowlisted: it stands for everyone, every authenticated user, every user, every guest or every computer of a domain." -f $label, $parsed.Text)
                }
                foreach ($listKey in @('Objects', 'Rights')) {
                    $listValue = $values[$listKey]
                    if ($listValue -is [string] -or $listValue -isnot [System.Collections.IList] -or @($listValue).Count -eq 0) {
                        throw ("{0}: '{1}' must be a non-empty list." -f $label, $listKey)
                    }
                    $allowedNames = @($BaseConfig['ObjectKinds'])
                    if ($listKey -eq 'Rights') { $allowedNames = @($BaseConfig['RightNames']) }
                    foreach ($v in @($listValue)) {
                        $hit = @()
                        if ($v -is [string]) { $hit = @($allowedNames | Where-Object { $_ -eq $v.Trim() }) }
                        if ($hit.Count -eq 0) {
                            $kind = 'object'
                            if ($listKey -eq 'Rights') { $kind = 'right' }
                            throw ("{0} names an unknown {1} '{2}'. Known: {3}." -f $label, $kind, [string]$v, ($allowedNames -join ', '))
                        }
                    }
                }
                if ($values['Reason'] -isnot [string] -or [string]::IsNullOrWhiteSpace([string]$values['Reason'])) {
                    throw ("{0}: 'Reason' must be text that is not blank, saying why this SID may hold these rights." -f $label)
                }
                $objects = @(@($values['Objects']) | ForEach-Object { $o = $_.Trim(); @($BaseConfig['ObjectKinds'] | Where-Object { $_ -eq $o })[0] } | Select-Object -Unique)
                $rights = @(@($values['Rights']) | ForEach-Object { $r = $_.Trim(); @($BaseConfig['RightNames'] | Where-Object { $_ -eq $r })[0] } | Select-Object -Unique)
                $added += @{ Sid = $parsed.Text; Objects = $objects; Rights = $rights; Reason = ([string]$values['Reason']).Trim(); Origin = 'config override' }
            }
            $merged['AdditionalAllowed'] = $added
        }
        $supplied += $name
    }
    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
    $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
    if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
    $merged['ThresholdSource'] = $text
    return $merged
}

# ---------------------------------------------------------------------------
# Privileged groups and delegation (PORT-PLAN C10): Schema Admins and Enterprise Admins membership,
# privileged group counts, adminCount objects outside every protected group, SPNs and delegation on
# privileged accounts, and unconstrained, protocol-transition, constrained and resource-based
# delegation. Rows of the PrivilegedAccounts, PrivilegedHygiene and Kerberos sections. Directory
# reads only; the sources are in the Privileged config table.
# ---------------------------------------------------------------------------

function New-AdfaPrivilegedRow {
    <#
    .SYNOPSIS
        Pure: one row of the three C10 sections. Every row has the same columns, so a consumer never
        has to test whether a column exists.
    .DESCRIPTION
        Account names, SIDs, DNs and SPNs go in their own columns (Principals, PrincipalSids,
        ForeignSids, Unresolved, Targets, AllowedSids), never in Detail: the consolidated findings
        choose a recommendation from Detail, and none of these columns is read there. A count that was
        not measured is an empty string, never 0.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][ValidateSet('Privileged', 'PrivHygiene', 'Kerberos')][string]$Area,
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = '',
        [AllowEmptyString()][string]$Evidence = '',
        [AllowEmptyString()][string]$CatalogueId = '',
        [AllowEmptyString()][string]$Severity = '',
        [AllowEmptyString()][string]$DomainSid = '',
        [AllowEmptyString()][string]$GroupSid = '',
        [AllowNull()]$Count = $null,
        [AllowNull()]$UserCount = $null,
        [AllowNull()]$ComputerCount = $null,
        [AllowNull()]$GroupCount = $null,
        [AllowNull()]$ForeignCount = $null,
        [AllowNull()]$UnresolvedCount = $null,
        [AllowNull()]$ExcludedCount = $null,
        [AllowNull()]$Listed = $null,
        [AllowNull()]$NotListed = $null,
        [AllowEmptyString()][string]$Principals = '',
        [AllowEmptyString()][string]$PrincipalSids = '',
        [AllowEmptyString()][string]$ForeignSids = '',
        [AllowEmptyString()][string]$Unresolved = '',
        [AllowEmptyString()][string]$Targets = '',
        [AllowEmptyString()][string]$AllowedSids = ''
    )
    $row = New-Finding -Scope $Scope -Area $Area -Item $Item -Status $Status -Detail $Detail
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $asText = { param($Number) if ($null -eq $Number) { return '' } return ([int64]$Number).ToString($inv) }
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    $row | Add-Member -NotePropertyName 'Evidence' -NotePropertyValue $Evidence
    $row | Add-Member -NotePropertyName 'CatalogueId' -NotePropertyValue $CatalogueId
    $row | Add-Member -NotePropertyName 'Severity' -NotePropertyValue $Severity
    $row | Add-Member -NotePropertyName 'DomainSid' -NotePropertyValue $DomainSid
    $row | Add-Member -NotePropertyName 'GroupSid' -NotePropertyValue $GroupSid
    $row | Add-Member -NotePropertyName 'Count' -NotePropertyValue (& $asText $Count)
    $row | Add-Member -NotePropertyName 'UserCount' -NotePropertyValue (& $asText $UserCount)
    $row | Add-Member -NotePropertyName 'ComputerCount' -NotePropertyValue (& $asText $ComputerCount)
    $row | Add-Member -NotePropertyName 'GroupCount' -NotePropertyValue (& $asText $GroupCount)
    $row | Add-Member -NotePropertyName 'ForeignCount' -NotePropertyValue (& $asText $ForeignCount)
    $row | Add-Member -NotePropertyName 'UnresolvedCount' -NotePropertyValue (& $asText $UnresolvedCount)
    $row | Add-Member -NotePropertyName 'ExcludedCount' -NotePropertyValue (& $asText $ExcludedCount)
    $row | Add-Member -NotePropertyName 'Listed' -NotePropertyValue (& $asText $Listed)
    $row | Add-Member -NotePropertyName 'NotListed' -NotePropertyValue (& $asText $NotListed)
    $row | Add-Member -NotePropertyName 'Principals' -NotePropertyValue $Principals
    $row | Add-Member -NotePropertyName 'PrincipalSids' -NotePropertyValue $PrincipalSids
    $row | Add-Member -NotePropertyName 'ForeignSids' -NotePropertyValue $ForeignSids
    $row | Add-Member -NotePropertyName 'Unresolved' -NotePropertyValue $Unresolved
    $row | Add-Member -NotePropertyName 'Targets' -NotePropertyValue $Targets
    $row | Add-Member -NotePropertyName 'AllowedSids' -NotePropertyValue $AllowedSids
    return $row
}

function ConvertTo-AdfaLdapSidFilterValue {
    <#
    .SYNOPSIS
        Pure: a SID in its text form as the encoded byte string an LDAP filter takes for objectSid,
        or '' when the text is not a SID.
    .DESCRIPTION
        Learn: for the Sid syntax "the value specified in a filter is the encoded byte string
        representation of the SID", each byte a backslash and two hexadecimal digits
        (https://learn.microsoft.com/windows/win32/ad/how-to-specify-comparison-values, read
        2026-11-16). The bytes are those of MS-DTYP 2.4.2.2, the layout ConvertFrom-AdfaSidValue
        checks: revision 1, the sub-authority count, the 6-byte authority big-endian, each
        sub-authority little-endian. Arithmetic on [uint64] only, so 5.1 and 7 agree.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowEmptyString()][string]$Sid = '')
    if ([string]::IsNullOrWhiteSpace($Sid)) { return '' }
    $parsed = ConvertFrom-AdfaSidValue -Value $Sid -NoPlatform
    if (-not [bool]$parsed.Ok) { return '' }
    $subs = @($parsed.SubAuthorities)
    $parts = New-Object System.Collections.Generic.List[string]
    $parts.Add('\01')
    $parts.Add(('\{0:x2}' -f $subs.Count))
    $authority = [uint64]$parsed.Authority
    for ($i = 5; $i -ge 0; $i--) { $parts.Add(('\{0:x2}' -f [int](($authority -shr (8 * $i)) -band [uint64]255))) }
    foreach ($s in $subs) {
        $v = [uint64]$s
        for ($i = 0; $i -lt 4; $i++) { $parts.Add(('\{0:x2}' -f [int](($v -shr (8 * $i)) -band [uint64]255))) }
    }
    return ($parts -join '')
}

function ConvertTo-AdfaPrivInteger {
    <#
    .SYNOPSIS
        Pure: an integer attribute value as [int64], or $null when there is none or it is not a whole
        number. Never throws.
    .OUTPUTS
        [int64] or $null
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    $first = $Value
    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        $items = @($Value | Where-Object { $null -ne $_ })
        if ($items.Count -ne 1) { return $null }
        $first = $items[0]
    }
    $number = [int64]0
    if ([int64]::TryParse(([string]$first).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$number)) { return $number }
    return $null
}

function ConvertTo-AdfaPrivRecord {
    <#
    .SYNOPSIS
        Pure: one directory object as the small record the C10 verdicts read. Never throws on a
        missing attribute.
    .DESCRIPTION
        Every value is read through PSObject.Properties, so an attribute the answer does not carry is
        $null and never an error under StrictMode, and no value passes through a function's return,
        which would unroll a byte array. Kind is User, Computer, Group, Foreign or Other, from the most
        specific objectClass (the last value) and the class lists of the config table. Enabled is read
        from ACCOUNTDISABLE in userAccountControl for users and computers; it is $null when
        userAccountControl was not returned. msDS-AllowedToActOnBehalfOfOtherIdentity, when present,
        is read in memory by ConvertTo-AdfaAclDescriptor (the C9 converter, which reads a byte array
        or an ActiveDirectorySecurity and names anything else as Unparseable).
    .OUTPUTS
        [pscustomobject] Dn, Sam, Name, Class, Kind, Sid, DomainPart, Rid, IsAccountDomainSid, Uac,
        Enabled, AdminCount, Spns, PrimaryGroupId, Members, DelegateTo, HasRbcd, Rbcd.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Object,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $values = @{}
    foreach ($attribute in @('distinguishedName', 'sAMAccountName', 'Name', 'objectClass', 'objectSid', 'userAccountControl', 'adminCount',
            'servicePrincipalName', 'primaryGroupID', 'member', 'msDS-AllowedToDelegateTo', 'msDS-AllowedToActOnBehalfOfOtherIdentity')) {
        $values[$attribute] = $null
        $p = $Object.PSObject.Properties[$attribute]
        if ($null -ne $p) { $values[$attribute] = $p.Value }
    }
    $dn = ([string]$values['distinguishedName']).Trim()
    $sam = ([string]$values['sAMAccountName']).Trim()
    $name = $sam
    if ($name -eq '') { $name = ([string]$values['Name']).Trim() }
    if ($name -eq '') { $name = $dn }
    if ($name -eq '') { $name = '(unnamed)' }
    $class = ''
    $classes = @(Get-AdfaSidValueList -Value $values['objectClass'] | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
    if ($classes.Count -gt 0) { $class = $classes[$classes.Count - 1] }
    $kind = 'Other'
    if (@(@($Config['UserClasses']) | Where-Object { $_ -eq $class }).Count -gt 0) { $kind = 'User' }
    elseif (@(@($Config['ComputerClasses']) | Where-Object { $_ -eq $class }).Count -gt 0) { $kind = 'Computer' }
    elseif (@(@($Config['GroupClasses']) | Where-Object { $_ -eq $class }).Count -gt 0) { $kind = 'Group' }
    elseif (@(@($Config['ForeignClasses']) | Where-Object { $_ -eq $class }).Count -gt 0) { $kind = 'Foreign' }
    $sid = ''; $domainPart = ''; $rid = $null; $isAccount = $false
    if ($null -ne $values['objectSid']) {
        $parsed = ConvertFrom-AdfaSidValue -Value $values['objectSid']
        if ([bool]$parsed.Ok) { $sid = [string]$parsed.Text; $domainPart = [string]$parsed.DomainPart; $rid = $parsed.Rid; $isAccount = [bool]$parsed.IsAccountDomain }
    }
    $uac = ConvertTo-AdfaPrivInteger -Value $values['userAccountControl']
    $enabled = $null
    if (($kind -eq 'User' -or $kind -eq 'Computer') -and $null -ne $uac) {
        $enabled = (($uac -band [int64]$Config['Uac']['AccountDisable']) -eq 0)
    }
    $hasRbcd = $false
    $rbcd = $null
    if ($null -ne $values['msDS-AllowedToActOnBehalfOfOtherIdentity']) {
        $hasRbcd = $true
        $rbcd = ConvertTo-AdfaAclDescriptor -Value $values['msDS-AllowedToActOnBehalfOfOtherIdentity']
    }
    return [pscustomobject]@{
        Dn = $dn; Sam = $sam; Name = $name; Class = $class; Kind = $kind
        Sid = $sid; DomainPart = $domainPart; Rid = $rid; IsAccountDomainSid = $isAccount
        Uac = $uac; Enabled = $enabled; AdminCount = (ConvertTo-AdfaPrivInteger -Value $values['adminCount'])
        Spns = @(Get-AdfaSidValueList -Value $values['servicePrincipalName'] | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ -ne '' })
        PrimaryGroupId = (ConvertTo-AdfaPrivInteger -Value $values['primaryGroupID'])
        Members = @(Get-AdfaSidValueList -Value $values['member'] | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ -ne '' })
        DelegateTo = @(Get-AdfaSidValueList -Value $values['msDS-AllowedToDelegateTo'] | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ -ne '' })
        HasRbcd = $hasRbcd; Rbcd = $rbcd
    }
}

function Get-AdfaPrivReadClass {
    <#
    .SYNOPSIS
        Pure: the class of a directory read that threw - NotFound for the module's identity-not-found
        exception, otherwise Unreachable, AccessDenied, TimedOut or Error (Get-AdfaDirectoryReadErrorClass).
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyString()][string]$Message, [AllowNull()][AllowEmptyString()][string]$TypeName)
    if (-not [string]::IsNullOrWhiteSpace($TypeName) -and $TypeName -match '(?i)ADIdentityNotFoundException') { return 'NotFound' }
    return (Get-AdfaDirectoryReadErrorClass -Message $Message -TypeName $TypeName)
}

function Get-AdfaPrivSearchRaw {
    <#
    .SYNOPSIS
        Directory seam of C10: one Get-ADObject search, asking for a named property list. Read-only.
        Never throws.
    .DESCRIPTION
        Get-ADObject -Server <server> -LDAPFilter <filter> -Properties <list> [-SearchBase] [-SearchScope],
        with the caller's other AD parameters (-Credential). The paging the ActiveDirectory module does
        by itself is relied on. No result limit is set unless -ResultSetSize is above 0, when it is
        passed on (Learn: it controls the maximum number of returned objects); only the primary-group
        searches use it, to stay inside MaxExpandedObjects. A property list that is empty or holds a blank
        or a wildcard is refused before any call (Class Refused). The objects are handed back as the
        module returned them; nothing is written.
    .OUTPUTS
        [pscustomobject] Ok, Class (Read | Refused | Unreachable | AccessDenied | TimedOut | Error),
        Error, ErrorType, Server, Filter, Objects.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Server,
        [Parameter(Mandatory)][string]$LDAPFilter,
        [AllowNull()][AllowEmptyCollection()][string[]]$Properties = @(),
        [AllowEmptyString()][string]$SearchBase = '',
        [AllowEmptyString()][string]$SearchScope = '',
        [hashtable]$AdParams = @{},
        [int]$ResultSetSize = 0
    )
    $out = [pscustomobject]@{ Ok = $false; Class = ''; Error = ''; ErrorType = ''; Server = $Server; Filter = $LDAPFilter; Objects = @() }
    $names = @(@($Properties) | ForEach-Object { [string]$_ })
    $refused = @(Get-AdfaSidHistoryRefusedProperty -PropertyNames $names)
    if ($names.Count -eq 0 -or $refused.Count -gt 0) {
        $out.Class = 'Refused'
        $out.Error = ("the property list is empty or holds a blank or a wildcard ({0}), so nothing was asked of the directory" -f ($refused -join ', '))
        return $out
    }
    try {
        $searchArgs = @{} + $AdParams
        $searchArgs.Server = $Server
        $searchArgs.LDAPFilter = $LDAPFilter
        $searchArgs.Properties = @($names)
        if ($SearchBase -ne '') { $searchArgs.SearchBase = $SearchBase }
        if ($SearchScope -ne '') { $searchArgs.SearchScope = $SearchScope }
        if ($ResultSetSize -gt 0) { $searchArgs.ResultSetSize = $ResultSetSize }
        $searchArgs.ErrorAction = 'Stop'
        $objects = New-Object System.Collections.ArrayList
        Get-ADObject @searchArgs | ForEach-Object { if ($null -ne $_) { [void]$objects.Add($_) } }
        $out.Objects = $objects.ToArray()
        $out.Class = 'Read'
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        $out.Class = Get-AdfaPrivReadClass -Message $out.Error -TypeName $out.ErrorType
    }
    return $out
}

function Get-AdfaPrivObjectRaw {
    <#
    .SYNOPSIS
        Directory seam of C10: one object by its distinguished name. Read-only. Never throws.
    .DESCRIPTION
        Get-ADObject -Identity <DN> -Server <server> -Properties <list>, with the caller's other AD
        parameters. The same property-list guard as Get-AdfaPrivSearchRaw. An identity the module
        cannot find is NotFound; any other failure is classed by Get-AdfaDirectoryReadErrorClass.
    .OUTPUTS
        [pscustomobject] Ok, Class (Read | NotFound | Refused | Unreachable | AccessDenied | TimedOut |
        Error), Error, ErrorType, Server, Object.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Identity,
        [Parameter(Mandatory)][string]$Server,
        [AllowNull()][AllowEmptyCollection()][string[]]$Properties = @(),
        [hashtable]$AdParams = @{}
    )
    $out = [pscustomobject]@{ Ok = $false; Class = ''; Error = ''; ErrorType = ''; Server = $Server; Object = $null }
    $names = @(@($Properties) | ForEach-Object { [string]$_ })
    $refused = @(Get-AdfaSidHistoryRefusedProperty -PropertyNames $names)
    if ($names.Count -eq 0 -or $refused.Count -gt 0) {
        $out.Class = 'Refused'
        $out.Error = ("the property list is empty or holds a blank or a wildcard ({0}), so nothing was asked of the directory" -f ($refused -join ', '))
        return $out
    }
    try {
        $objectArgs = @{} + $AdParams
        $objectArgs.Identity = $Identity
        $objectArgs.Server = $Server
        $objectArgs.Properties = @($names)
        $objectArgs.ErrorAction = 'Stop'
        $object = Get-ADObject @objectArgs
        if ($null -eq $object) { $out.Class = 'NotFound'; $out.Error = 'the read returned no object' }
        else { $out.Object = $object; $out.Class = 'Read'; $out.Ok = $true }
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        $out.Class = Get-AdfaPrivReadClass -Message $out.Error -TypeName $out.ErrorType
    }
    return $out
}

function Get-AdfaPrivForestRaw {
    <#
    .SYNOPSIS
        Directory seam of C10, once per run: the domain controllers registered in the configuration
        partition, by the DN of their computer account, and dSHeuristics. Read-only. Never throws.
    .DESCRIPTION
        Get-ADRootDSE (sent to the forest root domain when one is known) for configurationNamingContext;
        then two one-subtree searches under CN=Sites,<configuration NC>: every nTDSDSA object (nTDSDSARO,
        the RODC's, is a subclass of it - an inference from Learn's class page that the filter matches
        it) and every server object with serverReference, which Learn describes as the DN of the domain
        controller in the domain naming context. A DC is a server object that holds an nTDSDSA child;
        its serverReference is the DN that excludes its computer account from the delegation rows.
        Last, CN=Directory Service,CN=Windows NT,CN=Services,<configuration NC> asking for dSHeuristics
        only. Absent dSHeuristics is Microsoft's documented default (every character 0), not "unread".
        DcOk says only that both searches answered; DsaCount, NoReference and the DNs found are checked
        by Get-AdfaPrivDcPopulationState before any row relies on the population.
    .OUTPUTS
        [pscustomobject] ConfigNc, DcOk, DcClass, DcError, DcErrorType, DcDns (lower-case DNs),
        DsaCount, ServerCount, NoReference (server DNs of DCs with no serverReference),
        HeuristicsOk, HeuristicsClass, HeuristicsError, HeuristicsErrorType, HeuristicsPresent,
        HeuristicsValue.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$RootDomain = '',
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{
        ConfigNc = ''; DcOk = $false; DcClass = ''; DcError = ''; DcErrorType = ''; DcDns = @(); DsaCount = 0; ServerCount = 0; NoReference = @()
        HeuristicsOk = $false; HeuristicsClass = ''; HeuristicsError = ''; HeuristicsErrorType = ''; HeuristicsPresent = $false; HeuristicsValue = ''
    }
    $server = ''
    try {
        $rootArgs = @{} + $AdParams
        if (-not [string]::IsNullOrWhiteSpace($RootDomain)) { $rootArgs.Server = $RootDomain.Trim() }
        $rootArgs.ErrorAction = 'Stop'
        $rootDse = Get-ADRootDSE @rootArgs
        $cfgProp = $null
        if ($null -ne $rootDse) { $cfgProp = $rootDse.PSObject.Properties['configurationNamingContext'] }
        if ($null -ne $cfgProp -and $null -ne $cfgProp.Value) { $out.ConfigNc = ([string]$cfgProp.Value).Trim() }
        if ($rootArgs.ContainsKey('Server')) { $server = [string]$rootArgs.Server }
    }
    catch {
        $message = [string]$_.Exception.Message
        $type = [string]$_.Exception.GetType().FullName
        $class = Get-AdfaPrivReadClass -Message $message -TypeName $type
        $out.DcClass = $class; $out.DcError = $message; $out.DcErrorType = $type
        $out.HeuristicsClass = $class; $out.HeuristicsError = $message; $out.HeuristicsErrorType = $type
        return $out
    }
    if ($out.ConfigNc -eq '') {
        $out.DcClass = 'Error'; $out.DcError = 'the root DSE returned no configurationNamingContext'
        $out.HeuristicsClass = 'Error'; $out.HeuristicsError = $out.DcError
        return $out
    }
    if ($server -eq '' -and $AdParams.ContainsKey('Server')) { $server = [string]$AdParams['Server'] }
    $sitesBase = ("{0},{1}" -f [string]$Config['SitesRdn'], $out.ConfigNc)
    $searchArgs = @{ SearchBase = $sitesBase; SearchScope = 'Subtree'; AdParams = $AdParams }
    if ($server -eq '') {
        # No server named anywhere: the module's default, as every other read of this run.
        $out.DcClass = 'Error'; $out.DcError = 'no server to send the configuration reads to was known'
        $out.HeuristicsClass = 'Error'; $out.HeuristicsError = $out.DcError
        return $out
    }
    $dsas = Get-AdfaPrivSearchRaw -Server $server -LDAPFilter ([string]$Config['NtdsDsaFilter']) -Properties @($Config['DsaProperties']) @searchArgs
    $servers = $null
    if ([bool]$dsas.Ok) { $servers = Get-AdfaPrivSearchRaw -Server $server -LDAPFilter ([string]$Config['ServerFilter']) -Properties @($Config['ServerProperties']) @searchArgs }
    if (-not [bool]$dsas.Ok) { $out.DcClass = [string]$dsas.Class; $out.DcError = [string]$dsas.Error; $out.DcErrorType = [string]$dsas.ErrorType }
    elseif (-not [bool]$servers.Ok) { $out.DcClass = [string]$servers.Class; $out.DcError = [string]$servers.Error; $out.DcErrorType = [string]$servers.ErrorType }
    else {
        $serverDns = @{}
        foreach ($dsa in @($dsas.Objects)) {
            $dnProp = $dsa.PSObject.Properties['DistinguishedName']
            if ($null -eq $dnProp -or $null -eq $dnProp.Value) { continue }
            $dsaDn = ([string]$dnProp.Value).Trim()
            $comma = $dsaDn.IndexOf(',')
            if ($comma -lt 0) { continue }
            $serverDns[$dsaDn.Substring($comma + 1).ToLowerInvariant()] = $true
            $out.DsaCount++
        }
        $dcDns = New-Object System.Collections.ArrayList
        $noReference = New-Object System.Collections.ArrayList
        foreach ($srv in @($servers.Objects)) {
            $out.ServerCount++
            $dnProp = $srv.PSObject.Properties['DistinguishedName']
            if ($null -eq $dnProp -or $null -eq $dnProp.Value) { continue }
            $srvDn = ([string]$dnProp.Value).Trim()
            if (-not $serverDns.ContainsKey($srvDn.ToLowerInvariant())) { continue }
            $refProp = $srv.PSObject.Properties['serverReference']
            if ($null -ne $refProp -and $null -ne $refProp.Value -and ([string]$refProp.Value).Trim() -ne '') { [void]$dcDns.Add(([string]$refProp.Value).Trim().ToLowerInvariant()) }
            else { [void]$noReference.Add($srvDn) }
        }
        $out.DcDns = $dcDns.ToArray()
        $out.NoReference = $noReference.ToArray()
        $out.DcClass = 'Read'
        $out.DcOk = $true
    }
    $heuristics = Get-AdfaPrivObjectRaw -Identity ("{0},{1}" -f [string]$Config['DirectoryServiceRdn'], $out.ConfigNc) -Server $server -Properties @($Config['HeuristicsProperties']) -AdParams $AdParams
    $out.HeuristicsClass = [string]$heuristics.Class
    $out.HeuristicsError = [string]$heuristics.Error
    $out.HeuristicsErrorType = [string]$heuristics.ErrorType
    if ([bool]$heuristics.Ok) {
        $out.HeuristicsOk = $true
        $valueProp = $heuristics.Object.PSObject.Properties['dSHeuristics']
        if ($null -ne $valueProp -and $null -ne $valueProp.Value) { $out.HeuristicsPresent = $true; $out.HeuristicsValue = [string]$valueProp.Value }
    }
    return $out
}

function Get-AdfaPrivHeuristicsState {
    <#
    .SYNOPSIS
        Pure: what dSHeuristics says about AdminSDHolder exclusions - Known (the character was read or
        is the documented default), MaskZero (it is 0), and the character itself.
    .DESCRIPTION
        Character 16 is dwAdminSDExMask (MS-ADTS). An absent attribute, or a value shorter than 16
        characters, is the documented default "0". Learn does not publish which bit removes which
        operator group, so a character other than 0 makes every object protected only through
        Account, Server, Print or Backup Operators undecided, never judged.
    .OUTPUTS
        [pscustomobject] Known, MaskZero, Character, Text.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Forest, [Parameter(Mandatory)][hashtable]$Config)
    $position = [int]$Config['AdminSdExMaskPosition']
    if ($null -eq $Forest -or -not [bool]$Forest.HeuristicsOk) {
        $why = 'the forest-wide configuration was not read'
        if ($null -ne $Forest) { $why = ("dSHeuristics could not be read ({0}: {1})" -f [string]$Forest.HeuristicsClass, ([string]$Forest.HeuristicsError).Trim()) }
        return [pscustomobject]@{ Known = $false; MaskZero = $false; Character = ''; Text = $why }
    }
    $value = [string]$Forest.HeuristicsValue
    $char = '0'
    $source = 'dSHeuristics is not set, so every character is the documented default 0'
    if ([bool]$Forest.HeuristicsPresent) {
        if ($value.Length -ge $position) { $char = $value.Substring($position - 1, 1); $source = ("dSHeuristics is set and its character {0} (dwAdminSDExMask) is '{1}'" -f $position, $char) }
        else { $source = ("dSHeuristics is set with {0} character(s), so character {1} (dwAdminSDExMask) is the documented default 0" -f $value.Length, $position) }
    }
    return [pscustomobject]@{ Known = $true; MaskZero = ($char -eq '0'); Character = $char; Text = $source }
}

function Get-AdfaPrivDcPopulationState {
    <#
    .SYNOPSIS
        Pure: whether the domain controllers registered in the configuration partition were read
        completely enough to tell a DC's computer account apart - Known, Why, and the set of DNs.
    .DESCRIPTION
        Known only when both configuration searches answered (DcOk), at least one nTDSDSA object came
        back (a forest always has a domain controller, so none is a visibility gap, not an empty
        forest), every DC server object carried serverReference (NoReference empty), and each nTDSDSA
        object was matched to a server object (DcDns + NoReference = DsaCount). Otherwise Why names
        what is missing, and no row may exclude or judge a DC on it.
    .OUTPUTS
        [pscustomobject] Known, Why, Set (lower-case DN -> $true).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Forest)
    $set = @{}
    if ($null -eq $Forest) { return [pscustomobject]@{ Known = $false; Why = 'the forest-wide configuration was not read'; Set = $set } }
    $okProp = $Forest.PSObject.Properties['DcOk']
    if ($null -eq $okProp -or -not [bool]$okProp.Value) {
        $classProp = $Forest.PSObject.Properties['DcClass']; $errProp = $Forest.PSObject.Properties['DcError']
        $class = ''; $err = ''
        if ($null -ne $classProp) { $class = [string]$classProp.Value }
        if ($null -ne $errProp) { $err = [string]$errProp.Value }
        return [pscustomobject]@{ Known = $false; Why = (Get-AdfaPrivUnresolvedText -Read ([pscustomobject]@{ Class = $class; Error = $err })); Set = $set }
    }
    $dns = @()
    $dnsProp = $Forest.PSObject.Properties['DcDns']
    if ($null -ne $dnsProp) { $dns = @(@($dnsProp.Value) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() }) }
    foreach ($dn in $dns) { $set[$dn] = $true }
    $countProp = $Forest.PSObject.Properties['DsaCount']
    $noRefProp = $Forest.PSObject.Properties['NoReference']
    if ($null -eq $countProp -or $null -eq $noRefProp) {
        return [pscustomobject]@{ Known = $false; Why = 'the number of nTDSDSA objects and the server objects without serverReference were not recorded, so the population cannot be checked. This is a defect in the tool'; Set = @{} }
    }
    $dsaCount = [int]$countProp.Value
    $noRef = @(@($noRefProp.Value) | Where-Object { $null -ne $_ })
    if ($dsaCount -le 0) {
        return [pscustomobject]@{ Known = $false; Why = 'the nTDSDSA search under CN=Sites of the configuration partition returned no object, and a forest always has at least one domain controller, so the domain controllers were not visible to this account'; Set = @{} }
    }
    if ($noRef.Count -gt 0) {
        return [pscustomobject]@{ Known = $false; Why = ("{0} registered domain controller(s) have a server object with no serverReference returned, so their computer accounts cannot be told apart from other accounts" -f $noRef.Count); Set = @{} }
    }
    if ($set.Count -ne $dsaCount) {
        return [pscustomobject]@{ Known = $false; Why = ("{0} nTDSDSA object(s) were returned but {1} domain controller computer account(s) were matched through their server objects, so the population is incomplete" -f $dsaCount, $set.Count); Set = @{} }
    }
    return [pscustomobject]@{ Known = $true; Why = ''; Set = $set }
}

function Get-AdfaPrivDnDomainPart {
    <#
    .SYNOPSIS
        Pure: the trailing DC= components of a distinguished name, lower case - the naming context of
        the domain that holds the object (an inference: a domain's naming context is named by DC=
        components). '' when the DN ends in anything else.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowEmptyString()][string]$Dn = '')
    $parts = @($Dn.Trim().ToLowerInvariant() -split '(?<!\\),' | ForEach-Object { $_.Trim() })
    $kept = @()
    for ($i = $parts.Count - 1; $i -ge 0; $i--) {
        if ($parts[$i] -match '^dc=') { $kept = @($parts[$i]) + $kept } else { break }
    }
    return ($kept -join ',')
}

function Get-AdfaPrivDomainDcList {
    <#
    .SYNOPSIS
        Pure: the registered DCs (lower-case computer-account DNs) whose DN lies in the naming context
        DomainDn - exactly, not in a child domain below it.
    .OUTPUTS
        [string[]]
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param([AllowNull()]$DcState, [AllowEmptyString()][string]$DomainDn = '')
    if ($null -eq $DcState -or -not [bool]$DcState.Known -or [string]::IsNullOrWhiteSpace($DomainDn)) { return @() }
    $want = Get-AdfaPrivDnDomainPart -Dn $DomainDn
    return @(@($DcState.Set.Keys) | Where-Object { (Get-AdfaPrivDnDomainPart -Dn ([string]$_)) -eq $want } | Sort-Object)
}

function Get-AdfaPrivDcMembershipGap {
    <#
    .SYNOPSIS
        Pure: the non-vacuity check of a domain's group reads - every DC registered for the domain must
        be found among the members of its Domain Controllers (516) or Read-only Domain Controllers (521)
        groups as read (directly, nested or by primaryGroupID, which Microsoft documents as 516 and 521
        by default). '' when it holds; otherwise why the membership reads cannot be trusted to be complete.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][string]$Domain, [AllowEmptyString()][string]$DomainDn = '', [AllowNull()]$Groups, [AllowNull()]$Forest)
    $dcState = Get-AdfaPrivDcPopulationState -Forest $Forest
    if (-not [bool]$dcState.Known) { return ("the domain controllers registered in the configuration partition were not read completely ({0}), so the membership reads could not be checked against them" -f $dcState.Why) }
    if ([string]::IsNullOrWhiteSpace($DomainDn)) { return ("the distinguished name of {0} was not read, so its registered domain controllers could not be told" -f $Domain) }
    $dcs = @(Get-AdfaPrivDomainDcList -DcState $dcState -DomainDn $DomainDn)
    if ($dcs.Count -eq 0) { return ("no domain controller registered in the configuration partition belongs to {0}, and every domain has at least one, so what was read is incomplete" -f $Domain) }
    $seen = @{}
    foreach ($key in @('DomainControllers', 'ReadOnlyDomainControllers')) {
        if ($null -eq $Groups -or -not $Groups.Contains($key)) { continue }
        $entry = $Groups[$key]
        if ($null -eq $entry -or $null -eq $entry.Closure) { continue }
        foreach ($p in @($entry.Closure.Principals)) { $seen[([string]$p.Record.Dn).ToLowerInvariant()] = $true }
    }
    $missing = @($dcs | Where-Object { -not $seen.ContainsKey([string]$_) })
    if ($missing.Count -gt 0) {
        return ("{0} of the {1} domain controller(s) registered for {2} were not found among the members of Domain Controllers or Read-only Domain Controllers as read (directly, nested or by primaryGroupID 516/521, Microsoft's defaults), so the membership reads did not return their declared population" -f $missing.Count, $dcs.Count, $Domain)
    }
    return ''
}

function Get-AdfaPrivGroupSpec {
    <#
    .SYNOPSIS
        Pure: the groups of the Privileged table that apply to one scoped domain, in table order, each
        with the SID it is located by.
    .DESCRIPTION
        Scope Builtin: the fixed SID (S-1-5-32-x), present in every domain. Scope Domain: <domain
        SID>-RID. Scope ForestRoot: <forest root SID>-RID, and only for the forest root domain. A group
        whose SID cannot be built (the domain's SID was not read) carries Sid '' and is Not Assessed.
    .OUTPUTS
        [pscustomobject[]] Key, Name, Rid, Scope, Protected, Always, Sid.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowEmptyString()][string]$DomainSid = '',
        [bool]$IsRoot = $false,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $specs = @()
    foreach ($g in @($Config['Groups'])) {
        $scope = [string]$g['Scope']
        if ($scope -eq 'ForestRoot' -and -not $IsRoot) { continue }
        $sid = ''
        $rid = $null
        if ($scope -eq 'Builtin') { $sid = [string]$g['Sid'] }
        else {
            $rid = [int]$g['Rid']
            if ($DomainSid -ne '') { $sid = ("{0}-{1}" -f $DomainSid, $rid) }
        }
        $specs += [pscustomobject]@{ Key = [string]$g['Key']; Name = [string]$g['Name']; Rid = $rid; Scope = $scope; Protected = [bool]$g['Protected']; Always = [bool]$g['Always']; Sid = $sid }
    }
    return @($specs)
}

function Resolve-AdfaPrivDnDomain {
    <#
    .SYNOPSIS
        Pure: the scoped domain a distinguished name belongs to, so it is read from that domain.
    .DESCRIPTION
        The forest domain whose DN is the longest suffix of the DN. Routed when that domain is scoped;
        OutOfScope when it is a forest domain that is not scoped, or when no forest domain's DN is a
        suffix (the reference rule, AdAssessment26 decision 56: a member in a domain that is not read
        makes the count Not Assessed, never lower); Ambiguous when two domains share that DN, or when a
        forest domain whose DN was not read is a DNS child of the matched one and the DN has a DC=
        component above the matched domain's DN, so that child could own it. When no read DN matches
        but the DN's trailing DC= components spell a scoped forest domain whose Get-ADDomain read
        failed, the class is that read's own (Unreachable, AccessDenied, TimedOut or Error), never
        OutOfScope.
    .OUTPUTS
        [pscustomobject] Class (Routed | OutOfScope | Ambiguous | Unreachable | AccessDenied | TimedOut |
        Error), Domain, Why.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Dn = '',
        [Parameter(Mandatory)][hashtable]$DomainMap,
        [AllowNull()][AllowEmptyCollection()][string[]]$Scoped = @()
    )
    $lower = $Dn.Trim().ToLowerInvariant()
    $best = @(); $bestLength = -1
    $unread = @()
    foreach ($name in @($DomainMap.Keys)) {
        $entry = $DomainMap[$name]
        $domainDn = ''
        if ($null -ne $entry -and [bool]$entry.Ok) { $domainDn = ([string]$entry.DomainDn).Trim().ToLowerInvariant() }
        if ($domainDn -eq '') { $unread += [string]$name; continue }
        if ($lower -eq $domainDn -or $lower.EndsWith(',' + $domainDn)) {
            if ($domainDn.Length -gt $bestLength) { $best = @([string]$name); $bestLength = $domainDn.Length }
            elseif ($domainDn.Length -eq $bestLength) { $best += [string]$name }
        }
    }
    if ($best.Count -eq 0) {
        # A forest domain whose Get-ADDomain read failed has no DN to match. When the DN's trailing DC=
        # components spell that domain's DNS name, its own read failure is the cause - unreachable,
        # access denied, timed out - kept apart from "out of scope".
        $dnsName = ((Get-AdfaPrivDnDomainPart -Dn $lower) -split ',' | Where-Object { $_ -ne '' } | ForEach-Object { $_.Substring(3) }) -join '.'
        $owner = @($unread | Where-Object { $dnsName -ne '' -and ([string]$_).ToLowerInvariant() -eq $dnsName })
        if ($owner.Count -eq 1) {
            $ownerName = [string]$owner[0]
            $ownerScoped = (@(@($Scoped) | Where-Object { ([string]$_).ToLowerInvariant() -eq $ownerName.ToLowerInvariant() }).Count -gt 0)
            if ($ownerScoped) {
                $entry = $DomainMap[$ownerName]
                $err = ''; $type = ''
                if ($null -ne $entry) {
                    $errProp = $entry.PSObject.Properties['Error']; $typeProp = $entry.PSObject.Properties['ErrorType']
                    if ($null -ne $errProp) { $err = ([string]$errProp.Value).Trim() }
                    if ($null -ne $typeProp) { $type = [string]$typeProp.Value }
                }
                $class = Get-AdfaPrivReadClass -Message $err -TypeName $type
                if ($class -eq 'NotFound' -or $class -eq '') { $class = 'Error' }
                if ($err -eq '') { $err = 'no error text was returned' }
                return [pscustomobject]@{ Class = $class; Domain = $ownerName; Why = ("its domain {0}, scoped by this run, could not be read: {1}" -f $ownerName, $err) }
            }
            return [pscustomobject]@{ Class = 'OutOfScope'; Domain = $ownerName; Why = ("it is in {0}, a domain of this forest that this run did not scope and whose distinguished name was not read" -f $ownerName) }
        }
        return [pscustomobject]@{ Class = 'OutOfScope'; Domain = ''; Why = 'it is not under any domain of this forest whose distinguished name was read' }
    }
    if ($best.Count -gt 1) {
        return [pscustomobject]@{ Class = 'Ambiguous'; Domain = ''; Why = ("{0} domains report the same distinguished name ({1}), so the domain that holds it cannot be told" -f $best.Count, (($best | Sort-Object) -join ', ')) }
    }
    $match = [string]$best[0]
    # Only a DN with a DC= component above the matched domain's own DN could sit in a child domain
    # (a domain's naming context is named by DC= components - an inference, used only to make the
    # routing MORE cautious).
    $above = $lower.Substring(0, $lower.Length - $bestLength).TrimEnd(',')
    $children = @()
    if ($above -match '(^|,)dc=') { $children = @($unread | Where-Object { ([string]$_).ToLowerInvariant().EndsWith('.' + $match.ToLowerInvariant()) }) }
    if ($children.Count -gt 0) {
        return [pscustomobject]@{ Class = 'Ambiguous'; Domain = ''; Why = ("the distinguished name of {0}, a child of {1}, was not read, so it may hold this object" -f (($children | Sort-Object) -join ', '), $match) }
    }
    $isScoped = (@(@($Scoped) | Where-Object { ([string]$_).ToLowerInvariant() -eq $match.ToLowerInvariant() }).Count -gt 0)
    if (-not $isScoped) {
        return [pscustomobject]@{ Class = 'OutOfScope'; Domain = $match; Why = ("it is in {0}, a domain of this forest that this run did not scope (-AllDomains scopes every domain)" -f $match) }
    }
    return [pscustomobject]@{ Class = 'Routed'; Domain = $match; Why = '' }
}

function New-AdfaPrivContext {
    <#
    .SYNOPSIS
        Pure: the per-run reading context of C10 - the forest's domains, the scoped ones, the caches of
        object and primary-group reads, and the read budget.
    .DESCRIPTION
        Object reads are cached by DN and primary-group searches by "<domain>|<RID>", for the whole run,
        so a member of several privileged groups is read once. Offline = $true (tests only) answers any
        DN that is not in the cache as NotFound instead of reading the directory.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$DomainMap,
        [AllowNull()][AllowEmptyCollection()][string[]]$Scoped = @(),
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config,
        [switch]$Offline
    )
    return @{
        DomainMap = $DomainMap; Scoped = @($Scoped); AdParams = $AdParams; Config = $Config
        Objects = @{}; Primary = @{}; Used = 0; Limit = [int]$Config['MaxExpandedObjects']; Offline = [bool]$Offline
    }
}

function Read-AdfaPrivObject {
    <#
    .SYNOPSIS
        One member DN as a record, through the run's cache: routed to its own domain, read once.
        Read-only. Never throws.
    .OUTPUTS
        [pscustomobject] Ok, Class, Error, ErrorType, Record.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][hashtable]$Context, [Parameter(Mandatory)][string]$Dn)
    $key = $Dn.Trim().ToLowerInvariant()
    if ($Context['Objects'].ContainsKey($key)) { return $Context['Objects'][$key] }
    if ([bool]$Context['Offline']) {
        return [pscustomobject]@{ Ok = $false; Class = 'NotFound'; Error = 'not in the offline directory'; ErrorType = ''; Record = $null }
    }
    $route = Resolve-AdfaPrivDnDomain -Dn $Dn -DomainMap $Context['DomainMap'] -Scoped @($Context['Scoped'])
    if ([string]$route.Class -ne 'Routed') {
        $result = [pscustomobject]@{ Ok = $false; Class = [string]$route.Class; Error = [string]$route.Why; ErrorType = ''; Record = $null }
        $Context['Objects'][$key] = $result
        return $result
    }
    if ([int]$Context['Used'] -ge [int]$Context['Limit']) {
        return [pscustomobject]@{ Ok = $false; Class = 'Limit'; Error = ("the run reached MaxExpandedObjects ({0}, a tool default, not a Microsoft value) and read no further member" -f [int]$Context['Limit']); ErrorType = ''; Record = $null }
    }
    $Context['Used'] = [int]$Context['Used'] + 1
    $raw = Get-AdfaPrivObjectRaw -Identity $Dn -Server ([string]$route.Domain) -Properties @($Context['Config']['ObjectProperties']) -AdParams $Context['AdParams']
    $record = $null
    if ([bool]$raw.Ok) { $record = ConvertTo-AdfaPrivRecord -Object $raw.Object -Config $Context['Config'] }
    $result = [pscustomobject]@{ Ok = [bool]$raw.Ok; Class = [string]$raw.Class; Error = [string]$raw.Error; ErrorType = [string]$raw.ErrorType; Record = $record }
    $Context['Objects'][$key] = $result
    return $result
}

function Read-AdfaPrivPrimary {
    <#
    .SYNOPSIS
        The principals whose primaryGroupID is a group's RID, read once per run from the group's own
        domain. Read-only. Never throws.
    .DESCRIPTION
        Membership through the primary group is not in the member attribute (Learn, Defender for
        Identity, and AdAssessment26 N56), so it is read with (primaryGroupID=<RID>) in the domain that
        holds the group. A group whose SID is not an account-domain SID (a builtin group) cannot be a
        primary group and is skipped as Read with no record. The results count against the run's
        MaxExpandedObjects budget, as member reads do: the search asks for one more object than is
        left (-ResultSetSize), and an answer larger than what is left is Class Limit with no record.
    .OUTPUTS
        [pscustomobject] Ok, Class, Error, ErrorType, Records.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][hashtable]$Context, [Parameter(Mandatory)]$Group)
    if (-not [bool]$Group.IsAccountDomainSid -or $null -eq $Group.Rid) {
        return [pscustomobject]@{ Ok = $true; Class = 'Read'; Error = ''; ErrorType = ''; Records = @() }
    }
    $route = $null
    if ([bool]$Context['Offline']) { $route = [pscustomobject]@{ Class = 'Routed'; Domain = 'offline'; Why = '' } }
    else { $route = Resolve-AdfaPrivDnDomain -Dn ([string]$Group.Dn) -DomainMap $Context['DomainMap'] -Scoped @($Context['Scoped']) }
    $key = ("{0}|{1}" -f ([string]$route.Domain).ToLowerInvariant(), [string]$Group.Rid)
    if ([bool]$Context['Offline']) { $key = ("{0}|{1}" -f ([string]$Group.Dn).ToLowerInvariant(), [string]$Group.Rid) }
    if ($Context['Primary'].ContainsKey($key)) { return $Context['Primary'][$key] }
    if ([bool]$Context['Offline']) {
        return [pscustomobject]@{ Ok = $true; Class = 'Read'; Error = ''; ErrorType = ''; Records = @() }
    }
    if ([string]$route.Class -ne 'Routed') {
        $result = [pscustomobject]@{ Ok = $false; Class = [string]$route.Class; Error = [string]$route.Why; ErrorType = ''; Records = @() }
        $Context['Primary'][$key] = $result
        return $result
    }
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $filter = ("(primaryGroupID={0})" -f ([int64]$Group.Rid).ToString($inv))
    # The run's read budget covers these results too: the search asks for one more object than is left,
    # so "more than is left" is seen without reading the rest.
    $left = [int]$Context['Limit'] - [int]$Context['Used']
    $capText = ("the run reached MaxExpandedObjects ({0}, a tool default, not a Microsoft value) and the {1} search was not counted" -f [int]$Context['Limit'], $filter)
    if ($left -le 0) {
        $result = [pscustomobject]@{ Ok = $false; Class = 'Limit'; Error = $capText; ErrorType = ''; Records = @() }
        $Context['Primary'][$key] = $result
        return $result
    }
    $raw = Get-AdfaPrivSearchRaw -Server ([string]$route.Domain) -LDAPFilter $filter -Properties @($Context['Config']['ObjectProperties']) -AdParams $Context['AdParams'] -ResultSetSize ($left + 1)
    if ([bool]$raw.Ok -and @($raw.Objects).Count -gt $left) {
        $Context['Used'] = [int]$Context['Limit']
        $result = [pscustomobject]@{ Ok = $false; Class = 'Limit'; Error = ("the {0} search returned more than the {1} object(s) left under MaxExpandedObjects ({2}, a tool default, not a Microsoft value), so its members were not counted" -f $filter, $left, [int]$Context['Limit']); ErrorType = ''; Records = @() }
        $Context['Primary'][$key] = $result
        return $result
    }
    if ([bool]$raw.Ok) { $Context['Used'] = [int]$Context['Used'] + @($raw.Objects).Count }
    $records = @()
    if ([bool]$raw.Ok) {
        foreach ($o in @($raw.Objects)) {
            $r = ConvertTo-AdfaPrivRecord -Object $o -Config $Context['Config']
            $records += $r
            if ($r.Dn -ne '') {
                $objKey = $r.Dn.ToLowerInvariant()
                if (-not $Context['Objects'].ContainsKey($objKey)) { $Context['Objects'][$objKey] = [pscustomobject]@{ Ok = $true; Class = 'Read'; Error = ''; ErrorType = ''; Record = $r } }
            }
        }
    }
    $result = [pscustomobject]@{ Ok = [bool]$raw.Ok; Class = [string]$raw.Class; Error = [string]$raw.Error; ErrorType = [string]$raw.ErrorType; Records = @($records) }
    $Context['Primary'][$key] = $result
    return $result
}

function Find-AdfaPrivGroup {
    <#
    .SYNOPSIS
        One privileged group of a domain, located by its SID - never by name. Read-only. Never throws.
    .DESCRIPTION
        Get-ADObject -Server <domain> -LDAPFilter (objectSid=<encoded SID>) asking for the record's
        property list. No object is NotFound ("not visible to this account"); more than one is
        Duplicate - the read succeeded, and its answer cannot name one group.
    .OUTPUTS
        [pscustomobject] Ok, Class (Read | NotFound | Duplicate | NoSid | Refused | Unreachable |
        AccessDenied | TimedOut | Error), Error, ErrorType, Filter, Record.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][hashtable]$Context, [Parameter(Mandatory)][string]$Server, [AllowEmptyString()][string]$Sid = '')
    $encoded = ConvertTo-AdfaLdapSidFilterValue -Sid $Sid
    if ($encoded -eq '') {
        return [pscustomobject]@{ Ok = $false; Class = 'NoSid'; Error = 'the SID of the group could not be built, because the SID of its domain was not read'; ErrorType = ''; Filter = ''; Record = $null }
    }
    $filter = ("(objectSid={0})" -f $encoded)
    $raw = Get-AdfaPrivSearchRaw -Server $Server -LDAPFilter $filter -Properties @($Context['Config']['ObjectProperties']) -AdParams $Context['AdParams']
    if (-not [bool]$raw.Ok) {
        return [pscustomobject]@{ Ok = $false; Class = [string]$raw.Class; Error = [string]$raw.Error; ErrorType = [string]$raw.ErrorType; Filter = $filter; Record = $null }
    }
    $objects = @($raw.Objects)
    if ($objects.Count -eq 0) {
        return [pscustomobject]@{ Ok = $false; Class = 'NotFound'; Error = 'the search returned no object'; ErrorType = ''; Filter = $filter; Record = $null }
    }
    if ($objects.Count -gt 1) {
        return [pscustomobject]@{ Ok = $false; Class = 'Duplicate'; Error = ("the search by SID returned {0} objects" -f $objects.Count); ErrorType = ''; Filter = $filter; Record = $null }
    }
    $record = ConvertTo-AdfaPrivRecord -Object $objects[0] -Config $Context['Config']
    if ($record.Dn -ne '') { $Context['Objects'][$record.Dn.ToLowerInvariant()] = [pscustomobject]@{ Ok = $true; Class = 'Read'; Error = ''; ErrorType = ''; Record = $record } }
    return [pscustomobject]@{ Ok = $true; Class = 'Read'; Error = ''; ErrorType = ''; Filter = $filter; Record = $record }
}

function Get-AdfaPrivUnresolvedText {
    <#
    .SYNOPSIS
        Pure: why one member reference was not resolved, in words, by class.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Read)
    if ($null -eq $Read) { return 'not read (no answer)' }
    $err = ([string]$Read.Error).Trim()
    switch ([string]$Read.Class) {
        'OutOfScope' { return ("out of scope: {0}" -f $err) }
        'Ambiguous' { return ("domain not decided: {0}" -f $err) }
        'NotFound' { return 'not found in its domain' }
        'Duplicate' { return ("ambiguous answer: {0}" -f $err) }
        'Limit' { return 'not read: the read cap was reached' }
        'Unreachable' { return ("unreachable: {0}" -f $err) }
        'AccessDenied' { return ("access denied: {0}" -f $err) }
        'TimedOut' { return ("timed out: {0}" -f $err) }
        'Refused' { return ("not asked: {0}" -f $err) }
        default { return ("read failed: {0}" -f $err) }
    }
}

function Resolve-AdfaPrivGroupClosure {
    <#
    .SYNOPSIS
        A group's transitive membership: every member DN followed through nested groups (security and
        distribution alike, as Learn's protection rule counts both) and every group's primary-group
        members, each object read once. Cycle-safe. Read-only; the reads go through the context.
    .DESCRIPTION
        Leaf principals are unique by DN and carry how they were reached: direct (a value of the
        group's own member attribute), nested (through another group) or primary (primaryGroupID).
        A foreign security principal is kept with its SID and never expanded. A member DN that could
        not be read - out of scope, domain not decided, not found, unreachable, access denied, timed
        out, read cap - is kept in Unresolved with the reason; so is a group whose member list came
        back holding exactly one of MemberRangeLimits values (a range-retrieval limit), which may be
        truncated. Complete is true only when nothing is unresolved.
    .OUTPUTS
        [pscustomobject] Group, Complete, Principals (Record, Via), Groups, Foreign, Unresolved (Ref, Reason).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Group,
        [Parameter(Mandatory)][hashtable]$Context,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $principals = [ordered]@{}
    $groups = New-Object System.Collections.ArrayList
    $foreign = New-Object System.Collections.ArrayList
    $unresolved = New-Object System.Collections.ArrayList
    $visited = @{}
    $rootKey = ([string]$Group.Dn).ToLowerInvariant()
    $visited[$rootKey] = $true
    $queue = New-Object System.Collections.Queue
    $queue.Enqueue($Group)
    $limits = @(@($Config['MemberRangeLimits']) | ForEach-Object { [int]$_ })
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    while ($queue.Count -gt 0) {
        $g = $queue.Dequeue()
        $isRoot = (([string]$g.Dn).ToLowerInvariant() -eq $rootKey)
        $via = 'nested'
        if ($isRoot) { $via = 'direct' }
        $members = @($g.Members)
        if ($limits -contains $members.Count) {
            [void]$unresolved.Add([pscustomobject]@{ Ref = [string]$g.Dn; Reason = ("its member list came back with exactly {0} values, a range-retrieval limit (MaxValRange), so it may be truncated" -f $members.Count.ToString($inv)) })
        }
        foreach ($m in $members) {
            $key = ([string]$m).ToLowerInvariant()
            if ($visited.ContainsKey($key)) { continue }
            $visited[$key] = $true
            $read = Read-AdfaPrivObject -Context $Context -Dn ([string]$m)
            if ($null -eq $read -or -not [bool]$read.Ok -or $null -eq $read.Record) {
                [void]$unresolved.Add([pscustomobject]@{ Ref = [string]$m; Reason = (Get-AdfaPrivUnresolvedText -Read $read) })
                continue
            }
            $rec = $read.Record
            if ([string]$rec.Kind -eq 'Group') { [void]$groups.Add($rec); $queue.Enqueue($rec) }
            elseif ([string]$rec.Kind -eq 'Foreign') { [void]$foreign.Add($rec) }
            else { $principals[$key] = [pscustomobject]@{ Record = $rec; Via = $via } }
        }
        $primary = Read-AdfaPrivPrimary -Context $Context -Group $g
        if ($null -eq $primary -or -not [bool]$primary.Ok) {
            [void]$unresolved.Add([pscustomobject]@{ Ref = ("primaryGroupID={0} of {1}" -f [string]$g.Rid, [string]$g.Dn); Reason = (Get-AdfaPrivUnresolvedText -Read $primary) })
            continue
        }
        foreach ($rec in @($primary.Records)) {
            $key = ([string]$rec.Dn).ToLowerInvariant()
            if ($key -eq '' -or $visited.ContainsKey($key)) { continue }
            $visited[$key] = $true
            if ([string]$rec.Kind -eq 'Group') { [void]$groups.Add($rec); $queue.Enqueue($rec) }
            else { $principals[$key] = [pscustomobject]@{ Record = $rec; Via = 'primary' } }
        }
    }
    return [pscustomobject]@{
        Group = $Group; Complete = ($unresolved.Count -eq 0); Principals = @($principals.Values)
        Groups = $groups.ToArray(); Foreign = $foreign.ToArray(); Unresolved = $unresolved.ToArray()
    }
}

function Get-AdfaPrivDelegationFilter {
    <#
    .SYNOPSIS
        Pure: the one search that finds every delegation setting of a domain - TRUSTED_FOR_DELEGATION,
        TRUSTED_TO_AUTH_FOR_DELEGATION, msDS-AllowedToDelegateTo and
        msDS-AllowedToActOnBehalfOfOtherIdentity - with the bits as decimals (Learn: a bitwise rule
        takes a decimal value).
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][hashtable]$Config)
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    return ('(|(userAccountControl:1.2.840.113556.1.4.803:={0})(userAccountControl:1.2.840.113556.1.4.803:={1})(msDS-AllowedToDelegateTo=*)(msDS-AllowedToActOnBehalfOfOtherIdentity=*))' -f `
            ([int64]$Config['Uac']['TrustedForDelegation']).ToString($inv), ([int64]$Config['Uac']['TrustedToAuthForDelegation']).ToString($inv))
}

function Get-AdfaKerberosRoastRaw {
    <#
    .SYNOPSIS
        Directory seam: the Kerberoast and AS-REP reads of one domain, unchanged from before C10 except
        that names are kept apart from the verdict. Read-only. Never throws.
    .OUTPUTS
        [pscustomobject] RoastOk, RoastClass, RoastError, RoastErrorType, Roast (Name, Enabled),
        AsRepOk, AsRepClass, AsRepError, AsRepErrorType, AsRep (Name, Enabled).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$DomainName, [hashtable]$AdParams = @{})
    $out = [pscustomobject]@{
        RoastOk = $false; RoastClass = ''; RoastError = ''; RoastErrorType = ''; Roast = @()
        AsRepOk = $false; AsRepClass = ''; AsRepError = ''; AsRepErrorType = ''; AsRep = @()
    }
    $srv = @{} + $AdParams; $srv.Server = $DomainName
    $toRecord = {
        param($User)
        $samProp = $User.PSObject.Properties['SamAccountName']
        $enabledProp = $User.PSObject.Properties['Enabled']
        $name = ''
        if ($null -ne $samProp -and $null -ne $samProp.Value) { $name = [string]$samProp.Value }
        $enabled = $null
        if ($null -ne $enabledProp -and $enabledProp.Value -is [bool]) { $enabled = [bool]$enabledProp.Value }
        [pscustomobject]@{ Name = $name; Enabled = $enabled }
    }
    try {
        $out.Roast = @(Get-ADUser -LDAPFilter '(&(servicePrincipalName=*)(!(objectClass=computer))(!(cn=krbtgt)))' -Properties servicePrincipalName, msDS-SupportedEncryptionTypes @srv -ErrorAction Stop | ForEach-Object { & $toRecord $_ })
        $out.RoastOk = $true; $out.RoastClass = 'Read'
    }
    catch {
        $out.RoastError = [string]$_.Exception.Message; $out.RoastErrorType = [string]$_.Exception.GetType().FullName
        $out.RoastClass = Get-AdfaPrivReadClass -Message $out.RoastError -TypeName $out.RoastErrorType
    }
    try {
        $out.AsRep = @(Get-ADUser -LDAPFilter ('(&(userAccountControl:1.2.840.113556.1.4.803:={0})(!(objectClass=computer)))' -f $script:Config.Uac.DONT_REQ_PREAUTH) -Properties userAccountControl @srv -ErrorAction Stop | ForEach-Object { & $toRecord $_ })
        $out.AsRepOk = $true; $out.AsRepClass = 'Read'
    }
    catch {
        $out.AsRepError = [string]$_.Exception.Message; $out.AsRepErrorType = [string]$_.Exception.GetType().FullName
        $out.AsRepClass = Get-AdfaPrivReadClass -Message $out.AsRepError -TypeName $out.AsRepErrorType
    }
    return $out
}

function Get-AdfaPrivilegedState {
    <#
    .SYNOPSIS
        Every C10 directory read of the run, once, for the three sections that use them. Read-only.
        Never throws.
    .DESCRIPTION
        Parts says which reads are made: Groups (the privileged groups of every scoped domain and their
        transitive membership - PrivilegedAccounts and PrivilegedHygiene), Hygiene (one (adminCount=1)
        search per domain) and Delegation (one delegation search per domain and the two Kerberos roast
        reads). With any part, the DC population of the configuration partition and dSHeuristics are
        read once (Get-AdfaPrivForestRaw): every part checks its answers against the registered DCs. The domains of
        the forest are each read once with Get-ADDomain (their DN and SID), so a member DN is read from
        the domain that holds it. A domain whose handling throws is kept with the error, and the
        sections report it as a defect of the tool for that domain only.
    .OUTPUTS
        [pscustomobject] Scoped, RootDomain, RootScoped, Parts, DomainMap, Forest, Context, Domains
        (domain -> Domain, Raw, Groups (Key -> Spec, Locate, Closure), AdminCount, Delegation, Roast, Error).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$Domains = @(),
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$ForestDomains = @(),
        [AllowEmptyString()][string]$RootDomain = '',
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config,
        [ValidateSet('Groups', 'Hygiene', 'Delegation')][string[]]$Parts = @('Groups', 'Hygiene', 'Delegation')
    )
    $scoped = New-Object System.Collections.ArrayList
    foreach ($name in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        if (@($scoped | Where-Object { $_ -eq $name.Trim() }).Count -eq 0) { [void]$scoped.Add($name.Trim()) }
    }
    $root = ''
    if (-not [string]::IsNullOrWhiteSpace($RootDomain)) { $root = $RootDomain.Trim() }
    $state = [pscustomobject]@{
        Scoped = @($scoped.ToArray()); RootDomain = $root; RootScoped = (@($scoped | Where-Object { $_ -eq $root }).Count -gt 0 -and $root -ne '')
        Parts = @($Parts); DomainMap = @{}; Forest = $null; Context = $null; Domains = @{}
    }
    if ($scoped.Count -eq 0) { return $state }
    $mapNames = New-Object System.Collections.ArrayList
    foreach ($name in @(@($ForestDomains) + @($scoped.ToArray()) + @($root) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { ([string]$_).Trim() })) {
        if (@($mapNames | Where-Object { $_ -eq $name }).Count -eq 0) { [void]$mapNames.Add($name) }
    }
    foreach ($name in $mapNames) { $state.DomainMap[$name] = Get-AdfaAclDomainRaw -DomainName $name -AdParams $AdParams }
    $context = New-AdfaPrivContext -DomainMap $state.DomainMap -Scoped @($scoped.ToArray()) -AdParams $AdParams -Config $Config
    $state.Context = $context
    # Every part needs the registered DCs: the group rows check their membership reads against them,
    # the hygiene rows read dSHeuristics, and the delegation rows exclude DCs by them.
    if (@($Parts).Count -gt 0) { $state.Forest = Get-AdfaPrivForestRaw -RootDomain $root -AdParams $AdParams -Config $Config }
    foreach ($domain in $scoped) {
        $entry = [pscustomobject]@{ Domain = $domain; Raw = $state.DomainMap[$domain]; Groups = [ordered]@{}; AdminCount = $null; Delegation = $null; Roast = $null; Error = '' }
        try {
            $raw = $entry.Raw
            if ($null -ne $raw -and [bool]$raw.Ok) {
                if (@($Parts) -contains 'Groups') {
                    $isRoot = ($domain -eq $root)
                    foreach ($spec in @(Get-AdfaPrivGroupSpec -DomainSid ([string]$raw.DomainSid) -IsRoot $isRoot -Config $Config)) {
                        $locate = Find-AdfaPrivGroup -Context $context -Server $domain -Sid ([string]$spec.Sid)
                        $closure = $null
                        if ([bool]$locate.Ok) { $closure = Resolve-AdfaPrivGroupClosure -Group $locate.Record -Context $context -Config $Config }
                        $entry.Groups[[string]$spec.Key] = [pscustomobject]@{ Spec = $spec; Locate = $locate; Closure = $closure }
                    }
                }
                if (@($Parts) -contains 'Hygiene') {
                    $search = Get-AdfaPrivSearchRaw -Server $domain -LDAPFilter ([string]$Config['AdminCountFilter']) -Properties @($Config['ObjectProperties']) -AdParams $AdParams
                    $entry.AdminCount = [pscustomobject]@{ Ok = [bool]$search.Ok; Class = [string]$search.Class; Error = [string]$search.Error; ErrorType = [string]$search.ErrorType; Filter = [string]$search.Filter
                        Records = @(@($search.Objects) | ForEach-Object { ConvertTo-AdfaPrivRecord -Object $_ -Config $Config }) }
                }
                if (@($Parts) -contains 'Delegation') {
                    $search = Get-AdfaPrivSearchRaw -Server $domain -LDAPFilter (Get-AdfaPrivDelegationFilter -Config $Config) -Properties @($Config['DelegationProperties']) -AdParams $AdParams
                    $entry.Delegation = [pscustomobject]@{ Ok = [bool]$search.Ok; Class = [string]$search.Class; Error = [string]$search.Error; ErrorType = [string]$search.ErrorType; Filter = [string]$search.Filter
                        Records = @(@($search.Objects) | ForEach-Object { ConvertTo-AdfaPrivRecord -Object $_ -Config $Config }) }
                }
            }
            if (@($Parts) -contains 'Delegation') { $entry.Roast = Get-AdfaKerberosRoastRaw -DomainName $domain -AdParams $AdParams }
        }
        catch { $entry.Error = [string]$_.Exception.Message }
        $state.Domains[$domain] = $entry
    }
    return $state
}

function Get-AdfaPrivNameList {
    <#
    .SYNOPSIS
        Pure: the names and SIDs of a list of records, capped at NameListCap, for the display columns.
    .DESCRIPTION
        Records holds the listed records themselves, in the listed order, so that every other display
        column of a row (Targets, AllowedSids) is built from the same accounts Principals names.
    .OUTPUTS
        [pscustomobject] Listed, NotListed, Names, Sids, Records.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][AllowEmptyCollection()][object[]]$Records = @(), [Parameter(Mandatory)][hashtable]$Config)
    # Ordinal order, so 5.1 and 7 on any platform list the same names in the same order.
    # The keys carry each record's position, and only the string array is sorted in place: PowerShell
    # copies an object array it hands to the two-array Sort overload, so that one would sort nothing.
    $given = @(@($Records) | Where-Object { $null -ne $_ })
    $keys = New-Object 'string[]' $given.Count
    for ($i = 0; $i -lt $given.Count; $i++) { $keys[$i] = ("{0}`n{1}`n{2:D9}" -f [string]$given[$i].Name, [string]$given[$i].Dn, $i) }
    [System.Array]::Sort($keys, [System.StringComparer]::OrdinalIgnoreCase)
    $all = @($keys | ForEach-Object { $given[[int]($_.Substring($_.LastIndexOf("`n") + 1))] })
    $cap = [int]$Config['NameListCap']
    $listed = [math]::Min($cap, $all.Count)
    $names = @(); $sids = @(); $kept = @()
    for ($i = 0; $i -lt $listed; $i++) {
        $kept += $all[$i]
        $names += [string]$all[$i].Name
        $sid = [string]$all[$i].Sid
        if ($sid -eq '') { $sid = '(no SID read)' }
        $sids += $sid
    }
    return [pscustomobject]@{ Listed = $listed; NotListed = ($all.Count - $listed); Names = ($names -join '; '); Sids = ($sids -join '; '); Records = @($kept) }
}

function Get-AdfaPrivLocateLead {
    <#
    .SYNOPSIS
        Pure: the opening of a Not Assessed row for a privileged group that was not located, or (with
        -Search) for a search that failed, by class.
    .DESCRIPTION
        NotFound means "no group with that SID" only for a group lookup. For a search (-Search: the
        adminCount, delegation and roast reads), the module's identity-not-found exception means the
        directory refused an object the search needed (its base, for instance), and is worded so.
        Duplicate is a lookup that succeeded and returned more than one object: not a refusal.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Locate, [Parameter(Mandatory)][string]$What, [switch]$Search)
    if ($null -eq $Locate) { return 'Not assessed: the group was not looked up. This is a defect in the tool, not a result.' }
    switch ([string]$Locate.Class) {
        'NotFound' {
            if ([bool]$Search) { return ("Not found: the search for {0} was answered that an object it needed does not exist (the module's identity-not-found exception: {1}), so nothing was read. This is not an empty result. This is not a clean result." -f $What, ([string]$Locate.Error).Trim()) }
            return ("Not found: no group with the SID of {0} is visible to this account, so its members were not read. That group exists in every such domain, so this is not an empty group; it is what this account can see. This is not a clean result." -f $What)
        }
        'Duplicate' { return ("Not assessed: the lookup of {0} by SID succeeded but its answer is ambiguous - {1} - so which object is the group cannot be told. This is not a refusal and not a missing right. This is not a clean result." -f $What, ([string]$Locate.Error).Trim()) }
        'NoSid' { return ("Not assessed: {0} - {1}. This is not a clean result." -f $What, ([string]$Locate.Error).Trim()) }
        'Refused' { return ("Not assessed: {0} - {1}. This is a defect in the tool, not a result." -f $What, ([string]$Locate.Error).Trim()) }
        default { return ("{0} This is not a clean result." -f (Get-AdfaLapsReadFailureLead -Message ([string]$Locate.Error) -TypeName ([string]$Locate.ErrorType) -What $What)) }
    }
}

function Get-AdfaPrivMemberSummary {
    <#
    .SYNOPSIS
        Pure: the leaf members of a closure, counted by kind, with the display columns.
    .DESCRIPTION
        Counted: every leaf principal (user, computer or other) and every foreign security principal,
        each once. Nested groups are counted apart and are not members in the count. -ExcludeSid takes
        principals out of the count (the Enterprise Admins exemption of the forest root's
        Administrator, when the config switches it on); they are returned in Excluded.
    .OUTPUTS
        [pscustomobject] Count, Users, Computers, Others, Foreign, Groups, Unresolved, Counted, Excluded,
        Names (Get-AdfaPrivNameList), ForeignSids, UnresolvedText.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)]$Closure, [Parameter(Mandatory)][hashtable]$Config, [AllowEmptyString()][string]$ExcludeSid = '')
    $counted = @(); $excluded = @()
    foreach ($p in @($Closure.Principals)) {
        $rec = $p.Record
        if ($ExcludeSid -ne '' -and [string]$rec.Sid -eq $ExcludeSid) { $excluded += $rec } else { $counted += $rec }
    }
    $foreign = @($Closure.Foreign)
    $unresolved = @($Closure.Unresolved)
    $users = @($counted | Where-Object { $_.Kind -eq 'User' }).Count
    $computers = @($counted | Where-Object { $_.Kind -eq 'Computer' }).Count
    $others = $counted.Count - $users - $computers
    $names = Get-AdfaPrivNameList -Records $counted -Config $Config
    return [pscustomobject]@{
        Count = ($counted.Count + $foreign.Count); Users = $users; Computers = $computers; Others = $others; Foreign = $foreign.Count
        Groups = @($Closure.Groups).Count; Unresolved = $unresolved.Count; Counted = $counted; Excluded = $excluded; Names = $names
        ForeignSids = (@($foreign | ForEach-Object { $s = [string]$_.Sid; if ($s -eq '') { $s = [string]$_.Dn }; $s }) -join '; ')
        UnresolvedText = (@($unresolved | ForEach-Object { "{0} ({1})" -f [string]$_.Ref, [string]$_.Reason }) -join '; ')
    }
}

function Get-AdfaPrivEmptyGroupVerdict {
    <#
    .SYNOPSIS
        Pure: "Schema Admins members: <root>" (ADA-PRIV-001) or "Enterprise Admins members: <root>"
        (ADA-PRIV-002) - a group Microsoft says should be empty day to day.
    .DESCRIPTION
        In this order:
          group not located, or not read          Not Assessed, with the cause
          one or more members                     Config.<Key>Status (Warning by default; a TOOL
                                                  DEFAULT, the catalogue rule) - it stands when other
                                                  references could not be resolved, which Detail says
          none counted, a reference unresolved    Not Assessed
          none, but the root domain's membership
          reads failed their non-vacuity check
          (PopulationGap, Get-AdfaPrivDcMembershipGap) Not Assessed: an empty answer is not trusted
          none                                    Pass ("no member visible to this account")
        Members are transitive leaf principals and foreign security principals; nested groups are
        followed, not counted. For Enterprise Admins, EnterpriseAdminsExemptRootAdministrator ($false
        by default, the catalogue rule) takes the forest root's built-in Administrator (RID 500) out of
        the count; Detail always quotes Learn's exception for it.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [Parameter(Mandatory)][ValidateSet('SchemaAdmins', 'EnterpriseAdmins')][string]$Key,
        [AllowNull()]$Entry,
        [AllowEmptyString()][string]$DomainSid = '',
        [Parameter(Mandatory)][hashtable]$Config,
        [AllowEmptyString()][string]$PopulationGap = ''
    )
    $label = 'Schema Admins'
    $catalogue = $Config['Catalogue']['SchemaAdmins']
    $learn = 'Microsoft documents that Schema Admins is intended to be populated only temporarily and occasionally, when the schema must be modified'
    if ($Key -eq 'EnterpriseAdmins') {
        $label = 'Enterprise Admins'
        $catalogue = $Config['Catalogue']['EnterpriseAdmins']
        $learn = 'Microsoft documents that Enterprise Admins should contain no users on a day-to-day basis, with the possible exception of the forest root domain''s Administrator account'
    }
    $item = ("{0} members: {1}" -f $label, $Domain)
    $common = @{ Scope = $Domain; Area = 'Privileged'; Item = $item; CatalogueId = [string]$catalogue['Id']; Severity = [string]$catalogue['Severity']; DomainSid = $DomainSid }
    $notRun = 'Not read: whether a member is used only during a change window; who added it and when. Names are in the Principals column only.'
    if ($null -eq $Entry) {
        return (New-AdfaPrivilegedRow @common -Status $script:Status.NotAssessed -NotRun $notRun -Evidence 'none' -Detail 'Not assessed: the group was not looked up. This is a defect in the tool, not a result.')
    }
    $what = ("{0} of {1}" -f $label, $Domain)
    $evidence = ("Get-ADObject -Server {0} -LDAPFilter '{1}', then every member DN read from its own domain and (primaryGroupID=<RID>) for every group reached" -f $Domain, [string]$Entry.Locate.Filter)
    if (-not [bool]$Entry.Locate.Ok -or $null -eq $Entry.Closure) {
        return (New-AdfaPrivilegedRow @common -GroupSid ([string]$Entry.Spec.Sid) -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -Detail (Get-AdfaPrivLocateLead -Locate $Entry.Locate -What $what))
    }
    $exclude = ''
    $rootAdmin = ''
    if ($DomainSid -ne '') { $rootAdmin = ("{0}-{1}" -f $DomainSid, [int]$Config['RootAdministratorRid']) }
    if ($Key -eq 'EnterpriseAdmins' -and [bool]$Config['EnterpriseAdminsExemptRootAdministrator']) { $exclude = $rootAdmin }
    $s = Get-AdfaPrivMemberSummary -Closure $Entry.Closure -Config $Config -ExcludeSid $exclude
    $columns = @{ GroupSid = ([string]$Entry.Spec.Sid); Count = $s.Count; UserCount = $s.Users; ComputerCount = $s.Computers; GroupCount = $s.Groups; ForeignCount = $s.Foreign
        UnresolvedCount = $s.Unresolved; ExcludedCount = @($s.Excluded).Count; Listed = $s.Names.Listed; NotListed = $s.Names.NotListed
        Principals = [string]$s.Names.Names; PrincipalSids = [string]$s.Names.Sids; ForeignSids = [string]$s.ForeignSids; Unresolved = [string]$s.UnresolvedText }
    $defaultNote = ''
    if ($rootAdmin -ne '' -and @(@($Entry.Closure.Principals) | Where-Object { [string]$_.Record.Sid -eq $rootAdmin }).Count -gt 0) {
        $defaultNote = ' The forest root domain''s built-in Administrator (RID 500) is among the members; Microsoft documents it as the default member of this group.'
    }
    $exemptNote = ''
    if (@($s.Excluded).Count -gt 0) { $exemptNote = ' The forest root domain''s built-in Administrator is not counted, because EnterpriseAdminsExemptRootAdministrator is set (Learn''s possible exception).' }
    $unresolvedNote = ''
    if ($s.Unresolved -gt 0) { $unresolvedNote = (" {0} member reference(s) could not be resolved (listed in the Unresolved column), so the true number may be higher." -f $s.Unresolved) }
    if ($s.Count -gt 0) {
        $status = [string]$Config[("{0}Status" -f $Key)]
        $detail = ("{0} member(s) of {1} visible to this account: {2} user, {3} computer, {4} other, {5} foreign security principal(s) reported by SID, reached directly, through {6} nested group(s) or as primary group.{7}{8}{9} {10}. Graded {11}: the grade is a tool default, not a Microsoft value (setting from: {12})." -f `
                $s.Count, $what, $s.Users, $s.Computers, $s.Others, $s.Foreign, $s.Groups, $defaultNote, $exemptNote, $unresolvedNote, $learn, $status, [string]$Config['ThresholdSource'])
        return (New-AdfaPrivilegedRow @common @columns -Status $status -NotRun $notRun -Evidence $evidence -Detail $detail)
    }
    if ($s.Unresolved -gt 0) {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: no member of {0} was resolved, but {1} member reference(s) could not be (listed in the Unresolved column), so the group cannot be called empty. This is not a clean result." -f $what, $s.Unresolved))
    }
    if ($PopulationGap -ne '') {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: no member of {0} was read, but the membership reads of this domain failed their check: {1}. An empty answer from them is not taken as an empty group. This is not a clean result." -f $what, $PopulationGap))
    }
    return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.Pass -NotRun $notRun -Evidence $evidence `
            -Detail ("No member of {0} is visible to this account, directly, through a nested group or as primary group.{1} {2}." -f $what, $exemptNote, $learn))
}

function Get-AdfaPrivGroupCountVerdict {
    <#
    .SYNOPSIS
        Pure: "Privileged group: <name>: <domain>" (ADA-INV-005) - the transitive member count of one
        privileged group. Info, or Not Assessed; no threshold (the reference sets none).
    .DESCRIPTION
        A group the search did not find is Info "not present" when Microsoft documents it only from a
        later functional level or release (Always $false in the table), and Not Assessed otherwise. A
        closure with an unresolved reference is Not Assessed with the count left empty: never a lower
        number.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$Domain, [Parameter(Mandatory)]$Spec, [AllowNull()]$Entry, [AllowEmptyString()][string]$DomainSid = '', [Parameter(Mandatory)][hashtable]$Config)
    $catalogue = $Config['Catalogue']['Inventory']
    $item = ("Privileged group: {0}: {1}" -f [string]$Spec.Name, $Domain)
    $common = @{ Scope = $Domain; Area = 'Privileged'; Item = $item; CatalogueId = [string]$catalogue['Id']; Severity = [string]$catalogue['Severity']; DomainSid = $DomainSid; GroupSid = [string]$Spec.Sid }
    $what = ("{0} of {1}" -f [string]$Spec.Name, $Domain)
    if ($null -eq $Entry) {
        return (New-AdfaPrivilegedRow @common -Status $script:Status.NotAssessed -Evidence 'none' -Detail 'Not assessed: the group was not looked up. This is a defect in the tool, not a result.')
    }
    $evidence = ("Get-ADObject -Server {0} -LDAPFilter '{1}'; member DNs read from their own domain; (primaryGroupID=<RID>)" -f $Domain, [string]$Entry.Locate.Filter)
    if ([string]$Entry.Locate.Class -eq 'NotFound' -and -not [bool]$Spec.Always) {
        return (New-AdfaPrivilegedRow @common -Status $script:Status.Info -Evidence $evidence `
                -Detail ("Not present: no group with the SID of {0} is visible to this account. Microsoft documents this group only from a later functional level or release, so it may not exist in this domain." -f $what))
    }
    if (-not [bool]$Entry.Locate.Ok -or $null -eq $Entry.Closure) {
        return (New-AdfaPrivilegedRow @common -Status $script:Status.NotAssessed -Evidence $evidence -Detail (Get-AdfaPrivLocateLead -Locate $Entry.Locate -What $what))
    }
    $s = Get-AdfaPrivMemberSummary -Closure $Entry.Closure -Config $Config
    if ($s.Unresolved -gt 0) {
        return (New-AdfaPrivilegedRow @common -Status $script:Status.NotAssessed -Evidence $evidence -GroupCount $s.Groups -UnresolvedCount $s.Unresolved -Unresolved ([string]$s.UnresolvedText) `
                -Detail ("Not assessed: {0} member reference(s) of {1} could not be resolved (listed in the Unresolved column), so no count is given - never a lower number. This is not a clean result." -f $s.Unresolved, $what))
    }
    return (New-AdfaPrivilegedRow @common -Status $script:Status.Info -Evidence $evidence -Count $s.Count -UserCount $s.Users -ComputerCount $s.Computers -GroupCount $s.Groups -ForeignCount $s.Foreign -UnresolvedCount 0 `
            -Listed $s.Names.Listed -NotListed $s.Names.NotListed -Principals ([string]$s.Names.Names) -PrincipalSids ([string]$s.Names.Sids) -ForeignSids ([string]$s.ForeignSids) `
            -Detail ("{0} member(s) of {1} visible to this account: {2} user, {3} computer, {4} other, {5} foreign security principal(s) reported by SID, through {6} nested group(s) and primary groups. Inventory: no threshold is applied." -f `
                $s.Count, $what, $s.Users, $s.Computers, $s.Others, $s.Foreign, $s.Groups))
}

function Get-AdfaPrivGroupPopulationVerdict {
    <#
    .SYNOPSIS
        Pure: "Privileged group population: <domain>" - the non-vacuity row of the group table for one
        domain: every declared group located (or documented as optional and absent) and expanded
        completely, and the membership reads found the domain's registered DCs where Microsoft puts
        them by default (PopulationGap from Get-AdfaPrivDcMembershipGap is ''). Counting groups alone
        would pass a domain whose every group came back empty.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$Domain, [AllowNull()][AllowEmptyCollection()][object[]]$Specs = @(), [AllowNull()]$Groups, [AllowEmptyString()][string]$DomainSid = '',
        [AllowEmptyString()][string]$PopulationGap = '')
    $item = ("Privileged group population: {0}" -f $Domain)
    $declared = @($Specs).Count
    $complete = 0; $absent = 0; $notDone = @()
    foreach ($spec in @($Specs)) {
        $entry = $null
        if ($null -ne $Groups -and $Groups.Contains([string]$spec.Key)) { $entry = $Groups[[string]$spec.Key] }
        if ($null -ne $entry -and [bool]$entry.Locate.Ok -and $null -ne $entry.Closure -and [bool]$entry.Closure.Complete) { $complete++ }
        elseif ($null -ne $entry -and [string]$entry.Locate.Class -eq 'NotFound' -and -not [bool]$spec.Always) { $absent++ }
        else { $notDone += [string]$spec.Name }
    }
    $evidence = ("{0} group(s) of the Privileged table apply to {1}, each located by SID" -f $declared, $Domain)
    if ($declared -eq 0) {
        return (New-AdfaPrivilegedRow -Scope $Domain -Area 'Privileged' -Item $item -Status $script:Status.NotAssessed -DomainSid $DomainSid -Evidence $evidence -Count 0 `
                -Detail 'Not assessed: no group of the table applies to this domain. This is a defect in the tool, not a result.')
    }
    if ($notDone.Count -gt 0) {
        return (New-AdfaPrivilegedRow -Scope $Domain -Area 'Privileged' -Item $item -Status $script:Status.NotAssessed -DomainSid $DomainSid -Evidence $evidence -Count $declared -UnresolvedCount $notDone.Count `
                -Detail ("Not assessed: of {0} privileged group(s) declared for {1}, {2} were located and expanded completely and {3} are documented as optional and not present; {4} were not: {5}. Each is in its own row." -f $declared, $Domain, $complete, $absent, $notDone.Count, ($notDone -join ', ')))
    }
    if ($PopulationGap -ne '') {
        return (New-AdfaPrivilegedRow -Scope $Domain -Area 'Privileged' -Item $item -Status $script:Status.NotAssessed -DomainSid $DomainSid -Evidence $evidence -Count $declared -UnresolvedCount 0 `
                -Detail ("Not assessed: all {0} privileged group(s) declared for {1} were located or documented as absent, but {2}. This is not a clean result." -f $declared, $Domain, $PopulationGap))
    }
    return (New-AdfaPrivilegedRow -Scope $Domain -Area 'Privileged' -Item $item -Status $script:Status.Pass -DomainSid $DomainSid -Evidence $evidence -Count $declared -UnresolvedCount 0 `
            -Detail ("All {0} privileged group(s) declared for {1} were accounted for: {2} located by SID and expanded completely, {3} documented as optional and not present." -f $declared, $Domain, $complete, $absent))
}

function Get-AdfaPrivilegedAccount {
    <#
    .SYNOPSIS
        Privileged Accounts rows: "Schema Admins members" and "Enterprise Admins members" for the
        forest root, one "Privileged group: <name>" row per group of the table and a population row
        per scoped domain. Pure over the run's C10 state (Get-AdfaPrivilegedState).
    .DESCRIPTION
        DECLARED POPULATION: the two root rows once per run, scoped to the forest root - Not Assessed
        when the root domain was not scoped - and, for each domain in State.Scoped, one row per group
        Get-AdfaPrivGroupSpec gives it and one population row. With none scoped, one "Privileged groups
        (no domain scoped)" row. An exception while one domain is handled makes its population row Not
        Assessed and never ends the section. Each domain's group reads are checked against its
        registered DCs (Get-AdfaPrivDcMembershipGap): when they fail, the population row is Not
        Assessed, and an empty Schema Admins or Enterprise Admins is not passed.
    .OUTPUTS
        [pscustomobject[]] rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)]$State, [Parameter(Mandatory)][hashtable]$Config)
    $rows = @()
    if (@($State.Scoped).Count -eq 0) {
        $rows += New-AdfaPrivilegedRow -Area 'Privileged' -Item 'Privileged groups (no domain scoped)' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail 'No domain was scoped for this run, so no privileged group was read. This is not a clean result.'
        return @($rows)
    }
    $root = [string]$State.RootDomain
    foreach ($key in @('SchemaAdmins', 'EnterpriseAdmins')) {
        $label = 'Schema Admins'
        if ($key -eq 'EnterpriseAdmins') { $label = 'Enterprise Admins' }
        $catalogue = $Config['Catalogue'][$key]
        $scopeName = $root
        if ($scopeName -eq '') { $scopeName = '(forest root unknown)' }
        $why = ''
        if ($root -eq '') { $why = 'Not assessed: the forest reported no root domain, so this group, which exists only in the forest root, was not read. This is not a clean result.' }
        elseif (-not [bool]$State.RootScoped) { $why = ("Not assessed: this group exists only in the forest root domain {0}, which this run did not scope (-AllDomains scopes every domain). This is not a clean result." -f $root) }
        if ($why -ne '') {
            $rows += New-AdfaPrivilegedRow -Scope $scopeName -Area 'Privileged' -Item ("{0} members: {1}" -f $label, $scopeName) -Status $script:Status.NotAssessed -Evidence 'none' -CatalogueId ([string]$catalogue['Id']) -Severity ([string]$catalogue['Severity']) -Detail $why
            continue
        }
        try {
            $domainState = $State.Domains[$root]
            $entry = $null
            $sid = ''
            if ($null -ne $domainState -and [string]$domainState.Error -eq '' -and $null -ne $domainState.Raw -and [bool]$domainState.Raw.Ok) {
                $sid = [string]$domainState.Raw.DomainSid
                if ($domainState.Groups.Contains($key)) { $entry = $domainState.Groups[$key] }
                $rootGap = Get-AdfaPrivDcMembershipGap -Domain $root -DomainDn ([string]$domainState.Raw.DomainDn) -Groups $domainState.Groups -Forest $State.Forest
                $rows += Get-AdfaPrivEmptyGroupVerdict -Domain $root -Key $key -Entry $entry -DomainSid $sid -Config $Config -PopulationGap $rootGap
            }
            else {
                $detail = 'Not assessed: the forest root domain was not handled. This is a defect in the tool, not a result.'
                if ($null -ne $domainState -and [string]$domainState.Error -ne '') { $detail = ("Not assessed: handling the forest root domain failed inside this tool; this is a defect in the tool, not a result. Error: {0}" -f [string]$domainState.Error) }
                elseif ($null -ne $domainState -and $null -ne $domainState.Raw) { $detail = ("{0} This is not a clean result." -f (Get-AdfaLapsReadFailureLead -Message ([string]$domainState.Raw.Error) -TypeName ([string]$domainState.Raw.ErrorType) -What ("the domain {0} (its distinguished name and SID)" -f $root))) }
                $rows += New-AdfaPrivilegedRow -Scope $root -Area 'Privileged' -Item ("{0} members: {1}" -f $label, $root) -Status $script:Status.NotAssessed -Evidence 'none' -CatalogueId ([string]$catalogue['Id']) -Severity ([string]$catalogue['Severity']) -Detail $detail
            }
        }
        catch {
            $rows += New-AdfaPrivilegedRow -Scope $root -Area 'Privileged' -Item ("{0} members: {1}" -f $label, $root) -Status $script:Status.NotAssessed -Evidence 'none' -CatalogueId ([string]$catalogue['Id']) -Severity ([string]$catalogue['Severity']) `
                -Detail ("Not assessed: grading this group failed inside this tool; this is a defect in the tool, not a result. Error: {0}" -f [string]$_.Exception.Message)
        }
    }
    foreach ($domain in @($State.Scoped)) {
        try {
            $domainState = $State.Domains[$domain]
            $sid = ''
            if ($null -ne $domainState -and $null -ne $domainState.Raw) { $sid = [string]$domainState.Raw.DomainSid }
            $specs = @(Get-AdfaPrivGroupSpec -DomainSid $sid -IsRoot ($domain -eq $root) -Config $Config)
            if ($null -eq $domainState -or [string]$domainState.Error -ne '' -or $null -eq $domainState.Raw -or -not [bool]$domainState.Raw.Ok) {
                $why = 'Not assessed: the domain was not handled. This is a defect in the tool, not a result.'
                if ($null -ne $domainState -and [string]$domainState.Error -ne '') { $why = ("Not assessed: handling {0} failed inside this tool; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$domainState.Error) }
                elseif ($null -ne $domainState -and $null -ne $domainState.Raw) { $why = ("{0} No privileged group of this domain was read. This is not a clean result." -f (Get-AdfaLapsReadFailureLead -Message ([string]$domainState.Raw.Error) -TypeName ([string]$domainState.Raw.ErrorType) -What ("the domain {0} (its distinguished name and SID)" -f $domain))) }
                foreach ($spec in $specs) { $rows += New-AdfaPrivilegedRow -Scope $domain -Area 'Privileged' -Item ("Privileged group: {0}: {1}" -f [string]$spec.Name, $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why -CatalogueId ([string]$Config['Catalogue']['Inventory']['Id']) }
                $rows += New-AdfaPrivilegedRow -Scope $domain -Area 'Privileged' -Item ("Privileged group population: {0}" -f $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why
                continue
            }
            foreach ($spec in $specs) {
                $entry = $null
                if ($domainState.Groups.Contains([string]$spec.Key)) { $entry = $domainState.Groups[[string]$spec.Key] }
                $rows += Get-AdfaPrivGroupCountVerdict -Domain $domain -Spec $spec -Entry $entry -DomainSid $sid -Config $Config
            }
            $gap = Get-AdfaPrivDcMembershipGap -Domain $domain -DomainDn ([string]$domainState.Raw.DomainDn) -Groups $domainState.Groups -Forest $State.Forest
            $rows += Get-AdfaPrivGroupPopulationVerdict -Domain $domain -Specs $specs -Groups $domainState.Groups -DomainSid $sid -PopulationGap $gap
        }
        catch {
            $rows += New-AdfaPrivilegedRow -Scope $domain -Area 'Privileged' -Item ("Privileged group population: {0}" -f $domain) -Status $script:Status.NotAssessed -Evidence 'none' `
                -Detail ("Not assessed: grading the privileged groups of {0} failed inside this tool, so nothing about this domain is graded; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$_.Exception.Message)
        }
    }
    return @($rows)
}

function Get-AdfaPrivProtectedSet {
    <#
    .SYNOPSIS
        Pure: what is protected for one domain - every object reached from its protected groups (the
        Appendix C groups of the domain and its builtin container, and the forest root's protected
        groups), the groups themselves, and why the set may be incomplete.
    .DESCRIPTION
        BySid and ByDn map each protected object to the keys of the groups that reach it. Complete is
        false when a protected group that always exists was not located, when a group was not read,
        when a closure has an unresolved reference, or when the forest root's groups were not read
        (the root was not scoped). Learn's protected accounts (Administrator, krbtgt) are protected by
        RID, not by membership, and are decided by the verdict.
    .OUTPUTS
        [pscustomobject] Complete, Missing, BySid, ByDn, Members (records of protected users and
        computers, by DN), ProtectedUsers (Known, Dns, Why, DelegationEnforced - $true, $false or $null
        from the domain functional level - and ModeText), DomainSid.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)]$State, [Parameter(Mandatory)][string]$Domain, [Parameter(Mandatory)][hashtable]$Config)
    $bySid = @{}; $byDn = @{}; $missing = @(); $members = [ordered]@{}
    $domainState = $State.Domains[$Domain]
    $domainSid = ''
    if ($null -ne $domainState -and $null -ne $domainState.Raw) { $domainSid = [string]$domainState.Raw.DomainSid }
    $root = [string]$State.RootDomain
    $sources = @()
    foreach ($spec in @(Get-AdfaPrivGroupSpec -DomainSid $domainSid -IsRoot ($Domain -eq $root) -Config $Config | Where-Object { [bool]$_.Protected })) {
        $entry = $null
        if ($null -ne $domainState -and $domainState.Groups.Contains([string]$spec.Key)) { $entry = $domainState.Groups[[string]$spec.Key] }
        $sources += [pscustomobject]@{ Spec = $spec; Entry = $entry; Where = $Domain }
    }
    if ($Domain -ne $root) {
        $rootSpecs = @(@($Config['Groups']) | Where-Object { [string]$_['Scope'] -eq 'ForestRoot' -and [bool]$_['Protected'] })
        if (-not [bool]$State.RootScoped) {
            if ($rootSpecs.Count -gt 0) { $missing += ("the forest root's protected groups ({0}) were not read, because the forest root domain was not scoped" -f (@($rootSpecs | ForEach-Object { [string]$_['Name'] }) -join ', ')) }
        }
        else {
            $rootState = $State.Domains[$root]
            $rootSid = ''
            if ($null -ne $rootState -and $null -ne $rootState.Raw) { $rootSid = [string]$rootState.Raw.DomainSid }
            foreach ($spec in @(Get-AdfaPrivGroupSpec -DomainSid $rootSid -IsRoot $true -Config $Config | Where-Object { [bool]$_.Protected -and $_.Scope -eq 'ForestRoot' })) {
                $entry = $null
                if ($null -ne $rootState -and $rootState.Groups.Contains([string]$spec.Key)) { $entry = $rootState.Groups[[string]$spec.Key] }
                $sources += [pscustomobject]@{ Spec = $spec; Entry = $entry; Where = $root }
            }
        }
    }
    $add = {
        param($Rec, [string]$Key)
        $sidKey = [string]$Rec.Sid
        if ($sidKey -ne '') { if (-not $bySid.ContainsKey($sidKey)) { $bySid[$sidKey] = @() }; $bySid[$sidKey] = @($bySid[$sidKey]) + $Key }
        $dnKey = ([string]$Rec.Dn).ToLowerInvariant()
        if ($dnKey -ne '') { if (-not $byDn.ContainsKey($dnKey)) { $byDn[$dnKey] = @() }; $byDn[$dnKey] = @($byDn[$dnKey]) + $Key }
    }
    foreach ($source in $sources) {
        $spec = $source.Spec; $entry = $source.Entry
        $label = ("{0} of {1}" -f [string]$spec.Name, [string]$source.Where)
        if ($null -eq $entry) { $missing += ("{0}: not looked up" -f $label); continue }
        if (-not [bool]$entry.Locate.Ok -or $null -eq $entry.Closure) {
            if ([string]$entry.Locate.Class -eq 'NotFound' -and -not [bool]$spec.Always) { continue }
            $missing += ("{0}: {1}" -f $label, (Get-AdfaPrivUnresolvedText -Read $entry.Locate))
            continue
        }
        & $add $entry.Locate.Record ([string]$spec.Key)
        foreach ($g in @($entry.Closure.Groups)) { & $add $g ([string]$spec.Key) }
        foreach ($f in @($entry.Closure.Foreign)) { & $add $f ([string]$spec.Key) }
        foreach ($p in @($entry.Closure.Principals)) {
            & $add $p.Record ([string]$spec.Key)
            $dnKey = ([string]$p.Record.Dn).ToLowerInvariant()
            if ($dnKey -ne '' -and -not $members.Contains($dnKey)) { $members[$dnKey] = $p.Record }
        }
        if (-not [bool]$entry.Closure.Complete) { $missing += ("{0}: {1} member reference(s) not resolved" -f $label, @($entry.Closure.Unresolved).Count) }
    }
    $puKnown = $false; $puDns = @{}; $puWhy = 'Protected Users was not looked up'
    if ($null -ne $domainState -and $domainState.Groups.Contains('ProtectedUsers')) {
        $pu = $domainState.Groups['ProtectedUsers']
        if ([bool]$pu.Locate.Ok -and $null -ne $pu.Closure -and [bool]$pu.Closure.Complete) {
            $puKnown = $true; $puWhy = ''
            foreach ($p in @($pu.Closure.Principals)) { $puDns[([string]$p.Record.Dn).ToLowerInvariant()] = $true }
        }
        elseif ([string]$pu.Locate.Class -eq 'NotFound') { $puKnown = $true; $puWhy = '' }
        elseif ([bool]$pu.Locate.Ok) { $puWhy = 'the membership of Protected Users was not resolved completely' }
        else { $puWhy = ("Protected Users was not read ({0})" -f (Get-AdfaPrivUnresolvedText -Read $pu.Locate)) }
    }
    # Learn: the DC-side Protected Users restrictions, delegation among them, need domain functional
    # level Windows Server 2012 R2. $true at or above it, $false below it, $null when not known.
    $mode = ''
    if ($null -ne $domainState -and $null -ne $domainState.Raw) {
        $modeProp = $domainState.Raw.PSObject.Properties['DomainMode']
        if ($null -ne $modeProp -and $null -ne $modeProp.Value) { $mode = ([string]$modeProp.Value).Trim() }
    }
    $enforced = $null
    $modeText = ("the domain functional level of {0} was not read" -f $Domain)
    if ($mode -ne '') {
        if (@(@($Config['ProtectedUsersDelegationModes']) | Where-Object { [string]$_ -eq $mode }).Count -gt 0) { $enforced = $true; $modeText = ("the domain functional level is {0}" -f $mode) }
        elseif (@(@($Config['BelowProtectedUsersModes']) | Where-Object { [string]$_ -eq $mode }).Count -gt 0) { $enforced = $false; $modeText = ("the domain functional level is {0}, below Windows Server 2012 R2" -f $mode) }
        else { $modeText = ("the domain functional level {0} is not one this tool knows" -f $mode) }
    }
    return [pscustomobject]@{
        Complete = ($missing.Count -eq 0); Missing = @($missing); BySid = $bySid; ByDn = $byDn; Members = @($members.Values)
        ProtectedUsers = [pscustomobject]@{ Known = $puKnown; Dns = $puDns; Why = $puWhy; DelegationEnforced = $enforced; ModeText = $modeText }; DomainSid = $domainSid
    }
}

function Get-AdfaPrivOrphanVerdict {
    <#
    .SYNOPSIS
        Pure: "adminCount orphans: <domain>" (ADA-OBJ-001) - objects with adminCount=1 that no
        protected group reaches and that are not a protected account.
    .DESCRIPTION
        Population: every object the (adminCount=1) search returned - users, computers and groups,
        enabled or disabled, since an object left with adminCount=1 keeps its inheritance broken
        whatever its state (Learn). Protected: reached by any protected group of the domain or the
        forest root (by SID or DN), or the domain's Administrator (RID 500) or krbtgt (RID 502).
        "Orphan" is this tool's label: Learn calls these objects "formerly protected".
        In this order:
          the search failed                                   Not Assessed, with the cause
          the protected set is incomplete                     Not Assessed (an object may be protected
                                                              through what was not read); the candidates
                                                              are listed
          an object outside it                                Config.OrphanStatus (Warning; a TOOL
                                                              DEFAULT, catalogue D21)
          an object protected only through an operator group,
          and dSHeuristics' dwAdminSDExMask is not 0 or unread Not Assessed (the bit mapping is not
                                                              published on Learn)
          the domain's Administrator (RID 500) is not among
          the objects returned                                Not Assessed: the search did not return
                                                              its declared population (Learn: a
                                                              protected account has adminCount=1)
          otherwise                                           Pass ("none visible")
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$Domain, [AllowNull()]$AdminCount, [Parameter(Mandatory)]$Protected, [Parameter(Mandatory)]$Heuristics, [Parameter(Mandatory)][hashtable]$Config)
    $catalogue = $Config['Catalogue']['Orphan']
    $common = @{ Scope = $Domain; Area = 'PrivHygiene'; Item = ("adminCount orphans: {0}" -f $Domain); CatalogueId = [string]$catalogue['Id']; Severity = [string]$catalogue['Severity']; DomainSid = [string]$Protected.DomainSid }
    $notRun = 'Not read: the ACL of each object (whether inheritance is still disabled), and the history of its memberships. "Orphan" is this tool''s label for what Microsoft calls formerly protected.'
    if ($null -eq $AdminCount) {
        return (New-AdfaPrivilegedRow @common -Status $script:Status.NotAssessed -NotRun $notRun -Evidence 'none' -Detail 'Not assessed: the adminCount search was not made. This is a defect in the tool, not a result.')
    }
    $evidence = ("Get-ADObject -Server {0} -LDAPFilter '{1}'; protected groups expanded transitively by SID; {2}" -f $Domain, [string]$AdminCount.Filter, [string]$Heuristics.Text)
    if (-not [bool]$AdminCount.Ok) {
        $lead = Get-AdfaPrivLocateLead -Locate $AdminCount -What ("the objects with adminCount=1 in {0}" -f $Domain) -Search
        return (New-AdfaPrivilegedRow @common -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -Detail $lead)
    }
    $records = @($AdminCount.Records | Where-Object { $null -ne $_ })
    # Non-vacuity: the domain's Administrator (RID 500) is a protected account, and Learn says a
    # protected account has adminCount set to 1, so a search that did not return it is incomplete.
    $adminRid = [int64]$Config['RootAdministratorRid']
    $adminSeen = ([string]$Protected.DomainSid -ne '' -and @($records | Where-Object { [string]$_.DomainPart -eq [string]$Protected.DomainSid -and $null -ne $_.Rid -and [int64]$_.Rid -eq $adminRid }).Count -gt 0)
    $populationGap = ''
    if (-not $adminSeen) {
        $populationGap = ("the search returned {0} object(s) but not the built-in Administrator (RID 500) of {1}, a protected account whose adminCount Microsoft documents as set to 1, so it did not return its declared population" -f $records.Count, $Domain)
        if ([string]$Protected.DomainSid -eq '') { $populationGap = ("the SID of {0} was not read, so its built-in Administrator (RID 500) could not be looked for among the {1} object(s) returned" -f $Domain, $records.Count) }
    }
    $operatorKeys = @(@($Config['Groups']) | Where-Object { @($Config['OperatorGroupSids']) -contains [string]$_['Sid'] } | ForEach-Object { [string]$_['Key'] })
    $orphans = @(); $undecided = @(); $protectedCount = 0
    foreach ($r in $records) {
        $keys = @()
        if ([string]$r.Sid -ne '' -and $Protected.BySid.ContainsKey([string]$r.Sid)) { $keys += @($Protected.BySid[[string]$r.Sid]) }
        $dnKey = ([string]$r.Dn).ToLowerInvariant()
        if ($dnKey -ne '' -and $Protected.ByDn.ContainsKey($dnKey)) { $keys += @($Protected.ByDn[$dnKey]) }
        $isAccount = ([string]$Protected.DomainSid -ne '' -and [string]$r.DomainPart -eq [string]$Protected.DomainSid -and $null -ne $r.Rid -and @($Config['ProtectedAccountRids']) -contains [int64]$r.Rid)
        if ($isAccount) { $protectedCount++; continue }
        if ($keys.Count -eq 0) { $orphans += $r; continue }
        $other = @($keys | Where-Object { $operatorKeys -notcontains $_ })
        if ($other.Count -eq 0 -and -not ([bool]$Heuristics.Known -and [bool]$Heuristics.MaskZero)) { $undecided += $r; continue }
        $protectedCount++
    }
    $names = Get-AdfaPrivNameList -Records $orphans -Config $Config
    $users = @($orphans | Where-Object { $_.Kind -eq 'User' }).Count
    $computers = @($orphans | Where-Object { $_.Kind -eq 'Computer' }).Count
    $groups = @($orphans | Where-Object { $_.Kind -eq 'Group' }).Count
    $columns = @{ Count = $orphans.Count; UserCount = $users; ComputerCount = $computers; GroupCount = $groups; UnresolvedCount = $undecided.Count; ExcludedCount = $protectedCount
        Listed = $names.Listed; NotListed = $names.NotListed; Principals = [string]$names.Names; PrincipalSids = [string]$names.Sids
        Unresolved = (@($Protected.Missing) -join '; ') }
    $learn = 'Microsoft documents that when an account is removed from a protected group its adminCount attribute remains set to 1 if it is not manually changed, and that the object still does not inherit permissions'
    if (-not [bool]$Protected.Complete) {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: {0} object(s) with adminCount=1 in {1} were not reached from a protected group that was read, but the protected groups were not all read completely ({2} gap(s), listed in the Unresolved column), so an object may be protected through what was not read. They are candidates only, listed in the Principals column. This is not a clean result." -f $orphans.Count, $Domain, @($Protected.Missing).Count))
    }
    if ($orphans.Count -gt 0) {
        $status = [string]$Config['OrphanStatus']
        $undecidedNote = ''
        if ($undecided.Count -gt 0) { $undecidedNote = (" {0} other object(s) are protected only through Account, Server, Print or Backup Operators, and whether dSHeuristics removes those groups from protection could not be decided, so they are not counted." -f $undecided.Count) }
        if ($populationGap -ne '') { $undecidedNote += (" The search may be incomplete - {0} - so there may be more." -f $populationGap) }
        return (New-AdfaPrivilegedRow @common @columns -Status $status -NotRun $notRun -Evidence $evidence `
                -Detail ("{0} object(s) with adminCount=1 in {1} are outside every protected group and are not a protected account: {2} user, {3} computer, {4} group, {5} other; {6} object(s) with adminCount=1 are protected.{7} {8}. Calling them orphans is this tool's inference, not a Microsoft term. Graded {9}: a tool default, not a Microsoft value (setting from: {10})." -f `
                    $orphans.Count, $Domain, $users, $computers, $groups, ($orphans.Count - $users - $computers - $groups), $protectedCount, $undecidedNote, $learn, $status, [string]$Config['ThresholdSource']))
    }
    if ($populationGap -ne '') {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: no object with adminCount=1 in {0} was found outside every protected group, but {1}. This is not a clean result." -f $Domain, $populationGap))
    }
    if ($undecided.Count -gt 0) {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: no object with adminCount=1 in {0} is outside every protected group, but {1} are protected only through Account, Server, Print or Backup Operators, and dSHeuristics' AdminSDHolder exclusion mask is not 0 or was not read. Microsoft does not publish on Learn which bit excludes which group, so whether these objects are still protected is not decided. This is not a clean result." -f $Domain, $undecided.Count))
    }
    return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.Pass -NotRun $notRun -Evidence $evidence `
            -Detail ("None visible: every one of the {0} object(s) with adminCount=1 visible to this account in {1} is reached from a protected group or is a protected account." -f $records.Count, $Domain))
}

function Get-AdfaPrivAccountPopulation {
    <#
    .SYNOPSIS
        Pure: the privileged user accounts of one domain - members (transitively) of its protected
        groups whose SID belongs to the domain, the domain's Administrator, and, with
        -IncludeAdminCount, every user the (adminCount=1) search returned. krbtgt is never in it.
        DECLARED POPULATION: it always holds the domain's built-in Administrator (RID 500), a protected
        account (Appendix C); when that account is not in what was read, a gap says so and the
        population is not Complete.
    .OUTPUTS
        [pscustomobject] Records, Complete, Gaps.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)]$Protected, [AllowNull()]$AdminCount, [Parameter(Mandatory)][hashtable]$Config, [switch]$IncludeAdminCount)
    $byDn = [ordered]@{}
    $gaps = @(@($Protected.Missing))
    $domainSid = [string]$Protected.DomainSid
    $krbtgt = [int64]$Config['KrbtgtRid']
    $adminRid = [int64]$Config['RootAdministratorRid']
    $take = {
        param($Rec)
        if ([string]$Rec.Kind -ne 'User') { return }
        if ([string]$Rec.DomainPart -ne $domainSid) { return }
        if ($null -ne $Rec.Rid -and [int64]$Rec.Rid -eq $krbtgt) { return }
        $k = ([string]$Rec.Dn).ToLowerInvariant()
        if ($k -ne '' -and -not $byDn.Contains($k)) { $byDn[$k] = $Rec }
    }
    foreach ($r in @($Protected.Members)) { & $take $r }
    if ($null -eq $AdminCount -or -not [bool]$AdminCount.Ok) {
        $gaps += 'the adminCount search did not complete'
    }
    else {
        foreach ($r in @($AdminCount.Records)) {
            if ([bool]$IncludeAdminCount -or ($null -ne $r.Rid -and [int64]$r.Rid -eq $adminRid -and [string]$r.DomainPart -eq $domainSid)) { & $take $r }
        }
    }
    if ($domainSid -eq '') { $gaps += 'the SID of the domain was not read' }
    elseif (@(@($byDn.Values) | Where-Object { $null -ne $_.Rid -and [int64]$_.Rid -eq $adminRid }).Count -eq 0) {
        # Non-vacuity: the domain's Administrator is always a protected account (Appendix C).
        $gaps += 'the built-in Administrator (RID 500) of the domain, always a protected account, is not in the population read, so the population is incomplete'
    }
    return [pscustomobject]@{ Records = @($byDn.Values); Complete = ($gaps.Count -eq 0); Gaps = @($gaps) }
}

function Get-AdfaPrivSpnVerdict {
    <#
    .SYNOPSIS
        Pure: "Privileged accounts with SPN: <domain>" (ADA-OBJ-006) - enabled privileged user accounts
        (protected-group members or adminCount=1) that carry a servicePrincipalName. Computer accounts
        are not in the population; krbtgt is not either.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$Domain, [Parameter(Mandatory)]$Population, [Parameter(Mandatory)][hashtable]$Config, [AllowEmptyString()][string]$DomainSid = '')
    $catalogue = $Config['Catalogue']['PrivilegedSpn']
    $common = @{ Scope = $Domain; Area = 'PrivHygiene'; Item = ("Privileged accounts with SPN: {0}" -f $Domain); CatalogueId = [string]$catalogue['Id']; Severity = [string]$catalogue['Severity']; DomainSid = $DomainSid }
    $evidence = 'servicePrincipalName and userAccountControl of the members of the protected groups and of the objects with adminCount=1'
    $notRun = 'Not read: whether a service actually uses each SPN, and the password age or strength of the account.'
    $hits = @(); $unknown = 0; $disabled = 0
    foreach ($r in @($Population.Records)) {
        if (@($r.Spns).Count -eq 0) { continue }
        if ($null -eq $r.Enabled) { $unknown++; continue }
        if (-not [bool]$r.Enabled) { $disabled++; continue }
        $hits += $r
    }
    $names = Get-AdfaPrivNameList -Records $hits -Config $Config
    $columns = @{ Count = $hits.Count; UserCount = @($Population.Records).Count; UnresolvedCount = $unknown; ExcludedCount = $disabled; Listed = $names.Listed; NotListed = $names.NotListed
        Principals = [string]$names.Names; PrincipalSids = [string]$names.Sids; Unresolved = (@($Population.Gaps) -join '; ')
        Targets = (@(@($names.Records) | ForEach-Object { "{0}: {1}" -f [string]$_.Name, (@($_.Spns) -join ', ') }) -join '; ') }
    if ($hits.Count -eq 0 -and @($Population.Records).Count -eq 0) {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: no privileged user account of {0} was read, and the population always holds the domain's built-in Administrator (RID 500), so nothing was measured. This is not a clean result." -f $Domain))
    }
    if ($hits.Count -gt 0) {
        $status = [string]$Config['PrivilegedSpnStatus']
        $gapNote = ''
        if (-not [bool]$Population.Complete -or $unknown -gt 0) { $gapNote = ' The population was not read completely (the gaps are in the Unresolved column), so there may be more.' }
        return (New-AdfaPrivilegedRow @common @columns -Status $status -NotRun $notRun -Evidence $evidence `
                -Detail ("{0} enabled privileged user account(s) of {1} carry a service principal name.{2} Microsoft Defender for Identity recommends removing an SPN from a user account and shows that recommendation for sensitive accounts. Graded {3}: a tool default, not a Microsoft value (setting from: {4})." -f $hits.Count, $Domain, $gapNote, $status, [string]$Config['ThresholdSource']))
    }
    if (-not [bool]$Population.Complete -or $unknown -gt 0) {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: none of the privileged user accounts read in {0} is an enabled account with an SPN, but the population was not read completely ({1} gap(s)) or {2} account(s) with an SPN came back without userAccountControl. This is not a clean result." -f $Domain, @($Population.Gaps).Count, $unknown))
    }
    return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.Pass -NotRun $notRun -Evidence $evidence `
            -Detail ("None visible: none of the {0} privileged user account(s) of {1} visible to this account is an enabled account with a service principal name." -f @($Population.Records).Count, $Domain))
}

function Get-AdfaPrivDelegableVerdict {
    <#
    .SYNOPSIS
        Pure: "Privileged accounts delegable: <domain>" - enabled privileged user accounts with neither
        NOT_DELEGATED ("Account is sensitive and cannot be delegated") nor transitive membership of
        Protected Users. Not in the AdAssessment26 catalogue: a C10 addition from Learn guidance.
    .DESCRIPTION
        Population: the protected-group members of the domain and its Administrator (not every
        adminCount=1 object, whose protection may be historic). NOT_DELEGATED always counts. Protected
        Users membership counts only at domain functional level Windows Server 2012 R2 or later (Learn:
        the DC-side restrictions, delegation among them, need that level): below it the member is
        delegable and graded; with the level unread or unknown it is undecided. When Protected Users
        was not read, an account without the flag is undecided, never a finding and never a pass. An
        empty population is Not Assessed: it always holds the domain's Administrator.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$Domain, [Parameter(Mandatory)]$Population, [Parameter(Mandatory)]$ProtectedUsers, [Parameter(Mandatory)][hashtable]$Config, [AllowEmptyString()][string]$DomainSid = '')
    $catalogue = $Config['Catalogue']['Delegable']
    $common = @{ Scope = $Domain; Area = 'PrivHygiene'; Item = ("Privileged accounts delegable: {0}" -f $Domain); CatalogueId = [string]$catalogue['Id']; Severity = [string]$catalogue['Severity']; DomainSid = $DomainSid }
    $evidence = ("userAccountControl bit NOT_DELEGATED ({0}) of the protected-group members, and the transitive membership of Protected Users (RID {1})" -f [int64]$Config['Uac']['NotDelegated'], [int]$Config['ProtectedUsersRid'])
    $notRun = 'Not read: whether an account has a documented need to be delegated. Protected Users is not recommended here as the only remedy: Microsoft warns against adding highly privileged accounts before testing, and never service or computer accounts.'
    $flag = [int64]$Config['Uac']['NotDelegated']
    $enforced = $null
    $enforcedProp = $ProtectedUsers.PSObject.Properties['DelegationEnforced']
    if ($null -ne $enforcedProp -and $null -ne $enforcedProp.Value) { $enforced = [bool]$enforcedProp.Value }
    $modeText = 'the domain functional level was not read'
    $modeProp = $ProtectedUsers.PSObject.Properties['ModeText']
    if ($null -ne $modeProp -and -not [string]::IsNullOrWhiteSpace([string]$modeProp.Value)) { $modeText = [string]$modeProp.Value }
    $hits = @(); $undecided = 0; $mitigated = 0; $disabled = 0; $puUndecided = 0; $puBelow = 0
    foreach ($r in @($Population.Records)) {
        if ($null -eq $r.Enabled -or $null -eq $r.Uac) { $undecided++; continue }
        if (-not [bool]$r.Enabled) { $disabled++; continue }
        if (([int64]$r.Uac -band $flag) -ne 0) { $mitigated++; continue }
        if (-not [bool]$ProtectedUsers.Known) { $undecided++; continue }
        if ($ProtectedUsers.Dns.ContainsKey(([string]$r.Dn).ToLowerInvariant())) {
            # Learn: Protected Users blocks delegation only at domain functional level 2012 R2 or later.
            if ($null -eq $enforced) { $undecided++; $puUndecided++; continue }
            if ([bool]$enforced) { $mitigated++; continue }
            $puBelow++
        }
        $hits += $r
    }
    $gaps = @(@($Population.Gaps))
    if (-not [bool]$ProtectedUsers.Known) { $gaps += [string]$ProtectedUsers.Why }
    if ($puUndecided -gt 0) { $gaps += ("{0} account(s) without the flag are members of Protected Users, but {1}, and Microsoft documents that Protected Users blocks delegation only at domain functional level Windows Server 2012 R2 or later" -f $puUndecided, $modeText) }
    $names = Get-AdfaPrivNameList -Records $hits -Config $Config
    $columns = @{ Count = $hits.Count; UserCount = @($Population.Records).Count; UnresolvedCount = $undecided; ExcludedCount = ($mitigated + $disabled); Listed = $names.Listed; NotListed = $names.NotListed
        Principals = [string]$names.Names; PrincipalSids = [string]$names.Sids; Unresolved = ($gaps -join '; ') }
    $learn = 'Microsoft calls "Account is sensitive and cannot be delegated" a best practice for all sensitive accounts, and Defender for Identity lists privileged accounts without it'
    if ($hits.Count -gt 0) {
        $status = [string]$Config['DelegableStatus']
        $belowNote = ''
        if ($puBelow -gt 0) { $belowNote = (" {0} of them are members of Protected Users, but {1}, and Microsoft documents that Protected Users blocks delegation only at domain functional level Windows Server 2012 R2 or later." -f $puBelow, $modeText) }
        return (New-AdfaPrivilegedRow @common @columns -Status $status -NotRun $notRun -Evidence $evidence `
                -Detail ("{0} enabled privileged user account(s) of {1} can be delegated: the NOT_DELEGATED flag is not set, and no Protected Users membership blocks delegation; {2} are protected.{3} {4}. This row is a C10 addition, not an AdAssessment26 catalogue rule. Graded {5}: a tool default, not a Microsoft value (setting from: {6})." -f $hits.Count, $Domain, $mitigated, $belowNote, $learn, $status, [string]$Config['ThresholdSource']))
    }
    if (@($Population.Records).Count -eq 0) {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: no privileged user account of {0} was read, and the population always holds the domain's built-in Administrator (RID 500), so nothing was measured. This is not a clean result." -f $Domain))
    }
    if (-not [bool]$Population.Complete -or $undecided -gt 0) {
        return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not assessed: no privileged user account read in {0} was found delegable, but {1} could not be decided and {2} gap(s) remain (in the Unresolved column). This is not a clean result." -f $Domain, $undecided, @($gaps).Count))
    }
    return (New-AdfaPrivilegedRow @common @columns -Status $script:Status.Pass -NotRun $notRun -Evidence $evidence `
            -Detail ("None visible: every enabled privileged user account of {0} visible to this account ({1}) has the NOT_DELEGATED flag, or is a member of Protected Users at a domain functional level (Windows Server 2012 R2 or later) where Microsoft documents that it blocks delegation." -f $Domain, $mitigated))
}

function Get-AdfaPrivProtectedUsersVerdict {
    <#
    .SYNOPSIS
        Pure: "Protected Users members: <domain>" - the transitive member count of Protected Users
        (RID 525). Info, or Not Assessed. Not a grade: Learn warns against adding accounts blindly.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$Domain, [AllowNull()]$Entry, [Parameter(Mandatory)][hashtable]$Config, [AllowEmptyString()][string]$DomainSid = '')
    $item = ("Protected Users members: {0}" -f $Domain)
    $common = @{ Scope = $Domain; Area = 'PrivHygiene'; Item = $item; DomainSid = $DomainSid }
    if ($null -eq $Entry) { return (New-AdfaPrivilegedRow @common -Status $script:Status.NotAssessed -Evidence 'none' -Detail 'Not assessed: Protected Users was not looked up. This is a defect in the tool, not a result.') }
    $evidence = ("Get-ADObject -Server {0} -LDAPFilter '{1}'; members expanded transitively" -f $Domain, [string]$Entry.Locate.Filter)
    if ([string]$Entry.Locate.Class -eq 'NotFound') {
        return (New-AdfaPrivilegedRow @common -GroupSid ([string]$Entry.Spec.Sid) -Status $script:Status.Info -Evidence $evidence `
                -Detail ("Not present: no group with the SID of Protected Users is visible to this account in {0}. Microsoft documents that the group needs a domain controller running Windows Server 2012 R2 or later to be created." -f $Domain))
    }
    if (-not [bool]$Entry.Locate.Ok -or $null -eq $Entry.Closure) {
        return (New-AdfaPrivilegedRow @common -GroupSid ([string]$Entry.Spec.Sid) -Status $script:Status.NotAssessed -Evidence $evidence -Detail (Get-AdfaPrivLocateLead -Locate $Entry.Locate -What ("Protected Users of {0}" -f $Domain)))
    }
    $s = Get-AdfaPrivMemberSummary -Closure $Entry.Closure -Config $Config
    if ($s.Unresolved -gt 0) {
        return (New-AdfaPrivilegedRow @common -GroupSid ([string]$Entry.Spec.Sid) -Status $script:Status.NotAssessed -Evidence $evidence -UnresolvedCount $s.Unresolved -Unresolved ([string]$s.UnresolvedText) `
                -Detail ("Not assessed: {0} member reference(s) of Protected Users in {1} could not be resolved, so no count is given. This is not a clean result." -f $s.Unresolved, $Domain))
    }
    return (New-AdfaPrivilegedRow @common -GroupSid ([string]$Entry.Spec.Sid) -Status $script:Status.Info -Evidence $evidence -Count $s.Count -UserCount $s.Users -ComputerCount $s.Computers -GroupCount $s.Groups -ForeignCount $s.Foreign -UnresolvedCount 0 `
            -Listed $s.Names.Listed -NotListed $s.Names.NotListed -Principals ([string]$s.Names.Names) -PrincipalSids ([string]$s.Names.Sids) `
            -Detail ("{0} member(s) of Protected Users visible to this account in {1}: {2} user, {3} computer (Microsoft says never to add computer or service accounts), through {4} nested group(s). Inventory: no threshold is applied." -f $s.Count, $Domain, $s.Users, $s.Computers, $s.Groups))
}

function Get-AdfaPrivilegedHygiene {
    <#
    .SYNOPSIS
        Privileged Hygiene rows per scoped domain: "adminCount orphans", "Privileged accounts with SPN",
        "Privileged accounts delegable" and "Protected Users members". Pure over the run's C10 state.
    .DESCRIPTION
        DECLARED POPULATION: the domains in State.Scoped. Each gets exactly these four rows, whatever
        happened to its reads; with none scoped there is one "Privileged hygiene (no domain scoped)"
        row. An exception while one domain is handled makes its four rows Not Assessed and never ends
        the section.
    .OUTPUTS
        [pscustomobject[]] rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)]$State, [Parameter(Mandatory)][hashtable]$Config)
    $rows = @()
    $prefixes = @('adminCount orphans', 'Privileged accounts with SPN', 'Privileged accounts delegable', 'Protected Users members')
    if (@($State.Scoped).Count -eq 0) {
        $rows += New-AdfaPrivilegedRow -Area 'PrivHygiene' -Item 'Privileged hygiene (no domain scoped)' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail 'No domain was scoped for this run, so no privileged account was read. This is not a clean result.'
        return @($rows)
    }
    $heuristics = Get-AdfaPrivHeuristicsState -Forest $State.Forest -Config $Config
    foreach ($domain in @($State.Scoped)) {
        try {
            $domainState = $State.Domains[$domain]
            if ($null -eq $domainState -or [string]$domainState.Error -ne '' -or $null -eq $domainState.Raw -or -not [bool]$domainState.Raw.Ok) {
                $why = 'Not assessed: the domain was not handled. This is a defect in the tool, not a result.'
                if ($null -ne $domainState -and [string]$domainState.Error -ne '') { $why = ("Not assessed: handling {0} failed inside this tool; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$domainState.Error) }
                elseif ($null -ne $domainState -and $null -ne $domainState.Raw) { $why = ("{0} No privileged account of this domain was read. This is not a clean result." -f (Get-AdfaLapsReadFailureLead -Message ([string]$domainState.Raw.Error) -TypeName ([string]$domainState.Raw.ErrorType) -What ("the domain {0} (its distinguished name and SID)" -f $domain))) }
                foreach ($prefix in $prefixes) { $rows += New-AdfaPrivilegedRow -Scope $domain -Area 'PrivHygiene' -Item ("{0}: {1}" -f $prefix, $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why }
                continue
            }
            $sid = [string]$domainState.Raw.DomainSid
            $protected = Get-AdfaPrivProtectedSet -State $State -Domain $domain -Config $Config
            $rows += Get-AdfaPrivOrphanVerdict -Domain $domain -AdminCount $domainState.AdminCount -Protected $protected -Heuristics $heuristics -Config $Config
            $spnPopulation = Get-AdfaPrivAccountPopulation -Protected $protected -AdminCount $domainState.AdminCount -Config $Config -IncludeAdminCount
            $rows += Get-AdfaPrivSpnVerdict -Domain $domain -Population $spnPopulation -Config $Config -DomainSid $sid
            $delegablePopulation = Get-AdfaPrivAccountPopulation -Protected $protected -AdminCount $domainState.AdminCount -Config $Config
            $rows += Get-AdfaPrivDelegableVerdict -Domain $domain -Population $delegablePopulation -ProtectedUsers $protected.ProtectedUsers -Config $Config -DomainSid $sid
            $puEntry = $null
            if ($domainState.Groups.Contains('ProtectedUsers')) { $puEntry = $domainState.Groups['ProtectedUsers'] }
            $rows += Get-AdfaPrivProtectedUsersVerdict -Domain $domain -Entry $puEntry -Config $Config -DomainSid $sid
        }
        catch {
            $why = ("Not assessed: grading the privileged accounts of {0} failed inside this tool, so nothing about this domain is graded; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$_.Exception.Message)
            foreach ($prefix in $prefixes) { $rows += New-AdfaPrivilegedRow -Scope $domain -Area 'PrivHygiene' -Item ("{0}: {1}" -f $prefix, $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why }
        }
    }
    return @($rows)
}

function Get-AdfaKerberosRoastVerdict {
    <#
    .SYNOPSIS
        Pure: the two rows kept from before C10 - "Kerberoastable user accounts (SPN set)" (Warning) and
        "AS-REP roastable accounts (no pre-auth)" (Fail) - with the account names moved out of Detail
        into Principals, and a failed read worded by class.
    .OUTPUTS
        [pscustomobject[]] two rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$Domain, [AllowNull()]$Roast, [Parameter(Mandatory)][hashtable]$Config)
    $rows = @()
    $specs = @(
        @{ Item = 'Kerberoastable user accounts (SPN set)'; Ok = 'RoastOk'; Class = 'RoastClass'; Err = 'RoastError'; Type = 'RoastErrorType'; List = 'Roast'; Bad = $script:Status.Warning
            Evidence = "Get-ADUser -LDAPFilter '(&(servicePrincipalName=*)(!(objectClass=computer))(!(cn=krbtgt)))'"; What = 'the user accounts with a service principal name'; Noun = 'user account(s) with a service principal name' }
        @{ Item = 'AS-REP roastable accounts (no pre-auth)'; Ok = 'AsRepOk'; Class = 'AsRepClass'; Err = 'AsRepError'; Type = 'AsRepErrorType'; List = 'AsRep'; Bad = $script:Status.Fail
            Evidence = "Get-ADUser -LDAPFilter '(&(userAccountControl:1.2.840.113556.1.4.803:=4194304)(!(objectClass=computer)))'"; What = 'the accounts that do not require Kerberos pre-authentication'; Noun = 'account(s) that do not require Kerberos pre-authentication' }
    )
    foreach ($spec in $specs) {
        if ($null -eq $Roast) {
            $rows += New-AdfaPrivilegedRow -Scope $Domain -Area 'Kerberos' -Item $spec.Item -Status $script:Status.NotAssessed -Evidence 'none' -Detail 'Not assessed: the read was not made. This is a defect in the tool, not a result.'
            continue
        }
        if (-not [bool]$Roast.($spec.Ok)) {
            $lead = Get-AdfaPrivLocateLead -Locate ([pscustomobject]@{ Class = [string]$Roast.($spec.Class); Error = [string]$Roast.($spec.Err); ErrorType = [string]$Roast.($spec.Type) }) -What $spec.What -Search
            $rows += New-AdfaPrivilegedRow -Scope $Domain -Area 'Kerberos' -Item $spec.Item -Status $script:Status.NotAssessed -Evidence $spec.Evidence -Detail $lead
            continue
        }
        $enabled = @(@($Roast.($spec.List)) | Where-Object { $null -eq $_.Enabled -or [bool]$_.Enabled })
        $names = Get-AdfaPrivNameList -Records @($enabled | ForEach-Object { [pscustomobject]@{ Name = [string]$_.Name; Dn = ''; Sid = '' } }) -Config $Config
        $status = $script:Status.Pass
        if ($enabled.Count -gt 0) { $status = $spec.Bad }
        $rows += New-AdfaPrivilegedRow -Scope $Domain -Area 'Kerberos' -Item $spec.Item -Status $status -Evidence $spec.Evidence -Count $enabled.Count -Listed $names.Listed -NotListed $names.NotListed -Principals ([string]$names.Names) `
            -Detail ("{0} enabled {1} visible to this account; names are in the Principals column." -f $enabled.Count, $spec.Noun)
    }
    return @($rows)
}

function Get-AdfaPrivDelegationVerdict {
    <#
    .SYNOPSIS
        Pure: the four delegation rows of one domain from its one delegation search - "Unconstrained
        delegation" (ADA-OBJ-002), "Protocol transition delegation" (ADA-OBJ-003), "Constrained
        delegation" (ADA-INV-017, Info) and "Resource-based delegation" (ADA-OBJ-004).
    .DESCRIPTION
        Domain controllers are excluded from the first two by the DN of their computer account, taken
        from serverReference of each server object that holds an nTDSDSA child - never by name and never
        by primaryGroupID 516/521, which is read only to report accounts that carry it without being a
        registered DC (they are graded). Learn: a writable DC carries TRUSTED_FOR_DELEGATION and an RODC
        TRUSTED_TO_AUTH_FOR_DELEGATION by default. When the DC population was not read completely
        (Get-AdfaPrivDcPopulationState: no nTDSDSA object, a DC server object without serverReference,
        or an nTDSDSA object without its server object), those two rows are Not Assessed: no DC could
        be told apart. DCs are not excluded from constrained delegation and RBCD, which no default sets.
        DECLARED POPULATION of the search: every DC registered for this domain (its computer account DN
        under DomainDn, not a child domain's) - each carries one of the two bits by default, so the
        search must return it. When one is missing, when the domain has none registered, or when the DC
        population is unknown, no row is Pass and the Constrained count is not given; a row that found
        accounts keeps its grade and says the search may be incomplete. An object whose
        userAccountControl was not returned is undecided for the two bit rows. RBCD lists the principals
        of each listed descriptor's allow ACEs by SID in AllowedSids; a descriptor that could not be
        read is counted and marked unparsed. Targets and AllowedSids are built from the same records
        Principals names (Get-AdfaPrivNameList), never from a different selection.
    .OUTPUTS
        [pscustomobject[]] four rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$Domain, [AllowNull()]$Delegation, [AllowNull()]$Forest, [Parameter(Mandatory)][hashtable]$Config, [AllowEmptyString()][string]$DomainSid = '',
        [AllowEmptyString()][string]$DomainDn = '')
    $rows = @()
    $c = $Config['Catalogue']
    $families = @(
        @{ Key = 'Unconstrained'; Prefix = 'Unconstrained delegation'; Bit = 'TrustedForDelegation'; Status = 'UnconstrainedStatus' }
        @{ Key = 'ProtocolTransition'; Prefix = 'Protocol transition delegation'; Bit = 'TrustedToAuthForDelegation'; Status = 'ProtocolTransitionStatus' }
        @{ Key = 'Constrained'; Prefix = 'Constrained delegation'; Bit = ''; Status = '' }
        @{ Key = 'Rbcd'; Prefix = 'Resource-based delegation'; Bit = ''; Status = 'RbcdStatus' }
    )
    $filter = Get-AdfaPrivDelegationFilter -Config $Config
    $evidence = ("Get-ADObject -Server {0} -LDAPFilter '{1}'" -f $Domain, $filter)
    if ($null -eq $Delegation -or -not [bool]$Delegation.Ok) {
        $why = 'Not assessed: the delegation search was not made. This is a defect in the tool, not a result.'
        if ($null -ne $Delegation) { $why = Get-AdfaPrivLocateLead -Locate $Delegation -What ("the accounts with a delegation setting in {0}" -f $Domain) -Search }
        foreach ($f in $families) { $rows += New-AdfaPrivilegedRow -Scope $Domain -Area 'Kerberos' -Item ("{0}: {1}" -f $f.Prefix, $Domain) -Status $script:Status.NotAssessed -Evidence $evidence -CatalogueId ([string]$c[$f.Key]['Id']) -Severity ([string]$c[$f.Key]['Severity']) -DomainSid $DomainSid -Detail $why }
        return @($rows)
    }
    $dcState = Get-AdfaPrivDcPopulationState -Forest $Forest
    $dcKnown = [bool]$dcState.Known
    $dcSet = $dcState.Set
    $dcWhy = [string]$dcState.Why
    $dcPgids = @(@($Config['DcPrimaryGroupIds']) | ForEach-Object { [int64]$_ })
    $records = @($Delegation.Records | Where-Object { $null -ne $_ })
    $isDc = { param($Rec) return ($dcKnown -and $dcSet.ContainsKey(([string]$Rec.Dn).ToLowerInvariant())) }
    # Non-vacuity (a tool rule on Learn's defaults): every DC registered for this domain carries
    # TRUSTED_FOR_DELEGATION (writable) or TRUSTED_TO_AUTH_FOR_DELEGATION (RODC), so the one search,
    # which asks for either bit, must return each of them. A "none" answer is never passed without it.
    $searchGap = ''
    if (-not $dcKnown) { $searchGap = ("the domain controllers registered in the configuration partition were not read completely ({0}), so whether this search returned what it should could not be checked" -f $dcWhy) }
    elseif ($DomainDn -eq '') { $searchGap = ("the distinguished name of {0} was not given, so its registered domain controllers could not be told and this search could not be checked against them" -f $Domain) }
    else {
        $domainDcs = @(Get-AdfaPrivDomainDcList -DcState $dcState -DomainDn $DomainDn)
        $returned = @{}
        foreach ($r in $records) { $returned[([string]$r.Dn).ToLowerInvariant()] = $true }
        $missingDcs = @($domainDcs | Where-Object { -not $returned.ContainsKey([string]$_) })
        if ($domainDcs.Count -eq 0) { $searchGap = ("no domain controller registered in the configuration partition belongs to {0}, and every domain has at least one, so this search could not be checked" -f $Domain) }
        elseif ($missingDcs.Count -gt 0) { $searchGap = ("{0} of the {1} domain controller(s) registered for {2} were not returned by this search, although Microsoft documents that a writable DC carries TRUSTED_FOR_DELEGATION and an RODC TRUSTED_TO_AUTH_FOR_DELEGATION by default, so it did not return its declared population" -f $missingDcs.Count, $domainDcs.Count, $Domain) }
    }
    $pgidNotDc = @($records | Where-Object { $null -ne $_.PrimaryGroupId -and $dcPgids -contains [int64]$_.PrimaryGroupId -and -not (& $isDc $_) })
    $dcEvidence = 'DCs and RODCs excluded by the DN of their computer account (serverReference of each server object holding an nTDSDSA child under CN=Sites of the configuration partition); primaryGroupID 516/521 is not used to exclude'
    $pgidNote = ''
    if ($dcKnown -and $pgidNotDc.Count -gt 0) { $pgidNote = (" {0} account(s) here carry the primary group of domain controllers (516 or 521) but are not registered DCs; they are graded like any account." -f $pgidNotDc.Count) }
    foreach ($f in $families) {
        $item = ("{0}: {1}" -f $f.Prefix, $Domain)
        $common = @{ Scope = $Domain; Area = 'Kerberos'; Item = $item; CatalogueId = [string]$c[$f.Key]['Id']; Severity = [string]$c[$f.Key]['Severity']; DomainSid = $DomainSid }
        if ($f.Bit -ne '') {
            $bit = [int64]$Config['Uac'][$f.Bit]
            $rowEvidence = ("{0}; bit {1} ({2}); {3}" -f $evidence, $f.Bit, $bit, $dcEvidence)
            if (-not $dcKnown) {
                $rows += New-AdfaPrivilegedRow @common -Status $script:Status.NotAssessed -Evidence $rowEvidence `
                    -Detail ("Not assessed: the domain controllers registered in the configuration partition were not read ({0}), so the accounts that legitimately carry this setting could not be told apart, and none is graded. Names are never used to exclude a DC. This is not a clean result." -f $dcWhy)
                continue
            }
            $set = @($records | Where-Object { $null -ne $_.Uac -and (([int64]$_.Uac -band $bit) -ne 0) })
            $excluded = @($set | Where-Object { & $isDc $_ })
            $hits = @($set | Where-Object { -not (& $isDc $_) })
            $unknown = @($records | Where-Object { $null -eq $_.Uac })
            $names = Get-AdfaPrivNameList -Records $hits -Config $Config
            $columns = @{ Count = $hits.Count; ExcludedCount = $excluded.Count; UnresolvedCount = $unknown.Count; Listed = $names.Listed; NotListed = $names.NotListed; Principals = [string]$names.Names; PrincipalSids = [string]$names.Sids
                Targets = (@(@($names.Records) | Where-Object { @($_.DelegateTo).Count -gt 0 } | ForEach-Object { "{0}: {1}" -f [string]$_.Name, (@($_.DelegateTo) -join ', ') }) -join '; ') }
            $kindText = 'unconstrained delegation (TRUSTED_FOR_DELEGATION), which Microsoft documents as letting a service running under the account impersonate a client requesting the service'
            if ($f.Key -eq 'ProtocolTransition') { $kindText = 'protocol transition (TRUSTED_TO_AUTH_FOR_DELEGATION, "use any authentication protocol"), which Microsoft calls a security-sensitive setting that should be strictly controlled' }
            if ($hits.Count -gt 0) {
                $status = [string]$Config[$f.Status]
                $gapNote = ''
                if ($searchGap -ne '') { $gapNote = (" The search may be incomplete - {0} - so there may be more." -f $searchGap) }
                $rows += New-AdfaPrivilegedRow @common @columns -Status $status -Evidence $rowEvidence `
                    -Detail ("{0} account(s) of {1} other than its domain controllers are set for {2}; {3} DC account(s) carrying it were excluded by DN.{4}{5} Graded {6}: a tool default, not a Microsoft value (setting from: {7})." -f $hits.Count, $Domain, $kindText, $excluded.Count, $pgidNote, $gapNote, $status, [string]$Config['ThresholdSource'])
                continue
            }
            if ($unknown.Count -gt 0) {
                $rows += New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -Evidence $rowEvidence `
                    -Detail ("Not assessed: no account of {0} other than its domain controllers was found set for this, but {1} object(s) the search returned came back without userAccountControl. This is not a clean result." -f $Domain, $unknown.Count)
                continue
            }
            if ($searchGap -ne '') {
                $rows += New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -Evidence $rowEvidence `
                    -Detail ("Not assessed: no account of {0} other than its domain controllers was found set for this, but {1}. This is not a clean result." -f $Domain, $searchGap)
                continue
            }
            $rows += New-AdfaPrivilegedRow @common @columns -Status $script:Status.Pass -Evidence $rowEvidence `
                -Detail ("None visible: no account of {0} other than its domain controllers is set for {1}; {2} DC account(s) carrying it were excluded by DN.{3}" -f $Domain, $kindText, $excluded.Count, $pgidNote)
            continue
        }
        if ($f.Key -eq 'Constrained') {
            $ptBit = [int64]$Config['Uac']['TrustedToAuthForDelegation']
            $withTargets = @($records | Where-Object { @($_.DelegateTo).Count -gt 0 })
            $plain = @($withTargets | Where-Object { $null -ne $_.Uac -and (([int64]$_.Uac -band $ptBit) -eq 0) })
            $unknown = @($withTargets | Where-Object { $null -eq $_.Uac })
            $names = Get-AdfaPrivNameList -Records $plain -Config $Config
            $columns = @{ Count = $plain.Count; UnresolvedCount = $unknown.Count; Listed = $names.Listed; NotListed = $names.NotListed; Principals = [string]$names.Names; PrincipalSids = [string]$names.Sids
                Targets = (@(@($names.Records) | ForEach-Object { "{0}: {1}" -f [string]$_.Name, (@($_.DelegateTo) -join ', ') }) -join '; ') }
            if ($unknown.Count -gt 0) {
                $rows += New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -Evidence ("{0}; msDS-AllowedToDelegateTo present and bit TrustedToAuthForDelegation clear" -f $evidence) `
                    -Detail ("Not assessed: {0} account(s) of {1} with constrained delegation targets came back without userAccountControl, so Kerberos-only constrained delegation cannot be told from protocol transition for them. {2} account(s) use Kerberos-only constrained delegation. This is not a clean result." -f $unknown.Count, $Domain, $plain.Count)
                continue
            }
            if ($searchGap -ne '') {
                $columns['Count'] = $null
                $rows += New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -Evidence ("{0}; msDS-AllowedToDelegateTo present and bit TrustedToAuthForDelegation clear" -f $evidence) `
                    -Detail ("Not assessed: {0} account(s) of {1} were found with Kerberos-only constrained delegation (listed in the Principals column), but {2}, so no count is given. This is not a clean result." -f $plain.Count, $Domain, $searchGap)
                continue
            }
            $rows += New-AdfaPrivilegedRow @common @columns -Status $script:Status.Info -Evidence ("{0}; msDS-AllowedToDelegateTo present and bit TrustedToAuthForDelegation clear" -f $evidence) `
                -Detail ("{0} account(s) of {1} use Kerberos-only constrained delegation (msDS-AllowedToDelegateTo set, protocol transition not); their target services are in the Targets column. Inventory: no threshold is applied; protocol transition is graded in its own row." -f $plain.Count, $Domain)
            continue
        }
        # Resource-based constrained delegation.
        $rbcd = @($records | Where-Object { [bool]$_.HasRbcd })
        $unparsed = @($rbcd | Where-Object { $null -eq $_.Rbcd -or -not [bool]$_.Rbcd.Ok })
        $allowed = @()
        $names = Get-AdfaPrivNameList -Records $rbcd -Config $Config
        foreach ($r in @($names.Records)) {
            if ($null -eq $r.Rbcd -or -not [bool]$r.Rbcd.Ok) {
                $class = 'not returned'
                if ($null -ne $r.Rbcd) { $class = [string]$r.Rbcd.Class }
                $allowed += ("{0}: descriptor not parsed ({1})" -f [string]$r.Name, $class)
                continue
            }
            $allow = @(@($r.Rbcd.Aces) | Where-Object { [bool]$_.Allow -and [string]$_.Sid -ne '' } | ForEach-Object { [string]$_.Sid } | Select-Object -Unique)
            $deny = @(@($r.Rbcd.Aces) | Where-Object { [bool]$_.Deny -and [string]$_.Sid -ne '' } | ForEach-Object { [string]$_.Sid } | Select-Object -Unique)
            $other = @(@($r.Rbcd.Aces) | Where-Object { [string]$_.Kind -eq 'Other' }).Count
            $text = ("{0}: allowed {1}" -f [string]$r.Name, ($allow -join ', '))
            if ($deny.Count -gt 0) { $text += ("; denied {0}" -f ($deny -join ', ')) }
            if ($other -gt 0) { $text += ("; {0} ACE(s) not interpreted" -f $other) }
            $allowed += $text
        }
        $columns = @{ Count = $rbcd.Count; UnresolvedCount = $unparsed.Count; Listed = $names.Listed; NotListed = $names.NotListed; Principals = [string]$names.Names; PrincipalSids = [string]$names.Sids; AllowedSids = ($allowed -join ' | ') }
        $rowEvidence = ("{0}; msDS-AllowedToActOnBehalfOfOtherIdentity present, its descriptor read in memory" -f $evidence)
        if ($rbcd.Count -gt 0) {
            $status = [string]$Config[$f.Status]
            $unparsedNote = ''
            if ($unparsed.Count -gt 0) { $unparsedNote = (" The descriptor of {0} could not be read, so the principals allowed on them are not listed." -f $unparsed.Count) }
            if ($searchGap -ne '') { $unparsedNote += (" The search may be incomplete - {0} - so there may be more." -f $searchGap) }
            $rows += New-AdfaPrivilegedRow @common @columns -Status $status -Evidence $rowEvidence `
                -Detail ("{0} account(s) of {1} carry resource-based constrained delegation (msDS-AllowedToActOnBehalfOfOtherIdentity): the principals allowed to delegate to each are listed by SID in the AllowedSids column.{2} Microsoft documents that the KDC always allows protocol transition for resource-based constrained delegation. Graded {3}: a tool default, not a Microsoft value (setting from: {4})." -f $rbcd.Count, $Domain, $unparsedNote, $status, [string]$Config['ThresholdSource'])
            continue
        }
        if ($searchGap -ne '') {
            $rows += New-AdfaPrivilegedRow @common @columns -Status $script:Status.NotAssessed -Evidence $rowEvidence `
                -Detail ("Not assessed: no account of {0} was found with resource-based constrained delegation, but {1}. This is not a clean result." -f $Domain, $searchGap)
            continue
        }
        $rows += New-AdfaPrivilegedRow @common @columns -Status $script:Status.Pass -Evidence $rowEvidence `
            -Detail ("None visible: no account of {0} visible to this account carries resource-based constrained delegation." -f $Domain)
    }
    return @($rows)
}

function Get-AdfaKerberosExposure {
    <#
    .SYNOPSIS
        Kerberos Exposure rows per scoped domain: the Kerberoast and AS-REP rows kept from before C10,
        then "Unconstrained delegation", "Protocol transition delegation", "Constrained delegation" and
        "Resource-based delegation". Pure over the run's C10 state.
    .DESCRIPTION
        DECLARED POPULATION: the domains in State.Scoped. Each gets exactly these six rows, whatever
        happened to its reads; with none scoped there is one "Kerberos exposure (no domain scoped)" row.
        An exception while one domain is handled makes its six rows Not Assessed and never ends the
        section.
    .OUTPUTS
        [pscustomobject[]] rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)]$State, [Parameter(Mandatory)][hashtable]$Config)
    $rows = @()
    if (@($State.Scoped).Count -eq 0) {
        $rows += New-AdfaPrivilegedRow -Area 'Kerberos' -Item 'Kerberos exposure (no domain scoped)' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail 'No domain was scoped for this run, so no account was read. This is not a clean result.'
        return @($rows)
    }
    foreach ($domain in @($State.Scoped)) {
        try {
            $domainState = $State.Domains[$domain]
            if ($null -eq $domainState -or [string]$domainState.Error -ne '') {
                throw ("the domain's reads failed: {0}" -f $(if ($null -eq $domainState) { 'it was not handled' } else { [string]$domainState.Error }))
            }
            $sid = ''
            if ($null -ne $domainState.Raw) { $sid = [string]$domainState.Raw.DomainSid }
            $rows += @(Get-AdfaKerberosRoastVerdict -Domain $domain -Roast $domainState.Roast -Config $Config)
            $delegation = $domainState.Delegation
            if ($null -eq $delegation -and $null -ne $domainState.Raw -and -not [bool]$domainState.Raw.Ok) {
                $delegation = [pscustomobject]@{ Ok = $false; Class = (Get-AdfaPrivReadClass -Message ([string]$domainState.Raw.Error) -TypeName ([string]$domainState.Raw.ErrorType)); Error = [string]$domainState.Raw.Error; ErrorType = [string]$domainState.Raw.ErrorType; Filter = ''; Records = @() }
            }
            $domainDn = ''
            if ($null -ne $domainState.Raw) { $domainDn = [string]$domainState.Raw.DomainDn }
            $rows += @(Get-AdfaPrivDelegationVerdict -Domain $domain -Delegation $delegation -Forest $State.Forest -Config $Config -DomainSid $sid -DomainDn $domainDn)
        }
        catch {
            $why = ("Not assessed: grading the Kerberos exposure of {0} failed inside this tool, so nothing about this domain is graded; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$_.Exception.Message)
            foreach ($item in @('Kerberoastable user accounts (SPN set)', 'AS-REP roastable accounts (no pre-auth)')) { $rows += New-AdfaPrivilegedRow -Scope $domain -Area 'Kerberos' -Item $item -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why }
            foreach ($prefix in @('Unconstrained delegation', 'Protocol transition delegation', 'Constrained delegation', 'Resource-based delegation')) { $rows += New-AdfaPrivilegedRow -Scope $domain -Area 'Kerberos' -Item ("{0}: {1}" -f $prefix, $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why }
        }
    }
    return @($rows)
}

function Merge-AdfaPrivilegedConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in Privileged table, with validation. The Privileged
        validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: the eight grades - SchemaAdminsStatus, EnterpriseAdminsStatus,
        OrphanStatus, PrivilegedSpnStatus, DelegableStatus, UnconstrainedStatus,
        ProtocolTransitionStatus and RbcdStatus, each the text Warning or Fail -
        EnterpriseAdminsExemptRootAdministrator (a JSON true or false), NameListCap (a whole number from
        0 to 1000) and MaxExpandedObjects (a whole number from 1 to 100000):

            { "Privileged": { "SchemaAdminsStatus": "Fail", "EnterpriseAdminsExemptRootAdministrator": true } }

        What it cannot: the groups, the protected list, the bits, the filters, the property lists, the
        class lists and the range limits. Every such key is refused as unknown.

        Refused with the reason: an override that is not one object, an empty object, an unknown key,
        a key written twice, a null, a grade that is not the text Warning or Fail (a finding is never
        reported as a pass), a switch that is not a JSON boolean, a number that is not a JSON number or
        is out of range.

        Provenance follows the keys: ThresholdSource is rewritten to name the override's source for
        exactly the keys it supplied.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }
    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("Privileged config override must be a single object with named keys (for example {{ ""SchemaAdminsStatus"": ""Fail"" }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) {
        throw 'Privileged config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $statusKeys = @('SchemaAdminsStatus', 'EnterpriseAdminsStatus', 'OrphanStatus', 'PrivilegedSpnStatus', 'DelegableStatus', 'UnconstrainedStatus', 'ProtocolTransitionStatus', 'RbcdStatus')
    $ranges = @{ NameListCap = @(0, 1000, 'names listed in one row'); MaxExpandedObjects = @(1, 100000, 'objects read in one run, member reads and primary-group search results together') }
    $known = @($statusKeys + @('EnterpriseAdminsExemptRootAdministrator', 'NameListCap', 'MaxExpandedObjects'))
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("Privileged config override names an unknown key '{0}'. Known keys: {1}. The groups, the protected list, the userAccountControl bits, the filters, the property lists and the range limits cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        if ($supplied -contains $name) { throw ("Privileged config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) { throw ("Privileged config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name) }
        if ($statusKeys -contains $name) {
            $statusMatch = @()
            if ($value -is [string]) { $statusMatch = @(@('Warning', 'Fail') | Where-Object { $_ -eq $value.Trim() }) }
            if ($statusMatch.Count -eq 0) {
                throw ("Privileged config override sets '{0}' to '{1}'. It must be Warning or Fail: a finding of this section is never reported as a pass." -f $name, [string]$value)
            }
            $merged[$name] = [string]$statusMatch[0]
        }
        elseif ($name -eq 'EnterpriseAdminsExemptRootAdministrator') {
            if ($value -isnot [bool]) { throw ("Privileged config override sets 'EnterpriseAdminsExemptRootAdministrator' to a {0}. It must be a JSON true or false, written without quotes." -f $value.GetType().Name) }
            $merged[$name] = [bool]$value
        }
        else {
            $range = $ranges[$name]
            if ($value -is [array] -or $numericTypes -notcontains $value.GetType()) {
                throw ("Privileged config override sets '{0}' to a {1}. It must be a JSON number, written without quotes." -f $name, $value.GetType().Name)
            }
            $number = [double]$value
            if ([double]::IsNaN($number) -or [double]::IsInfinity($number) -or $number -ne [math]::Floor($number) -or $number -lt [double]$range[0] -or $number -gt [double]$range[1]) {
                throw ("Privileged config override sets '{0}' to {1}. It must be a whole number from {2} to {3} ({4})." -f $name, $number.ToString('0.####', $inv), $range[0], $range[1], $range[2])
            }
            $merged[$name] = [int]$number
        }
        $supplied += $name
    }
    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
    $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
    if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for the other keys" -f $text, [string]$BaseConfig['ThresholdSource']) }
    $merged['ThresholdSource'] = $text
    return $merged
}

# ---------------------------------------------------------------------------
# DC system: OS lifecycle verdict and patch-level inventory (PORT-PLAN C1)
# ---------------------------------------------------------------------------

# One reachability answer per DC and port for the whole run. Every per-DC section before C1
# probed for itself; a section that uses Test-AdfaDcPort shares the answer instead.
$script:DcPortCache = @{}
$script:DnsZoneListCache = @{}
$script:DnsDelegationCache = @{}
$script:DcNetworkCache = @{}
$script:DcReachCache = @{}

function Clear-AdfaDcPortCache {
    <#
    .SYNOPSIS
        Forgets every cached port probe. Called at the start of a run.
    #>
    [CmdletBinding()]
    param()
    $script:DcPortCache = @{}
    # PORT-PLAN C13: the zone list of each DNS server and the adapter read of each DC are shared by
    # the DNS sections in the same way, and forgotten at the start of a run with the probes.
    $script:DnsZoneListCache = @{}
    $script:DnsDelegationCache = @{}
    $script:DcNetworkCache = @{}
    # PORT-PLAN C14: the reachability class of each DC, classified once per run.
    $script:DcReachCache = @{}
}

function Test-AdfaDcPort {
    <#
    .SYNOPSIS
        Test-TcpPort with a per-run cache, so a DC is probed once per port, not once per section.
    .OUTPUTS
        [bool]
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][int]$Port,
        [int]$TimeoutMs = 1200
    )
    $key = ('{0}:{1}' -f $ComputerName.ToLowerInvariant(), $Port)
    if (-not $script:DcPortCache.ContainsKey($key)) {
        $script:DcPortCache[$key] = [bool](Test-TcpPort -ComputerName $ComputerName -Port $Port -TimeoutMs $TimeoutMs)
    }
    return [bool]$script:DcPortCache[$key]
}

function Get-AdfaConfigValue {
    <#
    .SYNOPSIS
        Pure: reads one named value from a config row that is a hashtable (built-in table) or
        an object (a row loaded from JSON). $null when the name is absent.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Entry, [Parameter(Mandatory)][string]$Name)
    if ($null -eq $Entry) { return $null }
    if ($Entry -is [System.Collections.IDictionary]) {
        if ($Entry.Contains($Name)) { return $Entry[$Name] }
        return $null
    }
    $p = $Entry.PSObject.Properties[$Name]
    if ($null -eq $p) { return $null }
    return $p.Value
}

function ConvertTo-AdfaConfigDate {
    <#
    .SYNOPSIS
        Pure: a yyyy-MM-dd config value as a date, or $null. No other format is accepted, so a
        date cannot be read differently on a host with a different culture.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    $s = ([string]$Value).Trim()
    if ($s -eq '') { return $null }
    $d = [datetime]::MinValue
    if ([datetime]::TryParseExact($s, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$d)) { return $d }
    return $null
}

function Get-AdfaOsBuild {
    <#
    .SYNOPSIS
        Pure: the build number from an operatingSystemVersion value such as "10.0 (17763)".
    .DESCRIPTION
        Learn documents the attribute only as "the operating system version string" and does not
        publish the "major.minor (build)" layout, so this is tolerant: it takes the digits inside
        the parentheses and returns $null for anything else. A caller that gets $null falls back
        to the OS name; it never assumes a build.
    .OUTPUTS
        [int] or $null
    #>
    [CmdletBinding()]
    param([AllowNull()][AllowEmptyString()][string]$OperatingSystemVersion)
    if ([string]::IsNullOrWhiteSpace($OperatingSystemVersion)) { return $null }
    $m = [regex]::Match($OperatingSystemVersion, '\((\d+)\)')
    if (-not $m.Success) { return $null }
    $b = 0
    if ([int]::TryParse($m.Groups[1].Value, [ref]$b)) { return $b }
    return $null
}

function Resolve-AdfaOsLifecycleEntry {
    <#
    .SYNOPSIS
        Pure: the lifecycle table row for a DC's operating system, or $null when none matches.
    .DESCRIPTION
        A release is identified only when the name and the build number AGREE. Where the version
        value carries no build, or the table lists none for the release (2012, 2012 R2), the
        name alone decides. Where the two point at different releases, or only one of them is
        recognised, nothing is matched and the reason is returned - a wrong release would apply
        the wrong dates, and a Pass on the wrong dates is the worst outcome this check has.

        Whether the directory's operatingSystem string is ever localised is not documented on
        Learn. If it is, a localised DC is reported Not Assessed with its raw values; it is
        never matched on the build alone.
    .OUTPUTS
        [pscustomobject] Entry ($null when not identified), Reason ('' when identified).
    #>
    [CmdletBinding()]
    param(
        [AllowNull()][AllowEmptyString()][string]$OperatingSystem,
        [AllowNull()][AllowEmptyString()][string]$OperatingSystemVersion,
        [AllowNull()][AllowEmptyCollection()]$Entries = @()
    )
    $build = Get-AdfaOsBuild -OperatingSystemVersion $OperatingSystemVersion
    $byName = $null
    if (-not [string]::IsNullOrWhiteSpace($OperatingSystem)) {
        foreach ($e in @($Entries)) {
            $pattern = [string](Get-AdfaConfigValue -Entry $e -Name 'Pattern')
            if ($pattern -ne '' -and $OperatingSystem -match $pattern) { $byName = $e; break }
        }
    }
    $byBuild = $null
    if ($null -ne $build) {
        foreach ($e in @($Entries)) {
            $eb = Get-AdfaConfigValue -Entry $e -Name 'Build'
            $parsed = 0
            if ($null -ne $eb -and [int]::TryParse([string]$eb, [ref]$parsed) -and $parsed -eq $build) { $byBuild = $e; break }
        }
    }
    $nameLabel = ''
    if ($null -ne $byName) { $nameLabel = [string](Get-AdfaConfigValue -Entry $byName -Name 'Label') }
    $buildLabel = ''
    if ($null -ne $byBuild) { $buildLabel = [string](Get-AdfaConfigValue -Entry $byBuild -Name 'Label') }

    # No build in the version value: the name is all there is.
    if ($null -eq $build) {
        if ($null -ne $byName) { return [pscustomobject]@{ Entry = $byName; Reason = '' } }
        return [pscustomobject]@{ Entry = $null; Reason = 'the name matches no release in the OS lifecycle table, and the version value carries no build number' }
    }
    # A build is present. It must not contradict the name, and the name must not contradict it.
    if ($null -ne $byBuild -and $null -ne $byName) {
        if ($buildLabel -eq $nameLabel) { return [pscustomobject]@{ Entry = $byBuild; Reason = '' } }
        return [pscustomobject]@{ Entry = $null; Reason = ("the build number is the one listed for {0} but the name is the one listed for {1}, so neither release's dates are applied" -f $buildLabel, $nameLabel) }
    }
    if ($null -ne $byBuild) {
        # Build known, name not recognised. Releases can share a build: Semi-Annual Channel
        # "Windows Server, version 1809" carries build 17763 like Windows Server 2019 and has
        # different support dates, so a build alone does not identify the release.
        return [pscustomobject]@{ Entry = $null; Reason = ("the build number is the one listed for {0} but the name is not, and a build number alone does not identify a release" -f $buildLabel) }
    }
    if ($null -ne $byName) {
        $listed = Get-AdfaConfigValue -Entry $byName -Name 'Build'
        if ($null -eq $listed -or [string]$listed -eq '') { return [pscustomobject]@{ Entry = $byName; Reason = '' } }
        return [pscustomobject]@{ Entry = $null; Reason = ("the name is the one listed for {0} but its build number is {1}, not the {2} the table lists for that release" -f $nameLabel, $build, [string]$listed) }
    }
    return [pscustomobject]@{ Entry = $null; Reason = 'neither the name nor the build number matches a release in the OS lifecycle table' }
}

function Get-AdfaOsLifecycleVerdict {
    <#
    .SYNOPSIS
        Pure: whether one DC's operating system is inside or past extended support on a date.
    .DESCRIPTION
        Fail when the date is past the release's extended support end. The text then says which
        of three situations applies - an Extended Security Updates (ESU) programme still
        running, one that has also ended, or none published - and always says that ESU
        ENROLMENT is not assessed: a published programme says nothing about whether this DC is
        in it.

        Fail-closed. An OS that could not be read, and an OS the table does not list, are both
        Not Assessed with the raw values. Neither is a Pass, and an unlisted OS is not a Fail
        either: the table has no date for it, so no date is claimed.
    .OUTPUTS
        [pscustomobject] Status, Detail, Label.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$OperatingSystem,
        [AllowNull()][AllowEmptyString()][string]$OperatingSystemVersion,
        [AllowNull()][AllowEmptyString()][string]$EnrichmentError,
        [Parameter(Mandatory)][datetime]$Today,
        [AllowNull()][AllowEmptyCollection()]$Entries = @()
    )
    if ([string]::IsNullOrWhiteSpace($OperatingSystem) -or $OperatingSystem -eq $script:Status.NotAssessed) {
        $cause = 'No cause was recorded.'
        if (-not [string]::IsNullOrWhiteSpace($EnrichmentError)) { $cause = ("Cause: {0}" -f $EnrichmentError.Trim()) }
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Label = ''
            Detail = ("The operating system could not be read from this DC's computer object, so its support status is not known. {0}" -f $cause) }
    }
    $seen = ("reported as '{0}', version '{1}'" -f $OperatingSystem, $OperatingSystemVersion)
    $resolved = Resolve-AdfaOsLifecycleEntry -OperatingSystem $OperatingSystem -OperatingSystemVersion $OperatingSystemVersion -Entries $Entries
    $entry = $resolved.Entry
    if ($null -eq $entry) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Label = ''
            Detail = ("'{0}' (version '{1}') could not be identified as a release in the OS lifecycle table: {2}. No support date is applied, and this is not a statement that it is supported. A release the table does not hold can be added with -DcSystemConfigPath." -f $OperatingSystem, $OperatingSystemVersion, [string]$resolved.Reason) }
    }
    $label = [string](Get-AdfaConfigValue -Entry $entry -Name 'Label')
    $extended = ConvertTo-AdfaConfigDate -Value (Get-AdfaConfigValue -Entry $entry -Name 'ExtendedEnd')
    if ($null -eq $extended) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; Label = $label
            Detail = ("{0} ({1}) is in the OS lifecycle table but its extended support end date is missing or not in yyyy-MM-dd form, so it cannot be judged." -f $label, $seen) }
    }
    $day = $Today.Date
    $extText = $extended.ToString('yyyy-MM-dd')
    if ($day -le $extended) {
        return [pscustomobject]@{ Status = $script:Status.Pass; Label = $label
            Detail = ("{0} ({1}) is in support: extended support ends on {2}." -f $label, $seen, $extText) }
    }
    $esuRaw = Get-AdfaConfigValue -Entry $entry -Name 'EsuEnd'
    $esu = ConvertTo-AdfaConfigDate -Value $esuRaw
    $tail = ''
    if ($null -eq $esu) {
        $tail = 'ESU end date not published for this release. Whether this DC is enrolled in any Extended Security Updates programme is not assessed.'
    }
    elseif ($day -le $esu) {
        $tail = ("An Extended Security Updates programme is published for this release until {0}. Whether this DC is enrolled in it is not assessed, and the programme does not extend the support lifecycle." -f $esu.ToString('yyyy-MM-dd'))
    }
    else {
        $tail = ("The Extended Security Updates programme for this release also ended on {0}. Whether this DC was enrolled in it is not assessed." -f $esu.ToString('yyyy-MM-dd'))
    }
    return [pscustomobject]@{ Status = $script:Status.Fail; Label = $label
        Detail = ("{0} ({1}) is past extended support, which ended on {2}. {3}" -f $label, $seen, $extText, $tail) }
}

function Get-AdfaDcOsLifecycle {
    <#
    .SYNOPSIS
        One OS lifecycle finding per domain controller, from the DC inventory.
    .DESCRIPTION
        Reads nothing: OperatingSystem and OperatingSystemVersion were already collected from the
        directory by the DomainControllers section, so this needs no rights on any DC. With no
        inventory it reports Not Assessed and names the section that supplies it.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [Parameter(Mandatory)][datetime]$Today,
        # Domains whose DC inventory call threw: objects with Domain and Error. Their DCs are in
        # no list, so without a row here the section would look complete while a whole domain
        # went unjudged.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @()
    )
    $rows = @()
    foreach ($failure in @($InventoryFailures | Where-Object { $null -ne $_ })) {
        $rows += New-Finding -Scope ([string]$failure.Domain) -Area 'DcSystem' -Item ("OS lifecycle - {0}" -f [string]$failure.Domain) -Status $script:Status.NotAssessed `
            -Detail ("The domain controllers of this domain could not be inventoried, so none of them was checked against the lifecycle table. Cause: {0}" -f [string]$failure.Error)
    }
    $dcs = @($DomainControllers | Where-Object { $null -ne $_ })
    if ($dcs.Count -eq 0) {
        $rows += New-Finding -Area 'DcSystem' -Item 'OS lifecycle' -Status $script:Status.NotAssessed `
            -Detail 'No domain controller inventory was available, so no operating system could be checked against the lifecycle table. The operating system is read by the DomainControllers section: run with -Sections DomainControllers,DcSystem (or All). This is not a clean result.'
        return @($rows)
    }
    $provenance = ("Dates per {0} (read {1})." -f [string]$Config['SourceUrl'], [string]$Config['ReadDate'])
    foreach ($dc in $dcs) {
        $values = @{}
        foreach ($n in @('HostName', 'Scope', 'OperatingSystem', 'OperatingSystemVersion', 'EnrichmentError')) {
            $p = $dc.PSObject.Properties[$n]
            $values[$n] = ''
            if ($null -ne $p -and $null -ne $p.Value) { $values[$n] = [string]$p.Value }
        }
        $name = $values['HostName']
        if ($name -eq '') { $name = '(unnamed)' }
        $v = Get-AdfaOsLifecycleVerdict -OperatingSystem $values['OperatingSystem'] -OperatingSystemVersion $values['OperatingSystemVersion'] `
            -EnrichmentError $values['EnrichmentError'] -Today $Today -Entries $Config['OsLifecycle']
        $rows += New-Finding -Scope $values['Scope'] -Area 'DcSystem' -Item ("OS lifecycle: {0}" -f $name) -Status $v.Status `
            -Detail ("{0} {1}" -f $v.Detail, $provenance)
    }
    return @($rows)
}

function ConvertTo-AdfaHotfixDate {
    <#
    .SYNOPSIS
        Pure: one Win32_QuickFixEngineering InstalledOn value as a date, or $null.
    .DESCRIPTION
        Learn types InstalledOn as a STRING, not a datetime, gives '23-10-2013' as an example,
        names no culture for it, and says it may instead be a 64-bit hexadecimal FILETIME. So
        this accepts: a value that is already a DateTime; a year-first date; a 16-digit
        hexadecimal FILETIME; and a year-last date whose day/month order is certain.

        A year-last date such as '11/10/2026' is NOT certain - it is 10 November or 11 October
        depending on the host's culture - and is returned as $null unless the caller supplies
        the order (see Get-AdfaHotfixDateOrder). A wrong date is worse than no date.
    .OUTPUTS
        [datetime] or $null
    #>
    [CmdletBinding()]
    param(
        [AllowNull()]$Value,
        [ValidateSet('Unknown', 'MonthFirst', 'DayFirst')][string]$Order = 'Unknown'
    )
    if ($null -eq $Value) { return $null }
    if ($Value -is [datetime]) { return $Value }
    $s = ([string]$Value).Trim()
    if ($s -eq '') { return $null }
    if ($s -match '^(0x)?[0-9a-fA-F]{16}$') {
        try {
            $ticks = [Convert]::ToInt64(($s -replace '^0x', ''), 16)
            if ($ticks -le 0) { return $null }
            return [datetime]::FromFileTimeUtc($ticks)
        }
        catch { return $null }
    }
    $m = [regex]::Match($s, '^(\d{1,4})[/\-.](\d{1,2})[/\-.](\d{1,4})$')
    if (-not $m.Success) { return $null }
    $a = [int]$m.Groups[1].Value
    $b = [int]$m.Groups[2].Value
    $c = [int]$m.Groups[3].Value
    $year = 0; $month = 0; $dayOfMonth = 0
    if ($m.Groups[1].Value.Length -eq 4) { $year = $a; $month = $b; $dayOfMonth = $c }
    elseif ($m.Groups[3].Value.Length -eq 4) {
        $year = $c
        if ($a -gt 12 -and $b -le 12) { $dayOfMonth = $a; $month = $b }
        elseif ($b -gt 12 -and $a -le 12) { $month = $a; $dayOfMonth = $b }
        elseif ($a -eq $b) { $month = $a; $dayOfMonth = $b }
        elseif ($Order -eq 'MonthFirst') { $month = $a; $dayOfMonth = $b }
        elseif ($Order -eq 'DayFirst') { $dayOfMonth = $a; $month = $b }
        else { return $null }
    }
    else { return $null }
    try { return (New-Object -TypeName datetime -ArgumentList $year, $month, $dayOfMonth) }
    catch { return $null }
}

function Get-AdfaHotfixDateOrder {
    <#
    .SYNOPSIS
        Pure: the day/month order of a set of year-last dates, where the set itself proves it.
    .DESCRIPTION
        Every value in one DC's update list was written by the same host, so one value with a
        day above 12 settles the order for all of them. MonthFirst or DayFirst is returned only
        when at least one value proves it and none proves the opposite; otherwise Unknown, and
        the ambiguous values stay unread.
    .OUTPUTS
        [string] Unknown | MonthFirst | DayFirst
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyCollection()][object[]]$Values = @())
    $monthFirst = 0; $dayFirst = 0
    foreach ($v in @($Values)) {
        if ($null -eq $v -or $v -is [datetime]) { continue }
        $m = [regex]::Match(([string]$v).Trim(), '^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})$')
        if (-not $m.Success) { continue }
        $a = [int]$m.Groups[1].Value
        $b = [int]$m.Groups[2].Value
        if ($a -gt 12 -and $b -le 12) { $dayFirst++ }
        elseif ($b -gt 12 -and $a -le 12) { $monthFirst++ }
    }
    if ($monthFirst -gt 0 -and $dayFirst -eq 0) { return 'MonthFirst' }
    if ($dayFirst -gt 0 -and $monthFirst -eq 0) { return 'DayFirst' }
    return 'Unknown'
}

function Get-AdfaHotfixSummary {
    <#
    .SYNOPSIS
        Pure: the latest readable install date in one DC's update list, and how much of the
        list could not be read.
    .OUTPUTS
        [pscustomobject] Total, Parsed, Unparsed, Latest ($null when none), Order, UnparsedSamples.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][AllowEmptyCollection()][object[]]$InstalledOn = @())
    $values = @()
    if ($null -ne $InstalledOn) { $values = @($InstalledOn) }
    $order = Get-AdfaHotfixDateOrder -Values $values
    $latest = $null
    $parsed = 0
    $samples = @()
    foreach ($v in $values) {
        $d = ConvertTo-AdfaHotfixDate -Value $v -Order $order
        if ($null -eq $d) {
            $text = ''
            if ($null -ne $v) { $text = ([string]$v).Trim() }
            if ($text -ne '' -and $samples -notcontains $text -and $samples.Count -lt 3) { $samples += $text }
            continue
        }
        $parsed++
        if ($null -eq $latest -or $d -gt $latest) { $latest = $d }
    }
    return [pscustomobject]@{
        Total = $values.Count; Parsed = $parsed; Unparsed = ($values.Count - $parsed)
        Latest = $latest; Order = $order; UnparsedSamples = $samples
    }
}

function Get-AdfaRemoteReadErrorClass {
    <#
    .SYNOPSIS
        Pure: AccessDenied or Error, from the text of a remote-read failure.
    .DESCRIPTION
        "Could not connect" is decided before any read, by the port probe. What is left once a
        port answered is either a refusal, which more rights would fix, or something else, which
        they would not - and the report must not send an operator after credentials for the
        second kind. Anything not recognised as a refusal is Error and is quoted, not interpreted.
    .OUTPUTS
        [string] AccessDenied | Error
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Message,
        # The CIM error code name where the exception carried one (CimException.NativeErrorCode).
        # Checked first because the message is in the UI language of the host running the
        # assessment: on a non-English host "access is denied" is not what the text says.
        [AllowNull()][AllowEmptyString()][string]$ErrorCode
    )
    if (-not [string]::IsNullOrWhiteSpace($ErrorCode) -and $ErrorCode -match '(?i)^AccessDenied$') { return 'AccessDenied' }
    if ([string]::IsNullOrWhiteSpace($Message)) { return 'Error' }
    if ($Message -match '(?i)access is denied|access denied|0x80070005|unauthorizedaccess') { return 'AccessDenied' }
    return 'Error'
}

function Get-AdfaExceptionErrorCode {
    <#
    .SYNOPSIS
        Pure: the CIM error code name (CimException.NativeErrorCode) an exception carries, on
        itself or on an exception it wraps. '' where none does.
    .DESCRIPTION
        A CIM cmdlet raises a CimException, whose NativeErrorCode names the CIM status
        (AccessDenied, InvalidNamespace, InvalidClass, NotFound ...):
          https://learn.microsoft.com/dotnet/api/microsoft.management.infrastructure.nativeerrorcode?view=powershellsdk-7.6.0
          Read: 2026-11-17.
        A CDXML cmdlet such as Get-SmbServerConfiguration does not: MEASURED on 2026-11-17 on one
        Windows 11 workstation (not a DC), under PowerShell 7 and Windows PowerShell 5.1, the
        error that reaches a catch block from a CDXML cmdlet is a
        Microsoft.PowerShell.Cmdletization.Cim.CimJobException with no NativeErrorCode of its
        own (the case measured was a cmdletization "not found" error, which wraps nothing).
        Whether a CIM failure on a remote DC arrives as an inner CimException carrying the code is
        not measured (PORT-PLAN C17a), so the wrapped exceptions are read too, up to five deep.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Exception)
    $e = $Exception
    $depth = 0
    while ($null -ne $e -and $depth -lt 5) {
        $code = $e.PSObject.Properties['NativeErrorCode']
        if ($null -ne $code -and $null -ne $code.Value -and ([string]$code.Value).Trim() -ne '') { return ([string]$code.Value).Trim() }
        $inner = $e.PSObject.Properties['InnerException']
        if ($null -eq $inner) { break }
        $e = $inner.Value
        $depth++
    }
    return ''
}

function Get-AdfaDcSystemRaw {
    <#
    .SYNOPSIS
        The one place C1 touches a DC: two read-only CIM queries in one bounded session.
    .DESCRIPTION
        Win32_OperatingSystem for LastBootUpTime, BuildNumber and Version, then
        Win32_QuickFixEngineering for InstalledOn. Nothing is written and no method is invoked.

        Never throws. A failure to open the session or read the OS class comes back as Ok =
        $false with the error text; a failure of the update query alone comes back as Ok = $true
        with HotfixOk = $false, so one half is not thrown away because the other failed.

        The timeout is the caller's. Learn notes that a value under three minutes means a
        network failure longer than the timeout is not recovered from - which is the intended
        behaviour here: a DC that does not answer is reported, not waited for.
    .OUTPUTS
        [pscustomobject] Ok, Protocol, LastBootUpTime, BuildNumber, Version, HotfixOk,
        InstalledOn (one entry per record, $null where the record carries none), Error, HotfixError.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [ValidateSet('Wsman', 'Dcom')][string]$Protocol = 'Wsman',
        [pscredential]$Credential,
        [int]$OperationTimeoutSec = 90
    )
    $out = [pscustomobject]@{
        Ok = $false; Protocol = $Protocol; LastBootUpTime = $null; BuildNumber = ''; Version = ''
        HotfixOk = $false; InstalledOn = @(); Error = ''; ErrorCode = ''; HotfixError = ''
    }
    $session = $null
    try {
        $sessionArgs = @{ ComputerName = $ComputerName; OperationTimeoutSec = [uint32]$OperationTimeoutSec; ErrorAction = 'Stop' }
        if ($Protocol -eq 'Dcom') { $sessionArgs.SessionOption = New-CimSessionOption -Protocol Dcom }
        if ($Credential) { $sessionArgs.Credential = $Credential }
        $session = New-CimSession @sessionArgs

        $os = @(Get-CimInstance -CimSession $session -ClassName 'Win32_OperatingSystem' `
                -Property 'LastBootUpTime', 'BuildNumber', 'Version' -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -ErrorAction Stop)
        if ($os.Count -eq 0 -or $null -eq $os[0]) { throw 'Win32_OperatingSystem returned no instance.' }
        foreach ($n in @('LastBootUpTime', 'BuildNumber', 'Version')) {
            $p = $os[0].PSObject.Properties[$n]
            if ($null -eq $p -or $null -eq $p.Value) { continue }
            if ($n -eq 'LastBootUpTime') { $out.LastBootUpTime = $p.Value } else { $out.$n = [string]$p.Value }
        }
        $out.Ok = $true

        try {
            $qfe = @(Get-CimInstance -CimSession $session -ClassName 'Win32_QuickFixEngineering' `
                    -Property 'HotFixID', 'InstalledOn' -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -ErrorAction Stop)
            $dates = New-Object System.Collections.ArrayList
            foreach ($q in $qfe) {
                if ($null -eq $q) { continue }
                # The RAW value, not the InstalledOn member. Windows PowerShell 5.1 ships type
                # data for this class that replaces InstalledOn with a script property doing
                # [DateTime]::Parse: it guesses month-first for '11/10/2026', and returns nothing
                # at all for a day-first date or a hexadecimal FILETIME. Measured on a real
                # Get-CimInstance result: the member is a DateTime, the raw property a String.
                # CimInstanceProperties is the unadapted store; the member is the fallback for
                # an object that has no such store.
                $value = $null
                $store = $q.PSObject.Properties['CimInstanceProperties']
                $rawProp = $null
                if ($null -ne $store -and $null -ne $store.Value) { $rawProp = $store.Value['InstalledOn'] }
                if ($null -ne $rawProp) { $value = $rawProp.Value }
                else {
                    $p = $q.PSObject.Properties['InstalledOn']
                    if ($null -ne $p) { $value = $p.Value }
                }
                [void]$dates.Add($value)
            }
            $out.InstalledOn = $dates.ToArray()
            $out.HotfixOk = $true
        }
        catch { $out.HotfixError = $_.Exception.Message }
    }
    catch {
        $out.Error = $_.Exception.Message
        $codeProp = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $out.ErrorCode = [string]$codeProp.Value }
    }
    finally {
        if ($null -ne $session) {
            # -WhatIf and -Confirm forced off: under a WhatIf preference in the caller's session
            # Remove-CimSession is not run, and the session opened above would stay open until
            # the process ends (found by the review of PORT-PLAN C2; see Get-AdfaDcDiskRaw).
            try { Remove-CimSession -CimSession $session -WhatIf:$false -Confirm:$false -ErrorAction SilentlyContinue } catch { }
        }
    }
    return $out
}

function Get-AdfaDcPatchLevel {
    <#
    .SYNOPSIS
        Per-DC patch-level inventory: OS build, uptime, and the latest update install date.
    .DESCRIPTION
        Inventory, not a verdict: every row is Info or Not Assessed, never Pass. Microsoft
        publishes no maximum uptime and no maximum age of the last update for a domain
        controller, so none is applied.

        A DC is probed once per port (shared cache). WinRM is tried first and DCOM second where
        the RPC endpoint mapper answers; a refusal is not retried over the other transport,
        because the same account would be refused again. Three outcomes are kept apart in the
        row: unreachable (no port answered, no read attempted), access denied, and any other
        read failure, quoted as the DC reported it.

        Needs local Administrators rights on each DC. Without them every DC comes back
        Not Assessed with "Access denied", while the OS lifecycle rows, which read only the
        directory, are unaffected.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # DC rows (HostName, Scope) or plain host names (PORT-PLAN C2e).
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [int]$OperationTimeoutSec = 90,
        [datetime]$Now = (Get-Date),
        # Domains whose DC enumeration threw (Domain, Error), and the domains of the run.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    $rows = @(Get-AdfaDcPopulationRow -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Area 'DcSystem' `
            -Label 'Patch level' -NothingRead 'No build, uptime or update date of its DCs was read.')
    if ($targets.Count -eq 0) {
        return @(@($rows) + @(New-Finding -Area 'DcSystem' -Item 'Patch level' -Status $script:Status.NotAssessed `
                    -Detail 'No domain controllers were enumerated, so no build, uptime or update date could be read. This is not a clean result.'))
    }
    # The CIM session always uses the default ports (PORT-PLAN C3g: a file cannot set them).
    $wsmanPort = [int]$Config['WsmanPort']
    $rpcPort = [int]$Config['RpcPort']
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item 'Patch level: (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and no build, uptime or update date was read.'
            continue
        }
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @($wsmanPort, $rpcPort) -TimeoutMs $PortTimeoutMs
        $wsman = [bool]$gate.Open[$wsmanPort]
        $rpc = [bool]$gate.Open[$rpcPort]
        if ($gate.Cause) {
            $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item ("Patch level: {0}" -f $dc) -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'no read was attempted')
            continue
        }
        if (-not $wsman -and -not $rpc) {
            $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item ("Patch level: {0}" -f $dc) -Status $script:Status.NotAssessed `
                -Detail ("Unreachable: neither WinRM ({0}) nor RPC ({1}) answered within {2} ms, so no read was attempted." -f $wsmanPort, $rpcPort, $PortTimeoutMs)
            continue
        }
        $protocols = @()
        if ($wsman) { $protocols += 'Wsman' }
        if ($rpc) { $protocols += 'Dcom' }
        $raw = $null
        $attempts = @()
        $denied = $false
        foreach ($protocol in $protocols) {
            $readArgs = @{ ComputerName = $dc; Protocol = $protocol; OperationTimeoutSec = $OperationTimeoutSec }
            if ($Credential) { $readArgs.Credential = $Credential }
            $raw = Get-AdfaDcSystemRaw @readArgs
            if ($null -ne $raw -and $raw.Ok) { break }
            $message = ''
            $code = ''
            if ($null -ne $raw) {
                $message = [string]$raw.Error
                $codeProp = $raw.PSObject.Properties['ErrorCode']
                if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $code = [string]$codeProp.Value }
            }
            $attempts += ("{0}: {1}" -f $protocol, $message)
            if ((Get-AdfaRemoteReadErrorClass -Message $message -ErrorCode $code) -eq 'AccessDenied') { $denied = $true; break }
        }
        if ($null -eq $raw -or -not $raw.Ok) {
            $lead = 'Read failed: a port answered, but system information could not be read. If the text below is a refusal in another language, local Administrators rights on the DC are what is missing.'
            if ($denied) { $lead = 'Access denied: the account running the assessment could not read system information from this DC. Local Administrators rights on the DC are needed for this read.' }
            $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item ("Patch level: {0}" -f $dc) -Status $script:Status.NotAssessed `
                -Detail ("{0} Reported by the DC - {1}" -f $lead, ($attempts -join ' | '))
            continue
        }

        # ---- OS build and uptime ----
        $boot = 'Last boot time was not returned.'
        if ($null -ne $raw.LastBootUpTime -and $raw.LastBootUpTime -is [datetime]) {
            $span = $Now - [datetime]$raw.LastBootUpTime
            if ($span.TotalSeconds -lt 0) {
                $boot = ("Last boot {0:yyyy-MM-dd HH:mm} is later than the clock of the host running the assessment, so uptime is not computed." -f [datetime]$raw.LastBootUpTime)
            }
            else {
                $boot = ("Last boot {0:yyyy-MM-dd HH:mm}; up {1} day(s), measured against the clock of the host running the assessment." -f [datetime]$raw.LastBootUpTime, [int][math]::Floor($span.TotalDays))
            }
        }
        $build = 'Build number was not returned.'
        $hasBuild = (-not [string]::IsNullOrWhiteSpace([string]$raw.BuildNumber))
        if ($hasBuild) { $build = ("Build {0} (version {1})." -f [string]$raw.BuildNumber, [string]$raw.Version) }
        # The class answered but gave neither value: nothing was measured, so it is not Info.
        $osStatus = $script:Status.Info
        if (-not $hasBuild -and -not ($raw.LastBootUpTime -is [datetime])) { $osStatus = $script:Status.NotAssessed }
        $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item ("OS build and uptime: {0}" -f $dc) -Status $osStatus `
            -Detail ("{0} {1} The update revision within the build is not part of this read. Read over {2}." -f $build, $boot, [string]$raw.Protocol)

        # ---- Latest update install date ----
        $hfItem = ("Last update installed: {0}" -f $dc)
        if (-not $raw.HotfixOk) {
            $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item $hfItem -Status $script:Status.NotAssessed `
                -Detail ("The update list could not be read: {0}" -f [string]$raw.HotfixError)
            continue
        }
        $summary = Get-AdfaHotfixSummary -InstalledOn @($raw.InstalledOn)
        $cbs = 'Win32_QuickFixEngineering lists only updates supplied by Component Based Servicing, so this is the latest of those and not necessarily the latest update of any kind.'
        if ($summary.Total -eq 0) {
            $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item $hfItem -Status $script:Status.NotAssessed `
                -Detail '0 records were returned by Win32_QuickFixEngineering, so no install date is known. This is not a statement that no update is installed.'
        }
        elseif ($summary.Parsed -eq 0) {
            $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item $hfItem -Status $script:Status.NotAssessed `
                -Detail ("{0} record(s) were returned, but none carries an install date that can be read without guessing the day/month order (examples: {1})." -f $summary.Total, (@($summary.UnparsedSamples) -join ', '))
        }
        else {
            $caveat = ''
            if ($summary.Unparsed -gt 0) { $caveat = (" {0} record(s) had no date or one that could not be read without guessing, and any of them may be newer." -f $summary.Unparsed) }
            $rows += New-Finding -Scope $scope -Area 'DcSystem' -Item $hfItem -Status $script:Status.Info `
                -Detail ("Latest update install date {0:yyyy-MM-dd}, from {1} of {2} record(s).{3} {4}" -f $summary.Latest, $summary.Parsed, $summary.Total, $caveat, $cbs)
        }
    }
    return @($rows)
}

function Merge-AdfaDcSystemConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in DC system table, with validation.
    .DESCRIPTION
        Same rules as Merge-AdfaExchangeSeConfig: only the keys the override names are replaced,
        and provenance is rewritten to the override's source so a finding does not cite Microsoft
        Learn for dates that came from a file.

        An override that replaces OsLifecycle replaces the whole table. Every row is checked,
        and a row this tool could not use is refused with the reason: an empty table, a row with
        no Label, an ExtendedEnd or EsuEnd that is not yyyy-MM-dd, a row with neither a Build nor
        a Pattern (it could match nothing), or a Pattern that is not a valid regular expression.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    # The override must be ONE object with named keys. A JSON array, string or number also
    # reaches this point as a .NET object, and its own properties (Length, Count, Rank ...)
    # would otherwise be merged as if they were config keys while the real table went
    # untouched - the built-in dates judged, and cited to the operator's file.
    $isTable = ($Override -is [hashtable])
    $isObject = ($Override -is [System.Management.Automation.PSCustomObject])
    if (-not $isTable -and -not $isObject) {
        throw ("DC system config override must be a single object with named keys (for example {{ ""OsLifecycle"": [ ... ] }}), not a {0}." -f $Override.GetType().Name)
    }
    $names = @()
    if ($isTable) { $names = @($Override.Keys) }
    else { $names = @($Override.PSObject.Properties | ForEach-Object { $_.Name }) }
    if ($names.Count -eq 0) {
        throw 'DC system config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    # Only keys this tool reads. A misspelt key ("OsLifecycles") would otherwise be accepted,
    # ignored, and leave the operator believing their table was applied.
    $known = @('OsLifecycle')
    $replacedTable = $false
    foreach ($k in $names) {
        # PORT-PLAN C3g: the two port keys are refused whatever they hold, with their own reason, as
        # DcHardening refuses them: a port set here was probed, and the CIM session still went to the
        # default one. New-CimSession -Port needs a WinRM listener on that port, which only a change
        # on the DC creates, and DCOM has no port option (Learn, read 2026-11-17).
        if (@('WsmanPort', 'RpcPort') -contains [string]$k) {
            throw ("DC system config override names '{0}'. The ports of this section cannot be set from a file: its CIM session is always opened on the default WinRM port ({1}), or through the RPC endpoint mapper ({2}) for DCOM, so a different port here would change what is probed and not what is connected to. Remove the key." -f [string]$k, [int]$BaseConfig['WsmanPort'], [int]$BaseConfig['RpcPort'])
        }
        if ($known -notcontains [string]$k) {
            throw ("DC system config override names an unknown key '{0}'. Known keys: {1}." -f [string]$k, ($known -join ', '))
        }
        # Read inline, not through Get-AdfaConfigValue: a function returning an empty array
        # hands back $null, which would turn "an empty table" into "key not supplied" and let
        # the empty-table check below pass silently.
        $value = $null
        if ($isTable) { $value = $Override[$k] }
        else { $value = $Override.PSObject.Properties[$k].Value }
        if ($null -eq $value) {
            throw ("DC system config override sets '{0}' to null. Remove the key to keep the built-in value." -f [string]$k)
        }
        if ($k -eq 'OsLifecycle') {
            if (@($value).Count -eq 0) {
                throw "DC system config override sets 'OsLifecycle' to an empty list. An empty table would leave every DC unjudged - remove the key to keep the built-in table."
            }
            $replacedTable = $true
        }
        $merged[$k] = $value
    }

    $index = 0
    foreach ($row in @($merged['OsLifecycle'])) {
        $index++
        $label = [string](Get-AdfaConfigValue -Entry $row -Name 'Label')
        if ([string]::IsNullOrWhiteSpace($label)) { throw ("DC system config: OsLifecycle row {0} has no Label." -f $index) }
        if ($null -eq (ConvertTo-AdfaConfigDate -Value (Get-AdfaConfigValue -Entry $row -Name 'ExtendedEnd'))) {
            throw ("DC system config: OsLifecycle row '{0}' has an ExtendedEnd that is missing or not in yyyy-MM-dd form." -f $label)
        }
        $esuRaw = Get-AdfaConfigValue -Entry $row -Name 'EsuEnd'
        if ($null -ne $esuRaw -and ([string]$esuRaw).Trim() -ne '' -and $null -eq (ConvertTo-AdfaConfigDate -Value $esuRaw)) {
            throw ("DC system config: OsLifecycle row '{0}' has an EsuEnd that is not in yyyy-MM-dd form. Use null where no ESU end date is published." -f $label)
        }
        $buildRaw = Get-AdfaConfigValue -Entry $row -Name 'Build'
        $pattern = [string](Get-AdfaConfigValue -Entry $row -Name 'Pattern')
        $buildParsed = 0
        $hasBuild = ($null -ne $buildRaw -and [int]::TryParse([string]$buildRaw, [ref]$buildParsed))
        if (-not $hasBuild -and [string]::IsNullOrWhiteSpace($pattern)) {
            throw ("DC system config: OsLifecycle row '{0}' has neither a Build nor a Pattern, so it could never match a domain controller." -f $label)
        }
        if (-not [string]::IsNullOrWhiteSpace($pattern)) {
            try { [void][regex]::new($pattern) }
            catch { throw ("DC system config: OsLifecycle row '{0}' has a Pattern that is not a valid regular expression: {1}" -f $label, $_.Exception.Message) }
        }
    }
    # Provenance follows the DATES. A file that changes only a port leaves the built-in
    # Microsoft dates in force, and a finding must go on citing Microsoft for them.
    if ($replacedTable -and -not [string]::IsNullOrWhiteSpace($OverrideSource)) {
        $merged['SourceUrl'] = $OverrideSource
        $merged['ReadDate'] = (Get-Date).ToString('yyyy-MM-dd')
    }
    return $merged
}

function Import-AdfaDcSystemConfig {
    <#
    .SYNOPSIS
        Loads a DC system override from JSON and merges it over the built-in table.
    .DESCRIPTION
        A missing, empty or malformed file throws: judging DCs against the built-in dates while
        the operator believes their own are in force is worse than stopping.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [Parameter(Mandatory)][string]$Path
    )
    if (-not (Test-Path -LiteralPath $Path)) { throw ("DC system config not found: {0}" -f $Path) }
    $raw = Get-Content -LiteralPath $Path -Raw -ErrorAction Stop
    if ([string]::IsNullOrWhiteSpace($raw)) { throw ("DC system config is empty: {0}" -f $Path) }
    $obj = $null
    try { $obj = $raw | ConvertFrom-Json -ErrorAction Stop }
    catch { throw ("DC system config is not valid JSON ({0}): {1}" -f $Path, $_.Exception.Message) }
    # The JSON literal null parses without error and would merge as "no override". A file that
    # was named must change something or stop the run.
    # (PowerShell 7 also arrives here for an empty top-level array, which it unrolls to nothing.)
    if ($null -eq $obj) { throw ("DC system config holds JSON null or an empty array, not an object: {0}" -f $Path) }
    try { return (Merge-AdfaDcSystemConfig -BaseConfig $BaseConfig -Override $obj -OverrideSource $Path) }
    catch { throw ("{0} (file: {1})" -f $_.Exception.Message, $Path) }
}

# ---------------------------------------------------------------------------
# DC disk space: NTDS database, NTDS log and SYSVOL volumes (PORT-PLAN C2)
# ---------------------------------------------------------------------------

function ConvertTo-AdfaByteCount {
    <#
    .SYNOPSIS
        Pure: a CIM byte count as a [double], or $null when it is not a number.
    .DESCRIPTION
        Win32_Volume types Capacity and FreeSpace as uint64. They reach this function as UInt64
        from a live session, and as Int64, Double or a string once an object has been
        serialised, so every shape goes through one invariant-culture parse. A Boolean is not a
        number here: $true would otherwise be read as one byte.
    .OUTPUTS
        [double] or $null
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value -or $Value -is [bool]) { return $null }
    $text = ([string]$Value).Trim()
    if ($text -eq '') { return $null }
    $d = [double]0
    if (-not [double]::TryParse($text, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d)) { return $null }
    if ([double]::IsNaN($d) -or [double]::IsInfinity($d)) { return $null }
    return $d
}

function ConvertTo-AdfaFixedText {
    <#
    .SYNOPSIS
        Pure: a number as text with a fixed number of decimals - truncated, culture-invariant.
    .DESCRIPTION
        Truncated and not rounded, so the figure printed beside a "below 10 %" verdict never
        reads "10.00": a value one byte short of a threshold prints below it, however close.
        Invariant, so one run does not print 9,98 on one host and 9.98 on another.

        How. The value is written with 17 significant digits (enough to tell any two doubles
        apart), read back as a decimal, and cut off there. Decimal arithmetic is exact at this
        size, so nothing is added to absorb binary error - an earlier version added 0.0000001
        before taking the floor, which printed 9.99999999906868 as "10.00". Multiplying the
        double itself by 100 is not used either: 9.99 * 100 is 998.9999999999999 in binary
        and would print as "9.98".

        A value too large for a decimal (beyond about 7.9E+28) or not a number falls back to
        the floor of the double. Values are expected to be zero or more.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][double]$Value, [ValidateRange(0, 6)][int]$Decimals = 2)
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $format = ('F{0}' -f $Decimals)
    $exact = [decimal]0
    if ([decimal]::TryParse($Value.ToString('G17', $inv), [System.Globalization.NumberStyles]::Float, $inv, [ref]$exact)) {
        try {
            $unit = [decimal]1
            for ($i = 0; $i -lt $Decimals; $i++) { $unit = $unit * 10 }
            return ([decimal]::Truncate($exact * $unit) / $unit).ToString($format, $inv)
        }
        catch [System.OverflowException] { $exact = [decimal]0 }
    }
    $scale = [math]::Pow(10, $Decimals)
    return ([math]::Floor($Value * $scale) / $scale).ToString($format, $inv)
}

function Get-AdfaDiskSpaceVerdict {
    <#
    .SYNOPSIS
        Pure: Pass, Warning, Fail or Not Assessed for one volume, from its capacity and free
        bytes and four thresholds.
    .DESCRIPTION
        Two tests are applied and the worse result is reported: free space as a percentage of
        the volume, and free space in GB against an absolute floor (1 GB = 1024^3 bytes). The
        floor exists because a percentage alone misleads on a small volume: 25 % of an 8 GB
        volume is 2 GB. A threshold of 0 is never crossed, which is how a floor is switched off.

        "Below" is strict: exactly 10 % is not below 10 %.

        NONE of the four thresholds is a Microsoft value. Microsoft publishes no percentage or
        absolute free-space threshold for the volumes that hold the directory database, its
        logs or SYSVOL; the caller's text says so (see $script:Config.DcDisk).

        Fail-closed. A capacity or free-space value that is missing, not a number, zero,
        negative or inconsistent is Not Assessed with the values as returned - Win32_Volume
        returns unformatted and offline volumes too, and those carry no figures. It is never a
        Pass and never reported as 0 %.
    .OUTPUTS
        [pscustomobject] Status, PercentFree, FreeGB, CapacityGB ($null when Not Assessed),
        Trigger (None | Percent | Floor | Both - what produced the reported status), Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$CapacityBytes,
        [AllowNull()]$FreeBytes,
        [Parameter(Mandatory)][double]$WarnBelowPercent,
        [Parameter(Mandatory)][double]$FailBelowPercent,
        [double]$WarnBelowFreeGB = 0,
        [double]$FailBelowFreeGB = 0
    )
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $capacity = ConvertTo-AdfaByteCount -Value $CapacityBytes
    $free = ConvertTo-AdfaByteCount -Value $FreeBytes
    $reason = ''
    if ($null -eq $CapacityBytes) { $reason = 'the volume returned no capacity' }
    elseif ($null -eq $capacity) { $reason = 'the capacity is not a number' }
    elseif ($capacity -eq 0) { $reason = 'the capacity is zero' }
    elseif ($capacity -lt 0) { $reason = 'the capacity is negative' }
    elseif ($null -eq $FreeBytes) { $reason = 'the volume returned no free space value' }
    elseif ($null -eq $free) { $reason = 'the free space is not a number' }
    elseif ($free -lt 0) { $reason = 'the free space is negative' }
    elseif ($free -gt $capacity) { $reason = 'the free space is larger than the capacity' }
    if ($reason -ne '') {
        $capacityText = 'not returned'
        if ($null -ne $CapacityBytes) { $capacityText = ("'{0}'" -f [string]$CapacityBytes) }
        $freeText = 'not returned'
        if ($null -ne $FreeBytes) { $freeText = ("'{0}'" -f [string]$FreeBytes) }
        return [pscustomobject]@{
            Status = $script:Status.NotAssessed; PercentFree = $null; FreeGB = $null; CapacityGB = $null; Trigger = 'None'
            Detail = ("Free space could not be judged: {0}. Returned values: Capacity {1}, FreeSpace {2}." -f $reason, $capacityText, $freeText)
        }
    }

    $bytesPerGb = [double]1073741824
    $percent = ($free / $capacity) * 100
    $freeGb = $free / $bytesPerGb
    $capacityGb = $capacity / $bytesPerGb

    $status = $script:Status.Pass
    $level = ''
    $byPercent = $false
    $byFloor = $false
    $percentLimit = [double]0
    $floorLimit = [double]0
    if (($percent -lt $FailBelowPercent) -or ($freeGb -lt $FailBelowFreeGB)) {
        $status = $script:Status.Fail
        $level = 'Fail'
        $byPercent = ($percent -lt $FailBelowPercent)
        $byFloor = ($freeGb -lt $FailBelowFreeGB)
        $percentLimit = $FailBelowPercent
        $floorLimit = $FailBelowFreeGB
    }
    elseif (($percent -lt $WarnBelowPercent) -or ($freeGb -lt $WarnBelowFreeGB)) {
        $status = $script:Status.Warning
        $level = 'Warning'
        $byPercent = ($percent -lt $WarnBelowPercent)
        $byFloor = ($freeGb -lt $WarnBelowFreeGB)
        $percentLimit = $WarnBelowPercent
        $floorLimit = $WarnBelowFreeGB
    }
    $trigger = 'None'
    if ($byPercent -and $byFloor) { $trigger = 'Both' }
    elseif ($byPercent) { $trigger = 'Percent' }
    elseif ($byFloor) { $trigger = 'Floor' }

    $detail = ("{0} % free: {1} GB free of {2} GB." -f (ConvertTo-AdfaFixedText -Value $percent), (ConvertTo-AdfaFixedText -Value $freeGb), (ConvertTo-AdfaFixedText -Value $capacityGb))
    $percentText = $percentLimit.ToString('0.##', $inv)
    $floorText = $floorLimit.ToString('0.##', $inv)
    if ($trigger -eq 'Both') { $detail = ("{0} Below the {1} threshold of {2} % free and the {1} floor of {3} GB free." -f $detail, $level, $percentText, $floorText) }
    elseif ($trigger -eq 'Percent') { $detail = ("{0} Below the {1} threshold of {2} % free." -f $detail, $level, $percentText) }
    elseif ($trigger -eq 'Floor') { $detail = ("{0} Below the {1} floor of {2} GB free." -f $detail, $level, $floorText) }

    return [pscustomobject]@{
        Status = $status; PercentFree = $percent; FreeGB = $freeGb; CapacityGB = $capacityGb; Trigger = $trigger; Detail = $detail
    }
}

function Resolve-AdfaVolumeForPath {
    <#
    .SYNOPSIS
        Pure: the volume a path is on - the one whose mount path is the longest prefix of it.
    .DESCRIPTION
        Longest prefix is the Win32 rule for mapping a path to its volume ("returns a full path
        whose prefix is the longest prefix that represents a volume"):
          https://learn.microsoft.com/windows/win32/api/fileapi/nf-fileapi-getvolumepathnamew
          Read: 2026-11-13.
        It matters because the database, the logs or SYSVOL can sit under a mounted folder, in
        which case the drive letter alone names the wrong volume.

        MEASURED, NOT PUBLISHED: this relies on Win32_Volume.Name holding the volume's mount
        path (C:\ or D:\Mount\NTDS\). Learn describes Name only as "Label by which the object is
        known", so the first run against a real DC (PORT-PLAN C17) has to confirm it. Until
        then the function fails closed: a path under no returned mount path resolves to nothing,
        with the candidate names listed, and is never matched to a "nearest" volume.

        Only local disks (DriveType 3) with a mount path are candidates. A volume whose Name is
        a volume GUID path (\\?\Volume{...}\) has no mount path and cannot hold a path read
        from the registry. Comparison ignores case and the direction of the slashes; a trailing
        backslash is added to both sides so D:\Mount\NTDSX is not taken to be under D:\Mount\NTDS.
    .OUTPUTS
        [pscustomobject] Resolved, Volume ($null when not resolved), Reason ('' when resolved).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Path,
        [AllowNull()][AllowEmptyCollection()]$Volumes = @()
    )
    $out = [pscustomobject]@{ Resolved = $false; Volume = $null; Reason = '' }
    if ([string]::IsNullOrWhiteSpace($Path)) { $out.Reason = 'the path is empty'; return $out }
    $target = $Path.Trim().Replace('/', '\')
    if (-not $target.EndsWith('\')) { $target = $target + '\' }

    $candidates = @()
    foreach ($v in @($Volumes)) {
        if ($null -eq $v) { continue }
        $name = [string](Get-AdfaConfigValue -Entry $v -Name 'Name')
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $type = Get-AdfaConfigValue -Entry $v -Name 'DriveType'
        $typeNumber = 0
        if ($null -eq $type -or -not [int]::TryParse([string]$type, [ref]$typeNumber) -or $typeNumber -ne 3) { continue }
        $mount = $name.Trim().Replace('/', '\')
        if ($mount.StartsWith('\\?\')) { continue }
        if (-not $mount.EndsWith('\')) { $mount = $mount + '\' }
        $candidates += [pscustomobject]@{ Mount = $mount; Volume = $v }
    }
    if ($candidates.Count -eq 0) {
        $out.Reason = 'no local-disk volume (DriveType 3) with a mount path was returned by the DC'
        return $out
    }
    $best = $null
    foreach ($c in $candidates) {
        if (-not $target.StartsWith([string]$c.Mount, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        if ($null -eq $best -or ([string]$c.Mount).Length -gt ([string]$best.Mount).Length) { $best = $c }
    }
    if ($null -eq $best) {
        $out.Reason = ("it is under none of the local-disk volumes the DC returned ({0})" -f (@($candidates | ForEach-Object { [string]$_.Mount }) -join ', '))
        return $out
    }
    $out.Resolved = $true
    $out.Volume = $best.Volume
    return $out
}

function Get-AdfaDcDiskThresholdText {
    <#
    .SYNOPSIS
        Pure: the thresholds in force and where each came from, as one sentence for a finding.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][hashtable]$Config)
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $parts = @()
    foreach ($level in @('Warn', 'Fail')) {
        $label = 'Warning'
        if ($level -eq 'Fail') { $label = 'Fail' }
        $percent = [double]$Config[("{0}BelowPercent" -f $level)]
        $floor = [double]$Config[("{0}BelowFreeGB" -f $level)]
        $bits = @()
        if ($percent -gt 0) { $bits += ("below {0} % free" -f $percent.ToString('0.##', $inv)) }
        if ($floor -gt 0) { $bits += ("below {0} GB free" -f $floor.ToString('0.##', $inv)) }
        if ($bits.Count -eq 0) { $parts += ("no {0} threshold" -f $label) }
        else { $parts += ("{0} {1}" -f $label, ($bits -join ' or ')) }
    }
    return ("Thresholds: {0}. Threshold source: {1}." -f ($parts -join '; '), [string]$Config['ThresholdSource'])
}

function Get-AdfaStdRegReturnClass {
    <#
    .SYNOPSIS
        Pure: what one StdRegProv Get* call's outcome means, as a class. Shared by every section
        that reads the registry through the provider (DcDisk, DcHardening).
    .DESCRIPTION
        One place decides what a return code is read as, so two sections cannot read the same
        code two ways. The wording a row gives the operator stays with the section.

          Success       the provider returned 0.
          ValueNotSet   it returned 1. MEASURED, NOT PUBLISHED: see Resolve-AdfaDcDiskPathRead for
                        what Microsoft publishes and what was measured for the two string
                        methods, and Get-AdfaStdRegDwordValue for GetDWORDValue.
          KeyAbsent     it returned 2. Measured, as above.
          AccessDenied  it returned 5 (WinError.h ERROR_ACCESS_DENIED) or 2147749891 (0x80041003,
                        WbemErrorEnum wbemErrAccessDenied), or the call threw a refusal.
          TypeMismatch  it returned 2147749893 (0x80041005, wbemErrTypeMismatch): the value
                        exists and is not of the type the method reads.
          ReadFailed    any other nonzero code, or the call threw anything else. Quoted by the
                        caller, never interpreted - and never read as "not set".
          NoReturnCode  nothing usable came back as a return code.

        Threw tells a call that raised from one that returned; Code is the number, or $null.
    .OUTPUTS
        [pscustomobject] Class, Code ([int64] or $null), Threw.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$ReturnValue,
        [AllowNull()][AllowEmptyString()][string]$ErrorText = '',
        [AllowNull()][AllowEmptyString()][string]$ErrorCode = ''
    )
    $out = [pscustomobject]@{ Class = 'NoReturnCode'; Code = $null; Threw = $false }
    if (-not [string]::IsNullOrEmpty($ErrorText)) {
        $out.Threw = $true
        $out.Class = 'ReadFailed'
        if ((Get-AdfaRemoteReadErrorClass -Message $ErrorText -ErrorCode $ErrorCode) -eq 'AccessDenied') { $out.Class = 'AccessDenied' }
        return $out
    }
    $number = [int64]0
    if ($null -eq $ReturnValue -or -not [int64]::TryParse([string]$ReturnValue, [ref]$number)) { return $out }
    $out.Code = $number
    if ($number -eq 0) { $out.Class = 'Success' }
    elseif ($number -eq 5 -or $number -eq 2147749891) { $out.Class = 'AccessDenied' }
    elseif ($number -eq 1) { $out.Class = 'ValueNotSet' }
    elseif ($number -eq 2) { $out.Class = 'KeyAbsent' }
    elseif ($number -eq 2147749893) { $out.Class = 'TypeMismatch' }
    else { $out.Class = 'ReadFailed' }
    return $out
}

function Resolve-AdfaDcDiskPathRead {
    <#
    .SYNOPSIS
        Pure: whether one registry read produced a usable path, and if not, the named cause.
    .DESCRIPTION
        Four outcomes are kept apart, because each sends the operator somewhere different:

          Access denied  the read threw a refusal, or StdRegProv returned 5 or 0x80041003.
          Not found      StdRegProv returned 1 (the value is not set) or 2 (its key does not
                         exist). MEASURED, NOT PUBLISHED - see below.
          Read failed    the read threw anything else, or returned any other nonzero code.
          Unusable       the value was read but is empty, or still holds an unexpanded
                         environment variable; or StdRegProv returned 0x80041005, so the value
                         exists and is not a string.

        WHAT MICROSOFT PUBLISHES. The return value is 0 for success. Otherwise, for C++
        callers, "a nonzero error code that is defined in WinError.h" ("You can also look up
        return values under the WMI Error Constants"), and for scripting callers "a nonzero
        error code that you can look up in WbemErrorEnum":
          https://learn.microsoft.com/previous-versions/windows/desktop/regprov/getstringvalue-method-in-class-stdregprov
          https://learn.microsoft.com/previous-versions/windows/desktop/regprov/getexpandedstringvalue-method-in-class-stdregprov
        WinError.h defines 1 as ERROR_INVALID_FUNCTION, 2 as ERROR_FILE_NOT_FOUND and 5 as
        ERROR_ACCESS_DENIED:
          https://learn.microsoft.com/windows/win32/debug/system-error-codes--0-499-
        WbemErrorEnum defines 0x80041003 as wbemErrAccessDenied ("The current user does not
        have permission to perform the action") and 0x80041005 as wbemErrTypeMismatch ("A
        type mismatch occurred"):
          https://learn.microsoft.com/windows/win32/api/wbemdisp/ne-wbemdisp-wbemerrorenum
          Read: 2026-11-13 (all four).
        Microsoft does NOT publish which of those codes this provider returns for which
        condition.

        WHAT WAS MEASURED. On 2026-11-13, with the same two methods this script calls, on ONE
        host - a Windows 11 (build 26100) workstation, not a domain controller, over a local
        CIM session and over a DCOM session to itself, under Windows PowerShell 5.1 and
        PowerShell 7 - both methods returned:
          0            a string value that exists (REG_SZ and REG_EXPAND_SZ alike)
          1            a value that does not exist, under a key that does
          2            a key that does not exist
          5            a key the account may not read
          2147749893   (0x80041005) a value that exists and is a REG_DWORD
        So an absent VALUE comes back as 1, not as 2, and WinError.h's name for 1 does not
        describe it. The findings name 1 and 2 as "Not found" on that measurement and say so;
        whether a domain controller, a server release or a remote session answers the same
        way has not been measured (PORT-PLAN C17). Any other code is quoted, not interpreted.
        Whatever the code means, the role stays Not Assessed.

        An absent value is NOT replaced by the default location. Microsoft states that "the
        default locations ... might be different from the locations on your servers", and
        publishes no meaning for an absent value, so the role is reported as not measured.
    .OUTPUTS
        [pscustomobject] Usable, Path ('' when not usable), Cause ('' when usable).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Entry)
    $out = [pscustomobject]@{ Usable = $false; Path = ''; Cause = '' }
    if ($null -eq $Entry) {
        $out.Cause = 'Read failed: no result was returned for this registry value.'
        return $out
    }
    $rights = 'Local Administrators rights on the DC are needed for this read.'
    $errorText = [string](Get-AdfaConfigValue -Entry $Entry -Name 'Error')
    $errorCode = [string](Get-AdfaConfigValue -Entry $Entry -Name 'ErrorCode')
    # What the outcome IS comes from the classifier every registry-reading section shares; what
    # the row SAYS about it is this section's own wording, below.
    $class = Get-AdfaStdRegReturnClass -ReturnValue (Get-AdfaConfigValue -Entry $Entry -Name 'ReturnValue') -ErrorText $errorText -ErrorCode $errorCode
    $kind = [string]$class.Class
    if ($class.Threw) {
        if ($kind -eq 'AccessDenied') {
            $out.Cause = ("Access denied: the registry read was refused. {0} Reported by the DC - {1}" -f $rights, $errorText)
        }
        else {
            $out.Cause = ("Read failed: the registry read did not complete. Reported by the DC - {0}" -f $errorText)
        }
        return $out
    }
    if ($kind -eq 'NoReturnCode') {
        $out.Cause = 'Read failed: the registry provider returned no return code, so whether the value was read is not known.'
        return $out
    }
    $number = [int64]$class.Code
    $also = ''
    $expanded = Get-AdfaConfigValue -Entry $Entry -Name 'ExpandedReturnValue'
    if ($null -ne $expanded -and [string]$expanded -ne '') { $also = (" GetExpandedStringValue was also tried and returned {0}." -f [string]$expanded) }
    # Where the 1 / 2 reading comes from, said in the row because it is not a vendor statement.
    $measured = 'This reading is measured, not published by Microsoft: on the one host where it was measured (a Windows 11 workstation, not a domain controller) the provider returns 1 for a value that is not set under a key that exists, and 2 for a key that does not exist.'
    if ($kind -eq 'AccessDenied' -and $number -eq 5) {
        $out.Cause = ("Access denied: StdRegProv returned 5, which WinError.h defines as ERROR_ACCESS_DENIED. {0}" -f $rights)
        return $out
    }
    if ($kind -eq 'AccessDenied') {
        $out.Cause = ("Access denied: StdRegProv returned 2147749891 (0x80041003), which WbemErrorEnum defines as wbemErrAccessDenied. {0}" -f $rights)
        return $out
    }
    if ($kind -eq 'ValueNotSet') {
        $out.Cause = ("Not found: StdRegProv returned 1, read here as the value not being set on this DC. {0} WinError.h defines 1 as ERROR_INVALID_FUNCTION, which does not describe it. No default location is assumed in its place.{1}" -f $measured, $also)
        return $out
    }
    if ($kind -eq 'KeyAbsent') {
        $out.Cause = ("Not found: StdRegProv returned 2, which WinError.h defines as ERROR_FILE_NOT_FOUND, read here as the registry key not existing on this DC. {0} No default location is assumed in its place.{1}" -f $measured, $also)
        return $out
    }
    if ($kind -eq 'TypeMismatch') {
        $out.Cause = ("The value is present but is not a string: StdRegProv returned 2147749893 (0x80041005), which WbemErrorEnum defines as wbemErrTypeMismatch, so it names no path.{0}" -f $also)
        return $out
    }
    if ($kind -ne 'Success') {
        $hex = ''
        if ($number -gt 0 -and $number -le 4294967295) { $hex = (" (0x{0})" -f $number.ToString('X8', [System.Globalization.CultureInfo]::InvariantCulture)) }
        $out.Cause = ("Read failed: StdRegProv returned {0}{1}. Microsoft documents a nonzero return as an error code from WinError.h or WbemErrorEnum and does not publish which code this provider returns for which condition, so the code is quoted and not interpreted.{2}" -f $number, $hex, $also)
        return $out
    }
    $value = ([string](Get-AdfaConfigValue -Entry $Entry -Name 'Value')).Trim()
    if ($value -eq '') {
        $out.Cause = ("The value is present but empty, so it names no path.{0}" -f $also)
        return $out
    }
    if ($value -match '%[^%\\]+%') {
        $method = [string](Get-AdfaConfigValue -Entry $Entry -Name 'Method')
        if ($method -eq '') { $method = 'GetStringValue' }
        $out.Cause = ("The value holds an environment variable that was not expanded ('{0}', read with {1}), so it names no volume.{2}" -f $value, $method, $also)
        return $out
    }
    $out.Usable = $true
    $out.Path = $value
    return $out
}

function New-AdfaDcDiskRow {
    <#
    .SYNOPSIS
        Pure: one DcDisk finding row. Every row of the section has the same columns, NotRun
        included, so a consumer never has to test whether the column exists.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = ''
    )
    $row = New-Finding -Scope $Scope -Area 'DcDisk' -Item $Item -Status $Status -Detail $Detail
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    return $row
}

function Get-AdfaDcDiskFinding {
    <#
    .SYNOPSIS
        Pure: one DC's raw read (Get-AdfaDcDiskRaw) as finding rows.
    .DESCRIPTION
        One row per DISTINCT volume, listing the roles it holds, because the default layout puts
        the database, the logs and SYSVOL on one volume and three identical verdicts would say
        nothing more than one. A role whose path could not be read, or could not be matched to
        a volume, gets its own Not Assessed row naming the cause. Every role in the config table
        is therefore accounted for by exactly one row - a role is never silently absent.

        The volume a role is judged on is the volume of the path the registry names. For SYSVOL
        that is the replica set root the SysVol value points at; whether DFSR staging or a
        junction target sits on another volume is not examined.

        Microsoft's sizing figures for the database volume are all relative to the size of
        ntds.dit - free space of 110 % of it to allow offline defragmentation, 300 % as "a safe
        way to accommodate growth and defragging", and 210 % of it as the size of a fixed VHD.
        None can be evaluated here, because the database FILE size is not read:
          https://learn.microsoft.com/windows-server/administration/performance-tuning/role/active-directory-server/capacity-planning-for-active-directory-domain-services
          Read: 2026-11-13.
        The row for the database volume says so in its NotRun column, not in its Detail: the
        recommendation is chosen from the Detail, and a note about what was not measured must
        not choose it.

        The consequence stated on a failing database or log volume is Microsoft's own, from
        NTDS General event 1393 ("Attempts to update the Directory Service database are failing
        with error 112 ... the NetLogon service is being paused"):
          https://learn.microsoft.com/troubleshoot/windows-server/active-directory/replication-error-8456-8457
          Read: 2026-11-13.
        Nothing equivalent is published for a volume that holds only SYSVOL, so none is claimed.
    .OUTPUTS
        [pscustomobject[]] Finding rows (Scope, Area, Item, Status, Detail, NotRun).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)]$Raw,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    $protocol = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Protocol')
    $rawPaths = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Paths') | Where-Object { $null -ne $_ })
    $volumes = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Volumes') | Where-Object { $null -ne $_ })
    $volumesOk = [bool](Get-AdfaConfigValue -Entry $Raw -Name 'VolumesOk')
    $thresholds = Get-AdfaDcDiskThresholdText -Config $Config

    # volume key -> the volume and the roles that resolved to it, in first-seen order.
    $groups = [ordered]@{}
    foreach ($definition in @($Config['Paths'])) {
        $role = [string](Get-AdfaConfigValue -Entry $definition -Name 'Role')
        $kind = [string](Get-AdfaConfigValue -Entry $definition -Name 'Kind')
        $registry = ("HKLM\{0}\{1}" -f [string](Get-AdfaConfigValue -Entry $definition -Name 'Key'), [string](Get-AdfaConfigValue -Entry $definition -Name 'ValueName'))
        $item = ("Disk space: {0} - {1} path" -f $DomainController, $role)

        $entry = $null
        foreach ($p in $rawPaths) {
            if ([string](Get-AdfaConfigValue -Entry $p -Name 'Role') -eq $role) { $entry = $p; break }
        }
        $read = Resolve-AdfaDcDiskPathRead -Entry $entry
        if (-not $read.Usable) {
            $rows += New-AdfaDcDiskRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed `
                -Detail ("{0} Registry value: {1}. The volume that holds the {2} is therefore not known, and its free space was not judged." -f [string]$read.Cause, $registry, $role)
            continue
        }
        if (-not $volumesOk) {
            $volumeError = [string](Get-AdfaConfigValue -Entry $Raw -Name 'VolumeError')
            $volumeCode = [string](Get-AdfaConfigValue -Entry $Raw -Name 'VolumeErrorCode')
            $lead = 'Read failed: the volume list (Win32_Volume) could not be read.'
            if ((Get-AdfaRemoteReadErrorClass -Message $volumeError -ErrorCode $volumeCode) -eq 'AccessDenied') {
                $lead = 'Access denied: the volume list (Win32_Volume) could not be read. Local Administrators rights on the DC are needed for this read.'
            }
            $rows += New-AdfaDcDiskRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed `
                -Detail ("{0} Reported by the DC - {1} The {2} path was read as '{3}' ({4}), but without the volume list its volume is not known, and its free space was not judged." -f $lead, $volumeError, $role, [string]$read.Path, $registry)
            continue
        }
        $resolved = Resolve-AdfaVolumeForPath -Path ([string]$read.Path) -Volumes $volumes
        if (-not $resolved.Resolved) {
            $rows += New-AdfaDcDiskRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed `
                -Detail ("The {0} path '{1}' ({2}) could not be matched to a volume: {3}. Its free space was not judged." -f $role, [string]$read.Path, $registry, [string]$resolved.Reason)
            continue
        }
        # One row per distinct volume: DeviceID is the volume's unique identifier; the mount
        # path stands in where it was not returned.
        $key = [string](Get-AdfaConfigValue -Entry $resolved.Volume -Name 'DeviceID')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-AdfaConfigValue -Entry $resolved.Volume -Name 'Name') }
        $key = $key.ToLowerInvariant()
        if (-not $groups.Contains($key)) { $groups[$key] = @{ Volume = $resolved.Volume; Roles = @() } }
        $groups[$key]['Roles'] = @($groups[$key]['Roles']) + [pscustomobject]@{ Role = $role; Kind = $kind; Path = [string]$read.Path }
    }

    foreach ($key in @($groups.Keys)) {
        $volume = $groups[$key]['Volume']
        $roles = @($groups[$key]['Roles'])
        $name = [string](Get-AdfaConfigValue -Entry $volume -Name 'Name')
        $roleNames = (@($roles | ForEach-Object { [string]$_.Role }) -join ', ')
        $holds = (@($roles | ForEach-Object { "{0} ({1})" -f [string]$_.Role, [string]$_.Path }) -join ', ')
        $kinds = @($roles | ForEach-Object { [string]$_.Kind })
        $item = ("Disk space: {0} {1} ({2})" -f $DomainController, $name, $roleNames)

        $verdict = Get-AdfaDiskSpaceVerdict -CapacityBytes (Get-AdfaConfigValue -Entry $volume -Name 'Capacity') `
            -FreeBytes (Get-AdfaConfigValue -Entry $volume -Name 'FreeSpace') `
            -WarnBelowPercent ([double]$Config['WarnBelowPercent']) -FailBelowPercent ([double]$Config['FailBelowPercent']) `
            -WarnBelowFreeGB ([double]$Config['WarnBelowFreeGB']) -FailBelowFreeGB ([double]$Config['FailBelowFreeGB'])

        if ($verdict.Status -eq $script:Status.NotAssessed) {
            $rows += New-AdfaDcDiskRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed `
                -Detail ("{0} Volume {1} holds: {2}. Read over {3}." -f [string]$verdict.Detail, $name, $holds, $protocol)
            continue
        }
        $consequence = ''
        if ($verdict.Status -eq $script:Status.Fail -and ($kinds -contains 'Database' -or $kinds -contains 'Logs')) {
            $consequence = 'When the volume that holds the directory database or its log files is full, Microsoft documents that database updates fail with error 112 and the Net Logon service is paused, so the DC stops logging on users (NTDS General event 1393). '
        }
        $notRun = ''
        if ($kinds -contains 'Database') {
            $notRun = 'Free space relative to the size of ntds.dit was not measured: this section does not read the database file size. Microsoft''s published sizing figures are relative to that size - free space of 110 % of the ntds.dit size to allow offline defragmentation, and 300 % where the storage allows - and meeting the thresholds above does not show either is met (PORT-PLAN C2a).'
        }
        $rows += New-AdfaDcDiskRow -Scope $Scope -Item $item -Status ([string]$verdict.Status) -NotRun $notRun `
            -Detail ("{0} Volume {1} holds: {2}. {3}{4} Read over {5}." -f [string]$verdict.Detail, $name, $holds, $consequence, $thresholds, $protocol)
    }
    return @($rows)
}

function Get-AdfaCimRawValue {
    <#
    .SYNOPSIS
        Pure: one property of a CIM instance as the DC returned it, not as a type adapter
        presents it.
    .DESCRIPTION
        Windows PowerShell 5.1 ships type data that replaces some CIM properties with script
        properties (C1 measured this on Win32_QuickFixEngineering.InstalledOn). Whether any is
        applied to Win32_Volume has not been measured, so the unadapted store,
        CimInstanceProperties, is read first and the member is the fallback for an object that
        has no such store.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Instance, [Parameter(Mandatory)][string]$Name)
    if ($null -eq $Instance) { return $null }
    $store = $Instance.PSObject.Properties['CimInstanceProperties']
    if ($null -ne $store -and $null -ne $store.Value) {
        $raw = $store.Value[$Name]
        if ($null -ne $raw) { return $raw.Value }
    }
    $member = $Instance.PSObject.Properties[$Name]
    if ($null -ne $member) { return $member.Value }
    return $null
}

function Get-AdfaStdRegStringValue {
    <#
    .SYNOPSIS
        Reads ONE string value from HKEY_LOCAL_MACHINE on a DC through the WMI registry
        provider. With Get-AdfaStdRegDwordValue, the only places this script invokes a CIM
        method.
    .DESCRIPTION
        READ-ONLY DECISION (PORT-PLAN C2). The house rule is "no CIM method invocation". This
        function is the one deliberate exception, and it is bounded:

          - StdRegProv has no instances to enumerate: a registry value can be read through it
            only by calling a method. It "is preinstalled in the WMI namespaces root\default and
            root\cimv2".
          - Microsoft lists the class's 20 methods in ONE table, and describes the class as
            able to "Read, write, and delete data values". It does not sort them into reading
            and writing methods; that sorting is this tool's, made from each method's own
            description. GetStringValue "Gets the string data value of a named value" and
            GetExpandedStringValue "Gets the expanded string data value of a named value";
            their only [out] parameter is the value. The methods Microsoft describes as
            creating, deleting or setting have other names: CreateKey, DeleteKey, DeleteValue,
            the seven Set* methods.
              https://learn.microsoft.com/previous-versions/windows/desktop/regprov/stdregprov
              https://learn.microsoft.com/previous-versions/windows/desktop/regprov/getstringvalue-method-in-class-stdregprov
              https://learn.microsoft.com/previous-versions/windows/desktop/regprov/getexpandedstringvalue-method-in-class-stdregprov
              Read: 2026-11-13 (all three).
          - Only those two Get* methods are called here, each with a LITERAL -MethodName on a
            literal -ClassName; Get-AdfaStdRegDwordValue calls a third, GetDWORDValue, the same
            way (PORT-PLAN C3). A test reads every Invoke-CimMethod in this script from the
            parsed source and fails on any other method name, a computed name, or another
            class. EnumValues is not used: it is not a Get* method.

        What Microsoft does NOT say: no page read states that these methods have no side
        effect. The decision rests on their documented purpose and signature, and on the
        creating, deleting and setting methods having names of their own. That is recorded
        here rather than presented as a vendor statement.

        Invoke-CimMethod supports -WhatIf, and under it "The cmdlet is not run":
          https://learn.microsoft.com/powershell/module/cimcmdlets/invoke-cimmethod?view=powershell-5.1
          Read: 2026-11-13.
        A WhatIf preference in the caller's session would therefore skip the read and leave
        nothing to judge, so -WhatIf and -Confirm are forced off on these two calls. That is
        safe only because both are reads.

        GetStringValue is documented for REG_SZ and GetExpandedStringValue for REG_EXPAND_SZ.
        The registry type of the three values this section reads is not published, which is why
        the caller tries the second where the first gives nothing usable.

        The session's operation timeout is passed to each call as well, so one registry read
        that never answers is bounded on its own and cannot hold the run.

        Never throws. A call that raised comes back with Answered = $false and the error text
        and CIM error code; a call that returned comes back with the provider's ReturnValue,
        whatever it is.
    .OUTPUTS
        [pscustomobject] Answered, ReturnValue ($null when not answered), Value, Method, Error,
        ErrorCode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$CimSession,
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)][string]$ValueName,
        [switch]$Expanded,
        [int]$OperationTimeoutSec = 90
    )
    $out = [pscustomobject]@{ Answered = $false; ReturnValue = $null; Value = ''; Method = 'GetStringValue'; Error = ''; ErrorCode = '' }
    # 2147483650 is HKEY_LOCAL_MACHINE, as the method pages list it (defined in WinReg.h).
    $arguments = @{ hDefKey = [uint32]2147483650; sSubKeyName = $Key; sValueName = $ValueName }
    try {
        $result = $null
        if ($Expanded) {
            $out.Method = 'GetExpandedStringValue'
            $result = Invoke-CimMethod -CimSession $CimSession -Namespace 'root/cimv2' -ClassName 'StdRegProv' -MethodName 'GetExpandedStringValue' `
                -Arguments $arguments -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -WhatIf:$false -Confirm:$false -ErrorAction Stop
        }
        else {
            $result = Invoke-CimMethod -CimSession $CimSession -Namespace 'root/cimv2' -ClassName 'StdRegProv' -MethodName 'GetStringValue' `
                -Arguments $arguments -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -WhatIf:$false -Confirm:$false -ErrorAction Stop
        }
        if ($null -eq $result) { throw 'The registry provider returned no result.' }
        $codeProp = $result.PSObject.Properties['ReturnValue']
        if ($null -eq $codeProp -or $null -eq $codeProp.Value) { throw 'The registry provider returned no ReturnValue.' }
        $out.ReturnValue = [int64]$codeProp.Value
        $valueProp = $result.PSObject.Properties['sValue']
        if ($null -ne $valueProp -and $null -ne $valueProp.Value) { $out.Value = [string]$valueProp.Value }
        $out.Answered = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        if ($out.Error -eq '') { $out.Error = 'The registry read failed without an error message.' }
        $nativeCode = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $nativeCode -and $null -ne $nativeCode.Value) { $out.ErrorCode = [string]$nativeCode.Value }
    }
    return $out
}

function Get-AdfaDcDiskRaw {
    <#
    .SYNOPSIS
        The one place C2 touches a DC: three registry reads and one volume query, in one
        bounded CIM session.
    .DESCRIPTION
        The three paths, from the registry of the DC itself - no LDAP attribute publishes them:
          NTDS database   HKLM\SYSTEM\CurrentControlSet\Services\NTDS\Parameters, "DSA Database File"
                          (the path of the database FILE, not a folder)
          NTDS logs       same key, "Database Log Files Path"
          SYSVOL          HKLM\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters, "SysVol"
        Sources and read date are beside $script:Config.DcDisk, which holds the names.

        Then Win32_Volume in root/cimv2 for Name, DeviceID, DriveType, Capacity and FreeSpace
        ("Size of the volume in bytes"; "Space, in bytes, available on the logical disk"):
          https://learn.microsoft.com/previous-versions/windows/desktop/legacy/aa394515(v=vs.85)
          Read: 2026-11-13.
        The class also has methods that change a volume (Format, Dismount, Chkdsk, Defrag,
        AddMountPoint ...) and three read/write properties. None is used: instances are
        enumerated with Get-CimInstance and five properties are read. Nothing is written.

        Each value is read with GetStringValue. Where that gives nothing usable - a nonzero
        return, an empty value, or a value still holding %VARIABLE% - GetExpandedStringValue
        is tried for that value, because the registry type of these values is not published.
        It is not tried after a refusal (a return of 5, ERROR_ACCESS_DENIED, or of 0x80041003,
        wbemErrAccessDenied): the same account would be refused again.

        Never throws. One value that cannot be read does not discard the other two, and a
        failed volume query does not discard the paths. Ok is $false only when the session could
        not be opened, or when not one of the four operations got an answer from the DC - which
        is what lets the caller try the other transport. A DC whose three registry reads all
        threw but whose volume list was read is therefore Ok, and gets one row per role.

        The session is always closed. Remove-CimSession supports -WhatIf and under it "The
        cmdlet is not run":
          https://learn.microsoft.com/powershell/module/cimcmdlets/remove-cimsession?view=powershell-5.1
          Read: 2026-11-13.
        A WhatIf or Confirm preference in the caller's session would therefore leave one
        session open per DC per transport, so both are forced off on that call. It closes a
        session this function opened; it changes nothing on the DC.
    .OUTPUTS
        [pscustomobject] Ok, Protocol, Error, ErrorCode,
        Paths (one per requested value: Role, Key, ValueName, Read, ReturnValue, Value, Method,
        Error, ErrorCode, ExpandedReturnValue),
        VolumesOk, Volumes (Name, DeviceID, DriveType, Capacity, FreeSpace - raw), VolumeError,
        VolumeErrorCode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [ValidateSet('Wsman', 'Dcom')][string]$Protocol = 'Wsman',
        [pscredential]$Credential,
        [int]$OperationTimeoutSec = 90,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$Paths
    )
    $out = [pscustomobject]@{
        Ok = $false; Protocol = $Protocol; Error = ''; ErrorCode = ''; Paths = @()
        VolumesOk = $false; Volumes = @(); VolumeError = ''; VolumeErrorCode = ''
    }
    $session = $null
    try {
        $sessionArgs = @{ ComputerName = $ComputerName; OperationTimeoutSec = [uint32]$OperationTimeoutSec; ErrorAction = 'Stop' }
        if ($Protocol -eq 'Dcom') { $sessionArgs.SessionOption = New-CimSessionOption -Protocol Dcom }
        if ($Credential) { $sessionArgs.Credential = $Credential }
        $session = New-CimSession @sessionArgs

        $answered = $false
        $firstError = ''
        $firstCode = ''
        $entries = New-Object System.Collections.ArrayList
        foreach ($definition in @($Paths)) {
            if ($null -eq $definition) { continue }
            $key = [string](Get-AdfaConfigValue -Entry $definition -Name 'Key')
            $valueName = [string](Get-AdfaConfigValue -Entry $definition -Name 'ValueName')
            $entry = [pscustomobject]@{
                Role = [string](Get-AdfaConfigValue -Entry $definition -Name 'Role'); Key = $key; ValueName = $valueName
                Read = $false; ReturnValue = $null; Value = ''; Method = 'GetStringValue'; Error = ''; ErrorCode = ''; ExpandedReturnValue = $null
            }
            $first = Get-AdfaStdRegStringValue -CimSession $session -Key $key -ValueName $valueName -OperationTimeoutSec $OperationTimeoutSec
            if (-not $first.Answered) {
                $entry.Error = [string]$first.Error
                $entry.ErrorCode = [string]$first.ErrorCode
                if ($firstError -eq '') { $firstError = $entry.Error; $firstCode = $entry.ErrorCode }
            }
            else {
                $answered = $true
                $entry.ReturnValue = $first.ReturnValue
                $entry.Value = [string]$first.Value
                $usable = ($first.ReturnValue -eq 0 -and $entry.Value.Trim() -ne '' -and $entry.Value -notmatch '%[^%\\]+%')
                $refused = ($first.ReturnValue -eq 5 -or $first.ReturnValue -eq 2147749891)
                if (-not $usable -and -not $refused) {
                    $second = Get-AdfaStdRegStringValue -CimSession $session -Key $key -ValueName $valueName -Expanded -OperationTimeoutSec $OperationTimeoutSec
                    if ($second.Answered) {
                        $entry.ExpandedReturnValue = $second.ReturnValue
                        if ($second.ReturnValue -eq 0 -and ([string]$second.Value).Trim() -ne '') {
                            $entry.ReturnValue = $second.ReturnValue
                            $entry.Value = [string]$second.Value
                            $entry.Method = 'GetExpandedStringValue'
                        }
                    }
                }
                $entry.Read = ($entry.ReturnValue -eq 0 -and $entry.Value.Trim() -ne '')
            }
            [void]$entries.Add($entry)
        }
        $out.Paths = $entries.ToArray()

        try {
            $instances = @(Get-CimInstance -CimSession $session -Namespace 'root/cimv2' -ClassName 'Win32_Volume' `
                    -Property 'Name', 'DeviceID', 'DriveType', 'Capacity', 'FreeSpace' -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -ErrorAction Stop)
            $list = New-Object System.Collections.ArrayList
            foreach ($instance in $instances) {
                if ($null -eq $instance) { continue }
                [void]$list.Add([pscustomobject]@{
                        Name      = Get-AdfaCimRawValue -Instance $instance -Name 'Name'
                        DeviceID  = Get-AdfaCimRawValue -Instance $instance -Name 'DeviceID'
                        DriveType = Get-AdfaCimRawValue -Instance $instance -Name 'DriveType'
                        Capacity  = Get-AdfaCimRawValue -Instance $instance -Name 'Capacity'
                        FreeSpace = Get-AdfaCimRawValue -Instance $instance -Name 'FreeSpace'
                    })
            }
            $out.Volumes = $list.ToArray()
            $out.VolumesOk = $true
            $answered = $true
        }
        catch {
            $out.VolumeError = [string]$_.Exception.Message
            if ($out.VolumeError -eq '') { $out.VolumeError = 'The volume query failed without an error message.' }
            $volumeCode = $_.Exception.PSObject.Properties['NativeErrorCode']
            if ($null -ne $volumeCode -and $null -ne $volumeCode.Value) { $out.VolumeErrorCode = [string]$volumeCode.Value }
            if ($firstError -eq '') { $firstError = $out.VolumeError; $firstCode = $out.VolumeErrorCode }
        }

        $out.Ok = $answered
        if (-not $answered) {
            $out.Error = $firstError
            $out.ErrorCode = $firstCode
        }
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $codeProp = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $out.ErrorCode = [string]$codeProp.Value }
    }
    finally {
        if ($null -ne $session) {
            try { Remove-CimSession -CimSession $session -WhatIf:$false -Confirm:$false -ErrorAction SilentlyContinue } catch { }
        }
    }
    return $out
}

function Get-AdfaDcTargetsByDomain {
    <#
    .SYNOPSIS
        The domain controllers of each scoped domain, as (Scope, HostName) rows, with the
        domains that could not be asked returned beside them.
    .DESCRIPTION
        For a per-DC section that has to run when the DomainControllers section was not
        selected, so there is no inventory to take its targets from. Without this, such a
        section fell back to one unscoped Get-ADDomainController call against the default
        server, which returns the current domain's DCs only: on a run with -AllDomains every
        other scoped domain was missing from the section, with no row to say so.

        One Get-ADDomainController -Filter * per domain, with -Server set to that domain - the
        call the DC inventory makes, without its per-DC Get-ADComputer enrichment, which a
        section that only needs host names has no use for. Read-only.

        Never throws. A domain whose call threw is returned in Failures with the error text, so
        the caller can give it a Not Assessed row; a DC returned with no host name is kept, for
        the caller to report, not dropped.
    .OUTPUTS
        [pscustomobject] Targets (Scope, HostName), Failures (Domain, Error).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$Domains = @(),
        [hashtable]$AdParams = @{}
    )
    $targets = New-Object System.Collections.ArrayList
    $failures = New-Object System.Collections.ArrayList
    foreach ($domain in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        try {
            $p = @{} + $AdParams
            $p.Server = $domain
            foreach ($dc in @(Get-ADDomainController -Filter * @p)) {
                if ($null -eq $dc) { continue }
                $hostName = ''
                $hostProp = $dc.PSObject.Properties['HostName']
                if ($null -ne $hostProp -and $null -ne $hostProp.Value) { $hostName = [string]$hostProp.Value }
                [void]$targets.Add([pscustomobject]@{ Scope = [string]$domain; HostName = $hostName })
            }
        }
        catch {
            [void]$failures.Add([pscustomobject]@{ Domain = [string]$domain; Error = [string]$_.Exception.Message })
        }
    }
    return [pscustomobject]@{ Targets = $targets.ToArray(); Failures = $failures.ToArray() }
}

function Get-AdfaDcPopulationGap {
    <#
    .SYNOPSIS
        Pure: the scoped domains a per-DC section must give a row of their own, because its DC
        rows do not account for them. Shared by DcDisk and DcHardening.
    .DESCRIPTION
        DECLARED POPULATION: the domains named in -ScopedDomains, plus any named only in
        -InventoryFailures. A domain is returned when its enumeration threw, or when no target
        carries it as Scope; a domain covered by at least one target and not failed is not.
        Names are compared without regard to case. The caller words the row.
    .OUTPUTS
        [pscustomobject[]] Domain, Failed, Error ('' unless Failed), Seen (targets carry this
        domain although its enumeration failed), WithoutDomain (how many targets carry no
        domain at all - they came from the unscoped fallback enumeration).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$Targets = @(),
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    # Which domains the targets account for, and how many targets carry no domain at all.
    $domainsSeen = @{}
    $withoutDomain = 0
    foreach ($target in @($Targets | Where-Object { $null -ne $_ })) {
        $targetScope = ''
        if ($target -isnot [string]) {
            $targetScopeProp = $target.PSObject.Properties['Scope']
            if ($null -ne $targetScopeProp -and $null -ne $targetScopeProp.Value) { $targetScope = ([string]$targetScopeProp.Value).Trim() }
        }
        if ($targetScope -eq '') { $withoutDomain++ } else { $domainsSeen[$targetScope.ToLowerInvariant()] = $true }
    }
    $failureCause = [ordered]@{}
    foreach ($failure in @($InventoryFailures | Where-Object { $null -ne $_ })) {
        $failedDomain = ([string]$failure.Domain).Trim()
        if (-not $failureCause.Contains($failedDomain.ToLowerInvariant())) { $failureCause[$failedDomain.ToLowerInvariant()] = @{ Domain = $failedDomain; Error = [string]$failure.Error } }
    }
    $population = New-Object System.Collections.ArrayList
    foreach ($name in @($ScopedDomains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        if (@($population | Where-Object { $_ -eq $name.Trim() }).Count -eq 0) { [void]$population.Add($name.Trim()) }
    }
    foreach ($k in @($failureCause.Keys)) {
        $failedName = [string]$failureCause[$k]['Domain']
        if (@($population | Where-Object { $_ -eq $failedName }).Count -eq 0) { [void]$population.Add($failedName) }
    }
    $gaps = New-Object System.Collections.ArrayList
    foreach ($domain in $population) {
        $key = $domain.ToLowerInvariant()
        $failed = $failureCause.Contains($key)
        $seen = $domainsSeen.ContainsKey($key)
        if ($seen -and -not $failed) { continue }
        $cause = ''
        if ($failed) { $cause = ([string]$failureCause[$key]['Error']).Trim() }
        [void]$gaps.Add([pscustomobject]@{ Domain = [string]$domain; Failed = [bool]$failed; Error = $cause; Seen = [bool]$seen; WithoutDomain = [int]$withoutDomain })
    }
    return @($gaps.ToArray())
}

function Get-AdfaDcPopulationGapText {
    <#
    .SYNOPSIS
        Pure: the Detail of a per-domain population row - why the domain has no DC row, and
        what that does and does not say about what was read.
    .DESCRIPTION
        The row does not claim "nothing was read" when DCs without a domain follow it: those
        came from a fallback enumeration that does not say which domain each belongs to, and the
        row says that instead. -NothingRead is the section's own sentence for the plain case.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]$Gap,
        [Parameter(Mandatory)][string]$NothingRead
    )
    $cause = 'The enumeration returned no domain controller for this domain.'
    if ($Gap.Failed) { $cause = ("The domain controllers of this domain could not be enumerated. Cause: {0}" -f [string]$Gap.Error) }
    $coverage = $NothingRead
    if ($Gap.Seen) {
        $coverage = 'The domain controllers listed under this domain came from another enumeration; whether they are all of them is not known.'
    }
    elseif ([int]$Gap.WithoutDomain -gt 0) {
        $coverage = ("The {0} domain controller(s) listed in this section without a domain came from the fallback enumeration against the default server, which does not say which domain each belongs to. Whether they include this domain's is not known, so this domain is not shown as read." -f [int]$Gap.WithoutDomain)
    }
    return ("{0} {1}" -f $cause, $coverage)
}

function ConvertTo-AdfaDcTarget {
    <#
    .SYNOPSIS
        Pure: one per-DC target as a host name and a domain. A target is an inventory row
        (HostName, Scope) or a plain host name, which carries no domain.
    .OUTPUTS
        [pscustomobject] HostName ('' when the target has none), Scope ('' when it has none).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Target)
    $out = [pscustomobject]@{ HostName = ''; Scope = '' }
    if ($null -eq $Target) { return $out }
    if ($Target -is [string]) { $out.HostName = $Target; return $out }
    $hostProp = $Target.PSObject.Properties['HostName']
    if ($null -ne $hostProp -and $null -ne $hostProp.Value) { $out.HostName = [string]$hostProp.Value }
    $scopeProp = $Target.PSObject.Properties['Scope']
    if ($null -ne $scopeProp -and $null -ne $scopeProp.Value) { $out.Scope = [string]$scopeProp.Value }
    return $out
}

function Get-AdfaDcHostSet {
    <#
    .SYNOPSIS
        Pure: the host names of a list of per-DC targets, in order, each once (PORT-PLAN C2e). The
        DNS server set of the four DNS-vs-AD sections and the DC count of the run.
    .DESCRIPTION
        A DC can be listed under more than one target (the same host returned by the enumeration of
        two domains, or in another case); it is counted and queried once. Names are compared
        without regard to case and without a trailing dot; the first spelling is kept. A target
        with no host name is left out: it names no server.
    .OUTPUTS
        [string[]]
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param([AllowNull()][AllowEmptyCollection()]$Targets = @())
    $hosts = New-Object System.Collections.ArrayList
    $seen = @{}
    foreach ($target in @($Targets | Where-Object { $null -ne $_ })) {
        $name = ([string](ConvertTo-AdfaDcTarget -Target $target).HostName).Trim()
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $key = $name.TrimEnd('.').ToLowerInvariant()
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        [void]$hosts.Add($name)
    }
    return [string[]]@($hosts.ToArray())
}

function Get-AdfaDomainDcHostName {
    <#
    .SYNOPSIS
        Pure: the host names of ONE scoped domain's DCs among the per-DC targets, or why there are
        none (PORT-PLAN C2e). For a per-domain consumer such as the SYSVOL backlog.
    .DESCRIPTION
        HostNames: the targets whose Scope is -Domain (case-insensitive). When no target carries a
        domain at all (the unscoped fallback enumeration against the default server) and -Domain
        is the only scoped domain, the unscoped names are that domain's - the default server's
        domain is the one scoped - and are returned, as before. In every other case the unscoped
        names are NOT taken for this domain: on a multi-domain run they are another domain's DCs.
        Gap: when HostNames is empty, this domain's entry of Get-AdfaDcPopulationGap (its
        enumeration threw, with the error; or it returned no DC), for the caller to report as a Not
        Assessed row; $null otherwise.
    .OUTPUTS
        [pscustomobject] HostNames (string[]), Gap.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [AllowNull()][AllowEmptyCollection()]$Targets = @(),
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $key = $Domain.Trim().TrimEnd('.').ToLowerInvariant()
    $named = @(@($Targets | Where-Object { $null -ne $_ }) | ForEach-Object { ConvertTo-AdfaDcTarget -Target $_ })
    $names = @($named | Where-Object { $_.Scope.Trim().TrimEnd('.').ToLowerInvariant() -eq $key } | ForEach-Object { [string]$_.HostName })
    $anyScoped = (@($named | Where-Object { -not [string]::IsNullOrWhiteSpace($_.Scope) }).Count -gt 0)
    $scoped = @(@($ScopedDomains) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { ([string]$_).Trim().TrimEnd('.').ToLowerInvariant() } | Sort-Object -Unique)
    if ($names.Count -eq 0 -and -not $anyScoped -and $scoped.Count -eq 1 -and $scoped[0] -eq $key) {
        $names = @($named | ForEach-Object { [string]$_.HostName })
    }
    $gap = $null
    if ($names.Count -eq 0) {
        $ownFailures = @(@($InventoryFailures | Where-Object { $null -ne $_ }) | Where-Object { ([string]$_.Domain).Trim().TrimEnd('.').ToLowerInvariant() -eq $key })
        $gaps = @(Get-AdfaDcPopulationGap -Targets @($Targets) -InventoryFailures $ownFailures -ScopedDomains @($Domain))
        if ($gaps.Count -gt 0) { $gap = $gaps[0] }
    }
    return [pscustomobject]@{ HostNames = [string[]]@($names); Gap = $gap }
}

function Invoke-AdfaDcRemoteRead {
    <#
    .SYNOPSIS
        The transport loop every CIM-reading per-DC section shares: one read per DC over the
        first transport that answers. Shared by DcDisk and DcHardening.
    .DESCRIPTION
        -Protocols lists, in order, the transports whose port answered the caller's probe
        (Test-AdfaDcPort, so a DC is probed once per port in the whole run). WinRM is tried
        first and DCOM second. A refusal is NOT retried over the other transport: the same
        account would be refused again. The read itself is the section's own seam, named by
        -ReadCommand from a fixed list and called with -ComputerName, -Protocol and the
        caller's -ReadArguments; it opens one session, reads, and closes it.

        Never decides what a failure means beyond refusal or not: the caller words the row.
    .OUTPUTS
        [pscustomobject] Raw (the seam's last result, $null when it returned none), Denied,
        Attempts ("<protocol>: <error>" for each attempt that did not succeed).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Protocols,
        [Parameter(Mandatory)][ValidateSet('Get-AdfaDcDiskRaw', 'Get-AdfaDcHardeningRaw', 'Get-AdfaDcNetworkRaw', 'Get-AdfaDcW32TimeRaw')][string]$ReadCommand,
        [hashtable]$ReadArguments = @{}
    )
    $raw = $null
    $attempts = @()
    $denied = $false
    foreach ($protocol in $Protocols) {
        $readArgs = @{} + $ReadArguments
        $readArgs['ComputerName'] = $ComputerName
        $readArgs['Protocol'] = $protocol
        $raw = & $ReadCommand @readArgs
        if ($null -ne $raw -and $raw.Ok) { break }
        $message = ''
        $code = ''
        if ($null -ne $raw) {
            $message = [string]$raw.Error
            $codeProp = $raw.PSObject.Properties['ErrorCode']
            if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $code = [string]$codeProp.Value }
        }
        $attempts += ("{0}: {1}" -f $protocol, $message)
        if ((Get-AdfaRemoteReadErrorClass -Message $message -ErrorCode $code) -eq 'AccessDenied') { $denied = $true; break }
    }
    return [pscustomobject]@{ Raw = $raw; Denied = $denied; Attempts = @($attempts) }
}

function Get-AdfaDcDiskSpace {
    <#
    .SYNOPSIS
        Per-DC free space on the volumes that hold the NTDS database, the NTDS logs and SYSVOL.
    .DESCRIPTION
        A DC is probed once per port through the shared cache (Test-AdfaDcPort). WinRM is tried
        first and DCOM second where the RPC endpoint mapper answers; a refusal is not retried
        over the other transport, because the same account would be refused again. Three
        outcomes are kept apart for a DC that gave nothing: unreachable (no port answered, no
        read attempted), access denied, and any other read failure, quoted as the DC reported it.

        Needs local Administrators rights on each DC: "By default, only members of the
        Administrators group can access the WMI namespace remotely."
          https://learn.microsoft.com/troubleshoot/windows-server/system-management-components/scenario-guide-troubleshoot-wmi-connectivity-access-issues
          Read: 2026-11-13.
        The registry permission StdRegProv needs on the two keys is not published.

        Accepts DC rows (HostName, Scope) so each finding carries its domain, or plain host
        names where the caller has only those.

        DECLARED POPULATION: the domains named in -ScopedDomains. Each of them ends up in the
        section one of two ways - as the Scope of at least one DC row, or as its own
        "Disk space - <domain>" Not Assessed row saying why none of its DCs is shown as read
        (the enumeration threw, or returned no DC for it). A domain is never simply missing.
        A domain named only in -InventoryFailures gets the same row. That row does not claim
        "nothing was read" when DCs without a domain follow it: those came from a fallback
        enumeration that does not say which domain each belongs to, and the row says that
        instead. No row is ever Info, and none is Pass unless both figures were read.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [int]$OperationTimeoutSec = 90,
        # Domains whose DC enumeration threw: objects with Domain and Error.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        # Why no DC could be enumerated at all, where the caller knows.
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        # The domains this run was scoped to: the declared population of the section.
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })

    # One row for each scoped domain the DC rows do not account for. Which domains those are,
    # and the wording that is the same in every per-DC section, are shared (Get-AdfaDcPopulationGap).
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaDcDiskRow -Scope ([string]$gap.Domain) -Item ("Disk space - {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'None of its volumes was read.')
    }
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        $rows += New-AdfaDcDiskRow -Item 'Disk space' -Status $script:Status.NotAssessed `
            -Detail ("No domain controllers were enumerated, so no volume was read.{0} This is not a clean result." -f $why)
        return @($rows)
    }
    $wsmanPort = [int]$Config['WsmanPort']
    $rpcPort = [int]$Config['RpcPort']
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-AdfaDcDiskRow -Scope $scope -Item 'Disk space: (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and no volume was read.'
            continue
        }
        $item = ("Disk space: {0}" -f $dc)
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @($wsmanPort, $rpcPort) -TimeoutMs $PortTimeoutMs
        $wsman = [bool]$gate.Open[$wsmanPort]
        $rpc = [bool]$gate.Open[$rpcPort]
        if ($gate.Cause) {
            $rows += New-AdfaDcDiskRow -Scope $scope -Item $item -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'no read was attempted')
            continue
        }
        if (-not $wsman -and -not $rpc) {
            $rows += New-AdfaDcDiskRow -Scope $scope -Item $item -Status $script:Status.NotAssessed `
                -Detail ("Unreachable: neither WinRM ({0}) nor RPC ({1}) answered within {2} ms, so no read was attempted." -f $wsmanPort, $rpcPort, $PortTimeoutMs)
            continue
        }
        $protocols = @()
        if ($wsman) { $protocols += 'Wsman' }
        if ($rpc) { $protocols += 'Dcom' }
        $readArguments = @{ OperationTimeoutSec = $OperationTimeoutSec; Paths = $Config['Paths'] }
        if ($Credential) { $readArguments.Credential = $Credential }
        $read = Invoke-AdfaDcRemoteRead -ComputerName $dc -Protocols $protocols -ReadCommand 'Get-AdfaDcDiskRaw' -ReadArguments $readArguments
        $raw = $read.Raw
        $attempts = @($read.Attempts)
        $denied = [bool]$read.Denied
        if ($null -eq $raw -or -not $raw.Ok) {
            $lead = 'Read failed: a port answered, but neither the registry values nor the volume list could be read. If the text below is a refusal in another language, local Administrators rights on the DC are what is missing.'
            if ($denied) { $lead = 'Access denied: the account running the assessment could not read the registry or the volume list of this DC. Local Administrators rights on the DC are needed for this read.' }
            $rows += New-AdfaDcDiskRow -Scope $scope -Item $item -Status $script:Status.NotAssessed `
                -Detail ("{0} Reported by the DC - {1}" -f $lead, ($attempts -join ' | '))
            continue
        }
        $rows += @(Get-AdfaDcDiskFinding -DomainController $dc -Scope $scope -Raw $raw -Config $Config)
    }
    return @($rows)
}

function Merge-AdfaDcDiskConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in DC disk table, with validation. The DcDisk
        validator for -ConfigOverridePath.
    .DESCRIPTION
        Only the keys the override names are replaced. The keys that can be named are the four
        thresholds. Paths, SourceUrl and ReadDate cannot: they are what the tool reads and where
        the vendor documents it, not a volatile value, and a file that redirected the registry
        reads would make every finding describe something else. WsmanPort and RpcPort are refused
        with their own reason (PORT-PLAN C3g): the CIM session is opened on the default ports, so
        a port set here would only have changed what was probed.

        Anything this tool could not use is refused with the reason: an override that is not one
        object, an empty object, an unknown key, a null, a value that is not a JSON number, a
        percentage outside 0 to 100, a negative floor, either port key. The MERGED
        table is then checked as a whole, so a file that names only FailBelowPercent is still
        refused when that puts Fail above the built-in Warning threshold, and a table left with
        no threshold at all - which would pass every volume - is refused too.

        Provenance follows the thresholds key by key. ThresholdSource is rewritten to name the
        override's source for exactly the thresholds it supplied, and goes on calling the rest
        tool defaults.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    # ONE object with named keys. A JSON array, string or number also arrives as a .NET object,
    # and its own properties (Length, Count ...) must not be read as config keys.
    $isTable = ($Override -is [System.Collections.IDictionary])
    $isObject = ($Override -is [System.Management.Automation.PSCustomObject])
    if (-not $isTable -and -not $isObject) {
        throw ("DC disk config override must be a single object with named keys (for example {{ ""WarnBelowPercent"": 25 }}), not a {0}." -f $Override.GetType().Name)
    }
    $names = @()
    if ($isTable) { $names = @($Override.Keys) }
    else { $names = @($Override.PSObject.Properties | ForEach-Object { $_.Name }) }
    if ($names.Count -eq 0) {
        throw 'DC disk config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $thresholdKeys = @('WarnBelowPercent', 'FailBelowPercent', 'WarnBelowFreeGB', 'FailBelowFreeGB')
    $portKeys = @('WsmanPort', 'RpcPort')
    $known = @($thresholdKeys)
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in $names) {
        $given = [string]$k
        # PORT-PLAN C3g: the two port keys are refused whatever they hold, with their own reason, as
        # DcHardening refuses them: a port set here was probed, and the CIM session still went to the
        # default one. New-CimSession -Port needs a WinRM listener on that port, which only a change
        # on the DC creates, and DCOM has no port option (Learn, read 2026-11-17).
        $portMatch = @($portKeys | Where-Object { $_ -eq $given })
        if ($portMatch.Count -gt 0) {
            throw ("DC disk config override names '{0}'. The ports of this section cannot be set from a file: its CIM session is always opened on the default WinRM port ({1}), or through the RPC endpoint mapper ({2}) for DCOM, so a different port here would change what is probed and not what is connected to. Remove the key." -f [string]$portMatch[0], [int]$BaseConfig['WsmanPort'], [int]$BaseConfig['RpcPort'])
        }
        # A misspelt key would otherwise be accepted, ignored, and leave the operator believing
        # their threshold was applied.
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("DC disk config override names an unknown key '{0}'. Known keys: {1}." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        # Reachable only from an object built in memory with keys that differ by case. A key
        # written twice in a FILE never gets here: ConvertFrom-Json has already reduced it to
        # its last value, which is why Import-AdfaConfigOverride looks for it in the text.
        if ($supplied -contains $name) { throw ("DC disk config override names '{0}' more than once." -f $name) }
        $value = $null
        if ($isTable) { $value = $Override[$k] }
        else { $value = $Override.PSObject.Properties[$given].Value }
        if ($null -eq $value) {
            throw ("DC disk config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name)
        }
        # A JSON number only. "25" in quotes is refused rather than parsed: how a string becomes
        # a number depends on the culture of the host, and a threshold must not.
        if ($numericTypes -notcontains $value.GetType()) {
            throw ("DC disk config override sets '{0}' to a {1} ('{2}'). It must be a JSON number, written without quotes." -f $name, $value.GetType().Name, [string]$value)
        }
        $number = [double]$value
        if ([double]::IsNaN($number) -or [double]::IsInfinity($number)) {
            throw ("DC disk config override sets '{0}' to a value that is not a finite number." -f $name)
        }
        $shown = $number.ToString('0.####', $inv)
        if ($name -like '*Percent') {
            if ($number -lt 0 -or $number -gt 100) {
                throw ("DC disk config override sets '{0}' to {1}. A percentage of free space must be in the range 0 to 100." -f $name, $shown)
            }
            $merged[$name] = $number
        }
        else {
            if ($number -lt 0) {
                throw ("DC disk config override sets '{0}' to {1}. A free-space floor in GB cannot be negative; use 0 for no floor." -f $name, $shown)
            }
            $merged[$name] = $number
        }
        $supplied += $name
    }

    # The table as a whole, built-in values included.
    $warnPercent = [double]$merged['WarnBelowPercent']
    $failPercent = [double]$merged['FailBelowPercent']
    $warnFloor = [double]$merged['WarnBelowFreeGB']
    $failFloor = [double]$merged['FailBelowFreeGB']
    if ($failPercent -gt $warnPercent) {
        throw ("DC disk config: FailBelowPercent ({0}) is above WarnBelowPercent ({1}) once the override is applied. A volume would fail at a level of free space at which it does not yet warn; set both." -f $failPercent.ToString('0.####', $inv), $warnPercent.ToString('0.####', $inv))
    }
    if ($failFloor -gt $warnFloor) {
        throw ("DC disk config: FailBelowFreeGB ({0}) is above WarnBelowFreeGB ({1}) once the override is applied. Set both; to switch the floor off, set both to 0." -f $failFloor.ToString('0.####', $inv), $warnFloor.ToString('0.####', $inv))
    }
    if ($warnPercent -le 0 -and $failPercent -le 0 -and $warnFloor -le 0 -and $failFloor -le 0) {
        throw 'DC disk config leaves no threshold in force: all four are 0, so every volume would pass whatever its free space.'
    }

    $fromOverride = @($thresholdKeys | Where-Object { $supplied -contains $_ })
    if ($fromOverride.Count -gt 0) {
        $from = 'an override whose source was not recorded'
        if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
        $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
        $builtIn = @($thresholdKeys | Where-Object { $supplied -notcontains $_ })
        if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
        $merged['ThresholdSource'] = $text
    }
    return $merged
}

# ---------------------------------------------------------------------------
# DC hardening: LDAP signing and channel binding, SMB signing, LAN Manager level (PORT-PLAN C3)
# ---------------------------------------------------------------------------

function New-AdfaDcHardeningRow {
    <#
    .SYNOPSIS
        Pure: one DcHardening finding row. Every row of the section has the same columns, NotRun
        included, so a consumer never has to test whether the column exists.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = ''
    )
    $row = New-Finding -Scope $Scope -Area 'DCHardening' -Item $Item -Status $Status -Detail $Detail
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    return $row
}

function ConvertTo-AdfaNullableBoolean {
    <#
    .SYNOPSIS
        Pure: a CIM boolean as $true or $false, or $null when it is neither. A property that was
        not returned is not False.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [bool]) { return [bool]$Value }
    $text = ([string]$Value).Trim()
    if ($text -ieq 'true') { return $true }
    if ($text -ieq 'false') { return $false }
    return $null
}

function Resolve-AdfaHardeningRead {
    <#
    .SYNOPSIS
        Pure: one GetDWORDValue result as a state - a number, "not set", or the named reason
        there is no number.
    .DESCRIPTION
        Kind is one of:
          Value         the provider returned 0 and a number.
          NotSet        it returned 1, read as the value not being set under a key that exists.
          KeyAbsent     it returned 2, read as the key not existing.
          AccessDenied  it returned 5 or 0x80041003, or the call threw a refusal.
          TypeMismatch  it returned 0x80041005: the value exists and is not a REG_DWORD.
          ReadFailed    anything else, including a return of 0 that carried no number.
        The classes come from Get-AdfaStdRegReturnClass, which DcDisk uses too.

        Number is $null for every Kind but Value. It is never 0 by default: for four of the six
        settings 0 means "disabled", so a missing number read as 0 would turn "not measured"
        into a finding.

        The reading of 1 and 2 is MEASURED, NOT PUBLISHED, and every row that relies on it says
        so. See Get-AdfaStdRegDwordValue for what Microsoft publishes and what was measured.
    .OUTPUTS
        [pscustomobject] Kind, Number ([int64] or $null), Cause ('' for Value and NotSet).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Entry)
    $out = [pscustomobject]@{ Kind = 'ReadFailed'; Number = $null; Cause = '' }
    if ($null -eq $Entry) {
        $out.Cause = 'Read failed: no result was returned for this registry value.'
        return $out
    }
    $rights = 'Local Administrators rights on the DC are needed for this read.'
    $measured = 'This reading is measured, not published by Microsoft: on the one host where it was measured (a Windows 11 workstation, not a domain controller) GetDWORDValue returns 1 for a value that is not set under a key that exists, and 2 for a key that does not exist.'
    $errorText = [string](Get-AdfaConfigValue -Entry $Entry -Name 'Error')
    $errorCode = [string](Get-AdfaConfigValue -Entry $Entry -Name 'ErrorCode')
    $class = Get-AdfaStdRegReturnClass -ReturnValue (Get-AdfaConfigValue -Entry $Entry -Name 'ReturnValue') -ErrorText $errorText -ErrorCode $errorCode
    $kind = [string]$class.Class
    if ($class.Threw) {
        if ($kind -eq 'AccessDenied') {
            $out.Kind = 'AccessDenied'
            $out.Cause = ("Access denied: the registry read was refused. {0} Reported by the DC - {1}" -f $rights, $errorText)
        }
        else { $out.Cause = ("Read failed: the registry read did not complete. Reported by the DC - {0}" -f $errorText) }
        return $out
    }
    if ($kind -eq 'NoReturnCode') {
        $out.Cause = 'Read failed: the registry provider returned no return code, so whether the value was read is not known.'
        return $out
    }
    $code = [int64]$class.Code
    if ($kind -eq 'AccessDenied') {
        $out.Kind = 'AccessDenied'
        if ($code -eq 5) { $out.Cause = ("Access denied: StdRegProv returned 5, which WinError.h defines as ERROR_ACCESS_DENIED. {0}" -f $rights) }
        else { $out.Cause = ("Access denied: StdRegProv returned 2147749891 (0x80041003), which WbemErrorEnum defines as wbemErrAccessDenied. {0}" -f $rights) }
        return $out
    }
    if ($kind -eq 'ValueNotSet') {
        $out.Kind = 'NotSet'
        return $out
    }
    if ($kind -eq 'KeyAbsent') {
        $out.Kind = 'KeyAbsent'
        $out.Cause = ("Not found: StdRegProv returned 2, which WinError.h defines as ERROR_FILE_NOT_FOUND, read here as the registry key not existing on this DC. {0}" -f $measured)
        return $out
    }
    if ($kind -eq 'TypeMismatch') {
        $out.Kind = 'TypeMismatch'
        $out.Cause = 'The value is present but is not a REG_DWORD: StdRegProv returned 2147749893 (0x80041005), which WbemErrorEnum defines as wbemErrTypeMismatch, so no number was read.'
        return $out
    }
    if ($kind -ne 'Success') {
        $hex = ''
        if ($code -gt 0 -and $code -le 4294967295) { $hex = (" (0x{0})" -f $code.ToString('X8', [System.Globalization.CultureInfo]::InvariantCulture)) }
        $out.Cause = ("Read failed: StdRegProv returned {0}{1}. Microsoft documents a nonzero return as an error code from WinError.h or WbemErrorEnum and does not publish which code this provider returns for which condition, so the code is quoted and not interpreted." -f $code, $hex)
        return $out
    }
    $value = Get-AdfaConfigValue -Entry $Entry -Name 'Value'
    if ($null -eq $value -or ([string]$value).Trim() -eq '') {
        $out.Cause = 'Read failed: StdRegProv returned 0 but no value, so no number was read.'
        return $out
    }
    $number = [int64]0
    if (-not [int64]::TryParse(([string]$value).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$number)) {
        $out.Cause = ("Read failed: StdRegProv returned 0 with a value that is not a number ('{0}')." -f [string]$value)
        return $out
    }
    $out.Kind = 'Value'
    $out.Number = $number
    return $out
}

function Resolve-AdfaHardeningDefault {
    <#
    .SYNOPSIS
        Pure: what Microsoft documents for a hardening value that is NOT SET, on a DC of a
        given OS build - or that it documents nothing usable, and why.
    .DESCRIPTION
        The setting's Defaults rows are keyed on a build range. The row whose range holds the
        build decides: a Known row gives the default (Value where Microsoft publishes the
        number, otherwise Meets), a row that is not Known gives the reason no default is known.
        A build that was not read, or one no row covers, has no documented default: an absent
        value is then neither a pass nor a failure, it is not known.
    .OUTPUTS
        [pscustomobject] Known, Value ([int64] or $null), Meets ($true, $false or $null),
        Label, Source, Reason ('' when Known).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Setting,
        [AllowNull()]$Build
    )
    $out = [pscustomobject]@{ Known = $false; Value = $null; Meets = $null; Label = ''; Source = ''; Reason = '' }
    if ($null -eq $Build) {
        $out.Reason = 'the default depends on the OS build, which was not read from this DC'
        return $out
    }
    $number = [int64]$Build
    foreach ($row in @(Get-AdfaConfigValue -Entry $Setting -Name 'Defaults')) {
        if ($null -eq $row) { continue }
        $min = Get-AdfaConfigValue -Entry $row -Name 'MinBuild'
        $max = Get-AdfaConfigValue -Entry $row -Name 'MaxBuild'
        if ($null -ne $min -and $number -lt [int64]$min) { continue }
        if ($null -ne $max -and $number -gt [int64]$max) { continue }
        $out.Source = [string](Get-AdfaConfigValue -Entry $row -Name 'Source')
        if (-not [bool](Get-AdfaConfigValue -Entry $row -Name 'Known')) {
            $out.Reason = [string](Get-AdfaConfigValue -Entry $row -Name 'Reason')
            return $out
        }
        $out.Known = $true
        $out.Label = [string](Get-AdfaConfigValue -Entry $row -Name 'Label')
        $value = Get-AdfaConfigValue -Entry $row -Name 'Value'
        if ($null -ne $value) { $out.Value = [int64]$value }
        $meets = Get-AdfaConfigValue -Entry $row -Name 'Meets'
        if ($null -ne $meets) { $out.Meets = [bool]$meets }
        return $out
    }
    # No row covers the build. The ranges are read from the setting's own rows, not written
    # here: they differ per setting (the LAN Manager level has a lower bound the others lack),
    # and a fixed sentence would contradict itself for a build below that bound.
    $ranges = @()
    foreach ($row in @(Get-AdfaConfigValue -Entry $Setting -Name 'Defaults')) {
        if ($null -eq $row) { continue }
        $min = Get-AdfaConfigValue -Entry $row -Name 'MinBuild'
        $max = Get-AdfaConfigValue -Entry $row -Name 'MaxBuild'
        if ($null -ne $min -and $null -ne $max) { $ranges += ("builds {0} to {1}" -f [int64]$min, [int64]$max) }
        elseif ($null -ne $max) { $ranges += ("build {0} and below" -f [int64]$max) }
        elseif ($null -ne $min) { $ranges += ("build {0} and later" -f [int64]$min) }
    }
    $covered = 'they say nothing for any build'
    if ($ranges.Count -gt 0) { $covered = ("what they say about this value when it is not set is for {0} only" -f ($ranges -join ', and for ')) }
    $out.Reason = ("Microsoft documents no default for OS build {0} in the pages read: {1}" -f $number, $covered)
    return $out
}

function Get-AdfaHardeningVerdict {
    <#
    .SYNOPSIS
        Pure: the verdict for one hardening setting on one DC. Inputs in, Status and Detail out.
    .DESCRIPTION
        The rule, in order:
          1. A setting documented only from a given OS build (the Windows Server 2025 LDAP
             signing enforcement policy) is Info, "Not applicable", below that build - and
             Not Assessed when the build was not read, because whether it applies is then
             exactly what is not known. Either way the row still says what the read of the
             value itself gave: a refusal, an absent key or a wrong type is not lost behind
             the statement about the build.
          2. A read that gave no number, other than "not set", is Not Assessed with its cause:
             key absent, access denied, wrong type, any other failure. Never Pass.
          3. A number Microsoft publishes no meaning for is Not Assessed.
          4. A number at or above ExpectedMinimum is Pass; below it, the setting's OtherStatus.
          5. A value that is NOT SET is graded on the default Microsoft documents for the DC's
             OS build, and the text says it is a default and not a configured value. Where no
             default is documented - the build was not read, no row covers it, or Microsoft
             leaves it open - it is Not Assessed with that reason.

        Three settings need more than their own value:

          LDAP server signing (LDAPServerIntegrity). From Windows Server 2025 the enforcement
          value decides with it: enforcement on means signing is required whatever this value
          holds; enforcement off means this value decides; neither set means the documented
          2025 default, signing required. A value below 2 with the enforcement value not set
          is Not Assessed: Microsoft documents both that an upgrade preserves the old policy
          and that an unconfigured enforcement policy behaves as Enabled, and the registry does
          not show which applies. 2 passes on every build, because every branch requires it.

          An enforcement value that was read but holds a number that is neither of those two
          settles nothing, and the signing row says that it was read and what it holds; it does
          not call it unread.

          LDAP server signing enforcement (LDAPServerEnforceIntegrity). Not set is the
          documented default, same effect as Enabled - except beside a signing value below 2,
          for the reason above, and except beside a signing value Microsoft publishes no
          meaning for (-RelatedSettings carries the signing setting's Meanings): a number
          nobody documents is not taken to require signing because it is larger than 2.

          SMB server signing. The SMB server's own configuration object is asked for in the
          same session and is a second instrument, where the DC returns one. Where the registry
          value is set, the row is graded on it and the second instrument can only veto: if the
          two disagree the row is Not Assessed. Where it is not set, Microsoft publishes no
          default for a domain controller, so the row is graded on the second instrument, which
          is a measurement; with neither, Not Assessed.

        Nothing here is a statement about the wire. The caller says so in NotRun.
    .OUTPUTS
        [pscustomobject] Status, Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Setting,
        [Parameter(Mandatory)]$State,
        [AllowNull()]$Build,
        # The states of the other settings of the same DC, by setting id.
        [hashtable]$Related = @{},
        # Read ([bool]), Value ($true / $false) and Error, or $null where there is none.
        [AllowNull()]$SecondInstrument = $null,
        # The config rows of the other settings, by setting id: where a verdict rests on
        # another setting's number, that number's published meanings come from here. A
        # setting that is not supplied has no published meaning as far as this function knows.
        [hashtable]$RelatedSettings = @{}
    )
    $name = [string](Get-AdfaConfigValue -Entry $Setting -Name 'ValueName')
    $minimum = [int64](Get-AdfaConfigValue -Entry $Setting -Name 'ExpectedMinimum')
    $otherStatus = [string](Get-AdfaConfigValue -Entry $Setting -Name 'OtherStatus')
    $meanings = Get-AdfaConfigValue -Entry $Setting -Name 'Meanings'
    $kind = [string]$State.Kind
    $pass = $script:Status.Pass
    $notAssessed = $script:Status.NotAssessed

    # ---- 1. Does the policy exist on this build at all?
    $appliesFrom = Get-AdfaConfigValue -Entry $Setting -Name 'AppliesFromBuild'
    if ($null -ne $appliesFrom) {
        $release = [string](Get-AdfaConfigValue -Entry $Setting -Name 'AppliesFromLabel')
        # What the read of the value itself gave. It is said in both rows below, so that a
        # refusal, an absent key or a wrong type stays a distinct result of this row.
        $readGave = ''
        if ($kind -ne 'Value' -and $kind -ne 'NotSet') {
            $readGave = ([string]$State.Cause).Trim()
            if ($readGave -eq '') { $readGave = ("Read failed: no number was read for {0}." -f $name) }
        }
        if ($null -eq $Build) {
            $applies = ("depends on the OS build, which was not read from this DC: Microsoft documents it only for {0} (build {1}) and later." -f $release, [int64]$appliesFrom)
            if ($readGave -ne '') {
                return [pscustomobject]@{ Status = $notAssessed; Detail = ("{0} Whether this policy applies at all also {1}" -f $readGave, $applies) }
            }
            $found = ("{0} is not set in the registry of this DC." -f $name)
            if ($kind -eq 'Value') { $found = ("{0} = {1} on this DC." -f $name, [int64]$State.Number) }
            return [pscustomobject]@{ Status = $notAssessed; Detail = ("{0} Whether this policy applies {1}" -f $found, $applies) }
        }
        if ([int64]$Build -lt [int64]$appliesFrom) {
            $present = ''
            if ($kind -eq 'Value') { $present = (" The value is present on this DC ({0} = {1}); whether an earlier release honours it is not published." -f $name, [int64]$State.Number) }
            elseif ($readGave -ne '') { $present = (" The value itself was not read on this DC - {0}" -f $readGave) }
            return [pscustomobject]@{ Status = $script:Status.Info
                Detail = ("Not applicable: this DC runs OS build {0}, and Microsoft documents this policy only for {1} (build {2}) and later.{3}" -f [int64]$Build, $release, [int64]$appliesFrom, $present) }
        }
    }

    # ---- 2. A read that gave no number and is not "not set".
    if ($kind -ne 'Value' -and $kind -ne 'NotSet') {
        return [pscustomobject]@{ Status = $notAssessed; Detail = [string]$State.Cause }
    }

    # ---- 3. A number with no published meaning.
    $number = $null
    $own = ("{0} is not set in the registry of this DC" -f $name)
    if ($kind -eq 'Value') {
        $number = [int64]$State.Number
        if ($null -eq $meanings -or -not $meanings.ContainsKey([string]$number)) {
            $documented = @()
            if ($null -ne $meanings) { $documented = @($meanings.Keys | ForEach-Object { [int64]$_ } | Sort-Object) }
            return [pscustomobject]@{ Status = $notAssessed
                Detail = ("{0} = {1}. Microsoft publishes no meaning for this number (documented values: {2}), so it is not graded." -f $name, $number, ($documented -join ', ')) }
        }
        $own = ("{0} = {1} ({2})" -f $name, $number, [string]$meanings[[string]$number])
    }
    $expected = ("{0}" -f $minimum)
    if ($null -ne $meanings -and $meanings.ContainsKey([string]$minimum)) { $expected = ("{0} ({1})" -f $minimum, [string]$meanings[[string]$minimum]) }
    $meets = ($kind -eq 'Value' -and $number -ge $minimum)

    # The plain grade of a value that is set.
    $valueStatus = $otherStatus
    $valueDetail = ("{0}. Below the expected minimum of {1}." -f $own, $expected)
    if ($meets) {
        $valueStatus = $pass
        $valueDetail = ("{0}. Meets the expected minimum of {1}." -f $own, $expected)
    }
    # The plain grade of a value that is not set: the documented default, or not known.
    $default = Resolve-AdfaHardeningDefault -Setting $Setting -Build $Build
    $defaultStatus = $notAssessed
    $defaultDetail = ("{0}, and the default in force is not known: {1}." -f $own, [string]$default.Reason)
    if ([string]$default.Source -ne '') { $defaultDetail = ("{0} Source: {1}." -f $defaultDetail, [string]$default.Source) }
    if ($default.Known) {
        $defaultMeets = $false
        if ($null -ne $default.Value) { $defaultMeets = ([int64]$default.Value -ge $minimum) }
        elseif ($null -ne $default.Meets) { $defaultMeets = [bool]$default.Meets }
        $defaultStatus = $otherStatus
        $compare = 'is below'
        if ($defaultMeets) { $defaultStatus = $pass; $compare = 'meets' }
        $defaultDetail = ("{0}. Microsoft documents the default for this OS build as '{1}'; the row is graded on that documented default, not on a configured value: it {2} the expected minimum of {3}. Default source: {4}." -f $own, [string]$default.Label, $compare, $expected, [string]$default.Source)
    }

    # ---- LDAP server signing: the Windows Server 2025 enforcement value decides with it.
    $overriddenBy = [string](Get-AdfaConfigValue -Entry $Setting -Name 'OverriddenBy')
    if ($overriddenBy -ne '' -and -not $meets) {
        $otherName = [string](Get-AdfaConfigValue -Entry $Setting -Name 'OverriddenByValueName')
        $fromBuild = [int64](Get-AdfaConfigValue -Entry $Setting -Name 'OverriddenFromBuild')
        if ($null -eq $Build -and $kind -eq 'Value') {
            return [pscustomobject]@{ Status = $notAssessed
                Detail = ("{0}. Below the expected minimum of {1}, but from Windows Server 2025 (build {2}) the enforcement policy ({3}) can override this value, and the OS build was not read from this DC, so whether signing is required is not known." -f $own, $expected, $fromBuild, $otherName) }
        }
        if ($null -ne $Build -and [int64]$Build -ge $fromBuild) {
            $otherKind = 'Unread'
            $otherNumber = $null
            if ($Related.ContainsKey($overriddenBy) -and $null -ne $Related[$overriddenBy]) {
                $otherKind = [string]$Related[$overriddenBy].Kind
                if ($otherKind -eq 'Value') { $otherNumber = [int64]$Related[$overriddenBy].Number }
            }
            $on = [int64](Get-AdfaConfigValue -Entry $Setting -Name 'OverrideOnValue')
            $off = [int64](Get-AdfaConfigValue -Entry $Setting -Name 'OverrideOffValue')
            if ($otherKind -eq 'Value' -and $otherNumber -eq $on) {
                return [pscustomobject]@{ Status = $pass
                    Detail = ("LDAP signing is required whatever this value holds: {0} = {1} on this DC, and Microsoft documents that the enforcement policy takes precedence over the signing requirements policy and requires LDAP signing regardless of it. {2}." -f $otherName, $on, $own) }
            }
            if ($otherKind -eq 'Value' -and $otherNumber -eq $off) {
                if ($kind -eq 'Value') {
                    return [pscustomobject]@{ Status = $otherStatus
                        Detail = ("{0} {1} = {2} on this DC, read as the enforcement policy being Disabled (inferred: Microsoft publishes no value table for it), in which case Microsoft documents that this value determines the requirement." -f $valueDetail, $otherName, $off) }
                }
                return [pscustomobject]@{ Status = $notAssessed
                    Detail = ("{0}, and {1} = {2}, read as the enforcement policy being Disabled (inferred). Microsoft documents that the signing requirements policy then determines the requirement, and separately that Windows Server 2025 requires signing where no server signing policy exists; it does not say which holds when the enforcement policy is Disabled and no signing value is present." -f $own, $otherName, $off) }
            }
            if ($otherKind -eq 'NotSet') {
                if ($kind -eq 'NotSet') {
                    # Both absent: the documented default of the release. Fall through to it,
                    # naming the second value so the reader sees what the default rests on.
                    if ($default.Known) { $defaultDetail = ("{0} {1} is not set either." -f $defaultDetail, $otherName) }
                    return [pscustomobject]@{ Status = $defaultStatus; Detail = $defaultDetail }
                }
                return [pscustomobject]@{ Status = $notAssessed
                    Detail = ("{0}, and {1} is not set. Microsoft documents both that an upgrade to Windows Server 2025 preserves an existing LDAP signing policy and that an enforcement policy left Not Configured has the same effect as Enabled. The registry does not show which applies, so whether signing is required is not known." -f $own, $otherName) }
            }
            if ($otherKind -eq 'Value') {
                # Read, and neither of the two numbers that settle the matter. It was read:
                # the row must not call it unread.
                return [pscustomobject]@{ Status = $notAssessed
                    Detail = ("{0}. On this OS build whether signing is required also depends on {1}, which holds {2} on this DC: neither {3}, read as the enforcement policy being Enabled, nor {4}, read as Disabled (see that row). That number settles nothing, so whether signing is required is not known." -f $own, $otherName, $otherNumber, $on, $off) }
            }
            return [pscustomobject]@{ Status = $notAssessed
                Detail = ("{0}. On this OS build whether signing is required also depends on {1}, which was not read on this DC (see that row)." -f $own, $otherName) }
        }
    }

    # ---- LDAP server signing enforcement, not set: the default, unless a legacy value is beside it.
    $governs = [string](Get-AdfaConfigValue -Entry $Setting -Name 'Governs')
    if ($governs -ne '' -and $kind -eq 'NotSet' -and $default.Known) {
        $otherName = [string](Get-AdfaConfigValue -Entry $Setting -Name 'GovernsValueName')
        $governedMinimum = [int64](Get-AdfaConfigValue -Entry $Setting -Name 'GovernedMinimum')
        $otherKind = 'Unread'
        $otherNumber = $null
        if ($Related.ContainsKey($governs) -and $null -ne $Related[$governs]) {
            $otherKind = [string]$Related[$governs].Kind
            if ($otherKind -eq 'Value') { $otherNumber = [int64]$Related[$governs].Number }
        }
        if ($otherKind -eq 'NotSet') {
            return [pscustomobject]@{ Status = $defaultStatus
                Detail = ("{0} {1} is not set either, and Microsoft documents that Windows Server 2025 requires LDAP signing where no server signing policy exists." -f $defaultDetail, $otherName) }
        }
        # The governed value counts only as a number Microsoft publishes a meaning for. A
        # number it does not document (3, 4294967295 ...) is not "at least 2, so signing is
        # required": the signing row reports that number as Not Assessed, and this row must
        # not assert as fact what that one says is unknown. With the governed setting's
        # meanings not supplied, no number is taken as documented.
        $otherDocumented = $false
        $otherDocumentedList = ''
        if ($otherKind -eq 'Value' -and $RelatedSettings.ContainsKey($governs) -and $null -ne $RelatedSettings[$governs]) {
            $otherMeanings = Get-AdfaConfigValue -Entry $RelatedSettings[$governs] -Name 'Meanings'
            if ($null -ne $otherMeanings) {
                $otherDocumented = [bool]$otherMeanings.ContainsKey([string]$otherNumber)
                $otherDocumentedList = (@($otherMeanings.Keys | ForEach-Object { [int64]$_ } | Sort-Object) -join ', ')
            }
        }
        if ($otherKind -eq 'Value' -and -not $otherDocumented) {
            $why = ("the published meanings of {0} were not available to this verdict" -f $otherName)
            if ($otherDocumentedList -ne '') { $why = ("a number Microsoft publishes no meaning for (documented values: {0}; see that row)" -f $otherDocumentedList) }
            return [pscustomobject]@{ Status = $notAssessed
                Detail = ("{0}, and {1} = {2}: {3}. What that value requires is not known, so the documented default of this policy ('{4}') is not applied beside it." -f $own, $otherName, $otherNumber, $why, [string]$default.Label) }
        }
        if ($otherKind -eq 'Value' -and $otherNumber -ge $governedMinimum) {
            return [pscustomobject]@{ Status = $defaultStatus
                Detail = ("{0} {1} = {2} on this DC requires signing whichever of the two policies decides." -f $defaultDetail, $otherName, $otherNumber) }
        }
        if ($otherKind -eq 'Value') {
            return [pscustomobject]@{ Status = $notAssessed
                Detail = ("{0}, and {1} = {2}. Microsoft documents both that an upgrade to Windows Server 2025 preserves an existing LDAP signing policy and that an enforcement policy left Not Configured has the same effect as Enabled. The registry does not show which applies, so whether the enforcement is in force is not known." -f $own, $otherName, $otherNumber) }
        }
        return [pscustomobject]@{ Status = $notAssessed
            Detail = ("{0}. Whether the documented default ('{1}') is what is in force depends on {2}, which was not read on this DC (see that row)." -f $own, [string]$default.Label, $otherName) }
    }

    # ---- SMB server signing: the SMB server's own configuration is a second instrument.
    $second = [string](Get-AdfaConfigValue -Entry $Setting -Name 'SecondInstrument')
    if ($second -ne '') {
        $secondValue = $null
        $secondError = ''
        if ($null -ne $SecondInstrument) {
            if ([bool](Get-AdfaConfigValue -Entry $SecondInstrument -Name 'Read')) { $secondValue = ConvertTo-AdfaNullableBoolean -Value (Get-AdfaConfigValue -Entry $SecondInstrument -Name 'Value') }
            $secondError = [string](Get-AdfaConfigValue -Entry $SecondInstrument -Name 'Error')
        }
        $notRead = ("The second instrument, {0}, was not read" -f $second)
        if ($secondError -ne '') { $notRead = ("{0} ({1})" -f $notRead, $secondError.Trim().TrimEnd('.')) }
        if ($kind -eq 'Value') {
            if ($null -eq $secondValue) { return [pscustomobject]@{ Status = $valueStatus; Detail = ("{0} {1}." -f $valueDetail, $notRead) } }
            if ([bool]$secondValue -ne [bool]$meets) {
                return [pscustomobject]@{ Status = $notAssessed
                    Detail = ("The two instruments disagree: {0}, but the SMB server's own configuration reports {1} = {2}. Which of them describes this DC is not known, so the row is not graded." -f $own, $second, [bool]$secondValue) }
            }
            return [pscustomobject]@{ Status = $valueStatus; Detail = ("{0} The second instrument agrees: {1} = {2}." -f $valueDetail, $second, [bool]$secondValue) }
        }
        if ($null -ne $secondValue) {
            $measuredStatus = $otherStatus
            $measuredWord = 'not required'
            if ([bool]$secondValue) { $measuredStatus = $pass; $measuredWord = 'required' }
            return [pscustomobject]@{ Status = $measuredStatus
                Detail = ("{0}, and Microsoft does not publish what that means on a domain controller. The row is graded on the SMB server's own configuration instead, which is a measurement and not a default: {1} = {2}, read here as signing being {3}. Microsoft's documented check of this property is the cmdlet Get-SmbServerConfiguration, which is what was run here, in the session opened to this DC." -f $own, $second, [bool]$secondValue, $measuredWord) }
        }
        return [pscustomobject]@{ Status = $defaultStatus; Detail = ("{0} {1}." -f $defaultDetail, $notRead) }
    }

    # ---- The plain rule.
    if ($kind -eq 'Value') { return [pscustomobject]@{ Status = $valueStatus; Detail = $valueDetail } }
    return [pscustomobject]@{ Status = $defaultStatus; Detail = $defaultDetail }
}

function Get-AdfaSpoolerVerdict {
    <#
    .SYNOPSIS
        Pure: the Print Spooler row from one DC's raw read. Status and Detail.
    .DESCRIPTION
        The rule the section has always had - Running is a Warning, Stopped is a Pass - now
        read from Win32_Service in the section's one CIM session, where it was Get-Service
        -ComputerName, a parameter PowerShell 7 does not have. State is one of the strings the
        class documents ("Stopped", "Start Pending", "Stop Pending", "Running", "Continue
        Pending", "Pause Pending", "Paused", "Unknown") and StartMode one of "Boot", "System",
        "Auto", "Manual", "Disabled":
          https://learn.microsoft.com/windows/win32/cimwin32prov/win32-service
          Read: 2026-11-13.
        Fail closed where the old code was not: no service returned, or a state that is empty
        or "Unknown", is Not Assessed, never a Pass. Any other state that is not Stopped is a
        Warning. A service that is Stopped but not Disabled is still a Pass, as before, and the
        row says its start mode: grading the start mode is PORT-PLAN C3b.

        "Domain controllers and Active Directory admin systems need to have the Print spooler
        service disabled":
          https://learn.microsoft.com/defender-for-identity/security-posture-assessments/identity-infrastructure
          Read: 2026-11-13.
    .OUTPUTS
        [pscustomobject] Status, Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)]$Raw)
    $notAssessed = $script:Status.NotAssessed
    if (-not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'SpoolerOk')) {
        $errorText = [string](Get-AdfaConfigValue -Entry $Raw -Name 'SpoolerError')
        $lead = 'Read failed: the service list (Win32_Service) could not be read.'
        if ((Get-AdfaRemoteReadErrorClass -Message $errorText -ErrorCode ([string](Get-AdfaConfigValue -Entry $Raw -Name 'SpoolerErrorCode'))) -eq 'AccessDenied') {
            $lead = 'Access denied: the service list (Win32_Service) could not be read. Local Administrators rights on the DC are needed for this read.'
        }
        return [pscustomobject]@{ Status = $notAssessed; Detail = ("{0} Reported by the DC - {1}" -f $lead, $errorText) }
    }
    if (-not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'SpoolerFound')) {
        return [pscustomobject]@{ Status = $notAssessed
            Detail = 'Win32_Service returned no service named Spooler on this DC. Whether the Print Spooler is absent or the query returned nothing for another reason is not known, so this is not reported as a pass.' }
    }
    $state = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'SpoolerState')).Trim()
    $mode = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'SpoolerStartMode')).Trim()
    $modeText = 'start mode not returned'
    if ($mode -ne '') { $modeText = ("start mode {0}" -f $mode) }
    if ($state -eq '' -or $state -ieq 'Unknown') {
        return [pscustomobject]@{ Status = $notAssessed
            Detail = ("The Print Spooler service was returned without a usable state ('{0}', {1}), so whether it is running is not known." -f $state, $modeText) }
    }
    $guidance = 'Microsoft''s guidance is that domain controllers need to have the Print Spooler service disabled.'
    if ($state -ieq 'Stopped') {
        $note = ''
        if ($mode -ne '' -and $mode -ine 'Disabled') { $note = (" It is stopped now, but its start mode is {0}, not Disabled, so it can be started again; that is stated here and not graded." -f $mode) }
        return [pscustomobject]@{ Status = $script:Status.Pass; Detail = ("Print Spooler is Stopped ({0}).{1}" -f $modeText, $note) }
    }
    if ($state -ieq 'Running') {
        return [pscustomobject]@{ Status = $script:Status.Warning; Detail = ("Print Spooler is Running ({0}). {1}" -f $modeText, $guidance) }
    }
    return [pscustomobject]@{ Status = $script:Status.Warning; Detail = ("Print Spooler is {0} ({1}), which is not Stopped. {2}" -f $state, $modeText, $guidance) }
}

function Resolve-AdfaSmbServerRead {
    <#
    .SYNOPSIS
        Pure: one DC's SMB server configuration read (the Smb* fields of Get-AdfaDcHardeningRaw)
        as one kind, with the two raw values and the cause. It feeds both the SMBv1 row and the
        second instrument of the SMB server signing row (PORT-PLAN C3f).
    .DESCRIPTION
        Kind is one of:
          Read           the cmdlet returned one configuration object. The two values are
                         passed on as returned - never defaulted - and judged by the callers.
          CmdletMissing  Get-SmbServerConfiguration is not available on the computer running the
                         assessment (no SmbShare module), so the DC was not asked.
          NoInstance     the cmdlet returned nothing and raised no error.
          AccessDenied   refused: CIM code AccessDenied, or the text of a refusal
                         (Get-AdfaRemoteReadErrorClass).
          ClassMissing   the DC reports that the class or its namespace is not there: CIM code
                         InvalidNamespace or InvalidClass, or - only where no code came back -
                         those words in the error text. The code names come from the
                         NativeErrorCode enumeration; which code a DC gives for a missing SMB
                         class is not measured (PORT-PLAN C17a).
          ReadFailed     anything else, the error quoted. Also a read that is marked as not done
                         and carries no error at all, and a cause this tool wrote itself
                         (SmbErrorByTool: more than one configuration object for one DC, or an
                         error raised with no message), whose words are never read as a refusal
                         or a missing class - only a CIM code the exception carried is.
        FAIL CLOSED where the raw read contradicts itself: CmdletMissing, then NoInstance, win
        over any value beside them, so a stray value is never taken for a read.

        CauseSource says who wrote the cause, so a row never credits the DC with this tool's
        own words: 'Error' is the text of an error the read raised; 'Tool' is a sentence this
        tool wrote (cmdlet missing, no object, more than one object, nothing recorded); '' for
        a read.
    .OUTPUTS
        [pscustomobject] Kind, Instrument, EnableSmb1, RequireSigning, Cause, CauseSource, ErrorCode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)]$Raw)
    $instrument = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'SmbInstrument')).Trim()
    if ($instrument -eq '') { $instrument = 'Get-SmbServerConfiguration' }
    $errorText = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'SmbError')).Trim()
    $errorCode = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'SmbErrorCode')).Trim()
    $out = [pscustomobject]@{ Kind = 'ReadFailed'; Instrument = $instrument; EnableSmb1 = $null; RequireSigning = $null; Cause = ''; CauseSource = 'Tool'; ErrorCode = $errorCode }
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'SmbCmdletMissing')) {
        $out.Kind = 'CmdletMissing'
        $out.Cause = ("{0} (module SmbShare) is not available on the computer running the assessment, so the SMB server configuration of this DC was not asked for" -f $instrument)
        return $out
    }
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'SmbNoInstance')) {
        $out.Kind = 'NoInstance'
        $out.Cause = ("{0} returned no configuration object for this DC, and no error" -f $instrument)
        return $out
    }
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'SmbOk')) {
        $out.Kind = 'Read'
        $out.CauseSource = ''
        $out.EnableSmb1 = Get-AdfaConfigValue -Entry $Raw -Name 'SmbEnableSmb1'
        $out.RequireSigning = Get-AdfaConfigValue -Entry $Raw -Name 'SmbRequireSigning'
        return $out
    }
    if ($errorText -eq '') {
        $out.Cause = ("{0} was not recorded as read, and no error was recorded" -f $instrument)
        return $out
    }
    $out.Cause = $errorText
    # A sentence this tool wrote is quoted as the tool's, and never read for the words of a
    # refusal or a missing class; a CIM code the exception carried is still the DC's answer.
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'SmbErrorByTool')) {
        if ($errorCode -match '(?i)^AccessDenied$') { $out.Kind = 'AccessDenied' }
        elseif ($errorCode -match '(?i)^(InvalidNamespace|InvalidClass)$') { $out.Kind = 'ClassMissing' }
        return $out
    }
    $out.CauseSource = 'Error'
    if ((Get-AdfaRemoteReadErrorClass -Message $errorText -ErrorCode $errorCode) -eq 'AccessDenied') { $out.Kind = 'AccessDenied'; return $out }
    $classMissing = $false
    if ($errorCode -ne '') { $classMissing = ($errorCode -match '(?i)^(InvalidNamespace|InvalidClass)$') }
    else { $classMissing = ($errorText -match '(?i)invalid namespace|invalid class') }
    if ($classMissing) { $out.Kind = 'ClassMissing' }
    return $out
}

function Get-AdfaSmb1Verdict {
    <#
    .SYNOPSIS
        Pure: the SMBv1 row from one DC's resolved SMB server read (Resolve-AdfaSmbServerRead).
        Status and Detail.
    .DESCRIPTION
        The rule the section has always had: the SMBv1 server enabled is a Fail. Microsoft's
        documented detection is "Get-SmbServerConfiguration | Select EnableSMB1Protocol", and it
        strongly recommends against using SMBv1:
          https://learn.microsoft.com/windows-server/storage/file-server/troubleshoot/detect-enable-and-disable-smbv1-v2-v3
          https://learn.microsoft.com/windows-server/storage/file-server/troubleshoot/smbv1-not-installed-by-default-in-windows
          Read: 2026-11-17 (both).
        EnableSMB1Protocol "Controls whether SMB1 protocol is enabled" and is a boolean (archived
        class page, https://learn.microsoft.com/previous-versions/windows/desktop/smb/msft-smbserverconfiguration,
        read 2026-11-17).

        PASS ONLY ON A RETURNED FALSE. Every other result is Not Assessed with its own cause:
        the cmdlet missing on the assessing host, access denied, the class not present on the
        DC, a read that failed, nothing returned, and a property that was not returned as true
        or false (quoted). The OS build is never used to infer a pass: Windows Server 2019 and
        later do not install SMBv1 on a clean installation, but nothing is published about an
        upgraded DC. The LanmanServer\Parameters\SMB1 registry value is not read: under its
        heading "Enable or disable SMB on Windows 7, Windows Server 2008 R2, Windows Vista, and
        Windows Server 2008" the detect page says "The default configuration is Enabled. As a
        result, no registry named value is created"; for later builds it publishes no meaning of
        an absent value, so the value could not grade the row where it is not set (PORT-PLAN C3f,
        option (c), not taken; scope re-read 2026-11-18).

        The rights a remote read needs are not published and not measured (PORT-PLAN C17a), so
        the access-denied row does not name any. A cause this tool wrote (CauseSource 'Tool') is
        never said to be reported by the DC.
    .OUTPUTS
        [pscustomobject] Status, Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Read,
        [AllowEmptyString()][string]$Protocol = ''
    )
    $na = $script:Status.NotAssessed
    $instrument = [string](Get-AdfaConfigValue -Entry $Read -Name 'Instrument')
    $cause = ([string](Get-AdfaConfigValue -Entry $Read -Name 'Cause')).Trim()
    $over = (" Read over {0}." -f $Protocol)
    $unknown = 'so whether the SMBv1 server is enabled is not known. This is not a pass.'
    # The quoted cause ends its own sentence, so it never runs into the transport.
    $quoted = $cause
    if ($quoted -ne '' -and $quoted -notmatch '[.!?]$') { $quoted = ("{0}." -f $quoted) }
    $reported = ("Reported by the DC - {0}" -f $quoted)
    if ([string](Get-AdfaConfigValue -Entry $Read -Name 'CauseSource') -ne 'Error') { $reported = ("Written by this tool, not an error from the DC - {0}" -f $quoted) }
    switch ([string](Get-AdfaConfigValue -Entry $Read -Name 'Kind')) {
        'CmdletMissing' {
            return [pscustomobject]@{ Status = $na; Detail = ("Not read: {0}, {1} Run the assessment from a Windows computer that has the SmbShare module.{2}" -f $cause, $unknown, $over) }
        }
        'NoInstance' {
            return [pscustomobject]@{ Status = $na; Detail = ("Not read: {0}, {1}{2}" -f $cause, $unknown, $over) }
        }
        'AccessDenied' {
            return [pscustomobject]@{ Status = $na; Detail = ("Access denied: {0} could not read the SMB server configuration of this DC, {1} Which rights this read needs on a DC is not published and has not been measured (PORT-PLAN C17a). {2}{3}" -f $instrument, $unknown, $reported, $over) }
        }
        'ClassMissing' {
            return [pscustomobject]@{ Status = $na; Detail = ("Not read: the DC reports that the SMB server configuration class (MSFT_SmbServerConfiguration, namespace root/Microsoft/Windows/SMB) or its namespace is not present, {0} {1}{2}" -f $unknown, $reported, $over) }
        }
        'Read' {
            $raw = Get-AdfaConfigValue -Entry $Read -Name 'EnableSmb1'
            $smb1 = ConvertTo-AdfaNullableBoolean -Value $raw
            if ($null -eq $smb1) {
                return [pscustomobject]@{ Status = $na; Detail = ("EnableSMB1Protocol was not returned as true or false by {0} on this DC (returned: '{1}'), {2}{3}" -f $instrument, [string]$raw, $unknown, $over) }
            }
            if ($smb1) {
                return [pscustomobject]@{ Status = $script:Status.Fail; Detail = ("EnableSMB1Protocol = True: the SMBv1 server is enabled on this DC, as {0} reports it.{1}" -f $instrument, $over) }
            }
            return [pscustomobject]@{ Status = $script:Status.Pass; Detail = ("EnableSMB1Protocol = False: the SMBv1 server is not enabled on this DC, as {0} reports it.{1}" -f $instrument, $over) }
        }
    }
    return [pscustomobject]@{ Status = $na; Detail = ("Read failed: {0} did not return the SMB server configuration of this DC, {1} {2}{3}" -f $instrument, $unknown, $reported, $over) }
}

function Get-AdfaDcHardeningFinding {
    <#
    .SYNOPSIS
        Pure: one DC's raw read (Get-AdfaDcHardeningRaw) as finding rows.
    .DESCRIPTION
        DECLARED POPULATION: one row for every setting in the config table, then Print Spooler,
        then SMBv1. A setting the read returned nothing for gets its own Not Assessed row, so
        a setting is never silently absent.

        Item is "<family>: <dc>", family first, so the recommendation map can anchor on the
        family and nothing after the colon - a host name, an error text, an override file path
        - can choose the advice.

        Every row carries the raw read (value name, number, key, OS build, transport), which is
        the inventory the AdAssessment26 catalogue lists as ADA-INV-019.

        Two things that are not Microsoft's are said in the row that relies on them. A setting
        whose registry path is not a published fact (KeyNote in the table: LDAPServerIntegrity
        under NTDS\Parameters) says so in every one of its rows, whatever the verdict. And a row
        graded below the expectation says that its status is a tool default or the operator's
        override, not a Microsoft value.

        The six setting rows say in NotRun, not in Detail, that nothing was tested on the wire:
        a registry value is the configured policy. For LDAP, signing applies to non-TLS SASL
        binds only and channel binding to TLS with SASL only; for SMB, "Signing doesn't occur
        only when both the server and client have signing set to 0", so one side's value does
        not settle what a connection does. Microsoft's own live check of LDAP signing, a simple
        bind on port 389, "sends simple-bind credentials without TLS. Run it only in an
        isolated lab" - which is why no bind is attempted here:
          https://learn.microsoft.com/windows-server/identity/manage-ldap-signing-group-policy
          https://learn.microsoft.com/windows-server/storage/file-server/smb-signing-overview
          Read: 2026-11-13 (both).

        The SMBv1 row keeps its rule (enabled is a Fail) and fails closed: anything but a
        returned False is never a Pass. Since PORT-PLAN C3f it is read the way Microsoft
        documents, "Get-SmbServerConfiguration | Select EnableSMB1Protocol":
          https://learn.microsoft.com/windows-server/storage/file-server/troubleshoot/detect-enable-and-disable-smbv1-v2-v3
          Read: 2026-11-17.
        The one read is resolved once (Resolve-AdfaSmbServerRead) and feeds both the SMBv1 row
        (Get-AdfaSmb1Verdict) and the SMB server signing row's second instrument, so the two
        rows always describe the same answer: the cmdlet missing on the assessing host, access
        denied, the class not present, a failed read, no object, and a property not returned
        are each their own Not Assessed cause.
    .OUTPUTS
        [pscustomobject[]] Finding rows (Scope, Area, Item, Status, Detail, NotRun).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)]$Raw,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    $protocol = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Protocol')
    $settings = @(@($Config['Settings']) | Where-Object { $null -ne $_ })
    $values = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Values') | Where-Object { $null -ne $_ })

    # The OS build, as the DC itself reported it. Not a number, or not returned: not known.
    $build = $null
    $buildText = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'BuildNumber')).Trim()
    $buildNote = ''
    $parsed = 0
    if ($buildText -ne '' -and [int]::TryParse($buildText, [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsed) -and $parsed -gt 0) {
        $build = $parsed
        $buildNote = ("OS build {0}." -f $build)
    }
    else {
        $why = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'BuildError')).Trim()
        if ($why -eq '' -and $buildText -ne '') { $why = ("the DC returned '{0}', which is not a build number" -f $buildText) }
        if ($why -eq '') { $why = 'Win32_OperatingSystem returned no build number' }
        $buildNote = ("OS build not read ({0})" -f $why)
        if (-not $buildNote.EndsWith('.)')) { $buildNote = $buildNote + '.' }
    }

    # Every setting's state first: two of the verdicts need another setting's state - and, for
    # the number it holds, that setting's published meanings.
    $states = @{}
    $settingsById = @{}
    foreach ($setting in $settings) {
        $id = [string](Get-AdfaConfigValue -Entry $setting -Name 'Id')
        $settingsById[$id] = $setting
        $entry = $null
        foreach ($v in $values) {
            if ([string](Get-AdfaConfigValue -Entry $v -Name 'Id') -eq $id) { $entry = $v; break }
        }
        $states[$id] = Resolve-AdfaHardeningRead -Entry $entry
    }

    # The SMB server configuration, read once with Get-SmbServerConfiguration (PORT-PLAN C3f):
    # one resolved read feeds the SMBv1 row and the second instrument of SMB server signing.
    $smbRead = Resolve-AdfaSmbServerRead -Raw $Raw
    $smbSigning = $null
    $smbWhy = ''
    switch ([string]$smbRead.Kind) {
        'Read' {
            $smbSigning = ConvertTo-AdfaNullableBoolean -Value $smbRead.RequireSigning
            if ($null -eq $smbSigning) { $smbWhy = ("RequireSecuritySignature was not returned as true or false (returned: '{0}')" -f [string]$smbRead.RequireSigning) }
        }
        'AccessDenied' { $smbWhy = ("access denied - {0}" -f [string]$smbRead.Cause) }
        'ClassMissing' { $smbWhy = ("the SMB server configuration class or its namespace is not present on this DC - {0}" -f [string]$smbRead.Cause) }
        'ReadFailed' { $smbWhy = ("the read failed - {0}" -f [string]$smbRead.Cause) }
        default { $smbWhy = [string]$smbRead.Cause }
    }
    $secondInstrument = [pscustomobject]@{ Read = ($null -ne $smbSigning); Value = $smbSigning; Error = $smbWhy }
    $smbSource = ''
    $smbTable = Get-AdfaConfigValue -Entry $Config -Name 'SmbServer'
    if ($null -ne $smbTable) {
        $smbUrl = ([string](Get-AdfaConfigValue -Entry $smbTable -Name 'SourceUrl')).Trim()
        if ($smbUrl -ne '') { $smbSource = (" Detection as Microsoft documents it: {0} (read {1})." -f $smbUrl, [string](Get-AdfaConfigValue -Entry $smbTable -Name 'ReadDate')) }
    }

    $measured = 'The reading of return code 1 as "not set" is measured, not published by Microsoft: on the one host where it was measured (a Windows 11 workstation, not a domain controller) GetDWORDValue returns 1 for a value that is not set under a key that exists.'
    # Said in every row graded below the expectation: the expected VALUE is Microsoft's, the
    # STATUS a DC gets for missing it is not.
    $statusNote = 'The status given to a value below the expectation ({0}) is a tool default or your own override, not a Microsoft value.'
    $wire = 'No LDAP bind, SMB session or NTLM authentication was attempted: this row shows the policy configured in the registry of the DC, which is not necessarily what a client and this DC negotiate on the wire.'
    foreach ($setting in $settings) {
        $id = [string](Get-AdfaConfigValue -Entry $setting -Name 'Id')
        $family = [string](Get-AdfaConfigValue -Entry $setting -Name 'Item')
        $state = $states[$id]
        $verdict = Get-AdfaHardeningVerdict -Setting $setting -State $state -Build $build -Related $states -SecondInstrument $secondInstrument -RelatedSettings $settingsById
        $registry = ("HKLM\{0}\{1}" -f [string](Get-AdfaConfigValue -Entry $setting -Name 'Key'), [string](Get-AdfaConfigValue -Entry $setting -Name 'ValueName'))
        $tail = ("Expectation source: {0}. Registry value: {1}. {2} Read over {3}." -f [string](Get-AdfaConfigValue -Entry $setting -Name 'ExpectedSource'), $registry, $buildNote, $protocol)
        # Said where the verdict rests on the reading of return code 1. A row that is not
        # applicable on this build rests on no reading at all.
        if ([string]$state.Kind -eq 'NotSet' -and [string]$verdict.Status -ne $script:Status.Info) { $tail = ("{0} {1}" -f $tail, $measured) }
        # Where the registry path itself is not a published fact, every row of the setting says so.
        $keyNote = ([string](Get-AdfaConfigValue -Entry $setting -Name 'KeyNote')).Trim()
        if ($keyNote -ne '') { $tail = ("{0} {1}" -f $tail, $keyNote) }
        $belowStatus = [string](Get-AdfaConfigValue -Entry $setting -Name 'OtherStatus')
        if ($belowStatus -ne '' -and [string]$verdict.Status -eq $belowStatus) { $tail = ("{0} {1}" -f $tail, ($statusNote -f $belowStatus)) }
        $rows += New-AdfaDcHardeningRow -Scope $Scope -Item ("{0}: {1}" -f $family, $DomainController) -Status ([string]$verdict.Status) `
            -Detail ("{0} {1}" -f [string]$verdict.Detail, $tail) -NotRun $wire
    }

    # ---- Print Spooler ----
    $spooler = Get-AdfaSpoolerVerdict -Raw $Raw
    $rows += New-AdfaDcHardeningRow -Scope $Scope -Item ("Print Spooler: {0}" -f $DomainController) -Status ([string]$spooler.Status) `
        -Detail ("{0} Read over {1}." -f [string]$spooler.Detail, $protocol)

    # ---- SMBv1 ----
    $smb1Verdict = Get-AdfaSmb1Verdict -Read $smbRead -Protocol $protocol
    $rows += New-AdfaDcHardeningRow -Scope $Scope -Item ("SMBv1: {0}" -f $DomainController) -Status ([string]$smb1Verdict.Status) `
        -Detail ("{0}{1}" -f [string]$smb1Verdict.Detail, $smbSource)
    return @($rows)
}

function Get-AdfaStdRegDwordValue {
    <#
    .SYNOPSIS
        Reads ONE REG_DWORD value from HKEY_LOCAL_MACHINE on a DC through the WMI registry
        provider. The third and last CIM method this script invokes.
    .DESCRIPTION
        READ-ONLY DECISION (PORT-PLAN C3), on the same footing as Get-AdfaStdRegStringValue,
        which records the decision in full. GetDWORDValue "returns the data value for a named
        value whose data type is REG_DWORD"; its signature is
          uint32 GetDWORDValue([in] uint32 hDefKey = HKEY_LOCAL_MACHINE, [in] string sSubKeyName,
                               [in] string sValueName, [out] uint32 uValue)
        and its only [out] parameter is the value:
          https://learn.microsoft.com/previous-versions/windows/desktop/regprov/getdwordvalue-method-in-class-stdregprov
        Microsoft lists it with the methods for reading registry data and names the Set*
        methods separately, as the ones "for creating new keys or values, or changing existing
        ones":
          https://learn.microsoft.com/windows/win32/wmisdk/obtaining-registry-data
          Read: 2026-11-13 (both).
        As for the string methods, no page read says in so many words that the method has no
        side effect; the decision rests on its documented purpose and signature. It is called
        with a LITERAL -MethodName on a literal -ClassName, and a test reads every
        Invoke-CimMethod in this script from the parsed source and fails on any name outside
        the three Get* names. -WhatIf and -Confirm are forced off, which is safe only because
        this is a read: under a WhatIf preference "The cmdlet is not run", and there would be
        nothing to judge.

        The method page lists the namespace as Root\default; the class "is preinstalled in the
        WMI namespaces root\default and root\cimv2", and root/cimv2 is used here because it is
        the namespace the C2 reads were measured in.

        WHAT MICROSOFT PUBLISHES about the return value: 0 for success, otherwise "a nonzero
        error code that is defined in WinError.h". Not which code means what, and not what the
        method returns for a value that exists with another type.

        WHAT WAS MEASURED for this method. On 2026-11-13, on ONE host - a Windows 11 (build
        26100) workstation, not a domain controller, over a local CIM session under PowerShell
        7 - GetDWORDValue returned:
          0            a REG_DWORD value that exists, with uValue as a UInt32
          1            a value that does not exist, under a key that does; uValue null
          2            a key that does not exist
          5            a key the account may not read
          2147749893   (0x80041005) a value that exists and is a string
        The same pattern C2 measured for the two string methods. Whether a domain controller, a
        server release, a DCOM or WSMan session to another host, or Windows PowerShell 5.1
        answers the same way has not been measured (PORT-PLAN C17).

        uValue is absent on every nonzero return. It is therefore never converted to a number
        here unless the return was 0 and a value came back: an absent value must not become 0,
        which for most of these settings means "disabled".

        Never throws. A call that raised comes back with Answered = $false and the error text
        and CIM error code.
    .OUTPUTS
        [pscustomobject] Answered, ReturnValue ($null when not answered), Value ($null unless
        the return was 0 and a value came back), Method, Error, ErrorCode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$CimSession,
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)][string]$ValueName,
        [int]$OperationTimeoutSec = 90
    )
    $out = [pscustomobject]@{ Answered = $false; ReturnValue = $null; Value = $null; Method = 'GetDWORDValue'; Error = ''; ErrorCode = '' }
    # 2147483650 is HKEY_LOCAL_MACHINE, as the method page lists it (defined in WinReg.h).
    $arguments = @{ hDefKey = [uint32]2147483650; sSubKeyName = $Key; sValueName = $ValueName }
    try {
        $result = Invoke-CimMethod -CimSession $CimSession -Namespace 'root/cimv2' -ClassName 'StdRegProv' -MethodName 'GetDWORDValue' `
            -Arguments $arguments -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -WhatIf:$false -Confirm:$false -ErrorAction Stop
        if ($null -eq $result) { throw 'The registry provider returned no result.' }
        $codeProp = $result.PSObject.Properties['ReturnValue']
        if ($null -eq $codeProp -or $null -eq $codeProp.Value) { throw 'The registry provider returned no ReturnValue.' }
        $out.ReturnValue = [int64]$codeProp.Value
        if ($out.ReturnValue -eq 0) {
            $valueProp = $result.PSObject.Properties['uValue']
            if ($null -ne $valueProp -and $null -ne $valueProp.Value) { $out.Value = [int64]$valueProp.Value }
        }
        $out.Answered = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        if ($out.Error -eq '') { $out.Error = 'The registry read failed without an error message.' }
        $nativeCode = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $nativeCode -and $null -ne $nativeCode.Value) { $out.ErrorCode = [string]$nativeCode.Value }
    }
    return $out
}

function Get-AdfaDcHardeningRaw {
    <#
    .SYNOPSIS
        The one place C3 touches a DC: the registry values the config names, two instance
        queries and the SMB server configuration, in one bounded CIM session.
    .DESCRIPTION
        One GetDWORDValue call per setting - no second method and no retry: a value that is not
        set, a refusal and a wrong type are all answers, and each is kept as the provider gave
        it. Then two classes, read as instances with the properties named:
          Win32_OperatingSystem         BuildNumber, the DC's own statement of its build, which
                                        decides which documented default applies.
          Win32_Service                 the Spooler service: Name, State, StartMode.
        Nothing is written and no other method is invoked. The classes have methods that change
        things (Win32_Service: StartService, StopService, ChangeStartMode ...); none is used.

        THE SMB SERVER CONFIGURATION (PORT-PLAN C3f) is read with the cmdlet Microsoft documents
        for it, Get-SmbServerConfiguration ("Retrieves the SMB server configuration"), given this
        session through its -CimSession parameter ("Runs the cmdlet in a remote session or on a
        remote computer. Enter a computer name or a session object, such as the output of a
        New-CimSession"), and documented as the check of both properties read -
        EnableSMB1Protocol and RequireSecuritySignature:
          https://learn.microsoft.com/powershell/module/smbshare/get-smbserverconfiguration
          https://learn.microsoft.com/windows-server/storage/file-server/troubleshoot/detect-enable-and-disable-smbv1-v2-v3
          https://learn.microsoft.com/windows-server/storage/file-server/smb-signing
          Read: 2026-11-17 (all three).
        Chosen over invoking the class's GetConfiguration method (a fourth name on the
        Invoke-CimMethod allow-list) and over the LanmanServer\Parameters\SMB1 registry value
        (whose absence Microsoft documents as the default, Enabled, only under its Windows 7 /
        Windows Server 2008 R2 / Windows Vista / Windows Server 2008 heading): a documented Get cmdlet,
        and no new method name. Before C3f the class was asked for as instances, and on the one
        host measured (2026-11-15, a Windows 11 workstation, not a DC) that query returns no
        instance and no error; it is no longer made.
        The cmdlet has no timeout parameter. It is bounded by the session: OperationTimeoutSec
        on New-CimSession "Specifies the operation timeout for all operations in session"
          https://learn.microsoft.com/dotnet/api/microsoft.management.infrastructure.cimcmdlets.newcimsessioncommand.operationtimeoutsec?view=powershellsdk-7.6.0
          Read: 2026-11-17.
        MEASURED on 2026-11-17 on ONE host - a Windows 11 build 26100 workstation, not a domain
        controller, not elevated, a DCOM session to itself, under PowerShell 7.6 and Windows
        PowerShell 5.1 - the cmdlet is a function of module SmbShare 2.0.0.0 with a -CimSession
        parameter, and returns one MSFT_SmbServerConfiguration instance whose two properties are
        CimType Boolean. What a domain controller returns, over WSMan and DCOM, the rights it
        needs and the codes its errors carry are not measured (PORT-PLAN C17a). Microsoft
        documents no side effect of the read; none is claimed either way.
        Kept apart, never defaulted: the cmdlet not available on the assessing host
        (SmbCmdletMissing - the DC is not asked), no object and no error (SmbNoInstance), more
        than one object (SmbError with SmbErrorByTool, none is read), and a failure (SmbError -
        this tool's own sentence, with SmbErrorByTool, where the error had no message - with the CIM code
        from the exception or the one it wraps, Get-AdfaExceptionErrorCode).

        Values are read from the unadapted CIM store where there is one (Get-AdfaCimRawValue).

        Never throws. One operation that fails does not discard the others: each registry value
        and each class carries its own error. Ok is $false only when the session could not be
        opened, or when not one operation got an answer from the DC - which is what lets the
        caller try the other transport.

        The session is always closed, with -WhatIf and -Confirm forced off for the reason given
        in Get-AdfaDcDiskRaw: a preference in the caller's session must not leave it open.
    .OUTPUTS
        [pscustomobject] Ok, Protocol, Error, ErrorCode, BuildNumber, BuildError, BuildErrorCode,
        Values (one per setting: Id, Key, ValueName, Answered, ReturnValue, Value, Method, Error,
        ErrorCode), SmbInstrument (the cmdlet named), SmbCmdletMissing ($true: the cmdlet is not
        available on the assessing host and the DC was not asked), SmbOk, SmbNoInstance,
        SmbEnableSmb1, SmbRequireSigning, SmbError, SmbErrorCode, SmbErrorByTool ($true: SmbError
        is a sentence this tool wrote, not an error the read raised), SpoolerOk, SpoolerFound,
        SpoolerState, SpoolerStartMode, SpoolerError, SpoolerErrorCode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [ValidateSet('Wsman', 'Dcom')][string]$Protocol = 'Wsman',
        [pscredential]$Credential,
        [int]$OperationTimeoutSec = 90,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$Settings
    )
    $out = [pscustomobject]@{
        Ok = $false; Protocol = $Protocol; Error = ''; ErrorCode = ''
        BuildNumber = ''; BuildError = ''; BuildErrorCode = ''; Values = @()
        SmbInstrument = 'Get-SmbServerConfiguration'; SmbCmdletMissing = $false
        SmbOk = $false; SmbNoInstance = $false; SmbEnableSmb1 = $null; SmbRequireSigning = $null; SmbError = ''; SmbErrorCode = ''; SmbErrorByTool = $false
        SpoolerOk = $false; SpoolerFound = $false; SpoolerState = ''; SpoolerStartMode = ''; SpoolerError = ''; SpoolerErrorCode = ''
    }
    $session = $null
    try {
        $sessionArgs = @{ ComputerName = $ComputerName; OperationTimeoutSec = [uint32]$OperationTimeoutSec; ErrorAction = 'Stop' }
        if ($Protocol -eq 'Dcom') { $sessionArgs.SessionOption = New-CimSessionOption -Protocol Dcom }
        if ($Credential) { $sessionArgs.Credential = $Credential }
        $session = New-CimSession @sessionArgs

        $answered = $false
        $firstError = ''
        $firstCode = ''

        # ---- The registry values ----
        $entries = New-Object System.Collections.ArrayList
        foreach ($definition in @($Settings)) {
            if ($null -eq $definition) { continue }
            $key = [string](Get-AdfaConfigValue -Entry $definition -Name 'Key')
            $valueName = [string](Get-AdfaConfigValue -Entry $definition -Name 'ValueName')
            $read = Get-AdfaStdRegDwordValue -CimSession $session -Key $key -ValueName $valueName -OperationTimeoutSec $OperationTimeoutSec
            if ($read.Answered) { $answered = $true }
            elseif ($firstError -eq '') { $firstError = [string]$read.Error; $firstCode = [string]$read.ErrorCode }
            [void]$entries.Add([pscustomobject]@{
                    Id = [string](Get-AdfaConfigValue -Entry $definition -Name 'Id'); Key = $key; ValueName = $valueName
                    Answered = [bool]$read.Answered; ReturnValue = $read.ReturnValue; Value = $read.Value
                    Method = [string]$read.Method; Error = [string]$read.Error; ErrorCode = [string]$read.ErrorCode
                })
        }
        $out.Values = $entries.ToArray()

        # ---- The OS build ----
        try {
            $os = @(Get-CimInstance -CimSession $session -Namespace 'root/cimv2' -ClassName 'Win32_OperatingSystem' `
                    -Property 'BuildNumber' -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -ErrorAction Stop)
            if ($os.Count -eq 0 -or $null -eq $os[0]) { throw 'Win32_OperatingSystem returned no instance.' }
            $answered = $true
            $buildValue = Get-AdfaCimRawValue -Instance $os[0] -Name 'BuildNumber'
            if ($null -ne $buildValue) { $out.BuildNumber = ([string]$buildValue).Trim() }
        }
        catch {
            $out.BuildError = [string]$_.Exception.Message
            if ($out.BuildError -eq '') { $out.BuildError = 'The operating system query failed without an error message.' }
            $buildCode = $_.Exception.PSObject.Properties['NativeErrorCode']
            if ($null -ne $buildCode -and $null -ne $buildCode.Value) { $out.BuildErrorCode = [string]$buildCode.Value }
            if ($firstError -eq '') { $firstError = $out.BuildError; $firstCode = $out.BuildErrorCode }
        }

        # ---- The SMB server configuration (PORT-PLAN C3f) ----
        # The documented read cmdlet, in this session. Not available on the assessing host (no
        # SmbShare module): the DC is not asked, and that is not the DC's error.
        if (-not (Test-CommandAvailable -Name 'Get-SmbServerConfiguration')) {
            $out.SmbCmdletMissing = $true
        }
        else {
            try {
                # -WhatIf and -Confirm forced off: SmbShare declares this Get cmdlet with
                # ConfirmImpact Medium (measured in SmbServerConfiguration.cdxml), so a caller's
                # $ConfirmPreference of Medium would otherwise stop to ask, and a WhatIf
                # preference must not skip a read.
                $smb = @(Get-SmbServerConfiguration -CimSession $session -WhatIf:$false -Confirm:$false -ErrorAction Stop)
                # The cmdlet completed: the DC answered, whatever it returned.
                $answered = $true
                $smb = @($smb | Where-Object { $null -ne $_ })
                if ($smb.Count -eq 0) {
                    # No object and no error. NOT a read, and never filled in with a default: an
                    # invented False here would be an SMBv1 Pass nobody measured.
                    $out.SmbNoInstance = $true
                }
                elseif ($smb.Count -gt 1) {
                    # One session to one DC returns one configuration. More than one: which of
                    # them describes the DC is not known, so none is read.
                    $out.SmbError = ("Get-SmbServerConfiguration returned {0} configuration objects for one DC, where one was expected, so none of them is taken as this DC's configuration." -f $smb.Count)
                    # This tool's sentence, not the DC's: a row must not say the DC reported it.
                    $out.SmbErrorByTool = $true
                }
                else {
                    $out.SmbEnableSmb1 = Get-AdfaCimRawValue -Instance $smb[0] -Name 'EnableSMB1Protocol'
                    $out.SmbRequireSigning = Get-AdfaCimRawValue -Instance $smb[0] -Name 'RequireSecuritySignature'
                    $out.SmbOk = $true
                }
            }
            catch {
                $out.SmbError = [string]$_.Exception.Message
                if ($out.SmbError -eq '') { $out.SmbError = 'The SMB server configuration read failed without an error message.'; $out.SmbErrorByTool = $true }
                $out.SmbErrorCode = Get-AdfaExceptionErrorCode -Exception $_.Exception
                if ($firstError -eq '') { $firstError = $out.SmbError; $firstCode = $out.SmbErrorCode }
            }
        }

        # ---- The Print Spooler service ----
        try {
            $services = @(Get-CimInstance -CimSession $session -Namespace 'root/cimv2' -ClassName 'Win32_Service' -Filter "Name='Spooler'" `
                    -Property 'Name', 'State', 'StartMode' -OperationTimeoutSec ([uint32]$OperationTimeoutSec) -ErrorAction Stop)
            $answered = $true
            $out.SpoolerOk = $true
            $service = @($services | Where-Object { $null -ne $_ })
            if ($service.Count -gt 0) {
                $out.SpoolerFound = $true
                $out.SpoolerState = [string](Get-AdfaCimRawValue -Instance $service[0] -Name 'State')
                $out.SpoolerStartMode = [string](Get-AdfaCimRawValue -Instance $service[0] -Name 'StartMode')
            }
        }
        catch {
            $out.SpoolerError = [string]$_.Exception.Message
            if ($out.SpoolerError -eq '') { $out.SpoolerError = 'The service query failed without an error message.' }
            $serviceCode = $_.Exception.PSObject.Properties['NativeErrorCode']
            if ($null -ne $serviceCode -and $null -ne $serviceCode.Value) { $out.SpoolerErrorCode = [string]$serviceCode.Value }
            if ($firstError -eq '') { $firstError = $out.SpoolerError; $firstCode = $out.SpoolerErrorCode }
        }

        $out.Ok = $answered
        if (-not $answered) {
            $out.Error = $firstError
            $out.ErrorCode = $firstCode
        }
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $codeProp = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $codeProp -and $null -ne $codeProp.Value) { $out.ErrorCode = [string]$codeProp.Value }
    }
    finally {
        if ($null -ne $session) {
            try { Remove-CimSession -CimSession $session -WhatIf:$false -Confirm:$false -ErrorAction SilentlyContinue } catch { }
        }
    }
    return $out
}

function Get-AdfaDcHardening {
    <#
    .SYNOPSIS
        Per-DC hardening: LDAP server signing and its Windows Server 2025 enforcement, LDAP
        channel binding, SMB server and client signing, the LAN Manager authentication level,
        the Print Spooler service and the SMBv1 server.
    .DESCRIPTION
        One CIM session per DC, over the transport loop DcDisk uses (Invoke-AdfaDcRemoteRead):
        the DC is probed once per port through the shared cache (Test-AdfaDcPort), WinRM is
        tried first and DCOM second where the RPC endpoint mapper answers, and a refusal is not
        retried over the other transport. Three outcomes are kept apart for a DC that gave
        nothing: unreachable (no port answered, no read attempted), access denied, and any
        other read failure, quoted as the DC reported it.

        Before v1.20.0 this section probed port 135 itself, read the Spooler with Get-Service
        -ComputerName, SMBv1 with its own CIM connection and LDAPServerIntegrity over the .NET
        remote registry, ignored -Credential for two of the three, and graded an absent
        LDAPServerIntegrity as a Warning with no reason.

        Needs local Administrators rights on each DC: "By default, only members of the
        Administrators group can access the WMI namespace remotely."
          https://learn.microsoft.com/troubleshoot/windows-server/system-management-components/scenario-guide-troubleshoot-wmi-connectivity-access-issues
          Read: 2026-11-13.
        The registry permission StdRegProv needs on the four keys is not published.

        Accepts DC rows (HostName, Scope) so each finding carries its domain, or plain host
        names where the caller has only those.

        DECLARED POPULATION: the domains named in -ScopedDomains. Each of them ends up in the
        section one of two ways - as the Scope of at least one DC row, or as its own
        "DC hardening - <domain>" Not Assessed row saying why none of its DCs is shown as read.
        A domain is never simply missing (PORT-PLAN C2e, done for this section).

        These are registry reads: they show the policy configured on each DC, not what a client
        and the DC negotiate on the wire. No LDAP bind and no SMB session is attempted.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [int]$OperationTimeoutSec = 90,
        # Domains whose DC enumeration threw: objects with Domain and Error.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        # Why no DC could be enumerated at all, where the caller knows.
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        # The domains this run was scoped to: the declared population of the section.
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })

    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaDcHardeningRow -Scope ([string]$gap.Domain) -Item ("DC hardening - {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'None of its hardening settings was read.')
    }
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        $rows += New-AdfaDcHardeningRow -Item 'DC hardening' -Status $script:Status.NotAssessed `
            -Detail ("No domain controllers were enumerated, so no hardening setting could be read.{0} This is not a clean result." -f $why)
        return @($rows)
    }
    $wsmanPort = [int]$Config['WsmanPort']
    $rpcPort = [int]$Config['RpcPort']
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-AdfaDcHardeningRow -Scope $scope -Item 'DC hardening: (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and no hardening setting was read.'
            continue
        }
        $item = ("DC hardening: {0}" -f $dc)
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @($wsmanPort, $rpcPort) -TimeoutMs $PortTimeoutMs
        $wsman = [bool]$gate.Open[$wsmanPort]
        $rpc = [bool]$gate.Open[$rpcPort]
        if ($gate.Cause) {
            $rows += New-AdfaDcHardeningRow -Scope $scope -Item $item -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'no read was attempted')
            continue
        }
        if (-not $wsman -and -not $rpc) {
            $rows += New-AdfaDcHardeningRow -Scope $scope -Item $item -Status $script:Status.NotAssessed `
                -Detail ("Unreachable: neither WinRM ({0}) nor RPC ({1}) answered within {2} ms, so no read was attempted." -f $wsmanPort, $rpcPort, $PortTimeoutMs)
            continue
        }
        $protocols = @()
        if ($wsman) { $protocols += 'Wsman' }
        if ($rpc) { $protocols += 'Dcom' }
        $readArguments = @{ OperationTimeoutSec = $OperationTimeoutSec; Settings = $Config['Settings'] }
        if ($Credential) { $readArguments.Credential = $Credential }
        $read = Invoke-AdfaDcRemoteRead -ComputerName $dc -Protocols $protocols -ReadCommand 'Get-AdfaDcHardeningRaw' -ReadArguments $readArguments
        $raw = $read.Raw
        if ($null -eq $raw -or -not $raw.Ok) {
            $lead = 'Read failed: a port answered, but neither the registry values nor the system, SMB and service information could be read. If the text below is a refusal in another language, local Administrators rights on the DC are what is missing.'
            if ($read.Denied) { $lead = 'Access denied: the account running the assessment could not read the registry or the system information of this DC. Local Administrators rights on the DC are needed for this read.' }
            $rows += New-AdfaDcHardeningRow -Scope $scope -Item $item -Status $script:Status.NotAssessed `
                -Detail ("{0} Reported by the DC - {1}" -f $lead, (@($read.Attempts) -join ' | '))
            continue
        }
        $rows += @(Get-AdfaDcHardeningFinding -DomainController $dc -Scope $scope -Raw $raw -Config $Config)
    }
    return @($rows)
}

function ConvertTo-AdfaOverrideTable {
    <#
    .SYNOPSIS
        Pure: an override object - a hashtable built in memory, or an object parsed from JSON -
        as an ordered name-to-value table. $null when it is neither, so the caller can refuse
        an array, a string or a number, whose own properties must not be read as keys.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    $table = [ordered]@{}
    if ($Value -is [System.Collections.IDictionary]) {
        foreach ($k in @($Value.Keys)) { $table[[string]$k] = $Value[$k] }
        return $table
    }
    if ($Value -is [System.Management.Automation.PSCustomObject]) {
        foreach ($p in @($Value.PSObject.Properties)) { $table[[string]$p.Name] = $p.Value }
        return $table
    }
    return $null
}

function Merge-AdfaDcHardeningConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in DC hardening table, with validation. The
        DcHardening validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: under Settings, per setting id, ExpectedMinimum and
        OtherStatus:

            { "DcHardening": { "Settings": { "LmCompatibilityLevel": { "ExpectedMinimum": 3, "OtherStatus": "Fail" } } } }

        What it cannot: the registry key and value a setting reads, the meanings of its numbers,
        its documented defaults and its sources. Those are what the tool reads and what the
        vendor documents, and a file that redirected them would make every finding describe
        something else.

        Nor WsmanPort and RpcPort. Until the review of this row they were accepted, and they
        changed only the port that is PROBED: the CIM session is opened with no -Port and no
        TLS option, so it always goes to the default WinRM port, or to the RPC endpoint mapper
        for DCOM. A file naming 5986 would have had a DC that listens on 5985 reported as
        unreachable without a read being attempted. Both keys are refused, with that reason.
        DcDisk still accepts them and has the same gap (PORT-PLAN C3g).

        Nor SmbServer (PORT-PLAN C3f): it names the cmdlet the SMB server configuration is read
        with and the Microsoft pages behind it, and is refused with that reason.

        Anything this tool could not use is refused with the reason: an override that is not
        one object, an empty object, an unknown key, a null, a port key, the SmbServer key,
        Settings that is not an object keyed by setting id (an array is refused), an unknown
        setting id, a setting that is null, not an object or empty, an unknown key under a
        setting, an ExpectedMinimum that is not a JSON number or is not one of the setting's
        ExpectedChoices, and an OtherStatus that is not Warning or Fail - a value below the
        expectation can never be configured to read as a pass or as information.

        Provenance follows the values. ExpectedSource is rewritten for exactly the settings and
        keys the override supplied, and the built-in source stays named beside it.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    # The settings are copied row by row, so a merge never modifies the built-in table.
    $settings = New-Object System.Collections.ArrayList
    foreach ($row in @($BaseConfig['Settings'])) {
        $copy = @{}
        foreach ($k in @($row.Keys)) { $copy[$k] = $row[$k] }
        [void]$settings.Add($copy)
    }
    $merged['Settings'] = $settings.ToArray()
    if ($null -eq $Override) { return $merged }

    $top = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $top) {
        throw ("DC hardening config override must be a single object with named keys (for example {{ ""Settings"": {{ ""LmCompatibilityLevel"": {{ ""ExpectedMinimum"": 3 }} }} }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($top.Count -eq 0) {
        throw 'DC hardening config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $portKeys = @('WsmanPort', 'RpcPort')
    $known = @('Settings')
    $settingKeys = @('ExpectedMinimum', 'OtherStatus')
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $suppliedTop = @()
    foreach ($given in @($top.Keys)) {
        # The two port keys are refused whatever they hold, and with their own reason: a port
        # set here would be probed, and the CIM session would still go to the default one.
        $portMatch = @($portKeys | Where-Object { $_ -eq $given })
        if ($portMatch.Count -gt 0) {
            throw ("DC hardening config override names '{0}'. The ports of this section cannot be set from a file: its CIM session is always opened on the default WinRM port ({1}), or through the RPC endpoint mapper ({2}) for DCOM, so a different port here would change what is probed and not what is connected to. Remove the key." -f [string]$portMatch[0], [int]$BaseConfig['WsmanPort'], [int]$BaseConfig['RpcPort'])
        }
        # The SMB server read (PORT-PLAN C3f) is refused with its own reason: it names the cmdlet
        # the tool runs and the Microsoft pages that document it, not a choice.
        if ($given -eq 'SmbServer') {
            throw "DC hardening config override names 'SmbServer'. The SMB server configuration read cannot be set from a file: it names the documented cmdlet this tool runs (Get-SmbServerConfiguration), the properties it reads and the Microsoft sources for them. Remove the key."
        }
        # A misspelt key would otherwise be accepted, ignored, and leave the operator believing
        # their value was applied.
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("DC hardening config override names an unknown key '{0}'. Known keys: {1}." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        if ($suppliedTop -contains $name) { throw ("DC hardening config override names '{0}' more than once." -f $name) }
        $suppliedTop += $name
        $value = $top[$given]
        if ($null -eq $value) {
            throw ("DC hardening config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name)
        }

        # ---- Settings: an object keyed by setting id.
        $bySetting = ConvertTo-AdfaOverrideTable -Value $value
        if ($null -eq $bySetting) {
            throw ("DC hardening config override: 'Settings' must be an object keyed by setting id (for example {{ ""LmCompatibilityLevel"": {{ ""ExpectedMinimum"": 3 }} }}), not a {0}. A list is refused: a setting is named by its key." -f $value.GetType().Name)
        }
        if ($bySetting.Count -eq 0) {
            throw "DC hardening config override: 'Settings' is an empty object. It names no setting, so it would change nothing while appearing to be in force."
        }
        $ids = @($merged['Settings'] | ForEach-Object { [string]$_['Id'] })
        $suppliedIds = @()
        foreach ($givenId in @($bySetting.Keys)) {
            $idMatch = @($ids | Where-Object { $_ -eq $givenId })
            if ($idMatch.Count -eq 0) {
                throw ("DC hardening config override names an unknown setting '{0}'. Known settings: {1}." -f $givenId, ($ids -join ', '))
            }
            $id = [string]$idMatch[0]
            if ($suppliedIds -contains $id) { throw ("DC hardening config override names setting '{0}' more than once." -f $id) }
            $suppliedIds += $id
            $settingValue = $bySetting[$givenId]
            if ($null -eq $settingValue) {
                throw ("DC hardening config override sets setting '{0}' to null. Remove the key to keep the built-in row." -f $id)
            }
            $changes = ConvertTo-AdfaOverrideTable -Value $settingValue
            if ($null -eq $changes) {
                throw ("DC hardening config override: setting '{0}' must be an object naming {1}, not a {2}." -f $id, ($settingKeys -join ' and/or '), $settingValue.GetType().Name)
            }
            if ($changes.Count -eq 0) {
                throw ("DC hardening config override: setting '{0}' is an empty object. It names no key, so it would change nothing while appearing to be in force." -f $id)
            }
            $target = @($merged['Settings'] | Where-Object { [string]$_['Id'] -eq $id })[0]
            $suppliedKeys = @()
            foreach ($givenKey in @($changes.Keys)) {
                $keyMatch = @($settingKeys | Where-Object { $_ -eq $givenKey })
                if ($keyMatch.Count -eq 0) {
                    throw ("DC hardening config override, setting '{0}', names an unknown key '{1}'. Known keys: {2}. The registry value a setting reads, the meanings of its numbers, its defaults and its sources cannot be changed from a file." -f $id, $givenKey, ($settingKeys -join ', '))
                }
                $key = [string]$keyMatch[0]
                if ($suppliedKeys -contains $key) { throw ("DC hardening config override, setting '{0}', names '{1}' more than once." -f $id, $key) }
                $suppliedKeys += $key
                $change = $changes[$givenKey]
                if ($null -eq $change) {
                    throw ("DC hardening config override, setting '{0}', sets '{1}' to null. Remove the key to keep the built-in value." -f $id, $key)
                }
                if ($key -eq 'ExpectedMinimum') {
                    # A JSON number only: how a string becomes a number depends on the culture
                    # of the host, and an expectation must not.
                    if ($numericTypes -notcontains $change.GetType()) {
                        throw ("DC hardening config override, setting '{0}', sets 'ExpectedMinimum' to a {1} ('{2}'). It must be a JSON number, written without quotes." -f $id, $change.GetType().Name, [string]$change)
                    }
                    $wanted = [double]$change
                    $choices = @($target['ExpectedChoices'] | ForEach-Object { [int64]$_ })
                    $isChoice = (-not [double]::IsNaN($wanted) -and -not [double]::IsInfinity($wanted) -and $wanted -eq [math]::Floor($wanted) -and $choices -contains [int64]$wanted)
                    if (-not $isChoice) {
                        throw ("DC hardening config override, setting '{0}', sets 'ExpectedMinimum' to {1}. It must be one of {2}: the values this setting can be graded against, each with a meaning Microsoft publishes." -f $id, $wanted.ToString('0.####', $inv), ($choices -join ', '))
                    }
                    $target['ExpectedMinimum'] = [int]$wanted
                }
                else {
                    $allowed = @('Warning', 'Fail')
                    $statusMatch = @()
                    if ($change -is [string]) { $statusMatch = @($allowed | Where-Object { $_ -eq $change.Trim() }) }
                    if ($statusMatch.Count -eq 0) {
                        throw ("DC hardening config override, setting '{0}', sets 'OtherStatus' to '{1}'. It must be Warning or Fail: a value below the expectation is never reported as a pass, as information or as not assessed." -f $id, [string]$change)
                    }
                    $target['OtherStatus'] = [string]$statusMatch[0]
                }
            }
            # Provenance, for exactly what the override supplied for this setting.
            $text = ("{0} for {1}" -f $from, ($suppliedKeys -join ', '))
            $builtIn = @($settingKeys | Where-Object { $suppliedKeys -notcontains $_ })
            if ($builtIn.Count -gt 0) { $text = ("{0}; the built-in {1} is unchanged" -f $text, ($builtIn -join ', ')) }
            $target['ExpectedSource'] = ("{0}. Built-in source: {1}" -f $text, [string]$target['ExpectedSource'])
        }
    }
    return $merged
}

# ---------------------------------------------------------------------------
# Windows LAPS: schema, DSRM password backup per DC, computers with no LAPS expiry time (PORT-PLAN C4)
# ---------------------------------------------------------------------------

function New-AdfaLapsRow {
    <#
    .SYNOPSIS
        Pure: one Windows LAPS finding row. Every row of the section has the same columns, NotRun
        included, so a consumer never has to test whether the column exists.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = ''
    )
    $row = New-Finding -Scope $Scope -Area 'Laps' -Item $Item -Status $Status -Detail $Detail
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    return $row
}

function ConvertTo-AdfaFileTimeUtc {
    <#
    .SYNOPSIS
        Pure: a directory time value (a FILETIME count of 100-nanosecond intervals since 1601, as
        a number or as text, or a date) as a UTC date, or $null when it is not a time.
    .DESCRIPTION
        lastLogonTimestamp and the two LAPS expiry attributes are 64-bit integers. Nothing here
        depends on the culture or the PowerShell edition of the host: the text form is parsed
        with the invariant culture, and a value outside what .NET can hold as a date - the
        directory's "never", 0x7FFFFFFFFFFFFFFF, included - is $null and not an exception.
        Zero is a time (the start of 1601), not an absent value; a caller that treats zero as
        "none" says so itself.
    .OUTPUTS
        [datetime] in UTC, or $null
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [datetime]) { return $Value.ToUniversalTime() }
    $ticks = [int64]0
    $integerTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64])
    if ($integerTypes -contains $Value.GetType()) {
        try { $ticks = [int64]$Value } catch { return $null }
    }
    else {
        $text = ([string]$Value).Trim()
        if (-not [int64]::TryParse($text, [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$ticks)) { return $null }
    }
    if ($ticks -lt 0) { return $null }
    try { return [datetime]::FromFileTimeUtc($ticks) } catch { return $null }
}

function Get-AdfaDirectoryReadErrorClass {
    <#
    .SYNOPSIS
        Pure: Unreachable, AccessDenied, TimedOut or Error, for a directory read that threw.
    .DESCRIPTION
        A directory read through the ActiveDirectory module has no port probe in front of it, so
        the results a row must keep apart are told from the exception: its TYPE first, because
        the message is in the UI language of the host, and its text second.

        TimedOut is its own class, not Unreachable: a timeout or a "server too busy" answer can
        come from a server that accepted the query and then took too long - the one unpaged
        computer query over a large domain is the likely case - so it is not evidence that no
        server answered. It is decided from the exception type only.

        NOT PUBLISHED: Microsoft Learn does not list the exceptions these cmdlets throw. The type
        names below are the module's and .NET's own, and none of them has been produced by a
        real directory in a test of this tool (PORT-PLAN C17). Anything not recognised is Error,
        and the row quotes it as reported rather than interpreting it.
    .OUTPUTS
        [string] Unreachable | AccessDenied | TimedOut | Error
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Message,
        [AllowNull()][AllowEmptyString()][string]$TypeName
    )
    if (-not [string]::IsNullOrWhiteSpace($TypeName)) {
        if ($TypeName -match '(?i)UnauthorizedAccessException|AuthenticationException|SecurityAccessDeniedException') { return 'AccessDenied' }
        if ($TypeName -match '(?i)ServerTooBusyException|TimeoutException') { return 'TimedOut' }
        if ($TypeName -match '(?i)ADServerDownException|EndpointNotFoundException') { return 'Unreachable' }
    }
    if ([string]::IsNullOrWhiteSpace($Message)) { return 'Error' }
    if ((Get-AdfaRemoteReadErrorClass -Message $Message -ErrorCode '') -eq 'AccessDenied') { return 'AccessDenied' }
    if ($Message -match '(?i)insufficient access rights|rejected the client credentials') { return 'AccessDenied' }
    if ($Message -match '(?i)unable to contact the server|server is not operational|server is unavailable') { return 'Unreachable' }
    return 'Error'
}

function Get-AdfaLapsReadFailureLead {
    <#
    .SYNOPSIS
        Pure: the opening of a Not Assessed row for a directory read that failed, by class.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Message,
        [AllowNull()][AllowEmptyString()][string]$TypeName,
        [Parameter(Mandatory)][string]$What
    )
    $reported = '(no error text was returned)'
    if (-not [string]::IsNullOrWhiteSpace($Message)) { $reported = $Message.Trim() }
    # The exception type is shown as well: the class below is decided from it first, on type
    # names no real directory has produced in a test of this tool, so the row carries what it
    # was decided from.
    if (-not [string]::IsNullOrWhiteSpace($TypeName)) { $reported = ("{0} (exception type: {1})" -f $reported, $TypeName.Trim()) }
    $class = Get-AdfaDirectoryReadErrorClass -Message $Message -TypeName $TypeName
    if ($class -eq 'Unreachable') {
        return ("Unreachable: no directory server answered for {0}, so nothing was read. Reported by the directory query - {1}" -f $What, $reported)
    }
    if ($class -eq 'AccessDenied') {
        return ("Access denied: the account running the assessment was refused when reading {0}, so nothing was read. Reported by the directory query - {1}" -f $What, $reported)
    }
    if ($class -eq 'TimedOut') {
        return ("Timed out: the directory query for {0} did not complete, so nothing was read. A server may have answered and then been too slow or too busy - a large domain makes this query long - so this is not evidence that no server answered. Reported by the directory query - {1}" -f $What, $reported)
    }
    return ("Read failed: {0} could not be read. If the text below is a refusal in another language, the rights of the account are what is missing. Reported by the directory query - {1}" -f $What, $reported)
}

function Get-AdfaLapsRefusedProperty {
    <#
    .SYNOPSIS
        Pure: the names in a property list that this section must never ask the directory for.
    .DESCRIPTION
        The guard behind the hard rule of PORT-PLAN C4: no password and no encrypted password is
        ever read. Refused are a name on the never-read list (compared without regard to case),
        a blank, a wildcard - which would ask for every attribute, the secret ones included - and
        any name that looks like a password attribute ("password" or "pwd" in it) unless it ends
        in ExpirationTime, which is how the two non-secret expiry attributes are named. With an
        empty never-read list there is nothing to check against, so everything is refused.
    .OUTPUTS
        [string[]] The refused names; empty when the list is safe to send.
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$PropertyNames = @(),
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$NeverRead = @()
    )
    $refused = New-Object System.Collections.ArrayList
    $never = @($NeverRead | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { ([string]$_).Trim() })
    foreach ($given in @($PropertyNames)) {
        $name = ([string]$given).Trim()
        if ($name -eq '') { [void]$refused.Add('(blank)'); continue }
        if ($never.Count -eq 0) { [void]$refused.Add($name); continue }
        if ($name -match '[*?]') { [void]$refused.Add($name); continue }
        if (@($never | Where-Object { $_ -eq $name }).Count -gt 0) { [void]$refused.Add($name); continue }
        if ($name -match '(?i)password|pwd' -and $name -notmatch '(?i)ExpirationTime$') { [void]$refused.Add($name) }
    }
    return @($refused.ToArray())
}

function Get-AdfaLapsSchemaRaw {
    <#
    .SYNOPSIS
        One of the two places C4 touches the directory: which of the named attributes the forest
        schema defines.
    .DESCRIPTION
        Two read-only calls: the root DSE, for the DN of the schema partition, and one search of
        that partition for attributeSchema objects by lDAPDisplayName, asking for lDAPDisplayName
        and nothing else. It reads attribute DEFINITIONS. No computer object is touched and no
        attribute value of one is read, so naming a confidential attribute here discloses
        nothing: the filter compares the name of a definition.

        Never throws. A failure comes back as Ok = $false with the error text and the exception
        type. A name that is not an attribute name is refused before any call, so nothing can be
        injected into the filter.
    .OUTPUTS
        [pscustomobject] Ok, Error, ErrorType, SchemaNamingContext, Names (the lDAPDisplayName
        of each definition returned).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [hashtable]$AdParams = @{},
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$AttributeNames = @()
    )
    $out = [pscustomobject]@{ Ok = $false; Error = ''; ErrorType = ''; SchemaNamingContext = ''; Names = @() }
    $asked = @($AttributeNames)
    $bad = @($asked | Where-Object { [string]$_ -notmatch '^[A-Za-z][A-Za-z0-9-]*$' })
    if ($asked.Count -eq 0 -or $bad.Count -gt 0) {
        $out.Error = ("Refused before any query: the list of schema attributes to look for is empty or holds a value that is not an attribute name ({0})." -f (@($bad | ForEach-Object { "'{0}'" -f [string]$_ }) -join ', '))
        return $out
    }
    try {
        $rootArgs = @{} + $AdParams
        $rootArgs.ErrorAction = 'Stop'
        $root = Get-ADRootDSE @rootArgs
        $schemaNc = ''
        if ($null -ne $root) {
            $ncProp = $root.PSObject.Properties['schemaNamingContext']
            if ($null -ne $ncProp -and $null -ne $ncProp.Value) { $schemaNc = ([string]$ncProp.Value).Trim() }
        }
        if ($schemaNc -eq '') { throw 'The root DSE returned no schemaNamingContext, so the schema partition could not be located.' }
        $out.SchemaNamingContext = $schemaNc
        $p = @{} + $AdParams
        $p.SearchBase = $schemaNc
        $p.LDAPFilter = ('(|' + ((@($asked | ForEach-Object { '(lDAPDisplayName={0})' -f [string]$_ })) -join '') + ')')
        $p.Properties = @('lDAPDisplayName')
        $p.ErrorAction = 'Stop'
        $names = New-Object System.Collections.ArrayList
        foreach ($o in @(Get-ADObject @p)) {
            if ($null -eq $o) { continue }
            $nameProp = $o.PSObject.Properties['lDAPDisplayName']
            if ($null -ne $nameProp -and $null -ne $nameProp.Value -and -not [string]::IsNullOrWhiteSpace([string]$nameProp.Value)) { [void]$names.Add(([string]$nameProp.Value).Trim()) }
        }
        $out.Names = $names.ToArray()
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Get-AdfaLapsSchemaState {
    <#
    .SYNOPSIS
        Pure: what a schema read says about the LAPS attributes.
    .DESCRIPTION
        Three results are kept apart, because they are three different facts: the query failed
        (NotRead); the query answered but without the control attribute every schema defines, so
        the absence of anything else from that answer proves nothing (ControlMissing); and the
        query answered with the control attribute, so an attribute that is not in the answer is
        not in the schema (Complete, Partial, LegacyOnly or Absent).

        Complete is all six attributes Update-LapsADSchema adds. The attribute that arrives with
        the Windows Server 2025 forest schema is reported and never required.
    .OUTPUTS
        [pscustomobject] Read, State, Error, ErrorType, ControlSeen, Present, Missing,
        HasWindowsExpiry, HasLegacyExpiry, WindowsSetPresent, WindowsSetMissing, LegacyPresent,
        VersionAttribute, HasVersionAttribute, SchemaNamingContext.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$Raw,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $state = [pscustomobject]@{
        Read = $false; State = 'NotRead'; Error = ''; ErrorType = ''; ControlSeen = $false
        Present = @(); Missing = @(); HasWindowsExpiry = $false; HasLegacyExpiry = $false
        WindowsSetPresent = @(); WindowsSetMissing = @(); LegacyPresent = @()
        VersionAttribute = ''; HasVersionAttribute = $false; SchemaNamingContext = ''
    }
    if ($null -eq $Raw) { $state.Error = 'The schema read returned no result.'; return $state }
    if (-not $Raw.Ok) {
        $state.Error = [string]$Raw.Error
        $state.ErrorType = [string]$Raw.ErrorType
        return $state
    }
    $state.SchemaNamingContext = [string]$Raw.SchemaNamingContext
    $returned = @($Raw.Names | Where-Object { $null -ne $_ } | ForEach-Object { ([string]$_).Trim() })
    $control = [string]$Config['SchemaControl']
    $state.ControlSeen = (@($returned | Where-Object { $_ -eq $control }).Count -gt 0)
    if (-not $state.ControlSeen) { $state.State = 'ControlMissing'; return $state }
    $state.Read = $true
    $present = @(); $missing = @(); $windowsPresent = @(); $windowsMissing = @(); $legacyPresent = @()
    foreach ($attribute in @($Config['SchemaAttributes'])) {
        $name = [string]$attribute['Name']
        $set = [string]$attribute['Set']
        $found = (@($returned | Where-Object { $_ -eq $name }).Count -gt 0)
        if ($found) { $present += $name } else { $missing += $name }
        if ($set -eq 'WindowsLaps') { if ($found) { $windowsPresent += $name } else { $windowsMissing += $name } }
        elseif ($set -eq 'LegacyLaps') { if ($found) { $legacyPresent += $name } }
        elseif ($set -eq 'WindowsServer2025') { $state.VersionAttribute = $name; $state.HasVersionAttribute = [bool]$found }
    }
    $state.Present = @($present); $state.Missing = @($missing)
    $state.WindowsSetPresent = @($windowsPresent); $state.WindowsSetMissing = @($windowsMissing); $state.LegacyPresent = @($legacyPresent)
    $state.HasWindowsExpiry = ($present -contains [string]$Config['WindowsExpiry'])
    $state.HasLegacyExpiry = ($present -contains [string]$Config['LegacyExpiry'])
    if ($windowsMissing.Count -eq 0 -and $windowsPresent.Count -gt 0) { $state.State = 'Complete' }
    elseif ($windowsPresent.Count -gt 0) { $state.State = 'Partial' }
    elseif ($legacyPresent.Count -gt 0) { $state.State = 'LegacyOnly' }
    else { $state.State = 'Absent' }
    return $state
}

function Get-AdfaLapsSchemaFinding {
    <#
    .SYNOPSIS
        Pure: the one forest row saying which LAPS attributes the schema carries.
    .DESCRIPTION
        Pass for the complete Windows LAPS set, Warning for a partial one, Not Assessed where the
        schema was not read. A schema with no Windows LAPS attribute at all is Info: that is a
        fact about the forest, and what it means for each domain and each DC is graded in their
        own rows, so that one cause is not counted as a finding twice here.
    .OUTPUTS
        [pscustomobject] One finding row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$SchemaState,
        [Parameter(Mandatory)][hashtable]$Config,
        [AllowEmptyString()][string]$ForestName = ''
    )
    $item = 'Windows LAPS schema'
    $notRun = 'Not read: any attribute value of any computer. This row reads attribute definitions in the schema partition only.'
    $source = ("Attribute names: {0} (read {1})." -f [string]$Config['SourceUrl'], [string]$Config['ReadDate'])
    $control = [string]$Config['SchemaControl']
    if ($SchemaState.State -eq 'NotRead') {
        $lead = Get-AdfaLapsReadFailureLead -Message ([string]$SchemaState.Error) -TypeName ([string]$SchemaState.ErrorType) -What 'the forest schema'
        return (New-AdfaLapsRow -Scope $ForestName -Item $item -Status $script:Status.NotAssessed -NotRun $notRun `
                -Detail ("{0} Whether the schema carries the LAPS attributes is therefore not known; it is not reported as absent." -f $lead))
    }
    if ($SchemaState.State -eq 'ControlMissing') {
        return (New-AdfaLapsRow -Scope $ForestName -Item $item -Status $script:Status.NotAssessed -NotRun $notRun `
                -Detail ("Not assessed: the schema query answered without the control attribute {0}, which every schema defines and which was asked for in the same query. An answer that lacks it is incomplete, so the absence of the LAPS attributes from it proves nothing." -f $control))
    }
    $where = ("Read as attribute definitions in the schema partition ({0}), by name; no attribute value of any computer was read. The control attribute {1} came back in the same answer, so an attribute that is not listed as present is not in the schema." -f [string]$SchemaState.SchemaNamingContext, $control)
    $versionText = ''
    if (-not [string]::IsNullOrWhiteSpace([string]$SchemaState.VersionAttribute)) {
        $versionWord = 'absent'
        if ($SchemaState.HasVersionAttribute) { $versionWord = 'present' }
        $versionText = (" {0}: {1} - it arrives with the Windows Server 2025 forest schema and is not added by Update-LapsADSchema, so its absence is normal below that schema." -f [string]$SchemaState.VersionAttribute, $versionWord)
    }
    $legacyText = ' Legacy Microsoft LAPS attributes: absent.'
    if (@($SchemaState.LegacyPresent).Count -gt 0) { $legacyText = (" Legacy Microsoft LAPS attributes: present ({0})." -f (@($SchemaState.LegacyPresent) -join ', ')) }
    $entra = 'Microsoft states that a forest whose devices back their passwords up to Microsoft Entra ID only does not need the schema extension, and this read cannot see that.'
    if ($SchemaState.State -eq 'Complete') {
        return (New-AdfaLapsRow -Scope $ForestName -Item $item -Status $script:Status.Pass -NotRun $notRun `
                -Detail ("The forest schema carries the six attributes Update-LapsADSchema adds: {0}.{1}{2} {3} {4}" -f (@($SchemaState.WindowsSetPresent) -join ', '), $versionText, $legacyText, $where, $source))
    }
    if ($SchemaState.State -eq 'Partial') {
        return (New-AdfaLapsRow -Scope $ForestName -Item $item -Status $script:Status.Warning -NotRun $notRun `
                -Detail ("The forest schema carries {0} of the six attributes Update-LapsADSchema adds - present: {1}; missing: {2}. Microsoft documents that cmdlet as adding all of them in one operation for the entire forest.{3}{4} {5} {6}" -f `
                        @($SchemaState.WindowsSetPresent).Count, (@($SchemaState.WindowsSetPresent) -join ', '), (@($SchemaState.WindowsSetMissing) -join ', '), $versionText, $legacyText, $where, $source))
    }
    $consequence = 'What that means for the computers of each domain and for each domain controller is graded in the LAPS coverage and DSRM password backup rows.'
    if ($SchemaState.State -eq 'LegacyOnly') {
        return (New-AdfaLapsRow -Scope $ForestName -Item $item -Status $script:Status.Info -NotRun $notRun `
                -Detail ("The forest schema carries the legacy Microsoft LAPS attributes ({0}) and none of the Windows LAPS attributes, so a computer can store a legacy Microsoft LAPS password in this directory and no computer or domain controller can store a Windows LAPS one. {1} {2}{3} {4} {5}" -f `
                        (@($SchemaState.LegacyPresent) -join ', '), $consequence, $entra, $versionText, $where, $source))
    }
    return (New-AdfaLapsRow -Scope $ForestName -Item $item -Status $script:Status.Info -NotRun $notRun `
            -Detail ("The forest schema carries neither the Windows LAPS attributes nor the legacy Microsoft LAPS attributes, so no computer and no domain controller of this forest can store a LAPS password in this directory. {0} {1}{2} {3} {4}" -f `
                    $consequence, $entra, $versionText, $where, $source))
}

function Get-AdfaLapsPropertyList {
    <#
    .SYNOPSIS
        Pure: the attributes to ask of every computer object - the fixed non-secret list, plus
        only those of the two expiry attributes that the schema holds.
    .DESCRIPTION
        An attribute the schema lacks is not asked for: the cmdlet throws on a name the schema
        does not define. The finished list goes through the never-read guard, and a list that
        holds a refused name is a terminating error - a defect in the config, never a request.
    .OUTPUTS
        [string[]]
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory)]$SchemaState,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $names = @($Config['ComputerProperties'] | ForEach-Object { [string]$_ })
    if ($SchemaState.HasWindowsExpiry) { $names += [string]$Config['WindowsExpiry'] }
    if ($SchemaState.HasLegacyExpiry) { $names += [string]$Config['LegacyExpiry'] }
    $refused = @(Get-AdfaLapsRefusedProperty -PropertyNames $names -NeverRead @($Config['NeverRead']))
    if ($refused.Count -gt 0) {
        throw ("The Windows LAPS property list holds a name that is never read: {0}. Nothing was asked of the directory. This is a defect in the tool's config table, not in the directory." -f ($refused -join ', '))
    }
    return @($names)
}

function ConvertTo-AdfaLapsComputerRecord {
    <#
    .SYNOPSIS
        Pure: one computer object as the small record the verdict functions read.
    .DESCRIPTION
        Only the named attributes are copied, each through PSObject.Properties, so an attribute
        the object does not carry is $null and never an error under StrictMode. The two expiry
        attributes are copied only when their name is given - that is, only when they were asked
        for. The times stay raw (the 64-bit integers the directory stores).
    .OUTPUTS
        [pscustomobject] Name, OperatingSystem, OperatingSystemVersion, UserAccountControl,
        LastLogonTimestamp, ObjectClasses, WindowsExpiry, LegacyExpiry.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Computer,
        [AllowEmptyString()][string]$WindowsExpiryName = '',
        [AllowEmptyString()][string]$LegacyExpiryName = ''
    )
    $name = ''
    foreach ($candidate in @('dNSHostName', 'Name', 'DistinguishedName')) {
        $value = Get-AdfaConfigValue -Entry $Computer -Name $candidate
        if ($null -ne $value -and -not [string]::IsNullOrWhiteSpace([string]$value)) { $name = ([string]$value).Trim(); break }
    }
    if ($name -eq '') { $name = '(unnamed)' }
    $uac = $null
    $uacRaw = Get-AdfaConfigValue -Entry $Computer -Name 'userAccountControl'
    if ($null -ne $uacRaw) {
        $parsed = [int64]0
        if ([int64]::TryParse(([string]$uacRaw).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsed)) { $uac = $parsed }
    }
    $classes = @(@(Get-AdfaConfigValue -Entry $Computer -Name 'objectClass') | Where-Object { $null -ne $_ -and -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
    $windowsExpiry = $null
    if ($WindowsExpiryName -ne '') { $windowsExpiry = Get-AdfaConfigValue -Entry $Computer -Name $WindowsExpiryName }
    $legacyExpiry = $null
    if ($LegacyExpiryName -ne '') { $legacyExpiry = Get-AdfaConfigValue -Entry $Computer -Name $LegacyExpiryName }
    return [pscustomobject]@{
        Name                   = $name
        OperatingSystem        = [string](Get-AdfaConfigValue -Entry $Computer -Name 'operatingSystem')
        OperatingSystemVersion = [string](Get-AdfaConfigValue -Entry $Computer -Name 'operatingSystemVersion')
        UserAccountControl     = $uac
        LastLogonTimestamp     = Get-AdfaConfigValue -Entry $Computer -Name 'lastLogonTimestamp'
        ObjectClasses          = @($classes)
        WindowsExpiry          = $windowsExpiry
        LegacyExpiry           = $legacyExpiry
    }
}

function Get-AdfaLapsDirectoryRaw {
    <#
    .SYNOPSIS
        The other place C4 touches the directory: one domain's functional level and its
        computer objects, with a guarded list of non-secret attributes.
    .DESCRIPTION
        Three read-only calls: Get-ADDomain -Identity <domain> for the DN of the domain head,
        Get-ADObject for msDS-Behavior-Version on it, and one Get-ADComputer for every computer
        object of the domain. The last two carry -Server set to the domain, so that a child
        domain is asked of its own domain controller. Get-ADDomain does NOT: it takes the
        caller's AD parameters unchanged - -Server and -Credential where the run has them, the
        default domain controller otherwise - as the script's older Get-ADDomain calls do. If
        that call fails for a child domain, the level is not read and every eligible DC of the
        domain is Not Assessed, never graded. The two halves are independent: a failed level
        read leaves the computers, and a failed computer read leaves the level.

        THE PROPERTY LIST IS CHECKED HERE AS WELL as where it is built. A list that holds a name
        on the never-read list, a wildcard or a blank, or that is empty, is refused before any
        call: Refused = $true, and nothing is asked of the directory.

        The computer query relies on the paging the ActiveDirectory module does by itself; this
        script sets no page size and no result limit anywhere, and none is set here. Each object
        is reduced to a small record as it arrives, so the full objects are not kept.

        Never throws.
    .OUTPUTS
        [pscustomobject] Ok (the computer query succeeded), Refused, Error, ErrorType,
        DomainLevel (raw string, '' when not read), DomainLevelError, Computers (records),
        PropertyNames.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$PropertyNames = @(),
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$NeverRead = @(),
        [AllowEmptyString()][string]$WindowsExpiryName = '',
        [AllowEmptyString()][string]$LegacyExpiryName = ''
    )
    $out = [pscustomobject]@{
        Ok = $false; Refused = $false; Error = ''; ErrorType = ''; DomainLevel = ''; DomainLevelError = ''
        Computers = @(); PropertyNames = @($PropertyNames)
    }
    $refused = @(Get-AdfaLapsRefusedProperty -PropertyNames $PropertyNames -NeverRead $NeverRead)
    if (@($PropertyNames).Count -eq 0 -or $refused.Count -gt 0) {
        $out.Refused = $true
        $out.Error = ("the property list is empty or holds a name that is never read ({0}), so nothing was asked of the directory. This is a defect in the tool, not in the directory." -f ($refused -join ', '))
        return $out
    }

    # The domain functional level, from the domain head.
    try {
        $domainArgs = @{} + $AdParams
        $domainArgs.Identity = $DomainName
        $domainDn = [string](Get-ADDomain @domainArgs).DistinguishedName
        if ([string]::IsNullOrWhiteSpace($domainDn)) { throw 'Get-ADDomain returned no DistinguishedName, so the domain head could not be located.' }
        $levelArgs = @{} + $AdParams
        $levelArgs.Server = $DomainName
        $levelArgs.Identity = $domainDn
        $levelArgs.Properties = @('msDS-Behavior-Version')
        $levelArgs.ErrorAction = 'Stop'
        $head = Get-ADObject @levelArgs
        $levelProp = $null
        if ($null -ne $head) { $levelProp = $head.PSObject.Properties['msDS-Behavior-Version'] }
        if ($null -eq $levelProp -or $null -eq $levelProp.Value -or [string]::IsNullOrWhiteSpace([string]$levelProp.Value)) {
            $out.DomainLevelError = ("msDS-Behavior-Version was not returned for {0}. An unset attribute and one that could not be read look the same from here, so no level is assumed." -f $domainDn)
        }
        else { $out.DomainLevel = ([string]$levelProp.Value).Trim() }
    }
    catch { $out.DomainLevelError = ("Reading msDS-Behavior-Version from the head of {0} failed: {1}" -f $DomainName, [string]$_.Exception.Message) }

    # The computer objects of the domain.
    try {
        $computerArgs = @{} + $AdParams
        $computerArgs.Server = $DomainName
        $computerArgs.LDAPFilter = '(objectClass=computer)'
        $computerArgs.Properties = @($PropertyNames)
        $computerArgs.ErrorAction = 'Stop'
        $records = New-Object System.Collections.ArrayList
        Get-ADComputer @computerArgs | ForEach-Object {
            if ($null -ne $_) { [void]$records.Add((ConvertTo-AdfaLapsComputerRecord -Computer $_ -WindowsExpiryName $WindowsExpiryName -LegacyExpiryName $LegacyExpiryName)) }
        }
        $out.Computers = $records.ToArray()
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Test-AdfaLapsCapableBuild {
    <#
    .SYNOPSIS
        Pure: whether an OS build is one Microsoft lists as able to run Windows LAPS.
    .OUTPUTS
        [bool]
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [AllowNull()]$Build,
        [Parameter(Mandatory)][hashtable]$Config
    )
    if ($null -eq $Build) { return $false }
    $number = [int]$Build
    foreach ($range in @($Config['CapableBuilds'])) {
        $min = Get-AdfaConfigValue -Entry $range -Name 'MinBuild'
        $max = Get-AdfaConfigValue -Entry $range -Name 'MaxBuild'
        if ($null -ne $min -and $number -lt [int]$min) { continue }
        if ($null -ne $max -and $number -gt [int]$max) { continue }
        return $true
    }
    return $false
}

function Get-AdfaLapsComputerClass {
    <#
    .SYNOPSIS
        Pure: which class a computer object falls in - InPopulation, or the one reason it is not
        graded.
    .DESCRIPTION
        DECLARED POPULATION of the coverage row: an enabled computer account that is not a
        domain controller and not a managed service account, whose operatingSystem begins with
        "Windows", whose OS build is one that can run Windows LAPS, and that logged on within the
        stale threshold. Everything else gets a named class and its own count, so that nothing
        that cannot run Windows LAPS is ever called a computer without it:

          ServiceAccount         a managed service account (a subclass of computer)
          AccountControlNotRead  userAccountControl was not returned, so neither "disabled" nor
                                 "domain controller" can be ruled out
          DomainController       SERVER_TRUST_ACCOUNT or PARTIAL_SECRETS_ACCOUNT; graded by the
                                 DSRM rows instead, disabled or not
          Disabled               ACCOUNTDISABLE
          NoOperatingSystem      no operatingSystem value: also how cluster name objects and other
                                 virtual computer objects are left out (a tool heuristic)
          NonWindows             operatingSystem does not begin with "Windows"
          BuildNotRead           Windows, but operatingSystemVersion carries no build number
          NotCapable             a Windows build Microsoft does not list for Windows LAPS
          NoLogonRecorded        no lastLogonTimestamp, or zero
          Stale                  lastLogonTimestamp older than the cutoff
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]$Computer,
        [Parameter(Mandatory)][hashtable]$Config,
        [Parameter(Mandatory)][datetime]$StaleCutoffUtc
    )
    $excluded = @($Config['ExcludedClasses'])
    foreach ($class in @($Computer.ObjectClasses)) {
        if (@($excluded | Where-Object { $_ -eq [string]$class }).Count -gt 0) { return 'ServiceAccount' }
    }
    if ($null -eq $Computer.UserAccountControl) { return 'AccountControlNotRead' }
    $flags = [int64]$Computer.UserAccountControl
    $dcFlags = ([int64]$Config['ServerTrustFlag']) -bor ([int64]$Config['PartialSecretsFlag'])
    if (($flags -band $dcFlags) -ne 0) { return 'DomainController' }
    if (($flags -band [int64]$Config['AccountDisableFlag']) -ne 0) { return 'Disabled' }
    $os = ([string]$Computer.OperatingSystem).Trim()
    if ($os -eq '') { return 'NoOperatingSystem' }
    if ($os -notlike 'Windows*') { return 'NonWindows' }
    $build = Get-AdfaOsBuild -OperatingSystemVersion ([string]$Computer.OperatingSystemVersion)
    if ($null -eq $build) { return 'BuildNotRead' }
    if (-not (Test-AdfaLapsCapableBuild -Build $build -Config $Config)) { return 'NotCapable' }
    $logon = ConvertTo-AdfaFileTimeUtc -Value $Computer.LastLogonTimestamp
    if ($null -eq $logon -or $logon.Year -le 1601) { return 'NoLogonRecorded' }
    if ($logon -lt $StaleCutoffUtc.ToUniversalTime()) { return 'Stale' }
    return 'InPopulation'
}

function Get-AdfaLapsCoverageVerdict {
    <#
    .SYNOPSIS
        Pure: the status of one domain's coverage row, from counts.
    .DESCRIPTION
        In this order:
          NoObjects        the query returned nothing at all - an incomplete read: Not Assessed
          EmptyPopulation  nothing to grade: Info
          SchemaAbsent     the schema has neither expiry attribute, so every in-population
                           computer is without - a measured absence, judged by the thresholds
          NoProofOfRead    the schema has the attribute and NO object in the domain returned a
                           value: not deployed, not readable and backed up elsewhere all look
                           the same, so Not Assessed - never Warning, never Pass
          AllVisible       Pass
          AboveFail / AboveWarn / WithinTolerance, by the share without a visible expiry time.
          Unclassified     a result that would be Pass or Info while some objects could not be
                           placed in or out of the population (userAccountControl not returned,
                           or a Windows build that could not be read): those objects are not
                           measured, so the row cannot pass or say there is nothing to grade -
                           Not Assessed. A Warning or a Fail stands: what was measured among the
                           others is a finding whatever the unmeasured ones turn out to be.
        "Above" is strict: a share equal to a threshold is not above it. Both thresholds are
        tool defaults or an override, never Microsoft values.
    .OUTPUTS
        [pscustomobject] Status, State, Percent.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][int]$TotalReturned,
        [Parameter(Mandatory)][int]$InPopulation,
        [Parameter(Mandatory)][int]$NoneVisible,
        [Parameter(Mandatory)][bool]$ProofOfRead,
        [Parameter(Mandatory)][bool]$SchemaHasExpiry,
        [Parameter(Mandatory)][hashtable]$Config,
        [int]$Unclassified = 0
    )
    if ($TotalReturned -le 0) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'NoObjects'; Percent = $null } }
    if ($InPopulation -le 0) {
        if ($Unclassified -gt 0) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'Unclassified'; Percent = $null } }
        return [pscustomobject]@{ Status = $script:Status.Info; State = 'EmptyPopulation'; Percent = $null }
    }
    $without = $NoneVisible
    if (-not $SchemaHasExpiry) { $without = $InPopulation }
    elseif (-not $ProofOfRead) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'NoProofOfRead'; Percent = $null } }
    $percent = ([double]$without * 100.0) / [double]$InPopulation
    $status = $script:Status.Pass
    $state = 'WithinTolerance'
    if ($without -le 0) { $state = 'AllVisible' }
    elseif ($percent -gt [double]$Config['FailAbovePercent']) { $status = $script:Status.Fail; $state = 'AboveFail' }
    elseif ($percent -gt [double]$Config['WarnAbovePercent']) { $status = $script:Status.Warning; $state = 'AboveWarn' }
    if (-not $SchemaHasExpiry) { $state = 'SchemaAbsent' }
    if ($Unclassified -gt 0 -and $status -eq $script:Status.Pass) { return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'Unclassified'; Percent = $percent } }
    return [pscustomobject]@{ Status = $status; State = $state; Percent = $percent }
}

function Get-AdfaLapsDsrmVerdict {
    <#
    .SYNOPSIS
        Pure: the status of one domain controller's DSRM password backup row.
    .DESCRIPTION
        Eligibility first, as Microsoft draws it: a DC below Windows Server 2019 (build 17763),
        or a domain below functional level 2016 (7), cannot use the feature and is Info, not
        applicable. A level or a build that was not read is Not Assessed.

        Then the evidence, which is the Windows LAPS expiry time on the DC's own computer
        object and nothing else:
          SchemaAbsent      the schema has no such attribute: a measured absence, Warning
          Current           a time that is not more than the grace period past: Pass
          Expired           a time further past than that: Warning
          ExpiryNotATime    a value that is not a time: Not Assessed
          NoProofOfRead     nothing on this DC and nothing on any object of the domain: not set
                            cannot be told from not readable, Not Assessed
          RodcNotPublished  nothing on a read-only DC, where Microsoft does not say whether the
                            feature is supported: Not Assessed
          NoneVisible       nothing on this DC while another object of the domain returned a
                            value: Warning
        Warning is the AdAssessment26 catalogue's rule for a DC without it (ADA-LAPS-001).
        Microsoft documents the feature as off by default, not as a requirement.
    .OUTPUTS
        [pscustomobject] Status, State.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$Build,
        [AllowNull()][AllowEmptyString()][string]$DomainLevel,
        [Parameter(Mandatory)][bool]$ExpiryPresent,
        [AllowNull()]$ExpiryUtc,
        [Parameter(Mandatory)][datetime]$Now,
        [Parameter(Mandatory)][bool]$ProofOfRead,
        [Parameter(Mandatory)][bool]$SchemaRead,
        [Parameter(Mandatory)][bool]$HasWindowsExpiry,
        [Parameter(Mandatory)][bool]$IsReadOnly,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $verdict = { param($Status, $State) [pscustomobject]@{ Status = $Status; State = $State } }
    if ($null -ne $Build -and [int]$Build -lt [int]$Config['MinDsrmDcBuild']) { return (& $verdict $script:Status.Info 'NotApplicableBuild') }
    $level = 0
    $levelIsNumber = [int]::TryParse(([string]$DomainLevel).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$level)
    if (-not $levelIsNumber) { return (& $verdict $script:Status.NotAssessed 'LevelNotRead') }
    if (@($Config['KnownDomainLevels'] | Where-Object { [int]$_ -eq $level }).Count -eq 0) { return (& $verdict $script:Status.NotAssessed 'LevelUnknown') }
    if ($level -lt [int]$Config['MinDomainLevel']) { return (& $verdict $script:Status.Info 'NotApplicableLevel') }
    if ($null -eq $Build) { return (& $verdict $script:Status.NotAssessed 'BuildNotRead') }
    if (-not $SchemaRead) { return (& $verdict $script:Status.NotAssessed 'SchemaNotRead') }
    if (-not $HasWindowsExpiry) { return (& $verdict $script:Status.Warning 'SchemaAbsent') }
    if ($ExpiryPresent) {
        if ($null -eq $ExpiryUtc) { return (& $verdict $script:Status.NotAssessed 'ExpiryNotATime') }
        # The grace period is taken off "now", never added to the expiry time: an expiry time
        # within the grace period of the last date .NET can hold (an administrator who set it to
        # the end of time to stop rotation) would otherwise throw and end the section. The two
        # comparisons are the same: now > expiry + grace exactly when now - grace > expiry.
        $earliestCurrent = $Now.ToUniversalTime().AddDays(-1 * [double]$Config['ExpiredGraceDays'])
        if ($earliestCurrent -gt ([datetime]$ExpiryUtc).ToUniversalTime()) { return (& $verdict $script:Status.Warning 'Expired') }
        return (& $verdict $script:Status.Pass 'Current')
    }
    if (-not $ProofOfRead) { return (& $verdict $script:Status.NotAssessed 'NoProofOfRead') }
    if ($IsReadOnly) { return (& $verdict $script:Status.NotAssessed 'RodcNotPublished') }
    return (& $verdict $script:Status.Warning 'NoneVisible')
}

function Get-AdfaLapsDsrmDetail {
    <#
    .SYNOPSIS
        Pure: the Detail of one DSRM password backup row, for the state the verdict returned.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$State,
        [AllowNull()]$Build,
        [AllowNull()][AllowEmptyString()][string]$BuildRaw,
        [AllowNull()][AllowEmptyString()][string]$DomainLevel,
        [AllowNull()][AllowEmptyString()][string]$DomainLevelError,
        [AllowNull()]$ExpiryUtc,
        [AllowNull()][AllowEmptyString()][string]$ExpiryRaw,
        [Parameter(Mandatory)][bool]$IsReadOnly,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $attribute = [string]$Config['WindowsExpiry']
    $grace = [int]$Config['ExpiredGraceDays']
    $minBuild = [int]$Config['MinDsrmDcBuild']
    $minLevel = [int]$Config['MinDomainLevel']
    $basis = ("Basis: {0} on the computer object of the DC, the one non-secret attribute Windows LAPS writes there. Microsoft does not state in prose that DSRM password backup writes it - its Get-LapsADPassword example shows an expiration time for a DC whose password source is the DSRM one - so reading it as evidence of DSRM password backup is an inference, not a documented contract." -f $attribute)
    $rule = 'That a DC without it is a Warning is the rule of the AdAssessment26 catalogue (ADA-LAPS-001), a tool default and not a Microsoft value: Microsoft documents DSRM password backup as a feature that is off by default, not as a requirement.'
    $sameLook = 'An attribute this account has no right to read looks exactly like one that is not set.'
    $when = ''
    if ($null -ne $ExpiryUtc) { $when = ("{0} UTC" -f ([datetime]$ExpiryUtc).ToUniversalTime().ToString('yyyy-MM-dd HH:mm', [System.Globalization.CultureInfo]::InvariantCulture)) }
    $rodc = ''
    if ($IsReadOnly) { $rodc = ' This is a read-only domain controller, and Microsoft does not state, on the pages read, whether DSRM password backup is supported on one.' }
    switch ($State) {
        'NotApplicableBuild' {
            return ("Not applicable: the OS build of this DC is {0}, below {1} (Windows Server 2019). Microsoft states that Windows Server 2016 and earlier domain controllers do not support Windows LAPS, so they cannot use DSRM account management. Nothing is graded." -f $Build, $minBuild)
        }
        'NotApplicableLevel' {
            return ("Not applicable: the domain functional level is msDS-Behavior-Version {0}, below {1} (Windows Server 2016). Microsoft states that with a domain functional level earlier than 2016 domain controllers cannot be configured to manage their DSRM account. Nothing is graded." -f $DomainLevel, $minLevel)
        }
        'LevelNotRead' {
            $why = 'no value was returned'
            if (-not [string]::IsNullOrWhiteSpace($DomainLevelError)) { $why = $DomainLevelError.Trim() }
            elseif (-not [string]::IsNullOrWhiteSpace($DomainLevel)) { $why = ("the value returned, '{0}', is not a number" -f $DomainLevel) }
            return ("Not assessed: the domain functional level was not read ({0}), and DSRM password backup needs level {1} (Windows Server 2016) or later, so it is not known whether this DC can use it. Nothing is concluded from the attribute." -f $why, $minLevel)
        }
        'LevelUnknown' {
            return ("Not assessed: the domain head holds msDS-Behavior-Version {0}, which is not one of the values this tool knows ({1} - the values Microsoft publishes for the forest functional level, applied here to the domain because the page for the domain level was not read), so it is not interpreted and it is not known whether this DC can use DSRM password backup." -f $DomainLevel, (@($Config['KnownDomainLevels']) -join ', '))
        }
        'BuildNotRead' {
            return ("Not assessed: operatingSystemVersion on the computer object of this DC is '{0}', which carries no build number, and DSRM password backup needs build {1} (Windows Server 2019) or later, so it is not known whether this DC can use it." -f $BuildRaw, $minBuild)
        }
        'SchemaNotRead' {
            return 'Not assessed: the forest schema could not be read (see the Windows LAPS schema row), so it is not known whether the attribute this row relies on exists.'
        }
        'SchemaAbsent' {
            return ("The forest schema does not carry {0} (see the Windows LAPS schema row), so Windows LAPS cannot back the DSRM password of this DC up to this directory. The DC is otherwise eligible: OS build {1}, domain functional level {2}. {3}" -f $attribute, $Build, $DomainLevel, $rule)
        }
        'Current' {
            return ("A Windows LAPS expiry time is visible on the computer object of this DC: {0}, which is not more than {1} day(s) past (grace period: {2}). A DC that was promoted from a member server Windows LAPS managed can carry a value left from before the promotion until it expires.{3} {4}" -f $when, $grace, [string]$Config['ThresholdSource'], $rodc, $basis)
        }
        'Expired' {
            return ("The Windows LAPS expiry time on the computer object of this DC is {0}, more than {1} day(s) in the past (grace period: {2}). Either the password it belongs to is no longer being rotated, or the value was left from before this server became a DC.{3} {4} {5}" -f $when, $grace, [string]$Config['ThresholdSource'], $rodc, $basis, $rule)
        }
        'ExpiryNotATime' {
            return ("Not assessed: {0} on the computer object of this DC holds '{1}', which is not a time, so it is neither current nor expired. {2}" -f $attribute, $ExpiryRaw, $basis)
        }
        'NoProofOfRead' {
            return ("Not assessed: no Windows LAPS expiry time is visible to this account on the computer object of this DC, and no computer object of this domain returned one either, so not set cannot be told from not readable. {0}{1} {2}" -f $sameLook, $rodc, $basis)
        }
        'RodcNotPublished' {
            return ("Not assessed: no Windows LAPS expiry time is visible to this account on the computer object of this read-only domain controller. Microsoft does not state, on the pages read, whether DSRM password backup is supported on a read-only domain controller, so nothing is concluded from the absence. {0} {1}" -f $sameLook, $basis)
        }
        default {
            return ("No Windows LAPS expiry time is visible to this account on the computer object of this DC, while at least one other computer object of this domain did return one. {0} Permissions can differ between organizational units, so this is not proof that the DSRM password is unmanaged. The DC is eligible: OS build {1}, domain functional level {2}. {3} {4}" -f $sameLook, $Build, $DomainLevel, $basis, $rule)
        }
    }
}

function Get-AdfaLapsThresholdText {
    <#
    .SYNOPSIS
        Pure: the two coverage thresholds in words, with where they come from.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][hashtable]$Config)
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $warn = ([double]$Config['WarnAbovePercent']).ToString('0.##', $inv)
    $fail = [double]$Config['FailAbovePercent']
    $failText = ("Fail above {0} %" -f $fail.ToString('0.##', $inv))
    if ($fail -ge 100) { $failText = 'Fail above 100 %, which no share can exceed, so this row never fails unless a config file lowers it' }
    return ("Judged against: Warning above {0} % of the computers in population with no LAPS expiry time visible, {1} ({2})." -f $warn, $failText, [string]$Config['ThresholdSource'])
}

function Get-AdfaLapsDomainFinding {
    <#
    .SYNOPSIS
        Pure: one domain's raw directory read to its finding rows.
    .DESCRIPTION
        DECLARED POPULATION: the one domain named. It always gets exactly one
        "LAPS coverage: <domain>" row, and at least one DSRM row - "DSRM password backup: <dc>"
        for each domain controller computer object the read returned, or one
        "DSRM password backup - <domain>" Not Assessed row saying why there is none. That
        Not Assessed row is also written beside the DC rows when an object returned no
        userAccountControl, since it may be a domain controller the rows do not cover.

        Nothing is graded when the schema was not read, whatever the computer read returned:
        without the schema it is not known which attribute could have been asked for.

        A computer is counted as having LAPS when either expiry attribute came back with a
        value, and is otherwise "no LAPS expiry time visible to this account" - never
        "unmanaged": a value this account has no right to read, and a password backed up to
        Microsoft Entra ID, look the same as no value. The names listed are capped at
        SampleLimit, and the row says when the list was cut.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowNull()]$Raw,
        [Parameter(Mandatory)]$SchemaState,
        [Parameter(Mandatory)][hashtable]$Config,
        [int]$StaleDays = 90,
        [Parameter(Mandatory)][datetime]$Now
    )
    $coverageItem = ("LAPS coverage: {0}" -f $DomainName)
    $dsrmGapItem = ("DSRM password backup - {0}" -f $DomainName)
    $coverageNotRun = 'Not read: any LAPS password or encrypted password attribute, which this section never requests; Microsoft Entra ID, where a device can back its password up in place of this directory; and the LAPS policy on any computer. The expiry time is the only evidence used.'
    $dsrmNotRun = 'Not read: the Windows LAPS policy in the registry of the DC (BackupDirectory, ADBackupDSRMPassword, ADPasswordEncryptionEnabled) - PORT-PLAN C4a; and the confidential attribute that holds the encrypted DSRM password, which this section never requests and does not test for presence - PORT-PLAN C4d.'
    $rows = @()

    # 1. Without the schema nothing is graded.
    if (-not $SchemaState.Read) {
        $cause = 'Not assessed: the forest schema could not be read (see the Windows LAPS schema row), so it is not known which LAPS attributes exist'
        $rows += New-AdfaLapsRow -Scope $DomainName -Item $coverageItem -Status $script:Status.NotAssessed -NotRun $coverageNotRun `
            -Detail ("{0}, and no computer account of this domain was graded." -f $cause)
        $rows += New-AdfaLapsRow -Scope $DomainName -Item $dsrmGapItem -Status $script:Status.NotAssessed -NotRun $dsrmNotRun `
            -Detail ("{0}, and no domain controller of this domain was graded." -f $cause)
        return @($rows)
    }

    # 2. The read itself failed, or was refused before it was sent.
    $what = ("the computer objects of {0}" -f $DomainName)
    $failure = ''
    if ($null -eq $Raw) { $failure = ("Read failed: {0} could not be read. The directory read returned no result." -f $what) }
    elseif ($Raw.Refused) { $failure = ("Refused: {0}" -f [string]$Raw.Error) }
    elseif (-not $Raw.Ok) { $failure = Get-AdfaLapsReadFailureLead -Message ([string]$Raw.Error) -TypeName ([string]$Raw.ErrorType) -What $what }
    if ($failure -ne '') {
        $rows += New-AdfaLapsRow -Scope $DomainName -Item $coverageItem -Status $script:Status.NotAssessed -NotRun $coverageNotRun `
            -Detail ("{0} No computer account of this domain was graded; this is not a clean result." -f $failure)
        $rows += New-AdfaLapsRow -Scope $DomainName -Item $dsrmGapItem -Status $script:Status.NotAssessed -NotRun $dsrmNotRun `
            -Detail ("{0} No domain controller of this domain was graded; this is not a clean result." -f $failure)
        return @($rows)
    }

    # 3. Classify what came back.
    $nowUtc = $Now.ToUniversalTime()
    $cutoff = $nowUtc.AddDays(-1 * $StaleDays)
    $computers = @($Raw.Computers | Where-Object { $null -ne $_ })
    $counts = [ordered]@{
        DomainController = 0; ServiceAccount = 0; Disabled = 0; NoOperatingSystem = 0; NonWindows = 0; BuildNotRead = 0
        NotCapable = 0; NoLogonRecorded = 0; Stale = 0; AccountControlNotRead = 0; InPopulation = 0
    }
    $domainControllers = New-Object System.Collections.ArrayList
    $withWindows = 0; $legacyOnly = 0; $notCapableWithLegacy = 0
    $anyExpirySeen = $false; $windowsExpirySeen = $false
    $noneVisibleNames = New-Object System.Collections.Generic.List[string]
    # Objects that could not be placed in or out of the population: not measured, so never
    # counted as measured-out. AccountControlNotRead could also be a domain controller.
    $unclassifiedNames = New-Object System.Collections.Generic.List[string]
    $noAccountControlNames = New-Object System.Collections.Generic.List[string]
    # A capped, name-ordered list, the cap being SampleLimit.
    $nameList = {
        param($Names, [string]$Label)
        $limit = [int]$Config['SampleLimit']
        $sorted = @($Names.ToArray())
        [array]::Sort($sorted, [System.StringComparer]::OrdinalIgnoreCase)
        if ($limit -le 0) { return (" {0}: names are not listed (SampleLimit is 0)." -f $Label) }
        if ($sorted.Count -gt $limit) { return (" {0} (showing {1} of {2}, in name order): {3}." -f $Label, $limit, $sorted.Count, (@($sorted | Select-Object -First $limit) -join ', ')) }
        return (" {0}: {1}." -f $Label, ($sorted -join ', '))
    }
    foreach ($computer in $computers) {
        $hasWindows = ($null -ne $computer.WindowsExpiry -and -not [string]::IsNullOrWhiteSpace([string]$computer.WindowsExpiry))
        $hasLegacy = ($null -ne $computer.LegacyExpiry -and -not [string]::IsNullOrWhiteSpace([string]$computer.LegacyExpiry))
        if ($hasWindows) { $windowsExpirySeen = $true }
        if ($hasWindows -or $hasLegacy) { $anyExpirySeen = $true }
        $class = Get-AdfaLapsComputerClass -Computer $computer -Config $Config -StaleCutoffUtc $cutoff
        $counts[$class] = [int]$counts[$class] + 1
        if ($class -eq 'DomainController') { [void]$domainControllers.Add($computer) }
        elseif ($class -eq 'AccountControlNotRead' -or $class -eq 'BuildNotRead') {
            $unclassifiedNames.Add([string]$computer.Name)
            if ($class -eq 'AccountControlNotRead') { $noAccountControlNames.Add([string]$computer.Name) }
        }
        elseif ($class -eq 'NotCapable') { if ($hasLegacy) { $notCapableWithLegacy++ } }
        elseif ($class -eq 'InPopulation') {
            if ($hasWindows) { $withWindows++ }
            elseif ($hasLegacy) { $legacyOnly++ }
            else { $noneVisibleNames.Add([string]$computer.Name) }
        }
    }
    $inPopulation = [int]$counts['InPopulation']
    $noneVisible = $noneVisibleNames.Count
    $outOfPopulation = $computers.Count - $inPopulation
    $schemaHasExpiry = ($SchemaState.HasWindowsExpiry -or $SchemaState.HasLegacyExpiry)
    $unclassified = $unclassifiedNames.Count

    # 4. The coverage row.
    $verdict = Get-AdfaLapsCoverageVerdict -TotalReturned $computers.Count -InPopulation $inPopulation -NoneVisible $noneVisible `
        -ProofOfRead $anyExpirySeen -SchemaHasExpiry $schemaHasExpiry -Config $Config -Unclassified $unclassified
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $percentText = ''
    if ($null -ne $verdict.Percent) { $percentText = ([double]$verdict.Percent).ToString('0.##', $inv) }
    $windowsName = [string]$Config['WindowsExpiry']
    $legacyName = [string]$Config['LegacyExpiry']
    $shareText = ("{0} of {1} computer account(s) in population ({2} %) have no LAPS expiry time visible to this account" -f $noneVisible, $inPopulation, $percentText)
    $lead = ''
    switch ([string]$verdict.State) {
        'NoObjects' { $lead = 'Not assessed: the computer query for this domain returned no object at all. Every domain holds at least the computer objects of its domain controllers, so an empty answer is an incomplete read, not an empty domain.' }
        'EmptyPopulation' { $lead = 'No computer account of this domain is in the population this row grades, so there is nothing to grade.' }
        'SchemaAbsent' { $lead = ("The forest schema carries neither {0} nor {1} (see the Windows LAPS schema row), so none of the {2} computer account(s) in population can have a LAPS password stored in this directory." -f $windowsName, $legacyName, $inPopulation) }
        'NoProofOfRead' { $lead = ("Not assessed: no LAPS expiry time is visible to this account on any of the {0} computer object(s) read in this domain, although the forest schema carries the attribute. LAPS not being deployed, this account having no right to read the attribute, and every device backing its password up to Microsoft Entra ID all look the same from here, so no computer is called unmanaged." -f $computers.Count) }
        'AllVisible' { $lead = ("Every one of the {0} computer account(s) in population has a LAPS expiry time visible to this account." -f $inPopulation) }
        'WithinTolerance' { $lead = ("{0}, which is not above the Warning threshold." -f $shareText) }
        'AboveFail' { $lead = ("{0}, which is above the Fail threshold of {1} %." -f $shareText, ([double]$Config['FailAbovePercent']).ToString('0.##', $inv)) }
        'Unclassified' {
            $lead = ("Not assessed: {0} computer object(s) of this domain could not be placed in or out of the population - account control flags not returned {1}, Windows with an OS build that could not be read {2} - so they are not measured, and the row is not graded Pass or 'nothing to grade' while they are not. Of the {3} computer account(s) that could be placed in population, {4} have no LAPS expiry time visible to this account." -f `
                    $unclassified, [int]$counts['AccountControlNotRead'], [int]$counts['BuildNotRead'], $inPopulation, $noneVisible)
        }
        default { $lead = ("{0}." -f $shareText) }
    }
    # A Warning or a Fail stands with unmeasured objects beside it, and says over what it was counted.
    if ($unclassified -gt 0 -and [string]$verdict.State -ne 'Unclassified' -and [string]$verdict.State -ne 'NoProofOfRead' -and [string]$verdict.State -ne 'NoObjects') {
        $lead = ("{0} The share is over the computers that could be classified: {1} more computer object(s) could not be placed in or out of the population, and are not measured." -f $lead, $unclassified)
    }
    $detail = $lead
    if ([string]$verdict.State -ne 'NoObjects') {
        $rule = ("Population rule: enabled computer accounts that are not domain controllers and not managed service accounts, whose operatingSystem begins with 'Windows', whose OS build can run Windows LAPS (17763, or 19041 and later - the release, not the patch level: the directory does not show whether the April 11, 2023 update is installed), and whose lastLogonTimestamp is within {0} day(s) (-StaleDays)." -f $StaleDays)
        $read = ("Read {0} computer object(s)." -f $computers.Count)
        $inText = ("In population {0}: Windows LAPS expiry time visible {1}; legacy Microsoft LAPS expiry time only {2}; no LAPS expiry time visible to this account {3}." -f $inPopulation, $withWindows, $legacyOnly, $noneVisible)
        $outText = ("Out of population {0}: domain controllers {1} (see the DSRM password backup rows); managed service accounts {2}; disabled {3}; no operatingSystem recorded {4}; operatingSystem not Windows {5}; Windows with an OS build that could not be read {6}; Windows release that cannot run Windows LAPS {7} (of them {8} with a legacy Microsoft LAPS expiry time visible); no logon recorded {9}; stale {10}; account control flags not returned {11}." -f `
                $outOfPopulation, [int]$counts['DomainController'], [int]$counts['ServiceAccount'], [int]$counts['Disabled'], [int]$counts['NoOperatingSystem'], [int]$counts['NonWindows'],
            [int]$counts['BuildNotRead'], [int]$counts['NotCapable'], $notCapableWithLegacy, [int]$counts['NoLogonRecorded'], [int]$counts['Stale'], [int]$counts['AccountControlNotRead'])
        $heuristic = 'A computer object with no operatingSystem value is how cluster and other virtual computer objects are left out; that is a tool heuristic, no Microsoft-documented marker for them was found.'
        $caveat = ''
        if ($schemaHasExpiry) {
            $caveat = ' For a single computer, not set and not readable look the same: an expiry time this account has no right to read is not returned, and permissions can differ between organizational units. A device that backs its password up to Microsoft Entra ID has no expiry time in this directory either.'
        }
        else { $caveat = ' A device that backs its password up to Microsoft Entra ID needs no attribute in this directory, and this read cannot see that.' }
        $sample = ''
        if ($noneVisible -gt 0 -and $schemaHasExpiry -and [string]$verdict.State -ne 'NoProofOfRead') {
            $sample = & $nameList $noneVisibleNames 'No LAPS expiry time visible'
        }
        if ($unclassified -gt 0) { $sample += & $nameList $unclassifiedNames 'Could not be classified' }
        $detail = ("{0}{1} {2} {3} {4} {5} {6}{7} {8}" -f $lead, $sample, $read, $inText, $outText, $rule, $heuristic, $caveat, (Get-AdfaLapsThresholdText -Config $Config))
    }
    $rows += New-AdfaLapsRow -Scope $DomainName -Item $coverageItem -Status ([string]$verdict.Status) -Detail $detail -NotRun $coverageNotRun

    # 5. One DSRM row per domain controller computer object - every one of them, in name order.
    # An object whose userAccountControl was not returned may be a domain controller: it gets no
    # DSRM row of its own, and the domain gets one Not Assessed row that names it.
    $noAccountControlText = ''
    if ($noAccountControlNames.Count -gt 0) {
        $noAccountControlText = ("{0} computer object(s) of this domain returned no userAccountControl, so it is not known whether any of them is a domain controller, and none of them has a DSRM row.{1}" -f `
                $noAccountControlNames.Count, (& $nameList $noAccountControlNames 'Without account control flags'))
    }
    if ($domainControllers.Count -eq 0) {
        $why = 'The computer query for this domain returned no domain controller computer object (none carries the SERVER_TRUST_ACCOUNT or PARTIAL_SECRETS_ACCOUNT flag). Every domain has at least one domain controller, so the answer is incomplete and nothing is concluded from it.'
        if ($noAccountControlText -ne '') { $why = ("{0} {1}" -f $why, $noAccountControlText) }
        $rows += New-AdfaLapsRow -Scope $DomainName -Item $dsrmGapItem -Status $script:Status.NotAssessed -Detail ("Not assessed: {0}" -f $why) -NotRun $dsrmNotRun
        return @($rows)
    }
    $partialSecrets = [int64]$Config['PartialSecretsFlag']
    foreach ($dc in @($domainControllers.ToArray() | Sort-Object -Property Name)) {
        $buildRaw = [string]$dc.OperatingSystemVersion
        $build = Get-AdfaOsBuild -OperatingSystemVersion $buildRaw
        $expiryPresent = ($null -ne $dc.WindowsExpiry -and -not [string]::IsNullOrWhiteSpace([string]$dc.WindowsExpiry))
        $expiryUtc = $null
        if ($expiryPresent) { $expiryUtc = ConvertTo-AdfaFileTimeUtc -Value $dc.WindowsExpiry }
        $isReadOnly = ((([int64]$dc.UserAccountControl) -band $partialSecrets) -ne 0)
        $dcVerdict = Get-AdfaLapsDsrmVerdict -Build $build -DomainLevel ([string]$Raw.DomainLevel) -ExpiryPresent $expiryPresent -ExpiryUtc $expiryUtc -Now $nowUtc `
            -ProofOfRead $windowsExpirySeen -SchemaRead ([bool]$SchemaState.Read) -HasWindowsExpiry ([bool]$SchemaState.HasWindowsExpiry) -IsReadOnly $isReadOnly -Config $Config
        $dcDetail = Get-AdfaLapsDsrmDetail -State ([string]$dcVerdict.State) -Build $build -BuildRaw $buildRaw -DomainLevel ([string]$Raw.DomainLevel) `
            -DomainLevelError ([string]$Raw.DomainLevelError) -ExpiryUtc $expiryUtc -ExpiryRaw ([string]$dc.WindowsExpiry) -IsReadOnly $isReadOnly -Config $Config
        $rows += New-AdfaLapsRow -Scope $DomainName -Item ("DSRM password backup: {0}" -f [string]$dc.Name) -Status ([string]$dcVerdict.Status) -Detail $dcDetail -NotRun $dsrmNotRun
    }
    if ($noAccountControlText -ne '') {
        $rows += New-AdfaLapsRow -Scope $DomainName -Item $dsrmGapItem -Status $script:Status.NotAssessed -NotRun $dsrmNotRun `
            -Detail ("Not assessed: {0} The DSRM rows of this domain cover the {1} domain controller computer object(s) that were recognised, and may not cover every domain controller." -f $noAccountControlText, $domainControllers.Count)
    }
    return @($rows)
}

function Get-AdfaLaps {
    <#
    .SYNOPSIS
        Windows LAPS: whether the forest schema carries the LAPS attributes, whether a DSRM
        password backup is visible for each domain controller, and how many enabled Windows
        computers of each scoped domain have no LAPS expiry time visible.
    .DESCRIPTION
        DIRECTORY READS ONLY, through two seams: Get-AdfaLapsSchemaRaw once per run, and
        Get-AdfaLapsDirectoryRaw once per scoped domain. No domain controller is connected to
        over CIM or the registry, no cmdlet of the LAPS module is called, and nothing is written.

        THIS SECTION NEVER READS A PASSWORD. The attributes that hold a LAPS password, an encrypted
        password, a password history or the password version are never in a property list and
        never in a filter on a computer object. Presence is judged only from the two expiry time
        attributes, which Microsoft documents as the scheduled expiration time and which are not
        confidential. A value this account has no right to read is not returned and looks like
        a value that is not set, so no row calls a computer unmanaged with certainty.

        Needs domain read access only. Microsoft publishes, in general, that authenticated
        users can read every attribute that is not confidential, and that the Windows LAPS
        expiry attribute is not confidential; it publishes no LAPS-specific statement of who
        can read the expiry attributes, and permissions can be changed per organizational unit.
        Where nothing at all is visible in a domain the rows are Not Assessed.

        A domain whose rows could not be built - an exception the grading did not expect - gets
        its two rows as Not Assessed with the error, and the other domains are still graded: no
        value in one domain ends the section or the run.

        DECLARED POPULATION: the domains named in -Domains. Each gets one "LAPS coverage:
        <domain>" row and at least one DSRM row, whatever happened to its read. The forest gets
        one "Windows LAPS schema" row. With the schema unread no domain is queried: without it
        the tool does not know which expiry attribute it may ask for.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$Domains = @(),
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config,
        [int]$StaleDays = 90,
        [Parameter(Mandatory)][datetime]$Now,
        [AllowEmptyString()][string]$ForestName = ''
    )
    $rows = @()
    $schemaNames = @(@([string]$Config['SchemaControl']) + @($Config['SchemaAttributes'] | ForEach-Object { [string]$_['Name'] }))
    $schemaRaw = Get-AdfaLapsSchemaRaw -AdParams $AdParams -AttributeNames $schemaNames
    $schemaState = Get-AdfaLapsSchemaState -Raw $schemaRaw -Config $Config
    $rows += Get-AdfaLapsSchemaFinding -SchemaState $schemaState -Config $Config -ForestName $ForestName

    $scoped = @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { ([string]$_).Trim() })
    if ($scoped.Count -eq 0) {
        $rows += New-AdfaLapsRow -Item 'LAPS coverage' -Status $script:Status.NotAssessed `
            -Detail 'No domain was scoped, so no computer account and no domain controller was read. This is not a clean result.'
        return @($rows)
    }
    $propertyNames = @()
    $propertyError = ''
    $windowsName = ''
    $legacyName = ''
    if ($schemaState.Read) {
        # A list the guard refuses is a defect in the config table. It must not reach the
        # directory, and it must not end the run either: every domain then says why it was not read.
        try { $propertyNames = @(Get-AdfaLapsPropertyList -SchemaState $schemaState -Config $Config) }
        catch { $propertyError = [string]$_.Exception.Message }
        if ($schemaState.HasWindowsExpiry) { $windowsName = [string]$Config['WindowsExpiry'] }
        if ($schemaState.HasLegacyExpiry) { $legacyName = [string]$Config['LegacyExpiry'] }
    }
    foreach ($domain in $scoped) {
        $raw = $null
        if ($propertyError -ne '') {
            $raw = [pscustomobject]@{ Ok = $false; Refused = $true; Error = $propertyError; ErrorType = ''; DomainLevel = ''; DomainLevelError = ''; Computers = @(); PropertyNames = @() }
        }
        elseif ($schemaState.Read) {
            $raw = Get-AdfaLapsDirectoryRaw -DomainName $domain -AdParams $AdParams -PropertyNames $propertyNames -NeverRead @($Config['NeverRead']) `
                -WindowsExpiryName $windowsName -LegacyExpiryName $legacyName
        }
        try {
            $rows += @(Get-AdfaLapsDomainFinding -DomainName $domain -Raw $raw -SchemaState $schemaState -Config $Config -StaleDays $StaleDays -Now $Now)
        }
        catch {
            # A defect in the grading, not in the directory. Fail closed for this domain only.
            $why = ("Not assessed: grading the computer objects of {0} failed inside this tool, so no row of this domain is graded; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$_.Exception.Message)
            $rows += New-AdfaLapsRow -Scope $domain -Item ("LAPS coverage: {0}" -f $domain) -Status $script:Status.NotAssessed -Detail $why
            $rows += New-AdfaLapsRow -Scope $domain -Item ("DSRM password backup - {0}" -f $domain) -Status $script:Status.NotAssessed -Detail $why
        }
    }
    return @($rows)
}

function Merge-AdfaLapsConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in Windows LAPS table, with validation. The
        Laps validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: WarnAbovePercent, FailAbovePercent, SampleLimit and
        ExpiredGraceDays - the four values that are this tool's own defaults:

            { "Laps": { "WarnAbovePercent": 5, "FailAbovePercent": 50 } }

        What it cannot: any attribute name, the list asked of every computer, the never-read
        list, the eligibility values Microsoft publishes and the sources. A file that could name
        an attribute could put a password attribute into a property list, so every such key is
        refused as unknown.

        Anything this tool could not use is refused with the reason: an override that is not one
        object, an empty object, an unknown key, a null, a value that is not a JSON number, a
        percentage outside 0 to 100, a Warning threshold of 100 (no share can exceed it, so no
        domain would ever be reported), a sample limit or a grace period that is not a whole
        number in its range. The MERGED table is then checked as a whole, so a file that names
        only FailAbovePercent is still refused when that puts Fail below the built-in Warning
        threshold.

        Provenance follows the values key by key: ThresholdSource is rewritten to name the
        override's source for exactly the keys it supplied, and goes on calling the rest tool
        defaults.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("Windows LAPS config override must be a single object with named keys (for example {{ ""WarnAbovePercent"": 5 }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) {
        throw 'Windows LAPS config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $percentKeys = @('WarnAbovePercent', 'FailAbovePercent')
    $known = @('WarnAbovePercent', 'FailAbovePercent', 'SampleLimit', 'ExpiredGraceDays')
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        # A misspelt key would otherwise be accepted, ignored, and leave the operator believing
        # their value was applied. An attribute name or NeverRead arrives here too, and is refused.
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("Windows LAPS config override names an unknown key '{0}'. Known keys: {1}. Attribute names and the never-read list cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        # Reachable only from an object built in memory with keys that differ by case; a key
        # written twice in a FILE is found in the text by Import-AdfaConfigOverride.
        if ($supplied -contains $name) { throw ("Windows LAPS config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) {
            throw ("Windows LAPS config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name)
        }
        # A JSON number only. "5" in quotes is refused rather than parsed: how a string becomes a
        # number depends on the culture of the host, and a threshold must not.
        if ($value -is [array] -or $numericTypes -notcontains $value.GetType()) {
            throw ("Windows LAPS config override sets '{0}' to a {1}. It must be a JSON number, written without quotes." -f $name, $value.GetType().Name)
        }
        $number = [double]$value
        if ([double]::IsNaN($number) -or [double]::IsInfinity($number)) {
            throw ("Windows LAPS config override sets '{0}' to a value that is not a finite number." -f $name)
        }
        $shown = $number.ToString('0.####', $inv)
        if ($percentKeys -contains $name) {
            if ($number -lt 0 -or $number -gt 100) {
                throw ("Windows LAPS config override sets '{0}' to {1}. A share of computers must be in the range 0 to 100." -f $name, $shown)
            }
            $merged[$name] = $number
        }
        elseif ($name -eq 'SampleLimit') {
            if ($number -ne [math]::Floor($number) -or $number -lt 0 -or $number -gt 1000) {
                throw ("Windows LAPS config override sets 'SampleLimit' to {0}. It must be a whole number from 0 to 1000; 0 lists no computer name." -f $shown)
            }
            $merged[$name] = [int]$number
        }
        else {
            if ($number -ne [math]::Floor($number) -or $number -lt 0 -or $number -gt 365) {
                throw ("Windows LAPS config override sets 'ExpiredGraceDays' to {0}. It must be a whole number of days from 0 to 365." -f $shown)
            }
            $merged[$name] = [int]$number
        }
        $supplied += $name
    }

    # The table as a whole, built-in values included.
    $warn = [double]$merged['WarnAbovePercent']
    $fail = [double]$merged['FailAbovePercent']
    if ($warn -ge 100) {
        throw ("Windows LAPS config: WarnAbovePercent is {0}. No share can be above 100 %, so no domain would ever be reported, whatever was found." -f $warn.ToString('0.####', $inv))
    }
    if ($fail -lt $warn) {
        throw ("Windows LAPS config: FailAbovePercent ({0}) is below WarnAbovePercent ({1}) once the override is applied. A domain would fail at a share at which it does not yet warn; set both." -f $fail.ToString('0.####', $inv), $warn.ToString('0.####', $inv))
    }

    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    if ($fromOverride.Count -gt 0) {
        $from = 'an override whose source was not recorded'
        if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
        $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
        $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
        if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
        $merged['ThresholdSource'] = $text
    }
    return $merged
}


# ---------------------------------------------------------------------------
# DC certificates: the certificate each DC presents on LDAPS, and those published for it in the
# directory (PORT-PLAN C5)
# ---------------------------------------------------------------------------

function New-AdfaDcCertificateRow {
    <#
    .SYNOPSIS
        Pure: one DC certificates row. Every row of the section has the same columns, so a
        consumer never has to test whether a column exists.
    .DESCRIPTION
        The text of a certificate - subject, issuer, subject alternative names - is chosen by
        whoever requested it, and the platform's chain status and policy errors are free text. All
        of it goes in its own columns (CertSubject, CertIssuer, CertSan, Ekus, SslPolicyErrors,
        ChainStatus), never in Detail: the consolidated findings choose a recommendation from
        Detail, and none of these columns is read there.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = '',
        [AllowEmptyString()][string]$Evidence = '',
        [AllowNull()]$Certificate = $null,
        [AllowNull()]$DaysLeft = $null,
        [AllowEmptyString()][string]$Ekus = '',
        [AllowEmptyString()][string]$SslPolicyErrors = '',
        [AllowEmptyString()][string]$ChainStatus = ''
    )
    $row = New-Finding -Scope $Scope -Area 'DcCertificates' -Item $Item -Status $Status -Detail $Detail
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $subject = ''
    $issuer = ''
    $san = ''
    $thumbprint = ''
    $notBefore = ''
    $notAfter = ''
    if ($null -ne $Certificate) {
        $subject = [string](Get-AdfaConfigValue -Entry $Certificate -Name 'Subject')
        $issuer = [string](Get-AdfaConfigValue -Entry $Certificate -Name 'Issuer')
        $san = [string](Get-AdfaConfigValue -Entry $Certificate -Name 'San')
        $thumbprint = [string](Get-AdfaConfigValue -Entry $Certificate -Name 'Thumbprint')
        $nb = Get-AdfaConfigValue -Entry $Certificate -Name 'NotBeforeUtc'
        if ($nb -is [datetime]) { $notBefore = $nb.ToString('yyyy-MM-dd HH:mm:ss', $inv) }
        $na = Get-AdfaConfigValue -Entry $Certificate -Name 'NotAfterUtc'
        if ($na -is [datetime]) { $notAfter = $na.ToString('yyyy-MM-dd HH:mm:ss', $inv) }
    }
    $days = ''
    if ($null -ne $DaysLeft) { $days = ([int]$DaysLeft).ToString($inv) }
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    $row | Add-Member -NotePropertyName 'Evidence' -NotePropertyValue $Evidence
    $row | Add-Member -NotePropertyName 'Thumbprint' -NotePropertyValue $thumbprint
    $row | Add-Member -NotePropertyName 'NotBeforeUtc' -NotePropertyValue $notBefore
    $row | Add-Member -NotePropertyName 'NotAfterUtc' -NotePropertyValue $notAfter
    $row | Add-Member -NotePropertyName 'DaysLeft' -NotePropertyValue $days
    $row | Add-Member -NotePropertyName 'CertSubject' -NotePropertyValue $subject
    $row | Add-Member -NotePropertyName 'CertIssuer' -NotePropertyValue $issuer
    $row | Add-Member -NotePropertyName 'CertSan' -NotePropertyValue $san
    $row | Add-Member -NotePropertyName 'Ekus' -NotePropertyValue $Ekus
    $row | Add-Member -NotePropertyName 'SslPolicyErrors' -NotePropertyValue $SslPolicyErrors
    $row | Add-Member -NotePropertyName 'ChainStatus' -NotePropertyValue $ChainStatus
    return $row
}

function ConvertTo-AdfaCertificateRecord {
    <#
    .SYNOPSIS
        A certificate as plain values: subject, issuer, thumbprint, serial number, validity in
        UTC, the EKU object identifiers and the subject alternative name as the platform formats
        it. Never throws.
    .DESCRIPTION
        Takes an X509Certificate or X509Certificate2 (what a TLS handshake hands over) or the
        DER bytes of one (what the directory holds in userCertificate). A copy is made in memory
        where needed; nothing is added to, opened in or read from any certificate store,
        PrivateKey and HasPrivateKey are never read, and nothing is exported.

        Bytes are read ONLY when X509Certificate2.GetCertContentType says they are one
        certificate ("Cert"). The byte-array constructor would also take a PKCS12 (PFX) blob and
        import its private key into a key container - a key file written to the profile of the
        account running the assessment - and a PKCS7 blob, of which it keeps only the signer
        (X509Certificate2 constructors, read 2026-11-16). Whoever can write userCertificate
        chooses those bytes, so any other content type is refused, with the type named, before
        a constructor sees it. GetCertContentType only identifies the content.

        NotBefore and NotAfter are documented by Microsoft as LOCAL time ("Gets the date in local
        time after which a certificate is no longer valid", X509Certificate2.NotAfter and
        .NotBefore, read 2026-11-16); both are converted to UTC here, once, and every comparison
        downstream is in UTC.

        HasEkuExtension tells a certificate with no EKU extension - which Microsoft documents as
        usable for all purposes (about_Certificate_Provider, read 2026-11-16) - from one whose
        extension lists purposes.
    .OUTPUTS
        [pscustomobject] Read, ReadError, Subject, Issuer, Thumbprint, SerialNumber, NotBeforeUtc,
        NotAfterUtc, Ekus, HasEkuExtension, San.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Certificate)
    $out = [pscustomobject]@{
        Read = $false; ReadError = ''; Subject = ''; Issuer = ''; Thumbprint = ''; SerialNumber = ''
        NotBeforeUtc = $null; NotAfterUtc = $null; Ekus = @(); HasEkuExtension = $false; San = ''
    }
    if ($null -eq $Certificate) { $out.ReadError = 'no certificate was handed over'; return $out }
    $copy = $null
    try {
        $cert = $null
        if ($Certificate -is [System.Security.Cryptography.X509Certificates.X509Certificate2]) { $cert = $Certificate }
        elseif ($Certificate -is [byte[]]) {
            # The content type first: a PFX would have its private key imported by the constructor.
            $contentType = [string][System.Security.Cryptography.X509Certificates.X509Certificate2]::GetCertContentType([byte[]]$Certificate)
            if ($contentType -ne 'Cert') {
                throw ("the value is a {0} blob, not a single DER certificate; it was not opened, so no key it may carry was imported" -f $contentType)
            }
            $copy = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList (, [byte[]]$Certificate)
            $cert = $copy
        }
        elseif ($Certificate -is [System.Security.Cryptography.X509Certificates.X509Certificate]) {
            $copy = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList $Certificate
            $cert = $copy
        }
        else { throw ("a {0} is not a certificate" -f $Certificate.GetType().FullName) }
        $out.Subject = [string]$cert.Subject
        $out.Issuer = [string]$cert.Issuer
        $out.Thumbprint = ([string]$cert.Thumbprint).ToUpperInvariant()
        $out.SerialNumber = ([string]$cert.SerialNumber).ToUpperInvariant()
        $out.NotBeforeUtc = [datetime]::SpecifyKind($cert.NotBefore.ToUniversalTime(), [System.DateTimeKind]::Utc)
        $out.NotAfterUtc = [datetime]::SpecifyKind($cert.NotAfter.ToUniversalTime(), [System.DateTimeKind]::Utc)
        foreach ($extension in @($cert.Extensions)) {
            $oid = [string]$extension.Oid.Value
            if ($oid -eq '2.5.29.37') {
                $out.HasEkuExtension = $true
                $eku = $extension
                if ($eku -isnot [System.Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]) {
                    $eku = New-Object System.Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension -ArgumentList $extension, $extension.Critical
                }
                $out.Ekus = @(foreach ($usage in $eku.EnhancedKeyUsages) { [string]$usage.Value })
            }
            elseif ($oid -eq '2.5.29.17') {
                $out.San = ([string]$extension.Format($false)).Trim()
            }
        }
        $out.Read = $true
    }
    catch {
        $out.Read = $false
        $out.ReadError = ("{0} ({1})" -f [string]$_.Exception.Message, $_.Exception.GetType().FullName)
    }
    finally {
        if ($null -ne $copy) { $copy.Reset() }
    }
    return $out
}

function Get-AdfaCertificateExpiryVerdict {
    <#
    .SYNOPSIS
        Pure: the status of one certificate on its validity dates alone, against an injected
        "now". Trust, name and purpose are not judged here.
    .DESCRIPTION
        Every date is converted to UTC before it is compared. In order:
          - a date that is missing                         -> Not Assessed (Unreadable)
          - NotAfter earlier than NotBefore                -> Not Assessed (Inconsistent)
          - now before NotBefore                           -> Warning (NotYetValid). The status
            is THIS TOOL'S RULE: Microsoft publishes none for a domain controller certificate
            that is not yet valid; the reference catalogue has no rule for it either.
          - now at or after NotAfter                       -> Fail (Expired). NotAfter equal to
            now counts as expired: the certificate has no validity left.
          - at most FailWithinDays whole days left         -> Fail (FailWindow), only when
            FailWithinDays is above 0
          - at most WarnWithinDays whole days left         -> Warning (ExpiringSoon), only when
            WarnWithinDays is above 0
          - otherwise                                      -> Pass (Valid)
        DaysLeft is the number of whole days from now to NotAfter, rounded down, so a
        certificate that expires in 30 days and 6 hours has 30 days left and is inside a 30-day
        window ("Warning at most 30 days left", the AdAssessment26 rule ADA-CERT-001).
    .OUTPUTS
        [pscustomobject] Status, State, DaysLeft ([int] or $null), Reason.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$NotBeforeUtc,
        [AllowNull()]$NotAfterUtc,
        [Parameter(Mandatory)][datetime]$NowUtc,
        [int]$WarnWithinDays = 30,
        [int]$FailWithinDays = 0,
        [AllowEmptyString()][string]$ThresholdSource = ''
    )
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $now = $NowUtc.ToUniversalTime()
    if ($NotBeforeUtc -isnot [datetime] -or $NotAfterUtc -isnot [datetime]) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'Unreadable'; DaysLeft = $null
            Reason = 'the validity dates of the certificate could not be read, so its expiry was not judged' }
    }
    $from = ([datetime]$NotBeforeUtc).ToUniversalTime()
    $to = ([datetime]$NotAfterUtc).ToUniversalTime()
    $fromText = $from.ToString('yyyy-MM-dd HH:mm:ss', $inv)
    $toText = $to.ToString('yyyy-MM-dd HH:mm:ss', $inv)
    if ($to -lt $from) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'Inconsistent'; DaysLeft = $null
            Reason = ("the certificate ends ({0} UTC) before it begins ({1} UTC), so its expiry was not judged" -f $toText, $fromText) }
    }
    $daysLeft = [int][math]::Floor(($to - $now).TotalDays)
    $source = $ThresholdSource
    if ([string]::IsNullOrWhiteSpace($source)) { $source = 'source not recorded' }
    if ($now -lt $from) {
        return [pscustomobject]@{ Status = $script:Status.Warning; State = 'NotYetValid'; DaysLeft = $daysLeft
            Reason = ("not yet valid: it begins on {0} UTC, after the time of this run, so it cannot be used now. That this is a Warning is this tool's rule, not a Microsoft value" -f $fromText) }
    }
    if ($now -ge $to) {
        $ago = [int][math]::Floor(($now - $to).TotalDays)
        return [pscustomobject]@{ Status = $script:Status.Fail; State = 'Expired'; DaysLeft = $daysLeft
            Reason = ("expired on {0} UTC, {1} whole day(s) before the time of this run" -f $toText, $ago) }
    }
    if ($FailWithinDays -gt 0 -and $daysLeft -le $FailWithinDays) {
        return [pscustomobject]@{ Status = $script:Status.Fail; State = 'FailWindow'; DaysLeft = $daysLeft
            Reason = ("{0} whole day(s) left, until {1} UTC: within the Fail window of {2} day(s) ({3})" -f $daysLeft, $toText, $FailWithinDays, $source) }
    }
    if ($WarnWithinDays -gt 0 -and $daysLeft -le $WarnWithinDays) {
        return [pscustomobject]@{ Status = $script:Status.Warning; State = 'ExpiringSoon'; DaysLeft = $daysLeft
            Reason = ("{0} whole day(s) left, until {1} UTC: within the Warning window of {2} day(s) ({3})" -f $daysLeft, $toText, $WarnWithinDays, $source) }
    }
    return [pscustomobject]@{ Status = $script:Status.Pass; State = 'Valid'; DaysLeft = $daysLeft
        Reason = ("valid from {0} to {1} UTC, {2} whole day(s) left; the Warning window is {3} day(s) ({4})" -f $fromText, $toText, $daysLeft, $WarnWithinDays, $source) }
}

function Get-AdfaCertificateEkuText {
    <#
    .SYNOPSIS
        Pure: the EKUs of a certificate as text, each object identifier with the name the config
        table gives it. "no EKU extension" is said as such, never as a missing purpose.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$Ekus = @(),
        [bool]$HasEkuExtension = $false,
        [AllowNull()]$EkuNames = @{}
    )
    if (-not $HasEkuExtension) { return 'no EKU extension (Microsoft documents a certificate with no EKU list as usable for all purposes)' }
    $parts = @()
    foreach ($oid in @($Ekus | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        $name = ''
        if ($null -ne $EkuNames) { $name = [string](Get-AdfaConfigValue -Entry $EkuNames -Name ([string]$oid)) }
        if ($name -ne '') { $parts += ("{0} ({1})" -f $name, $oid) } else { $parts += [string]$oid }
    }
    if ($parts.Count -eq 0) { return 'an EKU extension that lists no purpose' }
    return ($parts -join ', ')
}

function Get-AdfaSocketErrorClass {
    <#
    .SYNOPSIS
        Pure: the class of a failed TCP connection, from the SocketError name the platform gave.
    .DESCRIPTION
        ConnectionRefused (10061, "The remote host is actively refusing a connection"), TimedOut
        (10060), and the three name resolution failures HostNotFound (11001), TryAgain (11002) and
        NoData (11004) are told apart; anything else is ConnectFailed, quoted as reported. The
        values are .NET's SocketError enumeration, read on Microsoft Learn 2026-11-16:
        https://learn.microsoft.com/dotnet/api/system.net.sockets.socketerror
    .OUTPUTS
        [string] ConnectRefused | ConnectTimedOut | Unresolved | ConnectFailed
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyString()][string]$SocketError)
    switch -Regex ([string]$SocketError) {
        '^ConnectionRefused$' { return 'ConnectRefused' }
        '^TimedOut$' { return 'ConnectTimedOut' }
        '^(HostNotFound|TryAgain|NoData)$' { return 'Unresolved' }
    }
    return 'ConnectFailed'
}

function Get-AdfaTlsHandshakeErrorClass {
    <#
    .SYNOPSIS
        Pure: HandshakeTimedOut or HandshakeFailed, for a TLS handshake that threw, from the
        exception types and SocketError names found along the exception chain.
    .DESCRIPTION
        A synchronous read that runs past TcpClient.ReceiveTimeout throws an IOException ("If the
        time-out expires before Read successfully completes, TcpClient throws a IOException",
        read 2026-11-16) whose inner SocketException carries TimedOut. Anything else that stops
        the handshake - an AuthenticationException, a reset, a closed connection - is
        HandshakeFailed, and the caller quotes it.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyCollection()][string[]]$SocketErrors = @())
    if (@($SocketErrors | Where-Object { $_ -eq 'TimedOut' }).Count -gt 0) { return 'HandshakeTimedOut' }
    return 'HandshakeFailed'
}

function Get-AdfaExceptionChainInfo {
    <#
    .SYNOPSIS
        Pure: the type names, messages and SocketError names along an exception and its inner
        exceptions, outermost first.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Exception)
    $types = @()
    $messages = @()
    $socketErrors = @()
    $e = $Exception
    $depth = 0
    while ($null -ne $e -and $depth -lt 8) {
        $depth++
        # PowerShell's own wrapper around a .NET method call adds nothing but "Exception calling
        # <method>": the inner exception is what the platform reported.
        if ($e -is [System.Management.Automation.MethodInvocationException] -and $null -ne $e.InnerException) {
            $e = $e.InnerException
            continue
        }
        $types += [string]$e.GetType().FullName
        $messages += ([string]$e.Message).Trim()
        if ($e -is [System.Net.Sockets.SocketException]) { $socketErrors += [string]$e.SocketErrorCode }
        $e = $e.InnerException
    }
    return [pscustomobject]@{ Types = @($types); Messages = @($messages); SocketErrors = @($socketErrors) }
}

function Get-AdfaTlsProbeClass {
    <#
    .SYNOPSIS
        Pure: the class of one handshake attempt, from what happened during it.
    .DESCRIPTION
        In order:
          - no connection, and the connection attempt threw  -> the class of its SocketError
            (Get-AdfaSocketErrorClass)
          - no connection, and nothing threw                 -> ConnectTimedOut (the wait for the
            connection ran out)
          - a certificate reached the validation callback    -> Presented, EVEN IF the handshake
            then threw or the deadline then closed the connection: the certificate was handed over
          - the handshake threw after the deadline closed it -> HandshakeTimedOut
          - the handshake threw                              -> Get-AdfaTlsHandshakeErrorClass
          - the handshake ended with no certificate          -> NoCertificate
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [bool]$Connected = $false,
        [bool]$ConnectThrew = $false,
        [AllowNull()][AllowEmptyString()][string]$ConnectSocketError = '',
        [bool]$CertificateSeen = $false,
        [bool]$HandshakeThrew = $false,
        [AllowNull()][AllowEmptyCollection()][string[]]$HandshakeSocketErrors = @(),
        [bool]$DeadlineExpired = $false
    )
    if (-not $Connected) {
        if ($ConnectThrew) { return (Get-AdfaSocketErrorClass -SocketError $ConnectSocketError) }
        return 'ConnectTimedOut'
    }
    if ($CertificateSeen) { return 'Presented' }
    if ($HandshakeThrew) {
        if ($DeadlineExpired) { return 'HandshakeTimedOut' }
        return (Get-AdfaTlsHandshakeErrorClass -SocketErrors @($HandshakeSocketErrors))
    }
    return 'NoCertificate'
}

function Get-AdfaDcTlsCertificateRaw {
    <#
    .SYNOPSIS
        The certificate one DC presents on its LDAPS port, read with a TLS handshake that sends
        nothing but the handshake. Never throws.
    .DESCRIPTION
        One TCP connection, bounded by -ConnectTimeoutMs (BeginConnect and a wait, the pattern
        Test-TcpPort uses), then SslStream.AuthenticateAsClient(<DC host name>) - the overload
        that "No client certificates are used in the authentication. The certificate revocation
        list is not checked during authentication." (read 2026-11-16). It is called synchronously
        so that the validation callback, a PowerShell script block, runs on the calling thread.

        THE WHOLE HANDSHAKE IS BOUNDED by -HandshakeTimeoutMs. The synchronous handshake has no
        timeout of its own, and the socket's ReceiveTimeout restarts on every read, so a peer
        that sends one byte at a time inside it could hold this call for hours. A deadline is
        therefore armed first: a second runspace of this process waits on an event for
        -HandshakeTimeoutMs and, if the handshake has not ended by then, shuts the socket down
        and closes it, which makes the blocked read return. It touches nothing but this
        connection. If the deadline cannot be armed, no handshake is made (class Error). The
        socket's ReceiveTimeout and SendTimeout are still set, as an inner bound on one read.

        The validation callback copies the certificate, the platform's SslPolicyErrors and the
        status of the chain the platform built, and RETURNS TRUE: this tool neither trusts nor
        rejects the certificate. Returning false would make the client abort the handshake, and
        Microsoft documents Schannel error logging as on by default; a completed handshake
        avoids an abort sent by this client. The stream and the connection are then closed at
        once: no byte of application data is written, so no LDAP request, no bind and no
        credential is ever sent ("When connecting to ports 636 or 3269, SSL/TLS is negotiated
        before any LDAP traffic is exchanged", KB 321051, read 2026-11-16).

        WHAT THIS CANNOT RULE OUT, and why it runs only with -IncludeLdapsHandshake: Microsoft
        does not state that a TLS handshake leaves no trace on the server. A DC that cannot
        complete the handshake may log a Schannel error in its System log. And building the
        chain on this host may fetch issuer certificates from the AIA locations a certificate
        names - an outbound request from the host running the assessment, not to the DC - which
        Microsoft documents as controllable only on .NET 5 and later.

        The connection is bounded by -ConnectTimeoutMs. When that wait runs out the class is
        ConnectTimedOut; a refusal is ConnectRefused only when it is reported within the bound
        (Windows reported a refused loopback connection after about 2 s in this tool's tests).

        Classes (Get-AdfaTlsProbeClass): Presented (a certificate was handed over),
        ConnectRefused, ConnectTimedOut, Unresolved, ConnectFailed, HandshakeTimedOut,
        HandshakeFailed, NoCertificate (the handshake ended and no certificate reached the
        callback), Error (a defect in this tool, or a deadline that could not be armed).
    .OUTPUTS
        [pscustomobject] Ok, Class, Error, ErrorType, SocketError, Certificate (a record from
        ConvertTo-AdfaCertificateRecord, or $null), SslPolicyErrors, ChainStatus, CallbackRan,
        DeadlineExpired, ElapsedMs.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][int]$Port,
        [int]$ConnectTimeoutMs = 5000,
        [int]$HandshakeTimeoutMs = 5000
    )
    $out = [pscustomobject]@{
        Ok = $false; Class = ''; Error = ''; ErrorType = ''; SocketError = ''; Certificate = $null
        SslPolicyErrors = ''; ChainStatus = @(); CallbackRan = $false; DeadlineExpired = $false; ElapsedMs = 0
    }
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    $client = $null
    $ssl = $null
    $deadline = $null
    $deadlineHandle = $null
    $deadlineSignal = $null
    # What the callback saw. A hashtable, so the script block below writes into this object and
    # not into a variable of its own scope.
    $seen = @{ Ran = $false; Certificate = $null; Errors = ''; Chain = @() }
    # Written by the deadline's runspace, so synchronized.
    $deadlineState = [hashtable]::Synchronized(@{ Fired = $false; CloseError = '' })
    try {
        $client = New-Object System.Net.Sockets.TcpClient
        $connected = $false
        $connectThrew = $false
        $connectSocketError = ''
        $handshakeError = $null
        $handshakeSocketErrors = @()
        try {
            $pending = $client.BeginConnect($ComputerName, $Port, $null, $null)
            if ($pending.AsyncWaitHandle.WaitOne($ConnectTimeoutMs, $false)) {
                $client.EndConnect($pending)
                $connected = $true
            }
            else {
                $out.Error = ("no TCP connection to port {0} within {1} ms" -f $Port, $ConnectTimeoutMs)
            }
        }
        catch {
            $connectThrew = $true
            $chainInfo = Get-AdfaExceptionChainInfo -Exception $_.Exception
            if (@($chainInfo.SocketErrors).Count -gt 0) { $connectSocketError = [string]@($chainInfo.SocketErrors)[0] }
            $out.SocketError = $connectSocketError
            $out.Error = (@($chainInfo.Messages) -join ' -> ')
            $out.ErrorType = (@($chainInfo.Types) -join ' -> ')
        }
        if ($connected) {
            $client.ReceiveTimeout = $HandshakeTimeoutMs
            $client.SendTimeout = $HandshakeTimeoutMs
            $callback = [System.Net.Security.RemoteCertificateValidationCallback] {
                param($source, $certificate, $chain, $policyErrors)
                $seen['Ran'] = $true
                if ($null -ne $certificate) {
                    # A copy, so the values outlive the stream that is closed below.
                    $seen['Certificate'] = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList $certificate
                }
                $seen['Errors'] = [string]$policyErrors
                $statusLines = @()
                if ($null -ne $chain) {
                    foreach ($status in @($chain.ChainStatus)) {
                        $statusLines += ("{0}: {1}" -f [string]$status.Status, ([string]$status.StatusInformation).Trim())
                    }
                }
                $seen['Chain'] = @($statusLines)
                # Neither trusted nor rejected by this tool: the handshake is allowed to finish
                # so that no abort is sent, and nothing is written afterwards.
                return $true
            }
            $ssl = New-Object System.Net.Security.SslStream -ArgumentList $client.GetStream(), $false, $callback
            # The deadline, armed before the handshake starts. If it cannot be armed, the
            # handshake is not made: an unbounded handshake is not run.
            try {
                $deadlineSignal = New-Object System.Threading.ManualResetEvent -ArgumentList $false
                $deadline = [powershell]::Create()
                # Runs in the deadline's own runspace: waits on the event, and only if the wait
                # runs out shuts down and closes THIS connection. Nothing else is touched.
                $deadlineScript = 'param($Client, $Signal, $TimeoutMs, $State)
if (-not $Signal.WaitOne($TimeoutMs)) {
    $State["Fired"] = $true
    try { $Client.Client.Shutdown([System.Net.Sockets.SocketShutdown]::Both) } catch { $State["CloseError"] = [string]$_.Exception.Message }
    try { $Client.Close() } catch { $State["CloseError"] = [string]$_.Exception.Message }
}'
                [void]$deadline.AddScript($deadlineScript)
                [void]$deadline.AddArgument($client).AddArgument($deadlineSignal).AddArgument($HandshakeTimeoutMs).AddArgument($deadlineState)
                $deadlineHandle = $deadline.BeginInvoke()
            }
            catch {
                throw ("the handshake deadline could not be armed, so no handshake was made: {0}" -f [string]$_.Exception.Message)
            }
            try { $ssl.AuthenticateAsClient($ComputerName) }
            catch { $handshakeError = $_.Exception }
            finally {
                [void]$deadlineSignal.Set()
                try { [void]$deadline.EndInvoke($deadlineHandle) } catch { $deadlineState['CloseError'] = [string]$_.Exception.Message }
                $deadlineHandle = $null
            }
            $out.DeadlineExpired = [bool]$deadlineState['Fired']
            $out.CallbackRan = [bool]$seen['Ran']
            $out.SslPolicyErrors = [string]$seen['Errors']
            $out.ChainStatus = @($seen['Chain'])
            if ($null -ne $handshakeError) {
                $chainInfo = Get-AdfaExceptionChainInfo -Exception $handshakeError
                $out.Error = (@($chainInfo.Messages) -join ' -> ')
                $out.ErrorType = (@($chainInfo.Types) -join ' -> ')
                $handshakeSocketErrors = @($chainInfo.SocketErrors)
                if ($handshakeSocketErrors.Count -gt 0) { $out.SocketError = [string]$handshakeSocketErrors[0] }
            }
            if ($out.DeadlineExpired) {
                $out.Error = ("the handshake did not end within {0} ms, so the connection was closed. {1}" -f $HandshakeTimeoutMs, $out.Error).Trim()
            }
        }
        $out.Class = Get-AdfaTlsProbeClass -Connected $connected -ConnectThrew $connectThrew -ConnectSocketError $connectSocketError `
            -CertificateSeen ($null -ne $seen['Certificate']) -HandshakeThrew ($null -ne $handshakeError) -HandshakeSocketErrors @($handshakeSocketErrors) `
            -DeadlineExpired ([bool]$out.DeadlineExpired)
        if ($out.Class -eq 'Presented') {
            # The certificate was handed over, even if the handshake failed after it.
            $out.Certificate = ConvertTo-AdfaCertificateRecord -Certificate $seen['Certificate']
            $out.Ok = $true
        }
        elseif ($out.Class -eq 'NoCertificate') {
            $out.Error = 'the handshake ended without a certificate reaching the validation callback'
        }
    }
    catch {
        $out.Ok = $false
        $out.Class = 'Error'
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    finally {
        if ($null -ne $deadlineSignal) { try { [void]$deadlineSignal.Set() } catch { $out.Error = ("{0} (releasing the deadline: {1})" -f $out.Error, $_.Exception.Message).Trim() } }
        if ($null -ne $deadline) {
            try {
                if ($null -ne $deadlineHandle) { [void]$deadline.EndInvoke($deadlineHandle) }
                $deadline.Dispose()
            }
            catch { $out.Error = ("{0} (ending the deadline: {1})" -f $out.Error, $_.Exception.Message).Trim() }
        }
        if ($null -ne $deadlineSignal) { $deadlineSignal.Dispose() }
        if ($null -ne $ssl) { try { $ssl.Dispose() } catch { $out.Error = ("{0} (closing the stream: {1})" -f $out.Error, $_.Exception.Message).Trim() } }
        if ($null -ne $client) { try { $client.Close() } catch { $out.Error = ("{0} (closing the connection: {1})" -f $out.Error, $_.Exception.Message).Trim() } }
        if ($seen['Certificate'] -is [System.Security.Cryptography.X509Certificates.X509Certificate2]) { $seen['Certificate'].Reset() }
        $watch.Stop()
        $out.ElapsedMs = [int]$watch.ElapsedMilliseconds
    }
    return $out
}

function ConvertTo-AdfaLdapFilterValue {
    <#
    .SYNOPSIS
        Pure: a value escaped for an LDAP search filter. "If any of the following special
        characters must appear in the search filter as literals, they must be replaced by the
        listed escape sequence": * \2a, ( \28, ) \29, \ \5c, NUL \00, / \2f.
        https://learn.microsoft.com/windows/win32/adsi/search-filter-syntax (read 2026-11-16).
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyString()][string]$Value)
    if ($null -eq $Value) { return '' }
    $builder = New-Object System.Text.StringBuilder
    foreach ($ch in $Value.ToCharArray()) {
        switch ([int]$ch) {
            0x5C { [void]$builder.Append('\5c'); continue }
            0x2A { [void]$builder.Append('\2a'); continue }
            0x28 { [void]$builder.Append('\28'); continue }
            0x29 { [void]$builder.Append('\29'); continue }
            0x00 { [void]$builder.Append('\00'); continue }
            0x2F { [void]$builder.Append('\2f'); continue }
            default { [void]$builder.Append($ch) }
        }
    }
    return $builder.ToString()
}

function Get-AdfaDcCertificateDirectoryRaw {
    <#
    .SYNOPSIS
        The userCertificate values of one domain controller's computer object, found by its DNS
        host name. One read-only directory query. Never throws.
    .DESCRIPTION
        Get-ADComputer with -LDAPFilter (&(objectClass=computer)(dNSHostName=<host>)) and
        -Properties userCertificate, against -Server: the DC's domain where the caller knows it,
        otherwise the DC itself. -Identity is not used because it does not accept a DNS host
        name ("distinguished name, GUID, security identifier (SID) or Security Accounts Manager
        (SAM) account name", Get-ADComputer, read 2026-11-16).

        userCertificate is multi-valued; each value is "the DER-encoded X.509v3 certificates
        issued to the user ... by Microsoft Certificate Service" (X509-Cert, read 2026-11-16). A
        value that is not a byte array is kept as unreadable, never dropped.
    .OUTPUTS
        [pscustomobject] Ok, Error, ErrorType, Server, ObjectCount, AttributeReturned, Values
        (byte[] each, or the raw value where it was not bytes).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$HostName,
        [AllowEmptyString()][string]$Server = '',
        [hashtable]$AdParams = @{}
    )
    $target = $Server
    if ([string]::IsNullOrWhiteSpace($target)) { $target = $HostName }
    $out = [pscustomobject]@{ Ok = $false; Error = ''; ErrorType = ''; Server = $target; ObjectCount = 0; AttributeReturned = $false; Values = @() }
    try {
        $computerArgs = @{} + $AdParams
        $computerArgs.Server = $target
        $computerArgs.LDAPFilter = ('(&(objectClass=computer)(dNSHostName={0}))' -f (ConvertTo-AdfaLdapFilterValue -Value $HostName))
        $computerArgs.Properties = @('userCertificate')
        $computerArgs.ErrorAction = 'Stop'
        $objects = @(Get-ADComputer @computerArgs | Where-Object { $null -ne $_ })
        $out.ObjectCount = $objects.Count
        if ($objects.Count -eq 1) {
            $values = New-Object System.Collections.ArrayList
            $property = $objects[0].PSObject.Properties['userCertificate']
            if ($null -ne $property) {
                $out.AttributeReturned = $true
                $value = $property.Value
                if ($value -is [byte[]]) { [void]$values.Add($value) }
                elseif ($null -ne $value) {
                    foreach ($item in $value) { if ($null -ne $item) { [void]$values.Add($item) } }
                }
            }
            $out.Values = $values.ToArray()
        }
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Get-AdfaDcLdapsFinding {
    <#
    .SYNOPSIS
        Pure: the one "LDAPS certificate: <dc>" row of a domain controller, from what the
        handshake seam returned (or from the fact that it was not run, or that the port did not
        answer).
    .DESCRIPTION
        Only expiry is graded, with Get-AdfaCertificateExpiryVerdict. Every other outcome is Not
        Assessed with its own cause, and none of them is read as "this DC has no certificate":
        Microsoft does not document what a DC without a usable certificate does on port 636
        (refuses the connection, or accepts it and fails the handshake), so the row says what
        was observed and no more.

        The subject, the issuer, the EKUs and the platform's SslPolicyErrors and ChainStatus are
        evidence columns, not graded: they describe the trust of the host running the
        assessment, which may not be a client of the domain at all.
    .OUTPUTS
        [pscustomobject] One row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [AllowEmptyString()][string]$Scope = '',
        [bool]$HandshakeRun = $false,
        [bool]$PortAnswered = $false,
        [AllowNull()]$Raw = $null,
        [Parameter(Mandatory)][hashtable]$Config,
        [Parameter(Mandatory)][datetime]$NowUtc,
        [int]$PortTimeoutMs = 1200,
        # PORT-PLAN C14c: the reachability class of a DC classified Unreachable, which was not probed.
        [AllowEmptyString()][string]$ReachCause = ''
    )
    $item = ("LDAPS certificate: {0}" -f $DomainController)
    $port = [int]$Config['LdapsPort']
    $handshakeTimeout = [int]$Config['HandshakeTimeoutMs']
    $connectTimeout = [int]$Config['ConnectTimeoutMs']
    $notRun ='Not read: the certificate stores of the DC (the NTDS service store, which Microsoft documents AD DS checks first, and LocalMachine\My) - PORT-PLAN C5a; revocation; and whether the clients of this DC trust the chain and accept the name. What the platform of the host running the assessment reported about chain and name is quoted in SslPolicyErrors and ChainStatus and is not graded.'
    if (-not $HandshakeRun) {
        return (New-AdfaDcCertificateRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence 'none' -NotRun $notRun `
                -Detail ("Not run: the LDAPS handshake is opt-in (-IncludeLdapsHandshake). Microsoft documents Schannel error logging as on by default and does not state that a TLS handshake leaves no trace on the server, so a handshake this DC cannot complete may write an error event to its System log. No connection was made to port {0}, so the certificate this DC presents is not known." -f $port))
    }
    if (-not [string]::IsNullOrWhiteSpace($ReachCause)) {
        return (New-AdfaDcCertificateRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence 'none' -NotRun $notRun `
                -Detail (Get-AdfaDcGateText -Cause $ReachCause -NotRead ('port {0} was not probed and no handshake was attempted' -f $port)))
    }
    if (-not $PortAnswered) {
        return (New-AdfaDcCertificateRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence 'none' -NotRun $notRun `
                -Detail ("Unreachable: port {0} did not accept a TCP connection within {1} ms on the shared port probe, so no handshake was attempted. That probe does not tell a refused connection from a filtered or slow one. Microsoft does not document what a DC without a usable certificate does on this port, so this is not read as the DC having no certificate." -f $port, $PortTimeoutMs))
    }
    if ($null -eq $Raw) {
        return (New-AdfaDcCertificateRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence 'none' -NotRun $notRun `
                -Detail 'Not assessed: the handshake returned nothing. This is a defect in the tool, not a result.')
    }
    $class = [string]$Raw.Class
    $reported = ([string]$Raw.Error).Trim()
    if ($reported -eq '') { $reported = '(no error text was returned)' }
    $type = ([string]$Raw.ErrorType).Trim()
    if ($type -ne '') { $reported = ("{0} (exception type: {1})" -f $reported, $type) }
    $policy = [string]$Raw.SslPolicyErrors
    $chain = (@($Raw.ChainStatus) -join ' | ')
    $noConclusion = 'Microsoft does not document what a DC without a usable certificate does on this port, so this is not read as the DC having no certificate.'
    switch ($class) {
        'Presented' {
            $record = $Raw.Certificate
            if ($null -eq $record -or -not [bool](Get-AdfaConfigValue -Entry $record -Name 'Read')) {
                $why = '(no record)'
                if ($null -ne $record) { $why = [string](Get-AdfaConfigValue -Entry $record -Name 'ReadError') }
                return (New-AdfaDcCertificateRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence 'LDAPS handshake' -NotRun $notRun `
                        -SslPolicyErrors $policy -ChainStatus $chain `
                        -Detail ("Read failed: the DC presented a certificate on port {0}, but it could not be read, so its expiry was not judged. Reported - {1}" -f $port, $why))
            }
            $verdict = Get-AdfaCertificateExpiryVerdict -NotBeforeUtc $record.NotBeforeUtc -NotAfterUtc $record.NotAfterUtc -NowUtc $NowUtc `
                -WarnWithinDays ([int]$Config['WarnWithinDays']) -FailWithinDays ([int]$Config['FailWithinDays']) -ThresholdSource ([string]$Config['ThresholdSource'])
            $ekuText = Get-AdfaCertificateEkuText -Ekus @($record.Ekus) -HasEkuExtension ([bool]$record.HasEkuExtension) -EkuNames $Config['EkuNames']
            $detail = ("Presented on LDAPS port {0}: {1}. Thumbprint {2}." -f $port, [string]$verdict.Reason, [string]$record.Thumbprint)
            if ([string]$Raw.Error -ne '') {
                $detail = ("{0} The handshake ended with an error after the certificate was received - {1}" -f $detail, $reported)
            }
            $detail = ("{0} Only expiry is graded. Microsoft documents that a domain controller with several usable certificates may present any of them, so a certificate it holds but did not present here is not seen by this read." -f $detail)
            return (New-AdfaDcCertificateRow -Scope $Scope -Item $item -Status ([string]$verdict.Status) -Evidence 'LDAPS handshake' -NotRun $notRun `
                    -Certificate $record -DaysLeft $verdict.DaysLeft -Ekus $ekuText -SslPolicyErrors $policy -ChainStatus $chain -Detail $detail)
        }
        'ConnectRefused' { $detail = ("Refused: the connection for the handshake to port {0} was actively refused, although the shared port probe had connected. Reported - {1}. {2}" -f $port, $reported, $noConclusion) }
        'ConnectTimedOut' { $detail = ("Timed out: the connection for the handshake to port {0} was not made within {1} ms, although the shared port probe had connected. A refusal is told apart only when it is reported within that bound (Windows reported a refused loopback connection after about 2 s in this tool's tests, which is not a Microsoft value). Reported - {2}. {3}" -f $port, $connectTimeout, $reported, $noConclusion) }
        'Unresolved' { $detail = ("Unresolved: the DC's host name did not resolve when the handshake connected, although the shared port probe had connected. Reported - {0}" -f $reported) }
        'ConnectFailed' { $detail = ("Connection failed: the connection for the handshake to port {0} failed. Reported - {1}. {2}" -f $port, $reported, $noConclusion) }
        'HandshakeTimedOut' { $detail = ("Handshake timed out: port {0} accepted the connection, but the TLS handshake did not complete within {1} ms, so the connection was closed, and no certificate was received. Reported - {2}. {3}" -f $port, $handshakeTimeout, $reported, $noConclusion) }
        'HandshakeFailed' { $detail = ("Handshake failed: port {0} accepted the connection, but the TLS handshake did not complete and no certificate was received. A DC that has no usable certificate is one possible cause. Reported - {1}. {2}" -f $port, $reported, $noConclusion) }
        'NoCertificate' { $detail = ("No certificate: the handshake on port {0} ended without a certificate being handed over. Reported - {1}. {2}" -f $port, $reported, $noConclusion) }
        default { $detail = ("Not assessed: the handshake could not be made because of an error inside this tool ({0}); this is a defect in the tool, not a result. Reported - {1}" -f $class, $reported) }
    }
    return (New-AdfaDcCertificateRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence 'LDAPS handshake' -NotRun $notRun `
            -SslPolicyErrors $policy -ChainStatus $chain -Detail $detail)
}

function Get-AdfaDcDirectoryCertificateFinding {
    <#
    .SYNOPSIS
        The rows of one domain controller's userCertificate values: one "Directory certificate:
        <dc> [<thumbprint>]" row per value, or one "Directory certificates: <dc>" row when the
        read failed or returned no value.
    .DESCRIPTION
        DIRECTORY EVIDENCE: a value proves that a CA published that certificate for the DC's
        computer object, not that the DC holds it or presents it. Its expiry is graded the same
        way as the presented certificate's, and the row says what it is evidence of.

        A published value is not necessarily a domain controller certificate: Microsoft's table
        of default templates lists "Domain Controller" (version 1) and "Directory E-mail
        Replication" (version 2) among the computer templates published to AD DS, so the EKUs
        of every value are reported in the Ekus column.

        No value is NEVER a finding against the DC, and is Info: of the DC templates, "Domain
        Controller Authentication" and "Kerberos Authentication" are not published to AD DS by
        default, and publication is a separate operation from issuance (certificate-template-
        concepts, manage-certificate-templates, read 2026-11-16). A value this account has no
        right to read also looks like none, and who can read the attribute by default is not
        published.

        A failed read is Not Assessed, worded by Get-AdfaLapsReadFailureLead (Unreachable /
        Access denied / Timed out / Read failed). No object, or more than one, with the DC's DNS
        host name is Not Assessed too.
    .OUTPUTS
        [pscustomobject[]] Rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [AllowEmptyString()][string]$Scope = '',
        [AllowNull()]$Raw = $null,
        [Parameter(Mandatory)][hashtable]$Config,
        [Parameter(Mandatory)][datetime]$NowUtc,
        [AllowEmptyString()][string]$PresentedThumbprint = ''
    )
    $groupItem = ("Directory certificates: {0}" -f $DomainController)
    $notRun = 'Directory evidence only: whether the DC still holds or presents a published certificate is not read here, and its certificate stores are not read - PORT-PLAN C5a.'
    $what = ("the userCertificate attribute of {0}" -f $DomainController)
    if ($null -eq $Raw) {
        return @(New-AdfaDcCertificateRow -Scope $Scope -Item $groupItem -Status $script:Status.NotAssessed -Evidence 'Directory userCertificate' -NotRun $notRun `
                -Detail 'Not assessed: the directory read returned nothing. This is a defect in the tool, not a result.')
    }
    $server = [string]$Raw.Server
    $from = ("Read from {0}." -f $server)
    if ([string]::IsNullOrWhiteSpace($Scope)) {
        $from = ("Read from {0}, the DC itself, because this DC came from an enumeration that does not say which domain it belongs to." -f $server)
    }
    if (-not [bool]$Raw.Ok) {
        $lead = Get-AdfaLapsReadFailureLead -Message ([string]$Raw.Error) -TypeName ([string]$Raw.ErrorType) -What $what
        return @(New-AdfaDcCertificateRow -Scope $Scope -Item $groupItem -Status $script:Status.NotAssessed -Evidence 'Directory userCertificate' -NotRun $notRun `
                -Detail ("{0} {1}" -f $lead, $from))
    }
    $count = [int]$Raw.ObjectCount
    if ($count -eq 0) {
        return @(New-AdfaDcCertificateRow -Scope $Scope -Item $groupItem -Status $script:Status.NotAssessed -Evidence 'Directory userCertificate' -NotRun $notRun `
                -Detail ("Not found: no computer object with dNSHostName {0} was returned, so {1} was not read. {2}" -f $DomainController, $what, $from))
    }
    if ($count -gt 1) {
        return @(New-AdfaDcCertificateRow -Scope $Scope -Item $groupItem -Status $script:Status.NotAssessed -Evidence 'Directory userCertificate' -NotRun $notRun `
                -Detail ("Ambiguous: {0} computer objects carry dNSHostName {1}, and which of them is the DC cannot be told, so none was read. {2}" -f $count, $DomainController, $from))
    }
    # A lone byte array is ONE value. @() would turn it into one value per byte.
    $values = @()
    if ($Raw.Values -is [byte[]]) { $values = @(, [byte[]]$Raw.Values) }
    elseif ($null -ne $Raw.Values) { $values = @($Raw.Values) }
    if ($values.Count -eq 0) {
        return @(New-AdfaDcCertificateRow -Scope $Scope -Item $groupItem -Status $script:Status.Info -Evidence 'Directory userCertificate' -NotRun $notRun `
                -Detail ("No certificate is published for this DC in the directory: userCertificate has no value visible to this account. That is not evidence that the DC holds no certificate. Of Microsoft's default domain controller templates, 'Domain Controller' (version 1) is published to AD DS, while 'Domain Controller Authentication' and 'Kerberos Authentication' are not, and publication is a separate operation from issuance. A value this account has no right to read also looks like none. {0}" -f $from))
    }
    $rows = @()
    $index = 0
    foreach ($value in $values) {
        $index++
        $record = $null
        if ($value -is [byte[]]) { $record = ConvertTo-AdfaCertificateRecord -Certificate ([byte[]]$value) }
        if ($null -eq $record -or -not [bool]$record.Read) {
            $why = 'the value is not a byte array'
            if ($null -ne $record) { $why = [string]$record.ReadError }
            $rows += New-AdfaDcCertificateRow -Scope $Scope -Item ("Directory certificate: {0} [value {1}]" -f $DomainController, $index) -Status $script:Status.NotAssessed `
                -Evidence 'Directory userCertificate' -NotRun $notRun `
                -Detail ("Read failed: value {0} of {1} of {2} could not be read as a certificate, so its expiry was not judged. Reported - {3}. {4}" -f $index, $values.Count, $what, $why, $from)
            continue
        }
        $verdict = Get-AdfaCertificateExpiryVerdict -NotBeforeUtc $record.NotBeforeUtc -NotAfterUtc $record.NotAfterUtc -NowUtc $NowUtc `
            -WarnWithinDays ([int]$Config['WarnWithinDays']) -FailWithinDays ([int]$Config['FailWithinDays']) -ThresholdSource ([string]$Config['ThresholdSource'])
        $ekuText = Get-AdfaCertificateEkuText -Ekus @($record.Ekus) -HasEkuExtension ([bool]$record.HasEkuExtension) -EkuNames $Config['EkuNames']
        $presentedNote = ''
        if ($PresentedThumbprint -ne '') {
            if ([string]$record.Thumbprint -eq $PresentedThumbprint.ToUpperInvariant()) { $presentedNote = ' It is the certificate this DC presented on LDAPS in this run.' }
            else { $presentedNote = ' It is not the certificate this DC presented on LDAPS in this run.' }
        }
        $detail = ("Published in the directory: {0}. Thumbprint {1}. Directory evidence: a CA published this certificate for the DC's computer object, which does not show that the DC still holds or presents it, nor that it is a domain controller certificate (Microsoft's default 'Directory E-mail Replication' template is published to AD DS too; its purposes are in the Ekus column).{2} {3}" -f [string]$verdict.Reason, [string]$record.Thumbprint, $presentedNote, $from)
        $rows += New-AdfaDcCertificateRow -Scope $Scope -Item ("Directory certificate: {0} [{1}]" -f $DomainController, [string]$record.Thumbprint) -Status ([string]$verdict.Status) `
            -Evidence 'Directory userCertificate' -NotRun $notRun -Certificate $record -DaysLeft $verdict.DaysLeft -Ekus $ekuText -Detail $detail
    }
    return @($rows)
}

function Get-AdfaDcCertificates {
    <#
    .SYNOPSIS
        Per domain controller: the certificate it presents on LDAPS (with -IncludeHandshake) and
        the certificates published for it in the directory, each judged on expiry.
    .DESCRIPTION
        Two instruments, labelled in every row (Evidence column):
          LDAPS handshake            Get-AdfaDcTlsCertificateRaw, only when -IncludeHandshake is
                                     given, and only where port 636 answered the shared probe
                                     (Test-AdfaDcPort, so a DC is probed once per port in the
                                     run). What clients are handed. Needs no right on the DC.
          Directory userCertificate  Get-AdfaDcCertificateDirectoryRaw, always. Domain read only.
        The DC's certificate stores are NOT read (PORT-PLAN C5a): that needs remote execution on
        the DC, and Microsoft documents that AD DS looks in the NTDS service store before
        LocalMachine\My, so a read of My alone would not say which certificate is presented.

        DECLARED POPULATION: the domains named in -ScopedDomains. Each ends up in the section as
        the Scope of at least one DC row, or as its own "DC certificates - <domain>" Not Assessed
        row. Every DC target gets exactly one "LDAPS certificate: <dc>" row, and at least one
        directory row. An exception while one DC is handled makes that DC's rows Not Assessed
        and never ends the section.

        -Now is the clock every verdict is judged against, converted to UTC; tests inject it.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [hashtable]$AdParams = @{},
        [int]$PortTimeoutMs = 1200,
        [Parameter(Mandatory)][datetime]$Now,
        [bool]$IncludeHandshake = $false,
        # Domains whose DC enumeration threw: objects with Domain and Error.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        # Why no DC could be enumerated at all, where the caller knows.
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        # The domains this run was scoped to: the declared population of the section.
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $rows = @()
    $nowUtc = $Now.ToUniversalTime()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaDcCertificateRow -Scope ([string]$gap.Domain) -Item ("DC certificates - {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Evidence 'none' -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No certificate of its domain controllers was read.')
    }
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        $rows += New-AdfaDcCertificateRow -Item 'DC certificates' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail ("No domain controllers were enumerated, so no certificate was read.{0} This is not a clean result." -f $why)
        return @($rows)
    }
    $port = [int]$Config['LdapsPort']
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-AdfaDcCertificateRow -Scope $scope -Item 'LDAPS certificate: (unnamed)' -Status $script:Status.NotAssessed -Evidence 'none' `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to or look up and no certificate was read.'
            continue
        }
        $dcRows = @()
        try {
            $answered = $false
            $raw = $null
            $ldapsReach = ''
            if ($IncludeHandshake) {
                $ldapsGate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @($port) -TimeoutMs $PortTimeoutMs
                $ldapsReach = [string]$ldapsGate.Cause
                $answered = [bool]$ldapsGate.Open[$port]
                if ($answered) {
                    $raw = Get-AdfaDcTlsCertificateRaw -ComputerName $dc -Port $port -ConnectTimeoutMs ([int]$Config['ConnectTimeoutMs']) -HandshakeTimeoutMs ([int]$Config['HandshakeTimeoutMs'])
                }
            }
            $dcRows += Get-AdfaDcLdapsFinding -DomainController $dc -Scope $scope -HandshakeRun $IncludeHandshake -PortAnswered $answered -Raw $raw `
                -Config $Config -NowUtc $nowUtc -PortTimeoutMs $PortTimeoutMs -ReachCause $ldapsReach
            $presented = ''
            if ($null -ne $raw -and [bool]$raw.Ok -and $null -ne $raw.Certificate -and [bool]$raw.Certificate.Read) { $presented = [string]$raw.Certificate.Thumbprint }
            $directoryRaw = Get-AdfaDcCertificateDirectoryRaw -HostName $dc -Server $scope -AdParams $AdParams
            $dcRows += @(Get-AdfaDcDirectoryCertificateFinding -DomainController $dc -Scope $scope -Raw $directoryRaw -Config $Config -NowUtc $nowUtc -PresentedThumbprint $presented)
        }
        catch {
            # A defect in this tool, not in the DC. Fail closed for this DC only.
            $why = ("Not assessed: handling the certificates of {0} failed inside this tool, so nothing about this DC is graded; this is a defect in the tool, not a result. Error: {1}" -f $dc, [string]$_.Exception.Message)
            $dcRows = @(
                (New-AdfaDcCertificateRow -Scope $scope -Item ("LDAPS certificate: {0}" -f $dc) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why)
                (New-AdfaDcCertificateRow -Scope $scope -Item ("Directory certificates: {0}" -f $dc) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why)
            )
        }
        $rows += $dcRows
    }
    return @($rows)
}

function Merge-AdfaDcCertificatesConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in DC certificates table, with validation. The
        DcCertificates validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: WarnWithinDays and FailWithinDays (the expiry windows, both tool
        defaults), HandshakeTimeoutMs and ConnectTimeoutMs:

            { "DcCertificates": { "WarnWithinDays": 45, "FailWithinDays": 7 } }

        What it cannot: LdapsPort (636 is where AD DS serves LDAP over TLS; another port, 3269
        for the global catalog among them, would change what the row describes), the EKU names
        and the sources. Every such key is refused as unknown.

        Anything this tool could not use is refused with the reason: an override that is not one
        object, an empty object, an unknown key, a null, a value that is not a JSON number, a
        number of days that is not a whole number from 0 to 3650, a timeout that is not a whole
        number of milliseconds from 100 to 60000. The MERGED table is then checked as a whole: a
        Fail window wider than the Warning window is refused, so a file that names only
        FailWithinDays is refused when that puts it above the built-in Warning window.

        Provenance follows the windows key by key: ThresholdSource is rewritten to name the
        override's source for exactly the windows it supplied. A file that changes only the
        timeouts leaves it untouched.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("DC certificates config override must be a single object with named keys (for example {{ ""WarnWithinDays"": 45 }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) {
        throw 'DC certificates config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $windowKeys = @('WarnWithinDays', 'FailWithinDays')
    $known = @('WarnWithinDays', 'FailWithinDays', 'HandshakeTimeoutMs', 'ConnectTimeoutMs')
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("DC certificates config override names an unknown key '{0}'. Known keys: {1}. The LDAPS port, the EKU names and the sources cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        # Reachable only from an object built in memory with keys that differ by case; a key
        # written twice in a FILE is found in the text by Import-AdfaConfigOverride.
        if ($supplied -contains $name) { throw ("DC certificates config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) {
            throw ("DC certificates config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name)
        }
        # A JSON number only. "30" in quotes is refused rather than parsed: how a string becomes a
        # number depends on the culture of the host, and a threshold must not.
        if ($value -is [array] -or $numericTypes -notcontains $value.GetType()) {
            throw ("DC certificates config override sets '{0}' to a {1}. It must be a JSON number, written without quotes." -f $name, $value.GetType().Name)
        }
        $number = [double]$value
        if ([double]::IsNaN($number) -or [double]::IsInfinity($number)) {
            throw ("DC certificates config override sets '{0}' to a value that is not a finite number." -f $name)
        }
        $shown = $number.ToString('0.####', $inv)
        if ($windowKeys -contains $name) {
            if ($number -ne [math]::Floor($number) -or $number -lt 0 -or $number -gt 3650) {
                throw ("DC certificates config override sets '{0}' to {1}. It must be a whole number of days from 0 to 3650; 0 switches the window off." -f $name, $shown)
            }
        }
        else {
            if ($number -ne [math]::Floor($number) -or $number -lt 100 -or $number -gt 60000) {
                throw ("DC certificates config override sets '{0}' to {1}. It must be a whole number of milliseconds from 100 to 60000." -f $name, $shown)
            }
        }
        $merged[$name] = [int]$number
        $supplied += $name
    }

    # The table as a whole, built-in values included.
    $warn = [int]$merged['WarnWithinDays']
    $fail = [int]$merged['FailWithinDays']
    if ($fail -gt $warn) {
        throw ("DC certificates config: FailWithinDays ({0}) is above WarnWithinDays ({1}) once the override is applied. A certificate would fail at a number of days left at which it does not yet warn; set both." -f $fail, $warn)
    }

    $fromOverride = @($windowKeys | Where-Object { $supplied -contains $_ })
    if ($fromOverride.Count -gt 0) {
        $from = 'an override whose source was not recorded'
        if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
        $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
        $builtIn = @($windowKeys | Where-Object { $supplied -notcontains $_ })
        if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
        $merged['ThresholdSource'] = $text
    }
    return $merged
}

# ---------------------------------------------------------------------------
# RID pool: whether RID pool allocation is enabled, how much of the global RID space has been
# issued, and each DC's current and next RID pool (PORT-PLAN C6)
# ---------------------------------------------------------------------------

function New-AdfaRidPoolRow {
    <#
    .SYNOPSIS
        Pure: one RID Pool row. Every row of the section has the same columns, so a consumer never
        has to test whether a column exists.
    .DESCRIPTION
        The values read - the decoded halves of the large integers, the pool bounds, the next RID,
        the RID master's name and the distinguished names - go in their own columns, never in
        Detail: the consolidated findings choose a recommendation from Detail, and none of these
        columns is read there. Numbers are written in the invariant culture, and a value that was
        not measured is an empty string, never 0.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = '',
        [AllowEmptyString()][string]$Evidence = '',
        [AllowEmptyString()][string]$RidMaster = '',
        [AllowNull()]$Ceiling = $null,
        [AllowEmptyString()][string]$CeilingSource = '',
        [AllowNull()]$Issued = $null,
        [AllowEmptyString()][string]$PercentUsed = '',
        [AllowNull()]$PoolStart = $null,
        [AllowNull()]$PoolEnd = $null,
        [AllowNull()]$NextRid = $null,
        [AllowNull()]$RemainingInPool = $null,
        [AllowNull()]$NextPoolStart = $null,
        [AllowNull()]$NextPoolEnd = $null,
        [AllowEmptyString()][string]$ObjectDn = '',
        [AllowEmptyString()][string]$RawValue = ''
    )
    $row = New-Finding -Scope $Scope -Area 'RidPool' -Item $Item -Status $Status -Detail $Detail
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $asText = { param($Number) if ($null -eq $Number) { return '' } return ([int64]$Number).ToString($inv) }
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    $row | Add-Member -NotePropertyName 'Evidence' -NotePropertyValue $Evidence
    $row | Add-Member -NotePropertyName 'RidMaster' -NotePropertyValue $RidMaster
    $row | Add-Member -NotePropertyName 'Ceiling' -NotePropertyValue (& $asText $Ceiling)
    $row | Add-Member -NotePropertyName 'CeilingSource' -NotePropertyValue $CeilingSource
    $row | Add-Member -NotePropertyName 'Issued' -NotePropertyValue (& $asText $Issued)
    $row | Add-Member -NotePropertyName 'PercentUsed' -NotePropertyValue $PercentUsed
    $row | Add-Member -NotePropertyName 'PoolStart' -NotePropertyValue (& $asText $PoolStart)
    $row | Add-Member -NotePropertyName 'PoolEnd' -NotePropertyValue (& $asText $PoolEnd)
    $row | Add-Member -NotePropertyName 'NextRid' -NotePropertyValue (& $asText $NextRid)
    $row | Add-Member -NotePropertyName 'RemainingInPool' -NotePropertyValue (& $asText $RemainingInPool)
    $row | Add-Member -NotePropertyName 'NextPoolStart' -NotePropertyValue (& $asText $NextPoolStart)
    $row | Add-Member -NotePropertyName 'NextPoolEnd' -NotePropertyValue (& $asText $NextPoolEnd)
    $row | Add-Member -NotePropertyName 'ObjectDn' -NotePropertyValue $ObjectDn
    $row | Add-Member -NotePropertyName 'RawValue' -NotePropertyValue $RawValue
    return $row
}

function ConvertFrom-AdfaLargeInteger {
    <#
    .SYNOPSIS
        Pure: a 64-bit directory value (Interval or LargeInteger syntax) as its two unsigned 32-bit
        halves, Low and High, each an [int64] from 0 to 4294967295.
    .DESCRIPTION
        rIDAvailablePool, rIDPreviousAllocationPool and rIDAllocationPool are Interval values:
        "identical to the LargeInteger syntax, except the high and low values are unsigned
        integers" (https://learn.microsoft.com/windows/win32/adschema/s-interval, read 2026-11-16).
        The ActiveDirectory module hands a 64-bit value over as a signed Int64, so a high half of
        0x80000000 or more arrives as a negative number.

        The split is explicit 32-bit arithmetic that gives the same answer on Windows PowerShell
        5.1 and PowerShell 7: the value is taken as the Int64 with the same 64 bits, the low half
        is that value AND 4294967295, and the high half is the value shifted right by 32 and then
        ANDed with 4294967295, so the sign that the arithmetic shift carries in is masked away.
        No literal 0xFFFFFFFF is written: PowerShell types it as the Int32 -1.

        Accepted: any integer type up to 64 bits, a UInt64 above Int64.MaxValue included (taken by
        its bits), and text that is a whole number in the invariant culture, signed or unsigned.
        Anything else - $null, a fraction, a date, a list, hexadecimal text - is Read = $false with
        the reason, and never an exception.
    .OUTPUTS
        [pscustomobject] Read, Low, High, Raw (the value as text), Error.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Value)
    $out = [pscustomobject]@{ Read = $false; Low = [int64]0; High = [int64]0; Raw = ''; Error = '' }
    if ($null -eq $Value) { $out.Error = 'no value was given'; return $out }
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $bits = [int64]0
    $signedTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64])
    if ($Value -is [uint64]) {
        $bits = [BitConverter]::ToInt64([BitConverter]::GetBytes([uint64]$Value), 0)
        $out.Raw = ([uint64]$Value).ToString($inv)
    }
    elseif ($signedTypes -contains $Value.GetType()) {
        $bits = [int64]$Value
        $out.Raw = $bits.ToString($inv)
    }
    elseif ($Value -is [string]) {
        $text = $Value.Trim()
        $out.Raw = $text
        $signed = [int64]0
        $unsigned = [uint64]0
        if ([int64]::TryParse($text, [System.Globalization.NumberStyles]::AllowLeadingSign, $inv, [ref]$signed)) { $bits = $signed }
        elseif ([uint64]::TryParse($text, [System.Globalization.NumberStyles]::None, $inv, [ref]$unsigned)) { $bits = [BitConverter]::ToInt64([BitConverter]::GetBytes($unsigned), 0) }
        else { $out.Error = ("'{0}' is not a whole number that fits in 64 bits" -f $text); return $out }
    }
    else {
        $out.Raw = [string]$Value
        $out.Error = ("a value of type {0} is not a 64-bit integer" -f $Value.GetType().Name)
        return $out
    }
    $mask = [int64]4294967295
    $out.Low = [int64]($bits -band $mask)
    $out.High = [int64](($bits -shr 32) -band $mask)
    $out.Read = $true
    return $out
}

function Get-AdfaRidSchemaState {
    <#
    .SYNOPSIS
        Pure: whether the forest schema defines msDS-RIDPoolAllocationEnabled - Yes, No or Unknown.
    .DESCRIPTION
        Read from the answer of Get-AdfaLapsSchemaRaw, the same schema read the Laps section makes,
        asked for two names: rIDAvailablePool, which every Active Directory schema defines (Learn
        lists it from Windows 2000 Server) and so works as the control, and the allocation
        attribute. A query that failed, or that answered without the control, is Unknown: the
        absence of a name from such an answer proves nothing.
    .OUTPUTS
        [pscustomobject] InSchema (Yes | No | Unknown), Detail.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$Raw,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $control = [string]$Config['AvailablePoolAttribute']
    $attribute = [string]$Config['AllocationAttribute']
    $out = [pscustomobject]@{ InSchema = 'Unknown'; Detail = '' }
    if ($null -eq $Raw) { $out.Detail = 'The forest schema was not read (the read returned nothing).'; return $out }
    if (-not [bool]$Raw.Ok) {
        $reported = ([string]$Raw.Error).Trim()
        if ($reported -eq '') { $reported = '(no error text was returned)' }
        if (-not [string]::IsNullOrWhiteSpace([string]$Raw.ErrorType)) { $reported = ("{0} (exception type: {1})" -f $reported, ([string]$Raw.ErrorType).Trim()) }
        $out.Detail = ("The forest schema could not be read, so whether it defines {0} is not known. Reported by the schema query - {1}" -f $attribute, $reported)
        return $out
    }
    $names = @($Raw.Names | Where-Object { $null -ne $_ } | ForEach-Object { ([string]$_).Trim() })
    if (@($names | Where-Object { $_ -eq $control }).Count -eq 0) {
        $out.Detail = ("The schema query answered without {0}, which every Active Directory schema defines, so the absence of {1} from that answer proves nothing." -f $control, $attribute)
        return $out
    }
    if (@($names | Where-Object { $_ -eq $attribute }).Count -gt 0) {
        $out.InSchema = 'Yes'
        $out.Detail = ("The forest schema defines {0}." -f $attribute)
    }
    else {
        $out.InSchema = 'No'
        $out.Detail = ("The forest schema does not define {0}; the same query returned {1}, so its answer was complete." -f $attribute, $control)
    }
    return $out
}

function Get-AdfaRidAllocationVerdict {
    <#
    .SYNOPSIS
        Pure: whether RID pool allocation is blocked in a domain, from msDS-RIDPoolAllocationEnabled
        on CN=RID Manager$ (catalogue ADA-RID-001).
    .DESCRIPTION
        From Managing RID Issuance (https://learn.microsoft.com/windows-server/identity/ad-ds/manage/managing-rid-issuance,
        read 2026-11-16): at the RID ceiling the RID master "sets Active Directory attribute
        msDS-RIDPoolAllocationEnabled ... to FALSE", which "prevents further RID block issuance to
        all domain controllers"; an administrator sets it to TRUE to remove the block; and "On the
        next RID allocation performed by the RID master, the attribute will return to its default
        NOT SET value."

            FALSE                                   Fail     Disabled
            TRUE                                    Pass     Enabled
            not set, the schema defines it          Not Assessed  NotSet - an attribute this account
                                                    cannot read is left out the same way, and the
                                                    ACL is not evaluated (PORT-PLAN C6d)
            not set, the schema could not be read   Not Assessed  NotSetUnconfirmed
            not in the schema                       Not Assessed  NotInSchema - Microsoft publishes
                                                    no meaning for an older schema without it
            any other value                         Not Assessed  Unrecognised
            the attribute read failed               Not Assessed  ReadFailed
            CN=RID Manager$ not read                Not Assessed  NotRead

        A value that is present proves the schema defines the attribute, so TRUE and FALSE are
        graded whatever the schema read returned.
    .OUTPUTS
        [pscustomobject] Status, State, Reason.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$Raw,
        [ValidateSet('Yes', 'No', 'Unknown')][string]$InSchema = 'Unknown'
    )
    $name = 'msDS-RIDPoolAllocationEnabled'
    $notInSchema = ("The forest schema does not define {0}. Microsoft documents the RID ceiling that sets it as new in Windows Server 2012 and does not publish what the attribute's absence means (no schema page for it was found on Microsoft Learn), so this is not graded." -f $name)
    if ($null -eq $Raw -or -not [bool]$Raw.Ok) {
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'NotRead'; Reason = ("CN=RID Manager`$ was not read, so {0} was not read." -f $name) }
    }
    if (-not [bool]$Raw.AllocationRead) {
        if ($InSchema -eq 'No') { return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'NotInSchema'; Reason = $notInSchema } }
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'ReadFailed'; Reason = ("{0} could not be read." -f $name) }
    }
    if ([bool]$Raw.AllocationReturned) {
        $value = $Raw.AllocationValue
        if ($value -is [System.Collections.IEnumerable] -and $value -isnot [string]) {
            $items = @($value)
            if ($items.Count -eq 1) { $value = $items[0] }
        }
        $flag = $null
        if ($value -is [bool]) { $flag = [bool]$value }
        elseif ($null -ne $value -and ($value -is [string])) {
            $text = $value.Trim()
            if ($text -eq 'TRUE') { $flag = $true }
            elseif ($text -eq 'FALSE') { $flag = $false }
        }
        if ($null -eq $flag) {
            return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'Unrecognised'; Reason = ("{0} holds a value that is neither TRUE nor FALSE ('{1}'), which Microsoft documents no meaning for, so it is not graded." -f $name, [string]$value) }
        }
        if (-not $flag) {
            return [pscustomobject]@{ Status = $script:Status.Fail; State = 'Disabled'
                Reason = ("{0} is FALSE on CN=RID Manager`$: RID pool allocation is blocked. Microsoft documents that the RID master sets it to FALSE when it allocates the pool that reaches 90 % of the global RID space, writes event 16657, and issues no further RID pool to any domain controller; domain controllers keep using the pools they already hold, and when those run out no account, group or computer can be created." -f $name) }
        }
        return [pscustomobject]@{ Status = $script:Status.Pass; State = 'Enabled'
            Reason = ("{0} is TRUE: allocation is not blocked. Microsoft documents TRUE as the value an administrator sets to remove the block after the RID ceiling was reached, and that the attribute returns to its default NOT SET value at the next RID allocation, after which there is no further ceiling." -f $name) }
    }
    if ($InSchema -eq 'Yes') {
        # Not a Pass. Microsoft, Access Control and Read Operations
        # (https://learn.microsoft.com/windows/win32/ad/access-control-and-read-operations, read
        # 2026-11-16): "a search operation can succeed, but the search results don't include objects
        # or properties to which the caller doesn't have access". An unset attribute and one the
        # account may not read therefore look the same, this tool does not evaluate the object's
        # ACL, and a FALSE value hidden by a changed ACL would otherwise pass (PORT-PLAN C6d).
        return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'NotSet'
            Reason = ("Not returned: {0} was not returned for CN=RID Manager`$, and the forest schema defines it. Microsoft documents NOT SET as the attribute's default value, and only FALSE blocks allocation; but Microsoft also documents that a read can succeed without the properties the caller has no access to, and this tool does not evaluate the object's access control, so 'not set' cannot be told from 'not readable' and this is not graded as a pass. The default security descriptor of the RID-Manager class grants Authenticated Users read access." -f $name) }
    }
    if ($InSchema -eq 'No') { return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'NotInSchema'; Reason = $notInSchema } }
    return [pscustomobject]@{ Status = $script:Status.NotAssessed; State = 'NotSetUnconfirmed'
        Reason = ("{0} was not returned, and the forest schema could not be confirmed to define it, so 'not set' (the default, allocation not blocked) and 'not in the schema' cannot be told apart." -f $name) }
}

function Get-AdfaRidSpaceVerdict {
    <#
    .SYNOPSIS
        Pure: how much of a domain's global RID space has been issued, from the two halves of
        rIDAvailablePool (catalogue ADA-RID-002).
    .DESCRIPTION
        "The upper part defines the number of security principals that can be allocated for each
        domain (0x3FFFFFFF or just over 1 billion). The lower part is the number of RIDs that have
        been allocated in the domain." (Raise the value of available RID pools, read 2026-11-16.)

        The ceiling is the upper part AS READ, never assumed. It is graded only when it is one of
        the sizes in Config.KnownCeilings - 1,073,741,823 (the default 30-bit space) or
        2,147,483,647 (the 31-bit space after the unlock, matched by value: that the attribute holds
        it is an inference, see the config table) - and anything else, 0, or an issued count above
        the ceiling, is Not Assessed with the values quoted and no percentage.

        Integer comparison, no rounding: Fail when issued * 100 >= ceiling * FailAtPercentUsed,
        Warning when issued * 100 >= ceiling * WarnAtPercentUsed, otherwise Pass. Both halves are
        below 2^32, so the products fit an Int64. PercentUsed, the figure shown in the row and its
        column, is truncated to four decimals (never rounded up), so it never shows a point the
        row is graded below.
    .OUTPUTS
        [pscustomobject] Status, State, PercentUsed ('' when not computed), Ceiling, CeilingLabel,
        Reason.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [int64]$Low,
        [int64]$High,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $issuedText = $Low.ToString('N0', $inv)
    $ceilingText = $High.ToString('N0', $inv)
    $out = [pscustomobject]@{ Status = $script:Status.NotAssessed; State = ''; PercentUsed = ''; Ceiling = $High; CeilingLabel = ''; Reason = '' }
    $knownList = (@($Config['KnownCeilings'] | ForEach-Object { ([int64]$_['Value']).ToString('N0', $inv) }) -join ' and ')
    if ($High -le 0) {
        $out.State = 'NoCeiling'
        $out.Reason = ("No ceiling: the upper part of rIDAvailablePool, the size of the global RID space, is {0}, so no share of it can be computed. Lower part (RIDs issued): {1}." -f $ceilingText, $issuedText)
        return $out
    }
    $known = @($Config['KnownCeilings'] | Where-Object { [int64]$_['Value'] -eq $High })
    if ($known.Count -eq 0) {
        $out.State = 'UnknownCeiling'
        $out.Reason = ("Unknown ceiling: the upper part of rIDAvailablePool is {0}, which is neither of the sizes Microsoft documents for the global RID space ({1}), so no percentage is computed against a guessed ceiling. Lower part (RIDs issued): {2}." -f $ceilingText, $knownList, $issuedText)
        return $out
    }
    if ($Low -gt $High) {
        $out.State = 'Inconsistent'
        $out.Reason = ("Inconsistent: the lower part of rIDAvailablePool ({0}, RIDs issued) is above its upper part ({1}, the size of the global RID space), so the value is not judged." -f $issuedText, $ceilingText)
        return $out
    }
    $warn = [int64]$Config['WarnAtPercentUsed']
    $fail = [int64]$Config['FailAtPercentUsed']
    $out.CeilingLabel = [string]$known[0]['Label']
    # Truncated, not rounded, from exact decimal arithmetic: a count graded below a whole-number
    # point must never show that point (rounding 9.99999999 gives '10' on a row graded below 10).
    $exactPercent = ([decimal]$Low * [decimal]100) / [decimal]$High
    $out.PercentUsed = ([decimal]::Truncate($exactPercent * [decimal]10000) / [decimal]10000).ToString('0.####', $inv)
    $scaled = $Low * 100
    if ($scaled -ge ($High * $fail)) {
        $out.Status = $script:Status.Fail
        $out.State = 'PastFail'
        $verdict = ("At or past the Fail point of {0} % used. Microsoft documents that the RID master stops issuing RID pools (event 16657) when it allocates the pool that reaches 90 % of the global RID space, and that once that block is lifted there is no further ceiling before the space runs out." -f $fail)
    }
    elseif ($scaled -ge ($High * $warn)) {
        $out.Status = $script:Status.Warning
        $out.State = 'PastWarning'
        $verdict = ("At or past the Warning point of {0} % used. Microsoft logs event 16658 at the first 10 % of the global RID space used and calls reaching it not expected." -f $warn)
    }
    else {
        $out.Status = $script:Status.Pass
        $out.State = 'Below'
        $verdict = ("Below the Warning point of {0} % used." -f $warn)
    }
    $out.Reason = ("{0} of {1} RIDs issued ({2} % used). {3} The size of the space is the upper part of rIDAvailablePool as read: {4}. Thresholds: Warning at {5} % used, Fail at {6} % used - {7}." -f `
            $issuedText, $ceilingText, $out.PercentUsed, $verdict, [string]$known[0]['Note'], $warn, $fail, [string]$Config['ThresholdSource'])
    return $out
}

function Get-AdfaRidManagerRaw {
    <#
    .SYNOPSIS
        The domain half of C6: the RID master and the two attributes of CN=RID Manager$ of one
        domain. Read-only directory reads. Never throws.
    .DESCRIPTION
        Three reads:
          Get-ADDomain -Identity <domain>   DistinguishedName and RIDMaster. With the caller's AD
                                            parameters unchanged, as the Laps section reads it.
          Get-ADObject -Identity CN=RID Manager$,CN=System,<domain DN> -Properties rIDAvailablePool
          Get-ADObject (the same object) -Properties msDS-RIDPoolAllocationEnabled
        The two Get-ADObject calls carry -Server set to the domain. The allocation attribute is
        read on its own, so that a schema without it - where the module refuses the property list
        - leaves the global space read intact. Nothing here writes: no Set-ADObject, no -Replace,
        and neither msDS-RIDPoolAllocationEnabled nor SidCompatibilityVersion is ever modified.
        An attribute that is not set is not in the answer; that is reported as not returned.
    .OUTPUTS
        [pscustomobject] Ok (CN=RID Manager$ was read), Stage (Domain | RidManager where it
        failed), Error, ErrorType, Server, DomainDn, RidMaster, ObjectDn, AvailablePoolReturned,
        AvailablePool, AllocationRead, AllocationError, AllocationErrorType, AllocationReturned,
        AllocationValue.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{
        Ok = $false; Stage = ''; Error = ''; ErrorType = ''; Server = $DomainName; DomainDn = ''; RidMaster = ''; ObjectDn = ''
        AvailablePoolReturned = $false; AvailablePool = $null
        AllocationRead = $false; AllocationError = ''; AllocationErrorType = ''; AllocationReturned = $false; AllocationValue = $null
    }
    $poolName = [string]$Config['AvailablePoolAttribute']
    $allocationName = [string]$Config['AllocationAttribute']
    try {
        $domainArgs = @{} + $AdParams
        $domainArgs.Identity = $DomainName
        $domainArgs.ErrorAction = 'Stop'
        $domain = Get-ADDomain @domainArgs
        if ($null -ne $domain) {
            $dnProp = $domain.PSObject.Properties['DistinguishedName']
            if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $out.DomainDn = ([string]$dnProp.Value).Trim() }
            $masterProp = $domain.PSObject.Properties['RIDMaster']
            if ($null -ne $masterProp -and $null -ne $masterProp.Value) { $out.RidMaster = ([string]$masterProp.Value).Trim() }
        }
        if ($out.DomainDn -eq '') { throw 'Get-ADDomain returned no DistinguishedName, so CN=RID Manager$ could not be located.' }
    }
    catch {
        $out.Stage = 'Domain'
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        return $out
    }
    $out.ObjectDn = ("{0},{1}" -f [string]$Config['RidManagerRdn'], $out.DomainDn)
    try {
        $poolArgs = @{} + $AdParams
        $poolArgs.Server = $DomainName
        $poolArgs.Identity = $out.ObjectDn
        $poolArgs.Properties = @([string]$Config['AvailablePoolAttribute'])
        $poolArgs.ErrorAction = 'Stop'
        $manager = Get-ADObject @poolArgs
        if ($null -eq $manager) { throw ("Get-ADObject returned nothing for {0}." -f $out.ObjectDn) }
        $poolProp = $manager.PSObject.Properties[$poolName]
        if ($null -ne $poolProp -and $null -ne $poolProp.Value) {
            $out.AvailablePoolReturned = $true
            $out.AvailablePool = $poolProp.Value
        }
        $out.Ok = $true
    }
    catch {
        $out.Stage = 'RidManager'
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        return $out
    }
    try {
        $allocationArgs = @{} + $AdParams
        $allocationArgs.Server = $DomainName
        $allocationArgs.Identity = $out.ObjectDn
        $allocationArgs.Properties = @([string]$Config['AllocationAttribute'])
        $allocationArgs.ErrorAction = 'Stop'
        $answer = Get-ADObject @allocationArgs
        if ($null -eq $answer) { throw ("Get-ADObject returned nothing for {0}." -f $out.ObjectDn) }
        $allocationProp = $answer.PSObject.Properties[$allocationName]
        if ($null -ne $allocationProp -and $null -ne $allocationProp.Value) {
            $out.AllocationReturned = $true
            $out.AllocationValue = $allocationProp.Value
        }
        $out.AllocationRead = $true
    }
    catch {
        $out.AllocationError = [string]$_.Exception.Message
        $out.AllocationErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Get-AdfaRidDomainFinding {
    <#
    .SYNOPSIS
        Pure: the two rows of one domain - "RID pool allocation: <domain>" (ADA-RID-001) and
        "Global RID space: <domain>" (ADA-RID-002) - from what Get-AdfaRidManagerRaw returned.
    .DESCRIPTION
        A failed read of the domain or of CN=RID Manager$ makes both rows Not Assessed, worded by
        Get-AdfaLapsReadFailureLead (Unreachable / Access denied / Timed out / Read failed). After
        that the two halves are independent: a failed allocation read leaves the space graded, and
        a pool that was not returned or not an integer leaves the allocation graded. The RID
        master's name, the object's DN and the raw values go in their own columns.
    .OUTPUTS
        [pscustomobject[]] Two rows: allocation, then global space.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [AllowNull()]$Raw,
        [AllowNull()]$Schema,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $allocationItem = ("RID pool allocation: {0}" -f $Domain)
    $spaceItem = ("Global RID space: {0}" -f $Domain)
    $notRun = 'Not read: SidCompatibilityVersion, which holds whether the 31st bit of the global RID space is unlocked and which Microsoft says cannot be read with ADSIEdit, LDP or other tools; the Directory-Services-SAM events 16653 to 16658 in the System log of each domain controller; and dcdiag /test:RidManager, which this section does not run (the DC Diagnostics section does).'
    $allocationEvidence = ("Directory: {0} on CN=RID Manager`$" -f [string]$Config['AllocationAttribute'])
    $spaceEvidence = ("Directory: {0} on CN=RID Manager`$" -f [string]$Config['AvailablePoolAttribute'])
    if ($null -eq $Raw) {
        $defect = 'Not assessed: the directory read returned nothing. This is a defect in the tool, not a result.'
        return @(
            (New-AdfaRidPoolRow -Scope $Domain -Item $allocationItem -Status $script:Status.NotAssessed -Detail $defect -NotRun $notRun -Evidence 'none')
            (New-AdfaRidPoolRow -Scope $Domain -Item $spaceItem -Status $script:Status.NotAssessed -Detail $defect -NotRun $notRun -Evidence 'none')
        )
    }
    $ridMaster = [string]$Raw.RidMaster
    $objectDn = [string]$Raw.ObjectDn
    if (-not [bool]$Raw.Ok) {
        $what = ("CN=RID Manager`$,CN=System of {0}" -f $Domain)
        if ([string]$Raw.Stage -eq 'Domain') { $what = ("the domain object of {0} (Get-ADDomain), which locates CN=RID Manager`$," -f $Domain) }
        $lead = Get-AdfaLapsReadFailureLead -Message ([string]$Raw.Error) -TypeName ([string]$Raw.ErrorType) -What $what
        $detail = ("{0} This is not a clean result." -f $lead)
        return @(
            (New-AdfaRidPoolRow -Scope $Domain -Item $allocationItem -Status $script:Status.NotAssessed -Detail $detail -NotRun $notRun -Evidence 'none' -RidMaster $ridMaster -ObjectDn $objectDn)
            (New-AdfaRidPoolRow -Scope $Domain -Item $spaceItem -Status $script:Status.NotAssessed -Detail $detail -NotRun $notRun -Evidence 'none' -RidMaster $ridMaster -ObjectDn $objectDn)
        )
    }

    # Allocation (ADA-RID-001).
    $inSchema = 'Unknown'
    $schemaDetail = 'The forest schema was not read.'
    if ($null -ne $Schema) {
        $inSchema = [string]$Schema.InSchema
        $schemaDetail = [string]$Schema.Detail
    }
    $allocation = Get-AdfaRidAllocationVerdict -Raw $Raw -InSchema $inSchema
    $allocationDetail = [string]$allocation.Reason
    if ([string]$allocation.State -eq 'ReadFailed') {
        $lead = Get-AdfaLapsReadFailureLead -Message ([string]$Raw.AllocationError) -TypeName ([string]$Raw.AllocationErrorType) -What ("the {0} attribute of CN=RID Manager`$ of {1}" -f [string]$Config['AllocationAttribute'], $Domain)
        $allocationDetail = ("{0} {1}" -f $lead, $schemaDetail)
    }
    elseif (@('NotSetUnconfirmed', 'NotInSchema') -contains [string]$allocation.State) {
        $allocationDetail = ("{0} {1}" -f $allocationDetail, $schemaDetail)
    }
    $allocationRaw = ''
    if ([bool]$Raw.AllocationReturned -and $null -ne $Raw.AllocationValue) { $allocationRaw = [string]$Raw.AllocationValue }
    $rows = @(New-AdfaRidPoolRow -Scope $Domain -Item $allocationItem -Status ([string]$allocation.Status) -Detail $allocationDetail -NotRun $notRun `
            -Evidence $allocationEvidence -RidMaster $ridMaster -ObjectDn $objectDn -RawValue $allocationRaw)

    # Global space (ADA-RID-002).
    if (-not [bool]$Raw.AvailablePoolReturned) {
        $rows += New-AdfaRidPoolRow -Scope $Domain -Item $spaceItem -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $spaceEvidence -RidMaster $ridMaster -ObjectDn $objectDn `
            -Detail ("Not returned: {0} was not returned for CN=RID Manager`$ of {1}. An unset attribute and one this account cannot read look the same from here, so the global RID space was not judged." -f [string]$Config['AvailablePoolAttribute'], $Domain)
        return @($rows)
    }
    $decoded = ConvertFrom-AdfaLargeInteger -Value $Raw.AvailablePool
    if (-not [bool]$decoded.Read) {
        $rows += New-AdfaRidPoolRow -Scope $Domain -Item $spaceItem -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $spaceEvidence -RidMaster $ridMaster -ObjectDn $objectDn `
            -RawValue ([string]$decoded.Raw) -Detail ("Unreadable value: {0} of {1} could not be read as a 64-bit integer ({2}), so the global RID space was not judged." -f [string]$Config['AvailablePoolAttribute'], $Domain, [string]$decoded.Error)
        return @($rows)
    }
    $space = Get-AdfaRidSpaceVerdict -Low ([int64]$decoded.Low) -High ([int64]$decoded.High) -Config $Config
    $rows += New-AdfaRidPoolRow -Scope $Domain -Item $spaceItem -Status ([string]$space.Status) -Detail ([string]$space.Reason) -NotRun $notRun -Evidence $spaceEvidence `
        -RidMaster $ridMaster -Ceiling ([int64]$decoded.High) -CeilingSource ([string]$space.CeilingLabel) -Issued ([int64]$decoded.Low) -PercentUsed ([string]$space.PercentUsed) `
        -ObjectDn $objectDn -RawValue ([string]$decoded.Raw)
    return @($rows)
}

function ConvertTo-AdfaRidSetRecord {
    <#
    .SYNOPSIS
        Pure: a RID Set object as a small record - its DN and the four RID attributes, each the raw
        value or $null when it was not returned.
    .OUTPUTS
        [pscustomobject] Dn, FromSearch, PreviousAllocationPool, AllocationPool, NextRid, UsedPool,
        Returned (the attribute names that came back with a value), or $null for no object.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$Object,
        [Parameter(Mandatory)][hashtable]$Config,
        [bool]$FromSearch = $false
    )
    if ($null -eq $Object) { return $null }
    $dn = ''
    $dnProp = $Object.PSObject.Properties['DistinguishedName']
    if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $dn = ([string]$dnProp.Value).Trim() }
    # Config.RidSetAttributes is in this order: the current pool, the prefetched pool, the next
    # RID, the used pools. The record's fields follow it.
    $fields = @('PreviousAllocationPool', 'AllocationPool', 'NextRid', 'UsedPool')
    $names = @($Config['RidSetAttributes'] | ForEach-Object { [string]$_ })
    $record = [pscustomobject]@{ Dn = $dn; FromSearch = $FromSearch; PreviousAllocationPool = $null; AllocationPool = $null; NextRid = $null; UsedPool = $null; Returned = @() }
    $returned = @()
    for ($i = 0; $i -lt $fields.Count -and $i -lt $names.Count; $i++) {
        $prop = $Object.PSObject.Properties[$names[$i]]
        if ($null -eq $prop -or $null -eq $prop.Value) { continue }
        $value = $prop.Value
        if ($value -is [System.Collections.IEnumerable] -and $value -isnot [string]) {
            $items = @($value)
            if ($items.Count -eq 0) { continue }
            if ($items.Count -eq 1) { $value = $items[0] }
        }
        $record.($fields[$i]) = $value
        $returned += $names[$i]
    }
    $record.Returned = @($returned)
    return $record
}

function Get-AdfaDcRidSetRaw {
    <#
    .SYNOPSIS
        The per-DC half of C6: one domain controller's RID Set object, reached from its computer
        object. Read-only directory reads. Never throws.
    .DESCRIPTION
        1. Get-ADComputer -LDAPFilter (&(objectClass=computer)(dNSHostName=<host>)) -Properties
           rIDSetReferences, against -Server: the DC's domain where the caller knows it, otherwise
           the DC itself. No object, or more than one, ends the read; the caller says which.
        2. rIDSetReferences is multi-valued in the schema. More than one value ends the read: the
           caller reports them all and picks none. One value is read with Get-ADObject -Identity
           and the four RID attributes.
        3. A SECOND INSTRUMENT before "absent" is ever said: a one-level search for objectClass
           rIDSet under the computer object, run when rIDSetReferences has no value, or when the
           reference could not be read with an error that is not a refusal, an unreachable server
           or a time-out (the module's exception for an object that does not exist is not
           published, so every other error is treated as "may not exist"). A refused or
           unreachable read says nothing about existence, and the search is not run.
    .OUTPUTS
        [pscustomobject] Ok (the computer query succeeded), Stage, Error, ErrorType, Server,
        ObjectCount, ComputerDn, References, ReferenceRead (NotTried | Ok | Failed),
        ReferenceError, ReferenceErrorType, SearchRun, SearchOk, SearchError, SearchErrorType,
        SearchCount, RidSet (ConvertTo-AdfaRidSetRecord, or $null).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$HostName,
        [AllowEmptyString()][string]$Server = '',
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $target = $Server
    if ([string]::IsNullOrWhiteSpace($target)) { $target = $HostName }
    $out = [pscustomobject]@{
        Ok = $false; Stage = ''; Error = ''; ErrorType = ''; Server = $target; ObjectCount = 0; ComputerDn = ''; References = @()
        ReferenceRead = 'NotTried'; ReferenceError = ''; ReferenceErrorType = ''
        SearchRun = $false; SearchOk = $false; SearchError = ''; SearchErrorType = ''; SearchCount = 0; RidSet = $null
    }
    $setProperties = @($Config['RidSetAttributes'] | ForEach-Object { [string]$_ })
    $referenceName = [string]$Config['ReferenceAttribute']
    $objects = @()
    try {
        $computerArgs = @{} + $AdParams
        $computerArgs.Server = $target
        $computerArgs.LDAPFilter = ('(&(objectClass=computer)(dNSHostName={0}))' -f (ConvertTo-AdfaLdapFilterValue -Value $HostName))
        $computerArgs.Properties = @([string]$Config['ReferenceAttribute'])
        $computerArgs.ErrorAction = 'Stop'
        $objects = @(Get-ADComputer @computerArgs | Where-Object { $null -ne $_ })
    }
    catch {
        $out.Stage = 'Computer'
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        return $out
    }
    $out.Ok = $true
    $out.ObjectCount = $objects.Count
    if ($objects.Count -ne 1) { return $out }
    $computer = $objects[0]
    $dnProp = $computer.PSObject.Properties['DistinguishedName']
    if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $out.ComputerDn = ([string]$dnProp.Value).Trim() }
    $references = @()
    $referenceProp = $computer.PSObject.Properties[$referenceName]
    if ($null -ne $referenceProp -and $null -ne $referenceProp.Value) {
        if ($referenceProp.Value -is [string]) { $references = @($referenceProp.Value) }
        else { $references = @($referenceProp.Value | Where-Object { $null -ne $_ -and -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim() }) }
    }
    $out.References = @($references)
    if ($references.Count -gt 1) { return $out }

    $searchNeeded = $true
    if ($references.Count -eq 1) {
        try {
            $setArgs = @{} + $AdParams
            $setArgs.Server = $target
            $setArgs.Identity = [string]$references[0]
            $setArgs.Properties = $setProperties
            $setArgs.ErrorAction = 'Stop'
            $set = Get-ADObject @setArgs
            if ($null -eq $set) { throw ("Get-ADObject returned nothing for {0}." -f [string]$references[0]) }
            $out.RidSet = ConvertTo-AdfaRidSetRecord -Object $set -Config $Config
            $out.ReferenceRead = 'Ok'
            $searchNeeded = $false
        }
        catch {
            $out.ReferenceRead = 'Failed'
            $out.ReferenceError = [string]$_.Exception.Message
            $out.ReferenceErrorType = [string]$_.Exception.GetType().FullName
            if ((Get-AdfaDirectoryReadErrorClass -Message $out.ReferenceError -TypeName $out.ReferenceErrorType) -ne 'Error') { $searchNeeded = $false }
        }
    }
    if (-not $searchNeeded) { return $out }
    $out.SearchRun = $true
    if ($out.ComputerDn -eq '') {
        $out.SearchError = 'The computer object came back without a DistinguishedName, so there was nothing to search under.'
        return $out
    }
    try {
        $searchArgs = @{} + $AdParams
        $searchArgs.Server = $target
        $searchArgs.SearchBase = $out.ComputerDn
        $searchArgs.SearchScope = 'OneLevel'
        $searchArgs.LDAPFilter = ('(objectClass={0})' -f [string]$Config['RidSetClass'])
        $searchArgs.Properties = $setProperties
        $searchArgs.ErrorAction = 'Stop'
        $found = @(Get-ADObject @searchArgs | Where-Object { $null -ne $_ })
        $out.SearchOk = $true
        $out.SearchCount = $found.Count
        if ($found.Count -eq 1) { $out.RidSet = ConvertTo-AdfaRidSetRecord -Object $found[0] -Config $Config -FromSearch $true }
    }
    catch {
        $out.SearchError = [string]$_.Exception.Message
        $out.SearchErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Get-AdfaDcRidPoolFinding {
    <#
    .SYNOPSIS
        Pure: the one "RID pool: <dc>" row of a domain controller (catalogue ADA-INV-004), from what
        Get-AdfaDcRidSetRaw returned.
    .DESCRIPTION
        INVENTORY: Info when the current pool and the next RID were read and are consistent, with
        the pool bounds, the next RID, the RIDs remaining in the pool and the prefetched pool in
        their own columns. No threshold is applied, because Microsoft publishes none for a DC's own
        pool. Everything else is Not Assessed, each with its own lead:
          Unreachable / Access denied / Timed out / Read failed   a read that threw
          Not found / Ambiguous                                   0 or more than 1 computer
                                                                  objects, or RID Set objects
          Multiple references                                    rIDSetReferences holds more than
                                                                  one value; none is chosen
          RID Set object absent                                   the reference is empty or does
                                                                  not resolve AND the one-level
                                                                  search found none - a known DC
                                                                  defect (RID pool leak, KB 2618669)
                                                                  except on a read-only DC, for
                                                                  which Learn publishes nothing
          RID Set empty / Unreadable value / Inconsistent         the values themselves
        Microsoft documents the halves of rIDPreviousAllocationPool (start low, end high); that
        rIDAllocationPool has the same layout is an inference, and "remaining" (end - next + 1) is
        this tool's derivation. Both are said in the row.
    .OUTPUTS
        [pscustomobject] One row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [AllowEmptyString()][string]$Scope = '',
        [AllowNull()]$Raw,
        [bool]$IsReadOnly = $false,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $item = ("RID pool: {0}" -f $DomainController)
    $notRun = 'Not read: the RID Block Size registry value of this DC and the Directory-Services-SAM events in its System log. rIDUsedPool is read but not interpreted: Microsoft does not describe its halves.'
    $evidence = ("Directory: {0} and the RID Set object" -f [string]$Config['ReferenceAttribute'])
    if ($null -eq $Raw) {
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence 'none' `
                -Detail 'Not assessed: the directory read returned nothing. This is a defect in the tool, not a result.')
    }
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $server = [string]$Raw.Server
    $from = ("Read from {0}." -f $server)
    if ([string]::IsNullOrWhiteSpace($Scope)) { $from = ("Read from {0}, the DC itself, because this DC came from an enumeration that does not say which domain it belongs to." -f $server) }
    if (-not [bool]$Raw.Ok) {
        $lead = Get-AdfaLapsReadFailureLead -Message ([string]$Raw.Error) -TypeName ([string]$Raw.ErrorType) -What ("the computer object of {0}" -f $DomainController)
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -Detail ("{0} {1}" -f $lead, $from))
    }
    $count = [int]$Raw.ObjectCount
    if ($count -eq 0) {
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Not found: no computer object with dNSHostName {0} was returned, so its RID Set was not read. {1}" -f $DomainController, $from))
    }
    if ($count -gt 1) {
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                -Detail ("Ambiguous: {0} computer objects carry dNSHostName {1}, and which of them is the DC cannot be told, so no RID Set was read. {2}" -f $count, $DomainController, $from))
    }
    $computerDn = [string]$Raw.ComputerDn
    $references = @($Raw.References | Where-Object { $null -ne $_ -and [string]$_ -ne '' })
    if ($references.Count -gt 1) {
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn ($references -join '; ') `
                -Detail ("Multiple references: rIDSetReferences of {0} holds {1} values. Microsoft documents one RID Set per domain controller, so none of them was chosen and no pool is reported; the values are in the ObjectDn column. {2}" -f $DomainController, $references.Count, $from))
    }
    $referenceText = ("rIDSetReferences of {0} has no value visible to this account" -f $DomainController)
    if ($references.Count -eq 1) {
        $referenceText = ("rIDSetReferences of {0} names {1}" -f $DomainController, [string]$references[0])
        if ([string]$Raw.ReferenceRead -eq 'Failed') {
            $class = Get-AdfaDirectoryReadErrorClass -Message ([string]$Raw.ReferenceError) -TypeName ([string]$Raw.ReferenceErrorType)
            if ($class -ne 'Error') {
                $lead = Get-AdfaLapsReadFailureLead -Message ([string]$Raw.ReferenceError) -TypeName ([string]$Raw.ReferenceErrorType) -What ("the RID Set object {0} named by rIDSetReferences of {1}" -f [string]$references[0], $DomainController)
                return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn ([string]$references[0]) -Detail ("{0} {1}" -f $lead, $from))
            }
            $referenceText = ("{0}, which could not be read - {1}" -f $referenceText, ([string]$Raw.ReferenceError).Trim())
        }
    }
    if ([bool]$Raw.SearchRun -and -not [bool]$Raw.SearchOk) {
        $lead = Get-AdfaLapsReadFailureLead -Message ([string]$Raw.SearchError) -TypeName ([string]$Raw.SearchErrorType) -What ("the one-level search for a RID Set object under the computer object of {0}" -f $DomainController)
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn $computerDn `
                -Detail ("{0} That search was the second instrument, after {1}; with it unread, whether this DC has a RID Set is not concluded. {2}" -f $lead, $referenceText, $from))
    }
    $set = $Raw.RidSet
    if ($null -eq $set) {
        if (-not [bool]$Raw.SearchRun) {
            return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence `
                    -Detail ("Not assessed: no RID Set was read for {0}, for a reason this tool did not classify. This is a defect in the tool, not a result. {1}" -f $DomainController, $from))
        }
        if ([int]$Raw.SearchCount -gt 1) {
            return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn $computerDn `
                    -Detail ("Ambiguous: {0}, and a one-level search under its computer object found {1} RID Set objects. Microsoft documents one per domain controller, so none was chosen. {2}" -f $referenceText, [int]$Raw.SearchCount, $from))
        }
        $meaning = ' Microsoft documents one RID Set per domain controller, and names a missing rIDSetReferences as the cause of a known RID pool leak (fixed for Windows Server 2008 R2 by KB 2618669).'
        if ($IsReadOnly) { $meaning = ' This DC is read-only. The Microsoft pages read for this check do not say whether a read-only domain controller has a RID Set, so this is not called a defect.' }
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn $computerDn `
                -Detail ("RID Set object absent: {0}, and a one-level search under its computer object found no {1} object.{2} A RID Set this account cannot read would also look absent; the default security descriptor of the RID-Set class grants Authenticated Users read access. {3}" -f $referenceText, [string]$Config['RidSetClass'], $meaning, $from))
    }

    $setDn = [string]$set.Dn
    $names = @($Config['RidSetAttributes'] | ForEach-Object { [string]$_ })
    $missing = @()
    if ($null -eq $set.PreviousAllocationPool) { $missing += $names[0] }
    if ($null -eq $set.NextRid) { $missing += $names[2] }
    if ($missing.Count -gt 0) {
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn $setDn `
                -Detail ("RID Set empty: {0} not returned for {1}. Microsoft lists the four RID attributes as mandatory on the RID-Set class; an unset attribute and one this account cannot read look the same from here, so no pool is reported. {2}" -f ($missing -join ' and '), $setDn, $from))
    }
    $current = ConvertFrom-AdfaLargeInteger -Value $set.PreviousAllocationPool
    $next = ConvertFrom-AdfaLargeInteger -Value $set.NextRid
    # rIDNextRID is a 4-byte value: an Int32 above 0x7FFFFFFF arrives negative, and its low half
    # is the RID. A wider value with a non-zero high half is not a 4-byte value.
    $nextFits = ([bool]$next.Read -and ([int64]$next.High -eq 0 -or $set.NextRid -is [int32]))
    if (-not [bool]$current.Read -or -not $nextFits) {
        $why = [string]$current.Error
        if ([bool]$current.Read) { $why = ("rIDNextRID '{0}' is not a 32-bit integer" -f [string]$next.Raw) }
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn $setDn -RawValue ([string]$current.Raw) `
                -Detail ("Unreadable value: the RID Set {0} could not be read as numbers ({1}), so no pool is reported. {2}" -f $setDn, $why, $from))
    }
    $start = [int64]$current.Low
    $end = [int64]$current.High
    $nextRid = [int64]$next.Low
    if ($start -eq 0 -and $end -eq 0) {
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn $setDn -RawValue ([string]$current.Raw) `
                -Detail ("RID Set empty: rIDPreviousAllocationPool of {0} is 0, so it holds no current pool. {1}" -f $setDn, $from))
    }
    if ($end -lt $start) {
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn $setDn -RawValue ([string]$current.Raw) `
                -Detail ("Inconsistent: the current pool in rIDPreviousAllocationPool of {0} ends ({1}) before it starts ({2}), read as Microsoft documents (start in the lower four bytes, end in the upper), so no pool is reported. {3}" -f $setDn, $end.ToString($inv), $start.ToString($inv), $from))
    }
    if ($nextRid -lt $start -or $nextRid -gt $end) {
        return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.NotAssessed -NotRun $notRun -Evidence $evidence -ObjectDn $setDn -RawValue ([string]$current.Raw) `
                -Detail ("Inconsistent: rIDNextRID of {0} ({1}) is outside the current pool {2}-{3}. Microsoft describes it as the next free RID in the current pool, so what remains is not computed. {4}" -f $setDn, $nextRid.ToString($inv), $start.ToString($inv), $end.ToString($inv), $from))
    }
    $remaining = $end - $nextRid + 1
    $size = $end - $start + 1
    $nextPoolStart = $null
    $nextPoolEnd = $null
    $nextPoolText = 'rIDAllocationPool, the prefetched next pool, was not returned.'
    if ($null -ne $set.AllocationPool) {
        $prefetched = ConvertFrom-AdfaLargeInteger -Value $set.AllocationPool
        if ([bool]$prefetched.Read) {
            $nextPoolStart = [int64]$prefetched.Low
            $nextPoolEnd = [int64]$prefetched.High
            $nextPoolText = ("Next pool (rIDAllocationPool, prefetched): {0}-{1}; its halves are read as for the current pool, which is an inference - Microsoft states the layout for rIDPreviousAllocationPool only." -f $nextPoolStart.ToString($inv), $nextPoolEnd.ToString($inv))
        }
        else { $nextPoolText = ("rIDAllocationPool, the prefetched next pool, could not be read as a number ({0})." -f [string]$prefetched.Error) }
    }
    $foundNote = ''
    if ([bool]$set.FromSearch) {
        $foundNote = (" The RID Set was found by a one-level search under the computer object, not through rIDSetReferences: {0}." -f $referenceText)
    }
    $detail = ("Current pool (rIDPreviousAllocationPool): {0}-{1}, {2} RIDs. Next RID (rIDNextRID): {3}. Remaining in this pool: {4} - a tool derivation (end - next + 1); Microsoft does not state whether the end of a pool is inclusive. {5}{6} Inventory only: Microsoft publishes no threshold for a domain controller's own pool. {7}" -f `
            $start.ToString($inv), $end.ToString($inv), $size.ToString($inv), $nextRid.ToString($inv), $remaining.ToString($inv), $nextPoolText, $foundNote, $from)
    return (New-AdfaRidPoolRow -Scope $Scope -Item $item -Status $script:Status.Info -NotRun $notRun -Evidence $evidence -Detail $detail -ObjectDn $setDn -RawValue ([string]$current.Raw) `
            -PoolStart $start -PoolEnd $end -NextRid $nextRid -RemainingInPool $remaining -NextPoolStart $nextPoolStart -NextPoolEnd $nextPoolEnd)
}

function Get-AdfaRidPool {
    <#
    .SYNOPSIS
        RID pool health: per scoped domain whether RID pool allocation is enabled and how much of
        the global RID space has been issued, and per domain controller its current and next RID
        pool. Directory reads only.
    .DESCRIPTION
        Three seams, each read-only and none of which throws:
          Get-AdfaLapsSchemaRaw    once, for whether the schema defines msDS-RIDPoolAllocationEnabled
          Get-AdfaRidManagerRaw    once per scoped domain: Get-ADDomain and CN=RID Manager$
          Get-AdfaDcRidSetRaw      once per DC: its computer object and its RID Set
        No dcdiag test is run here - the DC Diagnostics section runs /test:RidManager, which
        Microsoft describes as checks only (PORT-PLAN C6e) - and SidCompatibilityVersion is not read (Microsoft: it cannot be read with ADSIEdit, LDP
        or other tools).

        DECLARED POPULATIONS. Domains: the names in -ScopedDomains; each gets exactly two rows,
        "RID pool allocation: <domain>" and "Global RID space: <domain>", or, with none scoped,
        one "RID pool (no domain scoped)" row. DCs: each scoped domain ends up in the section as
        the Scope of at least one "RID pool: <dc>" row or as its own "RID pool - <domain>" Not
        Assessed row, and every DC target gets exactly one row. An exception while one domain or
        one DC is handled makes its rows Not Assessed and never ends the section.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [hashtable]$AdParams = @{},
        # Domains whose DC enumeration threw: objects with Domain and Error.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        # Why no DC could be enumerated at all, where the caller knows.
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        # The domains this run was scoped to: the declared population of the section.
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $rows = @()
    $domains = New-Object System.Collections.ArrayList
    foreach ($name in @($ScopedDomains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        if (@($domains | Where-Object { $_ -eq $name.Trim() }).Count -eq 0) { [void]$domains.Add($name.Trim()) }
    }
    if ($domains.Count -eq 0) {
        $rows += New-AdfaRidPoolRow -Item 'RID pool (no domain scoped)' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail 'No domain was scoped for this run, so no CN=RID Manager$ was read. This is not a clean result.'
    }
    else {
        $schemaRaw = Get-AdfaLapsSchemaRaw -AdParams $AdParams -AttributeNames @([string]$Config['AvailablePoolAttribute'], [string]$Config['AllocationAttribute'])
        $schema = Get-AdfaRidSchemaState -Raw $schemaRaw -Config $Config
        foreach ($domain in $domains) {
            try {
                $raw = Get-AdfaRidManagerRaw -DomainName $domain -AdParams $AdParams -Config $Config
                $rows += @(Get-AdfaRidDomainFinding -Domain $domain -Raw $raw -Schema $schema -Config $Config)
            }
            catch {
                # A defect in this tool, not in the directory. Fail closed for this domain only.
                $why = ("Not assessed: handling the RID Manager of {0} failed inside this tool, so nothing about this domain is graded; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$_.Exception.Message)
                $rows += New-AdfaRidPoolRow -Scope $domain -Item ("RID pool allocation: {0}" -f $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why
                $rows += New-AdfaRidPoolRow -Scope $domain -Item ("Global RID space: {0}" -f $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why
            }
        }
    }

    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains @($domains))) {
        $rows += New-AdfaRidPoolRow -Scope ([string]$gap.Domain) -Item ("RID pool - {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Evidence 'none' -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No RID Set of its domain controllers was read.')
    }
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        $rows += New-AdfaRidPoolRow -Item 'RID pools' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail ("No domain controllers were enumerated, so no domain controller's RID pool was read.{0} This is not a clean result." -f $why)
        return @($rows)
    }
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        $readOnly = $false
        if ($target -isnot [string]) {
            $readOnlyProp = $target.PSObject.Properties['IsReadOnly']
            if ($null -ne $readOnlyProp -and $readOnlyProp.Value -is [bool]) { $readOnly = [bool]$readOnlyProp.Value }
        }
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-AdfaRidPoolRow -Scope $scope -Item 'RID pool: (unnamed)' -Status $script:Status.NotAssessed -Evidence 'none' `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to look up and no RID Set was read.'
            continue
        }
        try {
            $raw = Get-AdfaDcRidSetRaw -HostName $dc -Server $scope -AdParams $AdParams -Config $Config
            $rows += Get-AdfaDcRidPoolFinding -DomainController $dc -Scope $scope -Raw $raw -IsReadOnly $readOnly -Config $Config
        }
        catch {
            $rows += New-AdfaRidPoolRow -Scope $scope -Item ("RID pool: {0}" -f $dc) -Status $script:Status.NotAssessed -Evidence 'none' `
                -Detail ("Not assessed: handling the RID Set of {0} failed inside this tool, so nothing about this DC is reported; this is a defect in the tool, not a result. Error: {1}" -f $dc, [string]$_.Exception.Message)
        }
    }
    return @($rows)
}

function Merge-AdfaRidPoolConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in RID pool table, with validation. The RidPool
        validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: WarnAtPercentUsed and FailAtPercentUsed, the shares of the global
        RID space issued at which a domain is a Warning and a Fail:

            { "RidPool": { "WarnAtPercentUsed": 10, "FailAtPercentUsed": 90 } }

        What it cannot: the known ceilings, the location of CN=RID Manager$, the attribute and
        class names, and the sources. Every such key is refused as unknown, so a file cannot make
        the tool read another attribute or grade against a ceiling it did not read.

        Refused with the reason: an override that is not one object, an empty object, an unknown
        key, a null, a value that is not a JSON number, a number that is not a whole number from 1
        to 99. The MERGED table is then checked as a whole: FailAtPercentUsed must be above
        WarnAtPercentUsed, so a file that names only one of them is refused when that crosses the
        built-in other.

        Provenance follows the keys: ThresholdSource is rewritten to name the override's source for
        exactly the keys it supplied.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("RID pool config override must be a single object with named keys (for example {{ ""WarnAtPercentUsed"": 10 }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) {
        throw 'RID pool config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $known = @('WarnAtPercentUsed', 'FailAtPercentUsed')
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("RID pool config override names an unknown key '{0}'. Known keys: {1}. The ceilings, the location of CN=RID Manager`$, the attribute names and the sources cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        if ($supplied -contains $name) { throw ("RID pool config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) {
            throw ("RID pool config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name)
        }
        # A JSON number only: how a quoted string becomes a number depends on the host's culture.
        if ($value -is [array] -or $numericTypes -notcontains $value.GetType()) {
            throw ("RID pool config override sets '{0}' to a {1}. It must be a JSON number, written without quotes." -f $name, $value.GetType().Name)
        }
        $number = [double]$value
        if ([double]::IsNaN($number) -or [double]::IsInfinity($number)) {
            throw ("RID pool config override sets '{0}' to a value that is not a finite number." -f $name)
        }
        if ($number -ne [math]::Floor($number) -or $number -lt 1 -or $number -gt 99) {
            throw ("RID pool config override sets '{0}' to {1}. It must be a whole number from 1 to 99 (percent of the global RID space issued)." -f $name, $number.ToString('0.####', $inv))
        }
        $merged[$name] = [int]$number
        $supplied += $name
    }

    # The table as a whole, built-in values included.
    $warn = [int]$merged['WarnAtPercentUsed']
    $fail = [int]$merged['FailAtPercentUsed']
    if ($fail -le $warn) {
        throw ("RID pool config: FailAtPercentUsed ({0}) must be above WarnAtPercentUsed ({1}) once the override is applied; otherwise the Warning could never be reported. Set both." -f $fail, $warn)
    }

    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
    $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
    if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
    $merged['ThresholdSource'] = $text
    return $merged
}

function Merge-AdfaDcDiagConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in dcdiag table, with validation. The DcDiag
        validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: TestTimeoutSeconds, the time-out of one dcdiag invocation (a whole
        number from 5 to 600, the range of -ExternalToolTimeoutSeconds), and Retries, the attempts
        per invocation (1 to 10, the range of -Retries). Microsoft publishes neither: both are tool
        defaults.

            { "DcDiag": { "TestTimeoutSeconds": 180 } }

        What it cannot: the test lists (per DC, per domain, per forest, per site, not added), the
        opt-in list, the output markers, the evidence patterns and the DNS summary table (its
        columns, cell values, grades and header threshold; PORT-PLAN C12). Every such key is refused
        as unknown, so a file can never make the tool run a dcdiag test that changes state, read a
        verdict from a line Microsoft does not print, or turn a DNS test group's result into a Pass.

        Refused with the reason: an override that is not one object, an empty object, an unknown
        key, a null, a value that is not a JSON number, a number outside its range or not whole.

        Provenance follows the keys: ThresholdSource is rewritten to name the override's source for
        exactly the keys it supplied; TimeoutSource, which a timed-out cell quotes, says the value
        came from the -ConfigOverridePath file without naming the path.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("dcdiag config override must be a single object with named keys (for example {{ ""TestTimeoutSeconds"": 180 }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) {
        throw 'dcdiag config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $ranges = [ordered]@{
        TestTimeoutSeconds = @(5, 600, 'seconds for one dcdiag invocation')
        Retries            = @(1, 10, 'attempts per dcdiag invocation')
    }
    $known = @($ranges.Keys)
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("dcdiag config override names an unknown key '{0}'. Known keys: {1}. The test lists, the opt-in list, the output markers, the evidence patterns and the DNS summary table cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        if ($supplied -contains $name) { throw ("dcdiag config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) {
            throw ("dcdiag config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name)
        }
        # A JSON number only: how a quoted string becomes a number depends on the host's culture.
        if ($value -is [array] -or $numericTypes -notcontains $value.GetType()) {
            throw ("dcdiag config override sets '{0}' to a {1}. It must be a JSON number, written without quotes." -f $name, $value.GetType().Name)
        }
        $number = [double]$value
        if ([double]::IsNaN($number) -or [double]::IsInfinity($number)) {
            throw ("dcdiag config override sets '{0}' to a value that is not a finite number." -f $name)
        }
        $low = [int]$ranges[$name][0]
        $high = [int]$ranges[$name][1]
        if ($number -ne [math]::Floor($number) -or $number -lt $low -or $number -gt $high) {
            throw ("dcdiag config override sets '{0}' to {1}. It must be a whole number from {2} to {3} ({4})." -f $name, $number.ToString('0.####', $inv), $low, $high, [string]$ranges[$name][2])
        }
        $merged[$name] = [int]$number
        $supplied += $name
    }

    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
    $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
    if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
    $merged['ThresholdSource'] = $text
    if ($supplied -contains 'TestTimeoutSeconds') { $merged['TimeoutSource'] = 'set in the -ConfigOverridePath file; not a Microsoft value' }
    return $merged
}

# ---------------------------------------------------------------------------
# SID history: principals with sIDHistory, historic SIDs of the principal's own domain, privileged
# historic SIDs, and the domains they came from (PORT-PLAN C7). Rows of the SecurityPosture section.
# ---------------------------------------------------------------------------

function New-AdfaSidHistoryRow {
    <#
    .SYNOPSIS
        Pure: one SID history row. Every row has the same columns, so a consumer never has to test
        whether a column exists.
    .DESCRIPTION
        Account names, historic SIDs, the domain's SID and the source domains go in their own
        columns, never in Detail: the consolidated findings choose a recommendation from Detail,
        and none of these columns is read there. A count that was not measured is an empty string,
        never 0.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$NotRun = '',
        [AllowEmptyString()][string]$Evidence = '',
        [AllowEmptyString()][string]$DomainSid = '',
        [AllowNull()]$PrincipalCount = $null,
        [AllowNull()]$ValueCount = $null,
        [AllowNull()]$UserCount = $null,
        [AllowNull()]$ComputerCount = $null,
        [AllowNull()]$GroupCount = $null,
        [AllowNull()]$OtherCount = $null,
        [AllowNull()]$EnabledCount = $null,
        [AllowNull()]$DisabledCount = $null,
        [AllowNull()]$UnparsedCount = $null,
        [AllowNull()]$Listed = $null,
        [AllowNull()]$NotListed = $null,
        [AllowEmptyString()][string]$Principals = '',
        [AllowEmptyString()][string]$HistoricSids = '',
        [AllowEmptyString()][string]$SourceDomains = ''
    )
    $row = New-Finding -Scope $Scope -Area 'Security' -Item $Item -Status $Status -Detail $Detail
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $asText = { param($Number) if ($null -eq $Number) { return '' } return ([int64]$Number).ToString($inv) }
    $row | Add-Member -NotePropertyName 'NotRun' -NotePropertyValue $NotRun
    $row | Add-Member -NotePropertyName 'Evidence' -NotePropertyValue $Evidence
    $row | Add-Member -NotePropertyName 'DomainSid' -NotePropertyValue $DomainSid
    $row | Add-Member -NotePropertyName 'PrincipalCount' -NotePropertyValue (& $asText $PrincipalCount)
    $row | Add-Member -NotePropertyName 'ValueCount' -NotePropertyValue (& $asText $ValueCount)
    $row | Add-Member -NotePropertyName 'UserCount' -NotePropertyValue (& $asText $UserCount)
    $row | Add-Member -NotePropertyName 'ComputerCount' -NotePropertyValue (& $asText $ComputerCount)
    $row | Add-Member -NotePropertyName 'GroupCount' -NotePropertyValue (& $asText $GroupCount)
    $row | Add-Member -NotePropertyName 'OtherCount' -NotePropertyValue (& $asText $OtherCount)
    $row | Add-Member -NotePropertyName 'EnabledCount' -NotePropertyValue (& $asText $EnabledCount)
    $row | Add-Member -NotePropertyName 'DisabledCount' -NotePropertyValue (& $asText $DisabledCount)
    $row | Add-Member -NotePropertyName 'UnparsedCount' -NotePropertyValue (& $asText $UnparsedCount)
    $row | Add-Member -NotePropertyName 'Listed' -NotePropertyValue (& $asText $Listed)
    $row | Add-Member -NotePropertyName 'NotListed' -NotePropertyValue (& $asText $NotListed)
    $row | Add-Member -NotePropertyName 'Principals' -NotePropertyValue $Principals
    $row | Add-Member -NotePropertyName 'HistoricSids' -NotePropertyValue $HistoricSids
    $row | Add-Member -NotePropertyName 'SourceDomains' -NotePropertyValue $SourceDomains
    return $row
}

function Get-AdfaSidHistoryCapText {
    <#
    .SYNOPSIS
        Pure: the sentence that says how many names a row lists and how many it leaves out.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([int]$Listed, [int]$NotListed, [int]$Cap, [Parameter(Mandatory)][string]$Column)
    return ("{0} listed in the {1} column, {2} not listed (NameListCap {3}, a tool default, not a Microsoft value)." -f $Listed, $Column, $NotListed, $Cap)
}

function ConvertFrom-AdfaSidValue {
    <#
    .SYNOPSIS
        Pure: one SID - as bytes, as text, or as an object that carries its text in Value, as
        System.Security.Principal.SecurityIdentifier does - in its parts. Never throws.
    .DESCRIPTION
        sIDHistory, objectSid and securityIdentifier have the String(Sid) syntax, an octet string
        whose .NET type is System.Byte[] (https://learn.microsoft.com/windows/win32/adschema/s-string-sid,
        read 2026-11-16). What the ActiveDirectory module hands over for them is not published, so
        bytes, text and SecurityIdentifier-like objects are all read.

        BYTES. The layout is checked first, the same way on every platform (MS-DTYP 2.4.2.2):
        revision 1, at most 15 sub-authorities, and a length of exactly 8 + 4 x count bytes. The
        6-byte identifier authority is read big-endian and each sub-authority as an unsigned
        32-bit little-endian number, by arithmetic on [uint64] - never through [int] - so a RID of
        4294967295 survives on Windows PowerShell 5.1 and PowerShell 7 alike. Then, unless
        -NoPlatform is given, .NET SecurityIdentifier(byte[], 0) reads the same bytes: a value the
        platform refuses (an ArgumentException anywhere in the chain) is not read, a platform that
        cannot run it (the type missing, or not supported off Windows) leaves the fallback's
        reading, and a platform that reads it differently from the fallback makes the value NOT
        read, so the two parsers are cross-checked on every Windows run. The byte order of a
        sub-authority is left to the protocol by MS-DTYP; little-endian is measured by that
        cross-check, not read on Learn.

        -PlatformReader replaces the platform's reading, for tests only: a scriptblock given the
        bytes that returns the SID text or throws. No real value reaches the refusal or the
        disagreement branch - the layout check runs first, and SecurityIdentifier agrees with the
        fallback on every value that passes it - so without this seam neither branch could be
        tested. Every caller in this script leaves it out.

        TEXT. S-1-<authority>-<sub>... with up to 15 sub-authorities, the authority at most 2^48 - 1
        and each sub-authority an unsigned 32-bit number, in the invariant culture.

        DomainPart is every part but the last sub-authority (the domain identifier, Learn), Rid the
        last sub-authority as [uint32]. IsAccountDomain is true for S-1-5-21-x-y-z-RID only: the
        shape of a SID issued by a domain to an account or group.
    .OUTPUTS
        [pscustomobject] Ok, Text, Authority, SubAuthorities, DomainPart, Rid, IsAccountDomain,
        Parser (Text | Platform | Fallback), Error.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Value, [switch]$NoPlatform, [scriptblock]$PlatformReader = $null)
    $out = [pscustomobject]@{ Ok = $false; Text = ''; Authority = $null; SubAuthorities = @(); DomainPart = ''; Rid = $null; IsAccountDomain = $false; Parser = ''; Error = '' }
    $reader = $PlatformReader
    if ($null -eq $reader) { $reader = { param($SidBytes) [string]([System.Security.Principal.SecurityIdentifier]::new($SidBytes, 0)).Value } }
    if ($null -eq $Value) { $out.Error = 'no value was given'; return $out }
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $authority = [uint64]0
    $subs = New-Object 'System.Collections.Generic.List[uint32]'
    $parser = ''
    if ($Value -is [byte[]]) {
        $bytes = [byte[]]$Value
        if ($bytes.Length -lt 8) { $out.Error = ("{0} bytes is shorter than the 8-byte header of a SID" -f $bytes.Length); return $out }
        if ([int]$bytes[0] -ne 1) { $out.Error = ("the revision byte is {0}, and a SID's revision must be 1" -f [int]$bytes[0]); return $out }
        $count = [int]$bytes[1]
        if ($count -gt 15) { $out.Error = ("the value says it has {0} sub-authorities, and a SID has at most 15" -f $count); return $out }
        $expected = 8 + (4 * $count)
        if ($bytes.Length -ne $expected) { $out.Error = ("the value is {0} bytes long, and a SID with {1} sub-authorities is {2}" -f $bytes.Length, $count, $expected); return $out }
        for ($i = 2; $i -le 7; $i++) { $authority = ($authority * [uint64]256) + [uint64]$bytes[$i] }
        for ($k = 0; $k -lt $count; $k++) {
            $o = 8 + (4 * $k)
            $number = [uint64]$bytes[$o] + ([uint64]$bytes[$o + 1] * [uint64]256) + ([uint64]$bytes[$o + 2] * [uint64]65536) + ([uint64]$bytes[$o + 3] * [uint64]16777216)
            $subs.Add([uint32]$number)
        }
        $parser = 'Fallback'
        if (-not $NoPlatform) {
            $fallbackText = ('S-1-{0}{1}' -f $authority.ToString($inv), (@($subs | ForEach-Object { '-' + $_.ToString($inv) }) -join ''))
            try {
                $platformText = [string](& $reader $bytes)
                if ($platformText -cne $fallbackText) {
                    $out.Error = ("the platform reads this value as '{0}' and its byte layout gives '{1}', so it is not read" -f $platformText, $fallbackText)
                    return $out
                }
                $parser = 'Platform'
            }
            catch {
                $e = $_.Exception
                $refused = $false
                while ($null -ne $e) {
                    if ($e -is [System.ArgumentException]) { $refused = $true; break }
                    $e = $e.InnerException
                }
                if ($refused) { $out.Error = ("the platform refused it as a SID: {0}" -f [string]$_.Exception.Message); return $out }
                # The type is missing, or not supported on this platform: the fallback's reading stands.
            }
        }
    }
    else {
        $text = $null
        if ($Value -is [string]) { $text = [string]$Value }
        else {
            $valueProp = $Value.PSObject.Properties['Value']
            if ($null -ne $valueProp -and $valueProp.Value -is [string]) { $text = [string]$valueProp.Value }
        }
        if ($null -eq $text) { $out.Error = ("a value of type {0} is not a SID" -f $Value.GetType().FullName); return $out }
        $text = $text.Trim()
        if ($text -notmatch '^[Ss]-1-(\d{1,15})((?:-\d{1,10}){0,15})$') { $out.Error = ("'{0}' is not a SID in its text form" -f $text); return $out }
        $authorityText = $Matches[1]
        $subText = $Matches[2]
        if (-not [uint64]::TryParse($authorityText, [System.Globalization.NumberStyles]::None, $inv, [ref]$authority) -or $authority -gt [uint64]281474976710655) {
            $out.Error = ("the identifier authority of '{0}' does not fit in 48 bits" -f $text); return $out
        }
        foreach ($part in @($subText.Split([char]'-') | Where-Object { $_ -ne '' })) {
            $number = [uint32]0
            if (-not [uint32]::TryParse($part, [System.Globalization.NumberStyles]::None, $inv, [ref]$number)) {
                $out.Error = ("the sub-authority {0} of '{1}' is not an unsigned 32-bit number" -f $part, $text); return $out
            }
            $subs.Add($number)
        }
        $parser = 'Text'
    }
    $out.Authority = $authority
    $out.SubAuthorities = $subs.ToArray()
    $authorityString = $authority.ToString($inv)
    $out.Text = ('S-1-{0}{1}' -f $authorityString, (@($subs | ForEach-Object { '-' + $_.ToString($inv) }) -join ''))
    if ($subs.Count -ge 1) {
        $out.Rid = [uint32]$subs[$subs.Count - 1]
        $domainSubs = @()
        for ($i = 0; $i -lt ($subs.Count - 1); $i++) { $domainSubs += ('-' + $subs[$i].ToString($inv)) }
        $out.DomainPart = ('S-1-{0}{1}' -f $authorityString, ($domainSubs -join ''))
    }
    $out.IsAccountDomain = ($authority -eq [uint64]5 -and $subs.Count -eq 5 -and $subs[0] -eq [uint32]21)
    $out.Parser = $parser
    $out.Ok = $true
    return $out
}

function Get-AdfaSidValueList {
    <#
    .SYNOPSIS
        Pure: the values of a multi-valued SID attribute, one pipeline object per value.
    .DESCRIPTION
        A single byte array is ONE value and is written as one object: PowerShell would otherwise
        unroll it into its bytes. A string is one value. Any other collection - an array, an
        ArrayList, the module's own property value collection - gives each of its elements. $null
        gives nothing.
    .OUTPUTS
        [object] one per value.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return }
    if ($Value -is [byte[]] -or $Value -is [string]) { , $Value; return }
    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [System.Collections.IDictionary]) {
        foreach ($element in $Value) { if ($null -ne $element) { , $element } }
        return
    }
    , $Value
}

function Get-AdfaSidHistoryRefusedProperty {
    <#
    .SYNOPSIS
        Pure: the names in a property list that this row must never send - a blank, or a wildcard,
        which would ask the directory for every attribute of every principal.
    .OUTPUTS
        [string[]]
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param([AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$PropertyNames = @())
    $refused = @()
    foreach ($name in @($PropertyNames)) {
        if ([string]::IsNullOrWhiteSpace($name)) { $refused += '(blank)'; continue }
        if ($name -match '[*?]') { $refused += $name }
    }
    return @($refused)
}

function ConvertTo-AdfaSidHistoryRecord {
    <#
    .SYNOPSIS
        Pure: one directory object with sIDHistory as the small record the verdicts read.
    .DESCRIPTION
        Every value is read through PSObject.Properties, so an attribute the object does not carry
        is $null and never an error under StrictMode, and none of them passes through a function's
        return - which would unroll a byte array into its bytes. Enabled is read from
        userAccountControl (ACCOUNTDISABLE, Config.AccountDisableFlag) for users and computers;
        for a group, or where userAccountControl was not returned, it is $null.
    .OUTPUTS
        [pscustomobject] Dn, Sam, Name, Class, Enabled, ObjectSid, History.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]$Object,
        [Parameter(Mandatory)][hashtable]$Config
    )
    # Each value straight from its property, never through a function's return.
    $values = @{}
    foreach ($attribute in @('distinguishedName', 'sAMAccountName', 'Name', 'objectClass', 'userAccountControl')) {
        $values[$attribute] = $null
        $p = $Object.PSObject.Properties[$attribute]
        if ($null -ne $p) { $values[$attribute] = $p.Value }
    }
    $dn = [string]$values['distinguishedName']
    $sam = [string]$values['sAMAccountName']
    $name = $sam
    if ([string]::IsNullOrWhiteSpace($name)) { $name = [string]$values['Name'] }
    if ([string]::IsNullOrWhiteSpace($name)) { $name = $dn }
    if ([string]::IsNullOrWhiteSpace($name)) { $name = '(unnamed)' }
    # objectClass may come back as the most specific class or as the whole chain; the last value is
    # the most specific either way.
    $class = ''
    $classes = @(Get-AdfaSidValueList -Value $values['objectClass'] | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
    if ($classes.Count -gt 0) { $class = $classes[$classes.Count - 1] }
    $enabled = $null
    $isAccount = (@(@($Config['UserClasses']) + @($Config['ComputerClasses']) | Where-Object { $_ -eq $class }).Count -gt 0)
    $uacRaw = $values['userAccountControl']
    if ($isAccount -and $null -ne $uacRaw) {
        $uac = [int64]0
        if ([int64]::TryParse(([string]$uacRaw).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$uac)) {
            $enabled = (($uac -band [int64]$Config['AccountDisableFlag']) -eq 0)
        }
    }
    $sidProp = $Object.PSObject.Properties['objectSid']
    $objectSid = $null
    if ($null -ne $sidProp) { $objectSid = $sidProp.Value }
    $historyProp = $Object.PSObject.Properties['sIDHistory']
    $history = @()
    if ($null -ne $historyProp) { $history = @(Get-AdfaSidValueList -Value $historyProp.Value) }
    return [pscustomobject]@{ Dn = $dn; Sam = $sam; Name = $name; Class = $class; Enabled = $enabled; ObjectSid = $objectSid; History = $history }
}

function Get-AdfaSidHistoryRaw {
    <#
    .SYNOPSIS
        The directory seam of C7: one domain's SID, its principals with sIDHistory, and its
        trusted domain objects. Read-only. Never throws.
    .DESCRIPTION
        Three reads:
          Get-ADDomain -Identity <domain>   its DistinguishedName and DomainSID, with the caller's AD
                                            parameters unchanged, as the Laps and RidPool sections
                                            read it
          Get-ADObject -LDAPFilter (sIDHistory=*) -Server <domain>, asking for
                                            Config.ObjectProperties only
          Get-ADObject -LDAPFilter (objectClass=trustedDomain) -SearchBase CN=System,<domain DN>
                                            -Server <domain>, asking for Config.TrustProperties only
        The principal query relies on the paging the ActiveDirectory module does by itself (default
        256 objects per page, all results: https://learn.microsoft.com/powershell/module/activedirectory/get-adobject,
        read 2026-11-16); no page size and no result limit is set, as nowhere else in this script.
        Each object is reduced to a small record as it arrives.

        The three are independent: a domain that could not be read leaves the principals (only
        the same-domain row then needs its SID), and a trust read that failed leaves both.

        A property list that is empty or holds a blank or a wildcard is refused before any call:
        Refused = $true and nothing is asked. Nothing here writes: no Set-ADUser, no Set-ADObject,
        no -Remove, and sIDHistory is never modified.
    .OUTPUTS
        [pscustomobject] Ok (the principal query succeeded), Refused, Error, ErrorType, Server,
        DomainDn, DomainSid (text, '' when not read), DomainSidError, Records, TrustOk, TrustError,
        TrustErrorType, Trusts (Partner, FlatName, Sid).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{
        Ok = $false; Refused = $false; Error = ''; ErrorType = ''; Server = $DomainName; DomainDn = ''; DomainSid = ''; DomainSidError = ''
        Records = @(); TrustOk = $false; TrustError = ''; TrustErrorType = ''; Trusts = @()
    }
    $objectProperties = @(@($Config['ObjectProperties']) | ForEach-Object { [string]$_ })
    $trustProperties = @(@($Config['TrustProperties']) | ForEach-Object { [string]$_ })
    $refused = @(Get-AdfaSidHistoryRefusedProperty -PropertyNames @($objectProperties + $trustProperties))
    if ($objectProperties.Count -eq 0 -or $trustProperties.Count -eq 0 -or $refused.Count -gt 0) {
        $out.Refused = $true
        $out.Error = ("the property list is empty or holds a blank or a wildcard ({0}), so nothing was asked of the directory." -f ($refused -join ', '))
        return $out
    }

    # The domain: its DN, for the trusts, and its SID, for the same-domain comparison.
    try {
        $domainArgs = @{} + $AdParams
        $domainArgs.Identity = $DomainName
        $domainArgs.ErrorAction = 'Stop'
        $domain = Get-ADDomain @domainArgs
        if ($null -ne $domain) {
            $dnProp = $domain.PSObject.Properties['DistinguishedName']
            if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $out.DomainDn = ([string]$dnProp.Value).Trim() }
            $sidProp = $domain.PSObject.Properties['DomainSID']
            if ($null -ne $sidProp -and $null -ne $sidProp.Value) {
                $parsed = ConvertFrom-AdfaSidValue -Value $sidProp.Value
                if ($parsed.Ok) { $out.DomainSid = $parsed.Text }
                else { $out.DomainSidError = ("the DomainSID that Get-ADDomain returned for {0} could not be read as a SID: {1}" -f $DomainName, $parsed.Error) }
            }
            else { $out.DomainSidError = ("Get-ADDomain returned no DomainSID for {0}." -f $DomainName) }
        }
        else { $out.DomainSidError = ("Get-ADDomain returned nothing for {0}." -f $DomainName) }
    }
    catch { $out.DomainSidError = ("Get-ADDomain for {0}: {1}" -f $DomainName, [string]$_.Exception.Message) }

    # The principals with sIDHistory.
    try {
        $objectArgs = @{} + $AdParams
        $objectArgs.Server = $DomainName
        $objectArgs.LDAPFilter = [string]$Config['SearchFilter']
        $objectArgs.Properties = @($objectProperties)
        $objectArgs.ErrorAction = 'Stop'
        $records = New-Object System.Collections.ArrayList
        Get-ADObject @objectArgs | ForEach-Object {
            if ($null -ne $_) { [void]$records.Add((ConvertTo-AdfaSidHistoryRecord -Object $_ -Config $Config)) }
        }
        $out.Records = $records.ToArray()
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }

    # The trusted domain objects, for the source domains.
    if ($out.DomainDn -eq '') {
        $out.TrustError = ("the distinguished name of {0} was not read, so its trusted domain objects were not looked up" -f $DomainName)
    }
    else {
        try {
            $trustArgs = @{} + $AdParams
            $trustArgs.Server = $DomainName
            $trustArgs.LDAPFilter = [string]$Config['TrustFilter']
            $trustArgs.SearchBase = ("{0},{1}" -f [string]$Config['TrustContainerRdn'], $out.DomainDn)
            $trustArgs.Properties = @($trustProperties)
            $trustArgs.ErrorAction = 'Stop'
            $trusts = New-Object System.Collections.ArrayList
            Get-ADObject @trustArgs | ForEach-Object {
                if ($null -ne $_) {
                    $partnerProp = $_.PSObject.Properties['trustPartner']
                    $flatProp = $_.PSObject.Properties['flatName']
                    $tdoSidProp = $_.PSObject.Properties['securityIdentifier']
                    $partner = ''
                    if ($null -ne $partnerProp -and $null -ne $partnerProp.Value) { $partner = ([string]$partnerProp.Value).Trim() }
                    $flat = ''
                    if ($null -ne $flatProp -and $null -ne $flatProp.Value) { $flat = ([string]$flatProp.Value).Trim() }
                    $tdoSid = $null
                    if ($null -ne $tdoSidProp) { $tdoSid = $tdoSidProp.Value }
                    [void]$trusts.Add([pscustomobject]@{ Partner = $partner; FlatName = $flat; Sid = $tdoSid })
                }
            }
            $out.Trusts = $trusts.ToArray()
            $out.TrustOk = $true
        }
        catch {
            $out.TrustError = [string]$_.Exception.Message
            $out.TrustErrorType = [string]$_.Exception.GetType().FullName
        }
    }
    return $out
}

function Get-AdfaSidHistoryForestMap {
    <#
    .SYNOPSIS
        The forest seam of C7: the SID of every domain of the forest, to name the domain a historic
        SID came from. Read-only. Never throws.
    .DESCRIPTION
        Get-ADDomain -Identity <domain> for each name given, with the caller's AD parameters
        unchanged. A domain that could not be read is kept in Failures with the reason; it makes
        the sources row partial and never fails a domain.
    .OUTPUTS
        [pscustomobject] Map (domain SID text -> domain name), Failures ("<domain>: <reason>").
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$Domains = @(),
        [hashtable]$AdParams = @{}
    )
    $map = @{}
    $failures = New-Object System.Collections.ArrayList
    $seen = @()
    foreach ($name in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { ([string]$_).Trim() })) {
        if ($seen -contains $name) { continue }
        $seen += $name
        try {
            $domainArgs = @{} + $AdParams
            $domainArgs.Identity = $name
            $domainArgs.ErrorAction = 'Stop'
            $domain = Get-ADDomain @domainArgs
            $sidProp = $null
            if ($null -ne $domain) { $sidProp = $domain.PSObject.Properties['DomainSID'] }
            if ($null -eq $sidProp -or $null -eq $sidProp.Value) { [void]$failures.Add(("{0}: Get-ADDomain returned no DomainSID" -f $name)); continue }
            $parsed = ConvertFrom-AdfaSidValue -Value $sidProp.Value
            if (-not $parsed.Ok) { [void]$failures.Add(("{0}: its DomainSID could not be read as a SID ({1})" -f $name, $parsed.Error)); continue }
            $map[$parsed.Text] = $name
        }
        catch { [void]$failures.Add(("{0}: {1}" -f $name, [string]$_.Exception.Message)) }
    }
    return [pscustomobject]@{ Map = $map; Failures = $failures.ToArray() }
}

function Get-AdfaSidHistoryClassification {
    <#
    .SYNOPSIS
        Pure: every historic SID value of a domain's principals, parsed and classified.
    .DESCRIPTION
        For each value: whether it was parsed; SameDomain (its domain part equals the domain's own
        SID); PrivilegedName (the name of the privileged RID - on an account-domain SID only - or of
        the privileged fixed SID, or '') and Privileged, the label Detail carries ("<name> (RID n)"
        or "<name> (well-known SID)", never the SID text); and Source, the label of its domain part:
        "<name>, this forest", "<name>, trust partner", "builtin or well-known" (S-1-5-32-x, and
        SIDs with no domain identifier such as S-1-5-9), "not an account-domain SID", or
        "unresolved" - which says only that it matched neither, never what the domain is.
        NoValue counts the principals that came back with no sIDHistory value at all.
    .OUTPUTS
        [pscustomobject] OwnSid ('' when not known), Values (Record, Parsed, SameDomain, Privileged,
        PrivilegedName, SourceKey, Source), Unparsed, NoValue.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()]$Records = @(),
        [AllowEmptyString()][string]$DomainSid = '',
        [AllowNull()]$ForestMap = $null,
        [AllowNull()][AllowEmptyCollection()]$Trusts = @(),
        [Parameter(Mandatory)][hashtable]$Config
    )
    $own = ''
    if (-not [string]::IsNullOrWhiteSpace($DomainSid)) {
        $ownParsed = ConvertFrom-AdfaSidValue -Value $DomainSid
        if ($ownParsed.Ok) { $own = $ownParsed.Text }
    }
    $forest = @{}
    if ($null -ne $ForestMap) {
        $mapProp = $ForestMap.PSObject.Properties['Map']
        if ($null -ne $mapProp -and $mapProp.Value -is [System.Collections.IDictionary]) {
            foreach ($k in @($mapProp.Value.Keys)) {
                $p = ConvertFrom-AdfaSidValue -Value ([string]$k)
                if ($p.Ok) { $forest[$p.Text] = [string]$mapProp.Value[$k] }
            }
        }
    }
    $trustMap = @{}
    foreach ($t in @($Trusts | Where-Object { $null -ne $_ })) {
        $p = ConvertFrom-AdfaSidValue -Value $t.Sid
        if (-not $p.Ok) { continue }
        $label = [string]$t.Partner
        if ([string]::IsNullOrWhiteSpace($label)) { $label = [string]$t.FlatName }
        if ([string]::IsNullOrWhiteSpace($label)) { $label = '(unnamed trust)' }
        if (-not $trustMap.ContainsKey($p.Text)) { $trustMap[$p.Text] = $label }
    }
    $privRids = @{}
    foreach ($e in @($Config['PrivilegedDomainRids'])) { $privRids[([uint32]$e['Rid']).ToString([System.Globalization.CultureInfo]::InvariantCulture)] = [string]$e['Name'] }
    $privSids = @{}
    foreach ($e in @($Config['PrivilegedSids'])) { $privSids[([string]$e['Sid']).ToUpperInvariant()] = [string]$e['Name'] }

    $values = New-Object System.Collections.ArrayList
    $unparsed = 0
    $noValue = 0
    foreach ($r in @($Records | Where-Object { $null -ne $_ })) {
        $recordValues = @(Get-AdfaSidValueList -Value $r.History)
        # Returned by (sIDHistory=*) and yet no value came back on it: not measured, never clean.
        if ($recordValues.Count -eq 0) { $noValue++ }
        foreach ($v in $recordValues) {
            $p = ConvertFrom-AdfaSidValue -Value $v
            $entry = [pscustomobject]@{ Record = $r; Parsed = $p; SameDomain = $false; Privileged = ''; PrivilegedName = ''; SourceKey = ''; Source = '' }
            if (-not $p.Ok) { $unparsed++; [void]$values.Add($entry); continue }
            $entry.SameDomain = ($own -ne '' -and $p.DomainPart -eq $own)
            $ridKey = ''
            if ($null -ne $p.Rid) { $ridKey = ([uint32]$p.Rid).ToString([System.Globalization.CultureInfo]::InvariantCulture) }
            # Privileged is the label Detail carries, with no SID text in it; the SID itself goes
            # only to the HistoricSids column, with PrivilegedName.
            if ($p.IsAccountDomain -and $privRids.ContainsKey($ridKey)) { $entry.PrivilegedName = $privRids[$ridKey]; $entry.Privileged = ("{0} (RID {1})" -f $privRids[$ridKey], $ridKey) }
            elseif ($privSids.ContainsKey($p.Text)) { $entry.PrivilegedName = $privSids[$p.Text]; $entry.Privileged = ("{0} (well-known SID)" -f $privSids[$p.Text]) }
            $key = $p.DomainPart
            if ($key -eq '') { $key = $p.Text }
            $entry.SourceKey = $key
            $subs = @($p.SubAuthorities)
            if ($forest.ContainsKey($key)) { $entry.Source = ("{0}, this forest" -f $forest[$key]) }
            elseif ($trustMap.ContainsKey($key)) { $entry.Source = ("{0}, trust partner" -f $trustMap[$key]) }
            elseif ($p.IsAccountDomain) { $entry.Source = 'unresolved' }
            elseif ($p.Authority -eq [uint64]5 -and ($subs.Count -le 1 -or $subs[0] -eq [uint32]32)) { $entry.Source = 'builtin or well-known' }
            else { $entry.Source = 'not an account-domain SID' }
            [void]$values.Add($entry)
        }
    }
    return [pscustomobject]@{ OwnSid = $own; Values = $values.ToArray(); Unparsed = $unparsed; NoValue = $noValue }
}

function Get-AdfaSidHistoryHolderText {
    <#
    .SYNOPSIS
        Pure: the Principals and HistoricSids columns for a set of classified values, the number of
        principals they belong to, and how many were listed under the cap.
    .OUTPUTS
        [pscustomobject] Count, Listed, NotListed, Principals, HistoricSids.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][AllowEmptyCollection()]$Values = @(), [int]$Cap = 0, [switch]$WithPrivilegedName)
    $holders = New-Object System.Collections.ArrayList
    $byHolder = @{}
    $nameOf = @{}
    foreach ($v in @($Values | Where-Object { $null -ne $_ })) {
        # The key only groups; it is never split. The DN's length in front makes it unambiguous,
        # since a DN may hold an unescaped '|' (RFC 4514). The name is kept on its own.
        $dn = [string]$v.Record.Dn
        $key = ("{0}:{1}|{2}" -f $dn.Length, $dn, [string]$v.Record.Name)
        if (-not $byHolder.ContainsKey($key)) { $byHolder[$key] = New-Object System.Collections.ArrayList; [void]$holders.Add($key); $nameOf[$key] = [string]$v.Record.Name }
        $text = [string]$v.Parsed.Text
        if ($WithPrivilegedName -and [string]$v.PrivilegedName -ne '') { $text = ("{0} ({1})" -f $text, [string]$v.PrivilegedName) }
        [void]$byHolder[$key].Add($text)
    }
    $listed = [math]::Min($Cap, $holders.Count)
    $names = @()
    $sids = @()
    for ($i = 0; $i -lt $listed; $i++) {
        $name = [string]$nameOf[$holders[$i]]
        $names += $name
        $sids += ("{0}={1}" -f $name, (@($byHolder[$holders[$i]]) -join ','))
    }
    return [pscustomobject]@{ Count = $holders.Count; Listed = $listed; NotListed = ($holders.Count - $listed); Principals = ($names -join '; '); HistoricSids = ($sids -join '; ') }
}

function Get-AdfaSidHistoryCountVerdict {
    <#
    .SYNOPSIS
        Pure: row 1, "SID history: <domain>" - how many principals carry sIDHistory, by class.
    .DESCRIPTION
        Called only for a query that succeeded (the domain finding handles a failed one).
          none returned        Pass, worded "None visible": Microsoft documents that a search
                               returns no property the caller may not read, so this is what this
                               account can see
          one or more          Config.PresentStatus - Warning by default, Info by override: a TOOL
                               DEFAULT (catalogue ADA-OBJ-009), not a Microsoft value. Microsoft
                               publishes no grade; the same-domain and privileged rows carry the Fail
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [Parameter(Mandatory)]$Raw,
        [Parameter(Mandatory)]$Classified,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $item = ("SID history: {0}" -f $Domain)
    $evidence = ("Get-ADObject -LDAPFilter '{0}' -Server {1}" -f [string]$Config['SearchFilter'], $Domain)
    $records = @($Raw.Records | Where-Object { $null -ne $_ })
    $values = @($Classified.Values)
    if ($records.Count -eq 0) {
        $detail = ("None visible: no security principal with sIDHistory is visible to this account in {0}; the query {1} completed and returned no object. By the default security descriptors of the user, group and computer classes Authenticated Users may read sIDHistory, but Microsoft documents that a search returns no object or property the caller has no access to, so this is what this account can see, not proof that none exists." -f $Domain, [string]$Config['SearchFilter'])
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Pass -Detail $detail -Evidence $evidence -DomainSid ([string]$Classified.OwnSid) `
                -PrincipalCount 0 -ValueCount 0 -UserCount 0 -ComputerCount 0 -GroupCount 0 -OtherCount 0 -EnabledCount 0 -DisabledCount 0 -UnparsedCount 0 -Listed 0 -NotListed 0)
    }
    $users = 0; $computers = 0; $groups = 0; $others = 0; $enabled = 0; $disabled = 0; $noState = 0
    foreach ($r in $records) {
        $class = [string]$r.Class
        if (@(@($Config['UserClasses']) | Where-Object { $_ -eq $class }).Count -gt 0) { $users++ }
        elseif (@(@($Config['ComputerClasses']) | Where-Object { $_ -eq $class }).Count -gt 0) { $computers++ }
        elseif (@(@($Config['GroupClasses']) | Where-Object { $_ -eq $class }).Count -gt 0) { $groups++ }
        else { $others++ }
        if ($r.Enabled -is [bool]) { if ([bool]$r.Enabled) { $enabled++ } else { $disabled++ } }
        else { $noState++ }
    }
    $cap = [int]$Config['NameListCap']
    $listed = [math]::Min($cap, $records.Count)
    $names = @()
    for ($i = 0; $i -lt $listed; $i++) { $names += [string]$records[$i].Name }
    $status = [string]$Config['PresentStatus']
    $noValueNote = ''
    $noValue = [int]$Classified.NoValue
    if ($noValue -gt 0) { $noValueNote = (" {0} principal(s) came back with no sIDHistory value read, so their historic SIDs were not measured." -f $noValue) }
    $detail = ("{0} security principal(s) with sIDHistory visible to this account in {1}: {2} user, {3} computer (managed service accounts included), {4} group, {5} other; {6} enabled, {7} disabled, {8} with no enabled state (groups, or userAccountControl not returned). {9} historic SID value(s) in all, {10} of them not parsed.{14} {11} Graded {12}: the grade for SID history that is present is a tool default, not a Microsoft value (setting from: {13}). Microsoft publishes no grade for it; it names eliminating SID history as one way to reduce token size, and Defender for Identity reports SID history it judges unsecure for removal. Whether a value belongs to this domain itself or is privileged is graded in the two rows that follow." -f `
            $records.Count, $Domain, $users, $computers, $groups, $others, $enabled, $disabled, $noState, $values.Count, [int]$Classified.Unparsed,
            (Get-AdfaSidHistoryCapText -Listed $listed -NotListed ($records.Count - $listed) -Cap $cap -Column 'Principals'), $status, [string]$Config['ThresholdSource'], $noValueNote)
    return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $status -Detail $detail -Evidence $evidence -DomainSid ([string]$Classified.OwnSid) `
            -PrincipalCount $records.Count -ValueCount $values.Count -UserCount $users -ComputerCount $computers -GroupCount $groups -OtherCount $others `
            -EnabledCount $enabled -DisabledCount $disabled -UnparsedCount ([int]$Classified.Unparsed) -Listed $listed -NotListed ($records.Count - $listed) -Principals ($names -join '; '))
}

function Get-AdfaSidHistorySameDomainVerdict {
    <#
    .SYNOPSIS
        Pure: row 2, "SID history same-domain: <domain>" - a historic SID of the principal's own
        domain.
    .DESCRIPTION
        Called only for a query that succeeded. In this order:
          no principal returned                    Pass ("None visible")
          principals returned, no value read       Not Assessed
          the domain's own SID not read            Not Assessed, with the reason
          a value whose domain part is that SID    Fail (it stands even when other values were not
                                                   parsed or not read)
          a value that could not be parsed, or a   Not Assessed
          principal with no value read
          otherwise                                Pass
        The Fail is this tool's rule, from Microsoft's DsAddSidHistory constraint (source and
        destination "must not be in the same forest", so that duplicate SIDs are not created in
        it) and from a move issuing a new SID in the domain moved TO: Microsoft documents no origin
        for a historic SID of the object's own domain. That it indicates abuse is an inference.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [Parameter(Mandatory)]$Raw,
        [Parameter(Mandatory)]$Classified,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $item = ("SID history same-domain: {0}" -f $Domain)
    $evidence = ("Get-ADObject -LDAPFilter '{0}' -Server {1}; Get-ADDomain -Identity {1}" -f [string]$Config['SearchFilter'], $Domain)
    $values = @($Classified.Values)
    $unparsed = [int]$Classified.Unparsed
    $noValue = [int]$Classified.NoValue
    $own = [string]$Classified.OwnSid
    $records = @($Raw.Records | Where-Object { $null -ne $_ })
    if ($records.Count -eq 0) {
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Pass -Evidence $evidence -DomainSid $own -ValueCount 0 -UnparsedCount 0 -Listed 0 -NotListed 0 `
                -Detail ("None visible: no historic SID is visible to this account in {0}, so none belongs to the domain itself." -f $Domain))
    }
    if ($values.Count -eq 0) {
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -DomainSid $own -ValueCount 0 -UnparsedCount 0 `
                -Detail ("Not assessed: {0} principal(s) in {1} were returned for {2}, but no sIDHistory value was read on any of them, so none was compared with the domain's own SID. This is not a clean result." -f $records.Count, $Domain, [string]$Config['SearchFilter']))
    }
    if ($own -eq '') {
        $why = ([string]$Raw.DomainSidError).Trim()
        if ($why -eq '') { $why = '(no reason was recorded)' }
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -ValueCount $values.Count -UnparsedCount $unparsed `
                -Detail ("Not assessed: the SID of {0} was not read, so no historic SID was compared with it. This is not a clean result. Reported - {1}" -f $Domain, $why))
    }
    $hits = @($values | Where-Object { $_.SameDomain })
    $unparsedNote = ''
    if ($unparsed -gt 0) { $unparsedNote = (" {0} value(s) could not be parsed and were not compared." -f $unparsed) }
    if ($noValue -gt 0) { $unparsedNote += (" {0} principal(s) came back with no sIDHistory value read and were not compared." -f $noValue) }
    $cap = [int]$Config['NameListCap']
    if ($hits.Count -gt 0) {
        $holders = Get-AdfaSidHistoryHolderText -Values $hits -Cap $cap
        $detail = ("Same-domain SID history: {0} historic SID value(s) on {1} principal(s) belong to {2} itself - the domain part of each equals the domain's own SID (in the DomainSid column). Microsoft documents that DsAddSidHistory, the supported way to add SID history, requires the source and destination domains to be in different forests so that duplicate SIDs are not created in one forest, and that moving an object between domains keeps the SID it had in the domain it left; a SID of the object's own domain therefore has no documented origin. That it points to tampering is this tool's inference, not a Microsoft statement.{3} {4}" -f `
                $hits.Count, $holders.Count, $Domain, $unparsedNote, (Get-AdfaSidHistoryCapText -Listed $holders.Listed -NotListed $holders.NotListed -Cap $cap -Column 'Principals'))
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Fail -Detail $detail -Evidence $evidence -DomainSid $own -PrincipalCount $holders.Count `
                -ValueCount $hits.Count -UnparsedCount $unparsed -Listed $holders.Listed -NotListed $holders.NotListed -Principals $holders.Principals -HistoricSids $holders.HistoricSids)
    }
    if ($unparsed -gt 0 -or $noValue -gt 0) {
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -DomainSid $own -ValueCount $values.Count -UnparsedCount $unparsed `
                -Detail ("Not assessed: none of the parsed historic SIDs belongs to {0}, but {1} value(s) could not be parsed and {2} principal(s) came back with no sIDHistory value read, so a same-domain value cannot be ruled out. This is not a clean result." -f $Domain, $unparsed, $noValue))
    }
    return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Pass -Evidence $evidence -DomainSid $own -ValueCount $values.Count -UnparsedCount 0 -Listed 0 -NotListed 0 `
            -Detail ("None found: none of the {0} historic SID value(s) visible to this account belongs to {1} itself." -f $values.Count, $Domain))
}

function Get-AdfaSidHistoryPrivilegedVerdict {
    <#
    .SYNOPSIS
        Pure: row 3, "SID history privileged: <domain>" - a privileged well-known RID or SID in SID
        history, named.
    .DESCRIPTION
        Called only for a query that succeeded. Privileged: a RID in Config.PrivilegedDomainRids on
        an account-domain SID (S-1-5-21-x-y-z-RID), whatever its domain, or a SID equal to one in
        Config.PrivilegedSids. No principal returned: Pass. Principals returned and no value read:
        Not Assessed. A privileged value: Fail, naming each privileged RID or well-known group by
        name and count in Detail (the SIDs themselves only in HistoricSids); it stands even when
        other values were not parsed or not read. A value not parsed, or a principal with no value
        read, and none privileged: Not Assessed. Otherwise Pass. Microsoft's Defender for Identity gives
        the Enterprise Admins SID in another account's SID history as its example of unsecure SID
        history; which SIDs count as privileged is this tool's list, from Microsoft's tables.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [Parameter(Mandatory)]$Raw,
        [Parameter(Mandatory)]$Classified,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $item = ("SID history privileged: {0}" -f $Domain)
    $evidence = ("Get-ADObject -LDAPFilter '{0}' -Server {1}" -f [string]$Config['SearchFilter'], $Domain)
    $notRun = 'Whether a trust lets these SIDs through (SID filtering, also called quarantine) is reported in the Trusts section, not here.'
    $values = @($Classified.Values)
    $unparsed = [int]$Classified.Unparsed
    $noValue = [int]$Classified.NoValue
    $own = [string]$Classified.OwnSid
    $records = @($Raw.Records | Where-Object { $null -ne $_ })
    if ($records.Count -eq 0) {
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Pass -Evidence $evidence -NotRun $notRun -DomainSid $own -ValueCount 0 -UnparsedCount 0 -Listed 0 -NotListed 0 `
                -Detail ("None visible: no historic SID is visible to this account in {0}, so none is privileged." -f $Domain))
    }
    if ($values.Count -eq 0) {
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -NotRun $notRun -DomainSid $own -ValueCount 0 -UnparsedCount 0 `
                -Detail ("Not assessed: {0} principal(s) in {1} were returned for {2}, but no sIDHistory value was read on any of them, so none was checked against the privileged list. This is not a clean result." -f $records.Count, $Domain, [string]$Config['SearchFilter']))
    }
    $hits = @($values | Where-Object { [string]$_.Privileged -ne '' })
    $cap = [int]$Config['NameListCap']
    if ($hits.Count -gt 0) {
        # Privileged is "<name> (RID n)" or "<name> (well-known SID)": no SID text reaches Detail.
        $named = @($hits | Group-Object -Property { [string]$_.Privileged } | Sort-Object -Property Name | ForEach-Object { ("{0} x{1}" -f $_.Name, $_.Count) })
        $unparsedNote = ''
        if ($unparsed -gt 0) { $unparsedNote = (" {0} other value(s) could not be parsed." -f $unparsed) }
        if ($noValue -gt 0) { $unparsedNote += (" {0} principal(s) came back with no sIDHistory value read." -f $noValue) }
        $holders = Get-AdfaSidHistoryHolderText -Values $hits -Cap $cap -WithPrivilegedName
        $detail = ("Privileged SID in SID history: {0} historic SID value(s) on {1} principal(s) are privileged well-known SIDs: {2}. A SID in sIDHistory is added to the holder's access token at sign-in and can grant access as that SID; Microsoft's Defender for Identity gives the Enterprise Admins SID in another account's SID history as its example of unsecure SID history, and Microsoft documents that DsAddSidHistory refuses accounts with well-known SIDs and adds a well-known RID only to a principal that holds the same RID. Which RIDs and SIDs count as privileged is this tool's list, read from Microsoft's well-known SID tables.{3} {4}" -f `
                $hits.Count, $holders.Count, ($named -join ', '), $unparsedNote, (Get-AdfaSidHistoryCapText -Listed $holders.Listed -NotListed $holders.NotListed -Cap $cap -Column 'Principals'))
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Fail -Detail $detail -Evidence $evidence -NotRun $notRun -DomainSid $own -PrincipalCount $holders.Count `
                -ValueCount $hits.Count -UnparsedCount $unparsed -Listed $holders.Listed -NotListed $holders.NotListed -Principals $holders.Principals -HistoricSids $holders.HistoricSids)
    }
    if ($unparsed -gt 0 -or $noValue -gt 0) {
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -NotRun $notRun -DomainSid $own -ValueCount $values.Count -UnparsedCount $unparsed `
                -Detail ("Not assessed: none of the parsed historic SIDs is privileged, but {0} value(s) could not be parsed and {1} principal(s) came back with no sIDHistory value read, so a privileged value cannot be ruled out. This is not a clean result." -f $unparsed, $noValue))
    }
    return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Pass -Evidence $evidence -NotRun $notRun -DomainSid $own -ValueCount $values.Count -UnparsedCount 0 -Listed 0 -NotListed 0 `
            -Detail ("None found: none of the {0} historic SID value(s) visible to this account is a privileged RID or SID of this tool's list ({1} RIDs and {2} SIDs, from Microsoft's well-known SID tables)." -f $values.Count, @($Config['PrivilegedDomainRids']).Count, @($Config['PrivilegedSids']).Count))
}

function Get-AdfaSidHistorySourceVerdict {
    <#
    .SYNOPSIS
        Pure: row 4, "SID history sources: <domain>" - the domains the historic SIDs came from. Info.
    .DESCRIPTION
        Each distinct domain part, with its count, labelled from the SIDs of the forest's domains
        and of this domain's trusted domain objects, as "this forest", "trust partner",
        "builtin or well-known", "not an account-domain SID" or "unresolved". "Unresolved" says only
        that the domain part matched neither list; this read cannot say what that domain is. The
        row says when the forest's SIDs or the trusts were read only in part, or when a principal
        came back with no sIDHistory value read. When principals were returned and no value was read
        on any of them, the row is Not Assessed: no source was measured.
    .OUTPUTS
        [pscustomobject] a row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [Parameter(Mandatory)]$Raw,
        [Parameter(Mandatory)]$Classified,
        [AllowNull()]$ForestMap = $null,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $item = ("SID history sources: {0}" -f $Domain)
    $evidence = ("Get-ADObject -LDAPFilter '{0}' and '{1}' under {2} -Server {3}; Get-ADDomain for each forest domain" -f [string]$Config['SearchFilter'], [string]$Config['TrustFilter'], [string]$Config['TrustContainerRdn'], $Domain)
    $notRun = 'Whether a trust filters SIDs from these domains (SID filtering, also called quarantine) is reported in the Trusts section, not here. Only the trusted domain objects of this domain are read for this row.'
    $values = @($Classified.Values)
    $own = [string]$Classified.OwnSid
    $notes = @()
    if (-not [bool]$Raw.TrustOk) {
        $why = ([string]$Raw.TrustError).Trim()
        if ($why -eq '') { $why = '(no reason was recorded)' }
        $notes += ("The trusted domain objects of {0} could not be read ({1}), so a trust partner's SID shows as unresolved." -f $Domain, $why)
    }
    $failures = @()
    if ($null -ne $ForestMap) {
        $failProp = $ForestMap.PSObject.Properties['Failures']
        if ($null -ne $failProp) { $failures = @($failProp.Value | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }) }
    }
    if ($failures.Count -gt 0) {
        $notes += ("The SID of {0} forest domain(s) could not be read ({1}), so a SID from one of them shows as unresolved." -f $failures.Count, ($failures -join '; '))
    }
    $noValue = [int]$Classified.NoValue
    $records = @($Raw.Records | Where-Object { $null -ne $_ })
    if ($noValue -gt 0 -and $values.Count -gt 0) {
        $notes += ("{0} principal(s) came back with no sIDHistory value read, so their source domains are not listed." -f $noValue)
    }
    $noteText = ''
    if ($notes.Count -gt 0) { $noteText = ' ' + ($notes -join ' ') }
    if ($values.Count -eq 0 -and $records.Count -gt 0) {
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -NotRun $notRun -DomainSid $own -ValueCount 0 -UnparsedCount 0 `
                -Detail ("Not assessed: {0} principal(s) in {1} were returned for {2}, but no sIDHistory value was read on any of them, so no source domain was measured. This is not a clean result.{3}" -f $records.Count, $Domain, [string]$Config['SearchFilter'], $noteText))
    }
    if ($values.Count -eq 0) {
        return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Info -Evidence $evidence -NotRun $notRun -DomainSid $own -ValueCount 0 -UnparsedCount 0 `
                -Detail ("No historic SID is visible to this account in {0}, so there is no source domain to report.{1}" -f $Domain, $noteText))
    }
    $parsed = @($values | Where-Object { $_.Parsed.Ok })
    $groups = @($parsed | Group-Object -Property { [string]$_.SourceKey } | Sort-Object -Property Name)
    $forestCount = 0; $trustCount = 0; $wellKnown = 0; $unresolved = 0; $other = 0
    $listing = @()
    foreach ($g in $groups) {
        $label = [string]@($g.Group)[0].Source
        if ($label -match ', this forest$') { $forestCount++ }
        elseif ($label -match ', trust partner$') { $trustCount++ }
        elseif ($label -eq 'builtin or well-known') { $wellKnown++ }
        elseif ($label -eq 'unresolved') { $unresolved++ }
        else { $other++ }
        $listing += ("{0} ({1}) x{2}" -f $g.Name, $label, $g.Count)
    }
    $detail = ("Sources of {0} historic SID value(s) visible to this account in {1}: {2} distinct domain part(s) - {3} in this forest, {4} trust partner(s) of this domain, {5} builtin or well-known, {6} unresolved, {7} not an account-domain SID; {8} value(s) not parsed. Listed in the SourceDomains column. 'Unresolved' means only that the domain part matched neither a domain of this forest nor a trusted domain object of this domain; this read cannot say what that domain is.{9}" -f `
            $values.Count, $Domain, $groups.Count, $forestCount, $trustCount, $wellKnown, $unresolved, $other, [int]$Classified.Unparsed, $noteText)
    return (New-AdfaSidHistoryRow -Scope $Domain -Item $item -Status $script:Status.Info -Detail $detail -Evidence $evidence -NotRun $notRun -DomainSid $own `
            -ValueCount $values.Count -UnparsedCount ([int]$Classified.Unparsed) -SourceDomains ($listing -join '; '))
}

function Get-AdfaSidHistoryDomainFinding {
    <#
    .SYNOPSIS
        Pure: one domain's raw read to its four SID history rows, in Item order.
    .DESCRIPTION
        A principal query that did not succeed - unreachable, access denied, timed out, any other
        failure, or a property list refused before any call - makes all four rows Not Assessed with
        the same cause, worded by class from the exception type first (Get-AdfaLapsReadFailureLead).
        A count that was not measured is left empty.
    .OUTPUTS
        [pscustomobject[]] four rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$Domain,
        [AllowNull()]$Raw,
        [AllowNull()]$ForestMap = $null,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $items = @('SID history', 'SID history same-domain', 'SID history privileged', 'SID history sources')
    if ($null -eq $Raw -or -not [bool]$Raw.Ok) {
        $why = 'Not assessed: the directory read returned nothing. This is a defect in the tool, not a result.'
        if ($null -ne $Raw -and [bool]$Raw.Refused) {
            $why = ("Not assessed: {0} This is a defect in the tool, not a result." -f ([string]$Raw.Error).Trim())
        }
        elseif ($null -ne $Raw) {
            $why = ("{0} This is not a clean result." -f (Get-AdfaLapsReadFailureLead -Message ([string]$Raw.Error) -TypeName ([string]$Raw.ErrorType) -What ("the security principals of {0} that carry sIDHistory" -f $Domain)))
        }
        $evidence = ("Get-ADObject -LDAPFilter '{0}' -Server {1}" -f [string]$Config['SearchFilter'], $Domain)
        return @($items | ForEach-Object { New-AdfaSidHistoryRow -Scope $Domain -Item ("{0}: {1}" -f $_, $Domain) -Status $script:Status.NotAssessed -Detail $why -Evidence $evidence })
    }
    $classified = Get-AdfaSidHistoryClassification -Records @($Raw.Records) -DomainSid ([string]$Raw.DomainSid) -ForestMap $ForestMap -Trusts @($Raw.Trusts) -Config $Config
    $rows = @()
    $rows += Get-AdfaSidHistoryCountVerdict -Domain $Domain -Raw $Raw -Classified $classified -Config $Config
    $rows += Get-AdfaSidHistorySameDomainVerdict -Domain $Domain -Raw $Raw -Classified $classified -Config $Config
    $rows += Get-AdfaSidHistoryPrivilegedVerdict -Domain $Domain -Raw $Raw -Classified $classified -Config $Config
    $rows += Get-AdfaSidHistorySourceVerdict -Domain $Domain -Raw $Raw -Classified $classified -ForestMap $ForestMap -Config $Config
    return @($rows)
}

function Get-AdfaSidHistory {
    <#
    .SYNOPSIS
        SID history, per scoped domain: principals with sIDHistory, historic SIDs of their own
        domain, privileged historic SIDs, and the domains the historic SIDs came from. Directory
        reads only.
    .DESCRIPTION
        Two seams, each read-only and neither of which throws: Get-AdfaSidHistoryForestMap once per
        run (the SID of every forest domain) and Get-AdfaSidHistoryRaw once per scoped domain. No
        cmdlet that writes is called: sIDHistory is never removed or changed (Microsoft's own
        remediation, Set-ADUser -Remove, is quoted in the advice and never run), and no trust's SID
        filtering is read or set here - netdom and Forest.SetSidFilteringStatus are not used.

        DECLARED POPULATION: the domains named in -Domains. Each gets exactly four rows,
        "SID history: <domain>", "SID history same-domain: <domain>", "SID history privileged:
        <domain>" and "SID history sources: <domain>", whatever happened to its read; with none
        scoped there is one "SID history (no domain scoped)" row. An exception while one domain is
        handled makes its four rows Not Assessed and never ends the section.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$Domains = @(),
        [AllowNull()][AllowEmptyCollection()][AllowEmptyString()][string[]]$ForestDomains = @(),
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    $scoped = New-Object System.Collections.ArrayList
    foreach ($name in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        if (@($scoped | Where-Object { $_ -eq $name.Trim() }).Count -eq 0) { [void]$scoped.Add($name.Trim()) }
    }
    if ($scoped.Count -eq 0) {
        $rows += New-AdfaSidHistoryRow -Item 'SID history (no domain scoped)' -Status $script:Status.NotAssessed -Evidence 'none' `
            -Detail 'No domain was scoped for this run, so no security principal was read for sIDHistory. This is not a clean result.'
        return @($rows)
    }
    $mapDomains = @(@($ForestDomains) + @($scoped) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $forestMap = Get-AdfaSidHistoryForestMap -Domains $mapDomains -AdParams $AdParams
    foreach ($domain in $scoped) {
        try {
            $raw = Get-AdfaSidHistoryRaw -DomainName $domain -AdParams $AdParams -Config $Config
            $rows += @(Get-AdfaSidHistoryDomainFinding -Domain $domain -Raw $raw -ForestMap $forestMap -Config $Config)
        }
        catch {
            # A defect in this tool, not in the directory. Fail closed for this domain only.
            $why = ("Not assessed: handling the SID history of {0} failed inside this tool, so nothing about this domain is graded; this is a defect in the tool, not a result. Error: {1}" -f $domain, [string]$_.Exception.Message)
            foreach ($prefix in @('SID history', 'SID history same-domain', 'SID history privileged', 'SID history sources')) {
                $rows += New-AdfaSidHistoryRow -Scope $domain -Item ("{0}: {1}" -f $prefix, $domain) -Status $script:Status.NotAssessed -Evidence 'none' -Detail $why
            }
        }
    }
    return @($rows)
}

function Merge-AdfaSidHistoryConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over the built-in SID history table, with validation. The
        SidHistory validator for -ConfigOverridePath.
    .DESCRIPTION
        What a file can change: PresentStatus (Warning or Info, the grade of SID history that is
        present and neither same-domain nor privileged) and NameListCap (a whole number from 0 to
        1000, how many names one row lists):

            { "SidHistory": { "PresentStatus": "Info", "NameListCap": 50 } }

        What it cannot: the privileged RIDs and SIDs, the filters, the property lists, the class
        buckets and the sources. Every such key is refused as unknown, so a file cannot make the
        tool ask for every attribute or stop a privileged SID from failing.

        Refused with the reason: an override that is not one object, an empty object, an unknown
        key, a null, a PresentStatus that is not the text Warning or Info (SID history that is
        present is never reported as a pass), a NameListCap that is not a JSON number or not a
        whole number from 0 to 1000.

        Provenance follows the keys: ThresholdSource is rewritten to name the override's source for
        exactly the keys it supplied.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("SID history config override must be a single object with named keys (for example {{ ""PresentStatus"": ""Info"" }}), not a {0}." -f $Override.GetType().Name)
    }
    if ($table.Count -eq 0) {
        throw 'SID history config override is an empty object. It names no key, so it would change nothing while appearing to be in force.'
    }
    $known = @('PresentStatus', 'NameListCap')
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("SID history config override names an unknown key '{0}'. Known keys: {1}. The privileged RIDs and SIDs, the filters, the property lists, the class buckets and the sources cannot be set from a file." -f $given, ($known -join ', '))
        }
        $name = [string]$match[0]
        if ($supplied -contains $name) { throw ("SID history config override names '{0}' more than once." -f $name) }
        $value = $table[$k]
        if ($null -eq $value) {
            throw ("SID history config override sets '{0}' to null. Remove the key to keep the built-in value." -f $name)
        }
        if ($name -eq 'PresentStatus') {
            $allowed = @('Warning', 'Info')
            $statusMatch = @()
            if ($value -is [string]) { $statusMatch = @($allowed | Where-Object { $_ -eq $value.Trim() }) }
            if ($statusMatch.Count -eq 0) {
                throw ("SID history config override sets 'PresentStatus' to '{0}'. It must be Warning or Info: SID history that is present is never reported as a pass, and a Fail is kept for same-domain and privileged SIDs." -f [string]$value)
            }
            $merged['PresentStatus'] = [string]$statusMatch[0]
        }
        else {
            # A JSON number only: how a quoted string becomes a number depends on the host's culture.
            if ($value -is [array] -or $numericTypes -notcontains $value.GetType()) {
                throw ("SID history config override sets 'NameListCap' to a {0}. It must be a JSON number, written without quotes." -f $value.GetType().Name)
            }
            $number = [double]$value
            if ([double]::IsNaN($number) -or [double]::IsInfinity($number) -or $number -ne [math]::Floor($number) -or $number -lt 0 -or $number -gt 1000) {
                throw ("SID history config override sets 'NameListCap' to {0}. It must be a whole number from 0 to 1000 (names listed in one row)." -f $number.ToString('0.####', $inv))
            }
            $merged['NameListCap'] = [int]$number
        }
        $supplied += $name
    }
    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
    $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
    if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
    $merged['ThresholdSource'] = $text
    return $merged
}

# ---------------------------------------------------------------------------
# -ConfigOverridePath: one JSON file, one top-level key per section (PORT-PLAN C2)
# ---------------------------------------------------------------------------
# The sections whose built-in table that file can replace. A top-level key of the file is one of
# these names, and its value goes to that section's own validator. A later plan row adds ONE
# line here and writes its Merge-* function; nothing in the two loader functions changes.
#
#   ConfigKey  the key of the section's built-in table in $script:Config
#   Section    the -Sections value that uses the table, so a run that was given a file for a
#              section it did not select can say so in its log
#   Merge      the validator. Contract: -BaseConfig <hashtable> -Override <object>
#              -OverrideSource <string>; returns the merged table; throws on anything it cannot
#              use; rewrites provenance only for what the override supplied.
#
# Exchange SE and DC system are deliberately NOT here. They keep -ExchangeSeConfigPath and
# -DcSystemConfigPath, unchanged. A row that adds either must first decide what happens when
# both sources name the same section.
$script:ConfigOverrideSections = [ordered]@{
    DcDisk         = @{ ConfigKey = 'DcDisk'; Section = 'DcDisk'; Merge = 'Merge-AdfaDcDiskConfig' }
    DcHardening    = @{ ConfigKey = 'DcHardening'; Section = 'DcHardening'; Merge = 'Merge-AdfaDcHardeningConfig' }
    Laps           = @{ ConfigKey = 'Laps'; Section = 'Laps'; Merge = 'Merge-AdfaLapsConfig' }
    DcCertificates = @{ ConfigKey = 'DcCertificates'; Section = 'DcCertificates'; Merge = 'Merge-AdfaDcCertificatesConfig' }
    RidPool        = @{ ConfigKey = 'RidPool'; Section = 'RidPool'; Merge = 'Merge-AdfaRidPoolConfig' }
    SidHistory     = @{ ConfigKey = 'SidHistory'; Section = 'SecurityPosture'; Merge = 'Merge-AdfaSidHistoryConfig' }
    Gpo            = @{ ConfigKey = 'Gpo'; Section = 'Gpo'; Merge = 'Merge-AdfaGpoConfig' }
    Acl            = @{ ConfigKey = 'Acl'; Section = 'Acl'; Merge = 'Merge-AdfaAclConfig' }
    # One table for three sections (PORT-PLAN C10): Section names the first, AlsoUsedBy the other two, so
    # the "validated but not used" log is right whichever of them a run selects.
    Privileged     = @{ ConfigKey = 'Privileged'; Section = 'PrivilegedAccounts'; AlsoUsedBy = @('PrivilegedHygiene', 'Kerberos'); Merge = 'Merge-AdfaPrivilegedConfig' }
    # PORT-PLAN C11: the time-out and retries of one dcdiag invocation only; no test list.
    DcDiag         = @{ ConfigKey = 'DcDiag'; Section = 'DcDiagnostics'; Merge = 'Merge-AdfaDcDiagConfig' }
    # PORT-PLAN C13: the statuses and the record export cap only; no record name, pattern or port.
    Dns            = @{ ConfigKey = 'Dns'; Section = 'Dns'; AlsoUsedBy = @('DnsAdConsistency', 'DomainControllers', 'DnsRecordExport'); Merge = 'Merge-AdfaDnsConfig' }
    # PORT-PLAN C14: five tables, one generic validator that reads each table's own OverrideSpec, so a
    # file can set only the keys the table declares there.
    Reach          = @{ ConfigKey = 'Reach'; Section = 'PortMatrix'; AlsoUsedBy = @('TimeHierarchy', 'Topology'); Merge = 'Merge-AdfaSpecConfig' }
    SiteCoverage   = @{ ConfigKey = 'SiteCoverage'; Section = 'Topology'; Merge = 'Merge-AdfaSpecConfig' }
    ClockSkew      = @{ ConfigKey = 'ClockSkew'; Section = 'TimeHierarchy'; Merge = 'Merge-AdfaSpecConfig' }
    Stale          = @{ ConfigKey = 'Stale'; Section = 'StaleObjects'; Merge = 'Merge-AdfaSpecConfig' }
    SysvolEngine   = @{ ConfigKey = 'SysvolEngine'; Section = 'Sysvol'; Merge = 'Merge-AdfaSpecConfig' }
    # PORT-PLAN C15: the inventory caps only (objects per read, names per row, events per log, event
    # groups per log); no log, level, filter, flag table, label, key or pattern.
    # PORT-PLAN C4b: MaxObjects also caps the site link and connection reads of Topology.
    Inventory      = @{ ConfigKey = 'Inventory'; Section = 'Identity'; AlsoUsedBy = @('Forest', 'Trusts', 'Gpo', 'DsEvents', 'TimeHierarchy', 'Topology'); Merge = 'Merge-AdfaSpecConfig' }
}

function Resolve-AdfaConfigOverride {
    <#
    .SYNOPSIS
        Pure: validates a parsed -ConfigOverridePath document and returns the merged table of
        every section it names.
    .DESCRIPTION
        The document must be ONE object whose keys are section names from the registry. Each
        value is handed to that section's own validator; a refusal comes back prefixed with the
        section's name. An unknown section is refused with the known ones listed - a threshold
        written at the top level, outside its section, is the usual way to get there.

        Only the sections the document names are returned. A section it does not name is absent
        from the result, so its caller keeps the built-in table and that table's provenance.
    .OUTPUTS
        [hashtable] section name -> merged config table.
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [AllowNull()]$Override,
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [Parameter(Mandatory)][System.Collections.IDictionary]$Sections,
        [string]$OverrideSource = ''
    )
    if ($null -eq $Override) {
        throw 'Config override is null. It must be a single object whose keys are section names.'
    }
    $isTable = ($Override -is [System.Collections.IDictionary])
    $isObject = ($Override -is [System.Management.Automation.PSCustomObject])
    if (-not $isTable -and -not $isObject) {
        throw ("Config override must be a single object whose keys are section names (for example {{ ""DcDisk"": {{ ""WarnBelowPercent"": 25 }} }}), not a {0}." -f $Override.GetType().Name)
    }
    $names = @()
    if ($isTable) { $names = @($Override.Keys) }
    else { $names = @($Override.PSObject.Properties | ForEach-Object { $_.Name }) }
    if ($names.Count -eq 0) {
        throw 'Config override is an empty object. It names no section, so it would change nothing while appearing to be in force.'
    }
    $known = @($Sections.Keys | ForEach-Object { [string]$_ })
    $result = @{}
    foreach ($k in $names) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("Config override names an unknown section '{0}'. Known sections: {1}." -f $given, ($known -join ', '))
        }
        $section = [string]$match[0]
        # As in the section validators: reachable from an in-memory object only. A section
        # written twice in a file is found in the text by Import-AdfaConfigOverride.
        if ($result.ContainsKey($section)) { throw ("Config override names section '{0}' more than once." -f $section) }
        $value = $null
        if ($isTable) { $value = $Override[$k] }
        else { $value = $Override.PSObject.Properties[$given].Value }
        if ($null -eq $value) {
            throw ("Config override sets section '{0}' to null. Remove the key to keep the built-in table." -f $section)
        }
        $definition = $Sections[$section]
        $configKey = [string](Get-AdfaConfigValue -Entry $definition -Name 'ConfigKey')
        $merge = [string](Get-AdfaConfigValue -Entry $definition -Name 'Merge')
        # A registry line that points at nothing is a defect in this tool, not in the file.
        if ($configKey -eq '' -or -not $BaseConfig.ContainsKey($configKey) -or $BaseConfig[$configKey] -isnot [hashtable]) {
            throw ("Config override: section '{0}' is registered against a built-in table '{1}' that does not exist. This is a defect in the tool, not in the file." -f $section, $configKey)
        }
        if ($merge -eq '' -or $null -eq (Get-Command -Name $merge -CommandType Function -ErrorAction SilentlyContinue)) {
            throw ("Config override: section '{0}' is registered with a validator '{1}' that does not exist. This is a defect in the tool, not in the file." -f $section, $merge)
        }
        try { $result[$section] = & $merge -BaseConfig $BaseConfig[$configKey] -Override $value -OverrideSource $OverrideSource }
        catch { throw ("Config override, section '{0}': {1}" -f $section, $_.Exception.Message) }
    }
    return $result
}

function Get-AdfaJsonTopLevelKind {
    <#
    .SYNOPSIS
        Pure: what a JSON text holds at its top level, read from its first character.
    .DESCRIPTION
        Object, Array, String, Empty or Other (a number, true, false, null - or anything else,
        a comment included). Read from the text and not from what ConvertFrom-Json returned,
        because the two PowerShell editions return different things for the same array.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyString()][string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return 'Empty' }
    # A byte order mark that survived the read is not part of the document.
    $body = $Text.TrimStart([char[]]@([char]0xFEFF, [char]32, [char]9, [char]13, [char]10))
    if ($body.Length -eq 0) { return 'Empty' }
    $first = [string]$body[0]
    if ($first -ceq '{') { return 'Object' }
    if ($first -ceq '[') { return 'Array' }
    if ($first -ceq '"') { return 'String' }
    return 'Other'
}

function Get-AdfaJsonDuplicateKey {
    <#
    .SYNOPSIS
        Pure: the keys a JSON text names more than once inside one object.
    .DESCRIPTION
        ConvertFrom-Json cannot report this. Measured on Windows PowerShell 5.1 and PowerShell
        7.6: for { "a": 1, "a": 2 } both return a = 2 with no error, and for keys that differ
        only by case both refuse the document. So a repeated key has to be found in the text.

        A single pass over the characters, tracking only what is needed for that: where
        strings begin and end (with their escapes decoded, so "a" and "a" are one key),
        which objects and arrays are open, and whether the next string in an object is a key.
        Comments (// and /* */), which PowerShell 7 accepts, are skipped. Keys are compared
        without regard to case, as PowerShell reads them. It is meant for text that
        ConvertFrom-Json has already accepted, and does not validate JSON.
    .OUTPUTS
        [string[]] One entry per repeated key, as its dotted path (DcDisk.WarnBelowPercent),
        each path once. Empty when nothing is repeated.
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param([AllowNull()][AllowEmptyString()][string]$Text)
    $found = New-Object System.Collections.ArrayList
    if ([string]::IsNullOrEmpty($Text)) { return @() }
    # Open containers, innermost last: IsObject, Keys (case-insensitive), ExpectKey, Name.
    $open = New-Object System.Collections.ArrayList
    $nextName = ''
    $length = $Text.Length
    $i = 0
    while ($i -lt $length) {
        $c = $Text[$i]
        if ($c -eq [char]'"') {
            $builder = New-Object System.Text.StringBuilder
            $i++
            while ($i -lt $length -and $Text[$i] -ne [char]'"') {
                if ($Text[$i] -eq [char]'\' -and ($i + 1) -lt $length) {
                    $escape = $Text[$i + 1]
                    $i += 2
                    if ($escape -ceq [char]'u' -and ($i + 4) -le $length) {
                        $code = 0
                        if ([int]::TryParse($Text.Substring($i, 4), [System.Globalization.NumberStyles]::HexNumber, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$code)) {
                            [void]$builder.Append([char]$code)
                            $i += 4
                        }
                        continue
                    }
                    if ($escape -ceq [char]'n') { [void]$builder.Append("`n") }
                    elseif ($escape -ceq [char]'r') { [void]$builder.Append("`r") }
                    elseif ($escape -ceq [char]'t') { [void]$builder.Append("`t") }
                    elseif ($escape -ceq [char]'b') { [void]$builder.Append([char]8) }
                    elseif ($escape -ceq [char]'f') { [void]$builder.Append([char]12) }
                    else { [void]$builder.Append($escape) }
                    continue
                }
                [void]$builder.Append($Text[$i])
                $i++
            }
            $i++
            if ($open.Count -gt 0) {
                $top = $open[$open.Count - 1]
                if ($top['IsObject'] -and $top['ExpectKey']) {
                    $key = $builder.ToString()
                    if ($top['Keys'].ContainsKey($key)) {
                        $path = @(@($open | ForEach-Object { [string]$_['Name'] } | Where-Object { $_ -ne '' }) + $key) -join '.'
                        if (-not $found.Contains($path)) { [void]$found.Add($path) }
                    }
                    else { $top['Keys'][$key] = $true }
                    $top['ExpectKey'] = $false
                    $nextName = $key
                }
            }
            continue
        }
        if ($c -eq [char]'/' -and ($i + 1) -lt $length) {
            if ($Text[$i + 1] -eq [char]'/') {
                while ($i -lt $length -and $Text[$i] -ne [char]10) { $i++ }
                continue
            }
            if ($Text[$i + 1] -eq [char]'*') {
                $end = $Text.IndexOf('*/', $i + 2, [System.StringComparison]::Ordinal)
                if ($end -lt 0) { break }
                $i = $end + 2
                continue
            }
        }
        if ($c -eq [char]'{') { [void]$open.Add(@{ IsObject = $true; Keys = @{}; ExpectKey = $true; Name = $nextName }); $nextName = '' }
        elseif ($c -eq [char]'[') { [void]$open.Add(@{ IsObject = $false; Keys = @{}; ExpectKey = $false; Name = $nextName }); $nextName = '' }
        elseif ($c -eq [char]'}' -or $c -eq [char]']') { if ($open.Count -gt 0) { $open.RemoveAt($open.Count - 1) } }
        elseif ($c -eq [char]',') { if ($open.Count -gt 0 -and $open[$open.Count - 1]['IsObject']) { $open[$open.Count - 1]['ExpectKey'] = $true } }
        $i++
    }
    return @($found.ToArray())
}

function Import-AdfaConfigOverride {
    <#
    .SYNOPSIS
        Loads the -ConfigOverridePath file and returns the merged table of every section it names.
    .DESCRIPTION
        A missing, empty or malformed file throws, and so does anything the document or one of
        its sections holds that could not be used: judging a forest against built-in values
        while the operator believes their own are in force is worse than stopping. Every
        refusal names the file.

        Two faults are found in the file's text, because the parsed document hides them: a
        top-level array holding one object, which PowerShell 7 would unwrap and apply while
        Windows PowerShell 5.1 refused it, and a key written twice in one object, which both
        editions reduce to its last value without an error.
    .OUTPUTS
        [hashtable] section name -> merged config table.
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [Parameter(Mandatory)][System.Collections.IDictionary]$Sections
    )
    if (-not (Test-Path -LiteralPath $Path)) { throw ("Config override file not found: {0}" -f $Path) }
    $raw = Get-Content -LiteralPath $Path -Raw -ErrorAction Stop
    if ([string]::IsNullOrWhiteSpace($raw)) { throw ("Config override file is empty: {0}" -f $Path) }
    $obj = $null
    try { $obj = $raw | ConvertFrom-Json -ErrorAction Stop }
    catch { throw ("Config override file is not valid JSON ({0}): {1}" -f $Path, $_.Exception.Message) }
    # The JSON literal null parses without error. A file that was named must change something or
    # stop the run. (PowerShell 7 also arrives here for an empty top-level array, which it
    # unrolls to nothing; Windows PowerShell 5.1 hands that array on, and it is refused below.)
    if ($null -eq $obj) { throw ("Config override file holds JSON null or an empty array, not an object: {0}" -f $Path) }
    # The two checks below read the TEXT, because the parsed object cannot show either fault.
    # 1. A top-level array holding one object. PowerShell 7 unrolls it on the pipeline, so $obj
    #    is the inner object and the file would be applied; Windows PowerShell 5.1 hands the
    #    array on and refuses it. The same file must get the same answer on both.
    $kind = Get-AdfaJsonTopLevelKind -Text $raw
    if ($kind -ne 'Object') {
        throw ("Config override must be a single object whose keys are section names (for example {{ ""DcDisk"": {{ ""WarnBelowPercent"": 25 }} }}), not a JSON {0}. The file must begin with '{{'; an array is refused even when it holds one object. (file: {1})" -f $kind.ToLowerInvariant(), $Path)
    }
    # 2. A key written twice in one object. ConvertFrom-Json keeps the last one and drops the
    #    rest without a word on both editions, so the "more than once" checks in the validators
    #    never see it: a file that contradicts itself would be applied, and cited as the source.
    $twice = @(Get-AdfaJsonDuplicateKey -Text $raw)
    if ($twice.Count -gt 0) {
        throw ("Config override names {0} more than once. A JSON parser keeps only the last of them, so which value was meant cannot be known and the file is refused. (file: {1})" -f (@($twice | ForEach-Object { "'{0}'" -f $_ }) -join ', '), $Path)
    }
    try { return (Resolve-AdfaConfigOverride -Override $obj -BaseConfig $BaseConfig -Sections $Sections -OverrideSource $Path) }
    catch { throw ("{0} (file: {1})" -f $_.Exception.Message, $Path) }
}

function ConvertFrom-AdfaShowreplCsv {
    <#
    .SYNOPSIS
        Pure parser for 'repadmin /showrepl * /csv' output. Locates the CSV header and
        returns one object per replication link. Tolerates banner lines before the header.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([AllowEmptyString()][string]$Text = '')
    # Plain returns on purpose: callers wrap with @(...), and the `return @()` shape
    # would hand them one element that IS the empty array (PORT-PLAN P3).
    if ([string]::IsNullOrWhiteSpace($Text)) { return @() }
    $lines = @($Text -split "`r?`n")
    $headerIdx = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match 'Destination DSA' -and $lines[$i] -match 'Naming Context') { $headerIdx = $i; break }
    }
    if ($headerIdx -lt 0) { return @() }
    $csv = @($lines[$headerIdx..($lines.Count - 1)] | Where-Object { $_ -match '\S' })
    try { return @($csv | ConvertFrom-Csv) }
    catch { return @() }
}


function ConvertFrom-AdfaRepadminDelta {
    <#
    .SYNOPSIS
        Pure conversion of a repadmin "largest delta" token into minutes.
    .DESCRIPTION
        repadmin renders the delta as colon-joined unit tokens - "04h:02m:16s", "15m:30s",
        "3d.04h:02m:16s" - and as "(unknown)" for a link that has never succeeded. Returns
        $null for anything it cannot read, including (unknown), so an unreadable delta is never
        silently treated as zero.
    .OUTPUTS
        [System.Nullable[int]] Minutes, or $null.
    #>
    [CmdletBinding()]
    [OutputType([System.Nullable[int]])]
    param([AllowNull()][AllowEmptyString()][string]$Delta = '')
    if ([string]::IsNullOrWhiteSpace($Delta)) { return $null }
    $t = $Delta.Trim()
    if ($t -match '^\(') { return $null }              # (unknown), (never), ...
    # ">60 days" and friends: take the number and treat the unit as days.
    if ($t -match '^>\s*(\d+)\s*d') { return ([int]$Matches[1] * 1440) }
    $total = 0
    $matched = $false
    foreach ($m in [regex]::Matches($t, '(\d+)\s*([dhms])')) {
        $n = [int]$m.Groups[1].Value
        switch ($m.Groups[2].Value) {
            'd' { $total += $n * 1440; $matched = $true }
            'h' { $total += $n * 60; $matched = $true }
            'm' { $total += $n; $matched = $true }
            's' { $matched = $true }   # sub-minute: contributes nothing but proves a parse
        }
    }
    if (-not $matched) { return $null }
    return [int]$total
}

function ConvertFrom-AdfaReplsummary {
    <#
    .SYNOPSIS
        Pure parser for 'repadmin /replsummary' output.
    .DESCRIPTION
        The output is two tables - one keyed by source DSA, one by destination - each introduced
        by a header carrying "largest delta" and "fails/total":

            Source DSA          largest delta    fails/total %%   error
             DC1                      15m:30s     0 /  10    0
             DC2                    (unknown)     5 /   5  100  (8524) The DSA operation is unable...

        Format per https://learn.microsoft.com/troubleshoot/windows-server/active-directory/replication-error-8418
        (read 2026-09-22). This is localised, version-dependent console text with no CSV option,
        so the parser is deliberately defensive and its caller treats "parsed nothing" as
        Not Assessed rather than as a clean result.
    .OUTPUTS
        [pscustomobject[]] Direction (Source|Destination), Dsa, Delta, DeltaMinutes, Fails, Total, ErrorText
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([AllowEmptyString()][string]$Text = '')
    if ([string]::IsNullOrWhiteSpace($Text)) { return @() }
    $out = @()
    $direction = ''
    foreach ($line in @($Text -split "`r?`n")) {
        if ($line -match '(?i)largest\s+delta' -and $line -match '(?i)fails\s*/\s*total') {
            if ($line -match '(?i)source\s+DSA') { $direction = 'Source' }
            elseif ($line -match '(?i)destination\s+DSA') { $direction = 'Destination' }
            else { $direction = '' }
            continue
        }
        if (-not $direction) { continue }
        # name  delta  fails / total  pct  [ (code) text ]
        $m = [regex]::Match($line, '^\s+(\S+)\s+(\S+)\s+(\d+)\s*/\s*(\d+)\s+(\d+)\s*(.*)$')
        if (-not $m.Success) { continue }
        $delta = $m.Groups[2].Value
        $out += [pscustomobject]@{
            Direction    = $direction
            Dsa          = $m.Groups[1].Value
            Delta        = $delta
            DeltaMinutes = (ConvertFrom-AdfaRepadminDelta -Delta $delta)
            Fails        = [int]$m.Groups[3].Value
            Total        = [int]$m.Groups[4].Value
            ErrorText    = $m.Groups[6].Value.Trim()
        }
    }
    # Plain return: `return @()` would hand the caller one element that IS the empty array.
    return @($out)
}

function Get-AdfaReplsummaryVerdict {
    <#
    .SYNOPSIS
        Pure verdict on one parsed /replsummary row.
    .DESCRIPTION
        Two independent signals. Failures are unambiguous. The delta is the convergence lag, and
        an UNREADABLE delta is not zero: "(unknown)" means that DSA has no successful replication
        to measure from, which is worse than a large number, not better.
    .OUTPUTS
        [pscustomobject] Status, Detail
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Direction,
        [Parameter(Mandatory)][string]$Dsa,
        [AllowNull()][AllowEmptyString()][string]$Delta = '',
        [AllowNull()][Nullable[int]]$DeltaMinutes,
        [int]$Fails = 0,
        [int]$Total = 0,
        [string]$ErrorText = '',
        [int]$WarnHours = 24,
        [int]$FailHours = 168
    )
    $side = 'as a replication source'
    if ($Direction -eq 'Destination') { $side = 'as a replication destination' }
    $errSuffix = ''
    if (-not [string]::IsNullOrWhiteSpace($ErrorText)) { $errSuffix = (" Last error: {0}" -f $ErrorText) }

    if ($Fails -gt 0 -and $Fails -ge $Total -and $Total -gt 0) {
        return [pscustomobject]@{
            Status = $script:Status.Fail
            Detail = ("{0} fails EVERY replication attempt {1} ({2} of {3}). Nothing is flowing in that direction at all.{4}" -f $Dsa, $side, $Fails, $Total, $errSuffix)
        }
    }
    if ($Fails -gt 0) {
        return [pscustomobject]@{
            Status = $script:Status.Fail
            Detail = ("{0} fails {1} of {2} replication attempts {3}.{4}" -f $Dsa, $Fails, $Total, $side, $errSuffix)
        }
    }
    # No failures. The delta decides, and an unreadable one is not a pass.
    if ($null -eq $DeltaMinutes) {
        return [pscustomobject]@{
            Status = $script:Status.NotAssessed
            Detail = ("{0} reports no failures {1}, but its largest delta reads '{2}', so there is no successful replication to measure from and convergence cannot be confirmed. This is NOT a clean result - a DSA that has never replicated successfully reports no failures too.{3}" -f $Dsa, $side, $Delta, $errSuffix)
        }
    }
    $hours = [math]::Round($DeltaMinutes / 60.0, 1)
    $lagNote = (" Thresholds are this tool's, not Microsoft's: intra-site replication is notification-driven and the default inter-site schedule is 180 minutes, so {0}h is outside any normal schedule. The hard limit is tombstone lifetime - past that, reconnecting a stale DC introduces lingering objects instead of converging." -f $WarnHours)
    if ($DeltaMinutes -ge ($FailHours * 60)) {
        return [pscustomobject]@{
            Status = $script:Status.Fail
            Detail = ("{0} reports no failures {1}, but its largest delta is {2} ({3}h) - it has stopped converging rather than lagged. A link with no errors and an old last success is the silent case: nothing reports an error because nothing is being attempted.{4}{5}" -f $Dsa, $side, $Delta, $hours, $lagNote, $errSuffix)
        }
    }
    if ($DeltaMinutes -ge ($WarnHours * 60)) {
        return [pscustomobject]@{
            Status = $script:Status.Warning
            Detail = ("{0} reports no failures {1}, but its largest delta is {2} ({3}h).{4}{5}" -f $Dsa, $side, $Delta, $hours, $lagNote, $errSuffix)
        }
    }
    return [pscustomobject]@{
        Status = $script:Status.Pass
        Detail = ("{0}: no failures {1}, largest delta {2}." -f $Dsa, $side, $Delta)
    }
}

function Get-AdfaReplsummaryHealth {
    <#
    .SYNOPSIS
        Runs and parses 'repadmin /replsummary' into findings.
    .DESCRIPTION
        Previously this output was written to a raw file under -IncludeRepadmin and never read.
        It is the only place the tool sees a per-DSA convergence delta rolled up across every
        partition, in both directions.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([int]$TimeoutSeconds = 300, [int]$Retries = 2, [int]$RetryDelaySeconds = 2)
    if (-not (Test-CommandAvailable -Name 'repadmin.exe')) {
        return @(New-Finding -Area 'Replication' -Item 'repadmin /replsummary' -Status $script:Status.NotAssessed `
                -Detail 'repadmin.exe not available on this host, so the replication summary could not be collected.')
    }
    $r = Invoke-ExternalCommand -FilePath 'repadmin.exe' -Arguments '/replsummary' `
        -TimeoutSeconds $TimeoutSeconds -Retries $Retries -RetryDelaySeconds $RetryDelaySeconds
    $rowsIn = @(ConvertFrom-AdfaReplsummary -Text $r.StdOut)
    if ($rowsIn.Count -eq 0) {
        # Fail-closed: unparsed console output is not evidence of health. This is localised,
        # version-dependent text, so a parse miss is expected to happen eventually and must not
        # be mistaken for "no problems found".
        return @(New-Finding -Area 'Replication' -Item 'repadmin /replsummary' -Status $script:Status.NotAssessed `
                -Detail ("Could not parse 'repadmin /replsummary' output, so replication convergence is unassessed - not clean. {0}" -f `
                    $(if ($r.Error) { $r.Error } else { 'Re-run with -IncludeRepadmin and read raw\repadmin_replsummary.txt.' })))
    }
    $rows = @()
    foreach ($row in $rowsIn) {
        $v = Get-AdfaReplsummaryVerdict -Direction $row.Direction -Dsa $row.Dsa -Delta $row.Delta `
            -DeltaMinutes $row.DeltaMinutes -Fails $row.Fails -Total $row.Total -ErrorText $row.ErrorText `
            -WarnHours ([int]$script:Config.ReplLagWarnHours) -FailHours ([int]$script:Config.ReplLagFailHours)
        $rows += New-Finding -Area 'Replication' -Item ("replsummary {0}: {1}" -f $row.Direction, $row.Dsa) `
            -Status $v.Status -Detail $v.Detail
    }
    return @($rows)
}

function Get-AdfaReplicationLagVerdict {
    <#
    .SYNOPSIS
        Pure verdict on how long ago a replication link last succeeded.
    .DESCRIPTION
        Closes a gap in the /showrepl cross-check, which judged links on failure COUNT alone: a
        link with zero failures and a last success weeks old was reported as clean. That is the
        silent stall - a disabled connection object, a KCC problem, or a partner that simply
        stopped being contacted - where nothing errors because nothing is attempted.

        An unparseable or absent last-success time is NOT treated as recent.
    .OUTPUTS
        [pscustomobject] Status, Detail
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Destination,
        [Parameter(Mandatory)][string]$Source,
        [string]$NamingContext = '',
        [AllowNull()][AllowEmptyString()][string]$LastSuccess = '',
        [AllowNull()][Nullable[datetime]]$Now,
        [int]$WarnHours = 24,
        [int]$FailHours = 168
    )
    $asOf = (Get-Date)
    if ($null -ne $Now) { $asOf = $Now }
    $link = ("{0} <- {1}" -f $Destination, $Source)
    if (-not [string]::IsNullOrWhiteSpace($NamingContext)) { $link = ("{0} on {1}" -f $link, $NamingContext) }

    $parsed = $null
    if (-not [string]::IsNullOrWhiteSpace($LastSuccess)) {
        try { $parsed = [datetime]::Parse($LastSuccess, [Globalization.CultureInfo]::InvariantCulture) }
        catch {
            try { $parsed = [datetime]$LastSuccess }
            catch { $parsed = $null }
        }
    }
    if ($null -eq $parsed) {
        return [pscustomobject]@{
            Status = $script:Status.NotAssessed
            Detail = ("{0}: no readable last-success time ('{1}'), so convergence cannot be confirmed. A link that has never succeeded reports zero failures too, so this is not a clean result." -f $link, $LastSuccess)
        }
    }
    $ageHours = [math]::Round((New-TimeSpan -Start $parsed -End $asOf).TotalHours, 1)
    if ($ageHours -lt 0) {
        return [pscustomobject]@{
            Status = $script:Status.NotAssessed
            Detail = ("{0}: last success is timestamped in the future ({1:yyyy-MM-dd HH:mm}), which means clock skew between the DCs. Fix time sync before drawing conclusions from any replication timestamp." -f $link, $parsed)
        }
    }
    if ($ageHours -ge $FailHours) {
        return [pscustomobject]@{
            Status = $script:Status.Fail
            Detail = ("{0}: last successful replication {1:yyyy-MM-dd HH:mm} - {2}h ago - with no failures reported. Nothing is erroring because nothing is being attempted: check the connection object is enabled, the site link schedule, and KCC health. Approaching tombstone lifetime, reconnecting this link introduces lingering objects rather than converging." -f $link, $parsed, $ageHours)
        }
    }
    if ($ageHours -ge $WarnHours) {
        return [pscustomobject]@{
            Status = $script:Status.Warning
            Detail = ("{0}: last successful replication {1:yyyy-MM-dd HH:mm} - {2}h ago - with no failures reported. Outside any normal schedule (the inter-site default is 180 minutes), so confirm this link is still being attempted." -f $link, $parsed, $ageHours)
        }
    }
    return [pscustomobject]@{
        Status = $script:Status.Pass
        Detail = ("{0}: last successful replication {1:yyyy-MM-dd HH:mm} ({2}h ago)." -f $link, $parsed, $ageHours)
    }
}

function Get-AdfaRepadminReplication {
    <#
    .SYNOPSIS
        Cross-checks replication with 'repadmin /showrepl * /csv', which fans out from
        this host and reports links the Get-ADReplication* cmdlets miss when a partner
        is unreachable (the cmdlets query each DC's own view; repadmin reports the
        failing edge from the surviving side). One finding per failing link; a Pass
        summary when every reported link is clean.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([int]$TimeoutSeconds = 300, [int]$Retries = 2, [int]$RetryDelaySeconds = 2)
    if (-not (Test-CommandAvailable -Name 'repadmin.exe')) {
        return @(New-Finding -Area 'Replication' -Item 'repadmin cross-check' -Status $script:Status.NotAssessed -Detail 'repadmin.exe not available on this host.')
    }
    $r = Invoke-ExternalCommand -FilePath 'repadmin.exe' -Arguments '/showrepl * /csv' `
        -TimeoutSeconds $TimeoutSeconds -Retries $Retries -RetryDelaySeconds $RetryDelaySeconds
    $links = @(ConvertFrom-AdfaShowreplCsv -Text $r.StdOut)
    if (@($links).Count -eq 0) {
        return @(New-Finding -Area 'Replication' -Item 'repadmin cross-check' -Status $script:Status.NotAssessed -Detail ("Could not parse 'repadmin /showrepl * /csv' output. {0}" -f $(if ($r.Error) { $r.Error } else { 'See raw capture (-IncludeRepadmin) for the unparsed output.' })))
    }
    $rows = @()
    $failing = 0
    foreach ($l in $links) {
        $names = $l.PSObject.Properties.Name
        $failures = 0
        if ($names -contains 'Number of Failures' -and "$($l.'Number of Failures')" -match '^\d+$') { $failures = [int]$l.'Number of Failures' }
        if ($failures -gt 0) {
            $failing++
            $src = ''; $dst = ''; $nc = ''; $lastOk = ''; $status = ''
            if ($names -contains 'Source DSA') { $src = [string]$l.'Source DSA' }
            if ($names -contains 'Destination DSA') { $dst = [string]$l.'Destination DSA' }
            if ($names -contains 'Naming Context') { $nc = [string]$l.'Naming Context' }
            if ($names -contains 'Last Success Time') { $lastOk = [string]$l.'Last Success Time' }
            if ($names -contains 'Last Failure Status') { $status = [string]$l.'Last Failure Status' }
            $rows += New-Finding -Area 'Replication' -Item ("repadmin: {0} <- {1}" -f $dst, $src) -Status $script:Status.Fail `
                -Detail ("{0} consecutive failure(s) on {1}; last failure status {2}; last success {3}." -f $failures, $nc, $status, $(if ($lastOk) { $lastOk } else { 'unknown' }))
        }
    }
    # Convergence lag on EVERY link, including the ones reporting no failures. Judging on failure
    # count alone was the gap: a link with zero failures and a last success weeks old was reported
    # as clean, which is exactly the silent stall - a disabled connection object, a KCC problem, or
    # a partner that stopped being contacted - where nothing errors because nothing is attempted.
    $lagging = 0
    $lagUnknown = 0
    foreach ($l in $links) {
        $names = $l.PSObject.Properties.Name
        $failures = 0
        if ($names -contains 'Number of Failures' -and "$($l.'Number of Failures')" -match '^\d+$') { $failures = [int]$l.'Number of Failures' }
        if ($failures -gt 0) { continue }   # already reported above, with its error status
        $src = ''; $dst = ''; $nc = ''; $lastOk = ''
        if ($names -contains 'Source DSA') { $src = [string]$l.'Source DSA' }
        if ($names -contains 'Destination DSA') { $dst = [string]$l.'Destination DSA' }
        if ($names -contains 'Naming Context') { $nc = [string]$l.'Naming Context' }
        if ($names -contains 'Last Success Time') { $lastOk = [string]$l.'Last Success Time' }
        $v = Get-AdfaReplicationLagVerdict -Destination $dst -Source $src -NamingContext $nc -LastSuccess $lastOk `
            -WarnHours ([int]$script:Config.ReplLagWarnHours) -FailHours ([int]$script:Config.ReplLagFailHours)
        if ($v.Status -eq $script:Status.Pass) { continue }   # a converging link needs no row of its own
        if ($v.Status -eq $script:Status.NotAssessed) { $lagUnknown++ } else { $lagging++ }
        $rows += New-Finding -Area 'Replication' -Item ("repadmin lag: {0} <- {1}" -f $dst, $src) -Status $v.Status -Detail $v.Detail
    }

    if ($failing -eq 0 -and $lagging -eq 0 -and $lagUnknown -eq 0) {
        $rows += New-Finding -Area 'Replication' -Item 'repadmin cross-check' -Status $script:Status.Pass `
            -Detail ("repadmin /showrepl reports {0} link(s), all with zero failures AND a last success inside {1}h." -f @($links).Count, [int]$script:Config.ReplLagWarnHours)
    }
    else {
        $parts = @()
        if ($failing -gt 0) { $parts += ("{0} with failures" -f $failing) }
        if ($lagging -gt 0) { $parts += ("{0} not converging despite no failures" -f $lagging) }
        if ($lagUnknown -gt 0) { $parts += ("{0} with no readable last-success time" -f $lagUnknown) }
        $st = $script:Status.Fail
        if ($failing -eq 0 -and $lagging -eq 0) { $st = $script:Status.NotAssessed }
        $rows += New-Finding -Area 'Replication' -Item 'repadmin cross-check summary' -Status $st `
            -Detail ("Of {0} replication link(s): {1}." -f @($links).Count, ($parts -join '; '))
    }
    return @($rows)
}

function Get-AdfaLatestBackupDate {
    <#
    .SYNOPSIS
        Pure parser: extracts the most recent date from 'repadmin /showbackup' output.
        Returns $null when no date can be found - the caller reports Not Assessed, never
        a fabricated age.
    .OUTPUTS
        [nullable[datetime]]
    #>
    [CmdletBinding()]
    [OutputType([nullable[datetime]])]
    param([AllowEmptyString()][string]$Text = '')
    $best = $null
    foreach ($m in [regex]::Matches($Text, '\d{4}-\d{2}-\d{2} \d{2}:\d{2}(:\d{2})?')) {
        $d = [datetime]::MinValue
        if ([datetime]::TryParseExact($m.Value, [string[]]@('yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm'), [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$d)) {
            if ($null -eq $best -or $d -gt $best) { $best = $d }
        }
    }
    foreach ($m in [regex]::Matches($Text, '\d{1,2}/\d{1,2}/\d{4}( \d{1,2}:\d{2}(:\d{2})?)?')) {
        $d = [datetime]::MinValue
        if ([datetime]::TryParse($m.Value, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$d)) {
            if ($null -eq $best -or $d -gt $best) { $best = $d }
        }
    }
    return $best
}

function Get-AdfaBackupStatus {
    <#
    .SYNOPSIS
        Last directory-partition backup time PER DC via 'repadmin /showbackup <dc>'.
        In a restore-from-backup recovery this tells you which DCs were restored and
        when - correlate with the machine-account password ages in DcSecureChannel.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # DC rows (HostName, Scope) or plain host names (PORT-PLAN C2e).
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [int]$TimeoutSeconds = 90,
        [int]$Retries = 2,
        [int]$RetryDelaySeconds = 2,
        [int]$MaxAgeDays = 30,
        [int]$RpcPortTimeoutMs = 1200,
        # Domains whose DC enumeration threw (Domain, Error), and the domains of the run.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    if (-not (Test-CommandAvailable -Name 'repadmin.exe')) {
        return @(New-Finding -Area 'Backup' -Item 'Directory backup status' -Status $script:Status.NotAssessed -Detail 'repadmin.exe not available on this host.')
    }
    $targets = @($DomainControllers | Where-Object { $null -ne $_ -and -not ($_ -is [string] -and [string]::IsNullOrWhiteSpace($_)) })
    $rows = @(Get-AdfaDcPopulationRow -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Area 'Backup' `
            -Label 'Directory backup' -NothingRead 'No backup time of its DCs was read.')
    if (@($targets).Count -eq 0) {
        # No DC list - fall back to the local view.
        $r = Invoke-ExternalCommand -FilePath 'repadmin.exe' -Arguments '/showbackup' -TimeoutSeconds $TimeoutSeconds -Retries $Retries -RetryDelaySeconds $RetryDelaySeconds
        $latest = Get-AdfaLatestBackupDate -Text $r.StdOut
        if ($null -eq $latest) {
            $rows += New-Finding -Area 'Backup' -Item 'Directory backup (local DC)' -Status $script:Status.NotAssessed -Detail 'Could not parse repadmin /showbackup output.'
        }
        else {
            $age = ((Get-Date) - $latest).TotalDays
            $status = $script:Status.Pass
            if ($age -gt $MaxAgeDays) { $status = $script:Status.Warning }
            $rows += New-Finding -Area 'Backup' -Item 'Directory backup (local DC)' -Status $status -Detail ("Latest partition backup {0:yyyy-MM-dd HH:mm} ({1:N0} day(s) ago)." -f $latest, $age)
        }
        return @($rows)
    }
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-Finding -Scope $scope -Area 'Backup' -Item 'Directory backup: (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so repadmin /showbackup had nothing to ask.'
            continue
        }
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135) -TimeoutMs $RpcPortTimeoutMs
        if ($gate.Cause) {
            $rows += New-Finding -Scope $scope -Area 'Backup' -Item ("Directory backup: {0}" -f $dc) -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'repadmin /showbackup was not run against it')
            continue
        }
        if (-not $gate.Open[135]) {
            $rows += New-Finding -Scope $scope -Area 'Backup' -Item ("Directory backup: {0}" -f $dc) -Status $script:Status.NotAssessed -Detail 'DC not reachable (RPC/135) - run repadmin /showbackup locally on it.'
            continue
        }
        $r = Invoke-ExternalCommand -FilePath 'repadmin.exe' -Arguments ("/showbackup {0}" -f $dc) -TimeoutSeconds $TimeoutSeconds -Retries $Retries -RetryDelaySeconds $RetryDelaySeconds
        $latest = Get-AdfaLatestBackupDate -Text $r.StdOut
        if ($null -eq $latest) {
            $rows += New-Finding -Scope $scope -Area 'Backup' -Item ("Directory backup: {0}" -f $dc) -Status $script:Status.NotAssessed -Detail ("Could not parse repadmin /showbackup output for this DC.{0}" -f $(if ($r.Error) { ' ' + $r.Error } else { '' }))
        }
        else {
            $age = ((Get-Date) - $latest).TotalDays
            $status = $script:Status.Pass
            if ($age -gt $MaxAgeDays) { $status = $script:Status.Warning }
            $rows += New-Finding -Scope $scope -Area 'Backup' -Item ("Directory backup: {0}" -f $dc) -Status $status -Detail ("Latest partition backup {0:yyyy-MM-dd HH:mm} ({1:N0} day(s) ago). A very old value on a restored DC dates the backup it came from." -f $latest, $age)
        }
    }
    return @($rows)
}

function Get-AdfaLingeringObjectScan {
    <#
    .SYNOPSIS
        Proactive lingering-object enumeration using
        'repadmin /removelingeringobjects <dc> <reference-dsa-guid> <NC> /advisory_mode'.
        Advisory mode makes NO directory changes - it only compares each DC against the
        reference DC (the domain's PDC emulator) and logs what WOULD be removed. This is
        the check that finds lingering objects BEFORE they block replication with event
        1988, instead of after. Opt-in via -IncludeLingeringObjectScan because it writes
        events (1938/1942/1946) to the target DCs' Directory Service logs.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [int]$TimeoutSeconds = 300,
        [int]$RpcPortTimeoutMs = 1200
    )
    $rows = @()
    if (-not (Test-CommandAvailable -Name 'repadmin.exe')) {
        return @(New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item 'Advisory-mode scan' -Status $script:Status.NotAssessed -Detail 'repadmin.exe not available on this host.')
    }
    $p = @{} + $AdParams; $p.Server = $DomainName
    $domainNc = ''; $refDc = ''; $dcs = @()
    try {
        $dom = Get-ADDomain @p
        $domainNc = [string]$dom.DistinguishedName
        $refDc = [string]$dom.PDCEmulator
        $dcs = @(Get-ADDomainController -Filter * @p | Select-Object -ExpandProperty HostName)
    }
    catch {
        return @(New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item 'Advisory-mode scan' -Status $script:Status.NotAssessed -Detail $_.Exception.Message)
    }
    $refGuid = ''
    $refGuidError = ''
    try {
        $inv = @(Get-AdfaDsaInventory -AdParams $AdParams)
        $refNorm = $refDc.ToLowerInvariant().TrimEnd('.')
        foreach ($d in $inv) {
            if ($d.DnsHostName -and $d.DnsHostName.ToLowerInvariant().TrimEnd('.') -eq $refNorm) { $refGuid = $d.DsaGuid; break }
        }
    }
    catch {
        # The verdict below was already fail-closed, but the cause was discarded - so
        # "the DSA inventory threw" and "the reference DC simply was not in it" read alike.
        $refGuidError = $_.Exception.Message
    }
    if (-not $refGuid) {
        $why = ''
        if ($refGuidError) { $why = (" DSA inventory failed: {0}" -f $refGuidError) }
        else { $why = ' The DSA inventory was readable but contained no entry matching that host name.' }
        return @(New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item 'Advisory-mode scan' -Status $script:Status.NotAssessed -Detail ("Could not resolve the DSA GUID of the reference DC ({0}).{1}" -f $refDc, $why))
    }

    foreach ($dc in $dcs) {
        if ($dc.ToLowerInvariant().TrimEnd('.') -eq $refDc.ToLowerInvariant().TrimEnd('.')) { continue }
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135) -TimeoutMs $RpcPortTimeoutMs
        if ($gate.Cause) {
            $rows += New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item ("Advisory scan: {0}" -f $dc) -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'the advisory scan was not run against it')
            continue
        }
        if (-not $gate.Open[135]) {
            $rows += New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item ("Advisory scan: {0}" -f $dc) -Status $script:Status.NotAssessed -Detail 'DC not reachable (RPC/135).'
            continue
        }
        $r = Invoke-ExternalCommand -FilePath 'repadmin.exe' `
            -Arguments ('/removelingeringobjects {0} {1} "{2}" /advisory_mode' -f $dc, $refGuid, $domainNc) `
            -TimeoutSeconds $TimeoutSeconds -Retries 1
        $out = [string]$r.StdOut
        $count = -1
        if ($out -match '(?i)(\d+)\s+lingering object') { $count = [int]$Matches[1] }
        else {
            $perLine = ([regex]::Matches($out, '(?i)^\s*lingering obj', [System.Text.RegularExpressions.RegexOptions]::Multiline)).Count
            if ($perLine -gt 0) { $count = $perLine }
            elseif ($r.Success) { $count = 0 }
        }
        if ($count -gt 0) {
            $rows += New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item ("Advisory scan: {0}" -f $dc) -Status $script:Status.Fail -Detail ("{0} lingering object(s) found relative to {1} on {2}. Directory Service events 1946 on {3} list each object." -f $count, $refDc, $domainNc, $dc)
        }
        elseif ($count -eq 0) {
            $rows += New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item ("Advisory scan: {0}" -f $dc) -Status $script:Status.Pass -Detail ("No lingering objects relative to {0} on {1}." -f $refDc, $domainNc)
        }
        else {
            $excerpt = (($out -split "`r?`n") | Where-Object { $_ -match '\S' } | Select-Object -First 3) -join ' | '
            $rows += New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item ("Advisory scan: {0}" -f $dc) -Status $script:Status.NotAssessed -Detail ("Inconclusive output: {0}" -f $(if ($excerpt) { $excerpt } else { $r.Error }))
        }
    }
    if (@($rows).Count -eq 0) {
        $rows += New-Finding -Scope $DomainName -Area 'LingeringObjects' -Item 'Advisory-mode scan' -Status $script:Status.Info -Detail ("Only one DC in {0} - nothing to compare against the reference." -f $DomainName)
    }
    return @($rows)
}

function Get-AdfaTimeSync {
    <#
    .SYNOPSIS
        Local w32time source/status (run on a DC for domain-relevant results).
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([int]$TimeoutSeconds = 60)
    if (-not (Test-CommandAvailable -Name 'w32tm.exe')) {
        return @(New-Finding -Area 'TimeSync' -Item 'w32time' -Status $script:Status.NotAssessed -Detail 'w32tm.exe not available on this host.')
    }
    $rows = @()
    $src = Invoke-ExternalCommand -FilePath 'w32tm.exe' -Arguments '/query /source' -TimeoutSeconds $TimeoutSeconds -Retries 1 -RetryDelaySeconds 1
    $source = ($src.StdOut -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -First 1)
    $status = $script:Status.Info
    if ($source -match 'Local CMOS Clock|Free-running') { $status = $script:Status.Warning }
    $rows += New-Finding -Area 'TimeSync' -Item 'Time source' -Status $status -Detail ("Source: {0}" -f ("$source".Trim()))
    return @($rows)
}

function Get-AdfaDnsDepth {
    <#
    .SYNOPSIS
        DNS depth: critical SRV records resolvable, root hints (the secure dynamic updates check
        moved to DNS Health in v1.30.0, PORT-PLAN C13; one Info row says so).
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName, [string[]]$DomainControllers, [int]$RpcPortTimeoutMs = 1200)
    $rows = @()
    # SRV record resolution (needs Resolve-DnsName; degrade if absent)
    if (Test-CommandAvailable -Name 'Resolve-DnsName') {
        foreach ($rec in @("_ldap._tcp.dc._msdcs.$DomainName", "_kerberos._tcp.$DomainName")) {
            try {
                $ans = @(Resolve-DnsName -Name $rec -Type SRV -ErrorAction Stop)
                $rows += New-Finding -Scope $DomainName -Area 'DNSDepth' -Item ("SRV {0}" -f $rec) -Status $(if ($ans.Count -gt 0) { $script:Status.Pass } else { $script:Status.Fail }) -Detail ("{0} record(s)" -f $ans.Count)
            }
            catch { $rows += New-Finding -Scope $DomainName -Area 'DNSDepth' -Item ("SRV {0}" -f $rec) -Status $script:Status.Fail -Detail $_.Exception.Message }
        }
    }
    else {
        $rows += New-Finding -Scope $DomainName -Area 'DNSDepth' -Item 'SRV record resolution' -Status $script:Status.NotAssessed -Detail 'Resolve-DnsName not available on this host.'
    }
    # Secure dynamic updates: retired here by PORT-PLAN C13. This row read the domain zone on the
    # FIRST DC only and graded anything but 'Secure' a Warning; DNS Health now grades every primary
    # zone on every DNS server of each domain ("Zone dynamic update" rows), so a zone is never graded
    # twice with two different rules. The row stays, as Info, so a reader of an older report finds
    # where the check went.
    $rows += New-Finding -Scope $DomainName -Area 'DNSDepth' -Item 'Secure dynamic updates' -Status $script:Status.Info `
        -Detail 'Graded in the DNS Health section since v1.30.0, per zone and over every DNS server of the domain, in its "Zone dynamic update" rows; not read here.'
    return @($rows)
}

function Get-AdfaRedundancy {
    <#
    .SYNOPSIS
        Availability: DC count / FSMO concentration, GPO central store, duplicate SPNs.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName, [hashtable]$AdParams = @{})
    $rows = @()
    $srv = @{} + $AdParams; $srv.Server = $DomainName
    try {
        $dcs = @(Get-ADDomainController -Filter * -Server $DomainName)
        $rows += New-Finding -Scope $DomainName -Area 'Redundancy' -Item 'Domain controller redundancy' -Status $(if ($dcs.Count -ge 2) { $script:Status.Pass } else { $script:Status.Warning }) -Detail ("{0} DC(s) in domain (>=2 recommended for resilience)." -f $dcs.Count)
    }
    catch { $rows += New-Finding -Scope $DomainName -Area 'Redundancy' -Item 'Domain controller redundancy' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }

    # GPO central store (PolicyDefinitions in SYSVOL)
    try {
        $cs = "\\{0}\SYSVOL\{0}\Policies\PolicyDefinitions" -f $DomainName
        $exists = Test-Path -LiteralPath $cs -ErrorAction SilentlyContinue
        $rows += New-Finding -Scope $DomainName -Area 'Redundancy' -Item 'GPO central store' -Status $(if ($exists) { $script:Status.Pass } else { $script:Status.Warning }) -Detail ("PolicyDefinitions {0} in SYSVOL." -f $(if ($exists) { 'present' } else { 'not found' }))
    }
    catch { $rows += New-Finding -Scope $DomainName -Area 'Redundancy' -Item 'GPO central store' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }

    # Duplicate SPNs
    try {
        $objs = @(Get-ADObject -LDAPFilter '(servicePrincipalName=*)' -Properties servicePrincipalName, samAccountName @srv -ErrorAction Stop)
        $dupes = Find-AdfaDuplicateSpn -Objects $objs
        $rows += New-Finding -Scope $DomainName -Area 'Redundancy' -Item 'Duplicate SPNs' -Status $(if (@($dupes).Count -eq 0) { $script:Status.Pass } else { $script:Status.Fail }) -Detail ("{0} duplicated SPN(s){1}" -f @($dupes).Count, $(if (@($dupes).Count -gt 0) { ': ' + ((@($dupes | Select-Object -First 8).Spn) -join ', ') } else { '.' }))
    }
    catch { $rows += New-Finding -Scope $DomainName -Area 'Redundancy' -Item 'Duplicate SPNs' -Status $script:Status.NotAssessed -Detail $_.Exception.Message }

    return @($rows)
}

# ===========================================================================
# region Exchange Server SE readiness (AD prerequisites only)
# ===========================================================================

function Test-AdfaOsSupported {
    <#
    .SYNOPSIS
        Pure match of a DC's OperatingSystem string against the supported-OS table.
    .DESCRIPTION
        Returns the matching table Label, or '' when nothing matches. Kept separate so the
        patterns are testable in isolation - the 2012 R2 / 2012 distinction in particular,
        where 2012 R2 is supported and plain 2012 is not, and a loosened pattern would
        silently pass an unsupported DC.
    .OUTPUTS
        [string] The supported-OS label, or '' when unsupported.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyString()][string]$OperatingSystem,
        [AllowNull()][AllowEmptyCollection()]$SupportedOs = @()
    )
    if ([string]::IsNullOrWhiteSpace($OperatingSystem)) { return '' }
    foreach ($entry in @($SupportedOs)) {
        if ($null -eq $entry) { continue }
        $pattern = ''
        if ($entry -is [hashtable]) { $pattern = [string]$entry['Pattern'] }
        else {
            $prop = $entry.PSObject.Properties['Pattern']   # $null when absent - StrictMode-safe
            if ($null -ne $prop) { $pattern = [string]$prop.Value }
        }
        if ([string]::IsNullOrWhiteSpace($pattern)) { continue }
        if ($OperatingSystem -match $pattern) {
            if ($entry -is [hashtable]) { return [string]$entry['Label'] }
            return [string]$entry.PSObject.Properties['Label'].Value
        }
    }
    return ''
}

function Merge-AdfaExchangeSeConfig {
    <#
    .SYNOPSIS
        Pure merge of an override table over the built-in Exchange SE prerequisite table.
    .DESCRIPTION
        Only the keys present in the override are replaced, so a file that names one key does
        not blank the rest. Separated from the file read so the merge rules are testable
        without a filesystem.

        An override MUST NOT be able to empty a gate: a SupportedForestModes or
        SupportedDomainControllerOs of zero entries would make every value unsupported (or,
        worse in a future refactor, everything vacuously fine), so an empty collection is
        rejected rather than honoured. Provenance is rewritten to name the override, because a
        finding that cites Microsoft Learn must not do so when the values came from elsewhere.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }

    $names = @()
    if ($Override -is [hashtable]) { $names = @($Override.Keys) }
    else { $names = @($Override.PSObject.Properties.Name) }

    foreach ($k in $names) {
        $value = $null
        if ($Override -is [hashtable]) { $value = $Override[$k] }
        else { $value = $Override.PSObject.Properties[$k].Value }
        if ($null -eq $value) { continue }
        if (($k -eq 'SupportedForestModes' -or $k -eq 'SupportedDomainControllerOs' -or $k -eq 'ForestFunctionalLevels') -and @($value).Count -eq 0) {
            throw ("Exchange SE config override sets '{0}' to an empty list. An empty gate cannot be honoured - remove the key to keep the built-in value." -f $k)
        }
        $merged[$k] = $value
    }
    # The verdict is taken from the numeric level, so every supported mode NAME must resolve to
    # a level in the table. A name that does not would silently drop out of the supported set
    # and turn a supported forest into a Fail, so it is refused here instead.
    $knownModes = @(Get-AdfaForestLevelTable -SeConfig $merged | ForEach-Object { $_.Mode })
    foreach ($mode in @($merged['SupportedForestModes'])) {
        if ($knownModes -notcontains [string]$mode) {
            # Says where each half came from. The name may be the BUILT-IN one and the table the
            # overridden one: an override ForestFunctionalLevels replaces the whole table, it is
            # not merged row by row, so an override listing only a new level drops the rest.
            throw ("Exchange SE config: SupportedForestModes contains '{0}', which has no entry in the ForestFunctionalLevels table in force ({1}). An override that supplies ForestFunctionalLevels replaces the whole built-in table, so it must list every level the supported modes need. Add '{0}' there with its msDS-Behavior-Version value, or correct the name." -f [string]$mode, ($knownModes -join ', '))
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) {
        $merged['SourceUrl'] = $OverrideSource
        $merged['ReadDate'] = (Get-Date).ToString('yyyy-MM-dd')
    }
    return $merged
}

function Import-AdfaExchangeSeConfig {
    <#
    .SYNOPSIS
        Loads an Exchange SE prerequisite override from JSON and merges it over the built-in table.
    .DESCRIPTION
        Thin wrapper over Merge-AdfaExchangeSeConfig. A missing, unreadable or malformed file
        throws: silently judging a forest against the wrong table is worse than stopping.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [Parameter(Mandatory)][string]$Path
    )
    if (-not (Test-Path -LiteralPath $Path)) {
        throw ("Exchange SE config not found: {0}" -f $Path)
    }
    $raw = Get-Content -LiteralPath $Path -Raw -ErrorAction Stop
    if ([string]::IsNullOrWhiteSpace($raw)) {
        throw ("Exchange SE config is empty: {0}" -f $Path)
    }
    $obj = $null
    try { $obj = $raw | ConvertFrom-Json -ErrorAction Stop }
    catch { throw ("Exchange SE config is not valid JSON ({0}): {1}" -f $Path, $_.Exception.Message) }
    return (Merge-AdfaExchangeSeConfig -BaseConfig $BaseConfig -Override $obj -OverrideSource $Path)
}

function Get-AdfaEnrichmentFailureAdvice {
    <#
    .SYNOPSIS
        Pure: turns the errors a DC-inventory enrichment hit into advice that matches them.
    .DESCRIPTION
        Before v1.15.0 the "OS not readable" finding gave one fixed line - "re-run with
        credentials that can read the DC computer objects" - whatever had actually gone wrong.
        On a live four-domain forest the real cause was an LDAP REFERRAL: the enrichment queried
        a forest-root DC for a DN in a child domain, and Get-ADComputer does not chase referrals.
        Credentials had nothing to do with it, so the advice sent the operator somewhere there
        was nothing to find. A wrong cause is worse than no cause.

        The referral case is now named specifically, because it is the one that means THIS TOOL
        had a bug rather than the directory having a problem. Access errors keep the credentials
        advice, which is right for them. Anything else is quoted verbatim rather than
        interpreted - an unrecognised error is reported, never guessed at.
    .OUTPUTS
        [string] A leading-space-prefixed sentence, or '' when there is nothing to say.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyCollection()][string[]]$Causes = @())
    $seen = @(@($Causes) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() } | Select-Object -Unique)
    if ($seen.Count -eq 0) { return '' }
    $parts = @()
    if (@($seen | Where-Object { $_ -match '(?i)referral' }).Count -gt 0) {
        $parts += "An LDAP referral was returned, which means the computer object was looked up against a domain controller that does not hold that domain's naming context - not a credentials problem. On this build the per-domain lookup is targeted correctly; if you still see this, the DC serving the query cannot reach a DC in the affected domain."
    }
    if (@($seen | Where-Object { $_ -match '(?i)access is denied|insufficient access|authentication' }).Count -gt 0) {
        $parts += 'Access was denied, so re-run with credentials that can read the DC computer objects in that domain.'
    }
    $parts += ("Reported by the directory: {0}." -f (($seen | Select-Object -First 3) -join ' | '))
    return (' ' + ($parts -join ' '))
}

function Get-AdfaForestLevelTable {
    <#
    .SYNOPSIS
        Pure: the ForestFunctionalLevels config table as uniform objects.
    .DESCRIPTION
        The built-in table holds hashtables; one loaded from a JSON override holds
        PSCustomObjects. Normalised once here so no caller has to handle both. An entry whose
        Level is not a whole number is dropped rather than coerced - a level this tool cannot
        read as a number is not a level it can order.
    .OUTPUTS
        [pscustomobject[]] Level (int), Mode, Label.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][hashtable]$SeConfig)
    $out = @()
    foreach ($entry in @($SeConfig['ForestFunctionalLevels'])) {
        if ($null -eq $entry) { continue }
        $level = $null; $mode = ''; $label = ''
        if ($entry -is [hashtable]) { $level = $entry['Level']; $mode = [string]$entry['Mode']; $label = [string]$entry['Label'] }
        else {
            foreach ($n in @('Level', 'Mode', 'Label')) {
                $p = $entry.PSObject.Properties[$n]
                if ($null -eq $p) { continue }
                if ($n -eq 'Level') { $level = $p.Value } elseif ($n -eq 'Mode') { $mode = [string]$p.Value } else { $label = [string]$p.Value }
            }
        }
        $parsed = 0
        if (-not [int]::TryParse([string]$level, [ref]$parsed)) { continue }
        $out += [pscustomobject]@{ Level = $parsed; Mode = $mode; Label = $label }
    }
    return @($out)
}

function Get-AdfaForestLevelClass {
    <#
    .SYNOPSIS
        Pure: where a raw msDS-Behavior-Version value sits relative to the supported levels.
    .DESCRIPTION
        The one decision H17 turns on. Takes the value exactly as the directory returned it
        (a string, possibly empty), the levels this build knows, and the levels the release
        supports. Nothing is queried.
    .OUTPUTS
        [string] One of: Unreadable | Unrecognised | Supported | Below | Above
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyString()][string]$RawLevel,
        [AllowEmptyCollection()][int[]]$KnownLevels = @(),
        [AllowEmptyCollection()][int[]]$SupportedLevels = @()
    )
    if ([string]::IsNullOrWhiteSpace($RawLevel)) { return 'Unreadable' }
    $level = 0
    # TryParse rejects 'abc' and '7.5'. It accepts '-1' and '9', which are numbers but not
    # levels - the known-level check is what turns those away.
    if (-not [int]::TryParse($RawLevel.Trim(), [ref]$level)) { return 'Unrecognised' }
    if (@($KnownLevels) -notcontains $level) { return 'Unrecognised' }
    if (@($SupportedLevels) -contains $level) { return 'Supported' }
    $max = (@($SupportedLevels) | Measure-Object -Maximum).Maximum
    # Above only when it exceeds EVERY supported level. A known level sitting in a gap between
    # two supported ones (possible only with an override) is Below: raising it reaches a
    # supported level, so the raise advice is true for it.
    if ($null -ne $max -and $level -gt [int]$max) { return 'Above' }
    return 'Below'
}

function Get-AdfaForestBehaviorVersion {
    <#
    .SYNOPSIS
        Reads the forest functional level as the number the directory stores.
    .DESCRIPTION
        One read-only LDAP read of msDS-Behavior-Version on the Partitions container, whose DN
        comes from Get-ADForest's own PartitionsContainer property rather than being composed.

        Fail-closed. Learn states that "0 or not set" means the Windows 2000 level, but an
        attribute that was not RETURNED cannot be told apart from one that is not SET by this
        read, so an absent value is reported as not read with that reason - never as level 0.
        A refused or failed read carries the directory's own error text, uninterpreted.
    .OUTPUTS
        [pscustomobject] Level (raw string, '' when not read), Error ('' when read).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$Forest,
        [hashtable]$AdParams = @{}
    )
    $container = ''
    if ($null -ne $Forest) {
        $pcProp = $Forest.PSObject.Properties['PartitionsContainer']
        if ($null -ne $pcProp -and $null -ne $pcProp.Value) { $container = [string]$pcProp.Value }
    }
    if ([string]::IsNullOrWhiteSpace($container)) {
        return [pscustomobject]@{ Level = ''; Error = 'Get-ADForest returned no PartitionsContainer, so the object holding msDS-Behavior-Version could not be located.' }
    }
    try {
        $p = @{} + $AdParams
        $p.Identity = $container
        $p.Properties = @('msDS-Behavior-Version')
        $p.ErrorAction = 'Stop'
        $obj = Get-ADObject @p
        $bvProp = $null
        if ($null -ne $obj) { $bvProp = $obj.PSObject.Properties['msDS-Behavior-Version'] }
        if ($null -eq $bvProp -or $null -eq $bvProp.Value -or [string]::IsNullOrWhiteSpace([string]$bvProp.Value)) {
            return [pscustomobject]@{ Level = ''; Error = ("msDS-Behavior-Version was not returned for {0}. An unset attribute and one that could not be read look the same from here, so no level is assumed." -f $container) }
        }
        return [pscustomobject]@{ Level = ([string]$bvProp.Value).Trim(); Error = '' }
    }
    catch {
        return [pscustomobject]@{ Level = ''; Error = ("Reading msDS-Behavior-Version from {0} failed: {1}" -f $container, $_.Exception.Message) }
    }
}

function Get-AdfaExchangeSeCompatibility {
    <#
    .SYNOPSIS
        Verdict on whether the forest's AD level and DC operating systems permit Exchange SE.
    .DESCRIPTION
        Deliberately narrow. This answers only the two questions the directory can answer on
        its own - forest functional level, and the operating system of every DC in the forest -
        plus the read-only caveat from the same table. It is NOT an Exchange SE readiness
        assessment: schema and organisation object versions, the per-site writeable-GC
        requirement, Exchange server inventory and coexistence builds are out of scope here
        and belong to ExchangeAssessment, whose remit that is.

        Pure: every value is passed in, nothing is queried, so the whole verdict is testable
        without a directory.

        Fail-closed. A DC whose OperatingSystem could not be read is reported Not Assessed with
        that cause named - never assumed supported, and never counted as unsupported either,
        because an absent value and a measured unsupported value are different claims.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # Shown for information only. The verdict never reads it - see -ForestLevel.
        [AllowNull()][AllowEmptyString()][string]$ForestMode,
        # msDS-Behavior-Version exactly as read from the Partitions container; '' when not read.
        [AllowNull()][AllowEmptyString()][string]$ForestLevel,
        # Why -ForestLevel is empty, in the directory's own words where it gave any.
        [AllowNull()][AllowEmptyString()][string]$ForestLevelError,
        [AllowNull()][AllowEmptyCollection()]$DomainSummaries = @(),
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [Parameter(Mandatory)][hashtable]$SeConfig
    )
    $rows = @()
    $release = [string]$SeConfig['Release']
    $provenance = ("Per {0} (read {1})." -f [string]$SeConfig['SourceUrl'], [string]$SeConfig['ReadDate'])
    $supportedModes = @($SeConfig['SupportedForestModes'])
    $supportedOs = @($SeConfig['SupportedDomainControllerOs'])
    $osLabels = @($supportedOs | ForEach-Object {
            if ($_ -is [hashtable]) { [string]$_['Label'] } else { [string]$_.PSObject.Properties['Label'].Value }
        })

    # ---- Forest functional level ----
    # Decided from the NUMBER (msDS-Behavior-Version), not the mode name. Membership of a name
    # list can only say "listed" or "not listed"; before H17 every unlisted name was told to
    # raise the level, which is the wrong direction for a forest already above the matrix.
    $levelTable = @(Get-AdfaForestLevelTable -SeConfig $SeConfig)
    $knownLevels = @($levelTable | ForEach-Object { [int]$_.Level })
    $supportedLevels = @($levelTable | Where-Object { $supportedModes -contains $_.Mode } | ForEach-Object { [int]$_.Level })
    $rawLevel = ''
    if ($null -ne $ForestLevel) { $rawLevel = ([string]$ForestLevel).Trim() }
    $modeNote = ''
    if (-not [string]::IsNullOrWhiteSpace($ForestMode)) {
        $modeNote = (" Get-ADForest reported ForestMode '{0}', shown for information only - the verdict is taken from the numeric level." -f $ForestMode)
    }
    $fflItem = 'Forest functional level'

    if ($supportedLevels.Count -eq 0) {
        # Reachable only through a config whose supported names resolve to no level. Judging
        # against an empty set would fail every forest, so say what is wrong instead.
        $rows += New-Finding -Area 'ExchangeSeReadiness' -Item $fflItem -Status $script:Status.NotAssessed `
            -Detail ("None of the supported forest modes ({0}) resolves to a level in the ForestFunctionalLevels table, so there is nothing to judge the forest against. Correct the config. {1}" -f ($supportedModes -join ', '), $provenance)
    }
    else {
        $levelClass = Get-AdfaForestLevelClass -RawLevel $rawLevel -KnownLevels $knownLevels -SupportedLevels $supportedLevels
        $label = ''
        $parsedLevel = 0
        if ([int]::TryParse($rawLevel, [ref]$parsedLevel)) {
            $hit = @($levelTable | Where-Object { [int]$_.Level -eq $parsedLevel })
            if ($hit.Count -gt 0) { $label = [string]$hit[0].Label }
        }
        $what = ("{0} forest functional level (msDS-Behavior-Version {1})" -f $label, $rawLevel)

        if ($levelClass -eq 'Supported') {
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item $fflItem -Status $script:Status.Pass `
                -Detail ("{0} - supported for {1}. {2}{3}" -f $what, $release, $provenance, $modeNote)
        }
        elseif ($levelClass -eq 'Below') {
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item $fflItem -Status $script:Status.Fail `
                -Detail ("{0} is NOT supported for {1}: it is below the supported levels. Supported: {2}. Setup will not proceed until the forest functional level is raised. {3}{4}" -f `
                    $what, $release, ($supportedModes -join ', '), $provenance, $modeNote)
        }
        elseif ($levelClass -eq 'Above') {
            # No remediation command is offered, by the operator's decision for H17: "raise it"
            # is the opposite of what this finding means. Learn does publish a procedure for
            # LOWERING a functional level; whether to point at it is PORT-PLAN H18, because that
            # page was not read in full when this was written.
            #
            # The list is called "the supportability matrix" only when the values really are
            # Microsoft's. Under an override the same sentence would put words in the vendor's
            # mouth - the real matrix may well list the level an override leaves out.
            $listName = 'the supplied config table'
            if ([string]$SeConfig['SourceUrl'] -match '(?i)^https://learn\.microsoft\.com/') { $listName = 'the supportability matrix' }
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item $fflItem -Status $script:Status.Fail `
                -Detail ("{0} is not listed in {1} for {2}: it is above the levels listed there ({3}). This is not a level to raise. {4}{5}" -f `
                    $what, $listName, $release, ($supportedModes -join ', '), $provenance, $modeNote)
        }
        elseif ($levelClass -eq 'Unrecognised') {
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item $fflItem -Status $script:Status.NotAssessed `
                -Detail ("msDS-Behavior-Version on the Partitions container is '{0}', which is not a forest functional level this build recognises (known: {1}). The raw value is shown and no verdict is given for {2}.{3}" -f `
                    $rawLevel, (($knownLevels | Sort-Object) -join ', '), $release, $modeNote)
        }
        else {
            $cause = 'No cause was recorded.'
            if (-not [string]::IsNullOrWhiteSpace($ForestLevelError)) { $cause = ("Cause: {0}" -f ([string]$ForestLevelError).Trim()) }
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item $fflItem -Status $script:Status.NotAssessed `
                -Detail ("The forest functional level (msDS-Behavior-Version on the Partitions container) could not be read, so {0} compatibility cannot be judged. {1}{2}" -f `
                    $release, $cause, $modeNote)
        }
    }

    # ---- Domain functional levels: informational ----
    # The supportability matrix states a FOREST functional level requirement and no domain one,
    # so these are reported rather than judged. Inventing a domain gate would be a fabricated
    # vendor requirement.
    foreach ($d in @($DomainSummaries)) {
        if ($null -eq $d) { continue }
        $dmProp = $d.PSObject.Properties['DomainMode']
        $dnProp = $d.PSObject.Properties['DomainName']
        $dm = ''
        if ($null -ne $dmProp -and $null -ne $dmProp.Value) { $dm = [string]$dmProp.Value }
        $dn = ''
        if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $dn = [string]$dnProp.Value }
        if ([string]::IsNullOrWhiteSpace($dm)) { continue }
        $rows += New-Finding -Scope $dn -Area 'ExchangeSeReadiness' -Item ("Domain functional level - {0}" -f $dn) `
            -Status $script:Status.Info `
            -Detail ("{0}. Recorded for completeness: the supportability matrix states a forest functional level requirement and does not state a domain one. {1}" -f $dm, $provenance)
    }

    # ---- Domain controller operating systems ----
    # "All domain controllers in the forest must be running one of the supported versions",
    # so a single unsupported DC anywhere in the forest is a blocker, not a warning.
    $dcs = @($DomainControllers | Where-Object { $null -ne $_ })
    if ($dcs.Count -eq 0) {
        $rows += New-Finding -Area 'ExchangeSeReadiness' -Item 'Domain controller operating systems' -Status $script:Status.NotAssessed `
            -Detail ("No domain controllers were enumerated, so no OS could be checked against the {0} supported list ({1})." -f $release, ($osLabels -join ', '))
    }
    else {
        $unsupported = @()
        $unknown = @()
        $unknownCauses = @()
        $supported = @()
        foreach ($dc in $dcs) {
            $hostProp = $dc.PSObject.Properties['HostName']
            $osProp = $dc.PSObject.Properties['OperatingSystem']
            $dcName = '(unnamed)'
            if ($null -ne $hostProp -and $null -ne $hostProp.Value) { $dcName = [string]$hostProp.Value }
            $os = ''
            if ($null -ne $osProp -and $null -ne $osProp.Value) { $os = [string]$osProp.Value }

            # The inventory writes the literal 'Not Assessed' into OperatingSystem when the
            # Get-ADComputer enrichment failed. That is an absent measurement, not a bad OS.
            if ([string]::IsNullOrWhiteSpace($os) -or $os -eq $script:Status.NotAssessed) {
                $unknown += $dcName
                # The inventory records WHY it could not read the computer object. Without it
                # this finding guessed, and guessed wrong: a cross-domain LDAP referral is not a
                # credentials problem, and telling an operator to re-run with other credentials
                # sends them somewhere there is nothing to find.
                $eProp = $dc.PSObject.Properties['EnrichmentError']
                if ($null -ne $eProp -and -not [string]::IsNullOrWhiteSpace([string]$eProp.Value)) {
                    $unknownCauses += [string]$eProp.Value
                }
                continue
            }
            $label = Test-AdfaOsSupported -OperatingSystem $os -SupportedOs $supportedOs
            if ([string]::IsNullOrWhiteSpace($label)) { $unsupported += ("{0} ({1})" -f $dcName, $os) }
            else { $supported += $dcName }
        }

        if ($unsupported.Count -gt 0) {
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item 'Domain controller operating systems' -Status $script:Status.Fail `
                -Detail ("{0} of {1} DC(s) run an OS not supported for {2}: {3}. Every DC in the forest must run a supported version. Supported: {4}. {5}" -f `
                    $unsupported.Count, $dcs.Count, $release, ($unsupported -join '; '), ($osLabels -join ', '), $provenance)
        }
        elseif ($unknown.Count -gt 0 -and $supported.Count -eq 0) {
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item 'Domain controller operating systems' -Status $script:Status.NotAssessed `
                -Detail ("No DC operating system could be read ({0} DC(s): {1}), so {2} compatibility is unverified. Supported: {3}." -f `
                    $unknown.Count, ($unknown -join ', '), $release, ($osLabels -join ', '))
        }
        else {
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item 'Domain controller operating systems' -Status $script:Status.Pass `
                -Detail ("All {0} DC(s) whose OS could be read run a version supported for {1}. Supported: {2}. {3}" -f `
                    $supported.Count, $release, ($osLabels -join ', '), $provenance)
        }

        # An unreadable OS is reported on its own, so a partial pass above can never hide it.
        if ($unknown.Count -gt 0) {
            $rows += New-Finding -Area 'ExchangeSeReadiness' -Item 'Domain controller OS - not readable' -Status $script:Status.NotAssessed `
                -Detail ("{0} of {1} DC(s) did not return an operating system: {2}.{3} Until this is resolved these DCs are unverified, NOT compatible - and a forest-wide readiness verdict cannot be given while any DC is unread, because every DC in the forest must run a supported version." -f `
                    $unknown.Count, $dcs.Count, ($unknown -join ', '), (Get-AdfaEnrichmentFailureAdvice -Causes $unknownCauses))
        }

        # Read-only DCs. The same table says read-only DCs and GCs are not supported; Exchange
        # will not use one. Reported as a Warning rather than a blocker because an RODC in a site
        # Exchange is never installed into does not stop Setup - what stops Setup is a target
        # site with no writeable GC, which is ExchangeAssessment's check and not claimed here.
        if (-not [bool]$SeConfig['ReadOnlySupported']) {
            $rodc = @()
            foreach ($dc in $dcs) {
                $roProp = $dc.PSObject.Properties['IsReadOnly']
                $hostProp = $dc.PSObject.Properties['HostName']
                if ($null -eq $roProp -or $null -eq $roProp.Value) { continue }
                if ([string]$roProp.Value -eq $script:Status.NotAssessed) { continue }
                if ([bool]$roProp.Value) {
                    $n = '(unnamed)'
                    if ($null -ne $hostProp -and $null -ne $hostProp.Value) { $n = [string]$hostProp.Value }
                    $rodc += $n
                }
            }
            if ($rodc.Count -gt 0) {
                $rows += New-Finding -Area 'ExchangeSeReadiness' -Item 'Read-only domain controllers' -Status $script:Status.Warning `
                    -Detail ("{0} read-only DC(s): {1}. Read-only DCs and read-only global catalogs are not supported for {2} - Exchange will not use them. Confirm every site an Exchange server goes into also holds a writeable global catalog. {3}" -f `
                        $rodc.Count, ($rodc -join ', '), $release, $provenance)
            }
        }
    }

    # Scope statement, so nobody reads this section as full SE readiness.
    $rows += New-Finding -Area 'ExchangeSeReadiness' -Item 'Scope of this check' -Status $script:Status.Info `
        -Detail ("Covers the AD prerequisites this tool can answer from the directory: forest functional level and DC operating systems. It does NOT cover schema or organisation object versions, the per-site writeable global catalog requirement, Exchange server inventory or coexistence builds.")
    return @($rows)
}
# ===========================================================================
# region Exchange schema markers
# ===========================================================================

function Get-AdfaExchangeSchemaMarker {
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([hashtable]$AdParams = @{})
    $m = @()
    try {
        $schema = (Get-ADRootDSE @AdParams).schemaNamingContext
        $o = Get-ADObject -LDAPFilter '(cn=ms-Exch-Schema-Version-Pt)' -SearchBase $schema -Properties rangeUpper, whenChanged @AdParams -ErrorAction Stop
        if ($o) { $m += [pscustomobject]@{ Marker = 'ms-Exch-Schema-Version-Pt'; RangeUpper = $o.rangeUpper; WhenChanged = $o.whenChanged; Note = '' } }
        else { $m += [pscustomobject]@{ Marker = 'ms-Exch-Schema-Version-Pt'; RangeUpper = $null; WhenChanged = $null; Note = 'NotFound' } }
    }
    catch { $m += [pscustomobject]@{ Marker = 'ms-Exch-Schema-Version-Pt'; RangeUpper = $null; WhenChanged = $null; Note = $_.Exception.Message } }
    return @($m)
}

# ===========================================================================
# region Recovery & consistency (post-incident)
# ===========================================================================

function Get-AdfaDnsQueryOutcome {
    <#
    .SYNOPSIS
        Pure classification of a DNS query result. Distinguishes an authoritative
        "the record does not exist" from "the server did not answer" - conflating them
        would let a dead DNS server masquerade as a missing record (or vice versa).
    .OUTPUTS
        [string] NoTool | Resolved | NoRecord | NoAnswer
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [bool]$Available = $true,
        [int]$TargetCount = 0,
        [string]$ErrorText = ''
    )
    if (-not $Available) { return 'NoTool' }
    if ($TargetCount -gt 0) { return 'Resolved' }
    if ($ErrorText -match '(?i)does not exist|name_error|nxdomain|no records|non-existent|no such') { return 'NoRecord' }
    return 'NoAnswer'
}

function Resolve-AdfaDnsRecord {
    <#
    .SYNOPSIS
        Resolves a DNS record (SRV, CNAME, NS, A or SOA) with Resolve-DnsName, falling back to
        nslookup where the DnsClient module is absent. -Server queries a specific DNS
        server, so AD-integrated zone content can be compared PER SERVER - in a forest
        with broken replication the _msdcs content genuinely differs between DCs, and
        one resolver's view is not forest truth. Fail-closed: "no tool", "no record"
        and "no answer" are reported as distinct outcomes, never conflated.

        What Targets holds per type, because it is not uniform and a caller that assumed
        otherwise would draw a confident wrong conclusion:
          SRV   -> NameTarget, the host each SRV record points at.
          CNAME -> NameHost, the alias target.
          NS    -> NameHost, each name server named for the zone.
          A     -> IPAddress, used here as the GLUE record behind an NS target.
          SOA   -> the zone APEX that answered, i.e. the record's own Name, NOT the primary
                   server. That is deliberate: the only question this tool asks of an SOA
                   query is "which zone is authoritative for this name", which is how a
                   delegated child zone is told apart from a plain subdomain of its parent.
        nslookup cannot be parsed for SOA reliably - its output does not label the answering
        zone in a documented way - so an SOA query with no DnsClient module returns NoTool
        rather than a guess.
    .OUTPUTS
        [pscustomobject] Available (bool), Targets (string[]), Error (string),
        Outcome (NoTool|Resolved|NoRecord|NoAnswer)
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][ValidateSet('SRV', 'CNAME', 'NS', 'A', 'SOA')][string]$Type,
        [string]$Server
    )
    $targets = @()
    if (Test-CommandAvailable -Name 'Resolve-DnsName') {
        $err = ''
        try {
            $rp = @{ Name = $Name; Type = $Type; DnsOnly = $true; ErrorAction = 'Stop' }
            if ($Server) { $rp.Server = $Server }
            $ans = @(Resolve-DnsName @rp)
            foreach ($a in $ans) {
                # Every record type carries a Name, so an SOA answer MUST be filtered by record
                # type or an unrelated additional-section record would be read as the zone apex.
                if ($Type -eq 'SOA') {
                    $tProp = $a.PSObject.Properties['Type']   # $null when absent - StrictMode-safe
                    if ($null -eq $tProp -or "$($tProp.Value)" -ne 'SOA') { continue }
                }
                if ($Type -eq 'SRV' -and $a.PSObject.Properties['NameTarget'] -and $a.NameTarget) { $targets += [string]$a.NameTarget }
                elseif ($Type -eq 'CNAME' -and $a.PSObject.Properties['NameHost'] -and $a.NameHost) { $targets += [string]$a.NameHost }
                elseif ($Type -eq 'NS' -and $a.PSObject.Properties['NameHost'] -and $a.NameHost) { $targets += [string]$a.NameHost }
                elseif ($Type -eq 'A' -and $a.PSObject.Properties['IPAddress'] -and $a.IPAddress) { $targets += [string]$a.IPAddress }
                elseif ($Type -eq 'SOA' -and $a.PSObject.Properties['Name'] -and $a.Name) { $targets += [string]$a.Name }
            }
        }
        catch { $err = $_.Exception.Message }
        $targets = @($targets | Sort-Object -Unique)
        return [pscustomobject]@{
            Available = $true; Targets = $targets; Error = $err
            Outcome   = Get-AdfaDnsQueryOutcome -Available $true -TargetCount @($targets).Count -ErrorText $err
        }
    }
    # SOA is deliberately NOT attempted through nslookup: the answering zone is not labelled in
    # its output in any documented way, and a wrong apex here would turn a healthy delegation
    # into a confident Fail. No tool is an honest answer; a guessed one is not.
    if ($Type -eq 'SOA') {
        return [pscustomobject]@{
            Available = $false; Targets = @()
            Error     = 'Resolve-DnsName is not available on this host, and an SOA query cannot be read reliably from nslookup output, so the authoritative zone for this name was not determined.'
            Outcome   = 'NoTool'
        }
    }
    if (Test-CommandAvailable -Name 'nslookup.exe') {
        $lookupArgs = "-type={0} {1}" -f $Type, $Name
        if ($Server) { $lookupArgs = "{0} {1}" -f $lookupArgs, $Server }
        $r = Invoke-ExternalCommand -FilePath 'nslookup.exe' -Arguments $lookupArgs -TimeoutSeconds 20 -Retries 1
        if ($r.StdOut) {
            # nslookup prints its OWN server's address in the header, before the answer:
            #   Server:  ns.example  / Address:  <server ip>  / (blank) / Name: <query> / Address: <answer>
            # so an Address line is only an answer once a Name line has been seen. Reading the
            # header would report the DNS server's own address as the record's glue.
            $inAnswer = $false
            foreach ($line in ($r.StdOut -split "`r?`n")) {
                if ($line -match '^\s*Name:') { $inAnswer = $true }
                if ($Type -eq 'SRV' -and $line -match 'svr hostname\s*=\s*(\S+)') { $targets += $Matches[1].TrimEnd('.') }
                elseif ($Type -eq 'CNAME' -and $line -match 'canonical name\s*=\s*(\S+)') { $targets += $Matches[1].TrimEnd('.') }
                elseif ($Type -eq 'NS' -and $line -match 'nameserver\s*=\s*(\S+)') { $targets += $Matches[1].TrimEnd('.') }
                elseif ($Type -eq 'A' -and $inAnswer -and $line -match '^\s*Address(?:es)?:\s*(\S+)') { $targets += $Matches[1].TrimEnd('.') }
            }
        }
        $err = ''
        if (@($targets).Count -eq 0) {
            if ($r.StdOut -match '(?i)non-existent domain|NXDOMAIN') { $err = 'Non-existent domain (no such record).' }
            elseif ($r.StdOut -match '(?i)timed out|no response|server failed') { $err = 'DNS server did not answer.' }
            else { $err = 'No records returned by nslookup.' }
        }
        $targets = @($targets | Sort-Object -Unique)
        return [pscustomobject]@{
            Available = $true; Targets = $targets; Error = $err
            Outcome   = Get-AdfaDnsQueryOutcome -Available $true -TargetCount @($targets).Count -ErrorText $err
        }
    }
    return [pscustomobject]@{
        Available = $false; Targets = @()
        Error     = 'Neither Resolve-DnsName nor nslookup.exe is available on this host.'
        Outcome   = 'NoTool'
    }
}

function Compare-AdfaDnsServerView {
    <#
    .SYNOPSIS
        Pure comparison of multiple DNS servers' views of the same record set against
        the host set Active Directory contains. Reports per-server divergence plus a
        consensus summary, so "3 of 7 DNS servers advertise a DC that does not exist"
        is visible instead of one resolver's answer being printed as forest truth.
    .OUTPUTS
        [pscustomobject] PerServer, AgreeingServers, DivergentServers, ServersQueried
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyCollection()][string[]]$AdHosts = @(),
        [hashtable]$ServerTargets = @{}
    )
    $perServer = @()
    foreach ($srv in @($ServerTargets.Keys | Sort-Object)) {
        $cmp = Compare-AdfaDnsAdvertisement -AdHosts $AdHosts -DnsTargets $ServerTargets[$srv]
        $perServer += [pscustomobject]@{
            Server         = $srv
            StaleInDns     = $cmp.StaleInDns
            MissingFromDns = $cmp.MissingFromDns
            Matched        = $cmp.Matched
            Agrees         = (@($cmp.StaleInDns).Count -eq 0 -and @($cmp.MissingFromDns).Count -eq 0)
        }
    }
    [pscustomobject]@{
        PerServer        = @($perServer)
        AgreeingServers  = @($perServer | Where-Object { $_.Agrees } | Select-Object -ExpandProperty Server)
        DivergentServers = @($perServer | Where-Object { -not $_.Agrees } | Select-Object -ExpandProperty Server)
        ServersQueried   = @($perServer).Count
    }
}

function Compare-AdfaDnsAdvertisement {
    <#
    .SYNOPSIS
        Pure comparison of the DC set Active Directory contains against the host set DNS
        advertises. Names are normalised (case, trailing dot) before comparing.
    .OUTPUTS
        [pscustomobject] StaleInDns (string[]), MissingFromDns (string[]), Matched (string[])
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowEmptyCollection()][string[]]$AdHosts = @(),
        [AllowEmptyCollection()][string[]]$DnsTargets = @()
    )
    $ad = @{}
    foreach ($h in $AdHosts) { if ($h) { $ad[$h.ToLowerInvariant().TrimEnd('.')] = $true } }
    $dns = @{}
    foreach ($t in $DnsTargets) { if ($t) { $dns[$t.ToLowerInvariant().TrimEnd('.')] = $true } }

    $stale = @(); $missing = @(); $matched = @()
    foreach ($k in $dns.Keys) { if (-not $ad.ContainsKey($k)) { $stale += $k } }
    foreach ($k in $ad.Keys) {
        if ($dns.ContainsKey($k)) { $matched += $k } else { $missing += $k }
    }
    [pscustomobject]@{
        StaleInDns     = @($stale | Sort-Object)
        MissingFromDns = @($missing | Sort-Object)
        Matched        = @($matched | Sort-Object)
    }
}

function Resolve-AdfaDcPasswordVerdict {
    <#
    .SYNOPSIS
        Pure verdict for a DC machine-account password age. Rotation is client-initiated
        every 30 days by default, so an old replicated pwdLastSet means rotation is not
        happening - typical of a DC restored from an old backup.
    .OUTPUTS
        [string] Pass | Warning | Fail | Not Assessed
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][nullable[double]]$AgeDays,
        [int]$WarnDays = 45,
        [int]$FailDays = 90
    )
    if ($null -eq $AgeDays) { return $script:Status.NotAssessed }
    if ($AgeDays -ge $FailDays) { return $script:Status.Fail }
    if ($AgeDays -ge $WarnDays) { return $script:Status.Warning }
    return $script:Status.Pass
}

function Get-AdfaDnsRecordView {
    <#
    .SYNOPSIS
        Queries one DNS record on every given DNS server (plus the local resolver) and
        buckets the outcomes: answering servers with their target lists, and servers
        that did not answer. AD-integrated zones replicate through AD, so when
        replication is broken the answer genuinely differs per server - each server's
        view is collected separately, never merged.
    .OUTPUTS
        [pscustomobject] ToolAvailable (bool), Views (hashtable server->targets),
        Unanswered (string[]), Error (string)
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][ValidateSet('SRV', 'CNAME', 'NS', 'A', 'SOA')][string]$Type,
        [AllowEmptyCollection()][string[]]$DnsServers = @()
    )
    $views = @{}
    $unanswered = @()

    $local = Resolve-AdfaDnsRecord -Name $Name -Type $Type
    if ($local.Outcome -eq 'NoTool') {
        return [pscustomobject]@{ ToolAvailable = $false; Views = @{}; Unanswered = @(); Error = $local.Error }
    }
    if ($local.Outcome -eq 'NoAnswer') { $unanswered += '(local resolver)' }
    else { $views['(local resolver)'] = @($local.Targets) }

    foreach ($srv in @($DnsServers | Where-Object { $_ } | Sort-Object -Unique)) {
        $r = Resolve-AdfaDnsRecord -Name $Name -Type $Type -Server $srv
        if ($r.Outcome -eq 'NoAnswer') { $unanswered += $srv }
        else { $views[$srv] = @($r.Targets) }
    }
    [pscustomobject]@{ ToolAvailable = $true; Views = $views; Unanswered = @($unanswered); Error = '' }
}

function Get-AdfaDnsAdConsistency {
    <#
    .SYNOPSIS
        Compares the DC locator SRV records against the DCs Active Directory actually
        contains - PER DNS SERVER. Stale entries (a removed/dead DC still advertised)
        and missing entries (a live DC not advertised) are the divergences that surface
        as intermittent RPC 1722 and logon failures after a restore; in a forest with
        broken replication different DNS servers hold different zone content, so each
        server's view is assessed and a divergence summary is reported.

        PORT-PLAN C13 adds, after these rows, the per-DC rows of Get-AdfaDnsLocatorFinding: whether
        each writable DC is named by the graded DC locator SRV records on every DNS server, by two
        instruments (DNS-003); whether its A records are its configured addresses (DNS-004); and
        the locator records that name no DC (DNS-005). The per-server rows above are unchanged.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [AllowEmptyCollection()][string[]]$DnsServers = @(),
        [hashtable]$Config = $script:Config.Dns,
        [AllowNull()][AllowEmptyString()][string]$ForestRoot = '',
        [AllowNull()][AllowEmptyCollection()]$DsaInventory = @(),
        [AllowNull()][AllowEmptyString()][string]$DsaError = '',
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [int]$OperationTimeoutSec = 90
    )
    $rows = @()
    $p = @{} + $AdParams; $p.Server = $DomainName
    $adHosts = @()
    $adDcs = @()
    try {
        $adDcs = @(Get-ADDomainController -Filter * @p | Where-Object { $null -ne $_ })
        $adHosts = @($adDcs | ForEach-Object { $hp = $_.PSObject.Properties['HostName']; if ($null -ne $hp -and $null -ne $hp.Value) { [string]$hp.Value } })
    }
    catch {
        $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item 'DC list from AD' -Status $script:Status.NotAssessed -Detail $_.Exception.Message
        return @($rows)
    }

    foreach ($rec in @(("_ldap._tcp.dc._msdcs.{0}" -f $DomainName), ("_kerberos._tcp.dc._msdcs.{0}" -f $DomainName))) {
        $view = Get-AdfaDnsRecordView -Name $rec -Type SRV -DnsServers $DnsServers
        if (-not $view.ToolAvailable) {
            $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0}" -f $rec) -Status $script:Status.NotAssessed -Detail $view.Error
            continue
        }
        if (@($view.Views.Keys).Count -eq 0) {
            $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0}" -f $rec) -Status $script:Status.NotAssessed -Detail ("No DNS server answered for this record ({0} queried: {1})." -f @($view.Unanswered).Count, ($view.Unanswered -join ', '))
            continue
        }
        $sum = Compare-AdfaDnsServerView -AdHosts $adHosts -ServerTargets $view.Views
        foreach ($ps in @($sum.PerServer | Where-Object { -not $_.Agrees })) {
            $bits = @()
            if (@($ps.StaleInDns).Count -gt 0) { $bits += ("stale (no such DC in AD): {0}" -f ((@($ps.StaleInDns) | Select-Object -First 8) -join ', ')) }
            if (@($ps.MissingFromDns).Count -gt 0) { $bits += ("missing (DC in AD, not advertised): {0}" -f ((@($ps.MissingFromDns) | Select-Object -First 8) -join ', ')) }
            $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0} on {1}" -f $rec, $ps.Server) -Status $script:Status.Fail -Detail ($bits -join '; ')
        }
        $unansweredNote = ''
        if (@($view.Unanswered).Count -gt 0) { $unansweredNote = (' {0} server(s) did not answer: {1}.' -f @($view.Unanswered).Count, ($view.Unanswered -join ', ')) }
        if (@($sum.DivergentServers).Count -eq 0) {
            $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0}" -f $rec) -Status $script:Status.Pass -Detail ("All {0} answering DNS server(s) agree with AD ({1} DC(s)).{2}" -f $sum.ServersQueried, @($adHosts).Count, $unansweredNote)
        }
        else {
            $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0} - divergence summary" -f $rec) -Status $script:Status.Fail -Detail ("{0} of {1} answering DNS server(s) diverge from AD: {2}.{3}" -f @($sum.DivergentServers).Count, $sum.ServersQueried, ($sum.DivergentServers -join ', '), $unansweredNote)
        }
    }

    # PDC locator record must point at the actual PDC emulator - on every DNS server.
    try {
        $pdc = (Get-ADDomain @p).PDCEmulator
        $actual = ''
        if ($pdc) { $actual = ([string]$pdc).ToLowerInvariant().TrimEnd('.') }
        $pdcRec = "_ldap._tcp.pdc._msdcs.{0}" -f $DomainName
        $view = Get-AdfaDnsRecordView -Name $pdcRec -Type SRV -DnsServers $DnsServers
        if (-not $view.ToolAvailable) {
            $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0}" -f $pdcRec) -Status $script:Status.NotAssessed -Detail $view.Error
        }
        elseif (@($view.Views.Keys).Count -eq 0) {
            $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0}" -f $pdcRec) -Status $script:Status.NotAssessed -Detail 'No DNS server answered for the PDC locator record.'
        }
        else {
            $wrong = @()
            foreach ($srv in @($view.Views.Keys | Sort-Object)) {
                $t = @($view.Views[$srv])
                if (@($t).Count -eq 0) { $wrong += ("{0} (record missing)" -f $srv) }
                else {
                    $adv = ([string]$t[0]).ToLowerInvariant().TrimEnd('.')
                    if ($adv -ne $actual) { $wrong += ("{0} (advertises {1})" -f $srv, $adv) }
                }
            }
            if (@($wrong).Count -eq 0) {
                $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0}" -f $pdcRec) -Status $script:Status.Pass -Detail ("All {0} answering DNS server(s) point at the PDC emulator ({1})." -f @($view.Views.Keys).Count, $pdc)
            }
            else {
                $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item ("SRV {0}" -f $pdcRec) -Status $script:Status.Fail -Detail ("PDC emulator is {0} but: {1}. Logons and password changes will misroute on those servers." -f $actual, ($wrong -join '; '))
            }
        }
    }
    catch {
        $rows += New-Finding -Scope $DomainName -Area 'DnsAdConsistency' -Item 'PDC locator record' -Status $script:Status.NotAssessed -Detail $_.Exception.Message
    }

    # PORT-PLAN C13: the per-DC rows, from the same DC list.
    $rows += @(Get-AdfaDnsLocatorFinding -DomainName $DomainName -Dcs $adDcs -DnsServers $DnsServers -Config $Config -DsaInventory $DsaInventory -DsaError $DsaError `
            -ForestRoot $ForestRoot -Credential $Credential -PortTimeoutMs $PortTimeoutMs -OperationTimeoutSec $OperationTimeoutSec)
    return @($rows)
}

function Get-AdfaDsaInventory {
    <#
    .SYNOPSIS
        Enumerates every nTDSDSA object in the Configuration NC with its DSA GUID and
        the owning server's dNSHostName. Shared by the DSA CNAME check and the
        lingering-object scan. StrictMode-safe against objects missing properties.
    .OUTPUTS
        [pscustomobject[]] DsaGuid, ServerDn, DnsHostName ('' when orphaned)
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([hashtable]$AdParams = @{})
    $out = @()
    $cfg = (Get-ADRootDSE @AdParams).configurationNamingContext
    $dsas = @(Get-ADObject -LDAPFilter '(objectClass=nTDSDSA)' -SearchBase $cfg -Properties objectGUID, invocationId @AdParams)
    foreach ($dsa in $dsas) {
        $dsaDn = ''
        if ($dsa.PSObject.Properties['DistinguishedName'] -and $dsa.DistinguishedName) { $dsaDn = [string]$dsa.DistinguishedName }
        $dsaGuid = ''
        if ($dsa.PSObject.Properties['objectGUID'] -and $dsa.objectGUID) { $dsaGuid = [string]$dsa.objectGUID }
        if (-not $dsaDn -or -not $dsaGuid) { continue }
        $serverDn = $dsaDn -replace '^CN=NTDS Settings,', ''
        $dcHost = ''
        try {
            $srvObj = Get-ADObject -Identity $serverDn -Properties dNSHostName @AdParams
            if ($srvObj.PSObject.Properties['dNSHostName'] -and $srvObj.dNSHostName) { $dcHost = [string]$srvObj.dNSHostName }
        }
        catch {
            # Inventory rows carry no Status column, so there is nowhere here to put a finding.
            # It is logged instead: a blank DnsHostName silently fails to correlate with the DSA
            # CNAME and GC checks downstream, and that is worth a line in the run log.
            Write-Log -Level WARN -Section 'DsaInventory' -Message ("Server object {0} could not be read, so DSA {1} has no host name and will not correlate with the DNS checks: {2}" -f $serverDn, $dsaGuid, $_.Exception.Message)
        }
        # invocationId identifies the INSTANTIATION of the database, as distinct from objectGUID
        # which identifies the DSA. A supported restore resets it; an unsupported one does not,
        # which is what makes a duplicate across two DCs evidence of a cloned database.
        $invId = ''
        $iProp = $dsa.PSObject.Properties['invocationId']   # $null when absent - StrictMode-safe
        if ($null -ne $iProp -and $null -ne $iProp.Value) {
            try {
                if ($iProp.Value -is [byte[]]) { $invId = ([guid][byte[]]$iProp.Value).ToString() }
                else { $invId = [string]$iProp.Value }
            }
            catch { $invId = '' }
        }
        $out += [pscustomobject]@{ DsaGuid = $dsaGuid; ServerDn = $serverDn; DnsHostName = $dcHost; InvocationId = $invId }
    }
    # Plain return on purpose: callers wrap with @(...); `return @()` would hand them
    # one element that IS the empty array and StrictMode then chokes on it (PORT-PLAN P3).
    return @($out)
}

function Get-AdfaDsaGuidCname {
    <#
    .SYNOPSIS
        Verifies the DSA GUID CNAME alias in _msdcs for every DC - on every DNS server.
        Replication resolves a source DC through <objectGUID-of-NTDS-Settings>._msdcs,
        not through its A record; a missing or wrong alias is the single most common
        cause of RPC 1722 replication failures after metadata cleanup or a restore, and
        with broken replication the alias can exist on some DNS servers and not others.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$ForestRoot,
        [hashtable]$AdParams = @{},
        [AllowEmptyCollection()][string[]]$DnsServers = @()
    )
    $rows = @()
    $dsas = @()
    try { $dsas = @(Get-AdfaDsaInventory -AdParams $AdParams) }
    catch {
        $rows += New-Finding -Area 'DsaCname' -Item 'nTDSDSA enumeration' -Status $script:Status.NotAssessed -Detail $_.Exception.Message
        return @($rows)
    }
    if (@($dsas).Count -eq 0) {
        $rows += New-Finding -Area 'DsaCname' -Item 'nTDSDSA enumeration' -Status $script:Status.NotAssessed -Detail 'No usable nTDSDSA objects returned from the Configuration NC.'
        return @($rows)
    }

    foreach ($dsa in $dsas) {
        if (-not $dsa.DnsHostName) {
            $rows += New-Finding -Area 'DsaCname' -Item ("Orphaned NTDS Settings: {0}" -f $dsa.ServerDn) -Status $script:Status.Warning -Detail 'nTDSDSA object exists but its server object has no dNSHostName - likely metadata left behind by an incomplete demotion or restore.'
            continue
        }
        $dcHost = $dsa.DnsHostName
        $expected = $dcHost.ToLowerInvariant().TrimEnd('.')
        $alias = "{0}._msdcs.{1}" -f $dsa.DsaGuid, $ForestRoot
        $view = Get-AdfaDnsRecordView -Name $alias -Type CNAME -DnsServers $DnsServers
        if (-not $view.ToolAvailable) {
            $rows += New-Finding -Area 'DsaCname' -Item ("DSA GUID CNAME for {0}" -f $dcHost) -Status $script:Status.NotAssessed -Detail $view.Error
            continue
        }
        if (@($view.Views.Keys).Count -eq 0) {
            $rows += New-Finding -Area 'DsaCname' -Item ("DSA GUID CNAME for {0}" -f $dcHost) -Status $script:Status.NotAssessed -Detail ("No DNS server answered for {0}." -f $alias)
            continue
        }
        $missingOn = @(); $wrongOn = @(); $okOn = @()
        foreach ($srv in @($view.Views.Keys | Sort-Object)) {
            $t = @($view.Views[$srv])
            if (@($t).Count -eq 0) { $missingOn += $srv }
            else {
                $got = ([string]$t[0]).ToLowerInvariant().TrimEnd('.')
                if ($got -eq $expected) { $okOn += $srv }
                else { $wrongOn += ("{0} (-> {1})" -f $srv, $got) }
            }
        }
        $unansweredNote = ''
        if (@($view.Unanswered).Count -gt 0) { $unansweredNote = (' {0} server(s) did not answer: {1}.' -f @($view.Unanswered).Count, ($view.Unanswered -join ', ')) }
        if (@($missingOn).Count -eq 0 -and @($wrongOn).Count -eq 0) {
            $rows += New-Finding -Area 'DsaCname' -Item ("DSA GUID CNAME for {0}" -f $dcHost) -Status $script:Status.Pass -Detail ("{0} -> {1} consistent on all {2} answering DNS server(s).{3}" -f $alias, $expected, @($okOn).Count, $unansweredNote)
        }
        else {
            $bits = @()
            if (@($missingOn).Count -gt 0) { $bits += ("MISSING on: {0}" -f ($missingOn -join ', ')) }
            if (@($wrongOn).Count -gt 0) { $bits += ("WRONG HOST on: {0} (expected {1})" -f ($wrongOn -join ', '), $expected) }
            if (@($okOn).Count -gt 0) { $bits += ("correct on: {0}" -f ($okOn -join ', ')) }
            $rows += New-Finding -Area 'DsaCname' -Item ("DSA GUID CNAME for {0}" -f $dcHost) -Status $script:Status.Fail -Detail ("{0}: {1}.{2} Inbound replication from this DC fails wherever the alias is absent or wrong." -f $alias, ($bits -join '; '), $unansweredNote)
        }
    }
    return @($rows)
}

function Get-AdfaGcConsistency {
    <#
    .SYNOPSIS
        Compares the Global Catalog set Active Directory believes in (forest
        GlobalCatalogs) against what each DNS server advertises under _gc._tcp.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$ForestRoot,
        [hashtable]$AdParams = @{},
        [AllowEmptyCollection()][string[]]$DnsServers = @()
    )
    $rows = @()
    $gcs = @()
    try { $gcs = @((Get-ADForest @AdParams).GlobalCatalogs) }
    catch {
        $rows += New-Finding -Area 'GcConsistency' -Item 'GC list from AD' -Status $script:Status.NotAssessed -Detail $_.Exception.Message
        return @($rows)
    }

    $rec = "_gc._tcp.{0}" -f $ForestRoot
    $view = Get-AdfaDnsRecordView -Name $rec -Type SRV -DnsServers $DnsServers
    if (-not $view.ToolAvailable) {
        $rows += New-Finding -Area 'GcConsistency' -Item ("SRV {0}" -f $rec) -Status $script:Status.NotAssessed -Detail $view.Error
        return @($rows)
    }
    if (@($view.Views.Keys).Count -eq 0) {
        $rows += New-Finding -Area 'GcConsistency' -Item ("SRV {0}" -f $rec) -Status $script:Status.NotAssessed -Detail ("No DNS server answered for {0} ({1} queried)." -f $rec, @($view.Unanswered).Count)
        return @($rows)
    }
    $sum = Compare-AdfaDnsServerView -AdHosts $gcs -ServerTargets $view.Views
    foreach ($ps in @($sum.PerServer | Where-Object { -not $_.Agrees })) {
        $bits = @()
        if (@($ps.StaleInDns).Count -gt 0) { $bits += ("advertised as GC but not a GC in AD (or gone): {0}" -f ((@($ps.StaleInDns) | Select-Object -First 8) -join ', ')) }
        if (@($ps.MissingFromDns).Count -gt 0) { $bits += ("GC in AD but not advertised: {0}" -f ((@($ps.MissingFromDns) | Select-Object -First 8) -join ', ')) }
        $rows += New-Finding -Area 'GcConsistency' -Item ("Global Catalogs on {0}" -f $ps.Server) -Status $script:Status.Fail -Detail ($bits -join '; ')
    }
    $unansweredNote = ''
    if (@($view.Unanswered).Count -gt 0) { $unansweredNote = (' {0} server(s) did not answer: {1}.' -f @($view.Unanswered).Count, ($view.Unanswered -join ', ')) }
    if (@($sum.DivergentServers).Count -eq 0) {
        $rows += New-Finding -Area 'GcConsistency' -Item ("SRV {0}" -f $rec) -Status $script:Status.Pass -Detail ("All {0} answering DNS server(s) agree with AD ({1} GC(s)).{2}" -f $sum.ServersQueried, @($gcs).Count, $unansweredNote)
    }
    else {
        $rows += New-Finding -Area 'GcConsistency' -Item ("SRV {0} - divergence summary" -f $rec) -Status $script:Status.Fail -Detail ("{0} of {1} answering DNS server(s) diverge from AD: {2}. Forest-wide logons and Exchange address-book lookups behave differently per DNS server.{3}" -f @($sum.DivergentServers).Count, $sum.ServersQueried, ($sum.DivergentServers -join ', '), $unansweredNote)
    }
    return @($rows)
}

# ===========================================================================
# region _msdcs delegation, time hierarchy, per-site GC coverage
# ===========================================================================

function Get-AdfaDnsNameNormalised {
    <#
    .SYNOPSIS
        Lower-cases a DNS name and strips the root dot, so two spellings of the same name
        compare equal. Separate and tested because every comparison below depends on it and
        a mismatch here reads as a missing record.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][string]$Name)
    if ($null -eq $Name) { return '' }
    return ([string]$Name).Trim().TrimEnd('.').ToLowerInvariant()
}

function Get-AdfaMsdcsZoneVerdict {
    <#
    .SYNOPSIS
        Pure classification of whether _msdcs.<forest> is a delegated zone of its own.
    .DESCRIPTION
        The forest-wide locator records live in a zone of their own, replicated to every DNS
        server in the forest through the forest-wide DNS application directory partition:
        "Configure the zone containing the Active Directory forest-wide locator records (that
        is, the _msdcs.forestname zone) to replicate to every DNS server in the forest by using
        the forest-wide DNS application directory partition."
        https://learn.microsoft.com/windows-server/identity/ad-ds/plan/integrating-ad-ds-into-an-existing-dns-infrastructure

        The discriminator is which zone answers an SOA query for the name. If _msdcs.<forest> is
        its own zone, that zone's apex answers. If it is only a subdomain of the parent zone -
        the pre-delegation arrangement, and a state a hand-rebuilt DNS server after a recovery
        can easily be left in - the PARENT apex answers instead. Both spellings are compared
        normalised, so a trailing dot or capitalisation never decides the verdict.
    .OUTPUTS
        [string] DelegatedZone | NotDelegated | OtherApex | NoAnswer
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$ZoneName,
        [Parameter(Mandatory)][string]$ParentZone,
        [AllowEmptyCollection()][string[]]$SoaApex = @()
    )
    $apex = @(@($SoaApex) | ForEach-Object { Get-AdfaDnsNameNormalised -Name $_ } | Where-Object { $_ })
    if ($apex.Count -eq 0) { return 'NoAnswer' }
    $want = Get-AdfaDnsNameNormalised -Name $ZoneName
    $parent = Get-AdfaDnsNameNormalised -Name $ParentZone
    if ($apex -contains $want) { return 'DelegatedZone' }
    if ($apex -contains $parent) { return 'NotDelegated' }
    return 'OtherApex'
}

function Get-AdfaMsdcsDelegationVerdict {
    <#
    .SYNOPSIS
        Pure verdict on the _msdcs.<forest> delegation, from one observation per DNS server.
    .DESCRIPTION
        Three separable failures, each its own row, because they have different fixes:

        1. _msdcs.<forest> is not a zone in its own right (see Get-AdfaMsdcsZoneVerdict).
        2. The parent zone carries no delegation records for it. The forest recovery guide's
           DNS step is explicit: "Ensure that the parent DNS zone contains delegation resource
           records (name server (NS) and glue host (A) resource records) for the child zone that
           is hosted on this DNS server."
           https://learn.microsoft.com/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-configure-dns
        3. An NS record has no glue A record, so the name in it cannot be resolved to an address
           and the referral is a dead end. The vendor names both halves as one requirement: the
           NS record "to effect the delegation", and "a host (A or AAAA) resource record, which
           is also known as a glue record. This record must be present to resolve the name of
           the server that's specified in the NS resource record to its IP address."
           https://learn.microsoft.com/windows-server/identity/ad-ds/deploy/ad-ds-installation-and-removal-wizard-page-descriptions

        Plus a fourth row that is a recovery artefact rather than a delegation fault: NS records
        naming hosts that are not domain controllers Active Directory knows about. The recovery
        guide instructs "In the _msdcs and domain DNS zones, delete NS records of DCs that no
        longer exist after metadata cleanup" - stale NS records after a rebuild send resolvers to
        servers that are gone.
        https://learn.microsoft.com/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-perform-initial-recovery
        Read: 2026-09-22.

        Every row is per DNS server rather than merged, for the same reason the rest of this
        report queries each server separately: the zone is AD-integrated, so with replication
        broken the answer genuinely differs between servers and one answer is not forest truth.
        A host that is not a DC is a Warning, not a Fail, because a non-DC DNS server can
        legitimately be authoritative - the finding says what to confirm, it does not assert a
        fault.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$ForestRoot,
        # One object per answering DNS server: Server, SoaApex, NsTargets, GlueMissing,
        # GlueUnknown. Supplied by the collector so this verdict needs no directory or resolver.
        [AllowNull()][AllowEmptyCollection()]$Observations = @(),
        [AllowEmptyCollection()][string[]]$AdDcHosts = @(),
        [AllowEmptyCollection()][string[]]$Unanswered = @(),
        # PORT-PLAN C2e: scoped domains whose DCs are missing from -AdDcHosts (their enumeration threw or
        # returned no DC). With any named, an NS host missing from -AdDcHosts may be one of their DCs,
        # so it is Not Assessed naming them, never "not a known DC".
        [AllowNull()][AllowEmptyCollection()][string[]]$IncompleteDomains = @()
    )
    $zone = "{0}.{1}" -f $script:Config.MsdcsZoneLabel, $ForestRoot
    $rows = @()
    $incomplete = @(@($IncompleteDomains) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { ([string]$_).Trim() } | Sort-Object -Unique)
    $obs = @(@($Observations) | Where-Object { $null -ne $_ })
    $unansweredNote = ''
    if (@($Unanswered).Count -gt 0) {
        $unansweredNote = (' {0} DNS server(s) did not answer and are unverified, not clean: {1}.' -f @($Unanswered).Count, (@($Unanswered) -join ', '))
    }
    if ($obs.Count -eq 0) {
        return @(New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation" -f $zone) -Status $script:Status.NotAssessed `
                -Detail ("No DNS server answered for {0}, so nothing can be concluded about the forest-wide locator zone or its delegation.{1}" -f $zone, $unansweredNote))
    }

    $knownDcs = @(@($AdDcHosts) | ForEach-Object { Get-AdfaDnsNameNormalised -Name $_ } | Where-Object { $_ })

    $apexOk = @(); $apexNotDelegated = @(); $apexOther = @(); $apexNoAnswer = @()
    $noNs = @(); $glueBad = @(); $glueUnknown = @(); $notDcs = @()
    foreach ($o in $obs) {
        $server = '(unnamed)'
        $sProp = $o.PSObject.Properties['Server']          # $null when absent - StrictMode-safe
        if ($null -ne $sProp -and $null -ne $sProp.Value) { $server = [string]$sProp.Value }

        $apexVals = @()
        $aProp = $o.PSObject.Properties['SoaApex']
        if ($null -ne $aProp -and $null -ne $aProp.Value) { $apexVals = @($aProp.Value) }
        switch (Get-AdfaMsdcsZoneVerdict -ZoneName $zone -ParentZone $ForestRoot -SoaApex $apexVals) {
            'DelegatedZone' { $apexOk += $server }
            'NotDelegated' { $apexNotDelegated += $server }
            'OtherApex' { $apexOther += ("{0} (apex: {1})" -f $server, ((@($apexVals) | Select-Object -First 2) -join ', ')) }
            default { $apexNoAnswer += $server }
        }

        $ns = @()
        $nProp = $o.PSObject.Properties['NsTargets']
        if ($null -ne $nProp -and $null -ne $nProp.Value) { $ns = @(@($nProp.Value) | Where-Object { $_ }) }
        if ($ns.Count -eq 0) { $noNs += $server }

        $gm = @()
        $gProp = $o.PSObject.Properties['GlueMissing']
        if ($null -ne $gProp -and $null -ne $gProp.Value) { $gm = @(@($gProp.Value) | Where-Object { $_ }) }
        if ($gm.Count -gt 0) { $glueBad += ("{0} -> {1}" -f $server, ($gm -join ', ')) }

        $gu = @()
        $uProp = $o.PSObject.Properties['GlueUnknown']
        if ($null -ne $uProp -and $null -ne $uProp.Value) { $gu = @(@($uProp.Value) | Where-Object { $_ }) }
        if ($gu.Count -gt 0) { $glueUnknown += ("{0} -> {1}" -f $server, ($gu -join ', ')) }

        if ($knownDcs.Count -gt 0) {
            $strays = @(@($ns) | Where-Object { $knownDcs -notcontains (Get-AdfaDnsNameNormalised -Name $_) })
            if ($strays.Count -gt 0) { $notDcs += ("{0} -> {1}" -f $server, ($strays -join ', ')) }
        }
    }

    # 1. Is it a zone of its own?
    if (@($apexNotDelegated).Count -gt 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} is not a delegated zone" -f $zone) -Status $script:Status.Fail `
            -Detail ("On {0} of {1} answering DNS server(s) an SOA query for {2} is answered by the PARENT zone {3}, which means {2} is a plain subdomain there rather than the forest-wide locator zone. Servers: {4}. The forest-wide locator records must live in their own AD-integrated zone replicated to every DNS server in the forest through the forest-wide DNS application directory partition.{5}" -f `
                @($apexNotDelegated).Count, $obs.Count, $zone, $ForestRoot, (@($apexNotDelegated) -join ', '), $unansweredNote)
    }
    if (@($apexOther).Count -gt 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} answered by an unexpected zone" -f $zone) -Status $script:Status.Fail `
            -Detail ("An SOA query for {0} was answered by neither {0} nor {1} on: {2}. Something other than this forest's DNS is authoritative for the forest-wide locator name on those servers." -f `
                $zone, $ForestRoot, (@($apexOther) -join '; '))
    }
    if (@($apexNoAnswer).Count -gt 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} zone - SOA not readable" -f $zone) -Status $script:Status.NotAssessed `
            -Detail ("No SOA answer for {0} from: {1}. Whether the locator zone is delegated is UNKNOWN on those servers, not clean." -f $zone, (@($apexNoAnswer) -join ', '))
    }
    if (@($apexOk).Count -gt 0 -and @($apexNotDelegated).Count -eq 0 -and @($apexOther).Count -eq 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} is a delegated zone" -f $zone) -Status $script:Status.Pass `
            -Detail ("{0} of {1} answering DNS server(s) report {2} as its own authoritative zone.{3}" -f @($apexOk).Count, $obs.Count, $zone, $unansweredNote)
    }

    # 2. Delegation NS records in the parent.
    if (@($noNs).Count -gt 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - no NS records" -f $zone) -Status $script:Status.Fail `
            -Detail ("No NS record for {0} on {1} of {2} answering DNS server(s): {3}. Without a delegation NS record a resolver cannot be referred to the forest-wide locator zone, which is how replication partners and clients find global catalog servers." -f `
                $zone, @($noNs).Count, $obs.Count, (@($noNs) -join ', '))
    }
    else {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - NS records present" -f $zone) -Status $script:Status.Pass `
            -Detail ("Every one of the {0} answering DNS server(s) returned at least one NS record for {1}.{2}" -f $obs.Count, $zone, $unansweredNote)
    }

    # 3. Glue behind each NS record.
    if (@($glueBad).Count -gt 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - missing glue records" -f $zone) -Status $script:Status.Fail `
            -Detail ("NS records for {0} name hosts with no resolvable glue (A) record: {1}. A delegation needs both the NS record and the glue host record; without the glue the referral cannot be followed to an address." -f `
                $zone, (@($glueBad) -join '; '))
    }
    elseif (@($glueUnknown).Count -eq 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - glue records resolvable" -f $zone) -Status $script:Status.Pass `
            -Detail ("Every NS target returned for {0} resolved to an address on the server that named it." -f $zone)
    }
    if (@($glueUnknown).Count -gt 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - glue not readable" -f $zone) -Status $script:Status.NotAssessed `
            -Detail ("The glue record behind these NS targets could not be queried (the server did not answer, so absence cannot be distinguished from silence): {0}. Unverified, not clean." -f (@($glueUnknown) -join '; '))
    }

    # 4. NS records naming hosts AD does not know as DCs.
    if (@($notDcs).Count -gt 0 -and $incomplete.Count -gt 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - NS hosts not cross-checked" -f $zone) -Status $script:Status.NotAssessed `
            -Detail ("NS records for {0} name hosts that are not among the {1} domain controller(s) listed in this run: {2}. The domain controllers of {3} could not be listed (the enumeration failed or returned none), so each of these hosts may be one of theirs: whether any is a stale NS record is not known. This is not a clean result." -f `
                $zone, $knownDcs.Count, (@($notDcs) -join '; '), ($incomplete -join ', '))
    }
    elseif (@($notDcs).Count -gt 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - NS host not a known DC" -f $zone) -Status $script:Status.Warning `
            -Detail ("NS records for {0} name hosts that are not domain controllers in this forest's inventory: {1}. After a recovery with metadata cleanup, NS records of DCs that no longer exist must be deleted, or resolvers keep being referred to servers that are gone. Confirm each host above is a DNS server you intend to be authoritative for this zone; if it is a decommissioned DC, remove the record." -f `
                $zone, (@($notDcs) -join '; '))
    }
    elseif ($knownDcs.Count -eq 0) {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - NS hosts not cross-checked" -f $zone) -Status $script:Status.NotAssessed `
            -Detail ("No domain controller inventory was available, so the NS records for {0} were not compared against the DCs Active Directory knows about. Stale NS records left by a metadata cleanup would not have been detected." -f $zone)
    }
    else {
        $rows += New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation - NS hosts are known DCs" -f $zone) -Status $script:Status.Pass `
            -Detail ("Every NS host returned for {0} matches one of the {1} domain controller(s) in this forest's inventory." -f $zone, $knownDcs.Count)
    }
    return @($rows)
}

function Get-AdfaMsdcsDelegation {
    <#
    .SYNOPSIS
        Collects the _msdcs.<forest> delegation as each DNS server sees it, then classifies.
    .DESCRIPTION
        Thin collector over Get-AdfaMsdcsDelegationVerdict. Three query types per DNS server:
        SOA for the zone name (which zone is authoritative), NS for the zone name (the
        delegation records), and one A query per NS target ON THE SAME SERVER (the glue). Glue
        is queried from the server that named the target, because that is the referral a
        resolver using that server would actually have to follow.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$ForestRoot,
        [AllowEmptyCollection()][string[]]$DnsServers = @(),
        [AllowEmptyCollection()][string[]]$AdDcHosts = @(),
        # PORT-PLAN C2e: scoped domains whose DCs are missing from -AdDcHosts (their enumeration threw or
        # returned no DC). Passed to the verdict, which then does not call an NS host "not a known DC".
        [AllowNull()][AllowEmptyCollection()][string[]]$IncompleteDomains = @()
    )
    $zone = "{0}.{1}" -f $script:Config.MsdcsZoneLabel, $ForestRoot
    $soaView = Get-AdfaDnsRecordView -Name $zone -Type SOA -DnsServers $DnsServers
    if (-not $soaView.ToolAvailable) {
        return @(New-Finding -Area 'MsdcsDelegation' -Item ("{0} delegation" -f $zone) -Status $script:Status.NotAssessed -Detail $soaView.Error)
    }
    $nsView = Get-AdfaDnsRecordView -Name $zone -Type NS -DnsServers $DnsServers

    # Every server that answered either query is worth an observation: a server that answers NS
    # but not SOA still tells us about the delegation records, and vice versa.
    $servers = @(@(@($soaView.Views.Keys) + @($nsView.Views.Keys)) | Where-Object { $_ } | Sort-Object -Unique)
    $unanswered = @(@($soaView.Unanswered) | Where-Object { $servers -notcontains $_ } | Sort-Object -Unique)

    $observations = @()
    foreach ($srv in $servers) {
        $apex = @()
        if ($soaView.Views.ContainsKey($srv)) { $apex = @($soaView.Views[$srv]) }
        $ns = @()
        if ($nsView.Views.ContainsKey($srv)) { $ns = @(@($nsView.Views[$srv]) | Where-Object { $_ }) }

        $missing = @()
        $unknown = @()
        foreach ($target in $ns) {
            # '(local resolver)' is this collector's own label for a query with no -Server, so it
            # must not be passed back as a server name.
            $glue = $null
            if ($srv -eq '(local resolver)') { $glue = Resolve-AdfaDnsRecord -Name $target -Type A }
            else { $glue = Resolve-AdfaDnsRecord -Name $target -Type A -Server $srv }
            if ($glue.Outcome -eq 'Resolved') { continue }
            if ($glue.Outcome -eq 'NoRecord') { $missing += $target }
            else { $unknown += $target }
        }
        $observations += [pscustomobject]@{
            Server      = $srv
            SoaApex     = @($apex)
            NsTargets   = @($ns)
            GlueMissing = @($missing)
            GlueUnknown = @($unknown)
        }
    }
    return @(Get-AdfaMsdcsDelegationVerdict -ForestRoot $ForestRoot -Observations $observations `
            -AdDcHosts $AdDcHosts -Unanswered $unanswered -IncompleteDomains @($IncompleteDomains))
}

function ConvertFrom-AdfaW32tmConfiguration {
    <#
    .SYNOPSIS
        Pure, tolerant parse of "w32tm /query /configuration" for the NTP client Type and
        NtpServer values.
    .DESCRIPTION
        The KEY NAMES are published - Type takes NoSync, NTP, NT5DS or AllSync, and NtpServer
        holds the peer list - but the LINE FORMAT of this command's output is not published on
        Microsoft Learn. So the parser is deliberately tolerant of leading whitespace and of a
        trailing "(Local)" / "(Policy)" source annotation, and an unmatched key is returned as
        '' rather than assumed. A caller must treat '' as "not read", never as a value.
        https://learn.microsoft.com/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings
        Read: 2026-09-22.
    .OUTPUTS
        [pscustomobject] Type (string), NtpServer (string)
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][string]$Text)
    $type = ''
    $peers = ''
    foreach ($line in (("$Text") -split "`r?`n")) {
        if ($type -eq '' -and $line -match '^\s*Type:\s*(\S+)') { $type = $Matches[1] }
        elseif ($peers -eq '' -and $line -match '^\s*NtpServer:\s*(.+?)\s*$') { $peers = $Matches[1] }
    }
    # Strip the source annotation the command appends to each value, when present.
    $type = ($type -replace '\((?i:local|policy)\)\s*$', '').Trim()
    $peers = ($peers -replace '\s*\((?i:local|policy)\)\s*$', '').Trim()
    return [pscustomobject]@{ Type = $type; NtpServer = $peers }
}

function Get-AdfaTimeSourceVerdict {
    <#
    .SYNOPSIS
        Pure verdict on one domain controller's time source.
    .DESCRIPTION
        Two documented rules, and nothing invented beyond them.

        (1) The forest root PDC emulator sits at the TOP of the domain time hierarchy, so
        synchronising it from that hierarchy is not valid - W32Time logs event ID 12 for exactly
        this condition - and it should take time from an external authoritative source.
        https://learn.microsoft.com/services-hub/microsoft-engage-center/health/remediation-steps-ad/configure-the-root-pdc-with-an-authoritative-time-source-and-avoid-widespread-time-skew
        Which is why a root PDC whose reported source is one of this forest's own DCs is a
        finding, while any other host is taken as an external source.

        (2) A domain controller that takes time from its virtualisation host has TWO time
        sources, and the vendor is explicit about the consequence: "If domain controllers
        synchronize time from their own source and synchronize time from the host, the domain
        controller time can change frequently. Because many domain controller tasks are tied to
        the system time, a jump in the system time can cause lingering objects to be left in
        caches, and may cause replication to stop." The published fix is to clear Time
        Synchronization in the VM's Integration Services.
        https://learn.microsoft.com/troubleshoot/windows-server/active-directory/windows-time-service-event-ids-24-29-38

        Microsoft's guidance diverges for the PDC specifically - the Windows Server 2016 timekeeping
        guidance says "For the PDC, you don't want to disable the entry because the Hyper-V host
        delivers the most stable time source" - so on the root PDC this is reported as a decision
        to confirm with both positions named, not as a defect.
        https://learn.microsoft.com/windows-server/networking/windows-time-service/windows-server-2016-improvements#best-practices-for-accurate-timekeeping
        Read: 2026-09-22.

        Grading note: a host-supplied or free-running clock is a Warning rather than a Fail
        because the clock may still be correct - what is wrong is where it comes from. Kerberos
        breaks on the resulting skew, not on the configuration, and this function measures the
        configuration. It never returns Pass for a source it could not read.
    .OUTPUTS
        [pscustomobject] A single finding row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [string]$Scope = '',
        [bool]$IsPdcEmulator = $false,
        [bool]$IsForestRootPdc = $false,
        [bool]$Queried = $true,
        [string]$Source = '',
        [string]$ErrorText = '',
        [AllowEmptyCollection()][string[]]$DomainControllerHosts = @()
    )
    $role = 'domain controller'
    if ($IsForestRootPdc) { $role = 'FOREST ROOT PDC emulator' }
    elseif ($IsPdcEmulator) { $role = 'domain PDC emulator' }
    $item = ("Time source on {0} ({1})" -f $DomainController, $role)

    if (-not $Queried) {
        $why = 'the host was not reachable for a w32tm query'
        if ($ErrorText) { $why = $ErrorText }
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.NotAssessed `
            -Detail ("The time source could not be read: {0}. Note that w32tm requires Domain Admins membership to query a remote computer, so an access failure here is about rights or reachability, not about the DC's clock - nothing can be concluded either way." -f $why)
    }
    $src = ("$Source").Trim()
    if ([string]::IsNullOrWhiteSpace($src)) {
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.NotAssessed `
            -Detail 'w32tm returned no time source line, so the source is unknown. This is not a clean result.'
    }

    if ($src -match $script:Config.Time.HypervisorPattern) {
        if ($IsForestRootPdc) {
            return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Warning `
                -Detail ("Source is the virtualisation host's time provider ('{0}'). Microsoft's guidance is split for this role specifically: KB 976924 says to clear Time Synchronization in Integration Services on a virtualised DC because a DC with two time sources can jump, leave lingering objects in caches and stop replicating, while the Windows Server 2016 timekeeping guidance says not to disable it on the PDC because the host is the most stable source. Decide deliberately and record the decision - and note that on a DC restored from backup or a snapshot, the host clock is exactly how a wrong forest-wide time arrives. If the host is kept as the source, the host itself must be synchronised to the same authoritative source." -f $src)
        }
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Warning `
            -Detail ("Source is the virtualisation host's time provider ('{0}') rather than the domain hierarchy. Per KB 976924 a DC that synchronises from both its own source and its host can have its time change frequently, which 'can cause lingering objects to be left in caches, and may cause replication to stop' - both of which this report checks for elsewhere. Clear Time Synchronization in the VM's Integration Services and let W32Time use the domain hierarchy." -f $src)
    }

    if ($src -match $script:Config.Time.LocalClockPattern) {
        if ($IsForestRootPdc) {
            return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Warning `
                -Detail ("Source is this machine's own clock ('{0}'), so the forest has NO authoritative upstream time: every domain member ultimately derives its time from this BIOS clock, and if this DC goes offline members cannot synchronise at all. Point the forest root PDC emulator at an external authoritative NTP source." -f $src)
        }
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Warning `
            -Detail ("Source is this machine's own clock ('{0}'), which means it is not synchronising from the domain hierarchy at all. This can also be reported transiently just after the W32Time service starts, so confirm it persists - then fix it, because Kerberos rejects a ticket whose timestamp is outside the permitted skew." -f $src)
    }

    $srcHost = Get-AdfaDnsNameNormalised -Name ($src -replace ',.*$', '')
    $known = @(@($DomainControllerHosts) | ForEach-Object { Get-AdfaDnsNameNormalised -Name $_ } | Where-Object { $_ })
    $sourceIsDc = ($known -contains $srcHost)

    if ($IsForestRootPdc) {
        if ($sourceIsDc) {
            return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Warning `
                -Detail ("Source is '{0}', which is a domain controller in this forest - so the forest root PDC emulator is taking time from the domain hierarchy it is itself the top of. Microsoft states this is not a valid configuration and W32Time logs event ID 12 for it. Configure an external authoritative source: 'w32tm /config /syncfromflags:manual /manualpeerlist:<ntp host>,0x8 /reliable:yes /update'." -f $src)
        }
        if ($known.Count -eq 0) {
            return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.NotAssessed `
                -Detail ("Source is '{0}', but with no domain controller inventory available it could not be established whether that is an external source or one of this forest's own DCs - and only the latter is a fault for this role. Unverified, not clean." -f $src)
        }
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Pass `
            -Detail ("Source is '{0}', which is not a domain controller in this forest, so the forest root PDC emulator is taking time from outside the domain hierarchy as it should. This check does not verify that the source is accurate or that the last synchronisation succeeded." -f $src)
    }
    if ($sourceIsDc) {
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Pass `
            -Detail ("Source is '{0}', a domain controller in this forest, which is the expected NT5DS domain-hierarchy behaviour for this role." -f $src)
    }
    return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Info `
        -Detail ("Source is '{0}', which is not a domain controller in this forest. Microsoft's documented norm is that every DC except the forest root PDC emulator synchronises from the domain hierarchy, so this is a deliberate deviation rather than a fault - common where all DCs are pointed at a network time appliance. Confirm it was intended, and that the appliance and the root PDC agree." -f $src)
}

function Get-AdfaRootPdcClientTypeVerdict {
    <#
    .SYNOPSIS
        Pure verdict on the forest root PDC emulator's W32Time client type.
    .DESCRIPTION
        Complements Get-AdfaTimeSourceVerdict, which reads the source in effect; this reads the
        configured intent. NT5DS means "the time service synchronizes with the domain hierarchy",
        which is the configuration Microsoft calls invalid for this role. NoSync means the service
        does not synchronise at all. NTP and AllSync name an explicit peer list.
        https://learn.microsoft.com/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings
        Read: 2026-09-22.

        An unparsed value is Not Assessed, never a pass: the key names are published but this
        command's line format is not, so a non-match means the parser did not recognise the
        output, which says nothing about the configuration.
    .OUTPUTS
        [pscustomobject] A single finding row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [string]$Scope = '',
        [string]$ClientType = '',
        [string]$NtpServer = ''
    )
    $item = ("Forest root PDC time client type on {0}" -f $DomainController)
    $t = ("$ClientType").Trim()
    if ([string]::IsNullOrWhiteSpace($t)) {
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.NotAssessed `
            -Detail "The W32Time client Type could not be read from 'w32tm /query /configuration'. The key name is documented but the output line format is not published, so this means the value was not recognised - not that it is wrong. Read it on the DC itself, or from HKLM\SYSTEM\CurrentControlSet\Services\W32Time\Parameters."
    }
    $peerNote = ' No NtpServer peer list was read.'
    if (-not [string]::IsNullOrWhiteSpace($NtpServer)) { $peerNote = (" Peer list: {0}." -f ("$NtpServer").Trim()) }

    if ($t -eq $script:Config.Time.DomainHierarchyType) {
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Warning `
            -Detail ("Type is {0}, which means this DC synchronises with the domain hierarchy - and it is the top of that hierarchy. Microsoft states this is not a valid configuration for the forest root PDC emulator and that W32Time logs event ID 12 for it. Configure an external source with 'w32tm /config /syncfromflags:manual /manualpeerlist:<ntp host>,0x8 /reliable:yes /update', then restart W32Time.{1}" -f $t, $peerNote)
    }
    if ($t -match '(?i)^NoSync$') {
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Warning `
            -Detail ("Type is NoSync, so the time service does not synchronise with any source on the DC that the whole forest's time derives from. Its clock will drift freely.{0}" -f $peerNote)
    }
    if (@($script:Config.Time.ExternalTypes) -contains $t) {
        if ([string]::IsNullOrWhiteSpace($NtpServer)) {
            return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.NotAssessed `
                -Detail ("Type is {0}, which names an explicit peer list - but no NtpServer value was read, so it is unknown whether a peer is actually configured. Unverified, not clean." -f $t)
        }
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Pass `
            -Detail ("Type is {0} with an explicit peer list, which is the documented configuration for the forest root PDC emulator.{1} This check does not verify the peer is reachable or accurate." -f $t, $peerNote)
    }
    return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.NotAssessed `
        -Detail ("Type read as '{0}', which is not one of the documented values (NoSync, NTP, NT5DS, AllSync), so it was not interpreted.{1}" -f $t, $peerNote)
}

function ConvertFrom-AdfaStripchartCsv {
    <#
    .SYNOPSIS
        Pure parse of 'w32tm /stripchart /rdtsc' CSV output into offset samples.
    .DESCRIPTION
        This is the ONLY external-tool output in this whole tool whose format Microsoft actually
        publishes, and it is used for exactly that reason. Every other parser here matches
        console text that the vendor never documented, which is why they all have to degrade to
        Not Assessed on a wording or locale change.

        "/rdtsc: For each sample, prints comma-separated values along with the headers
         RdtscStart, RdtscEnd, FileTime, RoundtripDelay, and NtpOffset instead of the text
         graphic."
          - NtpOffset: "The time offset in seconds between the local computer and the NTP
            server, computed as per NTP offset computations."
          - RoundtripDelay: "The time elapsed in seconds between generating the NTP request and
            processing the received NTP response."
        https://learn.microsoft.com/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings
        Read: 2026-09-22.

        The header row is located by name rather than assumed to be first, because w32tm prints
        a line about the tracked computer before it. A row whose NtpOffset will not parse as a
        number is DROPPED rather than coerced: "Request timed out." appears in this stream on an
        unreachable target, and reading that as an offset of zero would report a dead DC as
        perfectly synchronised.
    .OUTPUTS
        [pscustomobject] Offsets (double[]), Delays (double[]), RowsSeen (int), RowsParsed (int)
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][string]$Text)
    $lines = @(("$Text") -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    $offsets = @()
    $delays = @()
    $rowsSeen = 0
    $headerIdx = -1
    $offCol = -1
    $delCol = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $cols = @($lines[$i] -split ',' | ForEach-Object { $_.Trim() })
        # Match the documented header names, case-insensitively. A plain index loop rather than
        # [array]::FindIndex with a [Predicate[T]] cast: scriptblock-to-delegate conversion is
        # not something this script can verify on the Windows PowerShell 5.1 floor it targets,
        # and there is nothing here worth that risk.
        $o = -1
        $d = -1
        for ($c = 0; $c -lt $cols.Count; $c++) {
            if ($cols[$c] -match '(?i)^NtpOffset$') { $o = $c }
            elseif ($cols[$c] -match '(?i)^RoundtripDelay$') { $d = $c }
        }
        if ($o -ge 0) { $headerIdx = $i; $offCol = $o; $delCol = $d; break }
    }
    if ($headerIdx -lt 0) {
        return [pscustomobject]@{ Offsets = @(); Delays = @(); RowsSeen = 0; RowsParsed = 0 }
    }
    for ($i = $headerIdx + 1; $i -lt $lines.Count; $i++) {
        $cols = @($lines[$i] -split ',' | ForEach-Object { $_.Trim() })
        if ($cols.Count -le $offCol) { continue }
        $rowsSeen++
        $val = 0.0
        # 'Request timed out.' lands in this stream for an unreachable target. Dropping the row
        # is the only safe reading: coercing it would report a dead DC as perfectly in sync.
        if (-not [double]::TryParse($cols[$offCol], [ref]$val)) { continue }
        $offsets += [double]$val
        if ($delCol -ge 0 -and $cols.Count -gt $delCol) {
            $dv = 0.0
            if ([double]::TryParse($cols[$delCol], [ref]$dv)) { $delays += [double]$dv }
        }
    }
    return [pscustomobject]@{
        Offsets = @($offsets); Delays = @($delays)
        RowsSeen = [int]$rowsSeen; RowsParsed = [int]@($offsets).Count
    }
}

function Get-AdfaClockOffsetVerdict {
    <#
    .SYNOPSIS
        Pure verdict on one DC's measured clock offset.
    .DESCRIPTION
        Closes the gap H8 left open and admitted to: that section reports where a DC takes time
        FROM, and says in its own detail that it "does not verify that the source is accurate".
        A DC can have a perfect source and still be minutes out, and Kerberos fails on the skew,
        not on the configuration.

        Two thresholds, and the finding is explicit about which is whose. 300 seconds is
        Microsoft's documented Kerberos maximum. The warning threshold below it is OURS: 300 is
        the cliff at which authentication stops, not a level to sit at, and a DC past a minute is
        already not keeping time.

        What this deliberately does NOT claim: that the forest's time is CORRECT. The offset is
        measured from the host running the assessment, so it reports divergence between that host
        and each DC. If the measuring host is itself wrong, every DC agreeing with it still reads
        clean - which is why the detail names the reference rather than leaving it implied.
    .OUTPUTS
        [pscustomobject] A single finding row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [string]$Scope = '',
        [string]$ReferenceHost = '(this host)',
        [bool]$Queried = $true,
        [AllowNull()][object[]]$Offsets = @(),
        [string]$ErrorText = '',
        [double]$WarnSeconds = 60,
        [double]$FailSeconds = 300
    )
    $item = ("Clock offset on {0}" -f $DomainController)
    if (-not $Queried) {
        $why = 'the host was not reachable for an NTP sample'
        if ($ErrorText) { $why = $ErrorText }
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.NotAssessed `
            -Detail ("The clock offset could not be measured: {0}. Nothing can be concluded about this DC's time - an unmeasured offset is not a small one." -f $why)
    }
    $vals = @(@($Offsets) | Where-Object { $_ -is [double] -or $_ -is [int] -or $_ -is [decimal] } | ForEach-Object { [double]$_ })
    if ($vals.Count -eq 0) {
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.NotAssessed `
            -Detail ("w32tm returned no usable NTP offset sample for this DC{0}. A sample that did not parse is discarded rather than read as zero, because zero would mean 'perfectly synchronised'." -f $(if ($ErrorText) { ": $ErrorText" } else { '' }))
    }
    # The worst sample, not the mean: a clock that swings is a clock that is not disciplined,
    # and averaging a +4s and a -4s sample would report it as perfect.
    $worst = 0.0
    foreach ($v in $vals) { if ([Math]::Abs($v) -gt [Math]::Abs($worst)) { $worst = $v } }
    $abs = [Math]::Abs($worst)
    $sampleNote = ("{0} sample(s), worst {1:0.###}s" -f $vals.Count, $worst)
    $refNote = ("Measured from {0}, so this is divergence between that host and this DC - not proof the forest's time is correct." -f $ReferenceHost)

    if ($abs -ge $FailSeconds) {
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Fail `
            -Detail ("Offset is {0:0.###}s ({1}), at or beyond the {2}s Kerberos maximum time skew Microsoft documents. Authentication against this DC fails outright at this offset, and every timestamp it writes - replication metadata included - is wrong by that much. {3}" -f `
                $worst, $sampleNote, $FailSeconds, $refNote)
    }
    if ($abs -ge $WarnSeconds) {
        return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Warning `
            -Detail ("Offset is {0:0.###}s ({1}). That is inside Microsoft's {2}s Kerberos limit but past the {3}s bar this tool sets, which is OURS and not a vendor threshold: {2}s is the cliff where authentication stops, not a level to run at, and a DC drifting this far is not being disciplined by its time source. {4}" -f `
                $worst, $sampleNote, $FailSeconds, $WarnSeconds, $refNote)
    }
    return New-Finding -Scope $Scope -Area 'TimeHierarchy' -Item $item -Status $script:Status.Pass `
        -Detail ("Offset is {0:0.###}s ({1}), within the {2}s bar this tool sets and well inside Microsoft's {3}s Kerberos maximum. {4}" -f `
            $worst, $sampleNote, $WarnSeconds, $FailSeconds, $refNote)
}

function Get-AdfaTimeHierarchyHealth {
    <#
    .SYNOPSIS
        Per-DC time source, with the PDC emulator roles resolved so the role-specific rules apply.
    .DESCRIPTION
        Thin collector over Get-AdfaTimeSourceVerdict and Get-AdfaRootPdcClientTypeVerdict.
        Uses the documented remote form 'w32tm /query /computer:<target> /source'; RPC (135) is
        probed first, through the shared port cache, so an unreachable DC reports Not Assessed rather
        than a missing source. A DC the C14 reachability probe classified Unreachable is not probed
        again: its time source and offset rows are Not Assessed with that cause.

        PORT-PLAN C14 (TIME-001): after the per-DC rows, every DC also gets a "Clock offset vs forest
        root PDC: <dc>" row, from the same stripchart samples, against the forest root PDC emulator's.
        When that PDC is not among the DCs asked, its stripchart is read once on its own. A DC the
        reachability probe classified Unreachable says so.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # DC rows (HostName, Scope) or plain host names (PORT-PLAN C2e).
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        # Hashtable of DC host name -> domain DNS name, for the PDC emulator of each domain.
        [hashtable]$PdcEmulators = @{},
        [string]$ForestRootPdc = '',
        [int]$RpcPortTimeoutMs = 1200,
        [int]$TimeoutSeconds = 60,
        [int]$SkewSamples = 3,
        [double]$WarnSeconds = 60,
        [double]$FailSeconds = 300,
        # Where the grades came from (ClockSkew ThresholdSource, the file's where it supplied one).
        [AllowEmptyString()][string]$ThresholdSource = '',
        # Domains whose DC enumeration threw (Domain, Error), and the domains of the run.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    # Named once so every offset finding can say what it measured against. The offset is relative
    # to THIS host; if this host's clock is wrong, every DC agreeing with it still reads clean.
    $refHost = [Environment]::MachineName
    # PORT-PLAN C2e: the DCs of every scoped domain, each with its domain; a scoped domain with no DC
    # row gets its own population row, and a DC with no host name its own row.
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    $population = @(Get-AdfaDcPopulationRow -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Area 'TimeHierarchy' `
            -Label 'Time hierarchy' -NothingRead 'No time source of its DCs was read.')
    $hostList = New-Object System.Collections.ArrayList
    $hostScopes = New-Object System.Collections.ArrayList
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        if ([string]::IsNullOrWhiteSpace([string]$named.HostName)) {
            $population += New-Finding -Scope ([string]$named.Scope) -Area 'TimeHierarchy' -Item 'Time source on (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so w32tm had nothing to query.'
            continue
        }
        [void]$hostList.Add([string]$named.HostName)
        [void]$hostScopes.Add([string]$named.Scope)
    }
    $DomainControllers = @($hostList.ToArray())
    if (@($DomainControllers).Count -eq 0) {
        if ($targets.Count -gt 0) { return @($population) }
        return @(@($population) + @(New-Finding -Area 'TimeHierarchy' -Item 'Time hierarchy' -Status $script:Status.NotAssessed `
                    -Detail 'No domain controllers were enumerated, so no time source could be read. This is not a clean result.'))
    }
    if (-not (Test-CommandAvailable -Name 'w32tm.exe')) {
        return @(@($population) + @(New-Finding -Area 'TimeHierarchy' -Item 'Time hierarchy' -Status $script:Status.NotAssessed `
                    -Detail 'w32tm.exe is not available on this host, so no domain controller time source could be queried. Run this assessment from a domain-joined Windows host with the Windows Time tools present.'))
    }
    $rootPdc = Get-AdfaDnsNameNormalised -Name $ForestRootPdc
    $pdcMap = @{}
    foreach ($k in @($PdcEmulators.Keys)) {
        $nk = Get-AdfaDnsNameNormalised -Name $k
        if ($nk) { $pdcMap[$nk] = [string]$PdcEmulators[$k] }
    }
    $rows = @()
    # PORT-PLAN C14: each DC's stripchart reading, kept for the forest-root-PDC offset rows below.
    $samplesByDc = @{}
    for ($hostIndex = 0; $hostIndex -lt @($DomainControllers).Count; $hostIndex++) {
        $dc = [string]@($DomainControllers)[$hostIndex]
        $norm = Get-AdfaDnsNameNormalised -Name $dc
        $isPdc = $pdcMap.ContainsKey($norm)
        $isRootPdc = ($rootPdc -ne '' -and $norm -eq $rootPdc)
        # The domain of the DC's own target where it carries one (PORT-PLAN C2e); otherwise, as before,
        # the domain whose PDC emulator it is.
        $scope = [string]$hostScopes[$hostIndex]
        if ($isPdc -and $scope -eq '') { $scope = [string]$pdcMap[$norm] }

        # PORT-PLAN C14: a DC the reachability probe classified Unreachable is not probed again; its
        # rows carry that cause, so a name that does not resolve is never reported as a silent port.
        $dcReachCause = Get-AdfaDcReachCause -HostName $dc
        if ($dcReachCause -ne '') {
            $samplesByDc[$norm] = [pscustomobject]@{ Queried = $false; Offsets = @(); Delays = @(); Error = $dcReachCause }
            $rows += Get-AdfaTimeSourceVerdict -DomainController $dc -Scope $scope -IsPdcEmulator $isPdc `
                -IsForestRootPdc $isRootPdc -Queried $false -DomainControllerHosts $DomainControllers `
                -ErrorText ("{0}, so w32tm could not be queried remotely" -f $dcReachCause.Trim().TrimEnd('.'))
            $rows += Get-AdfaClockOffsetVerdict -DomainController $dc -Scope $scope -ReferenceHost $refHost `
                -Queried $false -ErrorText ("{0}, so no NTP sample was taken" -f $dcReachCause.Trim().TrimEnd('.')) `
                -WarnSeconds $WarnSeconds -FailSeconds $FailSeconds
            continue
        }
        $reachable = [bool](Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135) -TimeoutMs $RpcPortTimeoutMs).Open[135]
        if (-not $reachable) {
            $samplesByDc[$norm] = [pscustomobject]@{ Queried = $false; Offsets = @(); Delays = @(); Error = 'RPC (135) was not reachable, so no NTP sample was taken' }
            $rows += Get-AdfaTimeSourceVerdict -DomainController $dc -Scope $scope -IsPdcEmulator $isPdc `
                -IsForestRootPdc $isRootPdc -Queried $false -DomainControllerHosts $DomainControllers `
                -ErrorText 'RPC (135) was not reachable, so w32tm could not be queried remotely'
            # An offset row too, so every DC carries one and a missing row never reads as clean.
            $rows += Get-AdfaClockOffsetVerdict -DomainController $dc -Scope $scope -ReferenceHost $refHost `
                -Queried $false -ErrorText 'RPC (135) was not reachable, so no NTP sample was taken' `
                -WarnSeconds $WarnSeconds -FailSeconds $FailSeconds
            continue
        }
        $r = Invoke-ExternalCommand -FilePath 'w32tm.exe' -Arguments ("/query /computer:{0} /source" -f $dc) `
            -TimeoutSeconds $TimeoutSeconds -Retries 1 -RetryDelaySeconds 1
        $source = ''
        if ($r.StdOut) {
            $source = [string](@(("$($r.StdOut)") -split "`r?`n" | Where-Object { $_.Trim() }) | Select-Object -First 1)
        }
        # w32tm prints its errors on stdout too, so a line that is an error message must not be
        # taken for a source name. Absence of output and an error are both "not read".
        $queried = $true
        $errText = ''
        if (-not $r.Success -or $source -match '(?i)^the following error|error:|access is denied|0x[0-9a-f]{8}') {
            $queried = $false
            $errText = ("w32tm reported: {0}" -f ("$source").Trim())
            if ([string]::IsNullOrWhiteSpace($source)) {
                $errText = ("w32tm exited with code {0} and no output" -f $r.ExitCode)
            }
        }
        $rows += Get-AdfaTimeSourceVerdict -DomainController $dc -Scope $scope -IsPdcEmulator $isPdc `
            -IsForestRootPdc $isRootPdc -Queried $queried -Source $source -ErrorText $errText `
            -DomainControllerHosts $DomainControllers

        # Measured offset, per DC. H8 reported where a DC takes time FROM and said in its own
        # detail that it does not verify the source is accurate; this is that verification.
        # Kerberos fails on skew, not on configuration.
        # One bounded w32tm /stripchart call (Get-AdfaStripchartSample, PORT-PLAN C14), which names
        # what happened when no sample parsed: the timed-out case is the common one and reads very
        # differently from a parse miss.
        $samples = Get-AdfaStripchartSample -ComputerName $dc -Samples $SkewSamples -TimeoutSeconds $TimeoutSeconds
        $samplesByDc[$norm] = $samples
        $rows += Get-AdfaClockOffsetVerdict -DomainController $dc -Scope $scope `
            -ReferenceHost $refHost -Queried $true -Offsets @($samples.Offsets) -ErrorText ([string]$samples.Error) `
            -WarnSeconds $WarnSeconds -FailSeconds $FailSeconds

        # The configured intent, for the root PDC only - it is the only role with a documented
        # required client type.
        if ($isRootPdc) {
            $cfgText = ''
            $c = Invoke-ExternalCommand -FilePath 'w32tm.exe' -Arguments ("/query /computer:{0} /configuration" -f $dc) `
                -TimeoutSeconds $TimeoutSeconds -Retries 1 -RetryDelaySeconds 1
            if ($c.Success -and $c.StdOut) { $cfgText = [string]$c.StdOut }
            $cfg = ConvertFrom-AdfaW32tmConfiguration -Text $cfgText
            $rows += Get-AdfaRootPdcClientTypeVerdict -DomainController $dc -Scope $scope `
                -ClientType $cfg.Type -NtpServer $cfg.NtpServer
        }
    }
    # PORT-PLAN C14 (TIME-001): each DC against the forest root PDC emulator. Its reading is the one
    # taken above when it was among the DCs asked; otherwise it is read once here, unless the
    # reachability probe classified it Unreachable.
    $referenceSample = $null
    if ($rootPdc -ne '') {
        if ($samplesByDc.ContainsKey($rootPdc)) { $referenceSample = $samplesByDc[$rootPdc] }
        else {
            $rootCause = Get-AdfaDcReachCause -HostName $ForestRootPdc
            if ($rootCause -ne '') { $referenceSample = [pscustomobject]@{ Queried = $false; Offsets = @(); Delays = @(); Error = $rootCause } }
            else { $referenceSample = Get-AdfaStripchartSample -ComputerName $ForestRootPdc -Samples $SkewSamples -TimeoutSeconds $TimeoutSeconds }
        }
    }
    for ($hostIndex = 0; $hostIndex -lt @($DomainControllers).Count; $hostIndex++) {
        $dc = [string]@($DomainControllers)[$hostIndex]
        $norm = Get-AdfaDnsNameNormalised -Name $dc
        $scope = [string]$hostScopes[$hostIndex]
        if ($pdcMap.ContainsKey($norm) -and $scope -eq '') { $scope = [string]$pdcMap[$norm] }
        $sample = $null
        if ($samplesByDc.ContainsKey($norm)) { $sample = $samplesByDc[$norm] }
        $rows += Get-AdfaPdcClockOffsetVerdict -DomainController $dc -Scope $scope -ReferencePdc $ForestRootPdc `
            -IsReference ($rootPdc -ne '' -and $norm -eq $rootPdc) -Sample $sample -ReferenceSample $referenceSample `
            -ReachCause (Get-AdfaDcReachCause -HostName $dc) -WarnSeconds $WarnSeconds -FailSeconds $FailSeconds -ThresholdSource $ThresholdSource
    }
    if ($rootPdc -eq '') {
        $rows += New-Finding -Area 'TimeHierarchy' -Item 'Forest root PDC emulator' -Status $script:Status.NotAssessed `
            -Detail 'The forest root domain''s PDC emulator could not be identified, so the role-specific rule (it must not take time from the domain hierarchy) was not applied to any DC. The per-DC rows above are therefore graded as ordinary DCs.'
    }
    elseif (-not (@($DomainControllers | ForEach-Object { Get-AdfaDnsNameNormalised -Name $_ }) -contains $rootPdc)) {
        $rows += New-Finding -Area 'TimeHierarchy' -Item 'Forest root PDC emulator' -Status $script:Status.NotAssessed `
            -Detail ("The forest root PDC emulator ({0}) is not in the list of domain controllers queried, so the one DC with a role-specific time requirement was not assessed. Re-run with -AllDomains, or with -Server pointed into the forest root domain." -f $ForestRootPdc)
    }
    return @(@($population) + @($rows))
}

function Get-AdfaSiteGcCoverage {
    <#
    .SYNOPSIS
        Pure per-site verdict on writeable global catalog coverage, from the DC inventory.
    .DESCRIPTION
        Joins three attributes the inventory already collects and never correlates: Site,
        IsGlobalCatalog and IsReadOnly. The rule is the vendor's, stated for the site where an
        Exchange server is installed: "The Active Directory site where you install the Exchange
        Server must contain at least one writeable domain controller that's also a global catalog
        server; or else, the installation will fail. Furthermore, you can't install the Exchange
        server and then remove the domain controller from the Active Directory site."
        https://learn.microsoft.com/exchange/plan-and-deploy/system-requirements#network-and-directory-server-requirements-for-exchange-server
        And: "You can't deploy an Exchange server in any site that contains only read-only
        directory servers."
        https://learn.microsoft.com/exchange/plan-and-deploy/active-directory/ad-access
        Read: 2026-09-22.

        A site with no writeable GC is a Warning, not a Fail: it is a legitimate design for a
        site that hosts no GC-dependent application, and whether it is a defect depends on what
        is deployed there - which this tool does not know. The finding names the consequence and
        what to confirm. Read-only is judged from IsReadOnly rather than inferred from anything
        else, and a DC whose site or flags could not be read makes its site UNKNOWN rather than
        quietly dropping out of the count.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @()
    )
    $dcs = @(@($DomainControllers) | Where-Object { $null -ne $_ })
    if ($dcs.Count -eq 0) {
        return @(New-Finding -Area 'SiteGc' -Item 'Writeable global catalog per site' -Status $script:Status.NotAssessed `
                -Detail 'No domain controller inventory was available, so global catalog coverage per site could not be derived. This is not a clean result.')
    }
    $rows = @()
    $bySite = @{}
    $noSite = @()
    foreach ($dc in $dcs) {
        $name = '(unnamed)'
        $hProp = $dc.PSObject.Properties['HostName']       # $null when absent - StrictMode-safe
        if ($null -ne $hProp -and $null -ne $hProp.Value) { $name = [string]$hProp.Value }
        $site = ''
        $sProp = $dc.PSObject.Properties['Site']
        if ($null -ne $sProp -and $null -ne $sProp.Value) { $site = ([string]$sProp.Value).Trim() }
        if ([string]::IsNullOrWhiteSpace($site)) { $noSite += $name; continue }

        # Tri-state on purpose: $null means "not readable", which must not count as $false.
        $isGc = $null
        $gProp = $dc.PSObject.Properties['IsGlobalCatalog']
        if ($null -ne $gProp -and $gProp.Value -is [bool]) { $isGc = [bool]$gProp.Value }
        $isRo = $null
        $rProp = $dc.PSObject.Properties['IsReadOnly']
        if ($null -ne $rProp -and $rProp.Value -is [bool]) { $isRo = [bool]$rProp.Value }

        if (-not $bySite.ContainsKey($site)) {
            $bySite[$site] = [pscustomobject]@{
                WriteableGc = @(); ReadOnlyGc = @(); WriteableNonGc = @(); ReadOnlyNonGc = @(); Unknown = @()
            }
        }
        $b = $bySite[$site]
        if ($null -eq $isGc -or $null -eq $isRo) { $b.Unknown += $name }
        elseif ($isGc -and -not $isRo) { $b.WriteableGc += $name }
        elseif ($isGc -and $isRo) { $b.ReadOnlyGc += $name }
        elseif (-not $isGc -and -not $isRo) { $b.WriteableNonGc += $name }
        else { $b.ReadOnlyNonGc += $name }
    }

    $covered = @()
    foreach ($site in @($bySite.Keys | Sort-Object)) {
        $b = $bySite[$site]
        if (@($b.WriteableGc).Count -gt 0) { $covered += $site; continue }
        $present = @()
        if (@($b.ReadOnlyGc).Count -gt 0) { $present += ("read-only GC: {0}" -f (@($b.ReadOnlyGc) -join ', ')) }
        if (@($b.WriteableNonGc).Count -gt 0) { $present += ("writeable but not a GC: {0}" -f (@($b.WriteableNonGc) -join ', ')) }
        if (@($b.ReadOnlyNonGc).Count -gt 0) { $present += ("read-only, not a GC: {0}" -f (@($b.ReadOnlyNonGc) -join ', ')) }
        if (@($b.Unknown).Count -gt 0) { $present += ("flags not readable: {0}" -f (@($b.Unknown) -join ', ')) }

        if (@($b.Unknown).Count -gt 0 -and $present.Count -eq 1) {
            $rows += New-Finding -Area 'SiteGc' -Item ("Site '{0}' - GC coverage not readable" -f $site) -Status $script:Status.NotAssessed `
                -Detail ("Every DC in this site had an unreadable global catalog or read-only flag ({0}), so whether the site has a writeable global catalog is UNKNOWN, not absent." -f (@($b.Unknown) -join ', '))
            continue
        }
        $rows += New-Finding -Area 'SiteGc' -Item ("Site '{0}' has no writeable global catalog" -f $site) -Status $script:Status.Warning `
            -Detail ("This site contains domain controllers but none of them is both writeable and a global catalog - {0}. Clients in this site must cross a site link for global catalog lookups, and no Exchange server can be installed here: Microsoft requires that the AD site hosting an Exchange server contain at least one writeable domain controller that is also a global catalog server, and states that an Exchange server cannot be deployed in a site containing only read-only directory servers. If nothing in this site depends on a local GC, this is a design choice rather than a fault - confirm which it is. To fix, set the GC flag on a writeable DC in this site (AD Sites and Services, or 'repadmin /options <dc> +IS_GC') and let the partial attribute set replicate." -f ($present -join '; '))
    }

    if (@($noSite).Count -gt 0) {
        $rows += New-Finding -Area 'SiteGc' -Item 'Domain controllers with no site' -Status $script:Status.NotAssessed `
            -Detail ("{0} domain controller(s) reported no site, so they were not counted towards any site's global catalog coverage: {1}. Those sites' coverage is therefore a partial result." -f @($noSite).Count, (@($noSite) -join ', '))
    }
    # A Pass row only where something actually passed. With no covered site the warnings above
    # are the whole result, and a "0 of N" row carrying a Pass status would be read as clean.
    if (@($covered).Count -gt 0) {
        $rows += New-Finding -Area 'SiteGc' -Item 'Writeable global catalog per site' -Status $script:Status.Pass `
            -Detail ("{0} of {1} site(s) holding domain controllers contain at least one writeable global catalog: {2}." -f `
                @($covered).Count, @($bySite.Keys).Count, (@($covered) -join ', '))
    }
    return @($rows)
}

function Get-AdfaPortMatrix {
    <#
    .SYNOPSIS
        Per-DC reachability on the ports replication and authentication require, probed
        from this host. Separates "unresolvable in DNS" from "resolvable but the port is
        closed" - they have completely different fixes.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # DC rows (HostName, Scope) or plain host names (PORT-PLAN C2e). The population rows of the
        # section are the "DC reachability (population)" rows, which take the same targets.
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [int]$RpcPortTimeoutMs = 1200
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-Finding -Scope $scope -Area 'PortMatrix' -Item '(unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so no port was probed.'
            continue
        }
        # PORT-PLAN C14c: a DC the reachability probe classified Unreachable is not probed on any
        # port; its "DC reachability" row carries the Fail, and this row says why nothing was probed.
        $reachCause = Get-AdfaDcReachCause -HostName $dc
        if ($reachCause) {
            $rows += New-Finding -Scope $scope -Area 'PortMatrix' -Item $dc -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $reachCause -NotRead 'none of the replication ports was probed; the DC reachability row of this DC carries the finding')
            continue
        }
        # Name resolution: the classification's where it ran (no second lookup), otherwise one
        # bounded lookup through the same seam.
        $record = Get-AdfaDcReachRecord -HostName $dc
        $resolvable = $false
        if ($null -ne $record) { $resolvable = (@(@(Get-AdfaConfigValue -Entry $record -Name 'Addresses') | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }).Count -gt 0) }
        else {
            $lookup = Resolve-AdfaHostAddress -HostName $dc -TimeoutMs ([int]$script:Config.Reach['ProbeTimeoutMs'])
            $resolvable = ([bool]$lookup.Ok -and @(@($lookup.Addresses) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }).Count -gt 0)
        }
        if (-not $resolvable) {
            $rows += New-Finding -Scope $scope -Area 'PortMatrix' -Item $dc -Status $script:Status.Fail -Detail 'Host name does not resolve in DNS - no A record. Nothing can reach this DC by name.'
            continue
        }
        $closedCritical = @(); $closedOptional = @(); $open = @()
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @($script:Config.ReplicationPorts | ForEach-Object { [int]$_.Port }) -TimeoutMs $RpcPortTimeoutMs
        foreach ($p in $script:Config.ReplicationPorts) {
            if ($gate.Open[[int]$p.Port]) { $open += ("{0}/{1}" -f $p.Port, $p.Name) }
            elseif ($p.Critical) { $closedCritical += ("{0}/{1}" -f $p.Port, $p.Name) }
            else { $closedOptional += ("{0}/{1}" -f $p.Port, $p.Name) }
        }
        if (@($closedCritical).Count -gt 0) {
            $rows += New-Finding -Scope $scope -Area 'PortMatrix' -Item $dc -Status $script:Status.Fail -Detail ("Critical port(s) not reachable: {0}.{1}" -f ($closedCritical -join ', '), $(if (@($closedOptional).Count -gt 0) { ' Also closed: ' + ($closedOptional -join ', ') + '.' } else { '' }))
        }
        elseif (@($closedOptional).Count -gt 0) {
            $rows += New-Finding -Scope $scope -Area 'PortMatrix' -Item $dc -Status $script:Status.Warning -Detail ("Optional port(s) not reachable: {0}. Core replication ports are open." -f ($closedOptional -join ', '))
        }
        else {
            $rows += New-Finding -Scope $scope -Area 'PortMatrix' -Item $dc -Status $script:Status.Pass -Detail ("All {0} probed ports reachable." -f @($open).Count)
        }
    }
    if (@($targets).Count -eq 0) {
        $rows += New-Finding -Area 'PortMatrix' -Item 'Port matrix' -Status $script:Status.NotAssessed -Detail 'No domain controllers enumerated.'
    }
    return @($rows)
}

function Get-AdfaDcSecureChannel {
    <#
    .SYNOPSIS
        Two checks per DC. (1) Machine-account password age from the replicated
        pwdLastSet attribute - collected centrally, no remoting needed; a stale value is
        the fingerprint of a DC restored from an old backup. (2) Where WinRM is
        reachable, the secure channel's status read ON the DC via nltest /sc_query
        (read-only, the last recorded state; /sc_verify only with -LiveVerify);
        where it is not, the check reports Not Assessed and says what to run locally.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [pscredential]$Credential,
        [int]$WarnDays = 45,
        [int]$FailDays = 90,
        # Run nltest /sc_verify on each DC instead of /sc_query. /sc_verify resets a channel
        # that is not working, on every DC it reaches; off unless asked for.
        [switch]$LiveVerify,
        [int]$RpcPortTimeoutMs = 1200
    )
    $rows = @()
    $scArgument = Get-AdfaNltestScArgument -Domain $DomainName -LiveVerify:$LiveVerify
    $p = @{} + $AdParams; $p.Server = $DomainName
    $dcs = @()
    # PORT-PLAN C2e: the domain's own enumeration (-Server <domain>), so every scoped domain is read; a
    # domain that cannot be enumerated, or that returns no DC, says so in its own row.
    try { $dcs = @(Get-ADDomainController -Filter * @p | Where-Object { $null -ne $_ }) }
    catch {
        $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item 'DC enumeration' -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap ([pscustomobject]@{ Domain = $DomainName; Failed = $true; Error = [string]$_.Exception.Message; Seen = $false; WithoutDomain = 0 }) `
                -NothingRead 'No machine-account password and no secure channel of its DCs was read.')
        return @($rows)
    }
    if ($dcs.Count -eq 0) {
        $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item 'DC enumeration' -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap ([pscustomobject]@{ Domain = $DomainName; Failed = $false; Error = ''; Seen = $false; WithoutDomain = 0 }) `
                -NothingRead 'No machine-account password and no secure channel of its DCs was read.')
        return @($rows)
    }

    foreach ($dc in $dcs) {
        $dcHost = ''
        $hostProp = $dc.PSObject.Properties['HostName']
        if ($null -ne $hostProp -and $null -ne $hostProp.Value) { $dcHost = [string]$hostProp.Value }
        if ([string]::IsNullOrWhiteSpace($dcHost)) {
            $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item 'Secure channel: (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The enumeration returned a domain controller with no host name, so there was nothing to connect to: neither its machine-account password nor its secure channel was read.'
            continue
        }
        # (1) Machine-account password age - central, from the replicated attribute.
        try {
            $comp = Get-ADComputer -Identity $dc.ComputerObjectDN -Properties PasswordLastSet @p
            $age = $null
            if ($comp.PasswordLastSet) { $age = ((Get-Date) - $comp.PasswordLastSet).TotalDays }
            $verdict = Resolve-AdfaDcPasswordVerdict -AgeDays $age -WarnDays $WarnDays -FailDays $FailDays
            $ageText = 'never set / not readable'
            if ($null -ne $age) { $ageText = ('{0:N0} day(s) old (set {1:yyyy-MM-dd})' -f $age, $comp.PasswordLastSet) }
            $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item ("Machine-account password: {0}" -f $dc.HostName) -Status $verdict -Detail ("pwdLastSet is {0}. Default rotation is every 30 days; a stale value on a DC usually means it was restored from an old backup or rotation is disabled." -f $ageText)
        }
        catch {
            $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item ("Machine-account password: {0}" -f $dc.HostName) -Status $script:Status.NotAssessed -Detail $_.Exception.Message
        }

        # (2) Secure channel verified ON the DC, via WinRM where reachable. PORT-PLAN C1b/C14c: through
        # the shared gate, so a DC classified Unreachable is not probed again and says so.
        $scGate = Get-AdfaDcProbeGate -ComputerName $dcHost -Ports @(5985) -TimeoutMs $RpcPortTimeoutMs
        if ($scGate.Cause) {
            $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item ("Secure channel: {0}" -f $dcHost) -Status $script:Status.NotAssessed `
                -Detail ("{0} Run 'nltest {1}' locally on the DC." -f (Get-AdfaDcGateText -Cause $scGate.Cause -NotRead 'its secure channel was not queried'), $scArgument)
        }
        elseif ($scGate.Open[5985]) {
            try {
                $icm = @{
                    ComputerName = $dc.HostName
                    ScriptBlock  = { param($a) & nltest.exe $a 2>&1 | Out-String }
                    ArgumentList = $scArgument
                    ErrorAction  = 'Stop'
                }
                if ($Credential) { $icm.Credential = $Credential }
                $out = [string](Invoke-Command @icm)
                $scItem = ("Secure channel: {0}" -f $dc.HostName)
                if ($LiveVerify) {
                    $v = Get-AdfaScVerifyOutcome -Output $out
                    if ($v.Outcome -eq 'Ok') {
                        $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item $scItem -Status $script:Status.Pass -Detail ("nltest /sc_verify on the DC reported status {0}. This is a live test; /sc_verify resets a channel that is not working, so a channel that was broken before this run may have been rebuilt by it." -f $v.Status)
                    }
                    elseif ($v.Outcome -eq 'Bad') {
                        $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item $scItem -Status $script:Status.Fail -Detail ("nltest /sc_verify on the DC reported status {0}: {1}" -f $v.Status, (Get-AdfaOutputExcerpt -Output $out))
                    }
                    else {
                        $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item $scItem -Status $script:Status.NotAssessed -Detail ("nltest /sc_verify on the DC printed no status line this tool can read (the match is on English text): {0}" -f (Get-AdfaOutputExcerpt -Output $out))
                    }
                }
                else {
                    $q = Get-AdfaScQueryOutcome -Output $out
                    if ($q.Outcome -eq 'Ok') {
                        $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item $scItem -Status $script:Status.Pass -Detail ("nltest {0} on the DC: last recorded status {1}. {2}" -f $scArgument, $q.Status, $script:ScQueryCaveat)
                    }
                    elseif ($q.Outcome -eq 'Bad') {
                        $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item $scItem -Status $script:Status.Fail -Detail ("nltest {0} on the DC: last recorded status {1}. {2}" -f $scArgument, $q.Status, $script:ScQueryCaveat)
                    }
                    else {
                        $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item $scItem -Status $script:Status.NotAssessed -Detail ("nltest {0} on the DC printed no connection status line this tool can read (the match is on English text): {1}" -f $scArgument, (Get-AdfaOutputExcerpt -Output $out))
                    }
                }
            }
            catch {
                $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item ("Secure channel: {0}" -f $dc.HostName) -Status $script:Status.NotAssessed -Detail ("WinRM query failed: {0}. Run 'nltest {1}' locally on the DC." -f $_.Exception.Message, $scArgument)
            }
        }
        else {
            $rows += New-Finding -Scope $DomainName -Area 'DcSecureChannel' -Item ("Secure channel: {0}" -f $dc.HostName) -Status $script:Status.NotAssessed -Detail ("WinRM (5985) not reachable from this host. Run 'nltest {0}' locally on the DC." -f $scArgument)
        }
    }
    return @($rows)
}


function Get-AdfaEventLogCoverage {
    <#
    .SYNOPSIS
        Pure classification of whether an event log actually covers a lookback window.
    .DESCRIPTION
        Absence of an event is only evidence if the log goes back far enough to have recorded
        one. Before this, a Directory Service log with nothing in it reported Pass - so a DC
        whose log had been cleared during a ransomware recovery, or had simply wrapped, read
        exactly like a healthy one on the checks that matter most (USN rollback 2095,
        unsupported restore 2103, lingering objects 1988).

        The signal is the oldest record the log still retains, compared with the start of the
        window being asked about. That one measurement covers every way the window can be
        incomplete - cleared, wrapped, or a DC rebuilt more recently than the window - and
        needs no vendor-specific "log was cleared" event ID. A specific marker event was
        considered and deliberately not used: the Windows Event Log docs on Microsoft Learn do
        not publish one for an arbitrary log (searched 2026-09-21), and it would add nothing,
        because clearing a log necessarily moves its oldest retained record forward.

        Verdicts:
          Covered   - the log reaches back to or past the window start; absence is meaningful.
          Truncated - the log starts inside the window; absence is NOT meaningful before
                      OldestRecord, and any count found is a floor rather than a total.
          Empty     - the log holds no records at all; nothing can be concluded.
          Unknown   - the log could not be inspected (unreachable, access denied, absent).
    .OUTPUTS
        [string] Covered | Truncated | Empty | Unknown
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [bool]$Inspected = $true,
        [AllowNull()][Nullable[int]]$RecordCount,
        [AllowNull()][Nullable[datetime]]$OldestRecord,
        [AllowNull()][Nullable[datetime]]$WindowStart
    )
    if (-not $Inspected) { return 'Unknown' }
    if ($null -ne $RecordCount -and $RecordCount -le 0) { return 'Empty' }
    # Either bound missing means the comparison cannot be made - say so rather than assume.
    if ($null -eq $OldestRecord -or $null -eq $WindowStart) { return 'Unknown' }
    if ($OldestRecord -le $WindowStart) { return 'Covered' }
    return 'Truncated'
}

function Get-AdfaEventCoverageDetail {
    <#
    .SYNOPSIS
        The sentence that explains a non-Covered verdict, naming what limits the claim.
    .DESCRIPTION
        Kept beside the classifier and pure, so the wording a report carries is testable
        rather than buried in string concatenation inside a collector.
    .OUTPUTS
        [string] Empty for 'Covered' - there is nothing to caveat.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][ValidateSet('Covered', 'Truncated', 'Empty', 'Unknown')][string]$Coverage,
        [AllowNull()][Nullable[datetime]]$OldestRecord,
        [int]$LookbackDays = 14,
        [string]$Reason = '',
        # Named by the caller so one guard serves both the Directory Service and the
        # DFS Replication logs rather than the wording being duplicated per log.
        [string]$LogName = 'Directory Service'
    )
    if ($Coverage -eq 'Covered') { return '' }
    if ($Coverage -eq 'Empty') {
        return (("The {0} log holds no records, so the absence of an event proves nothing. " +
                "A log cleared during recovery looks identical to a healthy one here - read the log on the DC itself.") -f $LogName)
    }
    if ($Coverage -eq 'Truncated') {
        $from = ''
        if ($null -ne $OldestRecord) { $from = $OldestRecord.ToString('yyyy-MM-dd HH:mm') }
        # The concatenation is parenthesised before -f on purpose: -f binds tighter than +, so
        # "a {0}" + "b" -f $x formats only the SECOND string and leaves {0} literal.
        return (("The {0} log only goes back to {1}, which is inside the {2}-day window, " +
                "so nothing can be concluded about the period before that. The log was cleared or has wrapped.") -f $LogName, $from, $LookbackDays)
    }
    $suffix = ''
    if (-not [string]::IsNullOrWhiteSpace($Reason)) { $suffix = (" Cause: {0}" -f $Reason) }
    return ("The {0} log could not be inspected, so its coverage of the {1}-day window is unknown.{2}" -f $LogName, $LookbackDays, $suffix)
}

function Get-AdfaEventLogCoverageForLog {
    <#
    .SYNOPSIS
        Measures how far back a named event log on a DC actually reaches.
    .DESCRIPTION
        Thin collector over Get-AdfaEventLogCoverage. Get-WinEvent -ListLog gives the record
        count but not the oldest record's timestamp, so the oldest record is read directly
        with -Oldest -MaxEvents 1.
    .OUTPUTS
        [pscustomobject] Coverage, OldestRecord, RecordCount, Reason
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][string]$LogName,
        [pscredential]$Credential,
        [Parameter(Mandatory)][datetime]$WindowStart
    )
    $recordCount = $null
    $oldest = $null
    $reason = ''
    $inspected = $false
    try {
        $listArgs = @{ ListLog = $LogName; ComputerName = $ComputerName; ErrorAction = 'Stop' }
        if ($Credential) { $listArgs.Credential = $Credential }
        $log = Get-WinEvent @listArgs
        if ($null -ne $log) {
            $inspected = $true
            $prop = $log.PSObject.Properties['RecordCount']   # $null when absent - StrictMode-safe
            if ($null -ne $prop -and $null -ne $prop.Value) { $recordCount = [int]$prop.Value }
        }
        else { $reason = ("Get-WinEvent -ListLog returned nothing for the {0} log." -f $LogName) }
    }
    catch {
        $reason = $_.Exception.Message
    }

    if ($inspected -and ($null -eq $recordCount -or $recordCount -gt 0)) {
        try {
            $oldArgs = @{
                ComputerName = $ComputerName; LogName = $LogName
                Oldest = $true; MaxEvents = 1; ErrorAction = 'Stop'
            }
            if ($Credential) { $oldArgs.Credential = $Credential }
            $first = @(Get-WinEvent @oldArgs)
            if (@($first).Count -gt 0) { $oldest = [datetime]$first[0].TimeCreated }
            else { $recordCount = 0 }
        }
        catch {
            # The log listed but its oldest record could not be read: coverage is unknown, not
            # covered. Recorded rather than swallowed, so the report can name the cause.
            $reason = ("oldest record unreadable: {0}" -f $_.Exception.Message)
            $inspected = $false
        }
    }

    $coverage = Get-AdfaEventLogCoverage -Inspected $inspected -RecordCount $recordCount `
        -OldestRecord $oldest -WindowStart $WindowStart
    return [pscustomobject]@{
        Coverage     = $coverage
        OldestRecord = $oldest
        RecordCount  = $recordCount
        Reason       = $reason
    }
}


function Get-AdfaSysvolShareOutcome {
    <#
    .SYNOPSIS
        Pure classification of whether a DC is actually sharing SYSVOL and NETLOGON.
    .DESCRIPTION
        The distinction that matters is between "the share is not there" and "we could not
        look". A DC that is unreachable over SMB tells us nothing about its shares, and calling
        that a missing share would invent a failure; calling it healthy would hide one.

        Missing SYSVOL/NETLOGON is the vendor's own first diagnostic for broken SYSVOL
        replication, and it is a common state after a restore - the DFSR service will not share
        SYSVOL until the replicated folder has initialised (event 4604).
        https://learn.microsoft.com/troubleshoot/windows-server/networking/troubleshoot-missing-sysvol-and-netlogon-shares
        Read: 2026-09-21.
    .OUTPUTS
        [string] Shared | MissingSysvol | MissingNetlogon | MissingBoth | Unknown
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [bool]$SmbReachable = $true,
        [AllowNull()][Nullable[bool]]$SysvolPresent,
        [AllowNull()][Nullable[bool]]$NetlogonPresent
    )
    if (-not $SmbReachable) { return 'Unknown' }
    if ($null -eq $SysvolPresent -or $null -eq $NetlogonPresent) { return 'Unknown' }
    if ($SysvolPresent -and $NetlogonPresent) { return 'Shared' }
    if (-not $SysvolPresent -and -not $NetlogonPresent) { return 'MissingBoth' }
    if (-not $SysvolPresent) { return 'MissingSysvol' }
    return 'MissingNetlogon'
}

function Get-AdfaSysvolShareHealth {
    <#
    .SYNOPSIS
        Per-DC SYSVOL / NETLOGON share presence.
    .DESCRIPTION
        Thin collector over Get-AdfaSysvolShareOutcome. SMB (445) is probed first so an
        unreachable DC is reported as unknown rather than as a missing share.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # DC rows (HostName, Scope) or plain host names (PORT-PLAN C2e).
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [int]$RpcPortTimeoutMs = 1200,
        # Domains whose DC enumeration threw (Domain, Error), and the domains of the run.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    $rows = @(Get-AdfaDcPopulationRow -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Area 'SYSVOL' `
            -Label 'SYSVOL / NETLOGON shares' -NothingRead 'No share of its DCs was probed.')
    if ($targets.Count -eq 0) {
        return @(@($rows) + @(New-Finding -Area 'SYSVOL' -Item 'SYSVOL / NETLOGON shares' -Status $script:Status.NotAssessed `
                    -Detail 'No domain controllers were enumerated, so no share could be probed. This is not a clean result.'))
    }
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-Finding -Scope $scope -Area 'SYSVOL' -Item 'Shares on (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and no share was probed.'
            continue
        }
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @(445) -TimeoutMs $RpcPortTimeoutMs
        if ($gate.Cause) {
            $rows += New-Finding -Scope $scope -Area 'SYSVOL' -Item ("Shares on {0}" -f $dc) -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'its shares were not probed. Nothing can be concluded about them from here')
            continue
        }
        $smbOk = [bool]$gate.Open[445]
        $sysvol = $null
        $netlogon = $null
        if ($smbOk) {
            foreach ($share in @($script:Config.SysvolShares)) {
                $present = $null
                try { $present = [bool](Test-Path -LiteralPath ("\\{0}\{1}" -f $dc, $share) -ErrorAction Stop) }
                catch { $present = $null }
                if ($share -eq 'SYSVOL') { $sysvol = $present } else { $netlogon = $present }
            }
        }
        $outcome = Get-AdfaSysvolShareOutcome -SmbReachable $smbOk -SysvolPresent $sysvol -NetlogonPresent $netlogon
        $status = $script:Status.NotAssessed
        $detail = ''
        switch ($outcome) {
            'Shared' {
                $status = $script:Status.Pass
                $detail = 'Both SYSVOL and NETLOGON are shared.'
            }
            'MissingBoth' {
                $status = $script:Status.Fail
                $detail = 'Neither SYSVOL nor NETLOGON is shared. Group Policy and logon scripts are not being served by this DC, and DFSR has not initialised the replicated folder (look for event 4604, and for 2213 / 4012 / 4114 in the DFS Replication log).'
            }
            'MissingSysvol' {
                $status = $script:Status.Fail
                $detail = 'SYSVOL is NOT shared (NETLOGON is). Group Policy is not being served by this DC.'
            }
            'MissingNetlogon' {
                $status = $script:Status.Fail
                $detail = 'NETLOGON is NOT shared (SYSVOL is). Logon scripts are not being served by this DC.'
            }
            default {
                $status = $script:Status.NotAssessed
                $detail = 'SMB (445) was not reachable, so the shares could not be probed. Nothing can be concluded about them from here - check on the DC itself.'
            }
        }
        $rows += New-Finding -Scope $scope -Area 'SYSVOL' -Item ("Shares on {0}" -f $dc) -Status $status -Detail $detail
    }
    return @($rows)
}

function Get-AdfaDfsrSubscriptionVerdict {
    <#
    .SYNOPSIS
        Pure verdict on the SYSVOL subscription state across every DC in a domain.
    .DESCRIPTION
        Per KB 2218556, a DFSR-replicated SYSVOL is reinitialised by hand through two attributes
        on each DC's SYSVOL subscription object: msDFSR-Enabled=FALSE takes that DC out of
        replication, and msDFSR-options=1 marks one DC authoritative (the DFSR equivalent of the
        FRS D4). Both are edited during a recovery and both are easy to leave behind - and
        nothing else in this report would show it.
        https://learn.microsoft.com/troubleshoot/windows-server/group-policy/force-authoritative-non-authoritative-synchronization
        Read: 2026-09-21.

        The cross-DC rule is the reason this is a whole-domain verdict rather than a per-DC one:
        the procedure marks exactly ONE member authoritative, so two or more is a conflict that
        cannot be seen by looking at any single DC.

        The verdict describes what the attributes say and what that means. It does not claim the
        reinitialisation is unfinished on the strength of msDFSR-options alone - the vendor does
        not document clearing it afterwards, so a set value is reported as state, not as a fault.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowNull()][AllowEmptyCollection()]$Subscriptions = @()
    )
    $rows = @()
    $subs = @($Subscriptions | Where-Object { $null -ne $_ })
    if ($subs.Count -eq 0) {
        return @(New-Finding -Scope $DomainName -Area 'SYSVOL' -Item 'DFSR SYSVOL subscription state' -Status $script:Status.NotAssessed `
                -Detail 'No SYSVOL subscription object could be read, so it is unknown whether SYSVOL replication is enabled on these DCs. This is not a clean result.')
    }

    $disabled = @()
    $unknown = @()
    $authoritative = @()
    foreach ($sub in $subs) {
        $name = '(unnamed)'
        $nProp = $sub.PSObject.Properties['DcName']
        if ($null -ne $nProp -and $null -ne $nProp.Value) { $name = [string]$nProp.Value }
        $eProp = $sub.PSObject.Properties['Enabled']
        $oProp = $sub.PSObject.Properties['Options']
        if ($null -eq $eProp -or $null -eq $eProp.Value) { $unknown += $name }
        elseif (-not [bool]$eProp.Value) { $disabled += $name }
        if ($null -ne $oProp -and $null -ne $oProp.Value -and [int]$oProp.Value -eq 1) { $authoritative += $name }
    }

    if ($disabled.Count -gt 0) {
        $rows += New-Finding -Scope $DomainName -Area 'SYSVOL' -Item 'DFSR SYSVOL replication disabled' -Status $script:Status.Fail `
            -Detail ("msDFSR-Enabled=FALSE on {0} of {1} DC(s): {2}. SYSVOL is NOT replicating on those DCs and they will not share SYSVOL. This attribute is only set by hand, during a D2/D4-equivalent reinitialisation - if that procedure was interrupted it must be completed by setting msDFSR-Enabled=TRUE and running 'dfsrdiag pollad'." -f `
                $disabled.Count, $subs.Count, ($disabled -join ', '))
    }
    else {
        $rows += New-Finding -Scope $DomainName -Area 'SYSVOL' -Item 'DFSR SYSVOL replication enabled' -Status $script:Status.Pass `
            -Detail ("msDFSR-Enabled is TRUE on all {0} DC(s) whose subscription object could be read." -f ($subs.Count - $unknown.Count))
    }

    if ($unknown.Count -gt 0) {
        $rows += New-Finding -Scope $DomainName -Area 'SYSVOL' -Item 'DFSR SYSVOL subscription - not readable' -Status $script:Status.NotAssessed `
            -Detail ("msDFSR-Enabled could not be read on {0} DC(s): {1}. Those DCs are unverified, not healthy." -f $unknown.Count, ($unknown -join ', '))
    }

    if ($authoritative.Count -gt 1) {
        $rows += New-Finding -Scope $DomainName -Area 'SYSVOL' -Item 'Conflicting authoritative SYSVOL members' -Status $script:Status.Fail `
            -Detail ("msDFSR-options=1 on {0} DCs: {1}. The reinitialisation procedure marks exactly ONE member authoritative; more than one is a conflict and the domain's SYSVOL content may diverge depending on which initialises first. Decide which DC holds the correct SYSVOL and clear the attribute on the others." -f `
                $authoritative.Count, ($authoritative -join ', '))
    }
    elseif ($authoritative.Count -eq 1) {
        $rows += New-Finding -Scope $DomainName -Area 'SYSVOL' -Item 'Authoritative SYSVOL member set' -Status $script:Status.Warning `
            -Detail ("msDFSR-options=1 on {0}, marking it the authoritative SYSVOL member (the DFSR equivalent of an FRS D4). That is expected DURING a deliberate SYSVOL rebuild and unexpected otherwise. Confirm the rebuild completed - DFS Replication event 4602 on that DC, then 4604 on the others - and that this DC genuinely holds the SYSVOL content you want to keep." -f $authoritative[0])
    }
    return @($rows)
}

function Get-AdfaDfsrSubscription {
    <#
    .SYNOPSIS
        Reads each DC's SYSVOL subscription object (msDFSR-Enabled, msDFSR-options).
    .OUTPUTS
        [pscustomobject[]] DcName, Enabled, Options, Error
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [hashtable]$AdParams = @{}
    )
    $out = @()
    foreach ($dc in @($DomainControllers | Where-Object { $null -ne $_ })) {
        $dn = ''
        $name = ''
        $hostProp = $dc.PSObject.Properties['HostName']
        $dnProp = $dc.PSObject.Properties['ComputerObjectDN']
        if ($null -ne $hostProp -and $null -ne $hostProp.Value) { $name = [string]$hostProp.Value }
        if ($null -ne $dnProp -and $null -ne $dnProp.Value) { $dn = [string]$dnProp.Value }
        if (-not $dn) {
            $out += [pscustomobject]@{ DcName = $name; Enabled = $null; Options = $null; Error = 'No computer object DN on the inventory row, so the subscription DN could not be built.' }
            continue
        }
        $subDn = $script:Config.SysvolSubscriptionDn -f $dn
        try {
            $p = @{} + $AdParams
            $p.Identity = $subDn
            $p.Properties = @('msDFSR-Enabled', 'msDFSR-options')
            $obj = Get-ADObject @p -ErrorAction Stop
            $en = $null
            $op = $null
            $eProp = $obj.PSObject.Properties['msDFSR-Enabled']
            $oProp = $obj.PSObject.Properties['msDFSR-options']
            if ($null -ne $eProp -and $null -ne $eProp.Value) { $en = [bool]$eProp.Value }
            if ($null -ne $oProp -and $null -ne $oProp.Value) { $op = [int]$oProp.Value }
            # An unset msDFSR-Enabled is the default-enabled state, not "unknown": the attribute
            # is only written when someone disables replication. Treated as TRUE so a healthy DC
            # is not reported as unverified, which would cry wolf on every normal forest.
            if ($null -eq $en) { $en = $true }
            $out += [pscustomobject]@{ DcName = $name; Enabled = $en; Options = $op; Error = '' }
        }
        catch {
            $out += [pscustomobject]@{ DcName = $name; Enabled = $null; Options = $null; Error = $_.Exception.Message }
        }
    }
    return @($out)
}


function Get-AdfaDfsrBacklogCount {
    <#
    .SYNOPSIS
        Pure resolution of a DFSR backlog size from what Get-DfsrBacklog actually returns.
    .DESCRIPTION
        Get-DfsrBacklog returns at most 100 records, and the true total appears only in its
        verbose stream - so counting the returned objects reports a FLOOR as if it were a total
        once the backlog reaches the cap. Microsoft's own documented way to get the real number
        is to read the verbose message, whose format is:

            The replicated folder has a backlog of files. Replicated folder: "RF01". Count: 2400

        https://learn.microsoft.com/powershell/module/dfsr/get-dfsrbacklog  (read 2026-09-21)

        So: prefer the verbose count when it parses; otherwise fall back to the object count,
        which is exact below the cap and a floor at it. The caller is told which, because
        "2400" and "at least 100" are different claims.

        Returns Count (int) and Exact (bool). Count is -1 when nothing could be determined.
    .OUTPUTS
        [pscustomobject] Count, Exact, Source
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$VerboseMessage = '',
        [int]$ObjectCount = 0,
        [int]$DisplayCap = 100,
        [bool]$Succeeded = $true
    )
    if (-not $Succeeded) {
        return [pscustomobject]@{ Count = -1; Exact = $false; Source = 'None' }
    }
    if (-not [string]::IsNullOrWhiteSpace($VerboseMessage)) {
        # Anchored on the vendor's documented wording rather than any trailing number in the
        # text, so an unrelated verbose line cannot be read as a backlog size.
        $m = [regex]::Match($VerboseMessage, '(?i)backlog of files.*?Count:\s*(\d+)')
        if ($m.Success) {
            return [pscustomobject]@{ Count = [int]$m.Groups[1].Value; Exact = $true; Source = 'Verbose' }
        }
    }
    if ($ObjectCount -ge $DisplayCap) {
        return [pscustomobject]@{ Count = $DisplayCap; Exact = $false; Source = 'CappedObjects' }
    }
    return [pscustomobject]@{ Count = $ObjectCount; Exact = $true; Source = 'Objects' }
}

function Get-AdfaSysvolBacklogVerdict {
    <#
    .SYNOPSIS
        Pure verdict on one directed SYSVOL backlog measurement.
    .DESCRIPTION
        Thresholds come from config, not from the vendor: Microsoft states a backlog indicates
        latency and is "not necessarily an indication of problems". The tighter bar applied here
        is reasoned and stated in the finding itself - SYSVOL changes only when Group Policy
        changes, so a standing backlog means a policy edit is not reaching that DC.

        A count that is a floor rather than a total is never reported as if it were exact.
    .OUTPUTS
        [pscustomobject] Status, Detail
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$SourceDc,
        [Parameter(Mandatory)][string]$DestinationDc,
        [int]$Count = -1,
        [bool]$Exact = $true,
        [int]$WarnAt = 1,
        [int]$FailAt = 100,
        [string]$Reason = ''
    )
    if ($Count -lt 0) {
        $why = 'the backlog could not be measured'
        if (-not [string]::IsNullOrWhiteSpace($Reason)) { $why = $Reason }
        return [pscustomobject]@{
            Status = $script:Status.NotAssessed
            Detail = ("SYSVOL backlog {0} -> {1} could not be measured: {2}. This is not a clean result." -f $SourceDc, $DestinationDc, $why)
        }
    }
    $shown = [string]$Count
    if (-not $Exact) { $shown = ("at least {0}" -f $Count) }
    if ($Count -eq 0) {
        return [pscustomobject]@{
            Status = $script:Status.Pass
            Detail = ("SYSVOL backlog {0} -> {1} is 0 - that direction has converged." -f $SourceDc, $DestinationDc)
        }
    }
    $status = $script:Status.Warning
    if ($Count -ge $FailAt) { $status = $script:Status.Fail }
    elseif ($Count -lt $WarnAt) { $status = $script:Status.Pass }
    $capNote = ''
    if (-not $Exact) {
        $capNote = ' The true figure may be far higher: Get-DfsrBacklog displays at most 100 records and its verbose count could not be read, so this is a floor, not a total.'
    }
    return [pscustomobject]@{
        Status = $status
        Detail = ("SYSVOL backlog {0} -> {1} is {2} file(s) pending. SYSVOL changes only when Group Policy changes, so it should sit at or near zero - a standing backlog means a policy edit is not reaching {1}. (A DFSR backlog on its own indicates latency rather than a fault; the tighter bar here is specific to SYSVOL.){3}" -f `
                $SourceDc, $DestinationDc, $shown, $capNote)
    }
}

function Get-AdfaSysvolBacklog {
    <#
    .SYNOPSIS
        Measures the SYSVOL backlog in both directions between a reference DC and every other DC.
    .DESCRIPTION
        Opt-in, because it costs two RPC round trips per DC and needs the optional DFSR module.
        The reference DC is the domain's PDC emulator, which is where Group Policy edits are
        normally written, so it is the DC the others should be catching up with.

        Both directions are measured: a backlog TO the PDC and a backlog FROM it are different
        faults, and testing only one would miss half of them.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [Parameter(Mandatory)][string]$ReferenceDc,
        [AllowEmptyCollection()][string[]]$DomainControllers = @(),
        [int]$RpcPortTimeoutMs = 1200
    )
    $rows = @()
    if (-not (Test-ModuleAvailable -Name 'DFSR')) {
        return @(New-Finding -Scope $DomainName -Area 'SysvolBacklog' -Item 'SYSVOL backlog' -Status $script:Status.NotAssessed `
                -Detail 'The DFSR PowerShell module is not installed on this host, so the SYSVOL backlog could not be measured. Install RSAT FS-DFS-Mgmt-Con, or run "dfsrdiag backlog" on a DC.')
    }
    Import-Module DFSR -ErrorAction SilentlyContinue -Verbose:$false
    $peers = @($DomainControllers | Where-Object {
            $null -ne $_ -and $_.ToLowerInvariant().TrimEnd('.') -ne $ReferenceDc.ToLowerInvariant().TrimEnd('.')
        })
    if ($peers.Count -eq 0) {
        return @(New-Finding -Scope $DomainName -Area 'SysvolBacklog' -Item 'SYSVOL backlog' -Status $script:Status.NotAssessed `
                -Detail ("No DC other than the reference ({0}) was available to compare against, so no backlog could be measured." -f $ReferenceDc))
    }

    $group = [string]$script:Config.SysvolReplicationGroup
    $folder = [string]$script:Config.SysvolReplicatedFolder
    foreach ($peer in $peers) {
        $peerGate = Get-AdfaDcProbeGate -ComputerName $peer -Ports @(135) -TimeoutMs $RpcPortTimeoutMs
        if ($peerGate.Cause) {
            $rows += New-Finding -Scope $DomainName -Area 'SysvolBacklog' -Item ("Backlog with {0}" -f $peer) -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $peerGate.Cause -NotRead 'neither direction could be measured')
            continue
        }
        if (-not $peerGate.Open[135]) {
            $rows += New-Finding -Scope $DomainName -Area 'SysvolBacklog' -Item ("Backlog with {0}" -f $peer) -Status $script:Status.NotAssessed `
                -Detail 'RPC (135) not reachable, so neither direction could be measured.'
            continue
        }
        foreach ($pair in @(@{ From = $ReferenceDc; To = $peer }, @{ From = $peer; To = $ReferenceDc })) {
            $objCount = 0
            $verboseText = ''
            $ok = $true
            $reason = ''
            try {
                # 4>&1 redirects the verbose stream into the output so the true count can be read;
                # the object count alone stops at the cmdlet's 100-record cap.
                $captured = @(Get-DfsrBacklog -GroupName $group -FolderName $folder `
                        -SourceComputerName $pair.From -DestinationComputerName $pair.To `
                        -Verbose -ErrorAction Stop 4>&1)
                foreach ($item in $captured) {
                    if ($item -is [System.Management.Automation.VerboseRecord]) { $verboseText = ("{0} {1}" -f $verboseText, $item.Message) }
                    else { $objCount++ }
                }
            }
            catch {
                $ok = $false
                $reason = $_.Exception.Message
            }
            $resolved = Get-AdfaDfsrBacklogCount -VerboseMessage $verboseText -ObjectCount $objCount `
                -DisplayCap ([int]$script:Config.DfsrBacklogDisplayCap) -Succeeded $ok
            $verdict = Get-AdfaSysvolBacklogVerdict -SourceDc ([string]$pair.From) -DestinationDc ([string]$pair.To) `
                -Count ([int]$resolved.Count) -Exact ([bool]$resolved.Exact) `
                -WarnAt ([int]$script:Config.SysvolBacklogWarnAt) -FailAt ([int]$script:Config.SysvolBacklogFailAt) -Reason $reason
            $rows += New-Finding -Scope $DomainName -Area 'SysvolBacklog' `
                -Item ("Backlog {0} -> {1}" -f $pair.From, $pair.To) -Status $verdict.Status -Detail $verdict.Detail
        }
    }
    return @($rows)
}

function Get-AdfaDfsrEventLog {
    <#
    .SYNOPSIS
        Scans each DC's DFS Replication log for the events that decide SYSVOL health.
    .DESCRIPTION
        The SYSVOL counterpart of Get-AdfaDsEventLog, and gated on log coverage the same way:
        finding no events only means something if the log reaches back across the window. After
        a ransomware recovery it frequently does not.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # DC rows (HostName, Scope) or plain host names (PORT-PLAN C2e).
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [pscredential]$Credential,
        [int]$LookbackDays = 14,
        [int]$RpcPortTimeoutMs = 1200,
        # Domains whose DC enumeration threw (Domain, Error), and the domains of the run.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    $population = @(Get-AdfaDcPopulationRow -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Area 'DfsrEvents' `
            -Label 'DFS Replication events' -NothingRead 'The DFS Replication log of none of its DCs was read.')
    if ($targets.Count -eq 0) {
        return @(@($population) + @(New-Finding -Area 'DfsrEvents' -Item 'DFS Replication events' -Status $script:Status.NotAssessed `
                    -Detail 'No domain controllers were enumerated, so the DFS Replication log could not be read. This is not a clean result.'))
    }
    $ids = @($script:Config.DfsrEventsOfInterest | ForEach-Object { [int]$_.Id })
    $meta = @{}
    foreach ($e in $script:Config.DfsrEventsOfInterest) { $meta[[int]$e.Id] = $e }
    $windowStart = (Get-Date).AddDays(-$LookbackDays)
    $rows = @()

    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item '(unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and its DFS Replication log was not read.'
            continue
        }
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135) -TimeoutMs $RpcPortTimeoutMs
        if ($gate.Cause) {
            $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item $dc -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'the DFS Replication log was not read remotely')
            continue
        }
        if (-not $gate.Open[135]) {
            $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item $dc -Status $script:Status.NotAssessed -Detail 'RPC (135) not reachable - the DFS Replication log could not be read remotely.'
            continue
        }
        $cov = Get-AdfaEventLogCoverageForLog -ComputerName $dc -LogName 'DFS Replication' -Credential $Credential -WindowStart $windowStart
        $covNote = ''
        if ($cov.Coverage -ne 'Covered') {
            $covNote = ("The DFS Replication log does not cover the full {0}-day window (coverage: {1}{2}), so absence of an event proves nothing." -f `
                    $LookbackDays, $cov.Coverage, $(if ($null -ne $cov.OldestRecord) { ("; oldest record {0:yyyy-MM-dd HH:mm}" -f $cov.OldestRecord) } else { '' }))
        }
        $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item ("Log coverage on {0}" -f $dc) `
            -Status $(if ($cov.Coverage -eq 'Covered') { $script:Status.Pass } else { $script:Status.NotAssessed }) `
            -Detail $(if ($cov.Coverage -eq 'Covered') { ("DFS Replication log covers the full {0}-day window." -f $LookbackDays) } else { $covNote })

        try {
            $gwe = @{
                ComputerName    = $dc
                FilterHashtable = @{ LogName = 'DFS Replication'; Id = $ids; StartTime = $windowStart }
                MaxEvents       = 500
                ErrorAction     = 'Stop'
            }
            if ($Credential) { $gwe.Credential = $Credential }
            $events = @(Get-WinEvent @gwe)
            if (@($events).Count -eq 0) {
                if ($cov.Coverage -eq 'Covered') {
                    # Not a Pass: SYSVOL health is proven by seeing 4604, not by silence.
                    $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item $dc -Status $script:Status.Warning `
                        -Detail ("No DFS Replication events of interest in {0} day(s) - including no 4604 (SYSVOL initialised). Silence is not evidence that SYSVOL initialised; confirm the shares are present and that DFSR has logged a 4604 at some point." -f $LookbackDays)
                }
                else {
                    $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item $dc -Status $script:Status.NotAssessed `
                        -Detail ("No DFS Replication events of interest found, but this is NOT a pass. {0}" -f $covNote)
                }
                continue
            }
            foreach ($g in ($events | Group-Object Id)) {
                $id = [int]$g.Name
                $m = $meta[$id]
                $sev = $script:Status.Warning
                $meaning = ''
                if ($m) {
                    $meaning = [string]$m.Meaning
                    if ([string]$m.Severity -eq 'Fail') { $sev = $script:Status.Fail }
                    elseif ([string]$m.Severity -eq 'Info') { $sev = $script:Status.Info }
                }
                $last = ($g.Group | Sort-Object TimeCreated -Descending | Select-Object -First 1).TimeCreated
                $floor = ''
                if ($cov.Coverage -ne 'Covered') { $floor = (" Count is a MINIMUM - {0}" -f $covNote) }
                $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item ("Event {0} on {1}" -f $id, $dc) -Status $sev `
                    -Detail ("{0} occurrence(s) in {1} day(s), last {2:yyyy-MM-dd HH:mm}. {3}{4}" -f $g.Count, $LookbackDays, $last, $meaning, $floor)
            }
        }
        catch {
            if ($_.Exception.Message -match 'No events were found|There is not an event log') {
                $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item $dc -Status $script:Status.NotAssessed `
                    -Detail ("The DFS Replication log held no matching events or is not present: {0}. Not a pass." -f $_.Exception.Message)
            }
            else {
                $rows += New-Finding -Scope $scope -Area 'DfsrEvents' -Item $dc -Status $script:Status.NotAssessed -Detail ("DFS Replication log query failed: {0}" -f $_.Exception.Message)
            }
        }
    }
    return @(@($population) + @($rows))
}

function Get-AdfaDsEventLog {
    <#
    .SYNOPSIS
        Scans each DC's Directory Service event log (remotely, over the event log RPC
        interface) for the events that block or mask recovery: lingering objects,
        tombstone-lifetime exceeded, USN rollback, unsupported restore, source-DC GUID
        DNS failures and KCC topology failures. Unreachable DCs degrade to Not Assessed.
    .DESCRIPTION
        Every DC's log coverage is measured before any conclusion is drawn from it. Finding no
        events is only evidence if the log actually reaches back across the window: a log
        cleared during a ransomware recovery, or one that has simply wrapped, is silent for the
        same reason a healthy one is. So a clean scan over an incomplete window reports
        Not Assessed naming where coverage begins, never Pass, and a scan that DOES find events
        over an incomplete window reports the count as a floor rather than a total.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # DC rows (HostName, Scope) or plain host names (PORT-PLAN C2e).
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [pscredential]$Credential,
        [int]$LookbackDays = 14,
        [int]$RpcPortTimeoutMs = 1200,
        # Domains whose DC enumeration threw (Domain, Error), and the domains of the run.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    $population = @(Get-AdfaDcPopulationRow -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Area 'DsEvents' `
            -Label 'Directory Service events' -NothingRead 'The Directory Service log of none of its DCs was read.')
    $ids = @($script:Config.DsEventsOfInterest | ForEach-Object { [int]$_.Id })
    $meta = @{}
    foreach ($e in $script:Config.DsEventsOfInterest) { $meta[[int]$e.Id] = $e }

    $windowStart = (Get-Date).AddDays(-$LookbackDays)

    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item '(unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and its Directory Service log was not read.'
            continue
        }
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135) -TimeoutMs $RpcPortTimeoutMs
        if ($gate.Cause) {
            $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item $dc -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'its event log was not read remotely. Check the Directory Service log on the DC itself')
            continue
        }
        if (-not $gate.Open[135]) {
            $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item $dc -Status $script:Status.NotAssessed -Detail 'RPC (135) not reachable - event log could not be read remotely. Check the Directory Service log on the DC itself.'
            continue
        }

        # How far back does this log actually reach? Asked before the scan, because it decides
        # whether "no events" means anything at all.
        $cov = Get-AdfaEventLogCoverageForLog -ComputerName $dc -LogName 'Directory Service' -Credential $Credential -WindowStart $windowStart
        $covNote = Get-AdfaEventCoverageDetail -Coverage $cov.Coverage -OldestRecord $cov.OldestRecord `
            -LookbackDays $LookbackDays -Reason $cov.Reason -LogName 'Directory Service'
        $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item ("Log coverage on {0}" -f $dc) `
            -Status $(if ($cov.Coverage -eq 'Covered') { $script:Status.Pass } else { $script:Status.NotAssessed }) `
            -Detail $(if ($cov.Coverage -eq 'Covered') {
                    ("Directory Service log covers the full {0}-day window (oldest record {1:yyyy-MM-dd HH:mm})." -f $LookbackDays, $cov.OldestRecord)
                }
                else { $covNote })

        try {
            $gwe = @{
                ComputerName    = $dc
                FilterHashtable = @{ LogName = 'Directory Service'; Id = $ids; StartTime = $windowStart }
                MaxEvents       = 500
                ErrorAction     = 'Stop'
            }
            if ($Credential) { $gwe.Credential = $Credential }
            $events = @(Get-WinEvent @gwe)
            if (@($events).Count -eq 0) {
                # The fail-closed branch: silence over an incomplete window is not a clean bill
                # of health. Reporting Pass here is what let a wiped log look healthy.
                if ($cov.Coverage -eq 'Covered') {
                    $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item $dc -Status $script:Status.Pass -Detail ("No events of interest in the last {0} day(s); log covers the whole window." -f $LookbackDays)
                }
                else {
                    $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item $dc -Status $script:Status.NotAssessed -Detail ("No events of interest found, but this is NOT a pass. {0}" -f $covNote)
                }
                continue
            }
            foreach ($g in ($events | Group-Object Id)) {
                $id = [int]$g.Name
                $m = $meta[$id]
                $sev = $script:Status.Warning
                $meaning = ''
                if ($m) {
                    $meaning = [string]$m.Meaning
                    if ([string]$m.Severity -eq 'Fail') { $sev = $script:Status.Fail }
                }
                $last = ($g.Group | Sort-Object TimeCreated -Descending | Select-Object -First 1).TimeCreated
                # A count taken from a partial log is a lower bound, and saying so costs nothing.
                $floor = ''
                if ($cov.Coverage -ne 'Covered') { $floor = (" Count is a MINIMUM - {0}" -f $covNote) }
                $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item ("Event {0} on {1}" -f $id, $dc) -Status $sev -Detail ("{0} occurrence(s) in {1} day(s), last {2:yyyy-MM-dd HH:mm}. {3}{4}" -f $g.Count, $LookbackDays, $last, $meaning, $floor)
            }
        }
        catch {
            if ($_.Exception.Message -match 'No events were found') {
                if ($cov.Coverage -eq 'Covered') {
                    $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item $dc -Status $script:Status.Pass -Detail ("No events of interest in the last {0} day(s); log covers the whole window." -f $LookbackDays)
                }
                else {
                    $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item $dc -Status $script:Status.NotAssessed -Detail ("No events of interest found, but this is NOT a pass. {0}" -f $covNote)
                }
            }
            else {
                $rows += New-Finding -Scope $scope -Area 'DsEvents' -Item $dc -Status $script:Status.NotAssessed -Detail ("Event log query failed: {0}" -f $_.Exception.Message)
            }
        }
    }
    if ($targets.Count -eq 0) {
        $rows += New-Finding -Area 'DsEvents' -Item 'Directory Service events' -Status $script:Status.NotAssessed -Detail 'No domain controllers enumerated.'
    }
    return @(@($population) + @($rows))
}

# ===========================================================================
# region Restore integrity (USN rollback forensics, database instantiation)
# ===========================================================================

function Get-AdfaUsnRollbackVerdict {
    <#
    .SYNOPSIS
        Pure classification of the "Dsa Not Writable" registry marker on a DC.
    .DESCRIPTION
        This is the check that does not depend on the event log surviving. When a DC is rolled
        back by an unsupported method - a VM snapshot revert, a VHD copy, a disk image, a P2V
        without decommissioning the original - replication quarantines it and logs Directory
        Service event 2095. Microsoft is explicit that the event "may be overwritten before
        [it is] observed by an administrator", and names the registry entry as the fallback:

            HKLM\System\CurrentControlSet\Services\NTDS\Parameters
            Dsa Not Writable = 0x4     "provides forensic evidence that a USN rollback has occurred"

        https://learn.microsoft.com/troubleshoot/windows-server/active-directory/detect-and-recover-from-usn-rollback
        https://learn.microsoft.com/windows-server/identity/ad-ds/introduction-to-active-directory-domain-services-ad-ds-virtualization-level-100
        Read: 2026-09-21.

        That is exactly the situation this tool is aimed at: a forest recovered from an incident,
        where the Directory Service log may have been cleared or wrapped long before anyone looked.
        The marker persists in the registry regardless.

        Note what absence does and does not prove. No marker means no forensic evidence of a
        rollback on THIS operating-system installation - it does not prove no rollback ever
        happened, because a rebuilt or reinstalled DC carries no history. Reported as a pass with
        that limit stated, rather than as proof of health.
    .OUTPUTS
        [string] Rollback | OtherValue | NoEvidence | Unknown
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [bool]$Readable = $true,
        [AllowNull()][Nullable[bool]]$Present,
        [AllowNull()]$Value
    )
    if (-not $Readable) { return 'Unknown' }
    if ($null -eq $Present) { return 'Unknown' }
    if (-not $Present) { return 'NoEvidence' }
    # The documented value is 4. Anything else is present-but-undocumented: reported as itself
    # rather than silently treated as either clean or as a confirmed rollback.
    if ($null -ne $Value -and ([string]$Value) -eq '4') { return 'Rollback' }
    return 'OtherValue'
}

function Get-AdfaUsnRollbackDetail {
    <#
    .SYNOPSIS
        The sentence that goes with a Dsa Not Writable verdict.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][ValidateSet('Rollback', 'OtherValue', 'NoEvidence', 'Unknown')][string]$Verdict,
        [AllowNull()]$Value,
        [string]$Reason = ''
    )
    if ($Verdict -eq 'Rollback') {
        return ('"Dsa Not Writable" = 4 in the NTDS Parameters registry key. Microsoft documents this as forensic evidence that a USN ROLLBACK has occurred on this DC - an unsupported restore (VM snapshot revert, VHD or disk-image copy, or a P2V whose original was left running). Replication has quarantined this DC: Net Logon is paused and inbound and outbound replication are disabled, so accounts and passwords originating here do not reach the rest of the forest. This marker survives even when Directory Service event 2095 has been overwritten. Do NOT delete or edit the value - doing so removes the quarantine and permanently diverges this DC from the forest.')
    }
    if ($Verdict -eq 'OtherValue') {
        return ('"Dsa Not Writable" is present in the NTDS Parameters registry key with value {0}. Microsoft documents only 4, so this value is undocumented and is reported as found rather than interpreted. Its presence at all means the directory has flagged itself non-writable at some point - read Directory Service events 2095, 2103 and 1113/1115 on this DC and confirm replication is inbound and outbound before trusting it.' -f $Value)
    }
    if ($Verdict -eq 'NoEvidence') {
        return ('No "Dsa Not Writable" value in the NTDS Parameters registry key, so there is no forensic evidence of a USN rollback on this DC. Note the limit of that claim: it covers this operating-system installation only - a DC that was rebuilt or reinstalled after an incident carries no such history either way.')
    }
    $suffix = ''
    if (-not [string]::IsNullOrWhiteSpace($Reason)) { $suffix = (' Cause: {0}' -f $Reason) }
    return ('The NTDS Parameters registry key could not be read, so the USN-rollback forensic marker is unknown. This is the one check that does not depend on the event log, so it is worth completing by hand: read "Dsa Not Writable" under HKLM\System\CurrentControlSet\Services\NTDS\Parameters on the DC itself.{0}' -f $suffix)
}

function Get-AdfaUsnRollbackForensics {
    <#
    .SYNOPSIS
        Reads the "Dsa Not Writable" USN-rollback marker from each DC's registry.
    .DESCRIPTION
        Thin collector over Get-AdfaUsnRollbackVerdict, using the same remote-registry approach as
        the DC hardening checks and the same NTDS Parameters key.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        # DC rows (HostName, Scope) or plain host names (PORT-PLAN C2e).
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [int]$RpcPortTimeoutMs = 1200,
        # Domains whose DC enumeration threw (Domain, Error), and the domains of the run.
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    $rows = @(Get-AdfaDcPopulationRow -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Area 'RestoreIntegrity' `
            -Label 'USN rollback marker' -NothingRead 'The marker was read on none of its DCs.')
    if ($targets.Count -eq 0) {
        return @(@($rows) + @(New-Finding -Area 'RestoreIntegrity' -Item 'USN rollback forensics' -Status $script:Status.NotAssessed `
                    -Detail 'No domain controllers were enumerated, so the USN-rollback marker could not be read on any of them. This is not a clean result.'))
    }
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-Finding -Scope $scope -Area 'RestoreIntegrity' -Item 'USN rollback marker on (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and the marker was not read.'
            continue
        }
        $gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @(445) -TimeoutMs $RpcPortTimeoutMs
        if ($gate.Cause) {
            $rows += New-Finding -Scope $scope -Area 'RestoreIntegrity' -Item ("USN rollback marker on {0}" -f $dc) -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaUsnRollbackDetail -Verdict 'Unknown' -Value $null -Reason (Get-AdfaDcGateText -Cause $gate.Cause -NotRead 'the remote registry was not opened'))
            continue
        }
        if (-not $gate.Open[445]) {
            $rows += New-Finding -Scope $scope -Area 'RestoreIntegrity' -Item ("USN rollback marker on {0}" -f $dc) -Status $script:Status.NotAssessed `
                -Detail (Get-AdfaUsnRollbackDetail -Verdict 'Unknown' -Value $null -Reason 'SMB (445) not reachable, so the remote registry could not be opened.')
            continue
        }
        $raw = Get-AdfaUsnRollbackRaw -ComputerName $dc
        $readable = [bool]$raw.Readable
        $present = $raw.Present
        $value = $raw.Value
        $reason = [string]$raw.Reason
        $verdict = Get-AdfaUsnRollbackVerdict -Readable $readable -Present $present -Value $value
        $status = $script:Status.NotAssessed
        if ($verdict -eq 'Rollback') { $status = $script:Status.Fail }
        elseif ($verdict -eq 'OtherValue') { $status = $script:Status.Warning }
        elseif ($verdict -eq 'NoEvidence') { $status = $script:Status.Pass }
        $detail = Get-AdfaUsnRollbackDetail -Verdict $verdict -Value $value -Reason $reason
        # Access denied is not "could not be read for some reason": it says what is missing.
        if ($verdict -eq 'Unknown' -and (Get-AdfaRemoteReadErrorClass -Message $reason -ErrorCode ([string]$raw.ErrorCode)) -eq 'AccessDenied') {
            $detail = ("Access denied: the account running the assessment could not open the remote registry of this DC. {0}" -f $detail)
        }
        $rows += New-Finding -Scope $scope -Area 'RestoreIntegrity' -Item ("USN rollback marker on {0}" -f $dc) -Status $status -Detail $detail
    }
    return @($rows)
}

function Get-AdfaUsnRollbackRaw {
    <#
    .SYNOPSIS
        The read seam of the USN-rollback marker: the "Dsa Not Writable" value under the NTDS
        Parameters key of one DC, through the remote registry. Read-only. Never throws.
    .DESCRIPTION
        RegistryKey.OpenRemoteBaseKey(LocalMachine, <dc>), then OpenSubKey of the NTDS Parameters key
        in its read-only overload, GetValueNames and GetValue - reads only; each key is closed. The
        connection is made with the identity of the process: -Credential is not used by this read.
        Taken out of Get-AdfaUsnRollbackForensics (PORT-PLAN C14c) so the collector can be tested
        without a DC.
    .OUTPUTS
        [pscustomobject] Readable, Present ($null unless Readable), Value, Reason, ErrorCode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$ComputerName)
    $out = [pscustomobject]@{ Readable = $false; Present = $null; Value = $null; Reason = ''; ErrorCode = '' }
    $reg = $null
    $key = $null
    try {
        $reg = [Microsoft.Win32.RegistryKey]::OpenRemoteBaseKey('LocalMachine', $ComputerName)
        $key = $reg.OpenSubKey('SYSTEM\CurrentControlSet\Services\NTDS\Parameters')
        if ($null -eq $key) {
            $out.Reason = 'The NTDS Parameters key does not exist - is this host actually a domain controller?'
        }
        else {
            $out.Readable = $true
            $names = @($key.GetValueNames())
            $out.Present = [bool]($names -contains 'Dsa Not Writable')
            if ($out.Present) { $out.Value = $key.GetValue('Dsa Not Writable') }
        }
    }
    catch {
        $out.Reason = [string]$_.Exception.Message
        $out.ErrorCode = Get-AdfaRegistryReadErrorCode -Exception $_.Exception
    }
    finally {
        if ($null -ne $key) { $key.Close() }
        if ($null -ne $reg) { $reg.Close() }
    }
    return $out
}

function Get-AdfaRegistryReadErrorCode {
    <#
    .SYNOPSIS
        Pure: 'AccessDenied' when a remote registry read failed because access was refused, told by
        the exception TYPE, never by its text; '' otherwise.
    .DESCRIPTION
        RegistryKey.OpenRemoteBaseKey reports a refusal as System.UnauthorizedAccessException ("The
        user does not have the necessary registry rights") or System.Security.SecurityException, and
        OpenSubKey as SecurityException (Learn, read 2026-11-17:
        https://learn.microsoft.com/dotnet/api/microsoft.win32.registrykey.openremotebasekey and
        https://learn.microsoft.com/dotnet/api/microsoft.win32.registrykey.opensubkey). PowerShell
        wraps a .NET method's exception in
        MethodInvocationException, so the chain of inner exceptions is walked. The message is
        localised on a host whose language is not English, which is why the type decides.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Exception)
    $ex = $Exception
    while ($null -ne $ex) {
        if ($ex -is [System.UnauthorizedAccessException] -or $ex -is [System.Security.SecurityException]) { return 'AccessDenied' }
        $innerProp = $ex.PSObject.Properties['InnerException']
        if ($null -eq $innerProp) { break }
        $ex = $innerProp.Value
    }
    return ''
}

function Get-AdfaInvocationIdVerdict {
    <#
    .SYNOPSIS
        Pure verdict on database-instantiation identity across the forest's DSAs.
    .DESCRIPTION
        invocationId identifies the INSTANTIATION of a DC's database, where objectGUID identifies
        the DSA itself. A supported restore resets invocationId; an unsupported one leaves it
        intact, which is precisely what lets a rolled-back DC go unnoticed.

        Only one thing about it is concludable from a single point-in-time read, and this is it:
        two DSAs sharing an invocationId means one database was CLONED from the other - a copied
        VHD or disk image - because the value is meant to be unique per instantiation. Every
        replication partner then believes both DCs have already received each other's changes.

        What this deliberately does NOT claim: a rollback cannot be detected from one read of a
        single DC, because that needs the value compared against a previous one. The value is
        emitted per DC so that comparison is possible - a re-run and a diff of Assessment.json
        between runs will show an invocationId that changed, which means a restore happened
        between them.
    .OUTPUTS
        [pscustomobject[]] Finding rows.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DsaInventory = @()
    )
    $rows = @()
    $dsas = @($DsaInventory | Where-Object { $null -ne $_ })
    if ($dsas.Count -eq 0) {
        return @(New-Finding -Area 'RestoreIntegrity' -Item 'Database instantiation (invocationId)' -Status $script:Status.NotAssessed `
                -Detail 'No DSA objects could be read, so database instantiation identity is unknown. This is not a clean result.')
    }

    $withId = @()
    $withoutId = @()
    foreach ($d in $dsas) {
        $name = ''
        $nProp = $d.PSObject.Properties['DnsHostName']
        if ($null -ne $nProp -and $null -ne $nProp.Value) { $name = [string]$nProp.Value }
        if ([string]::IsNullOrWhiteSpace($name)) {
            $sProp = $d.PSObject.Properties['ServerDn']
            if ($null -ne $sProp -and $null -ne $sProp.Value) { $name = [string]$sProp.Value }
        }
        $id = ''
        $iProp = $d.PSObject.Properties['InvocationId']
        if ($null -ne $iProp -and $null -ne $iProp.Value) { $id = [string]$iProp.Value }
        if ([string]::IsNullOrWhiteSpace($id)) { $withoutId += $name }
        else { $withId += [pscustomobject]@{ Name = $name; Id = $id } }
    }

    # The one conclusion a single read supports.
    $dupes = @($withId | Group-Object -Property Id | Where-Object { $_.Count -gt 1 })
    if ($dupes.Count -gt 0) {
        foreach ($g in $dupes) {
            $who = (@($g.Group | ForEach-Object { $_.Name }) -join ', ')
            $rows += New-Finding -Area 'RestoreIntegrity' -Item 'Duplicate database instantiation (invocationId)' -Status $script:Status.Fail `
                -Detail ("{0} DCs share invocationId {1}: {2}. That value is unique per database instantiation, so a shared one means one DC's database was CLONED from the other - a copied VHD or disk image rather than a supported restore. Every replication partner now believes both DCs have already received each other's changes, so originating updates on either can be silently dropped. Demote and rebuild the copy, or restore it from a proper system-state backup; do not leave both running." -f `
                    $g.Count, $g.Name, $who)
        }
    }
    else {
        $rows += New-Finding -Area 'RestoreIntegrity' -Item 'Database instantiation (invocationId)' -Status $script:Status.Pass `
            -Detail ("All {0} DSA(s) with a readable invocationId have a distinct value, so no DC's database is a clone of another's. Note this cannot detect a rollback on its own - that needs the value compared with a previous run. The per-DC values are in the report so that comparison is possible: re-run before and after each change window and diff Assessment.json, where an invocationId that has changed means a restore happened in between." -f $withId.Count)
    }

    if ($withoutId.Count -gt 0) {
        $rows += New-Finding -Area 'RestoreIntegrity' -Item 'invocationId - not readable' -Status $script:Status.NotAssessed `
            -Detail ("{0} DSA(s) returned no invocationId: {1}. Those DCs are excluded from the clone check above, so it is a partial result, not a clean one." -f $withoutId.Count, ($withoutId -join ', '))
    }

    # The baseline itself, as Info, so the values are in the report and in the JSON.
    foreach ($w in $withId) {
        $rows += New-Finding -Area 'RestoreIntegrity' -Item ("invocationId of {0}" -f $w.Name) -Status $script:Status.Info `
            -Detail ("{0} - baseline for comparison against a later run; a change means this DC's database was restored or reinstantiated." -f $w.Id)
    }
    return @($rows)
}

# ===========================================================================
# region Reachability classes, site coverage, clock offset reference, stale objects, SYSVOL engine (PORT-PLAN C14)
# ===========================================================================
# Catalogue REACH-001..002, SITE-001, TIME-001, STALE-001..002, SYSVOL-004, built into the existing
# sections PortMatrix, Topology, TimeHierarchy, StaleObjects and Sysvol. Every read here is a query:
# name resolution, a TCP connect that sends nothing, a read-only file open, w32tm /stripchart and
# directory reads with listed properties. The sources and read dates are next to the config tables.

function New-AdfaC14Row {
    <#
    .SYNOPSIS
        Pure: one row of a C14 check. Names, addresses and lists go in their own columns, never in
        Detail: the consolidated findings choose a recommendation from Detail, and no other column is
        read there. NotRun is added to the finding after the recommendation is chosen.
    .OUTPUTS
        [pscustomobject] Scope, Area, Item, Status, Detail, Evidence, the given columns, NotRun.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Area,
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Item,
        [Parameter(Mandatory)][ValidateSet('Pass', 'Warning', 'Fail', 'Not Assessed', 'Info')][string]$Status,
        [AllowEmptyString()][string]$Detail = '',
        [AllowEmptyString()][string]$Evidence = '',
        [AllowNull()][System.Collections.IDictionary]$Columns = $null,
        [AllowEmptyString()][string]$NotRun = ''
    )
    $row = [ordered]@{ Scope = $Scope; Area = $Area; Item = $Item; Status = $Status; Detail = $Detail; Evidence = $Evidence }
    if ($null -ne $Columns) { foreach ($k in @($Columns.Keys)) { $row[[string]$k] = $Columns[$k] } }
    $row['NotRun'] = $NotRun
    return [pscustomobject]$row
}

function Merge-AdfaSpecConfig {
    <#
    .SYNOPSIS
        Pure merge of an override over a built-in table that declares its own overridable keys, with
        validation. The validator of the five C14 sections of -ConfigOverridePath: Reach,
        SiteCoverage, ClockSkew, Stale and SysvolEngine.
    .DESCRIPTION
        The table's OverrideSpec names every key a file may set and how it is checked: Kind 'Status'
        (a string, one of Allowed) or Kind 'Int' (a JSON number, a whole number from Min to Max).
        Every other key - ports, paths, patterns, DN templates, sources, vendor values - is refused as
        unknown, so a file can never make a status Pass or point a read somewhere else.

        Refused with the reason: an override that is not one object, an empty object, an unknown key,
        a key named twice, a null, a status that is not a string or not in its set, a number written
        as text, a fraction, a number out of range. Provenance (ThresholdSource) names the file for the
        keys it supplied and the built-in source for the others.
    .OUTPUTS
        [hashtable]
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory)][hashtable]$BaseConfig,
        [AllowNull()]$Override,
        [string]$OverrideSource = ''
    )
    $merged = @{}
    foreach ($k in @($BaseConfig.Keys)) { $merged[$k] = $BaseConfig[$k] }
    if ($null -eq $Override) { return $merged }
    $label = [string]$BaseConfig['OverrideLabel']
    if ([string]::IsNullOrWhiteSpace($label)) { $label = 'Config' }
    $spec = $BaseConfig['OverrideSpec']
    if ($null -eq $spec -or $spec -isnot [System.Collections.IDictionary] -or $spec.Count -eq 0) {
        throw ("{0} config: the built-in table declares no key a file may set. This is a defect in the tool, not in the file." -f $label)
    }
    $table = ConvertTo-AdfaOverrideTable -Value $Override
    if ($null -eq $table) {
        throw ("{0} config override must be a single object with named keys (for example {1}), not a {2}." -f $label, [string]$BaseConfig['OverrideExample'], $Override.GetType().Name)
    }
    if ($table.Count -eq 0) { throw ("{0} config override is an empty object. It names no key, so it would change nothing while appearing to be in force." -f $label) }
    $known = @($spec.Keys | ForEach-Object { [string]$_ })
    $numericTypes = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64], [uint64], [single], [double], [decimal])
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $supplied = @()
    foreach ($k in @($table.Keys)) {
        $given = [string]$k
        $match = @($known | Where-Object { $_ -eq $given })
        if ($match.Count -eq 0) {
            throw ("{0} config override names an unknown key '{1}'. Known keys: {2}. {3}" -f $label, $given, ($known -join ', '), [string]$BaseConfig['OverrideRefused'])
        }
        $name = [string]$match[0]
        if ($supplied -contains $name) { throw ("{0} config override names '{1}' more than once." -f $label, $name) }
        $value = $table[$k]
        if ($null -eq $value) { throw ("{0} config override sets '{1}' to null. Remove the key to keep the built-in value." -f $label, $name) }
        $rule = $spec[$name]
        $kind = [string](Get-AdfaConfigValue -Entry $rule -Name 'Kind')
        if ($kind -eq 'Int') {
            $min = [int](Get-AdfaConfigValue -Entry $rule -Name 'Min')
            $max = [int](Get-AdfaConfigValue -Entry $rule -Name 'Max')
            $unit = [string](Get-AdfaConfigValue -Entry $rule -Name 'Unit')
            if ($value -is [array] -or $numericTypes -notcontains $value.GetType()) {
                throw ("{0} config override sets '{1}' to a {2}. It must be a JSON number, written without quotes." -f $label, $name, $value.GetType().Name)
            }
            $number = [double]$value
            if ([double]::IsNaN($number) -or [double]::IsInfinity($number) -or $number -ne [math]::Floor($number) -or $number -lt $min -or $number -gt $max) {
                throw ("{0} config override sets '{1}' to {2}. It must be a whole number from {3} to {4} ({5})." -f $label, $name, $number.ToString('0.####', $inv), $min, $max, $unit)
            }
            $merged[$name] = [int]$number
        }
        elseif ($kind -eq 'Status') {
            $allowedSet = @(Get-AdfaConfigValue -Entry $rule -Name 'Allowed')
            if ($value -isnot [string]) { throw ("{0} config override sets '{1}' to a {2}. It must be a string: one of {3}." -f $label, $name, $value.GetType().Name, ($allowedSet -join ', ')) }
            $allowed = @($allowedSet | Where-Object { $_ -eq $value.Trim() })
            if ($allowed.Count -eq 0) { throw ("{0} config override sets '{1}' to '{2}'. It must be one of {3}." -f $label, $name, $value, ($allowedSet -join ', ')) }
            $merged[$name] = [string]$allowed[0]
        }
        else {
            throw ("{0} config: the key '{1}' is declared with an unknown kind '{2}'. This is a defect in the tool, not in the file." -f $label, $name, $kind)
        }
        $supplied += $name
    }
    $from = 'an override whose source was not recorded'
    if (-not [string]::IsNullOrWhiteSpace($OverrideSource)) { $from = ("{0} (loaded {1})" -f $OverrideSource, (Get-Date).ToString('yyyy-MM-dd')) }
    $fromOverride = @($known | Where-Object { $supplied -contains $_ })
    $text = ("{0} for {1}" -f $from, ($fromOverride -join ', '))
    $builtIn = @($known | Where-Object { $supplied -notcontains $_ })
    if ($builtIn.Count -gt 0) { $text = ("{0}; {1}, for {2}" -f $text, [string]$BaseConfig['ThresholdSource'], ($builtIn -join ', ')) }
    $merged['ThresholdSource'] = $text
    return $merged
}

function Get-AdfaC14NameList {
    <#
    .SYNOPSIS
        Pure: up to -Cap names joined with '; ', and how many were left out. For display columns only.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyCollection()][string[]]$Names = @(), [int]$Cap = 20)
    $all = @($Names | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($all.Count -eq 0) { return '' }
    if ($Cap -le 0) { return ("({0} not listed: NameListCap is 0)" -f $all.Count) }
    $shown = @($all | Select-Object -First $Cap)
    $text = ($shown -join '; ')
    if ($all.Count -gt $shown.Count) { $text = ("{0}; and {1} more" -f $text, ($all.Count - $shown.Count)) }
    return $text
}

function Get-AdfaReadClassPhrase {
    <#
    .SYNOPSIS
        Pure: the words a row uses for a read-failure class, so that unreachable, access denied and
        timed out are never worded alike.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyString()][string]$Class)
    switch ([string]$Class) {
        'AccessDenied' { return 'access denied' }
        'Unreachable' { return 'unreachable' }
        'TimedOut' { return 'timed out' }
        'NotFound' { return 'not found' }
    }
    return 'failed'
}

# --- REACH-001/002 -----------------------------------------------------------------------------

function Resolve-AdfaHostAddress {
    <#
    .SYNOPSIS
        Seam: the addresses a host name resolves to, bounded in time. Never throws.
    .DESCRIPTION
        Dns.BeginGetHostAddresses, waited for at most -TimeoutMs. A lookup that did not finish in time
        is TimedOut; a SocketException carries its SocketError name (HostNotFound, TryAgain, NoRecovery,
        NoData - the four name resolution failures, Learn SocketError, read 2026-11-17); any other
        exception is a fault of the input or the tool, with no SocketError. Sends nothing to the DC.
    .OUTPUTS
        [pscustomobject] Ok, Addresses (string[]), SocketError, TimedOut, Error.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$HostName,
        [ValidateRange(100, 60000)][int]$TimeoutMs = 3000
    )
    $out = [pscustomobject]@{ Ok = $false; Addresses = @(); SocketError = ''; TimedOut = $false; Error = '' }
    try {
        $iar = [System.Net.Dns]::BeginGetHostAddresses($HostName, $null, $null)
        if (-not $iar.AsyncWaitHandle.WaitOne($TimeoutMs, $false)) {
            $out.TimedOut = $true
            $out.Error = ("name resolution did not complete within {0} ms" -f $TimeoutMs)
            return $out
        }
        $addresses = @([System.Net.Dns]::EndGetHostAddresses($iar))
        $out.Addresses = @($addresses | Where-Object { $null -ne $_ } | ForEach-Object { $_.ToString() })
        $out.Ok = $true
    }
    catch {
        $ex = $_.Exception
        while ($null -ne $ex.InnerException -and $ex -isnot [System.Net.Sockets.SocketException]) { $ex = $ex.InnerException }
        if ($ex -is [System.Net.Sockets.SocketException]) { $out.SocketError = [string]$ex.SocketErrorCode }
        $out.Error = ([string]$ex.Message).Trim()
    }
    return $out
}

function Test-AdfaTcpAddress {
    <#
    .SYNOPSIS
        Seam: one TCP connection attempt to an IP ADDRESS and port, bounded in time, closed at once.
        Sends no data. Never throws.
    .DESCRIPTION
        Takes an address, never a name: resolving inside the connect would merge "does not resolve"
        with "port silent", which have different fixes. A wait that runs out is TimedOut; a
        SocketException carries its SocketError name (ConnectionRefused, TimedOut, HostUnreachable,
        ...). The client is closed in a finally block. One attempt, no retry.
    .OUTPUTS
        [pscustomobject] Outcome (Open | Failed), SocketError, TimedOut, Error.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Address,
        [Parameter(Mandatory)][ValidateRange(1, 65535)][int]$Port,
        [ValidateRange(100, 60000)][int]$TimeoutMs = 3000
    )
    $out = [pscustomobject]@{ Outcome = 'Failed'; SocketError = ''; TimedOut = $false; Error = '' }
    $ip = $null
    if (-not [System.Net.IPAddress]::TryParse($Address, [ref]$ip)) {
        $out.Error = ("'{0}' is not an IP address; this probe connects to an address only" -f $Address)
        return $out
    }
    $client = $null
    try {
        $client = New-Object System.Net.Sockets.TcpClient($ip.AddressFamily)
        $iar = $client.BeginConnect($ip, $Port, $null, $null)
        if (-not $iar.AsyncWaitHandle.WaitOne($TimeoutMs, $false)) {
            $out.TimedOut = $true
            $out.Error = ("no answer within {0} ms" -f $TimeoutMs)
        }
        else {
            $client.EndConnect($iar)
            $out.Outcome = 'Open'
        }
    }
    catch {
        $ex = $_.Exception
        while ($null -ne $ex.InnerException -and $ex -isnot [System.Net.Sockets.SocketException]) { $ex = $ex.InnerException }
        if ($ex -is [System.Net.Sockets.SocketException]) { $out.SocketError = [string]$ex.SocketErrorCode }
        $out.Error = ([string]$ex.Message).Trim()
    }
    finally {
        if ($null -ne $client) { $client.Close() }
    }
    return $out
}

function Get-AdfaProbeClass {
    <#
    .SYNOPSIS
        Pure: Open, Refused, TimedOut, NetworkUnreachable, Failed or NotProbed, for one probe result.
    .DESCRIPTION
        From the outcome first, then the wait that ran out, then the SocketError name against the
        lists in the Reach table. Anything not recognised is Failed and is quoted, not interpreted.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Probe, [hashtable]$Config = $script:Config.Reach)
    if ($null -eq $Probe) { return 'NotProbed' }
    $outcome = [string](Get-AdfaConfigValue -Entry $Probe -Name 'Outcome')
    if ($outcome -eq 'Open') { return 'Open' }
    if ([bool](Get-AdfaConfigValue -Entry $Probe -Name 'TimedOut')) { return 'TimedOut' }
    $se = [string](Get-AdfaConfigValue -Entry $Probe -Name 'SocketError')
    if ($se -ne '') {
        if (@($Config['TimedOutSocketErrors']) -contains $se) { return 'TimedOut' }
        if (@($Config['RefusedSocketErrors']) -contains $se) { return 'Refused' }
        if (@($Config['NetworkSocketErrors']) -contains $se) { return 'NetworkUnreachable' }
    }
    return 'Failed'
}

function Resolve-AdfaDcReachClass {
    <#
    .SYNOPSIS
        Pure: the reachability class of one DC, from its name resolution and its probes.
    .DESCRIPTION
        Classes (tool design, REACH-001/002; Microsoft publishes none):
          Unreachable       the name does not resolve (Unresolved), resolution timed out
                            (ResolveTimedOut), it resolved to no address (NoAddress), or LDAP (389)
                            answered on no address: TimedOut when any attempt got no answer, else
                            NetworkUnreachable when any had no route, else Refused when every one was
                            refused, else ConnectFailed.
          Reachable         LDAP and WinRM (5985) answer.
          WinRmUnavailable  LDAP and RPC (135) answer, WinRM does not: remote CIM falls back to DCOM.
          NotManageable     LDAP answers, neither default management port does.
          NotAssessed       the classification could not be made: a resolver fault that is not a
                            socket error (ResolveFailed), or a port that was not probed (NotProbed).
        Never Reachable without every probe it rests on.
    .OUTPUTS
        [pscustomobject] Class, Cause.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()]$Resolve,
        [AllowNull()][AllowEmptyCollection()]$LdapProbes = @(),
        [AllowNull()]$WinRm = $null,
        [AllowNull()]$Rpc = $null,
        [hashtable]$Config = $script:Config.Reach
    )
    if ($null -eq $Resolve) { return [pscustomobject]@{ Class = 'NotAssessed'; Cause = 'NotProbed' } }
    if (-not [bool](Get-AdfaConfigValue -Entry $Resolve -Name 'Ok')) {
        if ([bool](Get-AdfaConfigValue -Entry $Resolve -Name 'TimedOut')) { return [pscustomobject]@{ Class = 'Unreachable'; Cause = 'ResolveTimedOut' } }
        $se = [string](Get-AdfaConfigValue -Entry $Resolve -Name 'SocketError')
        if ($se -ne '' -and @($Config['UnresolvedSocketErrors']) -contains $se) { return [pscustomobject]@{ Class = 'Unreachable'; Cause = 'Unresolved' } }
        return [pscustomobject]@{ Class = 'NotAssessed'; Cause = 'ResolveFailed' }
    }
    if (@(Get-AdfaConfigValue -Entry $Resolve -Name 'Addresses' | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }).Count -eq 0) {
        return [pscustomobject]@{ Class = 'Unreachable'; Cause = 'NoAddress' }
    }
    $classes = @(@($LdapProbes) | Where-Object { $null -ne $_ } | ForEach-Object { Get-AdfaProbeClass -Probe $_ -Config $Config })
    if ($classes.Count -eq 0) { return [pscustomobject]@{ Class = 'NotAssessed'; Cause = 'NotProbed' } }
    if ($classes -contains 'Open') {
        $w = Get-AdfaProbeClass -Probe $WinRm -Config $Config
        $r = Get-AdfaProbeClass -Probe $Rpc -Config $Config
        if ($w -eq 'Open') { return [pscustomobject]@{ Class = 'Reachable'; Cause = '' } }
        if ($w -eq 'NotProbed' -or $r -eq 'NotProbed') { return [pscustomobject]@{ Class = 'NotAssessed'; Cause = 'NotProbed' } }
        if ($r -eq 'Open') { return [pscustomobject]@{ Class = 'WinRmUnavailable'; Cause = '' } }
        return [pscustomobject]@{ Class = 'NotManageable'; Cause = 'ManagementPortsSilent' }
    }
    $cause = 'ConnectFailed'
    if ($classes -contains 'TimedOut') { $cause = 'TimedOut' }
    elseif ($classes -contains 'NetworkUnreachable') { $cause = 'NetworkUnreachable' }
    elseif (@($classes | Where-Object { $_ -ne 'Refused' }).Count -eq 0) { $cause = 'Refused' }
    return [pscustomobject]@{ Class = 'Unreachable'; Cause = $cause }
}

function Get-AdfaDcReachability {
    <#
    .SYNOPSIS
        The reachability record of one DC: probed once per run, then read from the cache.
    .DESCRIPTION
        Name resolution (Resolve-AdfaHostAddress), then LDAP (389) on each address until one answers,
        then WinRM (5985) and RPC (135) at that address only. A DC already Unreachable is not probed
        on the management ports. What was measured, and only that, is written into the shared port
        cache that Test-AdfaDcPort reads, so a later section reuses it instead of probing again. Read
        only: a TCP connection that sends no data, closed at once.
    .OUTPUTS
        [pscustomobject] HostName, Class, Cause, Addresses, LdapAddress, PortText, TimeoutMs, Error,
        SocketError.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$HostName,
        [hashtable]$Config = $script:Config.Reach
    )
    $key = $HostName.ToLowerInvariant()
    if ($script:DcReachCache.ContainsKey($key)) { return $script:DcReachCache[$key] }
    $timeout = [int]$Config['ProbeTimeoutMs']
    $ldapPort = [int]$Config['LdapPort']
    $winRmPort = [int]$Config['WinRmPort']
    $rpcPort = [int]$Config['RpcPort']
    $resolve = Resolve-AdfaHostAddress -HostName $HostName -TimeoutMs $timeout
    $ldapProbes = @()
    $ldapAddress = ''
    $winRm = $null
    $rpc = $null
    $portText = @()
    if ([bool]$resolve.Ok) {
        foreach ($a in @($resolve.Addresses)) {
            $probe = Test-AdfaTcpAddress -Address ([string]$a) -Port $ldapPort -TimeoutMs $timeout
            $ldapProbes += $probe
            $probeClass = Get-AdfaProbeClass -Probe $probe -Config $Config
            $portText += ("{0} {1}={2}" -f $a, $ldapPort, $probeClass)
            if ($probeClass -eq 'Open') { $ldapAddress = [string]$a; break }
        }
        if ($ldapAddress -ne '') {
            $winRm = Test-AdfaTcpAddress -Address $ldapAddress -Port $winRmPort -TimeoutMs $timeout
            $rpc = Test-AdfaTcpAddress -Address $ldapAddress -Port $rpcPort -TimeoutMs $timeout
            $portText += ("{0} {1}={2}" -f $ldapAddress, $winRmPort, (Get-AdfaProbeClass -Probe $winRm -Config $Config))
            $portText += ("{0} {1}={2}" -f $ldapAddress, $rpcPort, (Get-AdfaProbeClass -Probe $rpc -Config $Config))
        }
    }
    $class = Resolve-AdfaDcReachClass -Resolve $resolve -LdapProbes $ldapProbes -WinRm $winRm -Rpc $rpc -Config $Config
    $record = [pscustomobject]@{
        HostName = $HostName; Class = [string]$class.Class; Cause = [string]$class.Cause
        Addresses = @($resolve.Addresses); LdapAddress = $ldapAddress; PortText = ($portText -join '; ')
        TimeoutMs = $timeout; Error = [string]$resolve.Error; SocketError = [string]$resolve.SocketError
    }
    # Only what was measured goes into the shared cache. An unprobed port is left out, never written
    # as closed: a section that needs it probes it itself.
    if (@($ldapProbes).Count -gt 0) { $script:DcPortCache[('{0}:{1}' -f $key, $ldapPort)] = ($ldapAddress -ne '') }
    if ($null -ne $winRm) { $script:DcPortCache[('{0}:{1}' -f $key, $winRmPort)] = ((Get-AdfaProbeClass -Probe $winRm -Config $Config) -eq 'Open') }
    if ($null -ne $rpc) { $script:DcPortCache[('{0}:{1}' -f $key, $rpcPort)] = ((Get-AdfaProbeClass -Probe $rpc -Config $Config) -eq 'Open') }
    $script:DcReachCache[$key] = $record
    return $record
}

function Get-AdfaDcReachRecord {
    <#
    .SYNOPSIS
        The reachability record of one DC if it was classified in this run; $null otherwise. Probes
        nothing.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][AllowEmptyString()][string]$HostName)
    if ([string]::IsNullOrWhiteSpace($HostName)) { return $null }
    $key = $HostName.ToLowerInvariant()
    if ($script:DcReachCache.ContainsKey($key)) { return $script:DcReachCache[$key] }
    return $null
}

function Get-AdfaC14UnreachableText {
    <#
    .SYNOPSIS
        Pure: the words for one Unreachable cause. Never mentions access: a refused read is not a
        reachability class.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyString()][string]$Cause, [int]$TimeoutMs = 3000, [AllowNull()][AllowEmptyString()][string]$SocketError = '')
    switch ([string]$Cause) {
        'Unresolved' { return ("the host name does not resolve: name resolution failed ({0})" -f $SocketError) }
        'ResolveTimedOut' { return ("name resolution did not complete within {0} ms" -f $TimeoutMs) }
        'NoAddress' { return 'name resolution returned no address' }
        'Refused' { return 'every address refused the connection on LDAP (389): the host is up but nothing accepts LDAP there, or a firewall rejects it' }
        'TimedOut' { return ("LDAP (389) gave no answer within {0} ms on at least one address and answered on none: filtered, or the host is down" -f $TimeoutMs) }
        'NetworkUnreachable' { return 'there is no route to the host from the host running the assessment' }
    }
    return 'the connection to LDAP (389) failed on every address'
}

function Get-AdfaDcReachCause {
    <#
    .SYNOPSIS
        '' unless this DC was classified Unreachable in this run; then the reason, worded for the row
        of any section that did not read it. Probes nothing.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()][AllowEmptyString()][string]$HostName)
    $record = Get-AdfaDcReachRecord -HostName $HostName
    if ($null -eq $record -or [string]$record.Class -ne 'Unreachable') { return '' }
    return ("Unreachable, classified once for this run by the reachability probe: {0}" -f (Get-AdfaC14UnreachableText -Cause ([string]$record.Cause) -TimeoutMs ([int]$record.TimeoutMs) -SocketError ([string]$record.SocketError)))
}

function Get-AdfaDcProbeGate {
    <#
    .SYNOPSIS
        The one way a per-DC section probes a DC (PORT-PLAN C1b, C14c): the reachability class
        first, then the shared port cache.
    .DESCRIPTION
        A DC the reachability probe classified Unreachable in this run (its name does not resolve,
        or LDAP 389 answered on no address) is not probed again on any port: Cause is that class,
        worded by Get-AdfaDcReachCause, and every port is reported closed without a connection.
        Before PORT-PLAN C14c every section probed such a DC again on its own ports, because the
        classification measures 5985 and 135 only where 389 answered, so the cache held nothing
        for them.

        Any other DC is probed once per port in the whole run through Test-AdfaDcPort; a port the
        classification already measured (389, 5985, 135) comes from the cache. A DC whose default
        management ports are silent (NotManageable) or that answers RPC but not WinRM
        (WinRmUnavailable) is not Unreachable: its sections keep their own port wording.

        Read only: a TCP connection that sends no data, closed at once (Test-TcpPort). Probes
        nothing for an empty host name.
    .OUTPUTS
        [pscustomobject] Cause ('' unless the DC was classified Unreachable), Open (hashtable:
        port -> bool).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$ComputerName,
        [AllowNull()][AllowEmptyCollection()][int[]]$Ports = @(),
        [int]$TimeoutMs = 1200
    )
    $open = @{}
    foreach ($p in @($Ports)) { $open[[int]$p] = $false }
    if ([string]::IsNullOrWhiteSpace($ComputerName)) { return [pscustomobject]@{ Cause = ''; Open = $open } }
    $cause = Get-AdfaDcReachCause -HostName $ComputerName
    if (-not [string]::IsNullOrWhiteSpace($cause)) { return [pscustomobject]@{ Cause = [string]$cause; Open = $open } }
    foreach ($p in @($Ports)) { $open[[int]$p] = [bool](Test-AdfaDcPort -ComputerName $ComputerName -Port ([int]$p) -TimeoutMs $TimeoutMs) }
    return [pscustomobject]@{ Cause = ''; Open = $open }
}

function Get-AdfaDcGateText {
    <#
    .SYNOPSIS
        Pure: the Detail of a row a section could not read because the DC is classified
        Unreachable - the class, then what was not read. The same cause in every section.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$Cause,
        [Parameter(Mandatory)][string]$NotRead
    )
    return ("{0}, so {1}." -f $Cause.Trim().TrimEnd('.'), $NotRead.Trim().TrimEnd('.'))
}

function Get-AdfaDcPopulationRow {
    <#
    .SYNOPSIS
        Pure: the "<label> (population): <domain>" rows of a per-DC section (PORT-PLAN C2e), one
        for each scoped domain its DC rows do not account for, in the New-Finding shape.
    .DESCRIPTION
        DECLARED POPULATION: Get-AdfaDcPopulationGap's - the domains named in -ScopedDomains plus
        any named only in -InventoryFailures. Each such domain without a DC row gets one Not
        Assessed row naming why (its enumeration threw, with the error; or it returned no DC),
        worded by Get-AdfaDcPopulationGapText. -Shape 'DomainController' builds the row in the
        replication-health shape, whose item column is DomainController.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$Targets = @(),
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @(),
        [Parameter(Mandatory)][string]$Area,
        [Parameter(Mandatory)][string]$Label,
        [Parameter(Mandatory)][string]$NothingRead,
        [ValidateSet('Finding', 'DomainController')][string]$Shape = 'Finding'
    )
    $rows = @()
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets @($Targets) -InventoryFailures @($InventoryFailures) -ScopedDomains @($ScopedDomains))) {
        $item = ("{0} (population): {1}" -f $Label, [string]$gap.Domain)
        $detail = Get-AdfaDcPopulationGapText -Gap $gap -NothingRead $NothingRead
        if ($Shape -eq 'DomainController') {
            $rows += [pscustomobject]@{
                DomainController = $item; PartnerCount = $null; PartnerErrors = $null
                LastSuccessMinutesAgo = $null; FailureCount = $null; OldestFailureTime = $null
                ReplicationQueue = $null; Status = $script:Status.NotAssessed
                FailureDetail = ''; Detail = $detail; Scope = [string]$gap.Domain
            }
        }
        else {
            $rows += New-Finding -Scope ([string]$gap.Domain) -Area $Area -Item $item -Status $script:Status.NotAssessed -Detail $detail
        }
    }
    return @($rows)
}

function Get-AdfaDcReachVerdict {
    <#
    .SYNOPSIS
        Pure: the "DC reachability: <host>" row of one DC, from its reachability record.
    .DESCRIPTION
        Unreachable is UnreachableStatus (Fail; Warning by override), NotManageable is
        NotManageableStatus (Warning; Info by override), Reachable and WinRmUnavailable are Pass,
        anything not classified is Not Assessed. Addresses and ports are display columns.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$HostName = '',
        [AllowEmptyString()][string]$Scope = '',
        [AllowNull()]$Record,
        [hashtable]$Config = $script:Config.Reach
    )
    $label = $HostName
    if ([string]::IsNullOrWhiteSpace($label)) { $label = '(unnamed)' }
    $item = ("DC reachability: {0}" -f $label)
    $evidence = ("Name resolution, then one TCP connection per port from the host running the assessment, no ICMP, no retry; probe time-out {0} ms. The classes are this tool's design (catalogue REACH-001/002), Microsoft publishes none; SocketError names from Learn (read 2026-11-17). A refused read (access is refused by the DC) is not a reachability class: the section whose read met it reports it. Grades: {1}." -f [int]$Config['ProbeTimeoutMs'], [string]$Config['ThresholdSource'])
    $columns = [ordered]@{ Class = ''; Cause = ''; Addresses = ''; Ports = '' }
    if ([string]::IsNullOrWhiteSpace($HostName)) {
        return New-AdfaC14Row -Area 'PortMatrix' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail 'The inventory holds a domain controller with no host name, so it was not probed. This is not a clean result.'
    }
    if ($null -eq $Record) {
        return New-AdfaC14Row -Area 'PortMatrix' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail 'No reachability result exists for this domain controller, so it is not classified. This is not a clean result.'
    }
    $class = [string](Get-AdfaConfigValue -Entry $Record -Name 'Class')
    $cause = [string](Get-AdfaConfigValue -Entry $Record -Name 'Cause')
    $timeout = [int]$Config['ProbeTimeoutMs']
    $recTimeout = Get-AdfaConfigValue -Entry $Record -Name 'TimeoutMs'
    if ($null -ne $recTimeout) { $timeout = [int]$recTimeout }
    $columns.Class = $class
    $columns.Cause = $cause
    $columns.Addresses = (@(Get-AdfaConfigValue -Entry $Record -Name 'Addresses') | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ }) -join '; '
    $columns.Ports = [string](Get-AdfaConfigValue -Entry $Record -Name 'PortText')
    switch ($class) {
        'Unreachable' {
            $why = Get-AdfaC14UnreachableText -Cause $cause -TimeoutMs $timeout -SocketError ([string](Get-AdfaConfigValue -Entry $Record -Name 'SocketError'))
            return New-AdfaC14Row -Area 'PortMatrix' -Scope $Scope -Item $item -Status ([string]$Config['UnreachableStatus']) -Evidence $evidence -Columns $columns `
                -Detail ("Unreachable: {0}. The sections that connect to this domain controller reuse this result: their rows of it are Not Assessed with this cause (the dcdiag grid row stays Fail, as for any DC dcdiag could not reach), and no port of it is probed again, the port matrix included. Rows read from the directory about it (its OS lifecycle, machine-account password, published certificates, RID pool) are still graded. A firewall between the host running the assessment and the DC gives the same answer as a DC that is down." -f $why)
        }
        'NotManageable' {
            return New-AdfaC14Row -Area 'PortMatrix' -Scope $Scope -Item $item -Status ([string]$Config['NotManageableStatus']) -Evidence $evidence -Columns $columns `
                -Detail 'LDAP (389) answered, but neither default management port did: WinRM (5985) and the RPC endpoint mapper (135). Directory reads still run; the remote reads of this DC (CIM, event log, w32tm, dcdiag) cannot. WinRM listeners can be configured on any port, so this says the default management ports are silent, not that the DC cannot be managed.'
        }
        'Reachable' {
            return New-AdfaC14Row -Area 'PortMatrix' -Scope $Scope -Item $item -Status $script:Status.Pass -Evidence $evidence -Columns $columns `
                -Detail 'LDAP (389) and WinRM (5985) answered.'
        }
        'WinRmUnavailable' {
            return New-AdfaC14Row -Area 'PortMatrix' -Scope $Scope -Item $item -Status $script:Status.Pass -Evidence $evidence -Columns $columns `
                -Detail 'LDAP (389) and the RPC endpoint mapper (135) answered; WinRM (5985) did not, so remote CIM reads use DCOM.'
        }
    }
    $err = [string](Get-AdfaConfigValue -Entry $Record -Name 'Error')
    $what = 'a port the class rests on was not probed'
    if ($cause -eq 'ResolveFailed') { $what = ("name resolution failed with an error that is not a resolution answer ({0})" -f $err) }
    return New-AdfaC14Row -Area 'PortMatrix' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
        -Detail ("The probe could not classify this domain controller: {0}. This is not a clean result." -f $what)
}

function Get-AdfaDcReachabilityRows {
    <#
    .SYNOPSIS
        PortMatrix, REACH-001/002: one "DC reachability: <host>" row per DC of every scoped domain, a
        population row per domain, each DC classified once for the run.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [hashtable]$Config = $script:Config.Reach,
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaC14Row -Area 'PortMatrix' -Scope ([string]$gap.Domain) -Item ("DC reachability (population): {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No domain controller of it was probed.')
    }
    if ($targets.Count -eq 0) {
        $why = 'No domain controllers were enumerated'
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = ("Domain controller enumeration failed ({0})" -f $EnumerationError) }
        $rows += New-AdfaC14Row -Area 'PortMatrix' -Item 'DC reachability' -Status $script:Status.NotAssessed -Detail ("{0}, so no domain controller was probed. This is not a clean result." -f $why)
        return @($rows)
    }
    $byDomain = [ordered]@{}
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $record = $null
        if (-not [string]::IsNullOrWhiteSpace($dc)) { $record = Get-AdfaDcReachability -HostName $dc -Config $Config }
        $row = Get-AdfaDcReachVerdict -HostName $dc -Scope ([string]$named.Scope) -Record $record -Config $Config
        $rows += $row
        $domainKey = [string]$named.Scope
        if (-not $byDomain.Contains($domainKey)) { $byDomain[$domainKey] = New-Object System.Collections.ArrayList }
        [void]$byDomain[$domainKey].Add([string]$row.Class)
    }
    foreach ($domainKey in @($byDomain.Keys)) {
        $classes = @($byDomain[$domainKey])
        $label = $domainKey
        if ($label -eq '') { $label = '(domain not known)' }
        $answered = @($classes | Where-Object { $_ -eq 'Reachable' -or $_ -eq 'WinRmUnavailable' }).Count
        $notManageable = @($classes | Where-Object { $_ -eq 'NotManageable' }).Count
        $unreachable = @($classes | Where-Object { $_ -eq 'Unreachable' }).Count
        $rows += New-AdfaC14Row -Area 'PortMatrix' -Scope $domainKey -Item ("DC reachability (population): {0}" -f $label) -Status $script:Status.Info `
            -Detail ("{0} domain controller(s) probed: {1} answered on LDAP and a default management port, {2} not remotely manageable on the default ports, {3} unreachable, {4} not classified." -f `
                $classes.Count, $answered, $notManageable, $unreachable, ($classes.Count - $answered - $notManageable - $unreachable))
    }
    return @($rows)
}

# --- SITE-001 ------------------------------------------------------------------------------------

function Get-AdfaSubnetSiteVerdict {
    <#
    .SYNOPSIS
        Pure: "Subnets without a site: <forest>" - whether any subnet object carries no site.
    .DESCRIPTION
        UnassignedStatus (Warning; Info by override) when any subnet read has no site; Pass when every
        subnet read has one; Not Assessed when the read failed or returned no subnet. Subnet names
        are in the Subnets column, never in Detail. "No siteObject means no site" is reasoning, and
        the Evidence says so.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()]$Subnets = @(),
        [AllowNull()][AllowEmptyString()][string]$ReadError = '',
        [AllowNull()][AllowEmptyString()][string]$ForestName = '',
        [hashtable]$Config = $script:Config.SiteCoverage
    )
    $label = $ForestName
    if ([string]::IsNullOrWhiteSpace($label)) { $label = '(forest not known)' }
    $item = ("Subnets without a site: {0}" -f $label)
    $evidence = 'siteObject of each subnet object under CN=Subnets,CN=Sites (Learn a-siteobject, read 2026-11-17), read with Get-ADReplicationSubnet, whose Site property is taken to carry it (provisional, PORT-PLAN C17). That an empty siteObject means "no site" is reasoning from Microsoft''s statement that "the siteObject property of the subnet object defines the name of the site that contains the client" (directory-service-functions); the schema page does not say it.'
    $columns = [ordered]@{ SubnetCount = ''; Unassigned = ''; Subnets = '' }
    if (-not [string]::IsNullOrWhiteSpace($ReadError)) {
        return New-AdfaC14Row -Area 'Sites' -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail ("The subnet objects could not be read: {0}. Whether any subnet has no site is not known. This is not a clean result." -f $ReadError.Trim())
    }
    $list = @($Subnets | Where-Object { $null -ne $_ })
    $columns.SubnetCount = [string]$list.Count
    if ($list.Count -eq 0) {
        return New-AdfaC14Row -Area 'Sites' -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail 'The read returned no subnet object. A forest with no subnet maps no client to a site, and an empty answer cannot be told from a read that saw nothing, so this is not a clean result.'
    }
    $unassigned = @()
    foreach ($s in $list) {
        $siteValue = Get-AdfaConfigValue -Entry $s -Name 'Site'
        if ($null -eq $siteValue -or [string]::IsNullOrWhiteSpace([string]$siteValue)) {
            $nameValue = [string](Get-AdfaConfigValue -Entry $s -Name 'Name')
            if ([string]::IsNullOrWhiteSpace($nameValue)) { $nameValue = '(unnamed subnet)' }
            $unassigned += $nameValue
        }
    }
    $columns.Unassigned = [string]$unassigned.Count
    $columns.Subnets = Get-AdfaC14NameList -Names $unassigned -Cap ([int]$Config['NameListCap'])
    if ($unassigned.Count -gt 0) {
        $status = [string]$Config['UnassignedStatus']
        return New-AdfaC14Row -Area 'Sites' -Item $item -Status $status -Evidence $evidence -Columns $columns `
            -Detail ("{0} of {1} subnet(s) have no site (siteObject not set). A client whose address falls only in such a subnet is mapped to no site, so it may use any domain controller, including a distant one. Graded {2}: {3}." -f $unassigned.Count, $list.Count, $status, [string]$Config['ThresholdSource'])
    }
    return New-AdfaC14Row -Area 'Sites' -Item $item -Status $script:Status.Pass -Evidence $evidence -Columns $columns `
        -Detail ("All {0} subnet(s) read carry a site." -f $list.Count)
}

function Get-AdfaNetlogonLogRaw {
    <#
    .SYNOPSIS
        File seam of C14: the last -MaxBytes bytes of one netlogon.log, opened for reading only.
        Never throws.
    .DESCRIPTION
        new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete),
        as Get-AdfaGptIniRaw opens GPT.INI: read access only, and Netlogon, which keeps writing the
        log, is never refused a write or a rename by this handle. Only the end of the file is read,
        so the read is bounded; when it starts inside the file, the partial first line is dropped.
        Decoded as ISO-8859-1, which maps every byte, because Microsoft does not publish the log's
        encoding. Runs as the account running the script: -Credential is not passed to file reads.
        A failure is classed by Get-AdfaGpoFileFailure: NotFound, AccessDenied, Unreachable, TimedOut
        or Error.
    .OUTPUTS
        [pscustomobject] Ok, Class, Text, Error, ErrorType, HResult, Path, Partial, BytesRead,
        FileLength.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Path,
        [ValidateRange(256, 20000000)][int]$MaxBytes = 4194304
    )
    $out = [pscustomobject]@{ Ok = $false; Class = ''; Text = ''; Error = ''; ErrorType = ''; HResult = 0; Path = $Path; Partial = $false; BytesRead = 0; FileLength = [int64]0 }
    $stream = $null
    try {
        $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
        $stream = [System.IO.FileStream]::new($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
        $length = [int64]$stream.Length
        $out.FileLength = $length
        $start = [int64]0
        if ($length -gt $MaxBytes) { $start = $length - $MaxBytes; $out.Partial = $true }
        [void]$stream.Seek($start, [System.IO.SeekOrigin]::Begin)
        $count = [int]($length - $start)
        $buffer = New-Object byte[] $count
        $total = 0
        while ($total -lt $count) {
            $n = $stream.Read($buffer, $total, $count - $total)
            if ($n -le 0) { break }
            $total += $n
        }
        $text = [System.Text.Encoding]::GetEncoding(28591).GetString($buffer, 0, $total)
        if ($out.Partial) {
            $nl = $text.IndexOf([char]10)
            if ($nl -ge 0) { $text = $text.Substring($nl + 1) } else { $text = '' }
        }
        $out.Text = $text
        $out.BytesRead = $total
        $out.Class = 'Read'
        $out.Ok = $true
    }
    catch {
        $f = Get-AdfaGpoFileFailure -Exception $_.Exception
        $out.Class = $f.Class; $out.Error = $f.Error; $out.ErrorType = $f.ErrorType; $out.HResult = $f.HResult
    }
    finally {
        if ($null -ne $stream) { $stream.Dispose() }
    }
    return $out
}

function ConvertFrom-AdfaNetlogonNoClientSite {
    <#
    .SYNOPSIS
        Pure: the clients a netlogon.log names as mapped to no site.
    .DESCRIPTION
        Microsoft (Netlogon event 5807, KB 2668820, read 2026-11-17): "search for lines that contain
        text 'NO_CLIENT_SITE:'. The first word after this string is the client name and the second
        word is the client IP address." Nothing else of the line is read: its time stamp format is
        not published. A marker line without a name and an address that parses as an IP address is
        counted as Unparsed, never guessed. Clients are listed once each, in first-seen order.
    .OUTPUTS
        [pscustomobject] Lines (marker lines), Unparsed, Entries (Name, Address).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Text = '',
        [string]$Marker = 'NO_CLIENT_SITE:'
    )
    $lines = 0
    $unparsed = 0
    $seen = @{}
    $entries = New-Object System.Collections.ArrayList
    foreach ($line in @(([string]$Text) -split "`r?`n")) {
        $at = $line.IndexOf($Marker, [System.StringComparison]::Ordinal)
        if ($at -lt 0) { continue }
        $lines++
        $tokens = @($line.Substring($at + $Marker.Length).Split([char[]]@([char]32, [char]9), [System.StringSplitOptions]::RemoveEmptyEntries))
        $ip = $null
        if ($tokens.Count -lt 2 -or -not [System.Net.IPAddress]::TryParse($tokens[1], [ref]$ip)) { $unparsed++; continue }
        $key = ("{0}|{1}" -f $tokens[0].ToLowerInvariant(), $tokens[1])
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        [void]$entries.Add([pscustomobject]@{ Name = [string]$tokens[0]; Address = [string]$tokens[1] })
    }
    return [pscustomobject]@{ Lines = $lines; Unparsed = $unparsed; Entries = @($entries.ToArray()) }
}

function Get-AdfaNoClientSiteVerdict {
    <#
    .SYNOPSIS
        Pure: "Clients without a site: <dc>" - the clients this DC's netlogon.log names as mapped to no
        site.
    .DESCRIPTION
        NoClientSiteStatus (Warning; Info by override) when the part of the log read names any; Info,
        never Pass, when it names none: Microsoft does not state how long the lines are kept, and the
        log rolls over to netlogon.bak, which is not read. Not Assessed, each with its own cause, when
        the DC was classified unreachable, SMB (445) did not answer, the read was refused (access
        denied), the share was unreachable, the log was not found, the read timed out or failed, or a
        marker line could not be parsed. Client names and addresses are in the Clients column only.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyString()][string]$HostName = '',
        [AllowEmptyString()][string]$Scope = '',
        [AllowNull()]$Raw,
        [bool]$PortOpen = $true,
        [AllowNull()][AllowEmptyString()][string]$ReachCause = '',
        [hashtable]$Config = $script:Config.SiteCoverage
    )
    $label = $HostName
    if ([string]::IsNullOrWhiteSpace($label)) { $label = '(unnamed)' }
    $item = ("Clients without a site: {0}" -f $label)
    $evidence = ("Netlogon event 5807 (Learn KB 2668820, read 2026-11-17): clients whose addresses map to no site are logged in %SystemRoot%\debug\netlogon.log on lines holding '{0}', the first word after it the client name and the second its address. Read over the ADMIN$ administrative share, read-only, the last {1} bytes only (LogTailBytes, a tool default); the rights needed are not published." -f [string]$Config['NoClientSiteMarker'], [int]$Config['LogTailBytes'])
    $notRun = 'netlogon.bak, where the log rolls over when full, is not read.'
    $columns = [ordered]@{ ClientCount = ''; Clients = ''; LogPath = ''; BytesRead = '' }
    $na = { param([string]$Why) New-AdfaC14Row -Area 'Sites' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -NotRun $notRun -Detail ("{0} Whether clients of this DC are mapped to no site is not known. This is not a clean result." -f $Why) }
    if ([string]::IsNullOrWhiteSpace($HostName)) { return (& $na 'The inventory holds a domain controller with no host name, so its netlogon.log was not read.') }
    if (-not [string]::IsNullOrWhiteSpace($ReachCause)) { return (& $na ("netlogon.log was not read: {0}." -f $ReachCause.Trim().TrimEnd('.'))) }
    if (-not $PortOpen) { return (& $na ("SMB ({0}) did not answer, so netlogon.log was not read." -f [int]$Config['SmbPort'])) }
    if ($null -eq $Raw) { return (& $na 'netlogon.log was not read.') }
    $columns.LogPath = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Path')
    if (-not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) {
        $class = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Class')
        $err = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Error')
        switch ($class) {
            'AccessDenied' { return (& $na 'Reading netlogon.log was refused (access denied): reading it over the ADMIN$ share needs administrative rights on the domain controller, and Microsoft does not publish which.') }
            'Unreachable' { return (& $na 'The ADMIN$ share of this domain controller was unreachable (network path not found), so netlogon.log was not read.') }
            'NotFound' { return (& $na 'netlogon.log was not found on the ADMIN$ share (debug\netlogon.log).') }
            'TimedOut' { return (& $na 'Reading netlogon.log timed out.') }
        }
        return (& $na ("Reading netlogon.log failed: {0}." -f $err.Trim().TrimEnd('.')))
    }
    $columns.BytesRead = [string](Get-AdfaConfigValue -Entry $Raw -Name 'BytesRead')
    $parsed = ConvertFrom-AdfaNetlogonNoClientSite -Text ([string](Get-AdfaConfigValue -Entry $Raw -Name 'Text')) -Marker ([string]$Config['NoClientSiteMarker'])
    $entries = @($parsed.Entries)
    $columns.ClientCount = [string]$entries.Count
    $columns.Clients = Get-AdfaC14NameList -Names @($entries | ForEach-Object { "{0} {1}" -f $_.Name, $_.Address }) -Cap ([int]$Config['NameListCap'])
    $scopeText = 'the whole log'
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'Partial')) { $scopeText = 'its last part' }
    $unparsedText = ''
    if ([int]$parsed.Unparsed -gt 0) { $unparsedText = (" {0} marker line(s) did not carry a name and an address and were not read." -f [int]$parsed.Unparsed) }
    if ($entries.Count -gt 0) {
        $status = [string]$Config['NoClientSiteStatus']
        return New-AdfaC14Row -Area 'Sites' -Scope $Scope -Item $item -Status $status -Evidence $evidence -Columns $columns -NotRun $notRun `
            -Detail ("{0} distinct client(s), on {1} line(s) of {2}, connected to this DC from an address that maps to no site: no subnet object covers it. Such clients may use any domain controller, including a distant one.{3} Graded {4}: {5}." -f $entries.Count, [int]$parsed.Lines, $scopeText, $unparsedText, $status, [string]$Config['ThresholdSource'])
    }
    if ([int]$parsed.Unparsed -gt 0) { return (& $na ("{0} line(s) of {1} carry the marker but not a name and an address, so they could not be read." -f [int]$parsed.Unparsed, $scopeText)) }
    return New-AdfaC14Row -Area 'Sites' -Scope $Scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns -NotRun $notRun `
        -Detail ("No line of {0} names a client mapped to no site. This is not proof that every client maps to a site, so it is not a clean result: Microsoft does not state how long the lines are kept or whether they are written without debug logging, and the log rolls over when full." -f $scopeText)
}

function Get-AdfaClientSiteRows {
    <#
    .SYNOPSIS
        Topology, SITE-001: one "Clients without a site: <dc>" row per DC of every scoped domain, and a
        population row for a scoped domain with no DC row.
    .DESCRIPTION
        A DC classified Unreachable in this run is not read. Otherwise SMB (445) is probed through the
        shared port cache, and netlogon.log is read through Get-AdfaNetlogonLogRaw from
        \\<dc>\ADMIN$\debug\netlogon.log. Read-only.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [hashtable]$Config = $script:Config.SiteCoverage,
        [int]$PortTimeoutMs = 1200,
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @()
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaC14Row -Area 'Sites' -Scope ([string]$gap.Domain) -Item ("Clients without a site (population): {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No netlogon.log of it was read.')
    }
    if ($targets.Count -eq 0) {
        $why = 'No domain controllers were enumerated'
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = ("Domain controller enumeration failed ({0})" -f $EnumerationError) }
        $rows += New-AdfaC14Row -Area 'Sites' -Item 'Clients without a site' -Status $script:Status.NotAssessed -Detail ("{0}, so no netlogon.log was read. This is not a clean result." -f $why)
        return @($rows)
    }
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $reachCause = ''
        $portOpen = $true
        $raw = $null
        if (-not [string]::IsNullOrWhiteSpace($dc)) {
            $reachCause = Get-AdfaDcReachCause -HostName $dc
            if ($reachCause -eq '') {
                $portOpen = [bool](Get-AdfaDcProbeGate -ComputerName $dc -Ports @([int]$Config['SmbPort']) -TimeoutMs $PortTimeoutMs).Open[[int]$Config['SmbPort']]
                if ($portOpen) { $raw = Get-AdfaNetlogonLogRaw -Path ([string]$Config['NetlogonLogPath'] -f $dc) -MaxBytes ([int]$Config['LogTailBytes']) }
            }
        }
        $rows += Get-AdfaNoClientSiteVerdict -HostName $dc -Scope ([string]$named.Scope) -Raw $raw -PortOpen $portOpen -ReachCause $reachCause -Config $Config
    }
    return @($rows)
}

# --- TIME-001 ------------------------------------------------------------------------------------

function Get-AdfaStripchartSample {
    <#
    .SYNOPSIS
        The w32tm reading of one DC's clock offset from the host running the assessment, in one
        bounded call: 'w32tm /stripchart /computer:<dc> /dataonly /samples:<n> /rdtsc'.
    .DESCRIPTION
        /stripchart "Displays a strip chart of the offset between this computer and another
        computer"; /samples stops it after that many samples (without it, it runs until stopped);
        Microsoft documents no state change for it (windows-time-service-tools-and-settings, read
        2026-11-17). The output is read by ConvertFrom-AdfaStripchartCsv. When no sample parses, the
        reason is named: access denied, every sample timed out, rows with no number, no output, or no
        /rdtsc header.
    .OUTPUTS
        [pscustomobject] Queried, Offsets, Delays, Error.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [ValidateRange(1, 100)][int]$Samples = 3,
        [int]$TimeoutSeconds = 60
    )
    $sc = Invoke-ExternalCommand -FilePath 'w32tm.exe' -Arguments ("/stripchart /computer:{0} /dataonly /samples:{1} /rdtsc" -f $ComputerName, $Samples) `
        -TimeoutSeconds $TimeoutSeconds -Retries 1 -RetryDelaySeconds 1
    $scOut = ''
    $sop = $sc.PSObject.Properties['StdOut']
    if ($null -ne $sop -and $null -ne $sop.Value) { $scOut = [string]$sop.Value }
    $parsed = ConvertFrom-AdfaStripchartCsv -Text $scOut
    $err = ''
    if (@($parsed.Offsets).Count -eq 0) {
        if ($scOut -match '(?i)access is denied|0x80070005') { $err = 'w32tm reported access denied' }
        elseif ($scOut -match '(?i)timed out|0x800705B4') { $err = 'every NTP sample timed out (UDP 123 blocked, or the Windows Time service is not answering)' }
        elseif ($parsed.RowsSeen -gt 0) { $err = ("{0} sample row(s) were returned but none carried a numeric NtpOffset" -f $parsed.RowsSeen) }
        elseif ([string]::IsNullOrWhiteSpace($scOut)) { $err = 'w32tm produced no output' }
        else { $err = 'the /rdtsc CSV header was not found in the output' }
    }
    return [pscustomobject]@{ Queried = $true; Offsets = @($parsed.Offsets); Delays = @($parsed.Delays); Error = $err }
}

function Get-AdfaC14Median {
    <#
    .SYNOPSIS
        Pure: the median of a list of numbers, or $null for none.
    #>
    [CmdletBinding()]
    param([AllowNull()][AllowEmptyCollection()][double[]]$Values = @())
    $sorted = @($Values | Sort-Object)
    if ($sorted.Count -eq 0) { return $null }
    $mid = [int][math]::Floor($sorted.Count / 2)
    if ($sorted.Count % 2 -eq 1) { return [double]$sorted[$mid] }
    return ([double]$sorted[$mid - 1] + [double]$sorted[$mid]) / 2
}

function Get-AdfaPdcClockOffsetVerdict {
    <#
    .SYNOPSIS
        Pure: "Clock offset vs forest root PDC: <dc>" - one DC's clock against the forest root PDC
        emulator, the reference Microsoft names for the forest's time.
    .DESCRIPTION
        Both clocks are read from the host running the assessment with w32tm /stripchart. The
        offset of the DC against the PDC is each DC sample minus the median PDC sample, and the worst
        of those is graded on its size: at or beyond FailSeconds (300, the Kerberos default maximum
        tolerance) Fail, at or beyond WarnSeconds (60, a tool default, not a Microsoft value) Warning,
        else Pass. The sign is not graded. The error bound - half the DC's largest round trip plus
        half the PDC's median round trip - is TOOL REASONING, not a Microsoft method, and is reported,
        not graded. The forest root PDC itself is Info. Not Assessed, never Pass, when the reference is
        not identified or not measured, the DC was classified unreachable, or the DC was not measured.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainController,
        [AllowEmptyString()][string]$Scope = '',
        [AllowNull()][AllowEmptyString()][string]$ReferencePdc = '',
        [bool]$IsReference = $false,
        [AllowNull()]$Sample = $null,
        [AllowNull()]$ReferenceSample = $null,
        [AllowNull()][AllowEmptyString()][string]$ReachCause = '',
        [double]$WarnSeconds = 60,
        [double]$FailSeconds = 300,
        [AllowNull()][AllowEmptyString()][string]$ThresholdSource = ''
    )
    $item = ("Clock offset vs forest root PDC: {0}" -f $DomainController)
    $source = $ThresholdSource
    if ([string]::IsNullOrWhiteSpace($source)) { $source = [string]$script:Config.ClockSkew['ThresholdSource'] }
    $evidence = ("Reference: the forest root PDC emulator, 'the authoritative time server for the organization' (KB 884776); Kerberos needs only the relative difference between KDC and target (replication error 5 article); Kerberos SkewTime default 5 minutes (read 2026-11-17). Offset = DC sample minus the median reference sample, both from w32tm /stripchart run on the host running the assessment; error bound = half the DC's largest round trip plus half the reference's median round trip. Both are tool reasoning, not a Microsoft method. Grades: {0}." -f $source)
    $columns = [ordered]@{ Reference = [string]$ReferencePdc; OffsetSeconds = ''; ErrorBoundSeconds = ''; Samples = '' }
    $na = { param([string]$Why) New-AdfaC14Row -Area 'TimeHierarchy' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -Detail ("{0} Nothing can be concluded about this DC's time against the forest root PDC emulator - an unmeasured offset is not a small one." -f $Why) }
    if (-not [string]::IsNullOrWhiteSpace($ReachCause)) { return (& $na ("The offset was not measured: {0}." -f $ReachCause.Trim().TrimEnd('.'))) }
    if ([string]::IsNullOrWhiteSpace($ReferencePdc)) { return (& $na 'The forest root PDC emulator was not identified, so there is no reference clock.') }
    if ($IsReference) {
        return New-AdfaC14Row -Area 'TimeHierarchy' -Scope $Scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
            -Detail 'This domain controller is the forest root PDC emulator, the reference the other DCs are measured against. Its own time source is graded by the rows above.'
    }
    $numbers = { param($List) @(@($List) | Where-Object { $_ -is [double] -or $_ -is [int] -or $_ -is [decimal] -or $_ -is [single] } | ForEach-Object { [double]$_ }) }
    $refOffsets = @()
    $refDelays = @()
    $refError = ''
    if ($null -ne $ReferenceSample) {
        if ([bool](Get-AdfaConfigValue -Entry $ReferenceSample -Name 'Queried')) { $refOffsets = @(& $numbers (Get-AdfaConfigValue -Entry $ReferenceSample -Name 'Offsets')) }
        $refDelays = @(& $numbers (Get-AdfaConfigValue -Entry $ReferenceSample -Name 'Delays'))
        $refError = [string](Get-AdfaConfigValue -Entry $ReferenceSample -Name 'Error')
    }
    if ($refOffsets.Count -eq 0) {
        $why = 'it was not measured'
        if (-not [string]::IsNullOrWhiteSpace($refError)) { $why = $refError.Trim().TrimEnd('.') }
        return (& $na ("The reference, the forest root PDC emulator, could not be measured: {0}." -f $why))
    }
    $dcOffsets = @()
    $dcDelays = @()
    $dcError = ''
    if ($null -ne $Sample) {
        if ([bool](Get-AdfaConfigValue -Entry $Sample -Name 'Queried')) { $dcOffsets = @(& $numbers (Get-AdfaConfigValue -Entry $Sample -Name 'Offsets')) }
        $dcDelays = @(& $numbers (Get-AdfaConfigValue -Entry $Sample -Name 'Delays'))
        $dcError = [string](Get-AdfaConfigValue -Entry $Sample -Name 'Error')
    }
    if ($dcOffsets.Count -eq 0) {
        $why = 'no sample was taken'
        if (-not [string]::IsNullOrWhiteSpace($dcError)) { $why = $dcError.Trim().TrimEnd('.') }
        return (& $na ("This DC's offset could not be measured: {0}." -f $why))
    }
    $refMedian = [double](Get-AdfaC14Median -Values $refOffsets)
    $worst = 0.0
    foreach ($v in $dcOffsets) {
        $rel = $v - $refMedian
        if ([math]::Abs($rel) -gt [math]::Abs($worst)) { $worst = $rel }
    }
    $abs = [math]::Abs($worst)
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $boundText = 'no round trip was read, so no error bound is given'
    if ($dcDelays.Count -gt 0 -and $refDelays.Count -gt 0) {
        $bound = ((@($dcDelays | Measure-Object -Maximum).Maximum) + [double](Get-AdfaC14Median -Values $refDelays)) / 2
        $columns.ErrorBoundSeconds = $bound.ToString('0.###', $inv)
        $boundText = ("error bound about {0} s" -f $bound.ToString('0.###', $inv))
    }
    $columns.OffsetSeconds = $worst.ToString('0.###', $inv)
    $columns.Samples = ("{0} DC, {1} reference" -f $dcOffsets.Count, $refOffsets.Count)
    $thresholds = ("The {0} s warning level is a tool default, not a Microsoft value; {1} s is the Kerberos default maximum tolerance Microsoft documents." -f $WarnSeconds.ToString('0.###', $inv), $FailSeconds.ToString('0.###', $inv))
    if ($abs -ge $FailSeconds) {
        return New-AdfaC14Row -Area 'TimeHierarchy' -Scope $Scope -Item $item -Status $script:Status.Fail -Evidence $evidence -Columns $columns `
            -Detail ("Offset against the forest root PDC emulator is {0} s ({1}), at or beyond the Kerberos maximum tolerance: authentication between this DC and the others fails at this difference. {2}" -f $worst.ToString('0.###', $inv), $boundText, $thresholds)
    }
    if ($abs -ge $WarnSeconds) {
        return New-AdfaC14Row -Area 'TimeHierarchy' -Scope $Scope -Item $item -Status $script:Status.Warning -Evidence $evidence -Columns $columns `
            -Detail ("Offset against the forest root PDC emulator is {0} s ({1}): inside the Kerberos maximum tolerance but past the warning level. {2}" -f $worst.ToString('0.###', $inv), $boundText, $thresholds)
    }
    return New-AdfaC14Row -Area 'TimeHierarchy' -Scope $Scope -Item $item -Status $script:Status.Pass -Evidence $evidence -Columns $columns `
        -Detail ("Offset against the forest root PDC emulator is {0} s ({1}), below the warning level. {2}" -f $worst.ToString('0.###', $inv), $boundText, $thresholds)
}

# --- STALE-001/002 -------------------------------------------------------------------------------

function Get-AdfaStaleLdapFilter {
    <#
    .SYNOPSIS
        Pure: the LDAP filter of one stale read.
    .DESCRIPTION
        Enabled only: (!(userAccountControl:1.2.840.113556.1.4.803:=2)) - ACCOUNTDISABLE, bit 2,
        through the bitwise AND matching rule. User and Computer: lastLogonTimestamp at or before the
        cutoff (FILETIME), or none and whenCreated at or before it (generalized time) - a never-used
        account is counted once it is older than the cutoff. Users: (objectCategory=person)
        (objectClass=user). Computers: (objectCategory=computer) without the group managed and
        standalone managed service account classes. Password: enabled users whose pwdLastSet is at
        or before the cutoff (0 included; the verdict tells it apart). EnabledUser and EnabledComputer:
        the declared population of the User and Computer reads - the same filter without the time
        term (the cutoff is not used). DisabledUser and DisabledComputer (PORT-PLAN C15, INV-009): the
        User and Computer filters with ACCOUNTDISABLE set instead of clear; AllDisabledUser and
        AllDisabledComputer, their declared population, without the time term.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][ValidateSet('User', 'Computer', 'Password', 'EnabledUser', 'EnabledComputer', 'DisabledUser', 'DisabledComputer', 'AllDisabledUser', 'AllDisabledComputer')][string]$Kind,
        [Parameter(Mandatory)][datetime]$CutoffUtc
    )
    $cut = $CutoffUtc
    if ($cut.Kind -eq [System.DateTimeKind]::Local) { $cut = $cut.ToUniversalTime() }
    $cut = [datetime]::SpecifyKind($cut, [System.DateTimeKind]::Utc)
    $ft = $cut.ToFileTimeUtc()
    $gt = $cut.ToString('yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture) + '.0Z'
    $enabled = '(!(userAccountControl:1.2.840.113556.1.4.803:=2))'
    $disabled = '(userAccountControl:1.2.840.113556.1.4.803:=2)'
    $activity = ("(|(lastLogonTimestamp<={0})(&(!(lastLogonTimestamp=*))(whenCreated<={1})))" -f $ft, $gt)
    switch ($Kind) {
        'User' { return ("(&(objectCategory=person)(objectClass=user){0}{1})" -f $enabled, $activity) }
        'Computer' { return ("(&(objectCategory=computer)(!(objectClass=msDS-GroupManagedServiceAccount))(!(objectClass=msDS-ManagedServiceAccount)){0}{1})" -f $enabled, $activity) }
        'EnabledUser' { return ("(&(objectCategory=person)(objectClass=user){0})" -f $enabled) }
        'EnabledComputer' { return ("(&(objectCategory=computer)(!(objectClass=msDS-GroupManagedServiceAccount))(!(objectClass=msDS-ManagedServiceAccount)){0})" -f $enabled) }
        'DisabledUser' { return ("(&(objectCategory=person)(objectClass=user){0}{1})" -f $disabled, $activity) }
        'DisabledComputer' { return ("(&(objectCategory=computer)(!(objectClass=msDS-GroupManagedServiceAccount))(!(objectClass=msDS-ManagedServiceAccount)){0}{1})" -f $disabled, $activity) }
        'AllDisabledUser' { return ("(&(objectCategory=person)(objectClass=user){0})" -f $disabled) }
        'AllDisabledComputer' { return ("(&(objectCategory=computer)(!(objectClass=msDS-GroupManagedServiceAccount))(!(objectClass=msDS-ManagedServiceAccount)){0})" -f $disabled) }
    }
    return ("(&(objectCategory=person)(objectClass=user){0}(pwdLastSet<={1}))" -f $enabled, $ft)
}

function Get-AdfaStaleRaw {
    <#
    .SYNOPSIS
        The directory seam of STALE-001/002: one search of one domain, listed properties only,
        capped. Never throws.
    .DESCRIPTION
        Get-ADUser (User, Password) or Get-ADComputer (Computer) with -Server <domain>, -LDAPFilter
        from Get-AdfaStaleLdapFilter, -Properties naming sAMAccountName, lastLogonTimestamp,
        whenCreated and userAccountControl (pwdLastSet in place of the two logon attributes for
        Password) - never every property - and -ResultSetSize one above MaxObjects, so a domain with
        more than that is Capped, not silently cut. Each object is reduced to a small record as it
        arrives.
    .OUTPUTS
        [pscustomobject] Ok, Error, ErrorType, Records (Name, HasLastLogon, LastLogonUtc,
        WhenCreatedUtc, PwdLastSetRaw, UserAccountControl), Capped, Filter, Properties.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [Parameter(Mandatory)][ValidateSet('User', 'Computer', 'Password', 'DisabledUser', 'DisabledComputer')][string]$Kind,
        [Parameter(Mandatory)][datetime]$CutoffUtc,
        [ValidateRange(1, 1000000)][int]$MaxObjects = 100000,
        [hashtable]$AdParams = @{}
    )
    $props = @('sAMAccountName', 'lastLogonTimestamp', 'whenCreated', 'userAccountControl')
    if ($Kind -eq 'Password') { $props = @('sAMAccountName', 'pwdLastSet', 'userAccountControl') }
    $filter = Get-AdfaStaleLdapFilter -Kind $Kind -CutoffUtc $CutoffUtc
    $out = [pscustomobject]@{ Ok = $false; Error = ''; ErrorType = ''; Records = @(); Capped = $false; Filter = $filter; Properties = @($props) }
    $toRecord = {
        param($o)
        $name = [string](Get-AdfaConfigValue -Entry $o -Name 'sAMAccountName')
        if ([string]::IsNullOrWhiteSpace($name)) { $name = [string](Get-AdfaConfigValue -Entry $o -Name 'Name') }
        $llt = Get-AdfaConfigValue -Entry $o -Name 'lastLogonTimestamp'
        $hasLast = ($null -ne $llt -and -not [string]::IsNullOrWhiteSpace([string]$llt))
        $lastUtc = $null
        if ($hasLast) { $lastUtc = ConvertTo-AdfaFileTimeUtc -Value $llt }
        $created = Get-AdfaConfigValue -Entry $o -Name 'whenCreated'
        $createdUtc = $null
        if ($created -is [datetime]) { $createdUtc = $created.ToUniversalTime() }
        $pwdValue = Get-AdfaConfigValue -Entry $o -Name 'pwdLastSet'
        $pwdRaw = $null
        if ($null -ne $pwdValue) {
            $parsed = [int64]0
            if ([int64]::TryParse(([string]$pwdValue).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsed)) { $pwdRaw = $parsed }
        }
        # userAccountControl, raw: the password verdict needs UF_DONT_EXPIRE_PASSWD to read pwdLastSet 0.
        $uacValue = Get-AdfaConfigValue -Entry $o -Name 'userAccountControl'
        $uacRaw = $null
        if ($null -ne $uacValue) {
            $parsedUac = [int64]0
            if ([int64]::TryParse(([string]$uacValue).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsedUac)) { $uacRaw = $parsedUac }
        }
        [pscustomobject]@{ Name = $name; HasLastLogon = $hasLast; LastLogonUtc = $lastUtc; WhenCreatedUtc = $createdUtc; PwdLastSetRaw = $pwdRaw; UserAccountControl = $uacRaw }
    }
    try {
        $query = @{} + $AdParams
        $query.Server = $DomainName
        $query.LDAPFilter = $filter
        $query.Properties = @($props)
        $query.ResultSetSize = $MaxObjects + 1
        $query.ErrorAction = 'Stop'
        $records = New-Object System.Collections.ArrayList
        if ($Kind -eq 'Computer' -or $Kind -eq 'DisabledComputer') { Get-ADComputer @query | ForEach-Object { if ($null -ne $_) { [void]$records.Add((& $toRecord $_)) } } }
        else { Get-ADUser @query | ForEach-Object { if ($null -ne $_) { [void]$records.Add((& $toRecord $_)) } } }
        $out.Records = @($records.ToArray())
        $out.Capped = ($records.Count -gt $MaxObjects)
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Get-AdfaStalePopulationRaw {
    <#
    .SYNOPSIS
        The declared population of STALE-001/002: how many enabled users (or computers) one domain
        returns to the account running the scan. Never throws.
    .DESCRIPTION
        Get-ADUser (User) or Get-ADComputer (Computer) with -Server <domain>, -LDAPFilter from
        Get-AdfaStaleLdapFilter -Kind EnabledUser / EnabledComputer (the stale filter without its time
        term), the cmdlet's default property set (no -Properties, so never every property) and
        -ResultSetSize one above MaxObjects. Only a count is kept. It is what lets a stale read that
        returned nothing be told from a read that saw nothing: a count of 0 is never a clean result.
    .OUTPUTS
        [pscustomobject] Ok, Count, Capped, Error, ErrorType, Filter.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [Parameter(Mandatory)][ValidateSet('User', 'Computer', 'DisabledUser', 'DisabledComputer')][string]$Kind,
        [ValidateRange(1, 1000000)][int]$MaxObjects = 100000,
        [hashtable]$AdParams = @{}
    )
    # The enabled accounts for the C14 stale reads; the disabled ones (PORT-PLAN C15, INV-009) for the
    # stale disabled reads.
    $filterKind = ("Enabled{0}" -f $Kind)
    if ($Kind -like 'Disabled*') { $filterKind = ("All{0}" -f $Kind) }
    $filter = Get-AdfaStaleLdapFilter -Kind $filterKind -CutoffUtc ([datetime]::UtcNow)
    $out = [pscustomobject]@{ Ok = $false; Count = 0; Capped = $false; Error = ''; ErrorType = ''; Filter = $filter }
    try {
        $query = @{} + $AdParams
        $query.Server = $DomainName
        $query.LDAPFilter = $filter
        $query.ResultSetSize = $MaxObjects + 1
        $query.ErrorAction = 'Stop'
        $count = 0
        if ($Kind -like '*Computer') { Get-ADComputer @query | ForEach-Object { if ($null -ne $_) { $count++ } } }
        else { Get-ADUser @query | ForEach-Object { if ($null -ne $_) { $count++ } } }
        $out.Count = $count
        $out.Capped = ($count -gt $MaxObjects)
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Get-AdfaC14PopulationText {
    <#
    .SYNOPSIS
        Pure: how a stale row states its declared population, and why a row with nothing found cannot
        pass when that population is not known. Ok is true only for a read that saw at least one
        enabled account.
    .OUTPUTS
        [pscustomobject] Ok, Text, Why.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Population, [Parameter(Mandatory)][string]$Noun, [int]$MaxObjects = 100000)
    if ($null -eq $Population) {
        return [pscustomobject]@{ Ok = $false; Text = ("The enabled {0} accounts of this domain were not counted." -f $Noun)
            Why = ("The enabled {0} accounts of this domain were not counted, so a read that returned nothing cannot be told from a read that saw nothing." -f $Noun) }
    }
    if (-not [bool](Get-AdfaConfigValue -Entry $Population -Name 'Ok')) {
        $err = [string](Get-AdfaConfigValue -Entry $Population -Name 'Error')
        $class = Get-AdfaDirectoryReadErrorClass -Message $err -TypeName ([string](Get-AdfaConfigValue -Entry $Population -Name 'ErrorType'))
        $t = ("Counting the enabled {0} accounts of this domain failed ({1}): {2}." -f $Noun, (Get-AdfaReadClassPhrase -Class $class), $err.Trim().TrimEnd('.'))
        return [pscustomobject]@{ Ok = $false; Text = $t; Why = ("{0} A read that returned nothing cannot be told from a read that saw nothing." -f $t) }
    }
    $n = [int](Get-AdfaConfigValue -Entry $Population -Name 'Count')
    if ($n -le 0) {
        return [pscustomobject]@{ Ok = $false; Text = ("The read saw no enabled {0} account in this domain." -f $Noun)
            Why = ("The read saw no enabled {0} account at all in this domain (the declared population is empty): the rights of the account running the scan may hide them, so nothing returned is not proof that none is stale." -f $Noun) }
    }
    $countText = [string]$n
    if ([bool](Get-AdfaConfigValue -Entry $Population -Name 'Capped')) { $countText = ("more than {0}" -f $MaxObjects) }
    return [pscustomobject]@{ Ok = $true; Text = ("The read saw {0} enabled {1} account(s) in this domain." -f $countText, $Noun); Why = '' }
}

function Get-AdfaLogonSyncIntervalRaw {
    <#
    .SYNOPSIS
        The domain's msDS-LogonTimeSyncInterval, from its head. Never throws.
    .DESCRIPTION
        Get-ADDomain for the DN (with the caller's AD parameters, as the Laps read does), then
        Get-ADObject -Server <domain> -Identity <DN> -Properties msDS-LogonTimeSyncInterval. Present is
        false when the attribute is not set; the verdict then states the default.
    .OUTPUTS
        [pscustomobject] Ok, Present, Value, Error.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$DomainName, [hashtable]$AdParams = @{})
    $out = [pscustomobject]@{ Ok = $false; Present = $false; Value = $null; Error = '' }
    try {
        $domainArgs = @{} + $AdParams
        $domainArgs.Identity = $DomainName
        $domainArgs.ErrorAction = 'Stop'
        $dn = [string](Get-ADDomain @domainArgs).DistinguishedName
        if ([string]::IsNullOrWhiteSpace($dn)) { throw 'Get-ADDomain returned no DistinguishedName.' }
        $headArgs = @{} + $AdParams
        $headArgs.Server = $DomainName
        $headArgs.Identity = $dn
        $headArgs.Properties = @('msDS-LogonTimeSyncInterval')
        $headArgs.ErrorAction = 'Stop'
        $head = Get-ADObject @headArgs
        $value = Get-AdfaConfigValue -Entry $head -Name 'msDS-LogonTimeSyncInterval'
        if ($null -ne $value -and -not [string]::IsNullOrWhiteSpace([string]$value)) { $out.Present = $true; $out.Value = $value }
        $out.Ok = $true
    }
    catch { $out.Error = [string]$_.Exception.Message }
    return $out
}

function Get-AdfaC14SyncInterval {
    <#
    .SYNOPSIS
        Pure: the logon-sync interval a stale row states, where it came from, and whether updates are
        disabled.
    .OUTPUTS
        [pscustomobject] Days, Disabled, Text.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Interval, [hashtable]$Config = $script:Config.Stale)
    $default = [int]$Config['SyncIntervalDefaultDays']
    if ($null -eq $Interval -or -not [bool](Get-AdfaConfigValue -Entry $Interval -Name 'Ok')) {
        $err = ''
        if ($null -ne $Interval) { $err = [string](Get-AdfaConfigValue -Entry $Interval -Name 'Error') }
        return [pscustomobject]@{ Days = $default; Disabled = $false; Text = ("msDS-LogonTimeSyncInterval could not be read ({0}); {1} days, its default, was assumed" -f $err.Trim().TrimEnd('.'), $default) }
    }
    if (-not [bool](Get-AdfaConfigValue -Entry $Interval -Name 'Present')) {
        return [pscustomobject]@{ Days = $default; Disabled = $false; Text = ("msDS-LogonTimeSyncInterval is not set, which means its default of {0} days" -f $default) }
    }
    $days = 0
    if (-not [int]::TryParse(([string](Get-AdfaConfigValue -Entry $Interval -Name 'Value')).Trim(), [ref]$days)) {
        return [pscustomobject]@{ Days = $default; Disabled = $false; Text = ("msDS-LogonTimeSyncInterval holds a value that is not a number; {0} days, its default, was assumed" -f $default) }
    }
    if ($days -eq 0) { return [pscustomobject]@{ Days = 0; Disabled = $true; Text = 'msDS-LogonTimeSyncInterval is 0' } }
    return [pscustomobject]@{ Days = $days; Disabled = $false; Text = ("msDS-LogonTimeSyncInterval is {0} days" -f $days) }
}

function Get-AdfaStaleCountVerdict {
    <#
    .SYNOPSIS
        Pure: "Inactive enabled users" / "Inactive enabled computers" for one domain.
    .DESCRIPTION
        Counts the enabled accounts whose lastLogonTimestamp is at or before Now minus StaleDays, or
        that have none and were created at or before it (counted separately as never logged on).
        StaleStatus (Warning; Info by override) when any; Pass only when a complete read found none
        AND the declared population (Population, the enabled accounts of the kind the same account
        could see) is at least one. Every row states the logon-sync interval and that the real last
        logon can be up to that much more recent. Not Assessed, never Pass or zero, when the read
        failed (unreachable, access denied, timed out and other errors told apart), the cap was
        reached, updates are disabled (interval 0), StaleDays is not longer than the interval, a
        returned object carried neither time, or nothing was found and the population was not
        counted, could not be counted or was empty. Names are in the Accounts column only.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [Parameter(Mandatory)][ValidateSet('User', 'Computer')][string]$Kind,
        [AllowNull()]$Raw,
        [AllowNull()]$Interval,
        [Parameter(Mandatory)][int]$StaleDays,
        [Parameter(Mandatory)][datetime]$Now,
        [AllowNull()]$Population = $null,
        [hashtable]$Config = $script:Config.Stale
    )
    $noun = 'user'
    $item = 'Inactive enabled users'
    if ($Kind -eq 'Computer') { $noun = 'computer'; $item = 'Inactive enabled computers' }
    $sync = Get-AdfaC14SyncInterval -Interval $Interval -Config $Config
    $random = [int]$Config['SyncRandomisationDays']
    # Microsoft: the value is updated when it is older than the interval minus a random part (up to 5
    # days by default), "9 to 14 days" under the default. The random part shortens the wait, so the
    # value trails the real last logon by at most the interval itself, never by more.
    $caveat = ("lastLogonTimestamp is rewritten at a logon only when the value held is older than the logon-sync interval ({0}) minus a random part of up to {1} days, so the real last logon can be up to the interval more recent than the value read, never more (Microsoft: 'updated only when the current value in Active Directory is 9 to 14 days older than the time of logon' under the default)." -f $sync.Text, $random)
    $evidence = ("LDAP filter: enabled (ACCOUNTDISABLE clear), lastLogonTimestamp at or before the cutoff, or none and whenCreated at or before it; -Server {0}, listed properties only, at most {1} objects (MaxObjects). Declared population: the enabled accounts of the same kind, counted with the same filter without its time term. StaleDays {2} is the -StaleDays parameter, a tool default, not a Microsoft value (Defender for Identity uses 90 days for its own rule). Sources read 2026-11-17: a-lastlogontimestamp, KB 2679653, the AskDS archive on Learn." -f $DomainName, [int]$Config['MaxObjects'], $StaleDays)
    $columns = [ordered]@{ Count = ''; NeverLoggedOn = ''; Population = ''; StaleDays = [string]$StaleDays; SyncIntervalDays = $sync.Days; Accounts = '' }
    $na = { param([string]$Why) New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -Detail ("{0} The count of stale enabled {1} accounts is not known - not zero, and not a clean result." -f $Why, $noun) }
    if ($null -eq $Raw) { return (& $na 'The accounts were not read.') }
    if (-not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) {
        $err = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Error')
        $class = Get-AdfaDirectoryReadErrorClass -Message $err -TypeName ([string](Get-AdfaConfigValue -Entry $Raw -Name 'ErrorType'))
        return (& $na ("Reading the {0} accounts of this domain failed ({1}): {2}." -f $noun, (Get-AdfaReadClassPhrase -Class $class), $err.Trim().TrimEnd('.')))
    }
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'Capped')) { return (& $na ("The read reached its cap of {0} objects (MaxObjects, a tool default), so the count is incomplete." -f [int]$Config['MaxObjects'])) }
    if ($sync.Disabled) { return (& $na ("{0}: lastLogonTimestamp updates are disabled, so the attribute cannot show activity." -f $sync.Text)) }
    if ($StaleDays -le $sync.Days) { return (& $na ("StaleDays {0} is not longer than the logon-sync interval ({1} days), the most lastLogonTimestamp can trail the real last logon, so an account in use can look stale. Re-run with a larger -StaleDays." -f $StaleDays, $sync.Days)) }
    $nowUtc = $Now
    if ($nowUtc.Kind -eq [System.DateTimeKind]::Local) { $nowUtc = $nowUtc.ToUniversalTime() }
    $cutoff = $nowUtc.AddDays(-1 * $StaleDays)
    $stale = @()
    $never = 0
    $unclassified = 0
    foreach ($r in @(Get-AdfaConfigValue -Entry $Raw -Name 'Records' | Where-Object { $null -ne $_ })) {
        $last = Get-AdfaConfigValue -Entry $r -Name 'LastLogonUtc'
        $created = Get-AdfaConfigValue -Entry $r -Name 'WhenCreatedUtc'
        $name = [string](Get-AdfaConfigValue -Entry $r -Name 'Name')
        if ([bool](Get-AdfaConfigValue -Entry $r -Name 'HasLastLogon')) {
            if ($last -isnot [datetime]) { $unclassified++; continue }
            if ($last -le $cutoff) { $stale += $name }
            continue
        }
        if ($created -isnot [datetime]) { $unclassified++; continue }
        if ($created -le $cutoff) { $stale += $name; $never++ }
    }
    if ($unclassified -gt 0) { return (& $na ("{0} returned object(s) carried no readable lastLogonTimestamp and no readable whenCreated, so they could not be classified." -f $unclassified)) }
    $pop = Get-AdfaC14PopulationText -Population $Population -Noun $noun -MaxObjects ([int]$Config['MaxObjects'])
    if ($null -ne $Population -and [bool](Get-AdfaConfigValue -Entry $Population -Name 'Ok')) {
        $columns.Population = [string](Get-AdfaConfigValue -Entry $Population -Name 'Count')
        if ([bool](Get-AdfaConfigValue -Entry $Population -Name 'Capped')) { $columns.Population = ("more than {0}" -f [int]$Config['MaxObjects']) }
    }
    $columns.Count = [string]$stale.Count
    $columns.NeverLoggedOn = [string]$never
    $columns.Accounts = Get-AdfaC14NameList -Names $stale -Cap ([int]$Config['NameListCap'])
    if ($stale.Count -gt 0) {
        $status = [string]$Config['StaleStatus']
        return New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $status -Evidence $evidence -Columns $columns `
            -Detail ("{0} enabled {1} account(s) with no logon recorded for more than {2} days; {3} of them never logged on (no lastLogonTimestamp, created more than {2} days ago). {4} {5} Graded {6}: {7}." -f $stale.Count, $noun, $StaleDays, $never, $pop.Text, $caveat, $status, [string]$Config['ThresholdSource'])
    }
    # Nothing found passes only against a declared population the read could see.
    if (-not $pop.Ok) { return (& $na $pop.Why) }
    return New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $script:Status.Pass -Evidence $evidence -Columns $columns `
        -Detail ("0 enabled {0} accounts with no logon recorded for more than {1} days, in a complete read. {2} {3}" -f $noun, $StaleDays, $pop.Text, $caveat)
}

function Get-AdfaPasswordAgeVerdict {
    <#
    .SYNOPSIS
        Pure: "Enabled users with an old password" for one domain.
    .DESCRIPTION
        Enabled users whose pwdLastSet is at or before Now minus PasswordAgeDays (365, a tool default,
        not a Microsoft value) are PasswordAgeStatus (Warning; Info by override). pwdLastSet 0 is read
        as Microsoft documents it - the user must set the password at the next logon - only where the
        record's userAccountControl is readable and UF_DONT_EXPIRE_PASSWD (0x10000) is clear; those are
        counted on their own, not graded. pwdLastSet 0 with UF_DONT_EXPIRE_PASSWD set is an account
        whose password age is not known: it is counted and named in its own column, and the row
        cannot pass while any exists. Not Assessed when the read failed, was capped, a returned object
        carried no pwdLastSet (or pwdLastSet 0 with no readable userAccountControl), or nothing was
        found and the declared population (Population, the enabled users) was not counted or empty.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowNull()]$Raw,
        [Parameter(Mandatory)][datetime]$Now,
        [AllowNull()]$Population = $null,
        [hashtable]$Config = $script:Config.Stale
    )
    $item = 'Enabled users with an old password'
    $days = [int]$Config['PasswordAgeDays']
    $evidence = ("LDAP filter: enabled users (ACCOUNTDISABLE clear) with pwdLastSet at or before the cutoff; -Server {0}, listed properties only. Declared population: the enabled users, counted with the same filter without its pwdLastSet term. PasswordAgeDays {1} is a tool default, not a Microsoft value. pwdLastSet 0: 'If this value is set to 0 and the User-Account-Control attribute does not contain the UF_DONT_EXPIRE_PASSWD flag, then the user must set the password at the next logon' (Learn a-pwdlastset, read 2026-11-17)." -f $DomainName, $days)
    $columns = [ordered]@{ Count = ''; MustChangeAtNextLogon = ''; AgeNotKnown = ''; Population = ''; PasswordAgeDays = [string]$days; Accounts = ''; AgeNotKnownAccounts = '' }
    $na = { param([string]$Why) New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -Detail ("{0} The count of enabled users with an old password is not known - not zero, and not a clean result." -f $Why) }
    if ($null -eq $Raw) { return (& $na 'The accounts were not read.') }
    if (-not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) {
        $err = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Error')
        $class = Get-AdfaDirectoryReadErrorClass -Message $err -TypeName ([string](Get-AdfaConfigValue -Entry $Raw -Name 'ErrorType'))
        return (& $na ("Reading the user accounts of this domain failed ({0}): {1}." -f (Get-AdfaReadClassPhrase -Class $class), $err.Trim().TrimEnd('.')))
    }
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'Capped')) { return (& $na ("The read reached its cap of {0} objects (MaxObjects, a tool default), so the count is incomplete." -f [int]$Config['MaxObjects'])) }
    $nowUtc = $Now
    if ($nowUtc.Kind -eq [System.DateTimeKind]::Local) { $nowUtc = $nowUtc.ToUniversalTime() }
    $cutoff = $nowUtc.AddDays(-1 * $days)
    $old = @()
    $mustChange = 0
    $ageUnknown = @()
    $unclassified = 0
    $noUac = 0
    $dontExpire = [int64]0x10000
    foreach ($r in @(Get-AdfaConfigValue -Entry $Raw -Name 'Records' | Where-Object { $null -ne $_ })) {
        $rawValue = Get-AdfaConfigValue -Entry $r -Name 'PwdLastSetRaw'
        if ($null -eq $rawValue) { $unclassified++; continue }
        if ([int64]$rawValue -eq 0) {
            # Learn a-pwdlastset: 0 means "must set the password at the next logon" only where
            # UF_DONT_EXPIRE_PASSWD is clear; with it set, the age of the password is not known.
            $uac = Get-AdfaConfigValue -Entry $r -Name 'UserAccountControl'
            if ($null -eq $uac) { $noUac++; continue }
            if (([int64]$uac -band $dontExpire) -ne 0) { $ageUnknown += [string](Get-AdfaConfigValue -Entry $r -Name 'Name'); continue }
            $mustChange++
            continue
        }
        $set = ConvertTo-AdfaFileTimeUtc -Value ([int64]$rawValue)
        if ($null -eq $set) { $unclassified++; continue }
        if ($set -le $cutoff) { $old += [string](Get-AdfaConfigValue -Entry $r -Name 'Name') }
    }
    if ($unclassified -gt 0) { return (& $na ("{0} returned object(s) carried no readable pwdLastSet, so they could not be classified." -f $unclassified)) }
    if ($noUac -gt 0) { return (& $na ("{0} returned object(s) carried pwdLastSet 0 and no readable userAccountControl, so whether they must change their password at the next logon or hold a password of unknown age (UF_DONT_EXPIRE_PASSWD) could not be told." -f $noUac)) }
    $pop = Get-AdfaC14PopulationText -Population $Population -Noun 'user' -MaxObjects ([int]$Config['MaxObjects'])
    if ($null -ne $Population -and [bool](Get-AdfaConfigValue -Entry $Population -Name 'Ok')) {
        $columns.Population = [string](Get-AdfaConfigValue -Entry $Population -Name 'Count')
        if ([bool](Get-AdfaConfigValue -Entry $Population -Name 'Capped')) { $columns.Population = ("more than {0}" -f [int]$Config['MaxObjects']) }
    }
    $columns.Count = [string]$old.Count
    $columns.MustChangeAtNextLogon = [string]$mustChange
    $columns.AgeNotKnown = [string]$ageUnknown.Count
    $columns.Accounts = Get-AdfaC14NameList -Names $old -Cap ([int]$Config['NameListCap'])
    $columns.AgeNotKnownAccounts = Get-AdfaC14NameList -Names $ageUnknown -Cap ([int]$Config['NameListCap'])
    $mustText = ("{0} more must change their password at the next logon (pwdLastSet 0, UF_DONT_EXPIRE_PASSWD clear); they are counted, not graded." -f $mustChange)
    $unknownText = ''
    if ($ageUnknown.Count -gt 0) { $unknownText = (" {0} more carry pwdLastSet 0 with UF_DONT_EXPIRE_PASSWD set, so the age of their password is not known (AgeNotKnown column)." -f $ageUnknown.Count) }
    if ($old.Count -gt 0) {
        $status = [string]$Config['PasswordAgeStatus']
        return New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $status -Evidence $evidence -Columns $columns `
            -Detail ("{0} enabled user account(s) whose password was last set more than {1} days ago. {2}{3} {4} Graded {5}: {6}." -f $old.Count, $days, $mustText, $unknownText, $pop.Text, $status, [string]$Config['ThresholdSource'])
    }
    if ($ageUnknown.Count -gt 0) { return (& $na ("No enabled user account read has a password last set more than {0} days ago, but {1} carry pwdLastSet 0 with UF_DONT_EXPIRE_PASSWD set, so the age of their password was not measured." -f $days, $ageUnknown.Count)) }
    # Nothing found passes only against a declared population the read could see.
    if (-not $pop.Ok) { return (& $na $pop.Why) }
    return New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $script:Status.Pass -Evidence $evidence -Columns $columns `
        -Detail ("0 enabled user accounts whose password was last set more than {0} days ago, in a complete read. {1} {2}" -f $days, $mustText, $pop.Text)
}

# --- SYSVOL-004 ----------------------------------------------------------------------------------

function Get-AdfaDirectoryObjectState {
    <#
    .SYNOPSIS
        Whether one directory object exists, read from the server named: Present, Absent or Unread.
        Never throws.
    .DESCRIPTION
        Get-ADObject -Identity <DN> -Server <domain>. Absent only when the exception's type is the
        module's "identity not found" (NotFoundTypePattern; Microsoft does not publish the exceptions,
        PORT-PLAN C17). Anything else - refused, unreachable, timed out - is Unread, with its class, so
        a refused read is never taken for an object that does not exist.
    .OUTPUTS
        [pscustomobject] State, Object, Error, ErrorType, Class.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Identity,
        [Parameter(Mandatory)][string]$Server,
        [AllowNull()][AllowEmptyCollection()][string[]]$Properties = @(),
        [hashtable]$AdParams = @{},
        [hashtable]$Config = $script:Config.SysvolEngine
    )
    $out = [pscustomobject]@{ State = 'Unread'; Object = $null; Error = ''; ErrorType = ''; Class = '' }
    try {
        $query = @{} + $AdParams
        $query.Server = $Server
        $query.Identity = $Identity
        if (@($Properties).Count -gt 0) { $query.Properties = @($Properties) }
        $query.ErrorAction = 'Stop'
        $obj = Get-ADObject @query
        if ($null -eq $obj) { $out.Error = 'the read returned nothing'; $out.Class = 'Error'; return $out }
        $out.Object = $obj
        $out.State = 'Present'
    }
    catch {
        $type = [string]$_.Exception.GetType().FullName
        $out.ErrorType = $type
        $out.Error = ([string]$_.Exception.Message).Trim()
        if ($type -match [string]$Config['NotFoundTypePattern']) { $out.State = 'Absent'; $out.Class = 'NotFound' }
        else { $out.Class = Get-AdfaDirectoryReadErrorClass -Message $out.Error -TypeName $type }
    }
    return $out
}

function Get-AdfaSysvolEngineRaw {
    <#
    .SYNOPSIS
        The directory seam of SYSVOL-004: per DC of one domain, whether its DFSR SYSVOL subscription
        and its NTFRS subscriber exist, and the domain's msDFSR-Flags. Never throws.
    .DESCRIPTION
        Get-ADDomainController -Filter * -Server <domain> for the DCs (HostName, IsReadOnly,
        ComputerObjectDN); Get-ADDomain for the domain's DN; then, each with -Server <domain> so a child
        domain is asked of its own DC, CN=DFSR-GlobalSettings,CN=System,<domain DN> (msDFSR-Flags) and,
        per DC, CN=SYSVOL Subscription,CN=Domain System Volume,CN=DFSR-LocalSettings,<computer DN> and
        CN=Domain System Volume (SYSVOL share),CN=NTFRS Subscriptions,<computer DN>. Reads only.
    .OUTPUTS
        [pscustomobject] Ok, Error, ErrorType, DomainDn, GlobalState, GlobalFlags, GlobalError, Dcs
        (HostName, IsReadOnly, ComputerDn, Dfsr, DfsrError, Frs, FrsError).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [hashtable]$AdParams = @{},
        [hashtable]$Config = $script:Config.SysvolEngine
    )
    $out = [pscustomobject]@{ Ok = $false; Error = ''; ErrorType = ''; DomainDn = ''; GlobalState = 'Unread'; GlobalFlags = $null; GlobalError = ''; Dcs = @() }
    $dcs = @()
    try {
        $dcArgs = @{} + $AdParams
        $dcArgs.Server = $DomainName
        $dcArgs.Filter = '*'
        $dcArgs.ErrorAction = 'Stop'
        $dcs = @(Get-ADDomainController @dcArgs | Where-Object { $null -ne $_ })
        $out.Ok = $true
    }
    catch {
        $out.Error = ([string]$_.Exception.Message).Trim()
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        return $out
    }
    try {
        $domainArgs = @{} + $AdParams
        $domainArgs.Identity = $DomainName
        $domainArgs.ErrorAction = 'Stop'
        $out.DomainDn = [string](Get-ADDomain @domainArgs).DistinguishedName
    }
    catch { $out.GlobalError = ([string]$_.Exception.Message).Trim() }
    if (-not [string]::IsNullOrWhiteSpace($out.DomainDn)) {
        $g = Get-AdfaDirectoryObjectState -Identity ([string]$Config['GlobalSettingsDn'] -f $out.DomainDn) -Server $DomainName -Properties @('msDFSR-Flags') -AdParams $AdParams -Config $Config
        $out.GlobalState = $g.State
        $out.GlobalError = $g.Error
        if ($g.State -eq 'Present') {
            $flags = Get-AdfaConfigValue -Entry $g.Object -Name 'msDFSR-Flags'
            $n = 0
            if ($null -ne $flags -and [int]::TryParse(([string]$flags).Trim(), [ref]$n)) { $out.GlobalFlags = $n }
        }
    }
    elseif ([string]::IsNullOrWhiteSpace($out.GlobalError)) { $out.GlobalError = 'Get-ADDomain returned no DistinguishedName' }
    $records = New-Object System.Collections.ArrayList
    foreach ($dc in $dcs) {
        $hostName = [string](Get-AdfaConfigValue -Entry $dc -Name 'HostName')
        $ro = Get-AdfaConfigValue -Entry $dc -Name 'IsReadOnly'
        $isRo = $null
        if ($ro -is [bool]) { $isRo = [bool]$ro }
        $computerDn = [string](Get-AdfaConfigValue -Entry $dc -Name 'ComputerObjectDN')
        $record = [pscustomobject]@{ HostName = $hostName; IsReadOnly = $isRo; ComputerDn = $computerDn; Dfsr = 'Unread'; DfsrError = ''; Frs = 'Unread'; FrsError = '' }
        if ([string]::IsNullOrWhiteSpace($computerDn)) {
            $record.DfsrError = 'the DC was returned with no computer object DN, so its objects could not be named'
            $record.FrsError = $record.DfsrError
        }
        else {
            $d = Get-AdfaDirectoryObjectState -Identity ([string]$Config['DfsrSubscriptionDn'] -f $computerDn) -Server $DomainName -AdParams $AdParams -Config $Config
            $f = Get-AdfaDirectoryObjectState -Identity ([string]$Config['FrsSubscriberDn'] -f $computerDn) -Server $DomainName -AdParams $AdParams -Config $Config
            $record.Dfsr = $d.State
            $record.Frs = $f.State
            if ($d.State -eq 'Unread') { $record.DfsrError = ("{0}: {1}" -f (Get-AdfaReadClassPhrase -Class $d.Class), $d.Error) }
            if ($f.State -eq 'Unread') { $record.FrsError = ("{0}: {1}" -f (Get-AdfaReadClassPhrase -Class $f.Class), $f.Error) }
        }
        [void]$records.Add($record)
    }
    $out.Dcs = @($records.ToArray())
    return $out
}

function Resolve-AdfaSysvolEngineDc {
    <#
    .SYNOPSIS
        Pure: the SYSVOL engine of one DC from its two objects - DFSR, FRS, Transitional (both: a
        migration has started and not finished) or Unknown (neither, or either not read).
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()][AllowEmptyString()][string]$Dfsr = 'Unread',
        [AllowNull()][AllowEmptyString()][string]$Frs = 'Unread'
    )
    if ($Dfsr -eq 'Unread' -or $Frs -eq 'Unread') { return 'Unknown' }
    if ($Dfsr -eq 'Present' -and $Frs -eq 'Absent') { return 'DFSR' }
    if ($Dfsr -eq 'Absent' -and $Frs -eq 'Present') { return 'FRS' }
    if ($Dfsr -eq 'Present' -and $Frs -eq 'Present') { return 'Transitional' }
    return 'Unknown'
}

function Get-AdfaSysvolEngineVerdict {
    <#
    .SYNOPSIS
        Pure: "SYSVOL engine: <dc>" (Info) per DC and "SYSVOL replication engine: <domain>" for the
        domain.
    .DESCRIPTION
        The domain row grades the writable DCs (a DC whose read-only flag is unknown counts as
        writable): any that still uses FRS or is between FRS and DFSR is FrsStatus (Warning; Fail by
        override) - measured, so it stands even when another DC was not read; else any whose engine
        is not known is Not Assessed; else Pass when every writable DC uses DFSR. No writable DC, or
        a DC list that could not be read, is Not Assessed. msDFSR-Flags is quoted as corroboration
        only; its absence is never read as FRS.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowNull()]$Raw,
        [hashtable]$Config = $script:Config.SysvolEngine
    )
    $rows = @()
    $item = ("SYSVOL replication engine: {0}" -f $DomainName)
    $evidence = 'Per DC, from its own domain: CN=SYSVOL Subscription under its DFSR-LocalSettings (DFSR, KB 2218556) and the NTFRS subscriber "Domain System Volume (SYSVOL share)" under its NTFRS Subscriptions (FRS, missing SYSVOL and Netlogon shares article). FRS is deprecated since Windows Server 2008 R2; "Starting in Windows Server 2019, promoting new domain controllers requires the DFS Replication (DFSR)" (KB 4493934). Read 2026-11-17.'
    $columns = [ordered]@{ Writable = ''; Dfsr = ''; Frs = ''; Transitional = ''; Unknown = ''; GlobalFlags = '' }
    if ($null -eq $Raw -or -not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) {
        $err = ''
        $type = ''
        if ($null -ne $Raw) { $err = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Error'); $type = [string](Get-AdfaConfigValue -Entry $Raw -Name 'ErrorType') }
        $class = Get-AdfaDirectoryReadErrorClass -Message $err -TypeName $type
        $rows += New-AdfaC14Row -Area 'SYSVOL' -Scope $DomainName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail ("The domain controllers of this domain could not be enumerated ({0}): {1}. The SYSVOL replication engine is not known - not a clean result." -f (Get-AdfaReadClassPhrase -Class $class), $err.Trim().TrimEnd('.'))
        return @($rows)
    }
    $names = $Config['GlobalStateNames']
    $globalState = [string](Get-AdfaConfigValue -Entry $Raw -Name 'GlobalState')
    $flags = Get-AdfaConfigValue -Entry $Raw -Name 'GlobalFlags'
    $flagText = ''
    if ($globalState -eq 'Present' -and $null -ne $flags) {
        $flagName = 'not a value this tool knows'
        if ($names.ContainsKey([string]$flags)) { $flagName = [string]$names[[string]$flags] }
        $flagText = ("Corroboration: msDFSR-Flags on CN=DFSR-GlobalSettings is {0} ({1}; mapping from Microsoft's SYSVOL migration reference, provisional)." -f [int]$flags, $flagName)
        $columns.GlobalFlags = [string]$flags
    }
    elseif ($globalState -eq 'Present') { $flagText = 'Corroboration: CN=DFSR-GlobalSettings exists and carries no msDFSR-Flags.' }
    elseif ($globalState -eq 'Absent') { $flagText = 'Corroboration: CN=DFSR-GlobalSettings was not found; Microsoft does not say what that means, so it is not read as FRS.' }
    else { $flagText = ("Corroboration: msDFSR-Flags could not be read ({0})." -f ([string](Get-AdfaConfigValue -Entry $Raw -Name 'GlobalError')).Trim().TrimEnd('.')) }
    $dcs = @(Get-AdfaConfigValue -Entry $Raw -Name 'Dcs' | Where-Object { $null -ne $_ })
    $writable = @()
    foreach ($dc in $dcs) {
        $hostName = [string](Get-AdfaConfigValue -Entry $dc -Name 'HostName')
        if ([string]::IsNullOrWhiteSpace($hostName)) { $hostName = '(unnamed)' }
        $dfsr = [string](Get-AdfaConfigValue -Entry $dc -Name 'Dfsr')
        $frs = [string](Get-AdfaConfigValue -Entry $dc -Name 'Frs')
        $engine = Resolve-AdfaSysvolEngineDc -Dfsr $dfsr -Frs $frs
        $ro = Get-AdfaConfigValue -Entry $dc -Name 'IsReadOnly'
        $roText = 'unknown'
        if ($ro -is [bool]) { $roText = [string]$ro }
        $dcColumns = [ordered]@{ Engine = $engine; DfsrSubscription = $dfsr; FrsSubscriber = $frs; ReadOnly = $roText }
        $reason = ''
        switch ($engine) {
            'DFSR' { $reason = 'The DFSR SYSVOL subscription exists and the NTFRS subscriber does not: SYSVOL is replicated by DFS Replication.' }
            'FRS' { $reason = 'The NTFRS subscriber exists and the DFSR SYSVOL subscription does not: SYSVOL is replicated by FRS.' }
            'Transitional' { $reason = 'Both the DFSR SYSVOL subscription and the NTFRS subscriber exist: a migration from FRS to DFSR has started and not finished.' }
            default {
                $parts = @()
                $dfsrError = [string](Get-AdfaConfigValue -Entry $dc -Name 'DfsrError')
                $frsError = [string](Get-AdfaConfigValue -Entry $dc -Name 'FrsError')
                if ($dfsr -eq 'Unread') { $parts += ("the DFSR subscription could not be read ({0})" -f $dfsrError.Trim().TrimEnd('.')) }
                if ($frs -eq 'Unread' -and $frsError -ne $dfsrError) { $parts += ("the NTFRS subscriber could not be read ({0})" -f $frsError.Trim().TrimEnd('.')) }
                elseif ($frs -eq 'Unread') { $parts += 'nor the NTFRS subscriber' }
                if ($parts.Count -eq 0) { $parts += 'neither object was found' }
                $reason = ("The engine is not known: {0}. This is not a clean result." -f ($parts -join '; '))
            }
        }
        $dcStatus = $script:Status.Info
        if ($engine -eq 'Unknown') { $dcStatus = $script:Status.NotAssessed }
        $rows += New-AdfaC14Row -Area 'SYSVOL' -Scope $DomainName -Item ("SYSVOL engine: {0}" -f $hostName) -Status $dcStatus -Evidence $evidence -Columns $dcColumns -Detail $reason
        if ($ro -ne $true) { $writable += [pscustomobject]@{ Engine = $engine; Unread = ($dfsr -eq 'Unread' -or $frs -eq 'Unread') } }
    }
    $columns.Writable = [string]$writable.Count
    $countOf = { param([string]$E) @($writable | Where-Object { $_.Engine -eq $E }).Count }
    $columns.Dfsr = [string](& $countOf 'DFSR')
    $columns.Frs = [string](& $countOf 'FRS')
    $columns.Transitional = [string](& $countOf 'Transitional')
    $columns.Unknown = [string](& $countOf 'Unknown')
    if ($writable.Count -eq 0) {
        $rows += New-AdfaC14Row -Area 'SYSVOL' -Scope $DomainName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail ("There is no writable domain controller to grade ({0} DC(s) enumerated), so the SYSVOL replication engine of this domain is not known - not a clean result. {1}" -f $dcs.Count, $flagText)
        return @($rows)
    }
    $frsLike = (& $countOf 'FRS') + (& $countOf 'Transitional')
    $unknown = @($writable | Where-Object { $_.Engine -eq 'Unknown' })
    if ($frsLike -gt 0) {
        $status = [string]$Config['FrsStatus']
        $unknownText = ''
        if ($unknown.Count -gt 0) { $unknownText = (" The engine of {0} other writable DC(s) is not known." -f $unknown.Count) }
        $rows += New-AdfaC14Row -Area 'SYSVOL' -Scope $DomainName -Item $item -Status $status -Evidence $evidence -Columns $columns `
            -Detail ("{0} of {1} writable domain controller(s) still replicate SYSVOL with FRS or are between FRS and DFSR ({2} FRS, {3} migrating).{4} FRS is deprecated, it was removed in Windows Server 2019, and a Windows Server 2019 or later DC cannot be promoted into a domain whose SYSVOL still uses FRS. {5} Graded {6}: {7}." -f `
                $frsLike, $writable.Count, (& $countOf 'FRS'), (& $countOf 'Transitional'), $unknownText, $flagText, $status, [string]$Config['ThresholdSource'])
        return @($rows)
    }
    if ($unknown.Count -gt 0) {
        $unread = @($unknown | Where-Object { $_.Unread }).Count
        $neither = $unknown.Count - $unread
        $parts = @()
        if ($unread -gt 0) { $parts += ("{0} could not be read" -f $unread) }
        if ($neither -gt 0) { $parts += ("{0} had neither object" -f $neither) }
        $rows += New-AdfaC14Row -Area 'SYSVOL' -Scope $DomainName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail ("The engine of {0} of {1} writable domain controller(s) is not known: {2}. The others use DFSR. The domain's SYSVOL replication engine is not known - not a clean result. {3}" -f $unknown.Count, $writable.Count, ($parts -join ', '), $flagText)
        return @($rows)
    }
    $rows += New-AdfaC14Row -Area 'SYSVOL' -Scope $DomainName -Item $item -Status $script:Status.Pass -Evidence $evidence -Columns $columns `
        -Detail ("All {0} writable domain controller(s) replicate SYSVOL with DFS Replication: each has the DFSR SYSVOL subscription and no NTFRS subscriber. {1}" -f $writable.Count, $flagText)
    return @($rows)
}

# ===========================================================================
# region Inventory depth (PORT-PLAN C15)
# ===========================================================================
# Catalogue INV-001, INV-006..INV-012, INV-015, built into the existing sections Forest, Trusts,
# Identity, StaleObjects, Gpo, DsEvents and TimeHierarchy. Every row is Info when collected and Not
# Assessed with its cause when not: the catalogue grades none of them. Every read here is a query -
# directory reads with listed properties and a cap, Get-WinEvent with a time window and -MaxEvents,
# StdRegProv GetStringValue and GetDWORDValue. The sources and read dates are next to the config table.

function Get-AdfaInventoryDirectoryRaw {
    <#
    .SYNOPSIS
        The directory seam of the C15 inventory: one Get-ADObject read, by identity or by search,
        listed properties only, capped. Never throws.
    .DESCRIPTION
        -Identity reads one object; otherwise -LDAPFilter searches under -SearchBase (the domain's
        default naming context when none is given) with -SearchScope, -ResultSetSize one above
        MaxObjects, so a read with more than that is Capped, not silently cut. -Server is always
        sent, so each domain is read from itself. -Properties names the attributes kept on each
        record; -CountProperties names attributes of which only the number of values is kept
        (<name>Count), so a member list is never held. A property name holding a wildcard is
        refused before anything is sent. A read that throws part-way is not Ok: a count is never
        taken from a read that did not finish.
    .OUTPUTS
        [pscustomobject] Ok, Error, ErrorType, NotFound, Records (DistinguishedName, Name, the listed
        properties, <name>Count), Count, Capped, Filter, Identity.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Server,
        [AllowEmptyString()][string]$Identity = '',
        [AllowEmptyString()][string]$SearchBase = '',
        [AllowEmptyString()][string]$SearchScope = '',
        [AllowEmptyString()][string]$LDAPFilter = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$Properties = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$CountProperties = @(),
        [ValidateRange(1, 1000000)][int]$MaxObjects = 100000,
        [hashtable]$AdParams = @{}
    )
    $out = [pscustomobject]@{ Ok = $false; Error = ''; ErrorType = ''; NotFound = $false; Records = @(); Count = 0; Capped = $false; Filter = $LDAPFilter; Identity = $Identity }
    $keep = @(@($Properties) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { [string]$_ })
    $counted = @(@($CountProperties) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { [string]$_ })
    $asked = @($keep + $counted)
    foreach ($p in $asked) {
        if ($p -match '[*?]') { $out.Error = ("The property list holds '{0}', a wildcard; every property is never requested." -f $p); return $out }
    }
    $toRecord = {
        param($o)
        $record = [ordered]@{ DistinguishedName = [string](Get-AdfaConfigValue -Entry $o -Name 'DistinguishedName'); Name = [string](Get-AdfaConfigValue -Entry $o -Name 'Name') }
        foreach ($p in $keep) {
            $prop = $o.PSObject.Properties[$p]
            $v = $null
            if ($null -ne $prop) { $v = $prop.Value }
            if ($null -ne $v -and $v -isnot [string] -and $v -is [System.Collections.IEnumerable]) { $v = @($v | ForEach-Object { $_ }) }
            $record[$p] = $v
        }
        foreach ($p in $counted) {
            $prop = $o.PSObject.Properties[$p]
            $n = 0
            if ($null -ne $prop -and $null -ne $prop.Value) {
                if ($prop.Value -isnot [string] -and $prop.Value -is [System.Collections.IEnumerable]) { $n = @($prop.Value).Count } else { $n = 1 }
            }
            $record[("{0}Count" -f $p)] = $n
        }
        [pscustomobject]$record
    }
    try {
        $query = @{} + $AdParams
        $query.Server = $Server
        if ($asked.Count -gt 0) { $query.Properties = @($asked) }
        $query.ErrorAction = 'Stop'
        $records = New-Object System.Collections.ArrayList
        if ($Identity -ne '') {
            $query.Identity = $Identity
        }
        else {
            $query.LDAPFilter = $LDAPFilter
            if ($SearchBase -ne '') { $query.SearchBase = $SearchBase }
            if ($SearchScope -ne '') { $query.SearchScope = $SearchScope }
            $query.ResultSetSize = $MaxObjects + 1
        }
        Get-ADObject @query | ForEach-Object { if ($null -ne $_) { [void]$records.Add((& $toRecord $_)) } }
        $out.Records = @($records.ToArray())
        $out.Count = $records.Count
        $out.Capped = ($Identity -eq '' -and $records.Count -gt $MaxObjects)
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
        if ($out.ErrorType -match '(?i)ADIdentityNotFoundException$') { $out.NotFound = $true }
    }
    return $out
}

function Get-AdfaInventoryReadCause {
    <#
    .SYNOPSIS
        Pure: why a C15 directory read cannot be used - '' when it can. Unreachable, access denied,
        timed out, not found and a reached cap are each worded apart.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [AllowNull()]$Raw, [Parameter(Mandatory)][string]$What, [int]$MaxObjects = 100000,
        # Where MaxObjects came from, in the row's words. The C15 callers keep the default; the C4b
        # reads pass Get-AdfaCapSource's phrase (PORT-PLAN C4b4 for the C15 callers).
        [string]$CapSource = 'MaxObjects, a tool default'
    )
    if ($null -eq $Raw) {
        $lead = $What
        if ($lead.Length -gt 0) { $lead = $lead.Substring(0, 1).ToUpperInvariant() + $lead.Substring(1) }
        return ("{0} was not read." -f $lead)
    }
    if (-not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) {
        $err = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'Error')).Trim().TrimEnd('.')
        $class = Get-AdfaDirectoryReadErrorClass -Message $err -TypeName ([string](Get-AdfaConfigValue -Entry $Raw -Name 'ErrorType'))
        if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'NotFound')) { $class = 'NotFound' }
        return ("Reading {0} failed ({1}): {2}." -f $What, (Get-AdfaReadClassPhrase -Class $class), $err)
    }
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'Capped')) { return ("Reading {0} reached its cap of {1} objects ({2}), so the list is incomplete." -f $What, $MaxObjects, $CapSource) }
    return ''
}

function Get-AdfaInventoryDomainDn {
    <#
    .SYNOPSIS
        The distinguished name of one domain, from Get-ADDomain. Never throws.
    .OUTPUTS
        [pscustomobject] Ok, Dn, Error, ErrorType.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([Parameter(Mandatory)][string]$DomainName, [hashtable]$AdParams = @{})
    $out = [pscustomobject]@{ Ok = $false; Dn = ''; Error = ''; ErrorType = '' }
    try {
        $domainArgs = @{} + $AdParams
        $domainArgs.Identity = $DomainName
        $domainArgs.ErrorAction = 'Stop'
        $dn = [string](Get-AdfaConfigValue -Entry (Get-ADDomain @domainArgs) -Name 'DistinguishedName')
        if ([string]::IsNullOrWhiteSpace($dn)) { throw 'Get-ADDomain returned no DistinguishedName.' }
        $out.Dn = $dn
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function Get-AdfaRootDseRaw {
    <#
    .SYNOPSIS
        The rootDSE of the DC this run talks to: its dnsHostName (the runner DC) and the
        configuration naming context. Never throws.
    .OUTPUTS
        [pscustomobject] Ok, DnsHostName, ConfigurationNamingContext, Error, ErrorType.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([hashtable]$AdParams = @{})
    $out = [pscustomobject]@{ Ok = $false; DnsHostName = ''; ConfigurationNamingContext = ''; Error = ''; ErrorType = '' }
    try {
        $rootArgs = @{} + $AdParams
        $rootArgs.ErrorAction = 'Stop'
        $root = Get-ADRootDSE @rootArgs
        if ($null -eq $root) { throw 'Get-ADRootDSE returned nothing.' }
        $out.DnsHostName = [string](Get-AdfaConfigValue -Entry $root -Name 'dnsHostName')
        $out.ConfigurationNamingContext = [string](Get-AdfaConfigValue -Entry $root -Name 'configurationNamingContext')
        $out.Ok = $true
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $out.ErrorType = [string]$_.Exception.GetType().FullName
    }
    return $out
}

function New-AdfaInventoryFailedRead {
    <#
    .SYNOPSIS
        Pure: a read result that failed before it was sent, carrying the cause, in the shape the
        directory seam returns.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowEmptyString()][string]$ErrorText = '', [AllowEmptyString()][string]$ErrorType = '')
    return [pscustomobject]@{ Ok = $false; Error = $ErrorText; ErrorType = $ErrorType; NotFound = $false; Records = @(); Count = 0; Capped = $false; Filter = ''; Identity = '' }
}

# --- INV-001 / INV-007 -------------------------------------------------------------------------

function Get-AdfaLevelRow {
    <#
    .SYNOPSIS
        Pure: "Forest functional level: <forest>" or "Domain functional level: <domain>" from a read
        of msDS-Behavior-Version.
    .DESCRIPTION
        Info with the value and its MS-ADTS name. Not Assessed when the read failed, returned no
        object, did not return the attribute (MS-ADTS says an absent value is equivalent to 0, but a
        read that cannot see it returns nothing the same way, so the level is not asserted), returned
        something that is not a whole number, or a number with no published name (8, 9 and anything
        above 10; the raw value is kept).
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][ValidateSet('Forest', 'Domain')][string]$Kind,
        [AllowEmptyString()][string]$Scope = '',
        [AllowNull()]$Raw,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $item = ("{0} functional level: {1}" -f $Kind, $Scope)
    $where = 'msDS-Behavior-Version on the domain head'
    if ($Kind -eq 'Forest') { $where = 'msDS-Behavior-Version on CN=Partitions,CN=Configuration' }
    $evidence = ("{0}; names from MS-ADTS 6.1.4.3 and 6.1.4.4 (Learn, read 2026-11-17). Inventory only (catalogue INV-001): not graded." -f $where)
    $columns = [ordered]@{ Level = ''; LevelName = ''; Source = $where }
    $noun = $Kind.ToLowerInvariant()
    $na = { param([string]$Why) New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -Detail ("{0} The {1} functional level is not known." -f $Why, $noun) }
    $cause = Get-AdfaInventoryReadCause -Raw $Raw -What ("the {0} level object" -f $noun) -MaxObjects ([int]$Config['MaxObjects'])
    if ($cause -ne '') { return (& $na $cause) }
    $records = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Records') | Where-Object { $null -ne $_ })
    if ($records.Count -eq 0) { return (& $na 'The read returned no object.') }
    $value = Get-AdfaConfigValue -Entry $records[0] -Name 'msDS-Behavior-Version'
    if ($null -eq $value -or [string]::IsNullOrWhiteSpace([string]$value)) {
        return (& $na 'msDS-Behavior-Version was not returned. MS-ADTS says an absent value is equivalent to 0, but a read that cannot see the attribute returns nothing the same way, so the level is not asserted.')
    }
    $n = ConvertTo-AdfaInventoryInteger -Value $value
    if ($null -eq $n) {
        return (& $na 'msDS-Behavior-Version holds a value that is not a whole number.')
    }
    $columns.Level = [string]$n
    $labels = $Config['BehaviorVersionLabels']
    if ($null -eq $labels -or -not $labels.ContainsKey([string]$n)) {
        return (& $na ("msDS-Behavior-Version is {0}, which has no name published by Microsoft (MS-ADTS defines 0 to 7 and 10)." -f $n))
    }
    $columns.LevelName = [string]$labels[[string]$n]
    return New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
        -Detail ("msDS-Behavior-Version read; the value and its MS-ADTS name are in the Level and LevelName columns. Inventory only, not graded.")
}

function Get-AdfaFsmoHolderName {
    <#
    .SYNOPSIS
        Pure: the server an fSMORoleOwner value names. The value is the DN of the holder's NTDS
        Settings object, so the server is the next RDN. A value naming a deleted object (DEL:) is
        documented as invalid and is not read as a server.
    .OUTPUTS
        [pscustomobject] Valid, Server, Reason.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()][AllowEmptyString()][string]$Value)
    $out = [pscustomobject]@{ Valid = $false; Server = ''; Reason = '' }
    if ([string]::IsNullOrWhiteSpace($Value)) { $out.Reason = 'fSMORoleOwner holds no value'; return $out }
    if ($Value -match '(?i)DEL:') { $out.Reason = 'fSMORoleOwner names a deleted NTDS Settings object (DEL:), which Microsoft documents as an invalid value'; return $out }
    if ($Value -match '^(?i)CN=NTDS Settings,CN=((?:[^,\\]|\\.)+),') {
        $out.Server = [string]$Matches[1]
        $out.Valid = $true
        return $out
    }
    $out.Reason = 'fSMORoleOwner is not the distinguished name of an NTDS Settings object'
    return $out
}

function Get-AdfaFsmoRow {
    <#
    .SYNOPSIS
        Pure: "FSMO role holder: <Role> <scope>" from a read of fSMORoleOwner on the role object.
        The holder is in the Holder column, never in Detail.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Role,
        [AllowEmptyString()][string]$Scope = '',
        [AllowNull()]$Raw,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $item = ("FSMO role holder: {0} {1}" -f $Role, $Scope)
    $evidence = 'fSMORoleOwner on the role object, the DN of the holder''s NTDS Settings object (Learn fsmo-transfer-seizure-process, read 2026-11-17). Inventory only (catalogue INV-001): not graded.'
    $columns = [ordered]@{ Role = $Role; Holder = ''; HolderDn = '' }
    $na = { param([string]$Why) New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -Detail ("{0} The role holder is not known." -f $Why) }
    $cause = Get-AdfaInventoryReadCause -Raw $Raw -What 'the role object' -MaxObjects ([int]$Config['MaxObjects'])
    if ($cause -ne '') { return (& $na $cause) }
    $records = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Records') | Where-Object { $null -ne $_ })
    if ($records.Count -eq 0) { return (& $na 'The read returned no object.') }
    $value = [string](Get-AdfaConfigValue -Entry $records[0] -Name 'fSMORoleOwner')
    $columns.HolderDn = $value
    if ([string]::IsNullOrWhiteSpace($value)) { return (& $na 'fSMORoleOwner was not returned.') }
    $holder = Get-AdfaFsmoHolderName -Value $value
    if (-not $holder.Valid) { return (& $na ("{0}." -f $holder.Reason)) }
    $columns.Holder = $holder.Server
    return New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
        -Detail 'fSMORoleOwner read; the holder is the server named in the Holder column. Inventory only, not graded.'
}

function Get-AdfaSuffixListRow {
    <#
    .SYNOPSIS
        Pure: one row listing a multi-valued suffix attribute read from one object. Shared by the
        UPN suffix and allowed DNS suffix rows.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Item,
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$Attribute,
        [Parameter(Mandatory)][string]$Noun,
        [Parameter(Mandatory)][string]$What,
        [Parameter(Mandatory)][string]$Evidence,
        [AllowNull()]$Raw,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $columns = [ordered]@{ Count = ''; Suffixes = '' }
    $na = { param([string]$Why) New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $Item -Status $script:Status.NotAssessed -Evidence $Evidence -Columns $columns -Detail ("{0} The {1} are not known - not zero." -f $Why, $Noun) }
    $cause = Get-AdfaInventoryReadCause -Raw $Raw -What $What -MaxObjects ([int]$Config['MaxObjects'])
    if ($cause -ne '') { return (& $na $cause) }
    $records = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Records') | Where-Object { $null -ne $_ })
    if ($records.Count -eq 0) { return (& $na 'The read returned no object.') }
    $prop = $records[0].PSObject.Properties[$Attribute]
    $values = @()
    if ($null -ne $prop -and $null -ne $prop.Value) { $values = @(@($prop.Value) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ }) }
    $columns.Count = [string]$values.Count
    if ($values.Count -eq 0) {
        return New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $Item -Status $script:Status.Info -Evidence $Evidence -Columns $columns `
            -Detail ("0 {0}: {1} is not set (attribute absent) in a read that succeeded. Learn does not say what an absent value means, and a read that cannot see the attribute returns nothing the same way. Inventory only, not graded." -f $Noun, $Attribute)
    }
    $columns.Suffixes = Get-AdfaC14NameList -Names $values -Cap ([int]$Config['NameListCap'])
    return New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $Item -Status $script:Status.Info -Evidence $Evidence -Columns $columns `
        -Detail ("{0} {1} read from {2}; listed in the Suffixes column. Inventory only, not graded." -f $values.Count, $Noun, $Attribute)
}

function Get-AdfaUpnSuffixRow {
    <#
    .SYNOPSIS
        Pure: "UPN suffixes: <forest>" from uPNSuffixes on CN=Partitions.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowEmptyString()][string]$ForestName = '', [AllowNull()]$Raw, [Parameter(Mandatory)][hashtable]$Config)
    return Get-AdfaSuffixListRow -Item ("UPN suffixes: {0}" -f $ForestName) -Scope $ForestName -Attribute 'uPNSuffixes' -Noun 'additional UPN suffixes' `
        -What 'CN=Partitions' -Evidence 'uPNSuffixes on CN=Partitions,CN=Configuration (Learn a-upnsuffixes, read 2026-11-17). Inventory only (catalogue INV-007): not graded.' -Raw $Raw -Config $Config
}

function Get-AdfaAllowedDnsSuffixRow {
    <#
    .SYNOPSIS
        Pure: "Allowed DNS suffixes: <domain>" from msDS-AllowedDNSSuffixes on the domain head.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowEmptyString()][string]$DomainName = '', [AllowNull()]$Raw, [Parameter(Mandatory)][hashtable]$Config)
    return Get-AdfaSuffixListRow -Item ("Allowed DNS suffixes: {0}" -f $DomainName) -Scope $DomainName -Attribute 'msDS-AllowedDNSSuffixes' -Noun 'allowed DNS suffixes' `
        -What 'the domain head' -Evidence 'msDS-AllowedDNSSuffixes on the domain head, "the list of allowed suffixes for the dNSHostName attribute in computer objects" (Learn a-msds-alloweddnssuffixes, read 2026-11-17). Inventory only (catalogue INV-007): not graded.' -Raw $Raw -Config $Config
}

function Get-AdfaDnsSuffixRows {
    <#
    .SYNOPSIS
        Pure: "DNS suffix: <dc>" per DC - the suffix of its host name against its domain (disjoint
        namespace, inventory only) - and a population row for each scoped domain no DC row covers.
    .DESCRIPTION
        Disjoint is "a primary DNS suffix that does not match the DNS name of the Active Directory
        domain" (Learn). Microsoft calls it usable with caution, so it is never graded. A DC whose
        domain is not known (the fallback enumeration) or whose host name has no suffix gets
        Disjoint "Unknown" and Not Assessed.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @(),
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    $evidence = 'The suffix of each DC''s host name (dNSHostName, from the DC inventory) against the DNS name of its domain. Disjoint namespace: Learn plan/disjoint-namespace and event-ids-5788-5789, read 2026-11-17 ("can be used with caution"). Inventory only (catalogue INV-007): not graded.'
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope ([string]$gap.Domain) -Item ("DNS suffix (population): {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed -Evidence $evidence `
            -Columns ([ordered]@{ DnsSuffix = ''; Domain = [string]$gap.Domain; Disjoint = 'Unknown' }) -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No DC DNS suffix of this domain was compared.')
    }
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = ([string]$named.HostName).Trim().TrimEnd('.')
        $scope = ([string]$named.Scope).Trim().TrimEnd('.')
        $columns = [ordered]@{ DnsSuffix = ''; Domain = $scope; Disjoint = 'Unknown' }
        if ($dc -eq '') {
            $rows += New-AdfaC14Row -Area 'Inventory' -Scope $scope -Item 'DNS suffix: (unnamed)' -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
                -Detail 'The inventory holds a domain controller with no host name, so there is no suffix to compare.'
            continue
        }
        $item = ("DNS suffix: {0}" -f $dc)
        $dot = $dc.IndexOf('.')
        if ($dot -lt 1 -or $dot -ge ($dc.Length - 1)) {
            $rows += New-AdfaC14Row -Area 'Inventory' -Scope $scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
                -Detail 'The host name carries no DNS suffix, so whether it matches the domain is not known.'
            continue
        }
        $suffix = $dc.Substring($dot + 1)
        $columns.DnsSuffix = $suffix
        if ($scope -eq '') {
            $rows += New-AdfaC14Row -Area 'Inventory' -Scope $scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
                -Detail 'The domain of this DC is not known (it came from the fallback enumeration), so whether its suffix matches its domain is not known.'
            continue
        }
        if ($suffix -ieq $scope) { $columns.Disjoint = 'No' } else { $columns.Disjoint = 'Yes' }
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope $scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
            -Detail 'The suffix of the host name, the domain and whether they differ (Disjoint) are in their columns. Inventory only, not graded.'
    }
    return @($rows)
}

function Get-AdfaRunnerRow {
    <#
    .SYNOPSIS
        Pure: "Runner DC: <forest>" - the DC that answered this run (rootDSE dnsHostName) and the
        computer the run ran on.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowEmptyString()][string]$ForestName = '', [AllowNull()]$RootDse, [AllowEmptyString()][string]$ComputerName = '')
    $item = ("Runner DC: {0}" -f $ForestName)
    $evidence = 'dnsHostName of the rootDSE this run read (the DC that answered; -Server, when given, names it). Inventory only (catalogue INV-001): not graded.'
    $columns = [ordered]@{ RunnerDc = ''; RunnerComputer = $ComputerName }
    if ($null -eq $RootDse -or -not [bool](Get-AdfaConfigValue -Entry $RootDse -Name 'Ok')) {
        $err = ''
        $type = ''
        if ($null -ne $RootDse) { $err = ([string](Get-AdfaConfigValue -Entry $RootDse -Name 'Error')).Trim().TrimEnd('.'); $type = [string](Get-AdfaConfigValue -Entry $RootDse -Name 'ErrorType') }
        $class = Get-AdfaDirectoryReadErrorClass -Message $err -TypeName $type
        return New-AdfaC14Row -Area 'Inventory' -Scope $ForestName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail ("Reading the rootDSE failed ({0}): {1}. The DC that answered this run is not known." -f (Get-AdfaReadClassPhrase -Class $class), $err)
    }
    $runner = [string](Get-AdfaConfigValue -Entry $RootDse -Name 'DnsHostName')
    if ([string]::IsNullOrWhiteSpace($runner)) {
        return New-AdfaC14Row -Area 'Inventory' -Scope $ForestName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
            -Detail 'The rootDSE returned no dnsHostName. The DC that answered this run is not known.'
    }
    $columns.RunnerDc = $runner
    return New-AdfaC14Row -Area 'Inventory' -Scope $ForestName -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
        -Detail 'The DC that answered this run and the computer the run ran on are in their columns. Inventory only, not graded.'
}

function Get-AdfaTopologyInventory {
    <#
    .SYNOPSIS
        Forest: functional levels, the five FSMO holders, UPN and allowed DNS suffixes, each DC's
        DNS suffix and the runner DC (INV-001, INV-007). Directory reads only.
    .DESCRIPTION
        From the forest root domain: CN=Partitions (msDS-Behavior-Version, uPNSuffixes,
        fSMORoleOwner) and CN=Schema (fSMORoleOwner). From each scoped domain, read from itself: the
        domain head (msDS-Behavior-Version, fSMORoleOwner, msDS-AllowedDNSSuffixes), CN=RID Manager$
        and CN=Infrastructure (fSMORoleOwner). Every read names its properties. A domain whose DN
        could not be read gets every one of its rows Not Assessed with that cause.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowEmptyString()][string]$ForestName = '',
        [AllowEmptyString()][string]$RootDomain = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$Domains = @(),
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @(),
        [AllowNull()][AllowEmptyString()][string]$ForestError = '',
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config,
        [AllowEmptyString()][string]$ComputerName = [Environment]::MachineName
    )
    if (-not [string]::IsNullOrWhiteSpace($ForestError)) {
        return @(New-AdfaC14Row -Area 'Inventory' -Scope '' -Item ("Topology inventory: {0}" -f $ForestName) -Status $script:Status.NotAssessed `
                -Detail ("The forest could not be read ({0}), so no functional level, FSMO holder, suffix or runner DC was read. This is not a clean result." -f $ForestError.Trim().TrimEnd('.')))
    }
    $rows = @()
    $max = [int]$Config['MaxObjects']
    $rootDn = Get-AdfaInventoryDomainDn -DomainName $RootDomain -AdParams $AdParams
    if ($rootDn.Ok) {
        $partitions = Get-AdfaInventoryDirectoryRaw -Server $RootDomain -Identity ("CN=Partitions,CN=Configuration,{0}" -f $rootDn.Dn) -Properties @('msDS-Behavior-Version', 'uPNSuffixes', 'fSMORoleOwner') -MaxObjects $max -AdParams $AdParams
        $schema = Get-AdfaInventoryDirectoryRaw -Server $RootDomain -Identity ("CN=Schema,CN=Configuration,{0}" -f $rootDn.Dn) -Properties @('fSMORoleOwner') -MaxObjects $max -AdParams $AdParams
    }
    else {
        $partitions = New-AdfaInventoryFailedRead -ErrorText ("the forest root domain's distinguished name could not be read: {0}" -f $rootDn.Error) -ErrorType $rootDn.ErrorType
        $schema = $partitions
    }
    $rows += Get-AdfaLevelRow -Kind 'Forest' -Scope $ForestName -Raw $partitions -Config $Config
    $rows += Get-AdfaFsmoRow -Role 'Schema master' -Scope $ForestName -Raw $schema -Config $Config
    $rows += Get-AdfaFsmoRow -Role 'Domain naming master' -Scope $ForestName -Raw $partitions -Config $Config
    $rows += Get-AdfaUpnSuffixRow -ForestName $ForestName -Raw $partitions -Config $Config
    foreach ($d in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        $dn = Get-AdfaInventoryDomainDn -DomainName $d -AdParams $AdParams
        if ($dn.Ok) {
            $head = Get-AdfaInventoryDirectoryRaw -Server $d -Identity $dn.Dn -Properties @('msDS-Behavior-Version', 'fSMORoleOwner', 'msDS-AllowedDNSSuffixes') -MaxObjects $max -AdParams $AdParams
            $rid = Get-AdfaInventoryDirectoryRaw -Server $d -Identity ("CN=RID Manager$,CN=System,{0}" -f $dn.Dn) -Properties @('fSMORoleOwner') -MaxObjects $max -AdParams $AdParams
            $infra = Get-AdfaInventoryDirectoryRaw -Server $d -Identity ("CN=Infrastructure,{0}" -f $dn.Dn) -Properties @('fSMORoleOwner') -MaxObjects $max -AdParams $AdParams
        }
        else {
            $head = New-AdfaInventoryFailedRead -ErrorText ("the domain's distinguished name could not be read: {0}" -f $dn.Error) -ErrorType $dn.ErrorType
            $rid = $head
            $infra = $head
        }
        $rows += Get-AdfaLevelRow -Kind 'Domain' -Scope $d -Raw $head -Config $Config
        $rows += Get-AdfaFsmoRow -Role 'PDC emulator' -Scope $d -Raw $head -Config $Config
        $rows += Get-AdfaFsmoRow -Role 'RID master' -Scope $d -Raw $rid -Config $Config
        $rows += Get-AdfaFsmoRow -Role 'Infrastructure master' -Scope $d -Raw $infra -Config $Config
        $rows += Get-AdfaAllowedDnsSuffixRow -DomainName $d -Raw $head -Config $Config
    }
    $rows += Get-AdfaRunnerRow -ForestName $ForestName -RootDse (Get-AdfaRootDseRaw -AdParams $AdParams) -ComputerName $ComputerName
    $rows += @(Get-AdfaDnsSuffixRows -DomainControllers $DomainControllers -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains -Config $Config)
    return @($rows)
}

# --- INV-006 -----------------------------------------------------------------------------------

function Get-AdfaTrustAttributeDecode {
    <#
    .SYNOPSIS
        Pure: the trustAttributes flags by their MS-ADTS names. A bit the table does not name is
        kept as "unknown 0x..", never dropped. The value is a 32-bit field: a negative number (the
        high bit read as signed) is taken as unsigned. A value not returned or not a whole number is
        not measured - never "no flags".
    .OUTPUTS
        [pscustomobject] Measured, Value, Flags (string[]), Unknown (string[]), Reason.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Value, [Parameter(Mandatory)][hashtable]$Config)
    $out = [pscustomobject]@{ Measured = $false; Value = $null; Flags = @(); Unknown = @(); Reason = '' }
    if ($null -eq $Value -or [string]::IsNullOrWhiteSpace([string]$Value)) { $out.Reason = 'trustAttributes was not returned'; return $out }
    $n = ConvertTo-AdfaInventoryInteger -Value $Value
    if ($null -eq $n) {
        $out.Reason = 'trustAttributes holds a value that is not a whole number'
        return $out
    }
    if ($n -lt 0 -and $n -ge [int64]-2147483648) { $n = $n + [int64]4294967296 }
    if ($n -lt 0 -or $n -gt [int64]4294967295) { $out.Reason = 'trustAttributes holds a value outside 32 bits'; return $out }
    $flags = @()
    $remaining = $n
    foreach ($f in @($Config['TrustAttributeFlags'])) {
        $bit = [int64](Get-AdfaConfigValue -Entry $f -Name 'Bit')
        if (($n -band $bit) -ne 0) {
            $flags += [string](Get-AdfaConfigValue -Entry $f -Name 'Name')
            $remaining = $remaining -band (-bnot $bit)
        }
    }
    $unknown = @()
    for ($i = 0; $i -lt 32; $i++) {
        $b = [int64]1 -shl $i
        if (($remaining -band $b) -ne 0) { $unknown += ("unknown 0x{0:X}" -f $b) }
    }
    $out.Value = $n
    $out.Flags = @($flags)
    $out.Unknown = @($unknown)
    $out.Measured = $true
    return $out
}

function Get-AdfaInventoryCodeLabel {
    <#
    .SYNOPSIS
        Pure: "<raw> <name>" for an enumerated value, "<raw> (no published name)" for one the table
        does not name, '' for none.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Value, [AllowNull()][hashtable]$Labels)
    if ($null -eq $Value -or [string]::IsNullOrWhiteSpace([string]$Value)) { return '' }
    $key = ([string]$Value).Trim()
    if ($null -ne $Labels -and $Labels.ContainsKey($key)) { return ("{0} {1}" -f $key, [string]$Labels[$key]) }
    return ("{0} (no published name)" -f $key)
}

function Get-AdfaTrustInventoryRows {
    <#
    .SYNOPSIS
        Pure: "Trust: <domain> -> <partner>" per trustedDomain object, and "Trusts (population):
        <domain>" with the number read.
    .DESCRIPTION
        Columns, never graded: trustAttributes raw and by name; direction and type raw and by name;
        transitivity (NON_TRANSITIVE set or clear - clear is not claimed to mean transitive); the
        SID filtering flags (QUARANTINED_DOMAIN, TREAT_AS_EXTERNAL, PIM_TRUST); CROSS_ORGANIZATION by
        its raw name (Learn does not call it "selective authentication"); TGT delegation from the
        MS-KILE rule. A trust with no readable trustAttributes is Not Assessed. A failed or capped read
        makes the population Not Assessed with its cause, never 0 trusts.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName, [AllowNull()]$Raw, [Parameter(Mandatory)][hashtable]$Config)
    $rows = @()
    $evidence = 'trustedDomain objects one level under CN=System of this domain, read from the domain, listed attributes only (cn, trustPartner, flatName, trustAttributes, trustDirection, trustType). Bits: MS-ADTS 6.1.6.7.9; trustType: MS-ADTS 6.1.6.7.15; trustDirection: MS-LSAD; TGT delegation: MS-KILE (Learn, read 2026-11-17). Inventory only (catalogue INV-006): not graded.'
    $popItem = ("Trusts (population): {0}" -f $DomainName)
    $cause = Get-AdfaInventoryReadCause -Raw $Raw -What 'the trustedDomain objects of this domain' -MaxObjects ([int]$Config['MaxObjects'])
    if ($cause -ne '') {
        return @(New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $popItem -Status $script:Status.NotAssessed -Evidence $evidence -Columns ([ordered]@{ Count = '' }) `
                -Detail ("{0} How many trusts this domain has is not known - not zero." -f $cause))
    }
    $records = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Records') | Where-Object { $null -ne $_ })
    foreach ($r in $records) {
        $partner = [string](Get-AdfaConfigValue -Entry $r -Name 'trustPartner')
        if ([string]::IsNullOrWhiteSpace($partner)) { $partner = [string](Get-AdfaConfigValue -Entry $r -Name 'cn') }
        if ([string]::IsNullOrWhiteSpace($partner)) { $partner = [string](Get-AdfaConfigValue -Entry $r -Name 'Name') }
        if ([string]::IsNullOrWhiteSpace($partner)) { $partner = '(no trustPartner)' }
        $item = ("Trust: {0} -> {1}" -f $DomainName, $partner)
        $raw = Get-AdfaConfigValue -Entry $r -Name 'trustAttributes'
        $decode = Get-AdfaTrustAttributeDecode -Value $raw -Config $Config
        $columns = [ordered]@{
            Partner = $partner; FlatName = [string](Get-AdfaConfigValue -Entry $r -Name 'flatName'); TrustAttributes = ''; TrustAttributeFlags = ''
            TrustDirection = (Get-AdfaInventoryCodeLabel -Value (Get-AdfaConfigValue -Entry $r -Name 'trustDirection') -Labels $Config['TrustDirectionLabels'])
            TrustType = (Get-AdfaInventoryCodeLabel -Value (Get-AdfaConfigValue -Entry $r -Name 'trustType') -Labels $Config['TrustTypeLabels'])
            Transitive = ''; SidFiltering = ''; CrossOrganization = ''; TgtDelegation = ''
        }
        if (-not $decode.Measured) {
            $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns `
                -Detail ("{0}, so the trust's flags (transitivity, SID filtering, TGT delegation) are not known." -f $decode.Reason)
            continue
        }
        $flags = @($decode.Flags)
        $columns.TrustAttributes = ("0x{0:X}" -f [int64]$decode.Value)
        $columns.TrustAttributeFlags = (@($flags + @($decode.Unknown)) -join ', ')
        if ($flags -contains 'NON_TRANSITIVE') { $columns.Transitive = 'No (NON_TRANSITIVE set)' } else { $columns.Transitive = 'NON_TRANSITIVE clear' }
        $sid = @($flags | Where-Object { @('QUARANTINED_DOMAIN', 'TREAT_AS_EXTERNAL', 'PIM_TRUST') -contains $_ })
        if ($sid.Count -gt 0) { $columns.SidFiltering = ($sid -join ', ') } else { $columns.SidFiltering = 'none of QUARANTINED_DOMAIN, TREAT_AS_EXTERNAL, PIM_TRUST set' }
        if ($flags -contains 'CROSS_ORGANIZATION') { $columns.CrossOrganization = 'Yes (CROSS_ORGANIZATION set)' } else { $columns.CrossOrganization = 'No' }
        $disable = @($flags | Where-Object { @('CROSS_ORGANIZATION_NO_TGT_DELEGATION', 'QUARANTINED_DOMAIN') -contains $_ })
        $enable = @($flags | Where-Object { @('WITHIN_FOREST', 'CROSS_ORGANIZATION_ENABLE_TGT_DELEGATION') -contains $_ })
        if ($disable.Count -gt 0) { $columns.TgtDelegation = ("Disabled by trustAttributes ({0})" -f ($disable -join ', ')) }
        elseif ($enable.Count -gt 0) { $columns.TgtDelegation = ("Enabled by trustAttributes ({0}) for a source ticket that is ok-as-delegate" -f ($enable -join ', ')) }
        else { $columns.TgtDelegation = 'not enabled by trustAttributes (neither WITHIN_FOREST nor CROSS_ORGANIZATION_ENABLE_TGT_DELEGATION set)' }
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
            -Detail 'trustedDomain object read; its flags, direction and type are in their columns. Inventory only, not graded.'
    }
    $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $popItem -Status $script:Status.Info -Evidence $evidence -Columns ([ordered]@{ Count = [string]$records.Count }) `
        -Detail ("{0} trustedDomain object(s) in a complete read under CN=System of this domain." -f $records.Count)
    return @($rows)
}

function Get-AdfaTrustInventory {
    <#
    .SYNOPSIS
        Trusts: the trustedDomain objects of every scoped domain, read from that domain (INV-006).
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$Domains = @(),
        [AllowNull()][AllowEmptyString()][string]$ForestError = '',
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    if (-not [string]::IsNullOrWhiteSpace($ForestError)) {
        return @(New-AdfaC14Row -Area 'Inventory' -Item 'Trusts (population): (forest unreadable)' -Status $script:Status.NotAssessed `
                -Detail ("The forest could not be read ({0}), so no domain was scoped and no trustedDomain object was read. This is not a clean result." -f $ForestError.Trim().TrimEnd('.')))
    }
    $rows = @()
    foreach ($d in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        $dn = Get-AdfaInventoryDomainDn -DomainName $d -AdParams $AdParams
        if ($dn.Ok) {
            $raw = Get-AdfaInventoryDirectoryRaw -Server $d -SearchBase ("CN=System,{0}" -f $dn.Dn) -SearchScope 'OneLevel' -LDAPFilter '(objectClass=trustedDomain)' `
                -Properties @($Config['TrustProperties']) -MaxObjects ([int]$Config['MaxObjects']) -AdParams $AdParams
        }
        else { $raw = New-AdfaInventoryFailedRead -ErrorText ("the domain's distinguished name could not be read: {0}" -f $dn.Error) -ErrorType $dn.ErrorType }
        $rows += @(Get-AdfaTrustInventoryRows -DomainName $d -Raw $raw -Config $Config)
    }
    return @($rows)
}

# --- INV-008 / INV-010 -------------------------------------------------------------------------

function ConvertTo-AdfaInventoryInteger {
    <#
    .SYNOPSIS
        Pure: a whole number from a directory or registry value - an integral number as it is, a
        string only when it is a whole number - or $null. A fraction, a boolean or text is $null.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    $base = $Value
    if ($Value -is [System.Management.Automation.PSObject]) { $base = $Value.PSObject.BaseObject }
    $integral = @([byte], [sbyte], [int16], [uint16], [int32], [uint32], [int64])
    if ($integral -contains $base.GetType()) { return [int64]$base }
    if ($base -is [uint64]) { if ($base -le [uint64][int64]::MaxValue) { return [int64]$base }; return $null }
    if ($base -isnot [string]) { return $null }
    $n = [int64]0
    if ([int64]::TryParse($base.Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$n)) { return $n }
    return $null
}

function ConvertTo-AdfaInventoryUInt32 {
    <#
    .SYNOPSIS
        Pure: a 32-bit flag attribute as an unsigned number (a negative value read as signed is
        taken as unsigned), or $null when it is not a whole number.
    #>
    [CmdletBinding()]
    param([AllowNull()]$Value)
    $n = ConvertTo-AdfaInventoryInteger -Value $Value
    if ($null -eq $n) { return $null }
    if ($n -lt 0 -and $n -ge [int64]-2147483648) { $n = $n + [int64]4294967296 }
    if ($n -lt 0 -or $n -gt [int64]4294967295) { return $null }
    return $n
}

function Get-AdfaObjectCountRows {
    <#
    .SYNOPSIS
        Pure: "Object count: <Kind> <domain>" for the thirteen counts of a domain, from the seven
        capped reads (Users, Computers, Groups, Contacts, OUs, gMSA, sMSA).
    .DESCRIPTION
        Enabled and disabled from ACCOUNTDISABLE (0x2) in userAccountControl; security and
        distribution groups from 0x80000000 in groupType. A read that failed or reached its cap, or
        a split with any record whose flags could not be read, is Not Assessed - never 0. A complete
        read that returned nothing is 0, visible to the account running the assessment.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowNull()][System.Collections.IDictionary]$Reads = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    if ($null -eq $Reads) { $Reads = @{} }
    $max = [int]$Config['MaxObjects']
    $filters = $Config['CountFilters']
    $evidence = ("Get-ADObject -Server {0} with the LDAP filter in the Filter column, at most {1} objects (MaxObjects, a tool default); counted as returned to the account running the assessment. ACCOUNTDISABLE 0x2 (Learn useraccountcontrol-manipulate-account-properties) and groupType 0x80000000 security (Learn a-grouptype), read 2026-11-17. Inventory only (catalogue INV-008): not graded." -f $DomainName, $max)
    $newRow = {
        param([string]$Kind, [string]$Status, [string]$Count, [string]$Detail, [string]$Filter)
        New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item ("Object count: {0} {1}" -f $Kind, $DomainName) -Status $Status -Evidence $evidence `
            -Columns ([ordered]@{ Kind = $Kind; Count = $Count; Filter = $Filter }) -Detail $Detail
    }
    $plan = @(
        @{ Read = 'Users'; Kinds = @('Users', 'Enabled users', 'Disabled users'); Attribute = 'userAccountControl'; Bit = [int64]$Config['AccountDisableBit']; Set = 'Disabled users'; Clear = 'Enabled users' }
        @{ Read = 'Computers'; Kinds = @('Computers', 'Enabled computers', 'Disabled computers'); Attribute = 'userAccountControl'; Bit = [int64]$Config['AccountDisableBit']; Set = 'Disabled computers'; Clear = 'Enabled computers' }
        @{ Read = 'Groups'; Kinds = @('Groups', 'Security groups', 'Distribution groups'); Attribute = 'groupType'; Bit = [int64]$Config['GroupSecurityBit']; Set = 'Security groups'; Clear = 'Distribution groups' }
        @{ Read = 'Contacts'; Kinds = @('Contacts') }
        @{ Read = 'OUs'; Kinds = @('OUs') }
        @{ Read = 'gMSA'; Kinds = @('gMSA') }
        @{ Read = 'sMSA'; Kinds = @('sMSA') }
    )
    foreach ($p in $plan) {
        $readName = [string]$p['Read']
        $filter = ''
        if ($null -ne $filters -and $filters.Contains($readName)) { $filter = [string]$filters[$readName] }
        $raw = $null
        if ($Reads.Contains($readName)) { $raw = $Reads[$readName] }
        $kinds = @($p['Kinds'])
        $cause = Get-AdfaInventoryReadCause -Raw $raw -What ("the {0} of this domain" -f $readName) -MaxObjects $max
        if ($cause -ne '') {
            foreach ($k in $kinds) { $rows += & $newRow $k $script:Status.NotAssessed '' ("{0} The count is not known - not zero." -f $cause) $filter }
            continue
        }
        $records = @(@(Get-AdfaConfigValue -Entry $raw -Name 'Records') | Where-Object { $null -ne $_ })
        $rows += & $newRow $kinds[0] $script:Status.Info ([string]$records.Count) ("{0} object(s) in a complete read of this domain with the filter in the Filter column, visible to the account running the assessment." -f $records.Count) $filter
        if ($kinds.Count -eq 1) { continue }
        $attribute = [string]$p['Attribute']
        $bit = [int64]$p['Bit']
        $set = 0
        $clear = 0
        $unread = 0
        foreach ($r in $records) {
            $flags = ConvertTo-AdfaInventoryUInt32 -Value (Get-AdfaConfigValue -Entry $r -Name $attribute)
            if ($null -eq $flags) { $unread++; continue }
            if (([int64]$flags -band $bit) -ne 0) { $set++ } else { $clear++ }
        }
        foreach ($k in @([string]$p['Clear'], [string]$p['Set'])) {
            if ($unread -gt 0) {
                $rows += & $newRow $k $script:Status.NotAssessed '' ("{0} of the {1} object(s) read carried no readable {2}, so this split cannot be counted - not zero." -f $unread, $records.Count, $attribute) $filter
                continue
            }
            $n = $clear
            if ($k -eq [string]$p['Set']) { $n = $set }
            $rows += & $newRow $k $script:Status.Info ([string]$n) ("{0} of the {1} object(s) read, split on {2} 0x{3:X}." -f $n, $records.Count, $attribute, $bit) $filter
        }
    }
    return @($rows)
}

function Get-AdfaGroupScopeType {
    <#
    .SYNOPSIS
        Pure: the scope (Global, DomainLocal, Universal, Other) and type (Security, Distribution) a
        groupType value holds; both '' when it could not be read.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param([AllowNull()]$Value, [Parameter(Mandatory)][hashtable]$Config)
    $out = [pscustomobject]@{ Read = $false; Scope = ''; Type = ''; Raw = '' }
    $n = ConvertTo-AdfaInventoryUInt32 -Value $Value
    if ($null -eq $n) { return $out }
    $out.Read = $true
    $out.Raw = ("0x{0:X}" -f [int64]$n)
    $out.Scope = 'Other'
    $bits = $Config['GroupScopeBits']
    foreach ($k in @($bits.Keys)) { if (([int64]$n -band [int64]$bits[$k]) -ne 0) { $out.Scope = [string]$k; break } }
    if (([int64]$n -band [int64]$Config['GroupSecurityBit']) -ne 0) { $out.Type = 'Security' } else { $out.Type = 'Distribution' }
    return $out
}

function Get-AdfaGroupInventoryRows {
    <#
    .SYNOPSIS
        Pure: "Groups by type and scope", "Empty groups" and "Group member counts" for one domain.
    .DESCRIPTION
        Direct members only, from the number of member values the read returned. A group with
        MemberCountCeiling (1500, the MaxValRange default) values or more is not counted exactly.
        Members by primaryGroupID are not in member, so an "empty" group can still have members; the
        row says so. Names only in the Groups column. A failed or capped read is Not Assessed.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName, [AllowNull()]$Raw, [Parameter(Mandatory)][hashtable]$Config)
    $ceiling = [int]$Config['MemberCountCeiling']
    $evidence = ("Get-ADObject -Server {0} (objectClass=group), sAMAccountName and groupType, and the number of member values only (never the members), at most {1} groups (MaxObjects, a tool default). groupType bits: Learn a-grouptype; MaxValRange default 1500: Learn view-set-ldap-policy-using-ntdsutil (read 2026-11-17). One row per group in csv\Groups_<domain>.csv. Inventory only (catalogue INV-010): not graded." -f $DomainName, [int]$Config['MaxObjects'])
    $typeItem = ("Groups by type and scope: {0}" -f $DomainName)
    $emptyItem = ("Empty groups: {0}" -f $DomainName)
    $countItem = ("Group member counts: {0}" -f $DomainName)
    $cause = Get-AdfaInventoryReadCause -Raw $Raw -What 'the groups of this domain' -MaxObjects ([int]$Config['MaxObjects'])
    if ($cause -ne '') {
        $text = ("{0} The group inventory of this domain is not known - not zero." -f $cause)
        return @(
            (New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $typeItem -Status $script:Status.NotAssessed -Evidence $evidence -Detail $text)
            (New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $emptyItem -Status $script:Status.NotAssessed -Evidence $evidence -Columns ([ordered]@{ Count = ''; Groups = '' }) -Detail $text)
            (New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $countItem -Status $script:Status.NotAssessed -Evidence $evidence -Detail $text)
        )
    }
    $records = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Records') | Where-Object { $null -ne $_ })
    $types = [ordered]@{ GlobalSecurity = 0; GlobalDistribution = 0; DomainLocalSecurity = 0; DomainLocalDistribution = 0; UniversalSecurity = 0; UniversalDistribution = 0; OtherScope = 0; TypeNotRead = 0 }
    $empty = @()
    $exact = 0
    $over = 0
    $memberUnread = 0
    foreach ($r in $records) {
        $st = Get-AdfaGroupScopeType -Value (Get-AdfaConfigValue -Entry $r -Name 'groupType') -Config $Config
        if (-not $st.Read) { $types.TypeNotRead++ }
        elseif ($st.Scope -eq 'Other') { $types.OtherScope++ }
        else { $types[("{0}{1}" -f $st.Scope, $st.Type)]++ }
        $countValue = Get-AdfaConfigValue -Entry $r -Name 'memberCount'
        if ($null -eq $countValue) { $memberUnread++; continue }
        $count = [int]$countValue
        if ($count -ge $ceiling) { $over++; continue }
        $exact++
        if ($count -eq 0) {
            $name = [string](Get-AdfaConfigValue -Entry $r -Name 'sAMAccountName')
            if ([string]::IsNullOrWhiteSpace($name)) { $name = [string](Get-AdfaConfigValue -Entry $r -Name 'Name') }
            $empty += $name
        }
    }
    $typeColumns = [ordered]@{ Groups = [string]$records.Count }
    foreach ($k in @($types.Keys)) { $typeColumns[$k] = [string]$types[$k] }
    $rows = @()
    $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $typeItem -Status $script:Status.Info -Evidence $evidence -Columns $typeColumns `
        -Detail ("{0} group(s) in a complete read, counted by scope (groupType 0x2 global, 0x4 domain local, 0x8 universal) and type (0x80000000 security) in their columns." -f $records.Count)
    $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $emptyItem -Status $script:Status.Info -Evidence $evidence `
        -Columns ([ordered]@{ Count = [string]$empty.Count; Groups = (Get-AdfaC14NameList -Names $empty -Cap ([int]$Config['NameListCap'])) }) `
        -Detail ("{0} group(s) with no direct member visible to this account; names in the Groups column. Members by primaryGroupID (the primary group of an account) are not held in member and are not counted, so a group listed here can still have members." -f $empty.Count)
    $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $countItem -Status $script:Status.Info -Evidence $evidence `
        -Columns ([ordered]@{ Groups = [string]$records.Count; CountedExactly = [string]$exact; NotCountedExactly = [string]$over; MemberNotRead = [string]$memberUnread }) `
        -Detail ("Direct member counts per group are in csv\Groups_<domain>.csv. A group returning {0} member values or more (the MaxValRange default, beyond which range retrieval is needed) is not counted exactly and is listed as '{0} or more'." -f $ceiling)
    return @($rows)
}

function ConvertTo-AdfaGroupExportRow {
    <#
    .SYNOPSIS
        Pure: one row per group for csv\Groups_<domain>.csv - name, scope, type, raw groupType and
        the direct member count ("<ceiling> or more" where it was not counted exactly).
        ListComplete on every row says whether the read held every group of the domain: a read
        that reached its cap (MaxObjects) gives at most MaxObjects rows, each marked "No", so the
        CSV never reads as the domain's complete group list.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([Parameter(Mandatory)][string]$DomainName, [AllowNull()]$Raw, [Parameter(Mandatory)][hashtable]$Config)
    if ($null -eq $Raw -or -not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) { return @() }
    $ceiling = [int]$Config['MemberCountCeiling']
    $max = [int]$Config['MaxObjects']
    $records = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Records') | Where-Object { $null -ne $_ })
    $complete = 'Yes'
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'Capped')) {
        $complete = ("No: the read reached its cap of {0} objects (MaxObjects, a tool default), so groups after it are not listed" -f $max)
        $records = @($records | Select-Object -First $max)
    }
    $out = @()
    foreach ($r in $records) {
        $st = Get-AdfaGroupScopeType -Value (Get-AdfaConfigValue -Entry $r -Name 'groupType') -Config $Config
        $name = [string](Get-AdfaConfigValue -Entry $r -Name 'sAMAccountName')
        if ([string]::IsNullOrWhiteSpace($name)) { $name = [string](Get-AdfaConfigValue -Entry $r -Name 'Name') }
        $countValue = Get-AdfaConfigValue -Entry $r -Name 'memberCount'
        $members = 'not read'
        if ($null -ne $countValue) {
            if ([int]$countValue -ge $ceiling) { $members = ("{0} or more (not counted exactly)" -f $ceiling) } else { $members = [string][int]$countValue }
        }
        $out += [pscustomobject]@{ Domain = $DomainName; Name = $name; Scope = $st.Scope; Type = $st.Type; GroupType = $st.Raw; DirectMembers = $members; ListComplete = $complete }
    }
    return @($out)
}

function Get-AdfaIdentityInventoryDepth {
    <#
    .SYNOPSIS
        Identity: per scoped domain, the seven capped count reads and the group inventory (INV-008,
        INV-010). Directory reads only, listed properties, member values counted and never kept.
    .OUTPUTS
        [pscustomobject] Counts (rows), Groups (rows), GroupExport (domain -> rows for the CSV).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$Domains = @(),
        [AllowNull()][AllowEmptyString()][string]$ForestError = '',
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config
    )
    $counts = @()
    $groups = @()
    $export = @{}
    if (-not [string]::IsNullOrWhiteSpace($ForestError)) {
        $counts += New-AdfaC14Row -Area 'Inventory' -Item 'Object count: (forest unreadable)' -Status $script:Status.NotAssessed `
            -Detail ("The forest could not be read ({0}), so no domain was scoped and nothing was counted. This is not a clean result." -f $ForestError.Trim().TrimEnd('.'))
    }
    $max = [int]$Config['MaxObjects']
    foreach ($d in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        $reads = [ordered]@{}
        foreach ($kind in @($Config['CountFilters'].Keys)) {
            $props = @()
            $countProps = @()
            if ($kind -eq 'Users' -or $kind -eq 'Computers') { $props = @('userAccountControl') }
            if ($kind -eq 'Groups') { $props = @('sAMAccountName', 'groupType'); $countProps = @('member') }
            $reads[[string]$kind] = Get-AdfaInventoryDirectoryRaw -Server $d -LDAPFilter ([string]$Config['CountFilters'][$kind]) -Properties $props -CountProperties $countProps -MaxObjects $max -AdParams $AdParams
        }
        $counts += @(Get-AdfaObjectCountRows -DomainName $d -Reads $reads -Config $Config)
        $groups += @(Get-AdfaGroupInventoryRows -DomainName $d -Raw $reads['Groups'] -Config $Config)
        $export[$d] = @(ConvertTo-AdfaGroupExportRow -DomainName $d -Raw $reads['Groups'] -Config $Config)
    }
    return [pscustomobject]@{ Counts = @($counts); Groups = @($groups); GroupExport = $export }
}

# --- INV-009 -----------------------------------------------------------------------------------

function Get-AdfaStaleDisabledVerdict {
    <#
    .SYNOPSIS
        Pure: "Stale disabled users" / "Stale disabled computers" for one domain - inventory only.
    .DESCRIPTION
        Disabled accounts (ACCOUNTDISABLE set) whose lastLogonTimestamp is at or before Now minus
        StaleDays, or that have none and were created at or before it. Info with the count (names in
        the Accounts column) - never graded, as the catalogue says (INV-009). Not Assessed, never 0,
        when the read failed (unreachable, access denied, timed out told apart), reached its cap,
        logon-time updates are disabled, StaleDays is not longer than the sync interval, a returned
        object carried neither time, or nothing was found and the disabled accounts could not be
        counted. StaleDays is the -StaleDays parameter: Microsoft publishes no stale threshold.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [Parameter(Mandatory)][ValidateSet('User', 'Computer')][string]$Kind,
        [AllowNull()]$Raw,
        [AllowNull()]$Interval,
        [Parameter(Mandatory)][int]$StaleDays,
        [Parameter(Mandatory)][datetime]$Now,
        [AllowNull()]$Population = $null,
        [hashtable]$Config = $script:Config.Stale
    )
    $noun = 'user'
    $item = 'Stale disabled users'
    if ($Kind -eq 'Computer') { $noun = 'computer'; $item = 'Stale disabled computers' }
    $sync = Get-AdfaC14SyncInterval -Interval $Interval -Config $Config
    $caveat = ("lastLogonTimestamp can trail the real last logon by up to the logon-sync interval ({0})." -f $sync.Text)
    $evidence = ("LDAP filter: disabled (ACCOUNTDISABLE set), lastLogonTimestamp at or before the cutoff, or none and whenCreated at or before it; -Server {0}, listed properties only, at most {1} objects (MaxObjects). Declared population: the disabled accounts of the same kind. StaleDays {2} is the -StaleDays parameter, set by the operator: Microsoft publishes no stale threshold. Inventory only (catalogue INV-009): not graded." -f $DomainName, [int]$Config['MaxObjects'], $StaleDays)
    $columns = [ordered]@{ Count = ''; NeverLoggedOn = ''; Population = ''; StaleDays = [string]$StaleDays; SyncIntervalDays = $sync.Days; Accounts = '' }
    $na = { param([string]$Why) New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -Detail ("{0} The count of stale disabled {1} accounts is not known - not zero." -f $Why, $noun) }
    if ($null -eq $Raw) { return (& $na 'The accounts were not read.') }
    if (-not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) {
        $err = [string](Get-AdfaConfigValue -Entry $Raw -Name 'Error')
        $class = Get-AdfaDirectoryReadErrorClass -Message $err -TypeName ([string](Get-AdfaConfigValue -Entry $Raw -Name 'ErrorType'))
        return (& $na ("Reading the disabled {0} accounts of this domain failed ({1}): {2}." -f $noun, (Get-AdfaReadClassPhrase -Class $class), $err.Trim().TrimEnd('.')))
    }
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'Capped')) { return (& $na ("The read reached its cap of {0} objects (MaxObjects, a tool default), so the count is incomplete." -f [int]$Config['MaxObjects'])) }
    if ($sync.Disabled) { return (& $na ("{0}: lastLogonTimestamp updates are disabled, so the attribute cannot show activity." -f $sync.Text)) }
    if ($StaleDays -le $sync.Days) { return (& $na ("StaleDays {0} is not longer than the logon-sync interval ({1} days), the most lastLogonTimestamp can trail the real last logon. Re-run with a larger -StaleDays." -f $StaleDays, $sync.Days)) }
    $nowUtc = $Now
    if ($nowUtc.Kind -eq [System.DateTimeKind]::Local) { $nowUtc = $nowUtc.ToUniversalTime() }
    $cutoff = $nowUtc.AddDays(-1 * $StaleDays)
    $stale = @()
    $never = 0
    $unclassified = 0
    foreach ($r in @(Get-AdfaConfigValue -Entry $Raw -Name 'Records' | Where-Object { $null -ne $_ })) {
        $last = Get-AdfaConfigValue -Entry $r -Name 'LastLogonUtc'
        $created = Get-AdfaConfigValue -Entry $r -Name 'WhenCreatedUtc'
        $name = [string](Get-AdfaConfigValue -Entry $r -Name 'Name')
        if ([bool](Get-AdfaConfigValue -Entry $r -Name 'HasLastLogon')) {
            if ($last -isnot [datetime]) { $unclassified++; continue }
            if ($last -le $cutoff) { $stale += $name }
            continue
        }
        if ($created -isnot [datetime]) { $unclassified++; continue }
        if ($created -le $cutoff) { $stale += $name; $never++ }
    }
    if ($unclassified -gt 0) { return (& $na ("{0} returned object(s) carried no readable lastLogonTimestamp and no readable whenCreated, so they could not be classified." -f $unclassified)) }
    $popOk = ($null -ne $Population -and [bool](Get-AdfaConfigValue -Entry $Population -Name 'Ok'))
    $popText = ("The disabled {0} accounts of this domain were not counted." -f $noun)
    if ($null -ne $Population -and -not $popOk) {
        $perr = [string](Get-AdfaConfigValue -Entry $Population -Name 'Error')
        $pclass = Get-AdfaDirectoryReadErrorClass -Message $perr -TypeName ([string](Get-AdfaConfigValue -Entry $Population -Name 'ErrorType'))
        $popText = ("Counting the disabled {0} accounts of this domain failed ({1}): {2}." -f $noun, (Get-AdfaReadClassPhrase -Class $pclass), $perr.Trim().TrimEnd('.'))
    }
    if ($popOk) {
        $columns.Population = [string](Get-AdfaConfigValue -Entry $Population -Name 'Count')
        if ([bool](Get-AdfaConfigValue -Entry $Population -Name 'Capped')) { $columns.Population = ("more than {0}" -f [int]$Config['MaxObjects']) }
        $popText = ("The read saw {0} disabled {1} account(s) in this domain." -f $columns.Population, $noun)
    }
    # Nothing found is a count only against a declared population the read could see.
    if ($stale.Count -eq 0 -and -not $popOk) { return (& $na ("{0} A read that returned nothing cannot be told from a read that saw nothing." -f $popText)) }
    $columns.Count = [string]$stale.Count
    $columns.NeverLoggedOn = [string]$never
    $columns.Accounts = Get-AdfaC14NameList -Names $stale -Cap ([int]$Config['NameListCap'])
    if ($stale.Count -gt 0) {
        return New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
            -Detail ("{0} disabled {1} account(s) with no logon recorded for more than {2} days; {3} of them never logged on. {4} {5} Names in the Accounts column. Inventory only, not graded." -f $stale.Count, $noun, $StaleDays, $never, $popText, $caveat)
    }
    return New-AdfaC14Row -Area 'Stale' -Scope $DomainName -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
        -Detail ("0 disabled {0} accounts with no logon recorded for more than {1} days, in a complete read. {2} {3} Inventory only, not graded." -f $noun, $StaleDays, $popText, $caveat)
}

# --- INV-011 -----------------------------------------------------------------------------------

function ConvertFrom-AdfaGpLink {
    <#
    .SYNOPSIS
        Pure: the entries of one gPLink value, "[<GPC DN>;<options>]" each, with or without an
        LDAP:// prefix. Options 0x1 disabled, 0x2 enforced (Learn group-policy-scope); any other bit
        is kept as UnknownOptions. An entry that cannot be parsed is kept with Parsed $false, never
        dropped and never read as "not linked": that includes options that are not ASCII digits or
        do not fit Int64 (gPLink is a free-form string anyone who may write it can set), and a DN
        with no DC= part, whose GPO cannot be placed in a domain.
        DomainDn is the DC= part of the GPC DN, lower case with no spaces: the domain the linked GPO
        belongs to. The GUID alone does not say that - the two default GPOs have the same GUID in
        every domain.
    .OUTPUTS
        [pscustomobject[]] Raw, Dn, DomainDn, Guid, Options, Disabled, Enforced, UnknownOptions, Parsed.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param([AllowNull()][AllowEmptyString()][string]$Value, [Parameter(Mandatory)][hashtable]$Config)
    if ([string]::IsNullOrWhiteSpace($Value)) { return @() }
    $entries = @()
    $unparsed = { param([string]$Text) [pscustomobject]@{ Raw = $Text; Dn = ''; DomainDn = ''; Guid = ''; Options = $null; Disabled = $false; Enforced = $false; UnknownOptions = $false; Parsed = $false } }
    $found = [regex]::Matches($Value, '\[([^\]]*)\]')
    if ($found.Count -eq 0) { return @(& $unparsed $Value.Trim()) }
    foreach ($m in $found) {
        $inner = [string]$m.Groups[1].Value
        # [0-9], not \d: in .NET \d matches every Unicode decimal digit, which Int64 does not parse.
        if ($inner -notmatch '^(?i)(?:LDAP://)?(.+);([0-9]+)$') { $entries += & $unparsed $inner; continue }
        $dn = [string]$Matches[1]
        $optionsText = [string]$Matches[2]
        $options = [int64]0
        if (-not [int64]::TryParse($optionsText, [System.Globalization.NumberStyles]::None, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$options)) { $entries += & $unparsed $inner; continue }
        $guid = [regex]::Match($dn, [string]$Config['GuidPattern']).Value
        if ([string]::IsNullOrWhiteSpace($guid)) { $entries += & $unparsed $inner; continue }
        $domainPart = [regex]::Match($dn, '(?i)(?:^|,)\s*(DC=.*)$')
        if (-not $domainPart.Success) { $entries += & $unparsed $inner; continue }
        $entries += [pscustomobject]@{
            Raw = $inner; Dn = $dn; DomainDn = (ConvertTo-AdfaGpLinkDomainDn -Dn $domainPart.Groups[1].Value); Guid = $guid.ToUpperInvariant(); Options = $options
            Disabled = (($options -band 1) -ne 0); Enforced = (($options -band 2) -ne 0); UnknownOptions = (($options -band (-bnot [int64]3)) -ne 0); Parsed = $true
        }
    }
    return @($entries)
}

function ConvertTo-AdfaGpLinkDomainDn {
    <#
    .SYNOPSIS
        Pure: a domain DN in the one form the GPO inventory compares - lower case, no space around
        ',' or '='. From a DN when one is given, otherwise built from the DNS name (DC= per label).
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowEmptyString()][string]$Dn = '', [AllowEmptyString()][string]$DomainName = '')
    $text = $Dn
    if ([string]::IsNullOrWhiteSpace($text) -and -not [string]::IsNullOrWhiteSpace($DomainName)) {
        $text = 'DC=' + ((@($DomainName.Trim().TrimEnd('.') -split '\.') | Where-Object { $_ -ne '' }) -join ',DC=')
    }
    return ($text.Trim() -replace '\s*([,=])\s*', '$1').ToLowerInvariant()
}

function Get-AdfaGpoDirectoryRows {
    <#
    .SYNOPSIS
        Pure: "GPO: <guid>" per groupPolicyContainer (status flags, WMI filter, links), "GPO links on a
        SOM: <domain>" per site, domain or OU that links one, and "GPO directory inventory: <domain>".
    .DESCRIPTION
        Display names, DNs and filter names only in columns. A GPO whose links could not be read has
        Links '' - never 0, never "unlinked" - and the summary is Not Assessed. A failed container read
        gives the summary alone, Not Assessed. The flags labels are the Gpo table's; a value it does
        not hold is "unknown". The GroupPolicy-module rows of 'GPO Inventory' are unchanged.
        A GPO "is a per-domain object that can be linked anywhere in the forest" (Learn
        group-policy-management-console, read 2026-11-17), so its links are looked for in this
        domain's SOMs, the sites, and the SOM reads of the other forest domains passed in -OtherSom.
        A link is credited to this domain's GPO only when the GPC DN in it names this domain, never by
        GUID alone; this domain is the one the groupPolicyContainer objects' own DNs name, else
        -DomainDn, else the DC= form of -DomainName. "No link" is stated only when every forest domain's SOMs
        were read; otherwise a GPO with none found has Links '' and is counted in NoLinkFound, the
        counts found are a floor, and the summary is Not Assessed when any GPO has none found.
        -ForestDomains empty means the forest's domain list is not known - the fail-closed case.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$DomainName,
        [AllowNull()]$Gpc, [AllowNull()]$Som, [AllowNull()]$Site, [AllowNull()]$Wmi,
        [AllowEmptyString()][string]$DomainDn = '',
        [AllowNull()][AllowEmptyCollection()][string[]]$ForestDomains = @(),
        [AllowNull()][AllowEmptyCollection()]$OtherSom = @(),
        [Parameter(Mandatory)][hashtable]$Config,
        [Parameter(Mandatory)][hashtable]$GpoConfig
    )
    $max = [int]$Config['MaxObjects']
    $evidence = ("groupPolicyContainer objects one level under CN=Policies,CN=System (displayName, flags, gPCWQLFilter, versionNumber); gPLink and gPOptions of the domain head, its OUs and every site, and of the domain head and OUs of every other scoped domain; msWMI-Som under CN=System. Read from the domain, listed properties, at most {0} objects per read. gPLink options: Learn group-policy-scope; gPCWQLFilter, msWMI-Som: Learn adschema; a GPO can be linked anywhere in the forest: Learn group-policy-management-console (read 2026-11-17); flags labels: the Gpo table (MS-GPOL). Inventory only (catalogue INV-011): not graded." -f $max)
    $sumItem = ("GPO directory inventory: {0}" -f $DomainName)
    $sumColumns = [ordered]@{ Gpos = ''; Linked = ''; Unlinked = ''; NoLinkFound = ''; Soms = ''; SomsWithNoLink = ''; Links = ''; UnparsedLinks = ''; LinksToOtherGpos = ''; OtherDomainSoms = ''; OtherDomainsNotRead = ''; UnlinkedGpos = ''; NoLinkFoundGpos = '' }
    $thisDn = ConvertTo-AdfaGpLinkDomainDn -Dn $DomainDn -DomainName $DomainName
    $gpcCause = Get-AdfaInventoryReadCause -Raw $Gpc -What 'the groupPolicyContainer objects of this domain' -MaxObjects $max
    if ($gpcCause -ne '') {
        return @(New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $sumItem -Status $script:Status.NotAssessed -Evidence $evidence -Columns $sumColumns `
                -Detail ("{0} How many GPOs this domain has is not known - not zero." -f $gpcCause))
    }
    $somCause = Get-AdfaInventoryReadCause -Raw $Som -What 'the gPLink of the domain head and its OUs' -MaxObjects $max
    $siteCause = Get-AdfaInventoryReadCause -Raw $Site -What 'the gPLink of the sites' -MaxObjects $max
    $wmiCause = Get-AdfaInventoryReadCause -Raw $Wmi -What 'the WMI filters (msWMI-Som)' -MaxObjects $max
    $linksKnown = ($somCause -eq '' -and $siteCause -eq '')
    $gpcRecords = @(@(Get-AdfaConfigValue -Entry $Gpc -Name 'Records') | Where-Object { $null -ne $_ })
    $guids = @{}
    foreach ($g in $gpcRecords) { $guids[([string](Get-AdfaConfigValue -Entry $g -Name 'Name')).ToUpperInvariant()] = $true }
    # The domain the GPOs were read from, as their own DNs name it, when they all name one: links are
    # matched against the domain the containers live in. Otherwise -DomainDn, else the DNS name.
    $gpcDomains = @(foreach ($g in $gpcRecords) {
            $m = [regex]::Match([string](Get-AdfaConfigValue -Entry $g -Name 'DistinguishedName'), '(?i),\s*CN=Policies\s*,\s*CN=System\s*,\s*(DC=.*)$')
            if ($m.Success) { ConvertTo-AdfaGpLinkDomainDn -Dn $m.Groups[1].Value }
        })
    $gpcDomains = @($gpcDomains | Select-Object -Unique)
    if ($gpcDomains.Count -eq 1) { $thisDn = [string]$gpcDomains[0] }
    $wmiNames = @{}
    if ($wmiCause -eq '') {
        foreach ($w in @(@(Get-AdfaConfigValue -Entry $Wmi -Name 'Records') | Where-Object { $null -ne $_ })) {
            $wmiNames[([string](Get-AdfaConfigValue -Entry $w -Name 'Name')).ToUpperInvariant()] = [string](Get-AdfaConfigValue -Entry $w -Name 'msWMI-Name')
        }
    }
    # The SOMs of the other forest domains: a GPO can be linked from any of them. Domain names go in
    # the OtherDomainsNotRead column only, never in Detail.
    $crossCauses = @()
    $notRead = @()
    $otherSources = @()
    $otherDone = 0
    $forestList = @(@($ForestDomains) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim() })
    if ($forestList.Count -eq 0) { $crossCauses += "The forest's domain list was not read, so which other domains could link these GPOs is not known." }
    $otherDomains = @($forestList | Where-Object { $_ -ne $DomainName })
    $outOfScope = 0
    foreach ($fd in $otherDomains) {
        $match = @(@($OtherSom) | Where-Object { $null -ne $_ -and [string](Get-AdfaConfigValue -Entry $_ -Name 'Domain') -eq $fd })
        if ($match.Count -eq 0) { $outOfScope++; $notRead += $fd; continue }
        $otherRaw = Get-AdfaConfigValue -Entry $match[0] -Name 'Raw'
        $otherCause = Get-AdfaInventoryReadCause -Raw $otherRaw -What "the gPLink of another forest domain's head and OUs" -MaxObjects $max
        if ($otherCause -ne '') { $crossCauses += $otherCause; $notRead += $fd; continue }
        $otherDone++
        foreach ($s in @(@(Get-AdfaConfigValue -Entry $otherRaw -Name 'Records') | Where-Object { $null -ne $_ })) { $otherSources += [pscustomobject]@{ Record = $s; IsSite = $false; IsOther = $true } }
    }
    if ($outOfScope -gt 0) { $crossCauses += ("The domain head and OUs of {0} other forest domain(s) were not read: they are not in this run's scope (-AllDomains reads them)." -f $outOfScope) }
    $crossKnown = ($crossCauses.Count -eq 0)
    $counters = @{}
    $rows = @()
    $somCount = 0
    $somNoLink = 0
    $linkTotal = 0
    $unparsedTotal = 0
    $otherTotal = 0
    $sources = @()
    if ($somCause -eq '') { foreach ($s in @(@(Get-AdfaConfigValue -Entry $Som -Name 'Records') | Where-Object { $null -ne $_ })) { $sources += [pscustomobject]@{ Record = $s; IsSite = $false; IsOther = $false } } }
    if ($siteCause -eq '') { foreach ($s in @(@(Get-AdfaConfigValue -Entry $Site -Name 'Records') | Where-Object { $null -ne $_ })) { $sources += [pscustomobject]@{ Record = $s; IsSite = $true; IsOther = $false } } }
    $sources += $otherSources
    foreach ($src in $sources) {
        $entries = @(ConvertFrom-AdfaGpLink -Value ([string](Get-AdfaConfigValue -Entry $src.Record -Name 'gPLink')) -Config $Config)
        $parsed = @($entries | Where-Object { $_.Parsed })
        # This domain's GPO: its GUID AND the domain in its GPC DN, since the default GPOs share a GUID in every domain.
        $ours = @($parsed | Where-Object { [string]$_.DomainDn -eq $thisDn -and $guids.ContainsKey($_.Guid) })
        # A site is forest-wide, and another domain's SOM is that domain's: either is listed under this
        # domain only when it links a GPO of this domain.
        if (($src.IsSite -or $src.IsOther) -and $ours.Count -eq 0) { continue }
        $somClass = 'site'
        if (-not $src.IsSite) {
            $classes = @(@(Get-AdfaConfigValue -Entry $src.Record -Name 'objectClass') | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
            $somClass = ''
            if ($classes.Count -gt 0) { $somClass = [string]$classes[$classes.Count - 1] }
        }
        $unparsed = @($entries | Where-Object { -not $_.Parsed }).Count
        # Counted as linking only when it holds a link that was read: a gPLink that is blank, or holds
        # only entries that could not be parsed, links nothing that is known.
        if ($parsed.Count -gt 0) { $somCount++ } else { $somNoLink++ }
        if (-not $src.IsSite -and -not $src.IsOther) { $unparsedTotal += $unparsed; $otherTotal += ($parsed.Count - $ours.Count) }
        foreach ($e in $ours) {
            $linkTotal++
            if (-not $counters.ContainsKey($e.Guid)) { $counters[$e.Guid] = @{ Links = 0; Enabled = 0; Disabled = 0; Enforced = 0 } }
            $counters[$e.Guid]['Links']++
            if ($e.Disabled) { $counters[$e.Guid]['Disabled']++ } else { $counters[$e.Guid]['Enabled']++ }
            if ($e.Enforced) { $counters[$e.Guid]['Enforced']++ }
        }
        $somDetail = 'gPLink read; its entries are counted in the columns (options 0x1 disabled, 0x2 enforced). gPOptions is shown raw: the value that means block inheritance is not published. Inventory only, not graded.'
        if ($src.IsOther) { $somDetail = ("A site, domain or OU of another forest domain that links at least one GPO of this domain. {0}" -f $somDetail) }
        elseif ($parsed.Count -eq 0) { $somDetail = ("gPLink is present but holds no link that could be read, so this SOM links no known GPO. {0}" -f $somDetail) }
        $gpOptions = Get-AdfaConfigValue -Entry $src.Record -Name 'gPOptions'
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item ("GPO links on a SOM: {0}" -f $DomainName) -Status $script:Status.Info -Evidence $evidence `
            -Columns ([ordered]@{ Som = [string](Get-AdfaConfigValue -Entry $src.Record -Name 'DistinguishedName'); SomClass = $somClass; Links = [string]$parsed.Count
                LinksToThisDomain = [string]$ours.Count
                Disabled = [string]@($parsed | Where-Object { $_.Disabled }).Count; Enforced = [string]@($parsed | Where-Object { $_.Enforced }).Count
                Unparsed = [string]$unparsed; GpOptions = [string]$gpOptions }) `
            -Detail $somDetail
    }
    $crossText = ($crossCauses -join ' ')
    $unlinked = @()
    $noLinkFound = @()
    $linked = 0
    foreach ($g in $gpcRecords) {
        $guid = ([string](Get-AdfaConfigValue -Entry $g -Name 'Name')).ToUpperInvariant()
        $display = [string](Get-AdfaConfigValue -Entry $g -Name 'displayName')
        $flagsValue = Get-AdfaConfigValue -Entry $g -Name 'flags'
        $label = 'unknown'
        $flagNumber = ConvertTo-AdfaInventoryInteger -Value $flagsValue
        if ($null -ne $flagNumber) {
            foreach ($fl in @($GpoConfig['FlagLabels'])) { if ([int64](Get-AdfaConfigValue -Entry $fl -Name 'Value') -eq $flagNumber) { $label = [string](Get-AdfaConfigValue -Entry $fl -Name 'Label') } }
        }
        $wql = [string](Get-AdfaConfigValue -Entry $g -Name 'gPCWQLFilter')
        $wmiGuid = ''
        $wmiName = ''
        if (-not [string]::IsNullOrWhiteSpace($wql)) {
            $wmiGuid = ([regex]::Match($wql, [string]$Config['GuidPattern']).Value).ToUpperInvariant()
            if ($wmiGuid -eq '') { $wmiName = '(filter value not parsed)' }
            elseif ($wmiCause -ne '') { $wmiName = '(WMI filters not read)' }
            elseif ($wmiNames.ContainsKey($wmiGuid)) { $wmiName = [string]$wmiNames[$wmiGuid] }
            else { $wmiName = '(no WMI filter with this GUID found)' }
        }
        $columns = [ordered]@{ DisplayName = $display; Flags = [string]$flagsValue; FlagsLabel = $label; VersionNumber = [string](Get-AdfaConfigValue -Entry $g -Name 'versionNumber')
            WmiFilter = $wmiGuid; WmiFilterName = $wmiName; Links = ''; EnabledLinks = ''; DisabledLinks = ''; EnforcedLinks = '' }
        $detail = 'groupPolicyContainer read; its status flags, WMI filter and links are in the columns. Inventory only, not graded.'
        if ($linksKnown) {
            $c = @{ Links = 0; Enabled = 0; Disabled = 0; Enforced = 0 }
            if ($counters.ContainsKey($guid)) { $c = $counters[$guid] }
            if ([int]$c['Links'] -gt 0) {
                $columns.Links = [string]$c['Links']; $columns.EnabledLinks = [string]$c['Enabled']; $columns.DisabledLinks = [string]$c['Disabled']; $columns.EnforcedLinks = [string]$c['Enforced']
                $linked++
                if (-not $crossKnown) { $detail = ("{0} The link counts are a floor: the SOMs of every other forest domain were not read." -f $detail) }
            }
            elseif ($crossKnown) {
                $columns.Links = '0'; $columns.EnabledLinks = '0'; $columns.DisabledLinks = '0'; $columns.EnforcedLinks = '0'
                $unlinked += $display
            }
            else {
                # None found is not none: a SOM of a domain that was not read may link it.
                $noLinkFound += $display
                $detail = ("{0} No link to it was found in the SOMs read, but the SOMs of every other forest domain were not read, so whether it is linked is not known." -f $detail)
            }
        }
        else { $detail = ("{0} Its links could not be read, so whether it is linked is not known." -f $detail) }
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item ("GPO: {0}" -f $guid) -Status $script:Status.Info -Evidence $evidence -Columns $columns -Detail $detail
    }
    $sumColumns.Gpos = [string]$gpcRecords.Count
    $notes = ''
    if ($wmiCause -ne '') { $notes = (" {0} WMI filter names are not shown." -f $wmiCause) }
    if (-not $linksKnown) {
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $sumItem -Status $script:Status.NotAssessed -Evidence $evidence -Columns $sumColumns `
            -Detail ("{0} GPO(s) read. {1}{2} Which GPOs are linked is not known - none is called unlinked.{3}" -f $gpcRecords.Count, $somCause, $siteCause, $notes)
        return @($rows)
    }
    $sumColumns.Linked = [string]$linked
    $sumColumns.Soms = [string]$somCount
    $sumColumns.SomsWithNoLink = [string]$somNoLink
    $sumColumns.Links = [string]$linkTotal
    $sumColumns.UnparsedLinks = [string]$unparsedTotal
    $sumColumns.LinksToOtherGpos = [string]$otherTotal
    $sumColumns.OtherDomainsNotRead = (@($notRead) -join '; ')
    $readText = "this domain's head and OUs and the sites"
    if ($otherDone -gt 0) { $readText = ("{0}, and the domain head and OUs of {1} other forest domain(s)" -f $readText, $otherDone) }
    $somText = ("{0} site(s), domain or OU(s) with at least one link read" -f $somCount)
    if ($somNoLink -gt 0) { $somText = ("{0}; {1} more hold a gPLink with no link that could be read" -f $somText, $somNoLink) }
    if ($crossKnown) {
        $sumColumns.Unlinked = [string]$unlinked.Count
        $sumColumns.NoLinkFound = [string]$unlinked.Count
        $sumColumns.OtherDomainSoms = 'All read'
        $sumColumns.UnlinkedGpos = Get-AdfaC14NameList -Names $unlinked -Cap ([int]$Config['NameListCap'])
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $sumItem -Status $script:Status.Info -Evidence $evidence -Columns $sumColumns `
            -Detail ("{0} GPO(s), {1} linked and {2} with no link in any site, domain or OU of the forest ({3} read), from {4}. Counts in the columns; unlinked GPO names in UnlinkedGpos. Inventory only, not graded.{5}" -f $gpcRecords.Count, $linked, $unlinked.Count, $readText, $somText, $notes)
        return @($rows)
    }
    # Partial: the SOMs of some other forest domain were not read. A link found is a link; none found
    # is not a measured absence, so the summary is Not Assessed whenever a GPO has none found.
    $sumColumns.NoLinkFound = [string]$noLinkFound.Count
    $sumColumns.OtherDomainSoms = 'Not all read'
    $sumColumns.NoLinkFoundGpos = Get-AdfaC14NameList -Names $noLinkFound -Cap ([int]$Config['NameListCap'])
    $status = $script:Status.Info
    if ($noLinkFound.Count -gt 0) { $status = $script:Status.NotAssessed }
    $rows += New-AdfaC14Row -Area 'Inventory' -Scope $DomainName -Item $sumItem -Status $status -Evidence $evidence -Columns $sumColumns `
        -Detail ("{0} GPO(s), {1} with a link found and {2} with no link found in the SOMs read ({3}), from {4}. {5} A GPO can be linked from a site, domain or OU anywhere in the forest (Learn group-policy-management-console, read 2026-11-17), so none is called unlinked and the link counts are a floor. GPO names with no link found in NoLinkFoundGpos. Inventory only, not graded.{6}" -f $gpcRecords.Count, $linked, $noLinkFound.Count, $readText, $somText, $crossText, $notes)
    return @($rows)
}

function Get-AdfaGpoDirectoryInventory {
    <#
    .SYNOPSIS
        Gpo: per scoped domain, the groupPolicyContainer objects, the gPLink of the domain head and
        its OUs and the WMI filters; the sites once per run (INV-011). Directory reads only.
    .DESCRIPTION
        Every scoped domain is read first, so each domain's GPOs are matched against the SOMs of
        every other scoped domain too: a GPO can be linked from any domain of the forest. The
        domains of -ForestDomains outside the scope are not read; their absence is named in the
        rows and keeps "no link" from being stated.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$Domains = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ForestDomains = @(),
        [AllowEmptyString()][string]$RootDomain = '',
        [AllowNull()][AllowEmptyString()][string]$ForestError = '',
        [hashtable]$AdParams = @{},
        [Parameter(Mandatory)][hashtable]$Config,
        [Parameter(Mandatory)][hashtable]$GpoConfig
    )
    if (-not [string]::IsNullOrWhiteSpace($ForestError)) {
        return @(New-AdfaC14Row -Area 'Inventory' -Item 'GPO directory inventory: (forest unreadable)' -Status $script:Status.NotAssessed `
                -Detail ("The forest could not be read ({0}), so no domain was scoped and no GPO was read. This is not a clean result." -f $ForestError.Trim().TrimEnd('.')))
    }
    $max = [int]$Config['MaxObjects']
    $somProps = @($Config['SomProperties'])
    $root = Get-AdfaRootDseRaw -AdParams $AdParams
    $siteServer = $RootDomain
    if ([string]::IsNullOrWhiteSpace($siteServer)) { $siteServer = @($Domains)[0] }
    if ($root.Ok -and -not [string]::IsNullOrWhiteSpace($root.ConfigurationNamingContext) -and -not [string]::IsNullOrWhiteSpace($siteServer)) {
        $site = Get-AdfaInventoryDirectoryRaw -Server $siteServer -SearchBase ("CN=Sites,{0}" -f $root.ConfigurationNamingContext) -SearchScope 'Subtree' -LDAPFilter '(&(objectClass=site)(gPLink=*))' -Properties $somProps -MaxObjects $max -AdParams $AdParams
    }
    else { $site = New-AdfaInventoryFailedRead -ErrorText ("the configuration naming context could not be read from the rootDSE: {0}" -f $root.Error) -ErrorType $root.ErrorType }
    $reads = @()
    foreach ($d in @($Domains | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
        $dn = Get-AdfaInventoryDomainDn -DomainName $d -AdParams $AdParams
        $domainDn = ''
        if ($dn.Ok) {
            $domainDn = [string]$dn.Dn
            $gpc = Get-AdfaInventoryDirectoryRaw -Server $d -SearchBase ("CN=Policies,CN=System,{0}" -f $dn.Dn) -SearchScope 'OneLevel' -LDAPFilter '(objectClass=groupPolicyContainer)' -Properties @($Config['GpoContainerProperties']) -MaxObjects $max -AdParams $AdParams
            $som = Get-AdfaInventoryDirectoryRaw -Server $d -SearchBase $dn.Dn -SearchScope 'Subtree' -LDAPFilter '(gPLink=*)' -Properties $somProps -MaxObjects $max -AdParams $AdParams
            $wmi = Get-AdfaInventoryDirectoryRaw -Server $d -SearchBase ("CN=System,{0}" -f $dn.Dn) -SearchScope 'Subtree' -LDAPFilter '(objectClass=msWMI-Som)' -Properties @($Config['WmiFilterProperties']) -MaxObjects $max -AdParams $AdParams
        }
        else {
            $gpc = New-AdfaInventoryFailedRead -ErrorText ("the domain's distinguished name could not be read: {0}" -f $dn.Error) -ErrorType $dn.ErrorType
            $som = $gpc
            $wmi = $gpc
        }
        $reads += [pscustomobject]@{ Domain = $d; DomainDn = $domainDn; Gpc = $gpc; Som = $som; Wmi = $wmi }
    }
    $rows = @()
    foreach ($r in $reads) {
        $other = @($reads | Where-Object { $_.Domain -ne $r.Domain } | ForEach-Object { [pscustomobject]@{ Domain = $_.Domain; Raw = $_.Som } })
        $rows += @(Get-AdfaGpoDirectoryRows -DomainName $r.Domain -DomainDn $r.DomainDn -Gpc $r.Gpc -Som $r.Som -Site $site -Wmi $r.Wmi -ForestDomains $ForestDomains -OtherSom $other -Config $Config -GpoConfig $GpoConfig)
    }
    return @($rows)
}

# --- INV-012 -----------------------------------------------------------------------------------

function Get-AdfaEventInventoryRaw {
    <#
    .SYNOPSIS
        The event seam of the C15 inventory: one bounded Get-WinEvent read of one log on one DC.
        Never throws.
    .DESCRIPTION
        -FilterHashtable LogName, Level and StartTime, and -MaxEvents always passed: without it
        "The default is to return all the events in the logs" (Learn). Each event is reduced to its
        ID, level, provider and time as it arrives; no message is kept. A read that returned
        MaxEvents events is Truncated. "No events" and "no such log" are recognised by the config's
        patterns (not published by Microsoft; unmeasured against a real DC); any other error is kept
        and quoted, never read as zero events. An UnauthorizedAccessException, thrown or wrapped
        as an InnerException, is marked ErrorCode AccessDenied, so a refusal in another language
        is still told apart.
        "No events" is never taken from the filtered read alone: Get-WinEvent -FilterHashtable
        answers an account that may not read the log with NoMatchingEventsFound, the same answer as
        an empty window (measured on Windows PowerShell 5.1 by the review of this row, 2026-11-17;
        not published by Microsoft). So a filtered read that found nothing is followed by one
        unfiltered read of a single event (-LogName -MaxEvents 1), which does raise
        UnauthorizedAccessException for that account. Only when that read returns an event, or
        also finds none, is NoEvents set; a refusal is AccessDenied and any other error is kept.
    .OUTPUTS
        [pscustomobject] Ok, NoEvents, LogAbsent, Events, Truncated, Error, ErrorId, ErrorCode.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][string]$LogName,
        [Parameter(Mandatory)][datetime]$StartTime,
        [Parameter(Mandatory)][int[]]$Levels,
        [Parameter(Mandatory)][ValidateRange(1, 100000)][int]$MaxEvents,
        [pscredential]$Credential,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $out = [pscustomobject]@{ Ok = $false; NoEvents = $false; LogAbsent = $false; Events = @(); Truncated = $false; Error = ''; ErrorId = ''; ErrorCode = '' }
    $isDenied = {
        param($Exception)
        $ex = $Exception
        while ($null -ne $ex) {
            if ($ex -is [System.UnauthorizedAccessException]) { return $true }
            $ex = $ex.InnerException
        }
        return $false
    }
    $isNoEvents = { param([string]$Message, [string]$ErrorId) ($Message -match [string]$Config['EventNoEventsPattern'] -or $ErrorId -match [string]$Config['EventNoEventsPattern']) }
    $foundNone = $false
    try {
        $filter = @{ LogName = $LogName; Level = @($Levels); StartTime = $StartTime }
        $gwe = @{ ComputerName = $ComputerName; FilterHashtable = $filter; MaxEvents = $MaxEvents; ErrorAction = 'Stop' }
        if ($Credential) { $gwe.Credential = $Credential }
        $list = New-Object System.Collections.ArrayList
        Get-WinEvent @gwe | ForEach-Object {
            if ($null -ne $_) { [void]$list.Add([pscustomobject]@{ Id = [int](Get-AdfaConfigValue -Entry $_ -Name 'Id'); Level = (Get-AdfaConfigValue -Entry $_ -Name 'Level'); ProviderName = [string](Get-AdfaConfigValue -Entry $_ -Name 'ProviderName'); TimeCreated = (Get-AdfaConfigValue -Entry $_ -Name 'TimeCreated') }) }
        }
        $out.Events = @($list.ToArray())
        $out.Truncated = ($list.Count -ge $MaxEvents)
        if ($list.Count -eq 0) { $foundNone = $true } else { $out.Ok = $true }
    }
    catch {
        $message = [string]$_.Exception.Message
        $errorId = [string]$_.FullyQualifiedErrorId
        if (& $isNoEvents $message $errorId) { $foundNone = $true }
        elseif ($message -match [string]$Config['EventNoLogPattern'] -or $errorId -match [string]$Config['EventNoLogPattern']) { $out.LogAbsent = $true; $out.Error = $message }
        else {
            $out.Error = $message
            $out.ErrorId = $errorId
            if (& $isDenied $_.Exception) { $out.ErrorCode = 'AccessDenied' }
        }
    }
    if ($foundNone) {
        # The filtered read cannot tell an empty window from a log the account may not read: one
        # unfiltered single-event read can.
        try {
            $probe = @{ ComputerName = $ComputerName; LogName = $LogName; MaxEvents = 1; ErrorAction = 'Stop' }
            if ($Credential) { $probe.Credential = $Credential }
            $null = @(Get-WinEvent @probe)
            $out.Ok = $true
            $out.NoEvents = $true
        }
        catch {
            $message = [string]$_.Exception.Message
            $errorId = [string]$_.FullyQualifiedErrorId
            if (& $isDenied $_.Exception) {
                $out.ErrorCode = 'AccessDenied'
                $out.Error = $message
                $out.ErrorId = $errorId
            }
            elseif (& $isNoEvents $message $errorId) { $out.Ok = $true; $out.NoEvents = $true }
            else {
                $out.Error = ("the filtered read found no event, and a one-event read to confirm the log can be read failed: {0}" -f $message)
                $out.ErrorId = $errorId
            }
        }
    }
    return $out
}

function Get-AdfaEventInventoryRows {
    <#
    .SYNOPSIS
        Pure: "Event log: <log> on <dc>" and, per event ID, "Event group: <log> <id> on <dc>" (level,
        provider, count, first and last), worst level first, at most EventGroupCap groups.
    .DESCRIPTION
        Inventory only: no event is graded. A count read at MaxEvents, or over a log that does not
        reach back across the window, is a floor and says so. None found is Info 0 only over a log
        that covers the window; otherwise Not Assessed. A log that does not exist is Info "log
        absent" (the repo has no Not Applicable status). A refusal, an unreachable DC and any other
        error are Not Assessed, each with its own cause.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [AllowEmptyString()][string]$Scope = '',
        [Parameter(Mandatory)][string]$LogName,
        [AllowNull()]$Raw,
        [AllowNull()]$Coverage,
        [AllowNull()][AllowEmptyString()][string]$Unreachable = '',
        [int]$LookbackDays = 14,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $cap = [int]$Config['EventGroupCap']
    $levelNames = $Config['EventLevelNames']
    $item = ("Event log: {0} on {1}" -f $LogName, $ComputerName)
    $evidence = ("Get-WinEvent -ComputerName <dc> -FilterHashtable LogName, Level 1, 2, 3 (Critical, Error, Warning), StartTime {0} days back (-EventLookbackDays), -MaxEvents {1} (a tool default: without it Get-WinEvent returns every event); when that finds nothing, one -LogName -MaxEvents 1 read confirms the log can be read, since the filtered read answers a refusal as no events. Grouped by event ID, at most {2} groups listed (EventGroupCap, a tool default). Learn get-winevent, read 2026-11-17. Inventory only (catalogue INV-012): no event is graded." -f $LookbackDays, [int]$Config['EventMaxEvents'], $cap)
    $columns = [ordered]@{ Log = $LogName; Events = ''; DistinctIds = ''; Critical = ''; Error = ''; Warning = ''; Truncated = ''; Coverage = '' }
    $na = { param([string]$Why) @(New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -Detail $Why) }
    if (-not [string]::IsNullOrWhiteSpace($Unreachable)) { return (& $na ("{0} The {1} log was not read." -f $Unreachable.Trim(), $LogName)) }
    if ($null -eq $Raw) { return (& $na ("The {0} log was not read." -f $LogName)) }
    if ([bool](Get-AdfaConfigValue -Entry $Raw -Name 'LogAbsent')) {
        return @(New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
                -Detail ("log absent: this DC has no {0} log (the DNS Server log exists only on DNS servers, the File Replication Service log only where FRS runs), so there was nothing to read. Not applicable, not a fault." -f $LogName))
    }
    if (-not [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Ok')) {
        $err = ([string](Get-AdfaConfigValue -Entry $Raw -Name 'Error')).Trim()
        if ((Get-AdfaRemoteReadErrorClass -Message $err -ErrorCode ([string](Get-AdfaConfigValue -Entry $Raw -Name 'ErrorCode'))) -eq 'AccessDenied') {
            return (& $na ("Access denied: the account running the assessment could not read the {0} log of this DC ({1}). Members of Event Log Readers (S-1-5-32-573) can read event logs; the log's own permissions decide." -f $LogName, $err.TrimEnd('.')))
        }
        return (& $na ("Read failed: the {0} log of this DC could not be read: {1}. Its events are not known - not zero." -f $LogName, $err.TrimEnd('.')))
    }
    $coverageState = ''
    if ($null -ne $Coverage) { $coverageState = [string](Get-AdfaConfigValue -Entry $Coverage -Name 'Coverage') }
    $columns.Coverage = $coverageState
    $covered = ($coverageState -eq 'Covered')
    $events = @(@(Get-AdfaConfigValue -Entry $Raw -Name 'Events') | Where-Object { $null -ne $_ })
    $truncated = [bool](Get-AdfaConfigValue -Entry $Raw -Name 'Truncated')
    if ($truncated) { $columns.Truncated = 'Yes' } else { $columns.Truncated = 'No' }
    if ($events.Count -eq 0) {
        if (-not $covered) {
            $state = $coverageState
            if ($state -eq '') { $state = 'not measured' }
            return (& $na ("No event at levels Critical, Error and Warning found, but the log's reach back over the {0}-day window is {1}, so none found is not a measurement of the window." -f $LookbackDays, $state))
        }
        $columns.Events = '0'; $columns.DistinctIds = '0'; $columns.Critical = '0'; $columns.Error = '0'; $columns.Warning = '0'
        return @(New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
                -Detail ("0 events at levels Critical, Error and Warning in the last {0} days; the log reaches back over the whole window. Inventory only, not graded." -f $LookbackDays))
    }
    $levelCount = @{ 1 = 0; 2 = 0; 3 = 0 }
    foreach ($e in $events) { $lv = 0; if ([int]::TryParse([string]$e.Level, [ref]$lv) -and $levelCount.ContainsKey($lv)) { $levelCount[$lv]++ } }
    $groups = @()
    foreach ($g in @($events | Group-Object -Property Id)) {
        $members = @($g.Group)
        $worst = 99
        foreach ($m in $members) { $lv = 99; if ([int]::TryParse([string]$m.Level, [ref]$lv) -and $lv -lt $worst) { $worst = $lv } }
        $times = @($members | ForEach-Object { $_.TimeCreated } | Where-Object { $_ -is [datetime] } | Sort-Object)
        $groups += [pscustomobject]@{ Id = [int]$g.Name; Worst = $worst; Count = $members.Count; Provider = [string]$members[0].ProviderName; First = $(if ($times.Count -gt 0) { $times[0] } else { $null }); Last = $(if ($times.Count -gt 0) { $times[$times.Count - 1] } else { $null }) }
    }
    $groups = @($groups | Sort-Object -Property @{ Expression = 'Worst'; Ascending = $true }, @{ Expression = 'Count'; Descending = $true }, @{ Expression = 'Id'; Ascending = $true })
    $shown = @($groups | Select-Object -First $cap)
    $omitted = $groups.Count - $shown.Count
    $columns.Events = [string]$events.Count
    $columns.DistinctIds = [string]$groups.Count
    $columns.Critical = [string]$levelCount[1]; $columns.Error = [string]$levelCount[2]; $columns.Warning = [string]$levelCount[3]
    $detail = ("{0} event(s) at levels Critical, Error and Warning in the last {1} days, {2} distinct event ID(s); {3} listed as Event group rows" -f $events.Count, $LookbackDays, $groups.Count, $shown.Count)
    if ($omitted -gt 0) { $detail = ("{0}, and {1} more not listed (EventGroupCap {2}, a tool default)" -f $detail, $omitted, $cap) }
    $detail = ("{0}." -f $detail)
    if ($truncated -or -not $covered) {
        $why = @()
        if ($truncated) { $why += ("the read stopped at MaxEvents {0}" -f [int]$Config['EventMaxEvents']) }
        if (-not $covered) { $c = $coverageState; if ($c -eq '') { $c = 'not measured' }; $why += ("the log's reach back over the window is {0}" -f $c) }
        $detail = ("{0} The count is a floor - at least {1} - because {2}." -f $detail, $events.Count, ($why -join ' and '))
    }
    $rows = @(New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns -Detail ("{0} Inventory only, not graded." -f $detail))
    # A read cut at MaxEvents (Get-WinEvent returns the newest first) or a log that does not reach
    # back leaves older events out: each group's Count is then a floor and First may be later than
    # the real first occurrence, and every group row says so.
    $partial = ($truncated -or -not $covered)
    $groupDetail = 'Occurrences of this event ID in the window; level, provider, count, first and last in the columns. Inventory only, not graded.'
    if ($partial) {
        $groupDetail = ("Occurrences of this event ID found in the window, from a partial read ({0}): Count is a floor - at least this many - and First is the earliest event read, not necessarily the first in the window. Level, provider, count, first and last in the columns. Inventory only, not graded." -f ($why -join ' and '))
    }
    foreach ($g in $shown) {
        $levelName = [string]$g.Worst
        if ($null -ne $levelNames -and $levelNames.ContainsKey([string]$g.Worst)) { $levelName = [string]$levelNames[[string]$g.Worst] }
        $first = ''
        $last = ''
        if ($g.First -is [datetime]) { $first = $g.First.ToString('yyyy-MM-dd HH:mm', $inv) }
        if ($g.Last -is [datetime]) { $last = $g.Last.ToString('yyyy-MM-dd HH:mm', $inv) }
        $countText = [string]$g.Count
        $partialText = 'No'
        if ($partial) { $countText = ("at least {0}" -f $g.Count); $partialText = 'Yes' }
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item ("Event group: {0} {1} on {2}" -f $LogName, $g.Id, $ComputerName) -Status $script:Status.Info -Evidence $evidence `
            -Columns ([ordered]@{ Log = $LogName; EventId = [string]$g.Id; Level = $levelName; Provider = $g.Provider; Count = $countText; First = $first; Last = $last; PartialRead = $partialText }) `
            -Detail $groupDetail
    }
    return @($rows)
}

function Get-AdfaEventInventory {
    <#
    .SYNOPSIS
        DsEvents: per DC of every scoped domain, each configured log read once by level, bounded by
        -EventLookbackDays and EventMaxEvents (INV-012), with a population row for each scoped domain
        no DC row covers.
    .DESCRIPTION
        A DC the reachability probe classified unreachable, or whose RPC (135) does not answer the
        shared probe, is not read; every log gets a Not Assessed row saying so. The log's coverage of
        the window (Get-AdfaEventLogCoverageForLog) is measured after a read that worked.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @(),
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        [int]$LookbackDays = 14,
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope ([string]$gap.Domain) -Item ("Events (population): {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No event log of its DCs was read.')
    }
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        $rows += New-AdfaC14Row -Area 'Inventory' -Item 'Events (population): (no domain controller)' -Status $script:Status.NotAssessed `
            -Detail ("No domain controllers were enumerated, so no event log was read.{0} This is not a clean result." -f $why)
        return @($rows)
    }
    $start = (Get-Date).AddDays(-1 * $LookbackDays)
    $rpcPort = [int]$Config['RpcPort']
    $logs = @($Config['EventLogs'])
    $levels = @($Config['EventLevels'] | ForEach-Object { [int]$_ })
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-AdfaC14Row -Area 'Inventory' -Scope $scope -Item 'Event log: (all) on (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and no event log was read.'
            continue
        }
        $unreachable = Get-AdfaDcReachCause -HostName $dc
        if ([string]::IsNullOrWhiteSpace($unreachable) -and -not (Get-AdfaDcProbeGate -ComputerName $dc -Ports @($rpcPort) -TimeoutMs $PortTimeoutMs).Open[$rpcPort]) {
            $unreachable = ("Unreachable: RPC ({0}) did not answer within {1} ms, so no event log was read remotely." -f $rpcPort, $PortTimeoutMs)
        }
        foreach ($log in $logs) {
            if (-not [string]::IsNullOrWhiteSpace($unreachable)) {
                $rows += @(Get-AdfaEventInventoryRows -ComputerName $dc -Scope $scope -LogName $log -Raw $null -Coverage $null -Unreachable $unreachable -LookbackDays $LookbackDays -Config $Config)
                continue
            }
            $raw = Get-AdfaEventInventoryRaw -ComputerName $dc -LogName $log -StartTime $start -Levels $levels -MaxEvents ([int]$Config['EventMaxEvents']) -Credential $Credential -Config $Config
            $coverage = $null
            if ([bool]$raw.Ok) { $coverage = Get-AdfaEventLogCoverageForLog -ComputerName $dc -LogName $log -Credential $Credential -WindowStart $start }
            $rows += @(Get-AdfaEventInventoryRows -ComputerName $dc -Scope $scope -LogName $log -Raw $raw -Coverage $coverage -LookbackDays $LookbackDays -Config $Config)
        }
    }
    return @($rows)
}

# --- INV-015 -----------------------------------------------------------------------------------

function Get-AdfaDcW32TimeRaw {
    <#
    .SYNOPSIS
        The registry seam of INV-015: Type, NtpServer and AnnounceFlags of one DC, in one bounded
        CIM session, with the two StdRegProv Get methods this script already uses. Never throws.
    .DESCRIPTION
        GetStringValue for a String value, GetDWORDValue for a Dword value, one call per value, no
        retry and no other method; each answer is kept as the provider gave it (a value not set, a
        refusal and a wrong type are all answers). Ok is $false only when the session could not be
        opened or no value got an answer, which lets the transport loop try the other protocol. The
        session is always closed, with -WhatIf and -Confirm forced off (see Get-AdfaDcDiskRaw).
    .OUTPUTS
        [pscustomobject] Ok, Protocol, Error, ErrorCode, Values (Id, Key, ValueName, Kind, Answered,
        ReturnValue, Value, Method, Error, ErrorCode).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [ValidateSet('Wsman', 'Dcom')][string]$Protocol = 'Wsman',
        [pscredential]$Credential,
        [int]$OperationTimeoutSec = 90,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$Values
    )
    $out = [pscustomobject]@{ Ok = $false; Protocol = $Protocol; Error = ''; ErrorCode = ''; Values = @() }
    $session = $null
    try {
        $sessionArgs = @{ ComputerName = $ComputerName; OperationTimeoutSec = [uint32]$OperationTimeoutSec; ErrorAction = 'Stop' }
        if ($Protocol -eq 'Dcom') { $sessionArgs.SessionOption = New-CimSessionOption -Protocol Dcom }
        if ($Credential) { $sessionArgs.Credential = $Credential }
        $session = New-CimSession @sessionArgs
        $answered = $false
        $firstError = ''
        $firstCode = ''
        $entries = New-Object System.Collections.ArrayList
        foreach ($definition in @($Values)) {
            if ($null -eq $definition) { continue }
            $key = [string](Get-AdfaConfigValue -Entry $definition -Name 'Key')
            $valueName = [string](Get-AdfaConfigValue -Entry $definition -Name 'ValueName')
            $kind = [string](Get-AdfaConfigValue -Entry $definition -Name 'Kind')
            if ($kind -eq 'Dword') { $read = Get-AdfaStdRegDwordValue -CimSession $session -Key $key -ValueName $valueName -OperationTimeoutSec $OperationTimeoutSec }
            else { $read = Get-AdfaStdRegStringValue -CimSession $session -Key $key -ValueName $valueName -OperationTimeoutSec $OperationTimeoutSec }
            if ($read.Answered) { $answered = $true }
            elseif ($firstError -eq '') { $firstError = [string]$read.Error; $firstCode = [string]$read.ErrorCode }
            [void]$entries.Add([pscustomobject]@{
                    Id = [string](Get-AdfaConfigValue -Entry $definition -Name 'Id'); Key = $key; ValueName = $valueName; Kind = $kind
                    Answered = [bool]$read.Answered; ReturnValue = $read.ReturnValue; Value = $read.Value
                    Method = [string]$read.Method; Error = [string]$read.Error; ErrorCode = [string]$read.ErrorCode
                })
        }
        $out.Values = $entries.ToArray()
        if ($answered) { $out.Ok = $true }
        else {
            $out.Error = $firstError
            $out.ErrorCode = $firstCode
            if ($out.Error -eq '') { $out.Error = 'No registry value got an answer from the DC.' }
        }
    }
    catch {
        $out.Error = [string]$_.Exception.Message
        $nativeCode = $_.Exception.PSObject.Properties['NativeErrorCode']
        if ($null -ne $nativeCode -and $null -ne $nativeCode.Value) { $out.ErrorCode = [string]$nativeCode.Value }
    }
    finally {
        if ($null -ne $session) {
            try { Remove-CimSession -CimSession $session -WhatIf:$false -Confirm:$false -ErrorAction SilentlyContinue } catch { }
        }
    }
    return $out
}

function Get-AdfaW32TimeConfigRow {
    <#
    .SYNOPSIS
        Pure: "W32Time configuration: <dc>" - Type, NtpServer and AnnounceFlags from the service
        registry, in columns, never graded (INV-015, reference N21).
    .DESCRIPTION
        A value not set (StdRegProv 1 or 2, measured, not published) is "(not set)"; NtpServer not
        set is the documented default on domain members. Not Assessed when the DC was unreachable,
        access was denied, the read failed, or any value could not be read (refused, of another
        type, failed, or not answered) - each named. The policy area that overrides these values is
        not read, and the row says so.
    .OUTPUTS
        [pscustomobject]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [AllowEmptyString()][string]$Scope = '',
        [AllowNull()]$Read,
        [AllowNull()][AllowEmptyString()][string]$Unreachable = '',
        [Parameter(Mandatory)][hashtable]$Config
    )
    $item = ("W32Time configuration: {0}" -f $ComputerName)
    $evidence = 'StdRegProv GetStringValue (Type and NtpServer under SYSTEM\CurrentControlSet\Services\W32Time\Parameters) and GetDWORDValue (AnnounceFlags under ...\W32Time\Config) over one CIM session, WinRM then DCOM; needs local Administrators on the DC. Learn windows-time-service-tools-and-settings and configure-authoritative-time-server, read 2026-11-17. Inventory only (catalogue INV-015): no expected value is graded.'
    $policy = 'These are the service registry values. A Group Policy value under HKLM\SOFTWARE\Policies\Microsoft\W32Time overrides them (Learn: with the NTP client policy applied, W32Time does not use the NtpServer registry value); the policy area is not read, so this may not be the effective configuration.'
    $columns = [ordered]@{ Type = ''; NtpServer = ''; AnnounceFlags = ''; Transport = '' }
    $na = { param([string]$Why) New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.NotAssessed -Evidence $evidence -Columns $columns -Detail $Why }
    if (-not [string]::IsNullOrWhiteSpace($Unreachable)) { return (& $na ("{0} No W32Time value was read." -f $Unreachable.Trim())) }
    if ($null -eq $Read) { return (& $na 'No W32Time value was read.') }
    $raw = Get-AdfaConfigValue -Entry $Read -Name 'Raw'
    $err = ''
    if ($null -ne $raw) { $err = ([string](Get-AdfaConfigValue -Entry $raw -Name 'Error')).Trim().TrimEnd('.'); $columns.Transport = [string](Get-AdfaConfigValue -Entry $raw -Name 'Protocol') }
    if ([bool](Get-AdfaConfigValue -Entry $Read -Name 'Denied')) {
        return (& $na ("Access denied: the account running the assessment could not read the registry of this DC ({0}). Local Administrators rights on the DC are needed for this read." -f $err))
    }
    if ($null -eq $raw -or -not [bool](Get-AdfaConfigValue -Entry $raw -Name 'Ok')) {
        return (& $na ("Read failed: a port answered, but no W32Time value could be read: {0}." -f $err))
    }
    $values = @(@(Get-AdfaConfigValue -Entry $raw -Name 'Values') | Where-Object { $null -ne $_ })
    $problems = @()
    foreach ($definition in @($Config['W32TimeValues'])) {
        $id = [string](Get-AdfaConfigValue -Entry $definition -Name 'Id')
        $entry = @($values | Where-Object { [string](Get-AdfaConfigValue -Entry $_ -Name 'Id') -eq $id })
        if ($entry.Count -eq 0) { $problems += ("{0} was not read (no answer for it)" -f $id); continue }
        $e = $entry[0]
        $class = Get-AdfaStdRegReturnClass -ReturnValue (Get-AdfaConfigValue -Entry $e -Name 'ReturnValue') -ErrorText ([string](Get-AdfaConfigValue -Entry $e -Name 'Error')) -ErrorCode ([string](Get-AdfaConfigValue -Entry $e -Name 'ErrorCode'))
        switch ($class.Class) {
            'Success' {
                $v = Get-AdfaConfigValue -Entry $e -Name 'Value'
                if ($null -eq $v -or [string]::IsNullOrWhiteSpace([string]$v)) { $columns[$id] = '(empty)' } else { $columns[$id] = [string]$v }
            }
            'ValueNotSet' { $columns[$id] = '(not set)' }
            'KeyAbsent' { $columns[$id] = '(not set)' }
            'AccessDenied' { $problems += ("{0}: access denied" -f $id) }
            'TypeMismatch' { $problems += ("{0}: the value exists with a type the read does not take (the registry type of Type and NtpServer is not published)" -f $id) }
            default {
                $why = ([string](Get-AdfaConfigValue -Entry $e -Name 'Error')).Trim().TrimEnd('.')
                if ($why -eq '') { $why = ("return code {0}" -f [string]$class.Code) }
                $problems += ("{0}: read failed ({1})" -f $id, $why)
            }
        }
    }
    if ($problems.Count -gt 0) {
        return (& $na ("Not every W32Time value could be read: {0}. {1}" -f ($problems -join '; '), $policy))
    }
    return New-AdfaC14Row -Area 'Inventory' -Scope $Scope -Item $item -Status $script:Status.Info -Evidence $evidence -Columns $columns `
        -Detail ("Type, NtpServer and AnnounceFlags read; values in their columns. NtpServer not set is the documented default on domain members. {0} Inventory only, not graded." -f $policy)
}

function Get-AdfaW32TimeInventory {
    <#
    .SYNOPSIS
        TimeHierarchy: the W32Time configuration of every DC of every scoped domain, through the
        shared CIM transport loop (INV-015), with a population row for each scoped domain no DC row
        covers. Read-only: no w32tm verb is run here.
    .OUTPUTS
        [pscustomobject[]]
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param(
        [AllowNull()][AllowEmptyCollection()]$DomainControllers = @(),
        [AllowNull()][AllowEmptyCollection()]$InventoryFailures = @(),
        [AllowNull()][AllowEmptyCollection()][string[]]$ScopedDomains = @(),
        [AllowNull()][AllowEmptyString()][string]$EnumerationError = '',
        [pscredential]$Credential,
        [int]$PortTimeoutMs = 1200,
        [int]$OperationTimeoutSec = 90,
        [Parameter(Mandatory)][hashtable]$Config
    )
    $rows = @()
    $targets = @($DomainControllers | Where-Object { $null -ne $_ })
    foreach ($gap in @(Get-AdfaDcPopulationGap -Targets $targets -InventoryFailures $InventoryFailures -ScopedDomains $ScopedDomains)) {
        $rows += New-AdfaC14Row -Area 'Inventory' -Scope ([string]$gap.Domain) -Item ("W32Time configuration (population): {0}" -f [string]$gap.Domain) -Status $script:Status.NotAssessed `
            -Detail (Get-AdfaDcPopulationGapText -Gap $gap -NothingRead 'No W32Time value of its DCs was read.')
    }
    if ($targets.Count -eq 0) {
        $why = ''
        if (-not [string]::IsNullOrWhiteSpace($EnumerationError)) { $why = (" Domain controller enumeration failed: {0}." -f $EnumerationError.Trim().TrimEnd('.')) }
        $rows += New-AdfaC14Row -Area 'Inventory' -Item 'W32Time configuration (population): (no domain controller)' -Status $script:Status.NotAssessed `
            -Detail ("No domain controllers were enumerated, so no W32Time value was read.{0} This is not a clean result." -f $why)
        return @($rows)
    }
    $wsmanPort = [int]$Config['WsmanPort']
    $rpcPort = [int]$Config['RpcPort']
    foreach ($target in $targets) {
        $named = ConvertTo-AdfaDcTarget -Target $target
        $dc = [string]$named.HostName
        $scope = [string]$named.Scope
        if ([string]::IsNullOrWhiteSpace($dc)) {
            $rows += New-AdfaC14Row -Area 'Inventory' -Scope $scope -Item 'W32Time configuration: (unnamed)' -Status $script:Status.NotAssessed `
                -Detail 'The inventory holds a domain controller with no host name, so there was nothing to connect to and no value was read.'
            continue
        }
        $reach = Get-AdfaDcReachCause -HostName $dc
        if (-not [string]::IsNullOrWhiteSpace($reach)) {
            $rows += Get-AdfaW32TimeConfigRow -ComputerName $dc -Scope $scope -Read $null -Unreachable $reach -Config $Config
            continue
        }
        $w32Gate = Get-AdfaDcProbeGate -ComputerName $dc -Ports @($wsmanPort, $rpcPort) -TimeoutMs $PortTimeoutMs
        $wsman = [bool]$w32Gate.Open[$wsmanPort]
        $rpc = [bool]$w32Gate.Open[$rpcPort]
        if (-not $wsman -and -not $rpc) {
            $rows += Get-AdfaW32TimeConfigRow -ComputerName $dc -Scope $scope -Read $null -Config $Config `
                -Unreachable ("Unreachable: neither WinRM ({0}) nor RPC ({1}) answered within {2} ms, so no read was attempted." -f $wsmanPort, $rpcPort, $PortTimeoutMs)
            continue
        }
        $protocols = @()
        if ($wsman) { $protocols += 'Wsman' }
        if ($rpc) { $protocols += 'Dcom' }
        $readArguments = @{ OperationTimeoutSec = $OperationTimeoutSec; Values = $Config['W32TimeValues'] }
        if ($Credential) { $readArguments.Credential = $Credential }
        $read = Invoke-AdfaDcRemoteRead -ComputerName $dc -Protocols $protocols -ReadCommand 'Get-AdfaDcW32TimeRaw' -ReadArguments $readArguments
        $rows += Get-AdfaW32TimeConfigRow -ComputerName $dc -Scope $scope -Read $read -Config $Config
    }
    return @($rows)
}

# ===========================================================================
# region Best-practice recommendations
# ===========================================================================

# Table-driven mapping from a finding's section/item/detail text to a best-practice fix.
# First match wins; specific patterns must precede general ones. An entry may carry a
# Section regex - it is then considered only for findings from matching sections. This
# matters because detail text leaks across domains: a broken trust's reason reads
# "secure channel verification FAILED", which must route to the TRUST remediation, not
# the machine-account one. Kept as data so adding guidance never touches collector logic.
$script:RecommendationMap = @(
    # --- Section-scoped entries first: they cannot be hijacked by detail wording ---
    @{ Section = '(?i)trust'; Match = '(?i)sid filtering'
       Text  = 'Re-enable SID filtering on the trust: "netdom trust <local> /domain:<partner> /quarantine:Yes" (external trusts). Only relax for a documented, time-boxed migration.' }
    @{ Section = '(?i)trust'; Match = '(?i)rc4'
       Text  = 'Enable AES on the trust ("ksetup /setenctypeattr <partner> AES256-CTS-HMAC-SHA1-96 AES128-CTS-HMAC-SHA1-96" or the trust dialog''s AES checkbox), then reset the trust password so new AES keys are derived.' }
    @{ Section = '(?i)trust'; Match = '.'
       Text  = 'Confirm the network path and DNS name resolution (conditional forwarders / stub zones) to the partner domain in BOTH directions, then reset the trust secure channel: "netdom trust <local> /domain:<partner> /reset". Re-verify with "nltest /sc_verify:<partner>" from the local side and on a partner DC. After a ransomware incident, reset trust passwords as part of credential hygiene.' }
    @{ Section = '(?i)secure channel|machine password'; Match = '.'
       Text  = 'Reset the secure channel against a known-healthy DC. Member/workstation: "Reset-ComputerMachinePassword -Server <healthyDC>" or "nltest /sc_reset:<domain>". For a DC: stop the KDC service, run "netdom resetpwd /server:<healthyDC> /userd:<domain>\<admin> /passwordd:*", restart. Never disjoin/rejoin a domain controller.' }
    # --- Section-scoped: DC system. Only the lifecycle Fail carries advice; the patch-level
    #     rows are inventory. The ESU wording is Microsoft's own description of the programme:
    #     https://learn.microsoft.com/lifecycle/faq/extended-security-updates (read 2026-11-13).
    @{ Section = '(?i)^dc system'; Match = '(?i)past extended support'
       Text  = 'Upgrade or replace this domain controller so that it runs a supported Windows Server release. Microsoft describes Extended Security Updates as a last-resort paid option that is a temporary bridge and does not extend the product lifecycle; where one is published for this release, confirm separately whether this DC is enrolled, because this report does not assess that.' }
    # --- Section-scoped: DC disk space (PORT-PLAN C2). One entry answers every Warning and Fail
    #     row of the section, and it sits ahead of the unscoped entries because such a row names
    #     SYSVOL, a host and - under an override - a file path, any of which an unscoped entry
    #     ('sysvol|dfsr', 'replication', 'backup', 'stale') would otherwise answer with the fix
    #     for a different fault. A full disk is not cured by a D4 restore. A test pins it.
    #     The steps are Microsoft's own for a database volume short of space, in their order:
    #       https://learn.microsoft.com/troubleshoot/windows-server/active-directory/replication-event-id-2108-1084
    #     The 110 % figure is from the AD DS capacity planning page:
    #       https://learn.microsoft.com/windows-server/administration/performance-tuning/role/active-directory-server/capacity-planning-for-active-directory-domain-services
    #     Read: 2026-11-13 (both). Nothing is advised for a SYSVOL-only volume beyond freeing or
    #     extending it, because nothing more specific was found published.
    @{ Section = '(?i)^dc disk space'; Match = '.'
       Text  = 'Free space on the named volume, or extend it. For a volume that holds the directory database or its log files, Microsoft''s steps are, in this order: 1. Move unrelated files to another volume. 2. Perform a system state backup, which reduces the size of the transaction log files. 3. Perform an offline defragmentation of the database; Microsoft''s sizing guidance asks for free space of 110 % of the ntds.dit size to allow it, which this report does not measure. Also confirm that NTFS compression is not turned on for the drives that hold ntds.dit and the log files. The thresholds this finding was judged against are this tool''s defaults or your own override, not Microsoft values.' }
    # --- Section-scoped: DC hardening (PORT-PLAN C3). One entry per row family, each anchored on
    #     the family name the tool itself writes at the start of the Item ("<family>: <dc>"), so
    #     nothing after the colon - a host name, an error text, an override file path cited as
    #     the expectation source - takes part in choosing the advice. The last entry answers
    #     every other row of the section with no advice at all, so none of that free text can
    #     reach an unscoped entry further down ('ldap signing', 'smbv1', 'spooler', 'backup',
    #     'replication', 'sysvol' ...). Tests pin each family to its entry.
    #     The two settings whose expectation a file can move - channel binding (1 or 2) and the
    #     LAN Manager level (3, 4 or 5) - do not tell the reader to set one fixed value: the
    #     text is chosen by family and never sees the merged expectation, so it points at the
    #     expected minimum the finding itself names and gives Microsoft's baseline value as
    #     that. A fixed "set it to 5" beside "below the expected minimum of 3" would be two
    #     targets in one row. The other four have one possible expectation each.
    #     Every remediation is Microsoft's own, with the compatibility warning its page gives:
    #       LDAP signing, enforcement - https://learn.microsoft.com/windows-server/identity/manage-ldap-signing-group-policy
    #                                   https://learn.microsoft.com/windows-server/identity/ad-ds/ldap-signing
    #       Channel binding           - https://learn.microsoft.com/windows-server/identity/ad-ds/ldap-channel-binding
    #       SMB signing               - https://learn.microsoft.com/windows-server/storage/file-server/smb-signing
    #       LAN Manager level         - https://learn.microsoft.com/troubleshoot/windows-server/windows-security/audit-domain-controller-ntlmv1
    #       Print Spooler             - https://learn.microsoft.com/defender-for-identity/security-posture-assessments/identity-infrastructure
    #       SMBv1                     - https://learn.microsoft.com/windows-server/storage/file-server/troubleshoot/detect-enable-and-disable-smbv1-v2-v3
    #     Read: 2026-11-13 (all).
    @{ Section = '(?i)^dc hardening'; Match = '(?i)^DC Hardening :: LDAP server signing enforcement: '
       Text  = 'On Windows Server 2025, leave the Group Policy setting "Domain controller: LDAP server signing requirements enforcement" Enabled or Not Configured: Microsoft documents both as requiring LDAP signing whatever the older signing requirements policy says. Where it was set to Disabled to keep unsigned clients working, find those clients with Directory Service events 2887 and 2889, move them to signed binds, then enable it again. Clients that do not support LDAP signing can no longer query the DC once it is required.' }
    @{ Section = '(?i)^dc hardening'; Match = '(?i)^DC Hardening :: LDAP server signing: '
       Text  = 'Require LDAP signing with the Group Policy setting "Domain controller: LDAP server signing requirements" = Require signing. Microsoft''s migration path is to do it in this order: monitor Directory Service events 2887 and 2889 to identify clients that still bind unsigned, configure those clients to request signing, then require it - clients that do not support LDAP signing can no longer run LDAP queries against the DC afterwards. LDAP signing applies to SASL binds that are not over TLS; it does not protect simple binds.' }
    @{ Section = '(?i)^dc hardening'; Match = '(?i)^DC Hardening :: LDAP channel binding: '
       Text  = 'Raise the Group Policy setting "Domain controller: LDAP server channel binding token requirements" to at least the expected minimum this finding names. The value Microsoft''s Windows Server 2025 security baseline gives for a domain controller is Always, and Microsoft''s path to it is to audit first: with the setting at When supported, use Directory Service events 3039, 3074 and 3075 to identify the clients that fail or omit channel binding; fix or update those, then move to Always, which rejects every client that does not send a valid token. Channel binding applies to LDAP over TLS with SASL authentication only.' }
    @{ Section = '(?i)^dc hardening'; Match = '(?i)^DC Hardening :: SMB server signing: '
       Text  = 'Require SMB signing on the DC''s SMB server: enable the Group Policy setting "Microsoft network server: Digitally sign communications (always)", or run Set-SmbServerConfiguration -RequireSecuritySignature $true on the DC. Domain controllers require it by default through the Default Domain Controllers Policy, so check why that policy is not delivering the value here. A device that does not support SMB signing can no longer connect to the DC, SYSVOL and NETLOGON included.' }
    @{ Section = '(?i)^dc hardening'; Match = '(?i)^DC Hardening :: SMB client signing: '
       Text  = 'Require SMB signing on the DC''s outbound SMB connections: enable the Group Policy setting "Microsoft network client: Digitally sign communications (always)", or run Set-SmbClientConfiguration -RequireSecuritySignature $true on the DC. The DC can then no longer connect to an SMB server that does not support signing; Microsoft''s guidance is to enable signing on that server or replace the device, not to turn the requirement off.' }
    @{ Section = '(?i)^dc hardening'; Match = '(?i)^DC Hardening :: LAN Manager authentication level: '
       Text  = 'Raise the Group Policy setting "Network security: LAN Manager authentication level" on domain controllers to at least the expected minimum this finding names. The value Microsoft''s security baselines give for a DC is "Send NTLMv2 response only. Refuse LM & NTLM" (LmCompatibilityLevel 5). Audit first: a DC at level 5 refuses LM and NTLMv1, so find the clients that still use NTLMv1 with Microsoft''s procedure for auditing NTLMv1 on domain controllers (Security event 4624 on the DCs, filtered on the NTLM V1 package) and move them to NTLMv2 or Kerberos before changing the level.' }
    @{ Section = '(?i)^dc hardening'; Match = '(?i)^DC Hardening :: Print Spooler: '
       Text  = 'Disable the Print Spooler service on domain controllers; Microsoft recommends doing it with a Group Policy Object. Microsoft''s reason: any authenticated user can connect to a DC''s spooler and have the DC send a notification to a system with unconstrained delegation, which exposes the DC computer account credential. Check dependencies first: the domain controller role uses the spooler for print pruning - removing stale print queue objects from the directory - so with the service disabled, prune those objects another way.' }
    @{ Section = '(?i)^dc hardening'; Match = '(?i)^DC Hardening :: SMBv1: '
       Text  = 'Turn off the SMBv1 server on this DC: Set-SmbServerConfiguration -EnableSMB1Protocol $false, and remove the feature (Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol, which restarts the computer, or Server Manager > Remove Roles and Features > "SMB 1.0/CIFS File Sharing Support"). Find the clients that still use it first: Set-SmbServerConfiguration -AuditSmb1Access $true, then event 3000 in the Microsoft-Windows-SMBServer\Audit log names each one. Microsoft warns to be careful when disabling SMBv1 on domain controllers, because legacy systems that need SYSVOL may not support SMBv2 or SMBv3.' }
    @{ Section = '(?i)^dc hardening'; Match = '.'
       Text  = '' }
    # --- Section-scoped: Windows LAPS (PORT-PLAN C4). One entry per row family that can be a
    #     Warning or a Fail, each anchored on the Item the tool itself writes - "Windows LAPS
    #     schema", "LAPS coverage: <domain>", "DSRM password backup: <dc>" - so nothing after it
    #     (a domain or host name, the names of computers, an override file path cited as the
    #     threshold source) takes part in choosing the advice. The last entry answers every other
    #     row of the section with no advice at all. Without it the unscoped entries below would
    #     answer these rows by accident: 'backup' (DSRM password backup, BackupDirectory),
    #     'scavenging|aging' ("managing" holds "aging"), 'stale|inactive' (the population rule),
    #     'password policy|lockout', 'replication', 'global catalog'. Tests pin each family.
    #     The steps are Microsoft's own:
    #       schema, permissions, policy  - https://learn.microsoft.com/windows-server/identity/laps/laps-scenarios-windows-server-active-directory
    #       encryption ("We highly recommend that you enable password encryption")
    #                                    - https://learn.microsoft.com/windows-server/identity/laps/laps-concepts-overview
    #       DSRM setting, policy values  - https://learn.microsoft.com/windows-server/identity/laps/laps-management-policy-settings
    #       legacy migration ("We strongly recommend that you begin planning now to migrate your
    #       Windows LAPS-capable systems from legacy Microsoft LAPS", support statement section),
    #       and Entra ID as the other store
    #                                    - https://learn.microsoft.com/windows-server/identity/laps/laps-overview
    #     Read: 2026-11-15 (all); laps-overview re-read 2026-11-16 for the migration sentence.
    #     Microsoft documents DSRM password backup as off by default and
    #     publishes no sentence that every DC should have it, and the DSRM text says so.
    @{ Section = '(?i)^windows laps'; Match = '(?i)^Windows LAPS :: Windows LAPS schema :: '
       Text  = 'Complete the Windows LAPS schema. Microsoft documents Update-LapsADSchema as a one-time operation for the entire forest that adds all of the Windows LAPS attributes and puts them on the computer class, so a forest that holds only some of them points at an extension that did not finish or has not replicated. Check that the schema partition has replicated to every domain controller, then run Update-LapsADSchema again from a Windows Server 2019 or later domain controller updated with Windows LAPS, or from another server that has the Windows LAPS PowerShell module. It extends the schema, so treat it as a schema change under your own change process.' }
    @{ Section = '(?i)^windows laps'; Match = '(?i)^Windows LAPS :: LAPS coverage: '
       Text  = 'Bring the computers this finding counts under Windows LAPS, or establish why they show no expiry time here. Microsoft''s steps for backing passwords up to Active Directory are: extend the schema once for the forest with Update-LapsADSchema; grant the computers permission to update their own password on their organizational unit with Set-LapsADComputerSelfPermission; and apply a Windows LAPS policy (Group Policy, or Intune for hybrid-joined devices) with BackupDirectory set to 2, Active Directory. Microsoft highly recommends enabling password encryption, which needs domain functional level 2016, and strongly recommends moving computers still on legacy Microsoft LAPS to Windows LAPS. Before treating any computer as unmanaged, rule out the two things this directory read cannot see: a device that backs its password up to Microsoft Entra ID writes nothing here, and an expiry time this account has no right to read looks the same as none. The thresholds this finding was judged against are this tool''s defaults or your own override, not Microsoft values.' }
    @{ Section = '(?i)^windows laps'; Match = '(?i)^Windows LAPS :: DSRM password backup: '
       Text  = 'If the DSRM password of this domain controller is to be managed by Windows LAPS, Microsoft''s requirements are: the domain at functional level 2016 or later; the DC on Windows Server 2019 or later; the Windows LAPS schema in the forest (Update-LapsADSchema); and a Windows LAPS Group Policy applied to the domain controllers with BackupDirectory = 2 (Active Directory), password encryption left enabled (ADPasswordEncryptionEnabled, on by default) and ADBackupDSRMPassword = 1. Microsoft documents that setting as ignored unless encryption is enabled, and it cannot be delivered through the Windows LAPS CSP. Microsoft describes DSRM password backup as a feature that is off by default, not as a requirement: that a DC without it is reported is this tool''s rule. Where an expiry time is shown but is long past, look in the Windows LAPS event log of the DC for why the password is no longer rotated. This report read the directory only, so confirm what is configured on the DC before changing anything.' }
    @{ Section = '(?i)^windows laps'; Match = '.'
       Text  = '' }
    # --- Section-scoped: DC certificates (PORT-PLAN C5). One entry per row family that can be a
    #     Warning or a Fail, anchored on the Item the tool itself writes - "LDAPS certificate:
    #     <dc>" and "Directory certificate: <dc> [<thumbprint>]" - and a last entry that answers
    #     every other row of the section with no advice. A certificate's subject, issuer and
    #     subject alternative names are chosen by whoever requested it, so none of them is in the
    #     text matched here (they are in their own columns), and with the catch-all no free text
    #     of this section can reach an unscoped entry further down ('replication', 'backup',
    #     'certificate template|enrol', 'time sync|clock', 'port.*not reachable', 'does not
    #     resolve', 'global catalog', 'NOT a pass' ...). Tests pin each family.
    #     The steps are Microsoft's own:
    #       request a new DC certificate rather than renew an expired one ("If your valid domain
    #       controller certificate has expired, you may renew the domain controller certificate,
    #       but this process is more complex and typically more difficult than if you request a
    #       new domain controller certificate")
    #         - https://learn.microsoft.com/troubleshoot/windows-server/certificates-and-public-key-infrastructure-pki/enabling-smart-card-logon-third-party-certification-authorities
    #       requirements, the NTDS store first, the choice among several, restart or
    #       renewServerCertificate
    #         - https://learn.microsoft.com/windows-server/identity/ad-ds/configure-ldap-signing-certificates
    #         - https://learn.microsoft.com/troubleshoot/windows-server/active-directory/enable-ldap-over-ssl-3rd-certification-authority
    #       third-party CAs do not enrol or renew DC certificates automatically
    #         - https://learn.microsoft.com/troubleshoot/windows-server/active-directory/requirements-domain-controller
    #       publication to AD DS is a separate operation from issuance
    #         - https://learn.microsoft.com/windows-server/identity/ad-cs/manage-certificate-templates
    #       the default templates published to AD DS include "Directory E-mail Replication" as
    #       well as "Domain Controller", so a published value may not be a DC certificate
    #         - https://learn.microsoft.com/windows-server/identity/ad-cs/certificate-template-concepts
    #     Read: 2026-11-16 (all).
    @{ Section = '(?i)^dc certificates'; Match = '(?i)^DC Certificates :: LDAPS certificate: '
       Text  = 'Give this domain controller a valid certificate for LDAPS before the one it presents expires, or now if it has expired. For an expired domain controller certificate Microsoft''s guidance is to request a new valid one; renewing it is possible but more complex. The certificate must carry the Server Authentication EKU (1.3.6.1.5.5.7.3.1), name the DC''s Active Directory FQDN in the subject CN or a DNS subject alternative name, have its private key on the DC, and come from a CA that the DC and its clients trust. AD DS looks for it in the NTDS service store first and then in the local computer Personal store, and a DC with several usable certificates may present any of them, so check what both stores hold. Microsoft documents that AD DS takes up a new certificate after a restart of the DC or through the renewServerCertificate rootDSE operation. A third-party CA does not enrol or renew domain controller certificates automatically. A certificate that is not yet valid cannot be used before its start date. The expiry windows this finding was judged against are this tool''s defaults or your own override, not Microsoft values.' }
    @{ Section = '(?i)^dc certificates'; Match = '(?i)^DC Certificates :: Directory certificate: '
       Text  = 'This certificate is published on the domain controller''s computer object (userCertificate), which records what a CA published and not what the DC holds today: Microsoft documents publication to AD DS as a separate operation from issuance. It is not necessarily a domain controller certificate: Microsoft''s default templates published to AD DS include ''Directory E-mail Replication'' as well as ''Domain Controller'', so check its purposes (the Ekus column) and the template it was issued from first. Confirm on the DC whether it still holds and uses this certificate. If it is a domain controller certificate that the DC still uses, request a new valid domain controller certificate; Microsoft describes that as simpler than renewing an expired one, and a third-party CA does not renew it automatically. If the DC already has a newer certificate, this published copy is a record only. The expiry windows this finding was judged against are this tool''s defaults or your own override, not Microsoft values.' }
    @{ Section = '(?i)^dc certificates'; Match = '.'
       Text  = '' }
    # --- Section-scoped: RID pool (PORT-PLAN C6). Ahead of the unscoped entries: a RID pool row
    #     can say "event 16658", "restored", "dcdiag" or carry a file path, and the unscoped
    #     "event \d+ on", "backup", "dcdiag" and "aging" entries would otherwise answer it. Each
    #     family is anchored on the Item prefix this tool writes; the catch-all gives every other
    #     row of the section (per-DC inventory, population rows) no advice rather than wrong advice.
    #     Source of every statement: Managing RID Issuance (causes of RID consumption, the ceiling
    #     and event 16657, removing the block, the 31-bit unlock and its caveats, event 16658 "not
    #     expected", RID Block Size limit 15,000)
    #       https://learn.microsoft.com/windows-server/identity/ad-ds/manage/managing-rid-issuance
    #     Read: 2026-11-16.
    @{ Section = '(?i)^rid pool'; Match = '(?i)^RID Pool :: RID pool allocation: '
       Text  = 'RID pool allocation is blocked in this domain. Microsoft documents that the RID master sets msDS-RIDPoolAllocationEnabled to FALSE on CN=RID Manager$,CN=System when it allocates the pool that reaches 90 % of the global RID space (event 16657 on the RID master), and that no domain controller then receives a new RID pool, so creating users, groups and computers stops once the pools already issued run out. Before re-enabling allocation, find out why RIDs were consumed and stop it: Microsoft lists provisioning software or scripts that bulk-created objects, many unused groups, domain controllers demoted, restored or metadata-cleaned repeatedly, forest recoveries, frequent InvalidateRidPool operations and an incorrectly raised RID Block Size. Microsoft''s procedure to remove the block is to set the attribute to TRUE on the RID master (LDP, Modify, Replace); at the next allocation it returns to NOT SET, and there is no further ceiling. Unlocking the 31st bit of the global RID space (SidCompatibilityVersion) is irreversible except by a forest recovery, is meant only together with the ceiling, and leaves Windows Server 2003 and 2008 domain controllers, and 2008 R2 ones without KB 2642658, unable to issue RIDs. This tool changes neither.' }
    @{ Section = '(?i)^rid pool'; Match = '(?i)^RID Pool :: Global RID space: '
       Text  = 'Find out why so much of the global RID space has been issued. Microsoft calls reaching the first event 16658 milestone (10 % used) not expected, and says to investigate the user, computer and group creation processes in the domain immediately. Check the System log of the domain controllers for Directory-Services-SAM events 16658, 16656 and 16657, and look for the causes Microsoft lists: provisioning software or scripts that bulk-created objects, many unused groups, domain controllers demoted, restored or metadata-cleaned repeatedly, forest recoveries, frequent InvalidateRidPool operations and an incorrectly raised RID Block Size (from Windows Server 2012 a value above 15,000 is treated as 15,000). At 90 % used the RID master stops issuing RID pools until an administrator lifts the block, and after that there is no further ceiling before the space runs out, which only a domain migration or a forest recovery resolves. Unlocking the 31st bit (SidCompatibilityVersion) doubles the space but is irreversible except by a forest recovery and is meant only for a domain that has reached the ceiling. The thresholds this finding was judged against are Microsoft''s published points or your own override.' }
    @{ Section = '(?i)^rid pool'; Match = '.'
       Text  = '' }
    # --- Section-scoped: the once-per-domain, -forest and -site rows of DC Diagnostics (PORT-PLAN
    #     C11). Anchored on the Item prefixes this tool writes ("dcdiag <Test>: "), NOT on the
    #     section: the per-DC grid rows (Item = the DC's host name) keep reaching the unscoped
    #     'sysvol|dfsr', 'replication' and 'dcdiag' entries below, as tests pin. A partition or site
    #     name, a DC name or the word "replication" in a Detail cannot pull these rows to other
    #     advice. The prefix catch-all gives the coverage, not-run and site-unknown rows no advice.
    #     Each text restates what Microsoft documents the test checks, and names dcdiag's own /v
    #     (verbose) switch from the same page:
    #       https://learn.microsoft.com/windows-server/administration/windows-commands/dcdiag
    #     Read: 2026-11-16.
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag Topology: (?!\(no domain known\) :: )'
       Text  = 'dcdiag Topology reported that the replication topology of this domain is not fully connected. Microsoft documents that this test checks whether automatic intra-site and inter-site topology generation is disabled, and looks for disconnected topologies (missing connection objects) upstream and downstream of each reference DC, without replicating anything; it does not check that partners are available or that a schedule is open, which the Replications test covers. Run "dcdiag /test:Topology /s:<dc> /v" to see the DCs it names, then check the connection objects and the site and site-link configuration in Active Directory Sites and Services, and whether automatic topology generation has been turned off for a site. This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag CheckSDRefDom: '
       Text  = 'dcdiag CheckSDRefDom reported an application directory partition whose security descriptor reference domain is not right. Microsoft documents that this test validates the cross-reference objects in CN=Partitions,CN=Configuration of the forest root domain and checks that their msDS-SDReferenceDomain attribute holds the correct domain name. Run "dcdiag /test:CheckSDRefDom /s:<dc> /v" to see which partition, then read msDS-SDReferenceDomain on that partition''s crossRef object. This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag CrossRefValidation: '
       Text  = 'dcdiag CrossRefValidation reported a cross-reference that is not valid. Microsoft documents that this test reads the nCName, dnsRoot, nETBIOSName and systemFlags attributes of the crossRef objects in CN=Partitions,CN=Configuration to find names that are invalid or null, names altered by CNF or 0ADEL (a name conflict or a deleted object), wrong systemFlags, and empty (orphaned) replica sets. Run "dcdiag /test:CrossRefValidation /s:<dc> /v" to see which partition, then read those four attributes on its crossRef object. This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag Intersite: (?!(not run|site unknown|no site) :: )'
       Text  = 'dcdiag Intersite reported a failure that would prevent or hold up intersite replication for this site. Microsoft documents that this test locates and connects to the Intersite Topology Generator and the bridgehead servers, reports replication failures, and validates that the DCs in sites with inbound connections to this site are available. Run dcdiag''s Intersite test by hand against the DC named in this row, with /a and /v, to see the servers it names, and check their availability and the site links between the sites. Microsoft documents that this test triggers a replication; this tool ran it only because -IncludeDcdiagActiveTests was given.' }
    # --- Section-scoped: the DNS summary rows of DC Diagnostics, one per test group, per DC and per
    #     domain (PORT-PLAN C12). Anchored on the Item prefix this tool writes ("dcdiag DNS <group>: "),
    #     so the words of a Detail ("delegation", "secure dynamic", "replication", "dcdiag") cannot
    #     pull a row to the unscoped entries below. Each text restates what Microsoft documents the
    #     group checks and dcdiag's own advice to use /v when the summary table reports errors or
    #     warnings, and to read the "DC: <name>" section of the report:
    #       https://learn.microsoft.com/windows-server/administration/windows-commands/dcdiag
    #       https://learn.microsoft.com/troubleshoot/windows-server/active-directory/replication-error-1722-rpc-server-unavailable
    #       https://learn.microsoft.com/troubleshoot/windows-server/active-directory/active-directory-replication-event-id-2087
    #       https://learn.microsoft.com/windows-server/identity/ad-ds/manage/troubleshoot/verify-dns-functionality-to-support-directory-replication
    #         (its AAAA caveat is given for /DnsDynamicUpdate and for reruns of the whole DNS test,
    #         never for /DnsRecordRegistration: so it is in the Dyn text, not the RReg text)
    #       https://learn.microsoft.com/previous-versions/windows/it-pro/windows-server-2003/cc776854(v=ws.10)
    #         (archived, labelled for Windows Server 2003 SP1: the only Learn page that describes
    #         each test group's warnings)
    #     Read: 2026-11-16 (all).
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag DNS Auth: '
       Text  = 'dcdiag''s DNS test reported a problem in its Authentication (Auth) test group. Microsoft lists Authentication as the first of the DNS test groups and documents that membership in Enterprise Admins, or equivalent, is the minimum requirement to complete the DNS tests, and that dcdiag must be run with administrative rights from an elevated prompt: check the account and the session that ran this assessment first. Then rerun dcdiag''s DNS test against this domain controller with /DnsAll and /v (Microsoft: use /v when errors or warnings are reported in the summary table) and read the section for "DC: <name>". This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag DNS Basc: '
       Text  = 'dcdiag''s DNS test reported a problem in its Basic (Basc) test group. Microsoft documents that this test performs basic DNS tests, including network connectivity, DNS client configuration, service availability, and zone existence: check that the DNS servers this domain controller''s network adapters point to answer, that the Netlogon, KDC, DNS Client and (where installed) DNS Server services run, that the domain controller''s A record is registered, and that the Active Directory zone and its SOA record exist. Rerun dcdiag''s DNS test against this domain controller with /DnsAll and /v (Microsoft: use /v when errors or warnings are reported in the summary table) and read the section for "DC: <name>". This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag DNS Forw: '
       Text  = 'dcdiag''s DNS test reported a problem in its Forwarders/Root hints (Forw) test group. Microsoft documents that this test performs the Basic tests and also checks the configuration of forwarders: check the forwarders and root hints of the DNS server on this domain controller, and that each forwarder answers. Rerun dcdiag''s DNS test against this domain controller with /DnsAll and /v (Microsoft: use /v when errors or warnings are reported in the summary table) and read the section for "DC: <name>". This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag DNS Del: '
       Text  = 'dcdiag''s DNS test reported a problem in its Delegations (Del) test group. Microsoft documents that this test performs the Basic tests and also checks for proper delegations: check the delegations of the zones this domain controller''s DNS server holds, and that the name servers they name answer. Rerun dcdiag''s DNS test against this domain controller with /DnsAll and /v (Microsoft: use /v when errors or warnings are reported in the summary table) and read the section for "DC: <name>". This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag DNS Dyn: '
       Text  = 'dcdiag''s DNS test reported a problem in its Dynamic update (Dyn) test group. Microsoft documents that this test performs the Basic tests and also determines if dynamic update is enabled in the Active Directory zone; it reports dynamic update that is enabled but not secure as a warning, and recommends secure dynamic updates. The test registers a test record, _dcdiag_test_record, and deletes it, and Microsoft documents a warning when the delete fails: check the zone for a record left behind. Microsoft notes that if IPv6 is not enabled on the domain controller, the host (AAAA) resource record portion of this test is expected to fail, which is a normal condition when IPv6 is not enabled. Rerun dcdiag''s DNS test against this domain controller with /DnsAll and /v (Microsoft: use /v when errors or warnings are reported in the summary table) and read the section for "DC: <name>". This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag DNS RReg: '
       Text  = 'dcdiag''s DNS test reported a problem in its Records registration (RReg) test group. Microsoft documents that this test performs the Basic tests and also checks if the address (A), canonical name (CNAME) and well-known service (SRV) resource records are registered: check those records for this domain controller. Microsoft lists the alias (CNAME), host (A), LDAP SRV, GC SRV and PDC SRV records as the ones this test verifies, and notes that a missing SRV record can be ignored where DNSAvoidRegisterRecord, in the registry or in Group Policy, prevents its registration. Rerun dcdiag''s DNS test against this domain controller with /DnsAll and /v (Microsoft: use /v when errors or warnings are reported in the summary table) and read the section for "DC: <name>". This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag DNS Ext: '
       Text  = 'dcdiag''s DNS test reported a problem in its Ext test group. Learn does not name this column; it is taken to be the external name resolution test, /DnsResolveExtName, which resolves www.microsoft.com or the name given with /DnsInternetName, and which /DnsAll does not run. Microsoft notes that this test cannot resolve external Internet names in an environment where a proxy server is being used, so a failure may only mean that the domain controller has no direct internet access. Decide whether this domain controller is meant to resolve internet names; if it is, check its forwarders or root hints. This tool changes nothing.' }
    @{ Section = '(?i)^dc diagnostics'; Match = '(?i)^DC Diagnostics :: dcdiag (Topology|CheckSDRefDom|CrossRefValidation|Intersite|LocatorCheck|coverage|grid|DNS)\b'
       Text  = '' }
    # --- Section-scoped: the DNS rows of PORT-PLAN C13, in DNS Health, DNS vs AD Consistency, DC DNS
    #     Client and DNS Record Export. Anchored on the Item prefixes this tool writes, ahead of the
    #     unscoped entries: a zone or host name in an Item ("replication", "stale", "backup") or a
    #     Detail that says "aging", "secure dynamic" or "stale" must not pull a row to the unscoped
    #     'replication', 'scavenging|aging', 'secure dynamic' or 'stale' advice. NOT section-wide in
    #     DNS Health and DNS vs AD: the forwarder, zone transfer and per-server SRV rows of those
    #     sections keep the unscoped entries they had. The catch-alls give the inventory and
    #     population rows no advice. Sources, all read 2026-11-17:
    #       https://learn.microsoft.com/troubleshoot/windows-client/networking/troubleshooting-dns-dynamic-update-issues
    #       https://learn.microsoft.com/windows-server/networking/dns/dynamic-update
    #       https://learn.microsoft.com/powershell/module/dnsserver/set-dnsserverprimaryzone
    #       https://learn.microsoft.com/windows-server/networking/dns/aging-scavenging
    #       https://learn.microsoft.com/windows-server/networking/dns/configure-aging-scavenging
    #       https://learn.microsoft.com/troubleshoot/windows-server/networking/dns-scavenging-setup
    #       https://learn.microsoft.com/troubleshoot/windows-server/networking/enable-disable-dns-dynamic-registration
    #       https://learn.microsoft.com/troubleshoot/windows-server/active-directory/problems-with-dc-ad-integrated-dns-zones
    #       https://learn.microsoft.com/troubleshoot/windows-server/networking/best-practices-for-dns-client-settings
    #       https://learn.microsoft.com/troubleshoot/windows-server/networking/troubleshoot-dns-event-id-4013
    @{ Section = '(?i)^dns health'; Match = '(?i)^DNS Health :: Zone dynamic update: '
       Text  = 'Set this AD-integrated zone to Secure only. Microsoft recommends Secure only for AD-integrated zones and documents that DNS servers default to it once a zone becomes AD-integrated; without secure dynamic update any computer on the network can modify an existing record, while a zone configured for secure dynamic update allows only authorized users to modify it. The setting is the zone''s Dynamic updates option in DNS Manager, or the -DynamicUpdate parameter of Set-DnsServerPrimaryZone, whose accepted values are None, Secure and NonsecureAndSecure. Clients that cannot authenticate to the domain will no longer be able to update their own records once it is set, so find them first. This tool changes nothing.' }
    @{ Section = '(?i)^dns health'; Match = '(?i)^DNS Health :: Zone scavenging: '
       Text  = 'Enable aging on this zone and scavenging on one DNS server that hosts it. Microsoft documents aging and scavenging as two independent but complementary mechanisms that must both be enabled for stale records to be removed, and scavenging skips a zone that has aging disabled. It recommends enabling server-level scavenging on only one DNS server per zone - ideally a DC without FSMO roles, and not the PDC emulator - and gives 7 days as the default no-refresh, refresh and scavenging intervals; align the combined no-refresh and refresh intervals with your DHCP lease duration. Records added by hand have a timestamp of zero and are not scavenged; Microsoft warns that dnscmd /ageallrecords sets a timestamp on every record of a zone, static ones included. This tool changes nothing.' }
    @{ Section = '(?i)^dns health'; Match = '(?i)^DNS Health :: (DNS server( -|:) |Zone configuration: |DNS zones \(population\): |DNS health :: )'
       Text  = '' }
    @{ Section = '(?i)^dns vs ad'; Match = '(?i)^DNS vs AD Consistency :: DC locator records: '
       Text  = 'Find out why this domain controller is not named by its DC locator SRV records on the DNS servers in the Evidence column. The Net Logon service on the DC registers its SRV, CNAME and A records every hour and lists the records it must register in %systemroot%\System32\Config\Netlogon.dns: compare that file with the zone on each of those servers. Check that the DC''s DNS client points to DNS servers that host the zone, and that the zone accepts the DC''s dynamic updates. Microsoft documents that DnsAvoidRegisterRecords, in the registry or in Group Policy, stops a DC registering the records it names on purpose, so confirm it is not set for these records before treating the absence as a fault. This tool changes nothing.' }
    @{ Section = '(?i)^dns vs ad'; Match = '(?i)^DNS vs AD Consistency :: DC A record: '
       Text  = 'Compare the A records for this domain controller''s name (Evidence column) with the addresses on its enabled adapters (ConfiguredIPv4 column). Microsoft''s DNS client guidance says there should be a host record for the computer name, and documents that the DNS Server service registers A records for the addresses it listens on, which PublishAddresses can restrict: on a multihomed DC, check which adapters register. Remove an A record for an address the DC no longer holds once you have confirmed nothing else uses it. This tool changes nothing.' }
    @{ Section = '(?i)^dns vs ad'; Match = '(?i)^DNS vs AD Consistency :: Stale DC record: '
       Text  = 'This record names a host or a DSA GUID that matches no domain controller in the directory (read-only DCs included). Confirm that the DC it names was removed and that its metadata cleanup completed, then delete the record; Microsoft''s guidance is to remove references to stale domain controllers. This tool changes nothing.' }
    @{ Section = '(?i)^dns vs ad'; Match = '(?i)^DNS vs AD Consistency :: Stale DC records \(population\): '
       Text  = '' }
    @{ Section = '(?i)^dc dns client'; Match = '(?i)^DC DNS Client :: DNS client: '
       Text  = 'Give this domain controller more than one DNS server. Microsoft documents that pointing a domain controller at a single DNS server''s address, including the 127.0.0.1 loopback address, is a single point of failure that is tolerable only in a forest with one domain controller. Once replication is verified, a DC may use itself or a central DNS server as preferred server with another DC as alternate, and Microsoft''s hub-and-branch guidance lists the DC itself last. Microsoft also says not to point domain controllers at the DNS servers of an Internet service provider. This tool changes nothing.' }
    @{ Section = '(?i)^dc dns client'; Match = '.'
       Text  = '' }
    @{ Section = '(?i)^dns record export'; Match = '.'
       Text  = '' }
    # --- Section-scoped: SID history rows of Security Posture (PORT-PLAN C7). Anchored on the Item
    #     prefix this tool writes ("SID history...: <domain>"), NOT on the section: the section's
    #     older rows (krbtgt password age, AD Recycle Bin, Machine account quota, ...) rely on the
    #     unscoped entries below and must still reach them. The prefix catch-all gives every other
    #     SID history row no advice, so a privileged group's name in a Detail ("KRBTGT", "Backup
    #     Operators") cannot reach the unscoped 'krbtgt' or 'backup' entries, nor can 'replication',
    #     'global catalog', 'stale', 'NOT a pass' or 'event \d+ on'. Tests pin each family.
    #     Sources, read 2026-11-16:
    #       remediation (Get-ADUser -Properties SidHistory; Set-ADUser -Remove @{SIDHistory=...}),
    #       Enterprise Admins example, forest trusts without SID filtering (quarantine)
    #         - https://learn.microsoft.com/defender-for-identity/security-posture-assessments/accounts
    #       "eliminating SID history" to reduce token size
    #         - https://learn.microsoft.com/windows-server/identity/ad-ds/plan/security-best-practices/planning-for-compromise
    #       DsAddSidHistory: different forests, Domain Admins in the destination, "Add Sid History"
    #       audit events in the destination domain, well-known SIDs refused
    #         - https://learn.microsoft.com/windows/win32/ad/using-dsaddsidhistory
    #       MDI alert "Suspected SID-History injection" (external ID 1106)
    #         - https://learn.microsoft.com/defender-for-identity/alerts-mdi-classic
    #       netdom trust /quarantine:Yes accepts only SIDs from the directly trusted domain
    #         - https://learn.microsoft.com/windows-server/administration/windows-commands/netdom-trust
    @{ Section = '(?i)^security posture'; Match = '(?i)^Security Posture :: SID history same-domain: '
       Text  = 'Investigate the principals listed in this finding before changing anything: a historic SID of the principal''s own domain has no documented origin. Microsoft documents that DsAddSidHistory, the supported way to add SID history, works only between domains in different forests, requires Domain Admins membership in the destination domain, and writes an "Add Sid History" audit event in the destination domain for each attempt, so look in the Security logs of the domain controllers for those events and for directory changes to sIDHistory, and check whether Microsoft Defender for Identity raised "Suspected SID-History injection" (external ID 1106) for these principals. Treat the principals and the accounts that could have written the value as possibly compromised until explained. Removing the value is Microsoft''s remediation for unsecure SID history (Get-ADUser -Identity <account> -Properties SidHistory, then Set-ADUser -Identity <account> -Remove @{SIDHistory=''<SID>''}); this report reads only and changes nothing, and that the value indicates tampering is this tool''s inference, not a Microsoft statement.' }
    @{ Section = '(?i)^security posture'; Match = '(?i)^Security Posture :: SID history privileged: '
       Text  = 'Remove each privileged SID named in this finding from the sIDHistory of the principals listed, unless a documented migration still needs it: a SID in sIDHistory is added to the holder''s access token, so the holder can act with that group''s rights. Microsoft''s Defender for Identity gives an Enterprise Admins SID in another account''s SID history as its example of unsecure SID history, and its remediation is to identify the value (Get-ADUser -Identity <account> -Properties SidHistory) and remove it (Set-ADUser -Identity <account> -Remove @{SIDHistory=''<SID>''}); use the matching Set-ADGroup or Set-ADComputer cmdlet for a group or a computer. Find out how the value got there: Microsoft documents that DsAddSidHistory refuses accounts with well-known SIDs and writes an "Add Sid History" audit event in the destination domain. Where the SID belongs to another forest, confirm that SID filtering (quarantine) is enabled on the trust (netdom trust /quarantine:Yes accepts only SIDs from the directly trusted domain; the Trusts section of this report shows its state). This report reads only and changes nothing.' }
    @{ Section = '(?i)^security posture'; Match = '(?i)^Security Posture :: SID history: '
       Text  = 'Confirm that the migrations that left this SID history are finished, re-permission the resources that still grant access to the old SIDs so they name the current principals, and then remove the values. Microsoft''s Defender for Identity remediation for SID history is to identify the value (Get-ADUser -Identity <account> -Properties SidHistory) and remove it (Set-ADUser -Identity <account> -Remove @{SIDHistory=''<SID>''}); removing a value removes any access granted through it, so check first. Microsoft also names eliminating SID history as one way to reduce token size. Same-domain and privileged values are graded in their own findings and come first. That present SID history is graded at all is this tool''s default (catalogue ADA-OBJ-009), not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^security posture'; Match = '(?i)^Security Posture :: SID history'
       Text  = '' }
    # --- Section-scoped: GPO version consistency rows of GPO Inventory (PORT-PLAN C8). Anchored on
    #     the Item prefixes this tool writes ("GPO version: {GUID}", "GPO version summary: <domain>",
    #     "GPO folder without container: {GUID}"), NOT on the section: the inventory's older rows
    #     have the section name as their Item and keep whatever they matched before. Every version
    #     row's Detail says SYSVOL and replication, which the unscoped 'sysvol|dfsr' and
    #     'replication' entries would otherwise answer with restore advice; a config file path in the
    #     provenance could say "backup" or "stale". The prefix catch-all gives every other version
    #     row no advice. A GPO's display name and its gPCFileSysPath are never in Item or Detail.
    #     Sources, read 2026-11-16:
    #       AD and SYSVOL replicate independently; DFSR within a site every 15 minutes
    #         - https://learn.microsoft.com/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing
    #       both versions updated on every edit; clients compare versions to decide whether to reprocess
    #         - https://learn.microsoft.com/openspecs/windows_protocols/ms-gpol/70fd86b1-926a-4dcf-9ce7-6f9d2149c20d
    #         - https://learn.microsoft.com/openspecs/windows_protocols/ms-gpol/bc953fef-0ca0-495f-8097-20772b3f6a6e
    #       a SYSVOL folder whose GUID is not listed in Active Directory is an orphaned GPO that can be
    #       deleted from the file system
    #         - https://learn.microsoft.com/troubleshoot/windows-server/group-policy/rebuild-sysvol-tree-and-content-in-a-domain
    @{ Section = '(?i)^gpo inventory'; Match = '(?i)^GPO Inventory :: GPO version(: \{| summary: )'
       Text  = 'Run the assessment again once Active Directory and SYSVOL replication have converged: Microsoft documents that the directory part and the SYSVOL part of a GPO replicate by two independent mechanisms (DFSR replicates SYSVOL within a site every 15 minutes), so a version difference can be an edit still in flight. If it remains, the domain controller this finding names holds a directory version and a GPT.INI version that disagree, although Microsoft''s Group Policy protocol requires both to be updated together on every edit and clients compare them to decide whether to apply the GPO again. Check SYSVOL replication first - the SYSVOL / DFSR section of this report, and its backlog with -IncludeSysvolBacklog - and compare this GPO''s GPT.INI on the other domain controllers; do not edit or copy policy files until replication is healthy. Grading a difference at all is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^gpo inventory'; Match = '(?i)^GPO Inventory :: GPO folder without container: \{'
       Text  = 'Confirm that no Group Policy object uses this GUID before treating the folder as orphaned: read CN=Policies,CN=System with an account that can read every GPO (a GPO whose permissions deny this account looks the same as a missing one), and check the domain''s other domain controllers. Microsoft''s SYSVOL rebuild guidance says that a SYSVOL folder whose GUID is not listed in Active Directory is an orphaned GPO and can be deleted from the file system; take a copy of the folder first. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^gpo inventory'; Match = '(?i)^GPO Inventory :: GPO (version|folder)'
       Text  = '' }
    # --- Section-scoped: Dangerous ACLs (PORT-PLAN C9). One entry per row family, anchored on the Item
    #     prefix this tool writes ("DCSync rights: <domain>", "Domain root control rights: <domain>",
    #     "AdminSDHolder rights: <domain>", "GPO rights: {GUID}" and "GPO rights summary: <domain>"),
    #     and a prefix catch-all that gives every other row of the section no advice. Every graded row's
    #     Detail says "replication", and a provenance file path could say "backup" or "stale", so without
    #     these the unscoped 'replication', 'dcsync', 'sysvol|dfsr', 'pdc emulator', 'delegation' and
    #     'backup' entries would answer them with the fix for a different fault. Tests pin each family.
    #     Sources, read 2026-11-16:
    #       default holders of the replication and control rights on the domain object
    #         - https://learn.microsoft.com/windows/win32/adschema/c-domaindns
    #       Get-Changes-All is "the replication of secret domain data"
    #         - https://learn.microsoft.com/windows/win32/adschema/r-ds-replication-get-changes-all
    #       Enterprise Read-only Domain Controllers: Replicating Directory Changes only, and the fix when
    #       they hold Replicating Directory Changes All
    #         - https://learn.microsoft.com/troubleshoot/windows-server/active-directory/replication-error-8453
    #         - https://learn.microsoft.com/troubleshoot/windows-server/active-directory/rodc-replicates-passwords-grant-incorrect-permissions
    #       the Entra Connect AD DS connector account holds both replication rights by design
    #         - https://learn.microsoft.com/troubleshoot/entra/entra-id/user-prov-sync/password-writeback-access-rights-permissions
    #       WRITE_DAC "modify the DACL", WRITE_OWNER "assume ownership"; an owner implicitly holds WRITE_DAC
    #         - https://learn.microsoft.com/windows/win32/api/iads/ne-iads-ads_rights_enum
    #         - https://learn.microsoft.com/windows/win32/secauthz/owner-of-a-new-object
    #       AdminSDHolder: who may change it, its owner, SDProp every 60 minutes on the PDC emulator
    #         - https://learn.microsoft.com/windows-server/identity/ad-ds/plan/security-best-practices/appendix-c--protected-accounts-and-groups-in-active-directory
    #       groupPolicyContainer default descriptor; a Group Policy Creator Owners member owns what it creates
    #         - https://learn.microsoft.com/windows/win32/adschema/c-grouppolicycontainer
    #         - https://learn.microsoft.com/windows-server/identity/ad-ds/manage/understand-security-identifiers
    @{ Section = '(?i)^dangerous acls'; Match = '(?i)^Dangerous ACLs \(DCSync\) :: DCSync rights: '
       Text  = 'Review each SID this finding names. None of them is a holder Microsoft publishes for the replication rights on the domain head (Domain Controllers and Administrators for Replicating Directory Changes All; Enterprise Domain Controllers, Administrators and the forest root''s Enterprise Read-only Domain Controllers for Replicating Directory Changes), nor Domain Admins, Enterprise Admins or SYSTEM, which hold every extended right there by default. Some products hold these rights by design: Microsoft documents granting Replicating Directory Changes and Replicating Directory Changes All on the domain root to the Microsoft Entra Connect AD DS connector account. Confirm what each SID is and why it holds the right before changing anything; if it is legitimate, add its SID to AdditionalAllowed in the Acl section of the config override file, with the reason. Remove a grant nobody can explain from the permissions of the domain head and treat it as a possible compromise: Microsoft describes Replicating Directory Changes All as the right to replicate secret domain data. Where Enterprise Read-only Domain Controllers hold Replicating Directory Changes All, Microsoft''s fix is to change that grant to Replicating Directory Changes. This report reads only and changes nothing, and the allowlist it judged against is provisional.' }
    @{ Section = '(?i)^dangerous acls'; Match = '(?i)^Dangerous ACLs \(DCSync\) :: Domain root control rights: '
       Text  = 'Review each SID this finding names. WriteDacl lets the holder modify the permissions of the domain head, WriteOwner lets it take ownership, and an owner always holds WriteDacl; write of all properties and full control go further. Any of them is enough to grant the holder the replication rights. Microsoft''s published default descriptor of the domain object gives these rights to Domain Admins, Administrators, Enterprise Admins and SYSTEM only. Remove a grant or an ownership that has no documented owner and reason, and find out who made it; if one is legitimate, add its SID to AdditionalAllowed in the Acl section of the config override file, with the reason. This report reads only and changes nothing, and the allowlist it judged against is provisional.' }
    @{ Section = '(?i)^dangerous acls'; Match = '(?i)^Dangerous ACLs \(DCSync\) :: AdminSDHolder rights: '
       Text  = 'Remove the grants this finding names from CN=AdminSDHolder,CN=System of the domain, after finding out who made them. Microsoft documents that SDProp applies the permissions of AdminSDHolder to the protected accounts and groups - by default every 60 minutes, on the PDC emulator - so a grant here becomes a grant on Domain Admins, Enterprise Admins and every other protected account and group of the domain. By default only Enterprise Admins and the domain''s Domain Admins and Administrators can change AdminSDHolder, and Domain Admins owns it. This report reads only and changes nothing, and the allowlist it judged against is provisional.' }
    @{ Section = '(?i)^dangerous acls'; Match = '(?i)^Dangerous ACLs \(DCSync\) :: GPO rights( summary)?: '
       Text  = 'Review who can change the Group Policy objects this finding names. Microsoft''s default descriptor of a Group Policy container gives full control to Domain Admins, Enterprise Admins, SYSTEM and, through Creator Owner, the account that created the GPO; Microsoft also documents that a member of Group Policy Creator Owners who creates a GPO owns it. A delegated creator is therefore expected here and is reported so that the delegation is seen. Remove write and control rights and ownership from anyone who should not edit the GPO; if a delegation is intended, add its SID to AdditionalAllowed in the Acl section of the config override file, with the reason. The permissions of the GPO''s folder in SYSVOL were not read and need the same review. This report reads only and changes nothing, and the allowlist it judged against is provisional.' }
    @{ Section = '(?i)^dangerous acls'; Match = '(?i)^Dangerous ACLs \(DCSync\) :: '
       Text  = '' }
    # --- Section-scoped: Privileged Accounts, Privileged Hygiene and Kerberos Exposure (PORT-PLAN C10). One
    #     entry per graded row family, anchored on the Item prefix this tool writes, and a catch-all that
    #     gives every other new row no advice. Detail names groups such as Backup Operators and Replicator,
    #     the word delegation and, under an override, a file path, so without these the unscoped 'backup',
    #     'replication', 'delegation', 'krbtgt' and 'stale' entries would answer them with the fix for a
    #     different fault; the unscoped 'delegation' advice ("replace with resource-based constrained
    #     delegation") would even be wrong for the RBCD row. The Kerberos catch-all names only the new
    #     delegation prefixes, so the Kerberoast and AS-REP rows still reach their unscoped entries. Tests
    #     pin each family. Sources, read 2026-11-16:
    #       Schema Admins "populated only temporarily and occasionally"; adminCount stays 1 and inheritance
    #       stays off after removal from a protected group
    #         - https://learn.microsoft.com/windows-server/identity/ad-ds/plan/security-best-practices/reducing-the-active-directory-attack-surface
    #       Enterprise Admins empty day to day, the root Administrator a possible exception
    #         - https://learn.microsoft.com/windows-server/identity/ad-ds/plan/security-best-practices/appendix-e--securing-enterprise-admins-groups-in-active-directory
    #       "Account is sensitive and cannot be delegated"; Protected Users cautions
    #         - https://learn.microsoft.com/windows-server/identity/ad-ds/manage/understand-default-user-accounts
    #         - https://learn.microsoft.com/windows-server/security/credentials-protection-and-management/protected-users-security-group
    #       Defender for Identity: privileged accounts not delegated, unsecure Kerberos delegation, remove an SPN
    #         - https://learn.microsoft.com/defender-for-identity/security-posture-assessments/accounts
    #       TRUSTED_FOR_DELEGATION and TRUSTED_TO_AUTH_FOR_DELEGATION wording
    #         - https://learn.microsoft.com/windows/win32/adschema/a-useraccountcontrol
    #       RBCD read with PrincipalsAllowedToDelegateToAccount; protocol transition always allowed for RBCD
    #         - https://learn.microsoft.com/windows-server/security/kerberos/kerberos-constrained-delegation-overview
    @{ Section = '(?i)^privileged accounts'; Match = '(?i)^Privileged Accounts :: Schema Admins members: '
       Text  = 'Remove every member that is not needed for a schema change being made now. Microsoft documents that Schema Admins is intended to be populated only temporarily and occasionally, when the schema must be modified, and that its default member is the forest root domain''s built-in Administrator account: add an account when a schema change is scheduled and remove it when the change is done. Review the members this finding lists (names in the Principals column, SIDs in PrincipalSids) before removing anything. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^privileged accounts'; Match = '(?i)^Privileged Accounts :: Enterprise Admins members: '
       Text  = 'Remove day-to-day accounts from Enterprise Admins. Microsoft documents that Enterprise Admins should contain no users on a day-to-day basis, with the possible exception of the forest root domain''s Administrator account, secured as its guidance for that account describes: add an account only for a task that needs forest-wide rights and remove it afterwards. Review the members this finding lists (names in the Principals column, SIDs in PrincipalSids) before removing anything. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^privileged accounts'; Match = '(?i)^Privileged Accounts :: '
       Text  = '' }
    @{ Section = '(?i)^privileged hygiene'; Match = '(?i)^Privileged Hygiene :: adminCount orphans: '
       Text  = 'Confirm, for each object this finding lists, that it should no longer be protected - that no protected group reaches it through a path this account could not see - and then re-enable permission inheritance on it and clear its adminCount attribute. Microsoft documents that when an account is removed from a protected group its adminCount attribute remains set to 1 if it is not manually changed, and that the object still does not inherit permissions. Microsoft calls these objects formerly protected; orphan is this tool''s word. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^privileged hygiene'; Match = '(?i)^Privileged Hygiene :: Privileged accounts with SPN: '
       Text  = 'Remove the service principal names from the privileged user accounts this finding lists, and run each service under its own non-privileged account. Microsoft Defender for Identity recommends removing an SPN from a user account and shows that recommendation for sensitive accounts. Confirm what each SPN is used for (the Targets column lists them) before removing it. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^privileged hygiene'; Match = '(?i)^Privileged Hygiene :: Privileged accounts delegable: '
       Text  = 'Select "Account is sensitive and cannot be delegated" on each privileged account this finding lists, unless a documented need requires that account to be delegated. Microsoft calls this setting a best practice for all sensitive accounts, and Defender for Identity reports privileged accounts that lack it. Membership of Protected Users also prevents delegation, but Microsoft warns against adding highly privileged accounts to that group before testing, and never to add service or computer accounts, so decide that separately. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^privileged hygiene'; Match = '(?i)^Privileged Hygiene :: '
       Text  = '' }
    @{ Section = '(?i)^kerberos exposure'; Match = '(?i)^Kerberos Exposure :: Unconstrained delegation: '
       Text  = 'Review each account this finding lists and remove "Trust this computer for delegation to any service" (TRUSTED_FOR_DELEGATION) from it, or move it to constrained delegation limited to the services it actually needs. Microsoft documents that a service running under an account trusted for delegation can impersonate a client requesting the service, and Defender for Identity reports unconstrained delegation on accounts other than domain controllers as unsecure. The domain controllers registered in the configuration partition were excluded by the DN of their computer account. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^kerberos exposure'; Match = '(?i)^Kerberos Exposure :: Protocol transition delegation: '
       Text  = 'Review each account this finding lists: it is set for constrained delegation with protocol transition ("Use any authentication protocol", TRUSTED_TO_AUTH_FOR_DELEGATION). Microsoft describes this setting as security-sensitive and says accounts with it enabled should be strictly controlled. Keep it only where a service needs it, change the account to Kerberos-only constrained delegation where it does not, and confirm the target services in the Targets column. The domain controllers and read-only domain controllers registered in the configuration partition were excluded. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^kerberos exposure'; Match = '(?i)^Kerberos Exposure :: Resource-based delegation: '
       Text  = 'Review each resource this finding lists and the principals allowed to delegate to it, by SID in the AllowedSids column. Microsoft documents that this setting holds the principals allowed to delegate to the resource, and that the KDC always allows protocol transition for resource-based constrained delegation. Microsoft documents reading the setting with Get-ADComputer, Get-ADServiceAccount or Get-ADUser -Properties PrincipalsAllowedToDelegateToAccount; remove an entry nobody can explain. The grade is this tool''s default, not a Microsoft grade; this report reads only and changes nothing.' }
    @{ Section = '(?i)^kerberos exposure'; Match = '(?i)^Kerberos Exposure :: (Unconstrained|Protocol transition|Constrained|Resource-based) delegation: '
       Text  = '' }
    # --- Section-scoped: Exchange SE. Ahead of the unscoped entries so the generic
    #     replication/time wording in a detail line cannot hijack a readiness finding.
    # A forest ABOVE the listed levels gets NO advice, and this entry is what guarantees it.
    # First match wins, so it stops the raise entry below - which before H17 told a Windows
    # Server 2025 level forest to raise its level to Windows Server 2016 - and it stops every
    # later unscoped entry too. That second part is not theoretical: under a config override the
    # finding cites the override FILE PATH, and a path containing a word such as "Backup" would
    # otherwise attract the backup advice. Tests pin both.
    @{ Section = '(?i)exchange se'; Match = '(?i)this is not a level to raise'
       Text  = '' }
    # The target mode is not named: the supported set can be overridden, so the finding's own
    # "Supported:" list is the only place that knows which level to raise to.
    @{ Section = '(?i)exchange se'; Match = '(?i)forest functional level'
       Text  = 'Raise the forest functional level before Setup: confirm every DC is on a supported OS first, then "Set-ADForestMode -Identity <forest> -ForestMode <mode>", using one of the supported modes this finding lists (raise each domain with Set-ADDomainMode first where needed). This is a one-way change and cannot be reverted without a forest recovery, so take a verified system-state backup of two DCs per domain and confirm replication is healthy beforehand.' }
    @{ Section = '(?i)exchange se'; Match = '(?i)not supported for|not readable|unverified, not compatible'
       Text  = 'Every domain controller in the forest must run a supported Windows Server version, not only the ones in the Exchange site. Upgrade or decommission the named DCs before Setup, transferring any FSMO roles they hold first. Where the OS could not be read, re-run with credentials able to read the DC computer objects - an unreadable value is not a pass.' }
    @{ Section = '(?i)exchange se'; Match = '(?i)read-only domain controller'
       Text  = 'Exchange does not use a read-only DC or a read-only global catalog. No action is needed for an RODC in a site where no Exchange server will be installed; for any site that WILL host one, confirm it also contains a writeable global catalog, or Setup fails in that site alone.' }
    # --- Section-scoped: _msdcs delegation. Ahead of the generic DNS entries, which would
    #     otherwise answer a broken delegation with "enable scavenging".
    @{ Section = '(?i)msdcs'; Match = '(?i)is not a delegated zone|unexpected zone'
       Text  = 'Create _msdcs.<forest> as its own AD-integrated zone and delegate it from the parent. In DNS Manager: create the zone, store it in AD DS, set replication to "All DNS servers in this forest" (the forest-wide application directory partition), then right-click the parent zone -> New Delegation and point it at the DNS servers hosting the child zone. Move the existing _msdcs records across before removing the subdomain, and confirm with "nltest /dsgetdc:<forest> /force" plus "Resolve-DnsName _msdcs.<forest> -Type SOA" against each DNS server. Until this is right, replication partners and clients cannot find global catalog servers reliably.' }
    @{ Section = '(?i)msdcs'; Match = '(?i)no NS records|missing glue'
       Text  = 'Recreate the delegation records in the PARENT zone: an NS record naming each DNS server authoritative for _msdcs.<forest>, and a glue host (A/AAAA) record for each of those names. DNS Manager: right-click the parent zone -> New Delegation, or repair an existing delegation by editing the NS records and adding the missing glue. A delegation with an NS record but no glue is a dead referral - the resolver has a name it cannot turn into an address.' }
    @{ Section = '(?i)msdcs'; Match = '(?i)not a known DC'
       Text  = 'Compare each NS host against the DCs this report inventoried. For a decommissioned DC, delete the NS record from the _msdcs zone (and from the domain zone) as the forest recovery guide instructs after metadata cleanup, then run "nltest.exe /dsderegdns:<oldhost>" to clear its remaining SRV records. For a non-DC DNS server that is genuinely authoritative, no change is needed - record why, so the next run is not re-investigated.' }
    # --- Section-scoped: PORT-PLAN C14. Anchored on the Items this tool writes, ahead of the unscoped
    #     entries ('replication', 'does not resolve', 'port.*not reachable', 'time sync|w32tm|clock',
    #     'sysvol|dfsr', 'stale|inactive'), which would otherwise answer these rows with advice for a
    #     different fault. Sources, read 2026-11-17:
    #       https://learn.microsoft.com/troubleshoot/windows-server/active-directory/config-firewall-for-ad-domains-and-trusts
    #       https://learn.microsoft.com/windows-server/identity/ad-ds/deploy/ad-ds-metadata-cleanup
    #       https://learn.microsoft.com/windows/win32/winrm/installation-and-configuration-for-windows-remote-management
    #       https://learn.microsoft.com/windows/win32/ad/directory-service-functions
    #       https://learn.microsoft.com/troubleshoot/windows-server/active-directory/dc-delayed-response-to-ldap-kerberos-request
    #       https://learn.microsoft.com/troubleshoot/windows-server/active-directory/configure-w32ime-against-huge-time-offset
    #       https://learn.microsoft.com/troubleshoot/windows-server/windows-security/kerberos-protocol-registry-kdc-configuration-keys
    #       https://learn.microsoft.com/troubleshoot/mem/configmgr/discovery/lastlogontimestamp-not-accurate
    #       https://learn.microsoft.com/defender-for-identity/security-posture-assessments/accounts
    #       https://learn.microsoft.com/windows/win32/adschema/a-pwdlastset
    #       https://learn.microsoft.com/windows-server/storage/dfs-replication/migrate-sysvol-to-dfsr
    #       https://learn.microsoft.com/windows-server/administration/windows-commands/dfsrmig
    #       https://learn.microsoft.com/troubleshoot/windows-server/networking/sysvol-dfsr-migration-fails-after-in-place-upgrade
    @{ Section = '(?i)^port reachability$'; Match = '(?i)^Port Reachability :: DC reachability: '
       Text  = 'Find out why this domain controller does not answer the host running the assessment before reading any other result for it. A name that does not resolve needs its A record (check the DC''s DNS client settings and its registration). A refused or silent LDAP port needs the firewall between the two hosts checked against Microsoft''s port list for AD (TCP 389, 88, 135, 445, 3268 and the dynamic RPC range 49152-65535), or the DC itself checked. A DC that answers LDAP but neither WinRM (5985) nor RPC (135) cannot be read remotely; WinRM can listen on another port, so confirm its listener before opening anything. If the DC was retired and will not come back, perform metadata cleanup (delete its computer object in Active Directory Users and Computers, or ntdsutil "metadata cleanup"), as Microsoft documents for a forcibly removed DC.' }
    @{ Section = '(?i)^site health$'; Match = '(?i)^Site Health :: Subnets without a site: '
       Text  = 'Assign a site to each subnet listed in the Subnets column: Active Directory Sites and Services, Sites > Subnets, the subnet''s properties, Site. A domain controller maps a client to a site by the subnet object that covers its address, whose siteObject names the site; a subnet with no site maps its clients to none, and they may then use any domain controller.' }
    @{ Section = '(?i)^site health$'; Match = '(?i)^Site Health :: Clients without a site: '
       Text  = 'Create subnet object(s) covering the client addresses listed in the Clients column and map each to the site those clients are in (Active Directory Sites and Services, Sites > Subnets > New Subnet), as Microsoft''s Netlogon event 5807 advises. Until then those clients have no site and may use any domain controller, including a distant one. Look at netlogon.bak on the DC as well, which this tool does not read.' }
    @{ Section = '(?i)^time hierarchy$'; Match = '(?i)^Time Hierarchy :: Clock offset (vs forest root PDC: |on )'
       Text  = 'Kerberos tolerates five minutes of difference by default, and what counts is the difference between the KDC and the target, so every DC must keep step with the forest root PDC emulator, the authoritative time server of the forest. Check this DC''s source with "w32tm /query /computer:<dc> /source" and "w32tm /query /computer:<dc> /status": a DC takes time from the domain hierarchy (Type NT5DS), and only the forest root PDC emulator from an external source. Give a virtualised DC one time source, not the host''s as well. Fix time before chasing Kerberos or replication errors.' }
    @{ Section = '(?i)^stale objects$'; Match = '(?i)^Stale Objects :: Inactive enabled (users|computers) :: '
       Text  = 'Confirm that each account in the Accounts column is unused before acting: lastLogonTimestamp can trail the real last logon by up to the logon-sync interval (14 days by default; Microsoft says the value is updated when it is 9 to 14 days old), so for a borderline account read lastLogon on every DC. Then disable first, wait, and delete later, keeping any account its owner confirms is in use. Defender for Identity treats a user with no logon for 90 days as stale.' }
    @{ Section = '(?i)^stale objects$'; Match = '(?i)^Stale Objects :: Enabled users with an old password :: '
       Text  = 'Find the owner of each account in the Accounts column: an enabled account whose pwdLastSet is older than the threshold is either unused (disable it) or a service account (move it to a group managed service account, or set a new long random password). pwdLastSet 0 means the user must set a password at the next logon when UF_DONT_EXPIRE_PASSWD is clear; those accounts are counted, not listed. An account in the AgeNotKnownAccounts column has pwdLastSet 0 and a password that never expires, so its password age is not known: find its owner too.' }
    @{ Section = '(?i)^sysvol / dfsr$'; Match = '(?i)^SYSVOL / DFSR :: SYSVOL replication engine: '
       Text  = 'Migrate SYSVOL replication from FRS to DFS Replication with dfsrmig: confirm AD replication is healthy, then step the global state with "dfsrmig /setglobalstate 1" (Prepared), 2 (Redirected) and 3 (Eliminated), checking "dfsrmig /getmigrationstate" until every DC has reached each state before the next. From Prepared or Redirected the migration can be rolled back ("dfsrmig /setglobalstate 0"); reaching Eliminated is irreversible. FRS was removed in Windows Server 2019, and a Windows Server 2019 or later DC cannot be promoted into a domain whose SYSVOL still uses FRS. Where the engine was not known, re-run with rights to read each DC''s DFSR-LocalSettings and NTFRS Subscriptions objects.' }
    # --- Section-scoped: time hierarchy. Must precede the unscoped time entry, which assumes
    #     the finding is about the local host.
    @{ Section = '(?i)time hierarchy'; Match = "(?i)virtualisation host's time provider"
       Text  = 'Give the DC one time source, not two. On a non-PDC virtualised DC, clear Time Synchronization in the VM''s Integration Services (or set HKLM\SYSTEM\CurrentControlSet\Services\W32Time\TimeProviders\VMICTimeProvider\Enabled to 0 and restart W32Time), then confirm with "w32tm /query /source" that it now names a DC. Where the host is kept as the source on the PDC, the host itself must be synchronised to the same authoritative source, or the divergence simply moves up a layer.' }
    @{ Section = '(?i)time hierarchy'; Match = '(?i)no authoritative upstream|not synchronising from the domain hierarchy|Type is NoSync|not a valid configuration|top of that hierarchy|domain hierarchy it is itself the top of'
       Text  = 'Configure the forest root PDC emulator against an external authoritative source: "w32tm.exe /config /syncfromflags:manual /manualpeerlist:<ntp host>,0x8 /reliable:yes /update", then "net stop w32time & net start w32time" and verify with "w32tm /query /source" and "w32tm /query /status". Use three or more peers where you can - with only two, flag the second ,0x2 (UseAsFallbackOnly). Leave every other DC on the domain hierarchy (Type NT5DS). Fix time before chasing Kerberos or replication errors: a skew beyond five minutes fails authentication outright.' }
    # --- Section-scoped: per-site GC coverage.
    @{ Section = '(?i)site global catalog|sitegc'; Match = '.'
       Text  = 'Set the global catalog flag on a writeable DC in the affected site - AD Sites and Services -> the DC''s NTDS Settings -> Global Catalog, or "repadmin /options <dc> +IS_GC" - then wait for the partial attribute set to replicate (Directory Service event 1119 confirms it) and check the _gc._tcp SRV records register. A read-only DC does not satisfy this: Exchange Setup fails in a site containing only read-only directory servers. If no application in the site needs a local GC, record the decision instead of changing anything.' }
    # --- SYSVOL / DFSR specifics, ahead of the generic sysvol|dfsr entry below, which would
    #     otherwise answer every one of these with "perform a D4". Reinitialising is the LAST
    #     resort: the vendor's own guidance is that it is unnecessary in most cases and can lose
    #     data, and it hides the cause.
    #     https://learn.microsoft.com/troubleshoot/windows-server/networking/troubleshoot-missing-sysvol-and-netlogon-shares
    #     https://learn.microsoft.com/troubleshoot/windows-server/group-policy/force-authoritative-non-authoritative-synchronization
    #     Read: 2026-09-21.
    @{ Match = '(?i)msDFSR-options=1 on \d+ DCs|conflicting authoritative'
       Text  = 'Only ONE member may be authoritative. Decide which DC holds the SYSVOL content you want to keep - normally the PDC emulator, and compare \\<dc>\SYSVOL\<domain>\Policies on the candidates first - then clear msDFSR-options on every other DC''s "CN=SYSVOL Subscription,CN=Domain System Volume,CN=DFSR-LocalSettings,<server DN>" object. Leaving two set means SYSVOL content depends on which DC initialises first.' }
    @{ Match = '(?i)msDFSR-Enabled=FALSE'
       Text  = 'SYSVOL replication is switched off on the named DCs, which only happens by hand during a D2/D4-equivalent rebuild - so finish it. Set msDFSR-Enabled=TRUE on "CN=SYSVOL Subscription,CN=Domain System Volume,CN=DFSR-LocalSettings,<server DN>", force AD replication, then run "dfsrdiag pollad" on that DC. Watch for DFS Replication events 4614 (waiting) then 4604 (initialised); only 4604 means SYSVOL is serving again. Recover from the authoritative DC outward through its direct partners, not all at once.' }
    @{ Match = '(?i)authoritative SYSVOL member'
       Text  = 'Expected only during a deliberate SYSVOL rebuild. Confirm it finished: DFS Replication event 4602 on this DC, then 4604 on the others, and \\<dc>\SYSVOL present everywhere. If no rebuild was intended, this attribute was left behind - establish which DC holds correct SYSVOL content before clearing anything, because the next DFSR initialisation will treat this DC as the source of truth.' }
    @{ Match = '(?i)neither SYSVOL nor NETLOGON|SYSVOL is NOT shared|NETLOGON is NOT shared'
       Text  = 'Do NOT jump to a D4 rebuild - find the cause first. On the DC, read the DFS Replication log: event 2213 means a dirty shutdown paused replication and the fix is the ResumeReplication WMI method, not a rebuild; 4012 means content freshness stopped it (MaxOfflineTimeInDays exceeded) and needs reinitialisation; 4114 means the membership is disabled. A DC that has never logged 4604 has never initialised SYSVOL. Confirm AD replication is healthy first - DFSR reads its configuration from the directory, so a broken AD replica cannot converge SYSVOL.' }
    @{ Match = '(?i)dirty shutdown detected'
       Text  = 'DFSR paused replication after a dirty shutdown and will not resume by itself. Run the ResumeReplication WMI method on that volume as the 2213 event instructs; event 2214 confirms recovery completed. Do not delete the DFSR database - that makes DFSR treat all local data as non-authoritative and risks losing SYSVOL content.' }
    @{ Match = '(?i)content freshness'
       Text  = 'Replication has been stopped for longer than MaxOfflineTimeInDays, so DFSR will not resume without reinitialisation. Recover the affected DCs non-authoritatively (msDFSR-Enabled FALSE then TRUE, with "dfsrdiag pollad"), fanning out from a known-healthy DC through its direct partners. Only set a DC authoritative if EVERY DC has logged 4012 - that is the single case where an authoritative rebuild is correct.' }
    @{ Match = '(?i)WAITING to perform initial replication'
       Text  = 'This DC has not initialised SYSVOL and is not serving it. Run "dfsrdiag pollad" on it and wait for event 4604. If 4604 never arrives, its upstream partner is not serving SYSVOL either - fix the upstream DC first; initial sync cannot complete from a partner that has nothing to give.' }
    # A link that is not converging WITHOUT erroring needs different advice from one that is
    # failing: there is no error to chase, so the question is why nothing is being attempted.
    @{ Match = '(?i)nothing is being attempted|stopped converging rather than lagged'
       Text  = 'No error means nothing is being attempted, so look at the topology rather than the network. Check the connection object exists and is enabled (AD Sites and Services, or "repadmin /showconn <dc>"), the site link schedule and cost actually permit replication at this hour, and that the KCC is building the topology ("repadmin /kcc <dc>", then Directory Service events 1311/1865/1925). Then force a sync to prove the path works: "repadmin /replicate <dest> <source> <NC>". If the last success predates tombstone lifetime, do NOT simply reconnect it - that reintroduces lingering objects; run the advisory lingering-object scan first (-IncludeLingeringObjectScan).' }
    @{ Match = '(?i)no readable last-success time|no successful replication to measure from'
       Text  = 'This link or DSA has no successful replication on record, which reports as zero failures because nothing has been attempted since the counter reset. Confirm the DC is actually reachable on the replication ports (the port matrix section), then force a sync and watch the result: "repadmin /replicate <dest> <source> <NC>" followed by "repadmin /showrepl <dest>". A DC that has never replicated since being restored needs its secure channel and DNS records verified before anything else.' }
    @{ Match = '(?i)clock skew'
       Text  = 'A replication timestamp in the future means the DCs disagree about the time, and Kerberos fails beyond a five-minute skew. Fix time first - every other replication timestamp in this report is unreliable until you do. Check the PDC emulator''s external source ("w32tm /query /status /verbose" on it), then "w32tm /resync" on the others, and confirm no DC is taking time from a virtualisation host integration service while also using the domain hierarchy.' }
    # --- Unscoped entries: matched against "Section :: Item :: Detail" ---
    # Ahead of the event-specific entries: a log that cannot cover the window is a different
    # problem from an event found in it, and the fix is to recover the evidence, not the DC.
    @{ Match = '(?i)log coverage|absence of an event proves nothing|cleared or has wrapped|NOT a pass'
       Text  = 'Treat this DC as UNASSESSED for the window, not healthy - a cleared or wrapped Directory Service log is silent for the same reason a healthy one is. Recover the evidence before drawing any conclusion: check for an archived copy (%SystemRoot%\System32\winevt\Logs\*.evtx, any SIEM or log-forwarding target, or the backup the DC was restored from), and corroborate independently - "repadmin /showrepl <dc> /errorsonly" and "repadmin /showutdvec" reveal a replication break that the log would have reported. Then raise the log so the next run can conclude: "wevtutil sl \"Directory Service\" /ms:67108864" (64 MB) and confirm retention is Overwrite as needed. On a post-incident forest, also run the advisory lingering-object scan (-IncludeLingeringObjectScan), which does not depend on the event log at all.' }
    @{ Match = '(?i)dsa guid cname|orphaned ntds settings'
       Text  = 'If the DC is live: on that DC run "ipconfig /registerdns" and "nltest /dsregdns", then restart the Netlogon service, and confirm the _msdcs zone accepts secure dynamic updates. If the DC no longer exists: remove its metadata (ntdsutil "metadata cleanup", or delete the server object in AD Sites and Services) and delete the stale record. Replication resolves source DCs through this alias - fix it before chasing RPC 1722 errors.' }
    @{ Match = '(?i)stale dns entry'
       Text  = 'This host is advertised in DNS but does not exist in AD. Delete its stale SRV/A records, confirm metadata cleanup completed for the removed DC (ntdsutil "metadata cleanup"), then run "nltest /dsregdns" on surviving DCs to re-register clean records.' }
    @{ Match = '(?i)missing from dns|not advertised'
       Text  = 'On the affected DC: "ipconfig /registerdns", "nltest /dsregdns", restart Netlogon. Verify the zone allows secure dynamic updates and that the DC''s NIC points at working AD DNS servers (never an external resolver first).' }
    @{ Match = '(?i)pdc locator|pdc emulator'
       Text  = 'Re-register the PDC record: on the actual PDC emulator run "nltest /dsregdns" and restart Netlogon; if the role moved during recovery, confirm FSMO placement with "netdom query fsmo" and seize/transfer as intended before fixing DNS.' }
    @{ Match = '(?i)lingering object'
       Text  = 'Remove lingering objects rather than forcing replication through: "repadmin /removelingeringobjects <dc> <authoritative-dc-dsa-guid> <NC> /advisory_mode" first to preview, then without /advisory_mode. Do not disable strict replication consistency.' }
    @{ Match = '(?i)tombstone lifetime'
       Text  = 'Replication was stopped longer than tombstone lifetime; restarting it blindly risks lingering objects. Preferred fix: forcibly demote the divergent DC, clean its metadata, and repromote it. Only consider "allow replication with divergent and corrupt partner" after a full lingering-object scan.' }
    # NOTE: this previously advised "dcpromo /forceremoval", which is the Windows 2000 / Server
    # 2003 era command - the KB that documents it is scoped to those releases. On every OS this
    # tool supports (WS2012 R2 and later) the command is Uninstall-ADDSDomainController.
    # https://learn.microsoft.com/powershell/module/addsdeployment/uninstall-addsdomaincontroller
    # https://learn.microsoft.com/windows-server/identity/ad-ds/deploy/demoting-domain-controllers-and-domains--level-200-
    # Read: 2026-09-21.
    @{ Match = '(?i)dsa not writable'
       Text  = 'Do NOT delete or change the "Dsa Not Writable" value - that removes the quarantine and permanently diverges this DC from the forest. Pick one of the two supported recoveries. (1) Restore this DC''s system state from a backup taken BEFORE the bad restore, using an AD-aware backup application, which resets the invocation ID properly. (2) Demote and rebuild: "Uninstall-ADDSDomainController -ForceRemoval -DemoteOperationMasterRole", then clean its metadata on a surviving DC (ntdsutil "metadata cleanup", or delete the server object in AD Sites and Services), seize any FSMO roles it held, and repromote. Forced demotion loses every change that originated here and had not replicated out, so capture what you need first. Re-add the Global Catalog afterwards if it held one.' }
    @{ Match = '(?i)usn rollback|unsupported restore'
       Text  = 'This DC was restored by snapshot or disk image, which is not a supported way to restore a DC. Either restore its system state from a backup taken before the bad restore with an AD-aware backup application, or demote and rebuild it: "Uninstall-ADDSDomainController -ForceRemoval -DemoteOperationMasterRole", then metadata cleanup on a surviving DC, seize any FSMO roles it held, and repromote. Forced demotion discards every unreplicated change that originated on it. Recover DCs only by system-state restore or by rebuilding and repromoting.' }
    @{ Match = '(?i)share invocationId|database was CLONED'
       Text  = 'Two DCs are running the same database instantiation, which means one was copied from the other (a duplicated VHD, disk image, or a P2V whose original kept running) rather than restored. Do not leave both in service: decide which is authoritative, then demote and rebuild the other with "Uninstall-ADDSDomainController -ForceRemoval -DemoteOperationMasterRole", clean its metadata, and repromote it. Until then, replication partners believe both DCs already hold each other''s changes, so originating updates on either can be dropped without any replication error being reported.' }
    @{ Match = '(?i)generation id change|reverted to a previous state'
       Text  = 'A snapshot, import or live migration was applied to this DC. Where the hypervisor supplies a VM-Generation ID, AD detects it and protects itself - new invocation ID, RID pool invalidated, SYSVOL resynced non-authoritatively - so no rollback follows, but the practice still is not supported and on a hypervisor without VM-Generation ID the same action causes a silent USN rollback. Confirm this DC replicates inbound and outbound, check its RID pool, and confirm SYSVOL is shared. Stop using snapshots to roll DCs back: use system-state backup instead.' }
    @{ Match = '(?i)replication'
       Text  = 'Fix the DNS findings first (stale records, DSA GUID CNAMEs) - most post-restore RPC 1722 replication errors are DNS, not the network. Then: "repadmin /replsummary", "repadmin /showrepl <dc>", force with "repadmin /replicate <dest> <source> <NC>", and re-run this assessment to confirm.' }
    @{ Match = '(?i)no a record|does not resolve'
       Text  = 'Fix name resolution first: create or re-register the A record (on the DC: "ipconfig /registerdns", restart Netlogon) and confirm this host points at AD DNS servers. A host that does not resolve is unreachable regardless of firewall state.' }
    @{ Match = '(?i)port.*not reachable'
       Text  = 'Open the AD replication port set between DCs: TCP 88, 135, 389, 445, 636, 3268 plus the dynamic RPC range 49152-65535 (or pin replication to a fixed port via the NTDS "TCP/IP Port" registry value and open that). Distinguish firewall blocks from a service not listening (check with netstat on the DC).' }
    @{ Match = '(?i)time sync|w32tm|time skew|clock'
       Text  = 'Point the forest-root PDC emulator at reliable external NTP: "w32tm /config /manualpeerlist:""<ntp1> <ntp2>"" /syncfromflags:manual /reliable:yes /update"; every other DC: "w32tm /config /syncfromflags:domhier /update"; then "w32tm /resync". Kerberos fails beyond 5 minutes of skew.' }
    @{ Match = '(?i)central store'
       Text  = 'Create the GPO central store: copy %SystemRoot%\PolicyDefinitions (including language subfolders) into \\<domain>\SYSVOL\<domain>\Policies\PolicyDefinitions on the PDC; DFSR replicates it to the other DCs.' }
    @{ Match = '(?i)sysvol|dfsr'
       Text  = 'Check "dfsrmig /getmigrationstate". If SYSVOL is not replicating after the restore, perform an authoritative (D4) DFSR restore on the best DC and non-authoritative (D2) on the others via msDFSR-Options, and verify the SYSVOL/NETLOGON shares exist on every DC before editing GPOs.' }
    @{ Match = '(?i)krbtgt'
       Text  = 'Reset the krbtgt password TWICE per domain, waiting for full replication (10+ hours / one ticket lifetime) between resets - mandatory after a ransomware incident to invalidate any forged golden tickets. Use Microsoft''s New-KrbtgtKeys.ps1 for a controlled rollout.' }
    @{ Match = '(?i)kerberoast'
       Text  = 'Move the flagged service accounts to Group Managed Service Accounts (gMSA); where impossible, set 30+ character random passwords and AES-only Kerberos ("Set-ADUser -KerberosEncryptionType AES256").' }
    @{ Match = '(?i)as-rep|preauth|pre-auth'
       Text  = 'Re-enable Kerberos pre-authentication on the flagged accounts (clear "Do not require Kerberos preauthentication" / the DONT_REQ_PREAUTH UAC bit).' }
    @{ Match = '(?i)delegation'
       Text  = 'Remove unconstrained delegation; replace with resource-based constrained delegation where delegation is genuinely required. Mark privileged accounts "sensitive and cannot be delegated" and add them to Protected Users.' }
    @{ Match = '(?i)dcsync|replication.*extended right'
       Text  = 'Remove the DS-Replication-Get-Changes* extended rights from every non-default principal on the domain head. After an incident, treat an unexplained grant as evidence of persistence: reset that principal''s credentials and audit its history.' }
    @{ Match = '(?i)esc1|certificate template|enrol'
       Text  = 'Harden the template: remove ENROLLEE_SUPPLIES_SUBJECT, require manager approval, and restrict enrollment permissions. Audit already-issued certificates (certutil -view) and revoke anything suspicious - certificates outlive password resets.' }
    @{ Match = '(?i)backup'
       Text  = 'Take a fresh system-state backup of at least two DCs per domain now ("wbadmin start systemstatebackup -backuptarget:<vol>"). After a restore-based recovery the newest backup is your safety net AND your tombstone-lifetime clock.' }
    @{ Match = '(?i)global catalog'
       Text  = 'Align GC state: if the DC should be a GC, verify partial-attribute-set replication completed (Directory Service event 1119) and re-register DNS ("nltest /dsregdns"); if it should not, clear the GC flag in AD Sites and Services and scavenge the stale _gc records.' }
    @{ Match = '(?i)duplicate spn'
       Text  = 'List duplicates with "setspn -X" and remove the SPN from the wrong account with "setspn -D <spn> <account>". Kerberos authentication is unreliable while duplicates exist.' }
    @{ Match = '(?i)smbv1'
       Text  = 'Remove SMBv1 on DCs: "Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol" / "Uninstall-WindowsFeature FS-SMB1". It is a ransomware lateral-movement vector with no place on a domain controller.' }
    @{ Match = '(?i)spooler'
       Text  = 'Disable the Print Spooler service on all domain controllers ("Stop-Service Spooler; Set-Service Spooler -StartupType Disabled") - PrintNightmare-class exploits give SYSTEM on a DC.' }
    @{ Match = '(?i)ldap signing'
       Text  = 'Require LDAP signing on DCs (GPO: "Domain controller: LDAP server signing requirements" = Require signing) and enable LDAP channel binding; audit first with events 2886-2889 to find clients that would break.' }
    @{ Match = '(?i)password policy|lockout'
       Text  = 'Raise the domain password policy to current guidance (14+ character minimum, no periodic-expiry theatre, lockout/throttling on) and use fine-grained password policies for privileged and service accounts.' }
    @{ Match = '(?i)recycle bin'
       Text  = 'Enable the AD Recycle Bin ("Enable-ADOptionalFeature ''Recycle Bin Feature'' ..."). It is irreversible but makes object recovery trivial - exactly what a recovery scenario needs.' }
    @{ Match = '(?i)machine account quota'
       Text  = 'Set ms-DS-MachineAccountQuota to 0 so ordinary users cannot join computers to the domain; delegate joins explicitly.' }
    @{ Match = '(?i)scavenging|aging'
       Text  = 'Enable DNS scavenging with matched refresh/no-refresh intervals (7/7 days typical) on the AD zones and one scavenging server - stale records after a recovery cause exactly the divergence this report checks for.' }
    @{ Match = '(?i)zone transfer'
       Text  = 'Restrict zone transfers to named secondaries only (or disable entirely for AD-integrated zones).' }
    @{ Match = '(?i)secure dynamic'
       Text  = 'Set the zone to Secure-only dynamic updates so only authenticated machines can register or overwrite records.' }
    @{ Match = '(?i)stale|inactive|never.expir'
       Text  = 'Disable first, delete later: disable the flagged accounts, monitor for breakage for 30 days, then remove. After an incident, stale enabled accounts are re-entry vectors.' }
    @{ Match = '(?i)dcdiag|advertising|netlogons|sysvolcheck|fsmocheck|kccevent'
       Text  = 'Read raw\dcdiag_<dc>.txt for the failing test detail; fix in dependency order: DNS -> replication -> SYSVOL -> advertising. A dcdiag failure is a symptom - the DNS/replication sections of this report usually name the cause.' }
    @{ Match = '(?i)event \d+ on'
       Text  = 'Correlate with the Replication and DNS sections of this report; the event detail names the object or partner involved. Fix the cause there, then confirm the event stops recurring.' }
)

function ConvertTo-AdfaConsolidatedFinding {
    <#
    .SYNOPSIS
        Pure: one section row as a consolidated finding - item, status, detail, recommendation.
    .DESCRIPTION
        Taken out of Invoke-Main so the order of two steps can be tested. The recommendation is
        chosen from the text that describes what was FOUND (Detail, Reasons, FailureDetail,
        Failures, VerifyDetail). A row may also carry a NotRun note, saying what was
        deliberately not run and why; that note is added to the finding's detail AFTER the
        recommendation has been chosen. The recommendation map matches on the whole text,
        first match wins, so a note that mentions replication or DNS would otherwise pick the
        advice for a failure that has nothing to do with either.
    .OUTPUTS
        [pscustomobject] Section, Scope, Item, Status, Detail, Recommendation.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)][string]$Section,
        [Parameter(Mandatory)]$Row,
        [Parameter(Mandatory)][string]$StatusColumn
    )
    $names = @($Row.PSObject.Properties | ForEach-Object { $_.Name })
    $status = [string]$Row.$StatusColumn
    $item = $Section
    foreach ($n in @('Item', 'TrustName', 'DomainController', 'Group', 'PolicyName')) {
        if ($names -contains $n) { $item = $Row.$n; break }
    }
    $detailParts = @()
    foreach ($n in @('Detail', 'Reasons', 'FailureDetail', 'Failures', 'VerifyDetail')) {
        if (($names -contains $n) -and $Row.$n) { $detailParts += [string]$Row.$n }
    }
    $scopeVal = ''
    if ($names -contains 'Scope') { $scopeVal = [string]$Row.Scope }
    $detailText = $detailParts -join ' | '
    # Attach a best-practice fix to every actionable (non-Pass) finding.
    $recommendation = ''
    if ($status -match '^(Fail|Broken|Failed|Warning|Degraded)$') {
        $recommendation = Get-AdfaRecommendation -Section $Section -Item ([string]$item) -Detail $detailText
    }
    if (($names -contains 'NotRun') -and $Row.NotRun) {
        if ($detailText -ne '') { $detailText = ("{0} | {1}" -f $detailText, [string]$Row.NotRun) }
        else { $detailText = [string]$Row.NotRun }
    }
    return [pscustomobject]@{
        Section = $Section; Scope = $scopeVal; Item = [string]$item
        Status  = $status; Detail = $detailText
        Recommendation = $recommendation
    }
}

function Get-AdfaRecommendation {
    <#
    .SYNOPSIS
        Pure lookup: maps a finding's section/item/detail text to a best-practice
        remediation recommendation. Returns '' when no guidance matches - an absent
        recommendation is honest, never invented.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [string]$Section = '',
        [string]$Item = '',
        [string]$Detail = ''
    )
    $combined = "{0} :: {1} :: {2}" -f $Section, $Item, $Detail
    foreach ($entry in $script:RecommendationMap) {
        if ($entry.ContainsKey('Section') -and -not ($Section -match $entry.Section)) { continue }
        if ($combined -match $entry.Match) { return [string]$entry.Text }
    }
    return ''
}

# ===========================================================================
# region HTML report
# ===========================================================================

function ConvertTo-AdfaHtmlText {
    # Portable HTML-encode: System.Net.WebUtility is present on .NET Framework 4.5+ and
    # .NET Core/5+, so this works on Windows PowerShell 5.1 and pwsh 7 without System.Web.
    [CmdletBinding()]
    [OutputType([string])]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return '' }
    return [System.Net.WebUtility]::HtmlEncode([string]$Value)
}

function ConvertTo-AdfaHtmlSection {
    <#
    .SYNOPSIS
        Renders a collection to an HTML table with RAG colouring of a Status/Health column.
    .OUTPUTS
        [string]
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][string]$Title,
        [AllowNull()]$Data,
        [string]$Description
    )
    # Normalise to one column set: a section can legitimately mix row shapes (an
    # unreachable DC or a failed enumeration emits a shorter object than its neighbours),
    # and reading a missing property under StrictMode would throw and lose the report.
    $rows = @(ConvertTo-AdfaRowSet -Rows $Data)
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine("<h2>$(ConvertTo-AdfaHtmlText $Title)</h2>")
    if ($Description) { [void]$sb.AppendLine("<p class='desc'>$(ConvertTo-AdfaHtmlText $Description)</p>") }
    if ($rows.Count -eq 0) {
        [void]$sb.AppendLine("<p class='empty'>No data collected.</p>")
        return $sb.ToString()
    }
    $cols = @($rows[0].PSObject.Properties.Name)
    [void]$sb.AppendLine("<table><thead><tr>")
    foreach ($c in $cols) { [void]$sb.AppendLine("<th>$((ConvertTo-AdfaHtmlText $c))</th>") }
    [void]$sb.AppendLine("</tr></thead><tbody>")
    foreach ($r in $rows) {
        $statusVal = $null
        foreach ($sc in @('Status', 'Health')) { if ($cols -contains $sc) { $statusVal = [string]$r.$sc; break } }
        $cls = switch -Regex ($statusVal) {
            '^(Pass|Healthy|Verified)$' { 'ok'; break }
            '^(Warning|Degraded)$' { 'warn'; break }
            '^(Fail|Broken|Failed)$' { 'bad'; break }
            '^(Not Assessed)$' { 'na'; break }
            default { '' }
        }
        [void]$sb.AppendLine("<tr class='$cls'>")
        foreach ($c in $cols) {
            $v = $r.$c
            $text = if ($null -eq $v) { '' } else { [string]$v }
            [void]$sb.AppendLine("<td>$((ConvertTo-AdfaHtmlText $text))</td>")
        }
        [void]$sb.AppendLine("</tr>")
    }
    [void]$sb.AppendLine("</tbody></table>")
    return $sb.ToString()
}

function New-AdfaHtmlReport {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][System.Collections.Specialized.OrderedDictionary]$Sections,
        [Parameter(Mandatory)][pscustomobject]$Meta,
        [Parameter(Mandatory)][string]$Path
    )
    $css = @"
<style>
:root{color-scheme:light dark;}
body{font-family:'Segoe UI',Arial,sans-serif;margin:24px;color:#1b1b1b;background:#fff;}
h1{font-size:24px;margin-bottom:2px;} h2{font-size:17px;margin-top:28px;border-bottom:2px solid #eee;padding-bottom:4px;}
.desc{color:#666;font-size:12px;margin:2px 0 8px;}
.meta{font-size:12px;color:#555;} .empty{color:#888;font-style:italic;}
table{border-collapse:collapse;width:100%;margin:8px 0;font-size:12px;}
th,td{border:1px solid #ddd;padding:5px 7px;text-align:left;vertical-align:top;}
th{background:#f3f4f6;position:sticky;top:0;}
tr.ok  td:nth-child(1){border-left:4px solid #16a34a;}
tr.warn td:nth-child(1){border-left:4px solid #d97706;}
tr.bad td:nth-child(1){border-left:4px solid #dc2626;}
tr.na  td:nth-child(1){border-left:4px solid #9ca3af;}
tr.ok{background:#f0fdf4;} tr.warn{background:#fffbeb;} tr.bad{background:#fef2f2;} tr.na{background:#f9fafb;}
.badges span{display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;margin-right:6px;color:#fff;}
.b-ok{background:#16a34a;} .b-warn{background:#d97706;} .b-bad{background:#dc2626;} .b-na{background:#9ca3af;}
code{background:#f3f4f6;padding:1px 5px;border-radius:3px;}
</style>
"@

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine("<!DOCTYPE html><html><head><meta charset='utf-8'/><title>AD Forest Assessment</title>$css</head><body>")
    [void]$sb.AppendLine("<h1>Active Directory Forest Assessment</h1>")
    [void]$sb.AppendLine("<p class='meta'>Forest: <code>$((ConvertTo-AdfaHtmlText $Meta.Forest))</code> &middot; Generated: $($Meta.Generated) &middot; By: $((ConvertTo-AdfaHtmlText $Meta.RunBy)) &middot; Tool v$($Meta.Version)</p>")
    [void]$sb.AppendLine("<p class='badges'>$($Meta.Badges)</p>")
    foreach ($key in $Sections.Keys) {
        [void]$sb.AppendLine((ConvertTo-AdfaHtmlSection -Title $key -Data $Sections[$key]))
    }
    [void]$sb.AppendLine("</body></html>")
    $sb.ToString() | Out-File -Encoding UTF8 -FilePath $Path -Force
    return $Path
}

function New-AdfaReportSummary {
    <#
    .SYNOPSIS
        Builds a self-reconciling roll-up: every finding lands in exactly one bucket.
    .DESCRIPTION
        The four counters Invoke-Main computes for the log line and the HTML badges match
        Pass/Healthy, Warning/Degraded, Fail/Broken and Not Assessed. They do NOT match
        'Info', which is a valid New-Finding status, so those rows are counted nowhere.
        Measured on the three-domain fixture: 123 findings, 106 counted, 17 Info invisible.

        Those four are carried through unchanged, so the JSON agrees with the HTML and the
        log rather than quietly telling a third story. What is added is 'info', an
        'unclassified' bucket for any status none of them match, and 'total'. A consumer can
        assert that the buckets sum to the total; if a future status escapes every filter it
        shows up in 'unclassified' instead of vanishing.
    .OUTPUTS
        [System.Collections.Specialized.OrderedDictionary]
    #>
    [CmdletBinding()]
    [OutputType([System.Collections.Specialized.OrderedDictionary])]
    param(
        [Parameter(Mandatory)][pscustomobject]$Summary,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$Findings
    )
    $rows = @(Expand-AdfaRowList -Rows $Findings)
    $statuses = @($rows | ForEach-Object {
            $prop = $_.PSObject.Properties['Status']   # $null when absent - StrictMode-safe
            if ($null -eq $prop) { '' } else { [string]$prop.Value }
        })
    $info = @($statuses | Where-Object { $_ -eq 'Info' }).Count
    $classified = @($statuses | Where-Object {
            $_ -match '^(Pass|Healthy|Warning|Degraded|Fail|Broken|Not Assessed|Info)$'
        }).Count
    return [ordered]@{
        pass         = [int]$Summary.Pass
        warning      = [int]$Summary.Warning
        fail         = [int]$Summary.Fail
        notAssessed  = [int]$Summary.NotAssessed
        info         = [int]$info
        unclassified = [int](@($statuses).Count - $classified)
        total        = [int]@($statuses).Count
    }
}

function New-AdfaReportDocument {
    <#
    .SYNOPSIS
        Builds the machine-readable report object. Pure: no I/O, no collection.
    .DESCRIPTION
        Separated from the writer so the document's shape is unit-testable without a
        filesystem, in the same style as Get-AdfaDnsQueryOutcome and Resolve-AdfaTrustHealth.

        Every collection goes through ConvertTo-AdfaRowSet - the same normalisation the CSVs
        use - so a section whose rows differ in shape serialises with a stable column union
        instead of dropping the later rows' properties (the defect fixed for CSV and HTML in
        v1.5.1 and v1.6.0; JSON must not reintroduce it on a third output path).

        schemaVersion is emitted so a consumer diffing two runs can tell a tool change from
        an environment change. Bump it only when the shape changes incompatibly.
    .OUTPUTS
        [System.Collections.Specialized.OrderedDictionary]
    #>
    [CmdletBinding()]
    [OutputType([System.Collections.Specialized.OrderedDictionary])]
    param(
        [Parameter(Mandatory)][pscustomobject]$Meta,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$Findings,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$Coverage,
        [Parameter(Mandatory)][AllowNull()]$Sections,
        [Parameter(Mandatory)][pscustomobject]$Summary
    )

    $sectionMap = [ordered]@{}
    if ($null -ne $Sections) {
        foreach ($key in @($Sections.Keys)) {
            $sectionMap[[string]$key] = @(ConvertTo-AdfaRowSet -Rows $Sections[$key])
        }
    }
    # Normalised once: the summary counts and the serialised findings must describe the same
    # rows, so they are derived from one collection rather than normalised twice.
    $findingRows = @(ConvertTo-AdfaRowSet -Rows $Findings)

    # Meta carries an HTML badge string for the report header; it is presentation and has no
    # place in a data document, so the fields are taken by name rather than splatted.
    $doc = [ordered]@{
        schemaVersion = 1
        tool          = [ordered]@{
            name    = 'ADForestAssessment'
            version = [string]$Meta.Version
        }
        run           = [ordered]@{
            forest        = [string]$Meta.Forest
            generated     = [string]$Meta.Generated
            runBy         = [string]$Meta.RunBy
            domainsScoped = @($Meta.DomainsScoped)
            dcCount       = [int]$Meta.DcCount
            sectionsRun   = @($sectionMap.Keys)
        }
        summary       = (New-AdfaReportSummary -Summary $Summary -Findings $findingRows)
        findings      = $findingRows
        coverage      = @(ConvertTo-AdfaRowSet -Rows $Coverage)
        sections      = $sectionMap
    }
    return $doc
}

function Export-AdfaJsonReport {
    <#
    .SYNOPSIS
        Writes the run as JSON beside the HTML report.
    .DESCRIPTION
        Serialises what Invoke-Main has already assembled. Nothing is collected here, so a
        serialisation fault costs no data - the CSVs and the itemised log are already on disk
        by the time this runs.

        Depth is explicit and generous. ConvertTo-Json defaults to 2, which would render a
        section's rows as type names instead of values - silent truncation, which is the
        precise failure mode this tool exists to avoid. A test asserts the default depth
        carries real section data rather than "System.Object[]".
    .OUTPUTS
        [string] The path written.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)][pscustomobject]$Meta,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$Findings,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()]$Coverage,
        [Parameter(Mandatory)][AllowNull()]$Sections,
        [Parameter(Mandatory)][pscustomobject]$Summary,
        [Parameter(Mandatory)][string]$Path,
        [int]$Depth = 12
    )
    $doc = New-AdfaReportDocument -Meta $Meta -Findings $Findings -Coverage $Coverage -Sections $Sections -Summary $Summary
    $doc | ConvertTo-Json -Depth $Depth | Out-File -Encoding UTF8 -FilePath $Path -Force
    return $Path
}

# ===========================================================================
# region MAIN
# ===========================================================================

function Test-SectionSelected {
    param([string]$Name, [string[]]$Selected)
    return ($Selected -contains 'All' -or $Selected -contains $Name)
}

function Invoke-Main {
    [CmdletBinding()]
    param()

    # Resolve output root -> logged-on user's Documents by default.
    if (-not $OutputPath) {
        $docs = [Environment]::GetFolderPath('MyDocuments')
        if ([string]::IsNullOrWhiteSpace($docs)) { $docs = Join-Path $HOME 'Documents' }
        $OutputPath = Join-Path $docs 'AdAssessment'
    }
    $stamp = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'
    $runRoot = New-Folder -Path (Join-Path $OutputPath $stamp)
    $csvPath = New-Folder -Path (Join-Path $runRoot 'csv')
    $rawPath = New-Folder -Path (Join-Path $runRoot 'raw')

    # Detailed run log (itemised) is the primary log; transcript captures raw host/verbose.
    $script:LogFile = Join-Path $runRoot ("assessment_{0}.log" -f $stamp)
    "AD Forest Assessment detailed log - $stamp" | Out-File -LiteralPath $script:LogFile -Encoding UTF8 -Force
    $transcript = Join-Path $runRoot ("transcript_{0}.log" -f $stamp)
    try { Start-Transcript -Path $transcript -Force | Out-Null } catch { }

    Write-Log -Level INFO ("Runtime: PowerShell {0} on {1}; user {2}\{3}" -f `
        $PSVersionTable.PSVersion, [Environment]::MachineName, $env:USERDOMAIN, $env:USERNAME)
    Write-Log -Level INFO ("Parameters: AllDomains={0} Sections={1} IncludeDcdiag={2} IncludeRepadmin={3} SkipTrustVerification={4} Server={5} IncludeSecureChannelVerify={6} ConfigOverridePath={7}" -f `
        $AllDomains.IsPresent, ($Sections -join ','), $IncludeDcdiag.IsPresent, $IncludeRepadmin.IsPresent, $SkipTrustVerification.IsPresent, $Server, $IncludeSecureChannelVerify.IsPresent, $ConfigOverridePath)
    # Said in the log as well as in the findings: this run can change a secure channel.
    if ($IncludeSecureChannelVerify) {
        Write-Log -Level WARN -Section 'SecureChannel' -Message 'IncludeSecureChannelVerify is set: nltest /sc_verify will run, and it resets any secure channel it finds not working. This run is not read-only.'
    }
    if ($IncludeDcdiag) {
        Write-Log -Level WARN -Section 'DcDiagnostics' -Message 'IncludeDcdiag is set: the raw capture runs dcdiag /c on each DC. Microsoft documents /c as running all tests except DCPromo and RegisterInDNS; by that description it includes CutoffServers, which triggers replication, and the DNS test, whose dynamic update test registers and deletes a test record. This run is not read-only.'
    }
    if ($IncludeDcdiagActiveTests) {
        Write-Log -Level WARN -Section 'DcDiagnostics' -Message 'IncludeDcdiagActiveTests is set: the dcdiag DNS test will register and delete a DNS test record on each DC, the dcdiag SystemLog test, which Microsoft describes as reading and writing System log entries, will run on each DC, and the dcdiag Intersite test will trigger a replication, once per site that holds a DC. This run is not read-only.'
    }
    if ($IncludeLdapsHandshake) {
        Write-Log -Level WARN -Section 'DcCertificates' -Message 'IncludeLdapsHandshake is set: a TLS handshake is made to port 636 of each DC to read the certificate it presents. Nothing is written to the DC, but Microsoft does not state that a handshake leaves no trace: a DC that cannot complete it may log a Schannel error event in its System log.'
    }
    # -ConfigOverridePath is read and validated ONCE, here, before the directory is touched and
    # before any section runs: a file that cannot be used must stop the run before any work is
    # done, not after an hour of collection. It is validated in full even when the section it
    # names was not selected - a file is right or wrong regardless of this run's -Sections -
    # and the log says which of its sections this run will not use.
    $configOverrides = @{}
    if ($ConfigOverridePath) {
        try {
            $configOverrides = Import-AdfaConfigOverride -Path $ConfigOverridePath -BaseConfig $script:Config -Sections $script:ConfigOverrideSections
        }
        catch {
            Write-Log -Level ERROR ("Config override refused, nothing was collected: {0}" -f $_.Exception.Message)
            try { Stop-Transcript | Out-Null } catch { }
            throw
        }
        foreach ($name in @($configOverrides.Keys | Sort-Object)) {
            Write-Log -Level INFO ("Config override: section {0} taken from {1}" -f $name, $ConfigOverridePath)
            # A table may serve more than one section (AlsoUsedBy, PORT-PLAN C10); it is unused only when
            # none of them is selected.
            $usedBy = @(@([string]$script:ConfigOverrideSections[[string]$name]['Section']) + @(@($script:ConfigOverrideSections[[string]$name]['AlsoUsedBy']) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ }))
            if (@($usedBy | Where-Object { Test-SectionSelected -Name $_ -Selected $Sections }).Count -eq 0) {
                Write-Log -Level WARN -Message ("Config override: section {0} was validated but is not used by this run, because -Sections does not include {1}." -f $name, ($usedBy -join ' or '))
            }
        }
    }
    # A fresh run starts with no remembered port probes; within the run each DC is probed once.
    Clear-AdfaDcPortCache
    Write-Stage ("AD Forest Assessment v{0} starting" -f $script:Config.Version)
    Write-Stage ("Output: {0}" -f $runRoot)

    # Terminating on purpose: with no module there is no directory access and nothing to report
    # on. The message names the requirement instead of surfacing a raw module-load error.
    try { Import-Module ActiveDirectory -ErrorAction Stop -Verbose:$false }
    catch {
        Write-Log -Level ERROR ("RSAT ActiveDirectory module could not be loaded: {0}" -f $_.Exception.Message)
        throw ("The RSAT ActiveDirectory module is required and could not be loaded: {0}. Install RSAT-AD-PowerShell, or run this on a domain controller." -f $_.Exception.Message)
    }
    Write-Stage 'ActiveDirectory module imported'

    $adParams = @{}
    if ($Server) { $adParams.Server = $Server }
    if ($Credential) { $adParams.Credential = $Credential }
    $repParams = @{}
    if ($Credential) { $repParams.Credential = $Credential }

    # Forest and domain resolution. Previously unguarded: on a forest where either call throws -
    # a damaged or partially-recovered one, which is precisely what this tool exists for - the run
    # died with a raw exception and produced NO report at all. Now the failure becomes the
    # report's headline finding and every section degrades around it, which is only possible
    # because the collectors now tolerate an empty domain and DC list.
    $scopeRows = @()
    $forestError = ''
    $forest = $null
    try { $forest = Get-ADForest @adParams }
    catch { $forestError = $_.Exception.Message }

    if ($null -eq $forest) {
        Write-Log -Level ERROR -Section 'ForestScope' -Message ("Forest could not be read: {0}" -f $forestError)
        # A placeholder so the reporting path still runs and a bundle still lands on disk. Named
        # so nobody mistakes it for a forest: every section around it reports Not Assessed.
        $forest = [pscustomobject]@{ Name = '(forest unreadable)'; RootDomain = ''; Domains = @(); ForestMode = '' }
        $scopeRows += New-Finding -Area 'ForestScope' -Item 'Forest resolution' -Status $script:Status.Fail `
            -Detail ("The forest could not be read, so NOTHING in this report was assessed: {0}. Check that the target is reachable, that ADWS (9389) and LDAP (389) are open, and that the credentials can read the directory. Re-run with -Server pointed at a known-healthy DC." -f $forestError)
    }

    $rootDomain = [string]$forest.RootDomain
    $targetDomains = @()
    if (-not $forestError) {
        if ($AllDomains) { $targetDomains = @($forest.Domains) }
        else {
            try { $targetDomains = @((Get-ADDomain @adParams).DNSRoot) }
            catch {
                # The forest object read but the current domain did not. Falling back to the forest
                # root is a genuine recovery on a damaged forest - but it CHANGES THE SCOPE of the
                # run, so it is reported loudly rather than done quietly.
                Write-Log -Level ERROR -Section 'ForestScope' -Message ("Current domain could not be read: {0}" -f $_.Exception.Message)
                if ($rootDomain) {
                    $targetDomains = @($rootDomain)
                    $scopeRows += New-Finding -Area 'ForestScope' -Item 'Domain scope' -Status $script:Status.Warning `
                        -Detail ("The current domain could not be determined ({0}), so this run was scoped to the forest ROOT domain '{1}' instead. Confirm that is the domain you meant to assess; if not, re-run with -Server pointed at a DC in the intended domain." -f $_.Exception.Message, $rootDomain)
                }
                else {
                    $scopeRows += New-Finding -Area 'ForestScope' -Item 'Domain scope' -Status $script:Status.Fail `
                        -Detail ("The current domain could not be determined ({0}) and the forest reported no root domain to fall back to, so no domain was assessed." -f $_.Exception.Message)
                }
            }
        }
    }
    if (@($targetDomains).Count -eq 0 -and -not $forestError) {
        $scopeRows += New-Finding -Area 'ForestScope' -Item 'Domain scope' -Status $script:Status.Fail `
            -Detail 'The forest was readable but reported no domains to assess. Every per-domain section is therefore unassessed, not clean.'
    }
    # Whether the scoped domains are every domain of the forest (PORT-PLAN C13): only then is a DC
    # count, or the set of DNS servers that can host a forest-wide zone, one over the forest.
    $forestDomainsProp = $forest.PSObject.Properties['Domains']
    $forestDomainList = @()
    if ($null -ne $forestDomainsProp) { $forestDomainList = @(@($forestDomainsProp.Value) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim().TrimEnd('.').ToLowerInvariant() }) }
    $scopedDomainList = @(@($targetDomains) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim().TrimEnd('.').ToLowerInvariant() })
    $scopeCoversForest = ($forestDomainList.Count -gt 0 -and @($forestDomainList | Where-Object { $scopedDomainList -notcontains $_ }).Count -eq 0)
    Write-Stage ("Forest: {0}; assessing domains: {1}" -f $forest.Name, ($targetDomains -join ', '))

    $sectionData = [ordered]@{}
    $sectionStatus = [ordered]@{}
    # Scope problems lead the report: if the forest or the domain list could not be resolved,
    # every section below is unassessed and the reader needs to know that before reading them.
    if (@($scopeRows).Count -gt 0) { $sectionData['Forest & Domain Scope'] = @($scopeRows) }
    $ext = @{ TimeoutSeconds = $script:Config.ExternalToolTimeoutSec; Retries = $script:Config.Retries; RetryDelaySeconds = $script:Config.RetryDelaySeconds }

    # ---- Forest-level sections ----
    if (Test-SectionSelected 'Forest' $Sections) {
        try { $sectionData['Forest Summary'] = @(Get-AdfaForestSummary -AdParams $adParams); $sectionStatus['Forest'] = 'ok' }
        catch { $sectionStatus['Forest'] = 'error'; Write-Warning $_.Exception.Message }
    }

    $allDcInventory = @()
    # Domains whose inventory call threw. Their DCs are in no list, so a section that reports
    # per DC must be told, or it looks complete while a whole domain is missing from it.
    $dcInventoryFailures = @()
    # Whether the inventory was asked for at all. A per-DC section that needs every scoped
    # domain's DCs (DcDisk, DcHardening) enumerates them itself when it was not.
    $dcInventoryCollected = $false
    # The DNS table (PORT-PLAN C13), shared by Dns, DnsAdConsistency, DomainControllers and the opt-in
    # DnsRecordExport: the file's table where it supplied one, validated before any section ran.
    $dnsConfig = $script:Config.Dns
    if ($configOverrides.ContainsKey('Dns')) { $dnsConfig = $configOverrides['Dns'] }
    if (Test-SectionSelected 'DomainControllers' $Sections) {
        $dcInventoryCollected = $true
        $inv = @()
        foreach ($d in $targetDomains) {
            try { $inv += Get-AdfaDomainControllerInventory -DomainName $d -AdParams $adParams }
            catch {
                Write-Warning ("DC inventory failed for {0}: {1}" -f $d, $_.Exception.Message)
                $dcInventoryFailures += [pscustomobject]@{ Domain = [string]$d; Error = $_.Exception.Message }
            }
        }
        $allDcInventory = $inv
        $sectionData['Domain Controllers'] = $inv
        # ADA-INV-016: each DC's DNS server list from its enabled adapters (read-only CIM). Its own
        # key, so the inventory rows keep the columns they had. The key is placed here, in its place
        # in the report; the adapters are read after the reachability classification below
        # (PORT-PLAN C14c), so a DC classified Unreachable is not probed by this read first.
        $sectionData['DC DNS Client'] = @()
    }
    $dcNames = @($allDcInventory | Select-Object -ExpandProperty HostName -ErrorAction SilentlyContinue)
    # Every per-DC section downstream reads $dcNames. When this fallback threw silently, all of
    # them reported "No domain controllers enumerated" and the actual cause - bad credentials, no
    # ADWS, a dead target DC - was discarded. The reason is captured so those sections can name
    # it, which is the difference between "this forest has no DCs" and "we could not ask".
    $script:DcEnumerationError = ''
    if ($dcNames.Count -eq 0) {
        try { $dcNames = @(Get-ADDomainController -Filter * @adParams | Select-Object -ExpandProperty HostName) }
        catch {
            $script:DcEnumerationError = $_.Exception.Message
            Write-Log -Level ERROR -Section 'DomainControllers' -Message ("Domain controller enumeration FAILED, so every per-DC section is unassessed rather than clean: {0}" -f $_.Exception.Message)
        }
    }
    if ($dcNames.Count -eq 0) {
        $whyNoDcs = 'No domain controllers could be enumerated.'
        if ($script:DcEnumerationError) { $whyNoDcs = ("Domain controller enumeration failed: {0}" -f $script:DcEnumerationError) }
        Write-Log -Level ERROR -Section 'DomainControllers' -Message $whyNoDcs
        # A first-class finding, so the report itself says the per-DC checks are unassessed.
        # Without this the only trace was each section's own terse "no DCs enumerated" line.
        $sectionData['Domain Controller Enumeration'] = @(New-Finding -Area 'DomainControllers' `
                -Item 'Domain controller enumeration' -Status $script:Status.NotAssessed `
                -Detail ("{0} Every per-DC check (replication, DNS consistency, ports, secure channels, DS events, diagnostics) is therefore UNASSESSED, not clean." -f $whyNoDcs))
    }

    # ---- DC reachability classes (PORT-PLAN C14, REACH-001/002) ----
    # Every DC is classified ONCE, here, before the first per-DC section: name resolution, LDAP (389),
    # then WinRM (5985) and RPC (135). The class is kept for the run and seeded into the shared port
    # cache, and the later sections that read it (Site Health, Time Hierarchy) say "Unreachable" with
    # the cause instead of probing again. The table the file supplied where it supplied one.
    $reachConfig = $script:Config.Reach
    if ($configOverrides.ContainsKey('Reach')) { $reachConfig = $configOverrides['Reach'] }
    # The DCs of EVERY scoped domain, each carrying its domain, exactly as DcDisk takes them.
    $c14Targets = @($allDcInventory)
    $c14Failures = @($dcInventoryFailures)
    if (-not $dcInventoryCollected -and ((Test-SectionSelected 'PortMatrix' $Sections) -or (Test-SectionSelected 'Topology' $Sections))) {
        $c14Enumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
        $c14Targets = @($c14Enumeration.Targets)
        $c14Failures = @($c14Enumeration.Failures)
    }
    if ($c14Targets.Count -eq 0) { $c14Targets = @($dcNames) }
    # ---- Inventory depth (PORT-PLAN C15, INV-001, INV-006..INV-012, INV-015) ----
    # The Inventory table the file supplied where it supplied one; read by Forest, Trusts, Identity, Gpo,
    # DsEvents and TimeHierarchy. The per-DC families (DNS suffix, events, W32Time configuration) take
    # the DCs of every scoped domain with their domains: the C14 targets where they were enumerated per
    # domain, otherwise enumerated here, as the C14 block does.
    $inventoryConfig = $script:Config.Inventory
    if ($configOverrides.ContainsKey('Inventory')) { $inventoryConfig = $configOverrides['Inventory'] }
    # PORT-PLAN C4b: the words the capped C4b rows use for where MaxObjects came from, read from the
    # provenance the merge recorded, so a cap the file set is never called a tool default.
    $inventoryCapSource = Get-AdfaCapSource -Config $inventoryConfig -BaseConfig $script:Config.Inventory -Key 'MaxObjects' -Label 'Inventory'
    $c15Targets = @($c14Targets)
    $c15Failures = @($c14Failures)
    $c14PerDomain = ($dcInventoryCollected -or (Test-SectionSelected 'PortMatrix' $Sections) -or (Test-SectionSelected 'Topology' $Sections))
    # Whether $c15Targets is a per-domain list (PORT-PLAN C2e reuses it rather than enumerating again).
    $c15PerDomain = $c14PerDomain
    if (-not $c14PerDomain -and ((Test-SectionSelected 'Forest' $Sections) -or (Test-SectionSelected 'DsEvents' $Sections) -or (Test-SectionSelected 'TimeHierarchy' $Sections))) {
        $c15PerDomain = $true
        $c15Enumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
        $c15Targets = @($c15Enumeration.Targets)
        $c15Failures = @($c15Enumeration.Failures)
        if ($c15Targets.Count -eq 0) { $c15Targets = @($dcNames) }
    }
    if (Test-SectionSelected 'Forest' $Sections) {
        Write-Stage 'Topology inventory (functional levels, FSMO holders, UPN and DNS suffixes, runner DC)'
        $sectionData['Topology Inventory'] = @(Get-AdfaTopologyInventory -ForestName ([string]$forest.Name) -RootDomain $rootDomain -Domains $targetDomains `
                -DomainControllers $c15Targets -InventoryFailures $c15Failures -ScopedDomains $targetDomains -ForestError $forestError -AdParams $adParams -Config $inventoryConfig)
    }
    $reachRows = @()
    if (Test-SectionSelected 'PortMatrix' $Sections) {
        Write-Stage 'DC reachability (name resolution, LDAP 389, WinRM 5985, RPC 135; once per DC, reused by Site Health and Time Hierarchy)'
        $reachRows = @(Get-AdfaDcReachabilityRows -DomainControllers $c14Targets -Config $reachConfig -InventoryFailures $c14Failures `
                -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains)
    }
    if ($dcInventoryCollected) {
        # ADA-INV-016, read after the classification (PORT-PLAN C14c): see the DomainControllers block,
        # which set $dcInventoryCollected exactly when DomainControllers is among -Sections.
        Write-Stage 'DC DNS client settings (enabled adapters, per DC)'
        $sectionData['DC DNS Client'] = @(Get-AdfaDcDnsClient -DomainControllers $allDcInventory -Config $dnsConfig -Credential $Credential `
                -PortTimeoutMs $script:Config.RpcPortTimeoutMs -OperationTimeoutSec $script:Config.ExternalToolTimeoutSec `
                -InventoryFailures $dcInventoryFailures -ScopedDomains $targetDomains -ForestComplete $scopeCoversForest)
    }

    # ---- Per-domain DC targets of the per-DC sections that took $dcNames (PORT-PLAN C2e) ----
    # Replication, SYSVOL shares and DFS Replication events, the patch-level half of DcSystem, Backup,
    # Time Hierarchy, the port matrix, Directory Service events, Restore Integrity, the DNS server set of
    # the four DNS-vs-AD sections and the raw repadmin/dcdiag captures used to take $dcNames, which with
    # DomainControllers not selected is one unscoped Get-ADDomainController against the default server:
    # the current domain's DCs only. They now take the DCs of EVERY scoped domain, each with its domain:
    # the per-domain list C14/C15 already hold where one exists, otherwise one enumeration here shared
    # by all of them (one Get-ADDomainController per domain per run), and the unscoped names last.
    $perDcTargets = @($c15Targets)
    $perDcFailures = @($c15Failures)
    $perDcSections = @('Replication', 'Sysvol', 'DcSystem', 'Backup', 'DnsAdConsistency', 'DsaCname', 'GcConsistency', 'MsdcsDelegation',
        'TimeHierarchy', 'PortMatrix', 'DsEvents', 'RestoreIntegrity')
    $perDcSelected = (@($perDcSections | Where-Object { Test-SectionSelected $_ $Sections }).Count -gt 0)
    if (-not $c15PerDomain -and ($perDcSelected -or $IncludeRepadmin -or $IncludeDcdiag)) {
        $perDcEnumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
        $perDcTargets = @($perDcEnumeration.Targets)
        $perDcFailures = @($perDcEnumeration.Failures)
    }
    if ($perDcTargets.Count -eq 0) { $perDcTargets = @($dcNames) }
    # The host names of those targets, in order, each once: the DNS server set and the DC count.
    $perDcHosts = @(Get-AdfaDcHostSet -Targets $perDcTargets)
    $perDcDnsServers = @($perDcHosts)
    # The scoped domains whose DCs are missing from those targets (enumeration threw, or returned no DC):
    # a check that compares a host with "the known DCs" cannot call it unknown while these are missing.
    # On a single-domain run the unscoped fallback names are that domain's DCs (Get-AdfaDomainDcHostName).
    $perDcGapDomains = @(@(Get-AdfaDcPopulationGap -Targets $perDcTargets -InventoryFailures $perDcFailures -ScopedDomains $targetDomains) |
        Where-Object { -not ([int]$_.WithoutDomain -gt 0 -and @($targetDomains).Count -eq 1) } | ForEach-Object { [string]$_.Domain })

    # A throw here used to drop the domain from the section silently - the same shape of defect
    # as the v1.6.0 multi-domain data loss, where a reader saw a shorter list and no error. Each
    # failure now becomes a row, so the section's own count reconciles with the domains scoped.
    if (Test-SectionSelected 'Domains' $Sections) {
        $ds = foreach ($d in $targetDomains) {
            try { Get-AdfaDomainSummary -DomainName $d -AdParams $adParams }
            catch {
                Write-Log -Level ERROR -Section $d -Message ("Domain summary failed: {0}" -f $_.Exception.Message)
                New-Finding -Scope $d -Area 'Domains' -Item ("Domain summary - {0}" -f $d) -Status $script:Status.NotAssessed `
                    -Detail ("Could not be read: {0}. Functional level, FSMO holders and the domain SID are unknown for this domain." -f $_.Exception.Message)
            }
        }
        $sectionData['Domain Summary'] = @($ds)
    }
    if (Test-SectionSelected 'Fsmo' $Sections) {
        $fs = foreach ($d in $targetDomains) {
            try { Get-AdfaFsmoRole -DomainName $d -AdParams $adParams }
            catch {
                Write-Log -Level ERROR -Section $d -Message ("FSMO role lookup failed: {0}" -f $_.Exception.Message)
                New-Finding -Scope $d -Area 'Fsmo' -Item ("FSMO roles - {0}" -f $d) -Status $script:Status.NotAssessed `
                    -Detail ("Could not be read: {0}. Role holders for this domain are unknown - do not conclude they are healthy." -f $_.Exception.Message)
            }
        }
        $sectionData['FSMO Roles'] = @($fs)
    }

    if (Test-SectionSelected 'Replication' $Sections) {
        Write-Stage 'Replication health'
        $sectionData['Replication Health'] = Get-AdfaReplicationHealth -DomainControllers $perDcTargets -RepParams $repParams -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs -StaleMinutes $script:Config.ReplicationStaleMinutes `
            -InventoryFailures $perDcFailures -ScopedDomains $targetDomains
        Write-Stage 'Replication cross-check (repadmin /showrepl * /csv)'
        $sectionData['Replication Cross-Check (repadmin)'] = Get-AdfaRepadminReplication -TimeoutSeconds 300 -Retries $script:Config.Retries -RetryDelaySeconds $script:Config.RetryDelaySeconds
        Write-Stage 'Replication convergence summary (repadmin /replsummary)'
        $sectionData['Replication Summary (repadmin)'] = Get-AdfaReplsummaryHealth -TimeoutSeconds 300 -Retries $script:Config.Retries -RetryDelaySeconds $script:Config.RetryDelaySeconds
    }

    $topology = $null
    if (Test-SectionSelected 'Topology' $Sections) {
        Write-Stage 'Topology'
        $topologyError = ''
        $siteRows = @()
        try {
            # PORT-PLAN C4b: declared lists for the site links and connection objects, capped at the
            # Inventory table's MaxObjects; each of those two reads fails on its own row.
            $topology = Get-AdfaReplicationTopology -AdParams $adParams -Config $script:Config.DirectoryRead -MaxObjects ([int]$inventoryConfig['MaxObjects']) -CapSource $inventoryCapSource
            $sectionData['AD Sites'] = $topology.Sites
            $sectionData['AD Subnets'] = $topology.Subnets
            $sectionData['Site Links'] = $topology.SiteLinks
            $sectionData['Replication Connections'] = $topology.Connections
            if ($allDcInventory.Count -gt 0) {
                $siteRows += @(Get-AdfaSiteHealthFinding -Topology $topology -DomainControllers $allDcInventory)
            }
        }
        catch {
            $topologyError = [string]$_.Exception.Message
            Write-Warning ("Topology failed: {0}" -f $topologyError)
            Write-Log -Level ERROR -Section 'Topology' -Message ("Topology read failed, so whether any subnet lacks a site is unknown: {0}" -f $topologyError)
        }
        # PORT-PLAN C14 (SITE-001): subnets without a site, outside the DC inventory gate, and the
        # clients each DC's netlogon.log names as mapped to no site. The table the file supplied where
        # it supplied one.
        $siteConfig = $script:Config.SiteCoverage
        if ($configOverrides.ContainsKey('SiteCoverage')) { $siteConfig = $configOverrides['SiteCoverage'] }
        $subnetList = @()
        if ($null -ne $topology) { $subnetList = @($topology.Subnets) }
        $siteForest = ''
        if (-not $forestError) { $siteForest = [string]$forest.Name }
        else { $topologyError = ("the forest could not be read ({0})" -f $forestError) }
        $siteRows += Get-AdfaSubnetSiteVerdict -Subnets $subnetList -ReadError $topologyError -ForestName $siteForest -Config $siteConfig
        Write-Stage 'Clients without a site (netlogon.log NO_CLIENT_SITE, per DC, read-only)'
        $siteRows += @(Get-AdfaClientSiteRows -DomainControllers $c14Targets -Config $siteConfig -PortTimeoutMs $script:Config.RpcPortTimeoutMs `
                -InventoryFailures $c14Failures -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains)
        $sectionData['Site Health'] = @($siteRows)
    }

    if (Test-SectionSelected 'Trusts' $Sections) {
        Write-Stage 'Trust health (two-way verification)'
        $trustRows = @()
        foreach ($d in $targetDomains) {
            $tp = @{} + $adParams; $tp.Server = $d
            $trustRows += Get-AdfaTrustHealth -DomainName $d -AdParams $tp -SkipVerification:$SkipTrustVerification -LiveVerify:$IncludeSecureChannelVerify `
                -TimeoutSeconds $script:Config.ExternalToolTimeoutSec -Retries $script:Config.Retries `
                -RetryDelaySeconds $script:Config.RetryDelaySeconds -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs `
                -PropertyNames @($script:Config.DirectoryRead['TrustHealthProperties']) -MaxObjects ([int]$inventoryConfig['MaxObjects']) -CapSource $inventoryCapSource
        }
        $sectionData['Trusts & Two-Way Health'] = $trustRows
        # PORT-PLAN C15 (INV-006): the trustedDomain objects of every scoped domain, read from that
        # domain with a listed attribute set and decoded by name; inventory only.
        Write-Stage 'Trust inventory (trustedDomain objects, per domain)'
        $sectionData['Trust Inventory'] = @(Get-AdfaTrustInventory -Domains $targetDomains -ForestError $forestError -AdParams $adParams -Config $inventoryConfig)
    }

    if (Test-SectionSelected 'DcDiagnostics' $Sections) {
        Write-Stage 'DC diagnostics (parsed: per DC, per domain, per forest, per site)'
        # The table the file supplied where it supplied one, otherwise the built-in table. The file
        # was validated before any section ran. It can set the time-out and retries only.
        $dcDiagConfig = $script:Config.DcDiag
        if ($configOverrides.ContainsKey('DcDiag')) { $dcDiagConfig = $configOverrides['DcDiag'] }
        # The DCs of EVERY scoped domain, each carrying its domain (and, from the inventory, its site
        # and whether it is read-only), exactly as RidPool takes them: the DC inventory where the
        # DomainControllers section ran; otherwise the section's own enumeration of each scoped
        # domain; last resort, the fallback host names, which carry no domain.
        $dcDiagTargets = @($allDcInventory)
        $dcDiagFailures = @($dcInventoryFailures)
        if (-not $dcInventoryCollected) {
            $dcDiagEnumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
            $dcDiagTargets = @($dcDiagEnumeration.Targets)
            $dcDiagFailures = @($dcDiagEnumeration.Failures)
        }
        if ($dcDiagTargets.Count -eq 0) { $dcDiagTargets = @($dcNames) }
        $sectionData['DC Diagnostics'] = @(Get-AdfaDcDiagnostic -DomainControllers $dcDiagTargets -IncludeActiveTests:$IncludeDcdiagActiveTests @ext -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs `
                -Config $dcDiagConfig -InventoryFailures $dcDiagFailures -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains -ForestRoot $rootDomain)
    }
    if (Test-SectionSelected 'Dns' $Sections) {
        Write-Stage 'DNS health (zone dynamic update, aging and scavenging, zone inventory; per DNS server)'
        # The DCs of EVERY scoped domain, each carrying its domain, exactly as DcDisk takes them: the
        # DC inventory where the DomainControllers section ran; otherwise the section's own
        # enumeration of each scoped domain; last resort, the fallback host names.
        $dnsTargets = @($allDcInventory)
        $dnsFailures = @($dcInventoryFailures)
        if (-not $dcInventoryCollected) {
            $dnsEnumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
            $dnsTargets = @($dnsEnumeration.Targets)
            $dnsFailures = @($dnsEnumeration.Failures)
        }
        # The fallback host names carry no domain, so a run on them never claims the forest's servers.
        $dnsForestComplete = $scopeCoversForest
        if ($dnsTargets.Count -eq 0) { $dnsTargets = @($dcNames); $dnsForestComplete = $false }
        $sectionData['DNS Health'] = @(Get-AdfaDnsHealth -DomainControllers $dnsTargets -Config $dnsConfig -Credential $Credential -PortTimeoutMs $script:Config.RpcPortTimeoutMs `
                -InventoryFailures $dnsFailures -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains -ForestComplete $dnsForestComplete)
    }
    if (Test-SectionSelected 'Sysvol' $Sections) {
        Write-Stage 'SYSVOL/DFSR'
        $sysvolRows = @(Get-AdfaSysvolHealth @ext)

        # Whether each DC is actually serving SYSVOL and NETLOGON. The vendor's own first
        # diagnostic for broken SYSVOL replication, and a common state after a restore: DFSR
        # does not share SYSVOL until the replicated folder has initialised.
        $sysvolRows += @(Get-AdfaSysvolShareHealth -DomainControllers $perDcTargets -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs -InventoryFailures $perDcFailures -ScopedDomains $targetDomains)

        # The two attributes a D2/D4-equivalent rebuild edits by hand, per KB 2218556. Read
        # per domain, because "exactly one member is authoritative" is a cross-DC rule that
        # cannot be checked from any single DC.
        foreach ($d in $targetDomains) {
            $domainDcs = @($allDcInventory | Where-Object {
                    $sc = $_.PSObject.Properties['Scope']   # $null when absent - StrictMode-safe
                    $null -ne $sc -and [string]$sc.Value -eq $d
                })
            $subs = @(Get-AdfaDfsrSubscription -DomainName $d -DomainControllers $domainDcs -AdParams $adParams)
            $sysvolRows += @(Get-AdfaDfsrSubscriptionVerdict -DomainName $d -Subscriptions $subs)
        }
        # PORT-PLAN C14 (SYSVOL-004): the SYSVOL replication engine of each DC and each scoped domain,
        # from the DFSR SYSVOL subscription and the NTFRS subscriber of every DC, read from its own
        # domain. The table the file supplied where it supplied one.
        $sysvolEngineConfig = $script:Config.SysvolEngine
        if ($configOverrides.ContainsKey('SysvolEngine')) { $sysvolEngineConfig = $configOverrides['SysvolEngine'] }
        if ($forestError) {
            $sysvolRows += New-AdfaC14Row -Area 'SYSVOL' -Item 'SYSVOL replication engine' -Status $script:Status.NotAssessed `
                -Detail ("The forest could not be read ({0}), so no domain was scoped and no SYSVOL subscription was read. This is not a clean result." -f $forestError)
        }
        else {
            foreach ($d in $targetDomains) {
                $engineRaw = Get-AdfaSysvolEngineRaw -DomainName $d -AdParams $adParams -Config $sysvolEngineConfig
                $sysvolRows += @(Get-AdfaSysvolEngineVerdict -DomainName $d -Raw $engineRaw -Config $sysvolEngineConfig)
            }
        }
        $sectionData['SYSVOL / DFSR'] = @($sysvolRows)

        Write-Stage 'DFS Replication events'
        $sectionData['DFS Replication Events'] = Get-AdfaDfsrEventLog -DomainControllers $perDcTargets -Credential $Credential `
            -LookbackDays $script:Config.DfsrEventLookbackDays -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs -InventoryFailures $perDcFailures -ScopedDomains $targetDomains

        if ($IncludeSysvolBacklog) {
            Write-Stage 'SYSVOL backlog (DFSR, both directions against each domain PDC)'
            $backlogRows = @()
            foreach ($d in $targetDomains) {
                # The PDC emulator is where Group Policy edits are normally written, so it is the
                # DC the others should be catching up with.
                $pdc = ''
                try { $pdc = [string](Get-ADDomain -Identity $d @adParams).PDCEmulator }
                catch {
                    Write-Log -Level ERROR -Section $d -Message ("PDC emulator lookup failed, so no SYSVOL backlog could be measured: {0}" -f $_.Exception.Message)
                    $backlogRows += New-Finding -Scope $d -Area 'SysvolBacklog' -Item 'SYSVOL backlog' -Status $script:Status.NotAssessed `
                        -Detail ("The PDC emulator could not be identified, so there was no reference DC to measure against: {0}" -f $_.Exception.Message)
                    continue
                }
                # PORT-PLAN C2e: this domain's own DCs only. The unscoped host names are taken only on a
                # single-domain run, where they are that domain's; a domain whose DCs could not be listed
                # gets a Not Assessed row with the cause, never another domain's DCs under its scope.
                $backlogPeers = Get-AdfaDomainDcHostName -Domain $d -Targets $perDcTargets -InventoryFailures $perDcFailures -ScopedDomains $targetDomains
                if (@($backlogPeers.HostNames).Count -eq 0) {
                    $backlogWhy = 'No domain controller of it was listed, so no SYSVOL backlog was measured.'
                    if ($null -ne $backlogPeers.Gap) { $backlogWhy = Get-AdfaDcPopulationGapText -Gap $backlogPeers.Gap -NothingRead 'No SYSVOL backlog of its domain controllers was measured.' }
                    $backlogRows += New-Finding -Scope $d -Area 'SysvolBacklog' -Item ("SYSVOL backlog (population): {0}" -f $d) -Status $script:Status.NotAssessed -Detail $backlogWhy
                    continue
                }
                $backlogRows += @(Get-AdfaSysvolBacklog -DomainName $d -ReferenceDc $pdc `
                        -DomainControllers @($backlogPeers.HostNames) -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs)
            }
            $sectionData['SYSVOL Backlog'] = @($backlogRows)
        }
    }
    if (Test-SectionSelected 'Gpo' $Sections) {
        Write-Stage 'GPO inventory'
        $g = foreach ($d in $targetDomains) { Get-AdfaGpoInventory -DomainName $d }
        # GPO version consistency (PORT-PLAN C8): per scoped domain, each GPO's version in the
        # directory against GPT.INI in SYSVOL, both read from the domain's PDC emulator. Appended
        # after the inventory rows, whose shape is unchanged. The table the file supplied where it
        # supplied one, otherwise the built-in table; the file was validated before any section ran.
        Write-Stage 'GPO version consistency (directory against SYSVOL, on each domain PDC)'
        $gpoConfig = $script:Config.Gpo
        if ($configOverrides.ContainsKey('Gpo')) { $gpoConfig = $configOverrides['Gpo'] }
        # With the forest unreadable there is no domain to scope, and the rows say so in one row
        # instead of asking whatever the default server is.
        if ($forestError) {
            $gpoVersionRows = @(New-AdfaGpoVersionRow -Item 'GPO version' -Status $script:Status.NotAssessed -Evidence 'none' `
                    -Detail ("The forest could not be read ({0}), so no domain was scoped and no GPO version was read. This is not a clean result." -f $forestError))
        }
        else {
            $gpoVersionRows = @(Get-AdfaGpoVersion -Domains $targetDomains -AdParams $adParams -Config $gpoConfig)
        }
        $sectionData['GPO Inventory'] = @(@($g) + @($gpoVersionRows))
        # PORT-PLAN C15 (INV-011): from the directory, without the GroupPolicy module - each GPO's
        # status flags, WMI filter and links, and the links of every site, domain and OU; inventory only.
        Write-Stage 'GPO directory inventory (status flags, WMI filters, links per site, domain and OU)'
        $sectionData['GPO Directory Inventory'] = @(Get-AdfaGpoDirectoryInventory -Domains $targetDomains -ForestDomains @($forest.Domains) -RootDomain $rootDomain -ForestError $forestError `
                -AdParams $adParams -Config $inventoryConfig -GpoConfig $gpoConfig)
    }
    if (Test-SectionSelected 'PasswordPolicy' $Sections) {
        $pp = foreach ($d in $targetDomains) { Get-AdfaPasswordPolicy -DomainName $d -AdParams $adParams }
        $sectionData['Password Policy'] = @($pp)
    }
    # Privileged groups and delegation (PORT-PLAN C10): the directory is read ONCE for the three sections
    # that use it - the privileged groups and their transitive membership (PrivilegedAccounts and
    # PrivilegedHygiene), the adminCount objects and dSHeuristics (PrivilegedHygiene), and the DC
    # population and delegation settings (Kerberos) - and each section builds its rows from that state.
    # The table the file supplied where it supplied one, otherwise the built-in table; the file was
    # validated before any section ran.
    $privConfig = $script:Config.Privileged
    if ($configOverrides.ContainsKey('Privileged')) { $privConfig = $configOverrides['Privileged'] }
    $privParts = @()
    if (Test-SectionSelected 'PrivilegedAccounts' $Sections) { $privParts += 'Groups' }
    if (Test-SectionSelected 'PrivilegedHygiene' $Sections) { $privParts += @('Groups', 'Hygiene') }
    if (Test-SectionSelected 'Kerberos' $Sections) { $privParts += 'Delegation' }
    $privState = $null
    if (@($privParts).Count -gt 0 -and -not $forestError) {
        Write-Stage 'Privileged groups and delegation (directory reads for three sections)'
        $privState = Get-AdfaPrivilegedState -Domains $targetDomains -ForestDomains @($forest.Domains) -RootDomain $rootDomain -AdParams $adParams -Config $privConfig -Parts $privParts
    }
    if (Test-SectionSelected 'PrivilegedAccounts' $Sections) {
        # With the forest unreadable there is no domain to scope, and the rows say so in one row instead of
        # asking whatever the default server is.
        if ($forestError) {
            $paRows = @(New-AdfaPrivilegedRow -Area 'Privileged' -Item 'Privileged groups' -Status $script:Status.NotAssessed -Evidence 'none' `
                    -Detail ("The forest could not be read ({0}), so no domain was scoped and no privileged group was read. This is not a clean result." -f $forestError))
        }
        else {
            $paRows = @(Get-AdfaPrivilegedAccount -State $privState -Config $privConfig)
        }
        $sectionData['Privileged Accounts'] = @($paRows)
    }
    if (Test-SectionSelected 'SecurityPosture' $Sections) {
        Write-Stage 'Security posture'
        $sp = foreach ($d in $targetDomains) { Get-AdfaSecurityPosture -DomainName $d -IsRootDomain:($d -eq $rootDomain) -AdParams $adParams -KrbtgtMaxAgeDays $script:Config.KrbtgtMaxAgeDays }
        # SID history (PORT-PLAN C7): four rows per scoped domain, directory reads only. The table
        # the file supplied where it supplied one, otherwise the built-in table; the file was
        # validated before any section ran.
        $sidHistoryConfig = $script:Config.SidHistory
        if ($configOverrides.ContainsKey('SidHistory')) { $sidHistoryConfig = $configOverrides['SidHistory'] }
        # With the forest unreadable there is no domain to scope and no forest domain SID to read,
        # and the rows say so in one row instead of asking whatever the default server is.
        if ($forestError) {
            $sidHistoryRows = @(New-AdfaSidHistoryRow -Item 'SID history' -Status $script:Status.NotAssessed -Evidence 'none' `
                    -Detail ("The forest could not be read ({0}), so no domain was scoped and no security principal was read for sIDHistory. This is not a clean result." -f $forestError))
        }
        else {
            $sidHistoryRows = @(Get-AdfaSidHistory -Domains $targetDomains -ForestDomains @($forest.Domains) -AdParams $adParams -Config $sidHistoryConfig)
        }
        $sectionData['Security Posture'] = @(@($sp) + @($sidHistoryRows))
    }
    if (Test-SectionSelected 'StaleObjects' $Sections) {
        # PORT-PLAN C14 (STALE-001/002): per scoped domain, a listed-property, capped read of the
        # enabled users and computers with no logon recorded for -StaleDays, never-logged-on ones
        # included, and of the enabled users with an old password. The table the file supplied where
        # it supplied one.
        Write-Stage 'Stale enabled objects (lastLogonTimestamp, pwdLastSet; per domain)'
        $staleConfig = $script:Config.Stale
        if ($configOverrides.ContainsKey('Stale')) { $staleConfig = $configOverrides['Stale'] }
        $staleNow = Get-Date
        $so = @()
        if ($forestError) {
            $so += New-AdfaC14Row -Area 'Stale' -Item 'Stale objects' -Status $script:Status.NotAssessed `
                -Detail ("The forest could not be read ({0}), so no domain was scoped and no account was read. This is not a clean result." -f $forestError)
        }
        foreach ($d in $targetDomains) { $so += @(Get-AdfaStaleObject -DomainName $d -AdParams $adParams -StaleDays $script:Config.StaleDays -Config $staleConfig -Now $staleNow) }
        $sectionData['Stale Objects'] = @($so)
    }

    # ---- Deep security & reliability ----
    if (Test-SectionSelected 'Pki' $Sections) {
        Write-Stage 'AD CS / PKI (ESC1 heuristic)'
        $sectionData['PKI / AD CS'] = Get-AdfaPkiHealth -AdParams $adParams
    }
    if (Test-SectionSelected 'Acl' $Sections) {
        # Dangerous rights (PORT-PLAN C9): per scoped domain, the domain head's replication and control
        # rights, AdminSDHolder and every GPO, from nTSecurityDescriptor, matched by SID against an
        # allowlist. The table the file supplied where it supplied one, otherwise the built-in table;
        # the file was validated before any section ran.
        Write-Stage 'Dangerous ACLs (replication and control rights on the domain head, AdminSDHolder and GPOs)'
        $aclConfig = $script:Config.Acl
        if ($configOverrides.ContainsKey('Acl')) { $aclConfig = $configOverrides['Acl'] }
        # With the forest unreadable there is no domain to scope and no forest root SID to read, and the
        # rows say so in one row instead of asking whatever the default server is.
        if ($forestError) {
            $aclRows = @(New-AdfaAclRow -Item 'Dangerous ACLs' -Status $script:Status.NotAssessed -Evidence 'none' `
                    -Detail ("The forest could not be read ({0}), so no domain was scoped and no security descriptor was read. This is not a clean result." -f $forestError))
        }
        else {
            $aclRows = @(Get-AdfaDangerousAcl -Domains $targetDomains -RootDomain $rootDomain -AdParams $adParams -Config $aclConfig)
        }
        $sectionData['Dangerous ACLs (DCSync)'] = @($aclRows)
    }
    if (Test-SectionSelected 'Kerberos' $Sections) {
        Write-Stage 'Kerberos exposure (roasting / delegation)'
        if ($forestError) {
            $kRows = @(New-AdfaPrivilegedRow -Area 'Kerberos' -Item 'Kerberos exposure' -Status $script:Status.NotAssessed -Evidence 'none' `
                    -Detail ("The forest could not be read ({0}), so no domain was scoped and no account was read. This is not a clean result." -f $forestError))
        }
        else {
            $kRows = @(Get-AdfaKerberosExposure -State $privState -Config $privConfig)
        }
        $sectionData['Kerberos Exposure'] = @($kRows)
    }
    if (Test-SectionSelected 'PrivilegedHygiene' $Sections) {
        Write-Stage 'Privileged hygiene'
        if ($forestError) {
            $phRows = @(New-AdfaPrivilegedRow -Area 'PrivHygiene' -Item 'Privileged hygiene' -Status $script:Status.NotAssessed -Evidence 'none' `
                    -Detail ("The forest could not be read ({0}), so no domain was scoped and no privileged account was read. This is not a clean result." -f $forestError))
        }
        else {
            $phRows = @(Get-AdfaPrivilegedHygiene -State $privState -Config $privConfig)
        }
        $sectionData['Privileged Hygiene'] = @($phRows)
    }
    if (Test-SectionSelected 'DcHardening' $Sections) {
        Write-Stage 'DC hardening (LDAP signing and channel binding, SMB signing, LAN Manager level, Print Spooler, SMBv1; per DC)'
        # The table the file supplied where it supplied one, otherwise the built-in table. The
        # file was validated before any section ran.
        $dcHardeningConfig = $script:Config.DcHardening
        if ($configOverrides.ContainsKey('DcHardening')) { $dcHardeningConfig = $configOverrides['DcHardening'] }
        # The DCs of EVERY scoped domain, each carrying its domain, exactly as DcDisk takes them
        # (PORT-PLAN C2e): the DC inventory where the DomainControllers section ran; otherwise
        # the section's own enumeration of each scoped domain, because $dcNames then holds only
        # what one unscoped call against the default server returned - the current domain's DCs.
        $dcHardeningTargets = @($allDcInventory)
        $dcHardeningFailures = @($dcInventoryFailures)
        if (-not $dcInventoryCollected) {
            $dcHardeningEnumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
            $dcHardeningTargets = @($dcHardeningEnumeration.Targets)
            $dcHardeningFailures = @($dcHardeningEnumeration.Failures)
        }
        # Last resort, when no scoped domain gave a single DC: the host names the fallback
        # enumeration found. They carry no domain, and the section says so for each domain.
        if ($dcHardeningTargets.Count -eq 0) { $dcHardeningTargets = @($dcNames) }
        $sectionData['DC Hardening'] = @(Get-AdfaDcHardening -DomainControllers $dcHardeningTargets -Config $dcHardeningConfig -Credential $Credential `
                -PortTimeoutMs $script:Config.RpcPortTimeoutMs -OperationTimeoutSec $script:Config.ExternalToolTimeoutSec `
                -InventoryFailures $dcHardeningFailures -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains)
    }
    if (Test-SectionSelected 'DcSystem' $Sections) {
        Write-Stage 'DC system (OS lifecycle; build, uptime and last update per DC)'
        # As with the Exchange SE table, an override that cannot be read is fatal rather than
        # swallowed.
        $dcSystemConfig = $script:Config.DcSystem
        if ($DcSystemConfigPath) {
            $dcSystemConfig = Import-AdfaDcSystemConfig -BaseConfig $script:Config.DcSystem -Path $DcSystemConfigPath
            Write-Log -Level INFO ("DC system table overridden from {0}" -f $DcSystemConfigPath)
        }
        $dcSystemRows = @()
        # The lifecycle rows read only the inventory (directory attributes); the patch-level
        # rows read each DC. They are separate so that a run without rights on the DCs still
        # gets a lifecycle verdict for every one of them.
        $dcSystemRows += Get-AdfaDcOsLifecycle -DomainControllers $allDcInventory -Config $dcSystemConfig -Today (Get-Date) `
            -InventoryFailures $dcInventoryFailures
        $dcSystemRows += Get-AdfaDcPatchLevel -DomainControllers $perDcTargets -Config $dcSystemConfig -Credential $Credential `
            -PortTimeoutMs $script:Config.RpcPortTimeoutMs -OperationTimeoutSec $script:Config.ExternalToolTimeoutSec -InventoryFailures $perDcFailures -ScopedDomains $targetDomains
        $sectionData['DC System'] = @($dcSystemRows)
    }
    if (Test-SectionSelected 'DcDisk' $Sections) {
        Write-Stage 'DC disk space (NTDS database, NTDS log and SYSVOL volumes, per DC)'
        # The table the file supplied where it supplied one, otherwise the built-in table. The
        # file was validated before any section ran.
        $dcDiskConfig = $script:Config.DcDisk
        if ($configOverrides.ContainsKey('DcDisk')) { $dcDiskConfig = $configOverrides['DcDisk'] }
        # The DCs of EVERY scoped domain, each carrying its domain. Where the DomainControllers
        # section ran, that is its inventory. Where it did not, $allDcInventory is empty and
        # $dcNames holds only what one unscoped call against the default server returned - the
        # current domain's DCs - so on a run with -AllDomains every other domain would be
        # missing from this section with no row to say so. The section therefore enumerates the
        # scoped domains itself in that case.
        $dcDiskTargets = @($allDcInventory)
        $dcDiskFailures = @($dcInventoryFailures)
        if (-not $dcInventoryCollected) {
            $dcDiskEnumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
            $dcDiskTargets = @($dcDiskEnumeration.Targets)
            $dcDiskFailures = @($dcDiskEnumeration.Failures)
        }
        # Last resort, when no scoped domain gave a single DC: the host names the fallback
        # enumeration found. They carry no domain, and the section says so for each domain.
        if ($dcDiskTargets.Count -eq 0) { $dcDiskTargets = @($dcNames) }
        $sectionData['DC Disk Space'] = @(Get-AdfaDcDiskSpace -DomainControllers $dcDiskTargets -Config $dcDiskConfig -Credential $Credential `
                -PortTimeoutMs $script:Config.RpcPortTimeoutMs -OperationTimeoutSec $script:Config.ExternalToolTimeoutSec `
                -InventoryFailures $dcDiskFailures -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains)
    }
    if (Test-SectionSelected 'Laps' $Sections) {
        Write-Stage 'Windows LAPS (schema, DSRM password backup per DC, computers with no LAPS expiry time visible; directory reads only)'
        # The table the file supplied where it supplied one, otherwise the built-in table. The
        # file was validated before any section ran.
        $lapsConfig = $script:Config.Laps
        if ($configOverrides.ContainsKey('Laps')) { $lapsConfig = $configOverrides['Laps'] }
        # Directory reads only, per scoped domain: this section takes no DC list and connects to
        # no DC. With the forest unreadable there is no schema to ask and no domain to scope, and
        # the section says so in one row instead of querying whatever the default server is.
        if ($forestError) {
            $sectionData['Windows LAPS'] = @(New-AdfaLapsRow -Item 'Windows LAPS' -Status $script:Status.NotAssessed `
                    -Detail ("The forest could not be read ({0}), so neither the schema nor any computer account was read. This is not a clean result." -f $forestError))
        }
        else {
            # The stale threshold is the one the StaleObjects section uses (-StaleDays); there is
            # no second one.
            $sectionData['Windows LAPS'] = @(Get-AdfaLaps -Domains $targetDomains -AdParams $adParams -Config $lapsConfig `
                    -StaleDays $script:Config.StaleDays -Now (Get-Date) -ForestName ([string]$forest.Name))
        }
    }
    if (Test-SectionSelected 'DcCertificates' $Sections) {
        Write-Stage 'DC certificates (certificates published in the directory per DC; the LDAPS certificate each DC presents with -IncludeLdapsHandshake)'
        # The table the file supplied where it supplied one, otherwise the built-in table. The
        # file was validated before any section ran.
        $dcCertificatesConfig = $script:Config.DcCertificates
        if ($configOverrides.ContainsKey('DcCertificates')) { $dcCertificatesConfig = $configOverrides['DcCertificates'] }
        # The DCs of EVERY scoped domain, each carrying its domain, exactly as DcDisk and
        # DcHardening take them (PORT-PLAN C2e): the DC inventory where the DomainControllers
        # section ran; otherwise the section's own enumeration of each scoped domain.
        $dcCertificatesTargets = @($allDcInventory)
        $dcCertificatesFailures = @($dcInventoryFailures)
        if (-not $dcInventoryCollected) {
            $dcCertificatesEnumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
            $dcCertificatesTargets = @($dcCertificatesEnumeration.Targets)
            $dcCertificatesFailures = @($dcCertificatesEnumeration.Failures)
        }
        # Last resort, when no scoped domain gave a single DC: the host names the fallback
        # enumeration found. They carry no domain, and the section says so for each domain.
        if ($dcCertificatesTargets.Count -eq 0) { $dcCertificatesTargets = @($dcNames) }
        $sectionData['DC Certificates'] = @(Get-AdfaDcCertificates -DomainControllers $dcCertificatesTargets -Config $dcCertificatesConfig -AdParams $adParams `
                -PortTimeoutMs $script:Config.RpcPortTimeoutMs -Now (Get-Date) -IncludeHandshake ([bool]$IncludeLdapsHandshake) `
                -InventoryFailures $dcCertificatesFailures -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains)
    }
    if (Test-SectionSelected 'RidPool' $Sections) {
        Write-Stage 'RID pool (allocation and global RID space per domain, the RID pool of each DC; directory reads only)'
        # The table the file supplied where it supplied one, otherwise the built-in table. The
        # file was validated before any section ran.
        $ridPoolConfig = $script:Config.RidPool
        if ($configOverrides.ContainsKey('RidPool')) { $ridPoolConfig = $configOverrides['RidPool'] }
        # With the forest unreadable there is no domain to scope, and the section says so in one
        # row instead of asking whatever the default server is, as the Laps section does.
        if ($forestError) {
            $sectionData['RID Pool'] = @(New-AdfaRidPoolRow -Item 'RID pool' -Status $script:Status.NotAssessed -Evidence 'none' `
                    -Detail ("The forest could not be read ({0}), so no domain was scoped and neither CN=RID Manager`$ nor any RID Set was read. This is not a clean result." -f $forestError))
        }
        else {
            # The DCs of EVERY scoped domain, each carrying its domain, exactly as DcCertificates
            # takes them: the DC inventory where the DomainControllers section ran; otherwise the
            # section's own enumeration of each scoped domain.
            $ridPoolTargets = @($allDcInventory)
            $ridPoolFailures = @($dcInventoryFailures)
            if (-not $dcInventoryCollected) {
                $ridPoolEnumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
                $ridPoolTargets = @($ridPoolEnumeration.Targets)
                $ridPoolFailures = @($ridPoolEnumeration.Failures)
            }
            # Last resort, when no scoped domain gave a single DC: the host names the fallback
            # enumeration found. They carry no domain, and the section says so for each domain.
            if ($ridPoolTargets.Count -eq 0) { $ridPoolTargets = @($dcNames) }
            $sectionData['RID Pool'] = @(Get-AdfaRidPool -DomainControllers $ridPoolTargets -Config $ridPoolConfig -AdParams $adParams `
                    -InventoryFailures $ridPoolFailures -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains)
        }
    }
    if (Test-SectionSelected 'Backup' $Sections) {
        Write-Stage 'Directory backup status (per DC)'
        $sectionData['Backup Status'] = Get-AdfaBackupStatus -DomainControllers $perDcTargets -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs -InventoryFailures $perDcFailures -ScopedDomains $targetDomains @ext
    }
    if (Test-SectionSelected 'TimeSync' $Sections) {
        Write-Stage 'Time synchronization'
        $sectionData['Time Sync'] = Get-AdfaTimeSync -TimeoutSeconds $script:Config.ExternalToolTimeoutSec
    }
    if (Test-SectionSelected 'DnsDepth' $Sections) {
        Write-Stage 'DNS depth (SRV / secure updates)'
        $ddRows = foreach ($d in $targetDomains) { Get-AdfaDnsDepth -DomainName $d -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs }
        $sectionData['DNS Depth'] = @($ddRows)
    }
    if (Test-SectionSelected 'Redundancy' $Sections) {
        Write-Stage 'Redundancy / availability'
        $rdRows = foreach ($d in $targetDomains) { Get-AdfaRedundancy -DomainName $d -AdParams $adParams }
        $sectionData['Redundancy & Availability'] = @($rdRows)
    }

    # ---- Recovery & consistency (post-incident) ----
    if (Test-SectionSelected 'DnsAdConsistency' $Sections) {
        Write-Stage 'DNS vs AD consistency (per DNS server; per DC: locator records, A records, records naming no DC)'
        # The NTDS Settings objects of the forest, read once: the DCs a locator record may name and
        # the DSA GUIDs a <guid>._msdcs CNAME may carry (PORT-PLAN C13).
        $dnsDsa = @()
        $dnsDsaError = ''
        try { $dnsDsa = @(Get-AdfaDsaInventory -AdParams $adParams) }
        catch {
            $dnsDsaError = [string]$_.Exception.Message
            Write-Log -Level ERROR -Section 'DnsAdConsistency' -Message ("DSA inventory failed, so no <guid>._msdcs CNAME can be judged: {0}" -f $dnsDsaError)
        }
        $dacRows = foreach ($d in $targetDomains) {
            Get-AdfaDnsAdConsistency -DomainName $d -AdParams $adParams -DnsServers $perDcDnsServers -Config $dnsConfig -ForestRoot $rootDomain -DsaInventory $dnsDsa -DsaError $dnsDsaError `
                -Credential $Credential -PortTimeoutMs $script:Config.RpcPortTimeoutMs -OperationTimeoutSec $script:Config.ExternalToolTimeoutSec
        }
        $sectionData['DNS vs AD Consistency'] = @($dacRows)
    }
    if (Test-SectionSelected 'DsaCname' $Sections) {
        Write-Stage 'DSA GUID CNAME records (_msdcs, per DNS server)'
        $sectionData['DSA GUID CNAMEs'] = Get-AdfaDsaGuidCname -ForestRoot $forest.Name -AdParams $adParams -DnsServers $perDcDnsServers
    }
    if (Test-SectionSelected 'GcConsistency' $Sections) {
        Write-Stage 'Global Catalog consistency (AD flag vs DNS, per DNS server)'
        $sectionData['Global Catalog Consistency'] = Get-AdfaGcConsistency -ForestRoot $forest.Name -AdParams $adParams -DnsServers $perDcDnsServers
    }
    if (Test-SectionSelected 'MsdcsDelegation' $Sections) {
        Write-Stage 'Forest-wide locator zone delegation (_msdcs, per DNS server)'
        # Without a forest name there is no zone name to query, and building one from the
        # placeholder would put a nonsense zone in the report.
        if ($forestError) {
            $sectionData['_msdcs Zone Delegation'] = @(New-Finding -Area 'MsdcsDelegation' -Item 'Forest-wide locator zone' -Status $script:Status.NotAssessed `
                    -Detail 'The forest name could not be read, so the name of the forest-wide locator zone is unknown and its delegation was not queried.')
        }
        else {
            $sectionData['_msdcs Zone Delegation'] = @(Get-AdfaMsdcsDelegation -ForestRoot $forest.Name `
                    -DnsServers $perDcDnsServers -AdDcHosts $perDcHosts -IncompleteDomains $perDcGapDomains)
        }
    }
    if (Test-SectionSelected 'TimeHierarchy' $Sections) {
        Write-Stage 'Time hierarchy (per-DC source, PDC emulator roles)'
        # The PDC emulator of each scoped domain, plus the forest root's, so the role-specific
        # rules can be applied. A domain whose PDC cannot be read leaves its DCs graded as
        # ordinary DCs, and the collector says so rather than assuming.
        $pdcMap = @{}
        $rootPdc = ''
        $pdcErrors = @()
        $pdcDomains = @($targetDomains)
        if ($rootDomain -and $pdcDomains -notcontains $rootDomain) { $pdcDomains += $rootDomain }
        foreach ($d in $pdcDomains) {
            try {
                $pdc = [string](Get-ADDomain -Identity $d @adParams).PDCEmulator
                if ($pdc) {
                    $pdcMap[$pdc] = $d
                    if ($d -eq $rootDomain) { $rootPdc = $pdc }
                }
            }
            catch {
                $pdcErrors += ("{0}: {1}" -f $d, $_.Exception.Message)
                Write-Log -Level ERROR -Section $d -Message ("PDC emulator lookup failed, so the time-hierarchy role rules could not be applied to that domain: {0}" -f $_.Exception.Message)
            }
        }
        # The ClockSkew table the file supplied where it supplied one (PORT-PLAN C14): WarnSeconds and
        # Samples only; the Kerberos maximum is never taken from a file.
        $clockConfig = $script:Config.ClockSkew
        if ($configOverrides.ContainsKey('ClockSkew')) { $clockConfig = $configOverrides['ClockSkew'] }
        $timeRows = @(Get-AdfaTimeHierarchyHealth -DomainControllers $perDcTargets -InventoryFailures $perDcFailures -ScopedDomains $targetDomains -PdcEmulators $pdcMap `
                -ForestRootPdc $rootPdc -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs `
                -TimeoutSeconds $script:Config.ExternalToolTimeoutSec `
                -SkewSamples $clockConfig.Samples `
                -WarnSeconds $clockConfig.WarnSeconds `
                -FailSeconds $clockConfig.KerberosMaxSeconds -ThresholdSource ([string]$clockConfig['ThresholdSource']))
        if (@($pdcErrors).Count -gt 0) {
            $timeRows += New-Finding -Area 'TimeHierarchy' -Item 'PDC emulator resolution' -Status $script:Status.NotAssessed `
                -Detail ("The PDC emulator could not be read for {0} domain(s), so the role-specific time rule was not applied there: {1}. Those DCs were graded as ordinary domain controllers, which is a partial result." -f @($pdcErrors).Count, (@($pdcErrors) -join '; '))
        }
        $sectionData['Time Hierarchy'] = @($timeRows)
        # PORT-PLAN C15 (INV-015): Type, NtpServer and AnnounceFlags of every DC, read from the registry
        # through the shared CIM transport loop; inventory only, no expected value.
        Write-Stage 'W32Time configuration (Type, NtpServer, AnnounceFlags; per DC, read-only)'
        $sectionData['Time Configuration'] = @(Get-AdfaW32TimeInventory -DomainControllers $c15Targets -InventoryFailures $c15Failures -ScopedDomains $targetDomains `
                -EnumerationError $script:DcEnumerationError -Credential $Credential -PortTimeoutMs $script:Config.RpcPortTimeoutMs `
                -OperationTimeoutSec $script:Config.ExternalToolTimeoutSec -Config $inventoryConfig)
    }
    if (Test-SectionSelected 'SiteGc' $Sections) {
        Write-Stage 'Writeable global catalog coverage per site'
        $sectionData['Site Global Catalog Coverage'] = @(Get-AdfaSiteGcCoverage -DomainControllers $allDcInventory)
    }
    if (Test-SectionSelected 'PortMatrix' $Sections) {
        Write-Stage 'Port reachability matrix (replication port set)'
        # PORT-PLAN C14: the reachability class of each DC, classified once before the first per-DC
        # section, then the port matrix rows, unchanged.
        $sectionData['Port Reachability'] = @(@($reachRows) + @(Get-AdfaPortMatrix -DomainControllers $perDcTargets -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs))
    }
    if (Test-SectionSelected 'DcSecureChannel' $Sections) {
        Write-Stage 'DC machine-account passwords & secure channels'
        $scRows = foreach ($d in $targetDomains) {
            Get-AdfaDcSecureChannel -DomainName $d -AdParams $adParams -Credential $Credential -LiveVerify:$IncludeSecureChannelVerify `
                -WarnDays $script:Config.DcPasswordWarnDays -FailDays $script:Config.DcPasswordFailDays `
                -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs
        }
        $sectionData['DC Secure Channel & Machine Passwords'] = @($scRows)
    }
    if (Test-SectionSelected 'DsEvents' $Sections) {
        Write-Stage 'Directory Service event log (lingering / rollback / DNS failures)'
        $sectionData['Directory Service Events'] = Get-AdfaDsEventLog -DomainControllers $perDcTargets -Credential $Credential `
            -LookbackDays $script:Config.DsEventLookbackDays -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs -InventoryFailures $perDcFailures -ScopedDomains $targetDomains
        # PORT-PLAN C15 (INV-012): every configured log of every DC, by level (Critical, Error, Warning),
        # bounded by -EventLookbackDays and EventMaxEvents, grouped by event ID; inventory only.
        Write-Stage 'Event inventory (Critical, Error and Warning per log and DC; bounded reads)'
        $sectionData['Event Inventory'] = @(Get-AdfaEventInventory -DomainControllers $c15Targets -InventoryFailures $c15Failures -ScopedDomains $targetDomains `
                -EnumerationError $script:DcEnumerationError -LookbackDays $script:Config.DsEventLookbackDays -Credential $Credential `
                -PortTimeoutMs $script:Config.RpcPortTimeoutMs -Config $inventoryConfig)
    }
    if (Test-SectionSelected 'RestoreIntegrity' $Sections) {
        Write-Stage 'Restore integrity (USN rollback forensics, database instantiation)'
        $riRows = @()
        # The registry marker first: it is the only restore-integrity signal that does not depend
        # on the Directory Service log still holding the event, which on a recovered forest it
        # frequently does not.
        $riRows += @(Get-AdfaUsnRollbackForensics -DomainControllers $perDcTargets -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs -InventoryFailures $perDcFailures -ScopedDomains $targetDomains)
        try {
            $riRows += @(Get-AdfaInvocationIdVerdict -DsaInventory (Get-AdfaDsaInventory -AdParams $adParams))
        }
        catch {
            Write-Log -Level ERROR -Section 'RestoreIntegrity' -Message ("DSA inventory failed, so database instantiation could not be checked: {0}" -f $_.Exception.Message)
            $riRows += New-Finding -Area 'RestoreIntegrity' -Item 'Database instantiation (invocationId)' -Status $script:Status.NotAssessed `
                -Detail ("The DSA inventory could not be read, so database instantiation identity is unknown: {0}" -f $_.Exception.Message)
        }
        $sectionData['Restore Integrity'] = @($riRows)
    }

    if ($IncludeLingeringObjectScan) {
        Write-Stage 'Lingering object scan (repadmin advisory mode - no changes)'
        $loRows = foreach ($d in $targetDomains) {
            Get-AdfaLingeringObjectScan -DomainName $d -AdParams $adParams -TimeoutSeconds 300 -RpcPortTimeoutMs $script:Config.RpcPortTimeoutMs
        }
        $sectionData['Lingering Object Scan (advisory)'] = @($loRows)
    }

    if (Test-SectionSelected 'ExchangeSchema' $Sections) {
        $sectionData['Exchange Schema Markers'] = Get-AdfaExchangeSchemaMarker -AdParams $adParams
    }

    if (Test-SectionSelected 'ExchangeSeReadiness' $Sections) {
        Write-Stage 'Exchange Server SE compatibility (forest level + DC operating systems)'
        # An override that cannot be read is fatal here rather than swallowed: the alternative
        # is judging the forest against the built-in table while the operator believes theirs
        # is in force.
        $seConfig = $script:Config.ExchangeSe
        if ($ExchangeSeConfigPath) {
            $seConfig = Import-AdfaExchangeSeConfig -BaseConfig $script:Config.ExchangeSe -Path $ExchangeSeConfigPath
            Write-Log -Level INFO ("Exchange SE prerequisite table overridden from {0}" -f $ExchangeSeConfigPath)
        }
        $forestMode = ''
        if ($null -ne $forest) {
            $fmProp = $forest.PSObject.Properties['ForestMode']   # $null when absent - StrictMode-safe
            if ($null -ne $fmProp -and $null -ne $fmProp.Value) { $forestMode = [string]$fmProp.Value }
        }
        # The numeric level is what the verdict reads. When the forest itself was unreadable
        # there is no Partitions container to ask, and the cause is the forest error.
        $forestLevel = ''
        $forestLevelError = ''
        if ($forestError) { $forestLevelError = ("The forest could not be read: {0}" -f $forestError) }
        else {
            $bv = Get-AdfaForestBehaviorVersion -Forest $forest -AdParams $adParams
            $forestLevel = [string]$bv.Level
            $forestLevelError = [string]$bv.Error
            if ($forestLevelError) { Write-Log -Level WARN -Section 'ExchangeSeReadiness' -Message $forestLevelError }
        }
        $sectionData['Exchange SE Compatibility'] = Get-AdfaExchangeSeCompatibility -ForestMode $forestMode `
            -ForestLevel $forestLevel -ForestLevelError $forestLevelError `
            -DomainSummaries $sectionData['Domain Summary'] -DomainControllers $allDcInventory -SeConfig $seConfig
    }

    # ---- User and computer export (declared attribute lists) -> CSV; HTML gets a summary only ----
    if (Test-SectionSelected 'Identity' $Sections) {
        Write-Stage 'Identity inventory (user/computer export, declared attribute lists)'
        $identitySummary = @()
        # PORT-PLAN C4b: each domain's users and computers are read with the declared lists of the
        # DirectoryRead table, never every attribute, capped at the Inventory table's MaxObjects (the
        # table the file supplied where it supplied one). A failed, refused, empty or capped read is
        # carried to the summary as its cause (PORT-PLAN C15: Not Assessed, never 0).
        $exportConfig = $script:Config.DirectoryRead
        $exportSecrets = @(Get-AdfaSecretAttributeName)
        $exportMax = [int]$inventoryConfig['MaxObjects']
        foreach ($d in $targetDomains) {
            $userExport = ConvertTo-AdfaIdentityExport -Kind User -Columns @($exportConfig['UserExportProperties']) -MaxObjects $exportMax -AccountDisableBit ([int]$inventoryConfig['AccountDisableBit']) -CapSource $inventoryCapSource `
                -Raw (Get-AdfaIdentityExportRaw -DomainName $d -Kind User -Config $exportConfig -SecretNames $exportSecrets -MaxObjects $exportMax -AdParams $adParams)
            $computerExport = ConvertTo-AdfaIdentityExport -Kind Computer -Columns @($exportConfig['ComputerExportProperties']) -MaxObjects $exportMax -AccountDisableBit ([int]$inventoryConfig['AccountDisableBit']) -CapSource $inventoryCapSource `
                -Raw (Get-AdfaIdentityExportRaw -DomainName $d -Kind Computer -Config $exportConfig -SecretNames $exportSecrets -MaxObjects $exportMax -AdParams $adParams)
            $users = @($userExport.Rows); $computers = @($computerExport.Rows)
            $usersError = [string]$userExport.Cause; $computersError = [string]$computerExport.Cause
            if ($usersError) { Write-Warning ("User export for {0}: {1}" -f $d, $usersError) }
            if ($computersError) { Write-Warning ("Computer export for {0}: {1}" -f $d, $computersError) }

            $safeDom = New-SafeFileName $d
            if (@($users).Count -gt 0) { Save-Csv -InputObject $users -Path (Join-Path $csvPath ("AllUsers_{0}.csv" -f $safeDom)) }
            if (@($computers).Count -gt 0) { Save-Csv -InputObject $computers -Path (Join-Path $csvPath ("AllComputers_{0}.csv" -f $safeDom)) }
            $identitySummary += Get-AdfaIdentitySummary -DomainName $d -Users $users -Computers $computers -StaleDays $script:Config.StaleDays `
                -UsersError $usersError -ComputersError $computersError
        }
        $sectionData['Identity Inventory'] = @($identitySummary)
        # PORT-PLAN C15 (INV-008, INV-010): per scoped domain, thirteen object counts from seven capped,
        # listed-property reads (never the export above), and the group inventory - scope and type,
        # empty groups, direct member counts (member values counted, never kept). One CSV of groups per
        # domain; inventory only.
        Write-Stage 'Object counts and group inventory (capped reads, listed properties, per domain)'
        $identityDepth = Get-AdfaIdentityInventoryDepth -Domains $targetDomains -ForestError $forestError -AdParams $adParams -Config $inventoryConfig
        $sectionData['Object Counts'] = @($identityDepth.Counts)
        $sectionData['Group Inventory'] = @($identityDepth.Groups)
        foreach ($gd in @($identityDepth.GroupExport.Keys)) {
            $groupRows = @($identityDepth.GroupExport[$gd])
            if ($groupRows.Count -gt 0) { Save-Csv -InputObject $groupRows -Path (Join-Path $csvPath ("Groups_{0}.csv" -f (New-SafeFileName $gd))) }
        }
    }

    # ---- DNS record export (PORT-PLAN C13, ADA-INV-014) -> one CSV per zone and server ----
    # Opt-in: NOT part of 'All', because a zone can hold many records. Test-SectionSelected is not
    # used for that reason - it is true for 'All'. The cap per zone is RecordExportCap.
    if ($Sections -contains 'DnsRecordExport') {
        Write-Stage 'DNS record export (every zone of every DC''s DNS server, capped per zone)'
        $dnsExportTargets = @($allDcInventory)
        $dnsExportFailures = @($dcInventoryFailures)
        if (-not $dcInventoryCollected) {
            $dnsExportEnumeration = Get-AdfaDcTargetsByDomain -Domains $targetDomains -AdParams $adParams
            $dnsExportTargets = @($dnsExportEnumeration.Targets)
            $dnsExportFailures = @($dnsExportEnumeration.Failures)
        }
        if ($dnsExportTargets.Count -eq 0) { $dnsExportTargets = @($dcNames) }
        $sectionData['DNS Record Export'] = @(Export-AdfaDnsRecord -DomainControllers $dnsExportTargets -Config $dnsConfig -CsvPath $csvPath `
                -PortTimeoutMs $script:Config.RpcPortTimeoutMs -InventoryFailures $dnsExportFailures -EnumerationError $script:DcEnumerationError -ScopedDomains $targetDomains)
    }

    # ---- Raw diagnostics ----
    if ($IncludeRepadmin -and (Test-CommandAvailable -Name 'repadmin.exe')) {
        Write-Stage 'raw repadmin'
        Invoke-ExternalCommand -FilePath 'repadmin.exe' -Arguments '/replsummary * /bysrc /bydest /sort:delta' -OutFile (Join-Path $rawPath 'repadmin_replsummary.txt') @ext | Out-Null
        foreach ($dc in $perDcHosts) {
            if ((Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135) -TimeoutMs $script:Config.RpcPortTimeoutMs).Open[135]) {
                Invoke-ExternalCommand -FilePath 'repadmin.exe' -Arguments ("/showrepl {0} /errorsonly" -f $dc) -OutFile (Join-Path $rawPath ("repadmin_showrepl_{0}.txt" -f (New-SafeFileName $dc))) @ext | Out-Null
            }
        }
    }
    if ($IncludeDcdiag -and (Test-CommandAvailable -Name 'dcdiag.exe')) {
        Write-Stage 'raw dcdiag'
        foreach ($dc in $perDcHosts) {
            if ((Get-AdfaDcProbeGate -ComputerName $dc -Ports @(135) -TimeoutMs $script:Config.RpcPortTimeoutMs).Open[135]) {
                Invoke-ExternalCommand -FilePath 'dcdiag.exe' -Arguments ("/s:{0} /c /v" -f $dc) -OutFile (Join-Path $rawPath ("dcdiag_{0}.txt" -f (New-SafeFileName $dc))) @ext | Out-Null
            }
        }
    }

    # ---- Persist CSVs ----
    Write-Stage 'Writing CSVs'
    foreach ($key in $sectionData.Keys) {
        $file = Join-Path $csvPath (("{0}.csv" -f (New-SafeFileName $key)))
        Save-Csv -InputObject $sectionData[$key] -Path $file
    }

    # ---- Consolidated findings + detailed itemised log ----
    # One row per status-bearing check across every section: the single actionable list.
    $consolidated = @()
    $unreadableRows = 0
    foreach ($key in $sectionData.Keys) {
        # Expand first: a nested collection here would present as a row with no Status and
        # be skipped, which is how whole sections were once discarded without a word.
        foreach ($row in @(Expand-AdfaRowList -Rows $sectionData[$key])) {
            $names = $row.PSObject.Properties.Name
            $statusCol = if ($names -contains 'Status') { 'Status' } elseif ($names -contains 'Health') { 'Health' } else { $null }
            if (-not $statusCol) {
                # Rows with no status column are informational inventory (sites, subnets,
                # site links) and belong only in their own section - expected, not an error.
                # Anything that is not a plain object, though, means a collector returned a
                # shape this build did not expect: say so rather than dropping it in silence.
                if (($row -is [System.Collections.IEnumerable]) -and ($row -isnot [string])) {
                    $unreadableRows++
                    Write-Log -Level ERROR ("Section '{0}' produced a row of type {1} that carries no status - it is NOT in the consolidated findings. This is a tool defect; report it." -f $key, $row.GetType().Name)
                }
                continue
            }
            $consolidated += ConvertTo-AdfaConsolidatedFinding -Section $key -Row $row -StatusColumn $statusCol
        }
    }
    # Severity order for the consolidated file and the log.
    $sevRank = @{ 'Fail' = 0; 'Broken' = 0; 'Failed' = 0; 'Warning' = 1; 'Degraded' = 1; 'Not Assessed' = 2; 'Info' = 3; 'Pass' = 4; 'Healthy' = 4; 'Verified' = 4 }
    $consolidated = $consolidated | Sort-Object @{ e = { $r = $sevRank[$_.Status]; if ($null -eq $r) { 5 } else { $r } } }, Section, Item
    Save-Csv -InputObject $consolidated -Path (Join-Path $csvPath 'Findings-Consolidated.csv')

    # ---- Section reconciliation ----
    # Collected-vs-reported, per section. A section that produced rows but contributed no
    # finding is either pure inventory (expected) or data loss (a defect). Stating the
    # count for every section makes the second case impossible to miss - the failure mode
    # that discarded twelve sections on the first multi-domain run showed no symptom at all.
    $sectionAudit = @()
    foreach ($key in $sectionData.Keys) {
        $collected = @(Expand-AdfaRowList -Rows $sectionData[$key]).Count
        $reported = @($consolidated | Where-Object { $_.Section -eq $key }).Count
        $sectionAudit += [pscustomobject]@{
            Section = $key; RowsCollected = $collected; FindingsReported = $reported
            Note    = $(if ($collected -gt 0 -and $reported -eq 0) { 'No status-bearing rows (inventory section, or data loss - verify)' } else { '' })
        }
    }
    Save-Csv -InputObject $sectionAudit -Path (Join-Path $csvPath 'Section-Coverage.csv')
    Write-Log -Level RESULT ("Section reconciliation ({0} sections):" -f @($sectionAudit).Count)
    foreach ($a in $sectionAudit) {
        $lvl = if ($a.Note) { 'WARN' } else { 'RESULT' }
        Write-Log -Level $lvl ('{0,-42} collected={1,-6} reported={2}{3}' -f $a.Section, $a.RowsCollected, $a.FindingsReported, $(if ($a.Note) { ' <- ' + $a.Note } else { '' }))
    }
    if ($unreadableRows -gt 0) {
        Write-Log -Level ERROR ("{0} collected row(s) could not be interpreted and are absent from the consolidated findings. Treat this report as INCOMPLETE." -f $unreadableRows)
        Write-Warning ("{0} collected row(s) could not be interpreted - the consolidated findings are INCOMPLETE. See the log." -f $unreadableRows)
    }

    # Detailed itemised log: every section's findings, worst first, with the exact detail text.
    Write-Log -Level RESULT ("Assessment findings ({0} checks across {1} sections):" -f @($consolidated).Count, $sectionData.Keys.Count)
    foreach ($f in $consolidated) {
        $lvl = switch -Regex ($f.Status) {
            '^(Fail|Broken|Failed)$' { 'ERROR'; break }
            '^(Warning|Degraded)$' { 'WARN'; break }
            '^(Not Assessed)$' { 'WARN'; break }
            default { 'RESULT' }
        }
        $msg = '{0,-12} {1} :: {2}{3}{4}' -f $f.Status, $f.Section, $f.Item, $(if ($f.Detail) { " -> $($f.Detail)" } else { '' }), $(if ($f.Recommendation) { " || FIX: $($f.Recommendation)" } else { '' })
        Write-Log -Level $lvl -Section $f.Scope -Message $msg
    }

    # ---- Roll-up badges ----
    $flat = @($consolidated | ForEach-Object { $_.Status })
    $countOk = @($flat | Where-Object { $_ -match '^(Pass|Healthy)$' }).Count
    $countWarn = @($flat | Where-Object { $_ -match '^(Warning|Degraded)$' }).Count
    $countBad = @($flat | Where-Object { $_ -match '^(Fail|Broken)$' }).Count
    $countNa = @($flat | Where-Object { $_ -eq 'Not Assessed' }).Count
    Write-Log -Level RESULT ("Summary: Pass={0} Warning={1} Fail={2} NotAssessed={3}" -f $countOk, $countWarn, $countBad, $countNa)
    $badges = "<span class='b-ok'>Pass $countOk</span><span class='b-warn'>Warning $countWarn</span><span class='b-bad'>Fail $countBad</span><span class='b-na'>Not Assessed $countNa</span>"
    # One summary object, consumed by the JSON document and by this function's return value,
    # so the two can never disagree about the same run.
    $runSummary = [pscustomobject]@{ Pass = $countOk; Warning = $countWarn; Fail = $countBad; NotAssessed = $countNa }

    $meta = [pscustomobject]@{
        Forest        = $forest.Name
        Generated     = (Get-Date).ToString('u')
        RunBy         = ("{0}\{1}" -f $env:USERDOMAIN, $env:USERNAME)
        Version       = $script:Config.Version
        DomainsScoped = @($targetDomains)
        DcCount       = @($perDcHosts).Count
        Badges        = $badges
    }

    Write-Stage 'Writing HTML report'
    $reportPath = Join-Path $runRoot 'Assessment.html'
    # Lead the report with the consolidated, severity-sorted findings, then the detail sections.
    $htmlSections = [ordered]@{}
    $htmlSections['Findings (worst first)'] = @($consolidated | Where-Object { $_.Status -notmatch '^(Pass|Healthy|Verified|Info)$' })
    # Reconciliation sits directly under the findings: what each section collected against
    # what it contributed, so a silently empty section is visible in the report itself.
    $htmlSections['Section Coverage (collected vs reported)'] = $sectionAudit
    foreach ($k in $sectionData.Keys) { $htmlSections[$k] = $sectionData[$k] }
    if (@($htmlSections['Findings (worst first)']).Count -eq 0) {
        $htmlSections['Findings (worst first)'] = @([pscustomobject]@{ Section = '(none)'; Item = 'No warnings or failures'; Status = 'Pass'; Detail = 'All assessed checks passed.'; Recommendation = '' })
    }
    # The CSVs and the itemised log are already on disk at this point. A rendering fault
    # must not discard them, stop the transcript from closing, or suppress the run summary
    # - the collection is the expensive part and on a recovery it may not be repeatable
    # cheaply. Report the failure loudly and carry on.
    $reportRendered = $false
    try {
        New-AdfaHtmlReport -Sections $htmlSections -Meta $meta -Path $reportPath | Out-Null
        $reportRendered = $true
    }
    catch {
        $reportPath = ''
        Write-Log -Level ERROR ("HTML report generation FAILED: {0}" -f $_.Exception.Message)
        Write-Warning ("HTML report could not be written: {0}" -f $_.Exception.Message)
        Write-Warning ("All findings are still on disk: {0}" -f (Join-Path $csvPath 'Findings-Consolidated.csv'))
    }
    if ($reportRendered) { Write-Log -Level INFO ("HTML report: {0}" -f $reportPath) }

    # JSON is the machine-readable twin of the HTML, for diffing one run against the next
    # (a phased rollout re-runs this between phases). Guarded separately from the HTML so
    # neither renderer can take the other down, and so a JSON fault cannot discard the CSVs.
    Write-Stage 'Writing JSON report'
    $jsonPath = Join-Path $runRoot 'Assessment.json'
    try {
        Export-AdfaJsonReport -Meta $meta -Findings $consolidated -Coverage $sectionAudit `
            -Sections $sectionData -Summary $runSummary -Path $jsonPath | Out-Null
        Write-Log -Level INFO ("JSON report: {0}" -f $jsonPath)
    }
    catch {
        $jsonPath = ''
        Write-Log -Level ERROR ("JSON report generation FAILED: {0}" -f $_.Exception.Message)
        Write-Warning ("JSON report could not be written: {0}" -f $_.Exception.Message)
    }

    Write-Log -Level INFO ("Detailed log: {0}" -f $script:LogFile)
    Write-Log -Level INFO ("Consolidated findings: {0}" -f (Join-Path $csvPath 'Findings-Consolidated.csv'))
    try { Stop-Transcript | Out-Null } catch { }

    if ($reportRendered) { Write-Stage ("DONE. Report: {0}" -f $reportPath) }
    else { Write-Stage ("DONE (HTML report failed to render). Findings: {0}" -f (Join-Path $csvPath 'Findings-Consolidated.csv')) }

    [pscustomobject]@{
        Forest        = $forest.Name
        DomainsScoped = $targetDomains
        DcCount       = @($perDcHosts).Count
        OutputRoot    = $runRoot
        ReportPath    = $reportPath
        JsonPath      = $jsonPath
        CsvPath       = $csvPath
        RawPath       = $rawPath
        LogFile       = $script:LogFile
        FindingsFile  = (Join-Path $csvPath 'Findings-Consolidated.csv')
        Transcript    = $transcript
        Summary       = $runSummary
        Sections      = @($sectionData.Keys)
    }
}

# Only auto-run when executed as a script (not when dot-sourced for testing).
if ($MyInvocation.InvocationName -ne '.' -and -not $env:ADFA_NO_AUTORUN) {
    Invoke-Main
}
